#[derive(Debug, Clone)]
pub enum ScenarioDisclosure {
    Complete(CheckedScenarioDisclosure),
    Declined(DisclosureDecline),
}

impl ScenarioDisclosure {
    pub fn source_facts(&self) -> Option<&CheckedScenarioSource> {
        match self {
            Self::Complete(value) => value.source_facts.as_deref(),
            Self::Declined(value) => value.source_facts.as_deref(),
        }
    }
}

/// Invoke only for a clean checked cohort. Missing anchors/facts decline;
/// absence of a table row never proves an empty dependency closure.
pub fn analyze_scenario_disclosure(
    db: &SourceDb,
    trees: &[(SourceId, SyntaxNode)],
    resolve: &ResolveTables,
    types: &TypeTable,
    effects: &EffectTables,
) -> HashMap<SymbolId, ScenarioDisclosure> {
    analyze_scenario_disclosure_with_catalog(db, trees, resolve, types, effects, None)
}

pub(super) fn analyze_scenario_disclosure_with_catalog<'a>(
    db: &'a SourceDb,
    trees: &'a [(SourceId, SyntaxNode)],
    resolve: &'a ResolveTables,
    types: &'a TypeTable,
    effects: &'a EffectTables,
    catalog: Option<&'a Catalog>,
) -> HashMap<SymbolId, ScenarioDisclosure> {
    let mut nodes = HashMap::new();
    let mut pending: Vec<_> = trees.iter().map(|(_, tree)| tree).collect();
    while let Some(node) = pending.pop() {
        nodes.insert(NodeKey::of(node), node);
        pending.extend(node.children.iter());
    }
    let mut cx = Closure::new(db, resolve, types, effects, nodes, catalog);
    let mut out = HashMap::new();
    // Resolve only proven acyclic children. A prior wave can establish a
    // parent, never its own recursive prerequisite; cap the call depth at 16.
    for _ in 0..=16 {
        cx.complete_children = out
            .iter()
            .filter_map(|(id, value)| match value {
                ScenarioDisclosure::Complete(_) => Some(*id),
                ScenarioDisclosure::Declined(_) => None,
            })
            .collect();
        cx.complete_model_children = out
            .iter()
            .filter_map(|(id, value)| {
                let ScenarioDisclosure::Complete(checked) = value else {
                    return None;
                };
                let model = stored_result_model(types.symbol_results.get(id)?.as_ref()?, resolve)?;
                (!checked.returns.is_empty()
                    && checked.returns.iter().all(|returned| {
                        returned
                            .model_result
                            .is_some_and(|origin| origin.model() == model)
                    }))
                .then_some((*id, model))
            })
            .collect();
        let prior_complete = cx.complete_children.len();
        for scenario in effects.scenarios.values() {
            if cx.complete_children.contains(&scenario.scenario) {
                continue;
            }
            cx.steps = 0;
            cx.stack.clear();
            cx.effect_proofs.clear();
            cx.require_consumptions.clear();
            cx.loop_node = None;
            cx.effect_visits = 0;
            cx.result_model = None;
            let result = (|| {
                // C23 hook slice: a handler with an admitted first-query fact
                // may prove its closure below; every other trusted shape
                // keeps this refusal, and the finite-query fast path never
                // applies to handlers.
                if scenario.on.is_some()
                    && cx.hook_first_complete(scenario).is_none()
                    && cx.hook_delivery_event(scenario).is_none()
                {
                    return Err(cx.fail(scenario.node, "trusted handler"));
                }
                if scenario.on.is_none()
                    && let Some(plan) = cx.complete_query(scenario)?
                {
                    return Ok(plan);
                }
                let signature = types
                    .symbol_results
                    .get(&scenario.scenario)
                    .ok_or_else(|| cx.fail(scenario.node, "missing checked result signature"))?;
                cx.result_model = signature
                    .as_ref()
                    .and_then(|ty| stored_result_model(ty, resolve));
                if signature.as_ref().is_some_and(|ty| !result_type(ty))
                    && cx.result_model.is_none()
                {
                    return Err(cx.fail(scenario.node, "unsupported result shape"));
                }
                let source = cx.source(scenario.module, scenario.node)?;
                let mut flows = vec![Flow::default()];
                for param in &scenario.params {
                    let ty = types
                        .symbol_types
                        .get(&param.param)
                        .ok_or_else(|| cx.fail(param.node, "missing parameter type"))?;
                    let mut supplied = ValuePath::default();
                    if let ResolvedType::Record {
                        symbol,
                        stored: true,
                    } = ty
                        && matches!(
                            resolve.symbols.get(symbol.0 as usize).map(|s| &s.kind),
                            Some(SymbolKind::Model { .. })
                        )
                    {
                        supplied.record = Some(*symbol);
                        if !scenario.read && param.default.is_none() {
                            supplied.reference_origin =
                                Some(ReferenceOrigin::Parameter(param.param));
                            let parameter =
                                resolve.symbols.get(param.param.0 as usize).ok_or_else(|| {
                                    cx.fail(param.node, "missing admitted parameter declaration")
                                })?;
                            let model =
                                resolve.symbols.get(symbol.0 as usize).ok_or_else(|| {
                                    cx.fail(param.node, "missing admitted parameter model")
                                })?;
                            supplied.reference =
                                Some(DisclosureIntrinsicKind::AdmittedReferenceVersion {
                                    parameter: param.param,
                                    parameter_name: parameter.name.clone(),
                                    model: *symbol,
                                    model_name: model.canonical.clone(),
                                });
                        }
                    }
                    if let Some(model) = cx.nullable_model_input(scenario, param) {
                        supplied.record = Some(model);
                        supplied.reference_origin =
                            Some(ReferenceOrigin::NullableParameter(param.param));
                    }
                    if let ResolvedType::Scalar(scalar) = ty
                        && primitive_type(ty)
                        && param.default.is_none()
                        && cx.direct_builtin_parameter_type(param.type_node, *scalar)
                        && !types
                            .value_constraints
                            .get(&param.param)
                            .is_some_and(|value| value.alias.is_some())
                    {
                        let parameter =
                            resolve.symbols.get(param.param.0 as usize).ok_or_else(|| {
                                cx.fail(param.node, "missing admitted primitive parameter")
                            })?;
                        supplied.input = Some((param.param, parameter.name.clone(), *scalar));
                    }
                    let mut next = Vec::new();
                    for flow in flows {
                        // Only prior declaration bindings exist while this default
                        // executes. An explicit input is already admitted and frozen.
                        let alternatives = match param.default {
                            Some(default) if !cx.admitted_actor_default(default, ty) => {
                                Some((default, cx.expr(default, scenario.module, &flow.env, &[])?))
                            }
                            _ => None,
                        };
                        if let Some((default, alternatives)) = alternatives
                            && alternatives.iter().any(|value| {
                                !value.reads.is_empty()
                                    || !value.intrinsics.is_empty()
                                    || !value.decisions.is_empty()
                            })
                        {
                            let provided = DisclosureDecision {
                                node: default,
                                calls: Vec::new(),
                                choice: DisclosureChoice::DefaultProvided,
                            };
                            let mut provided_flow = flow.clone();
                            let mut frozen = supplied.clone();
                            frozen.decisions.push(provided.clone());
                            provided_flow.env.insert(Local::Symbol(param.param), frozen);
                            provided_flow.evaluated.push(provided);
                            next.push(provided_flow);
                            for mut value in alternatives {
                                if !compatible(&flow.evaluated, &value.decisions) {
                                    continue;
                                }
                                let decision = DisclosureDecision {
                                    node: default,
                                    calls: Vec::new(),
                                    choice: DisclosureChoice::DefaultEvaluated,
                                };
                                let mut evaluated = flow.clone();
                                evaluated.evaluated.push(decision.clone());
                                evaluated.observe_value(&value);
                                value.decisions.push(decision);
                                evaluated.env.insert(Local::Symbol(param.param), value);
                                next.push(evaluated);
                                if next.len() > 1024 {
                                    return Err(
                                        cx.fail(default, "parameter default evaluation path bound")
                                    );
                                }
                            }
                        } else {
                            let mut path = flow;
                            path.env
                                .insert(Local::Symbol(param.param), supplied.clone());
                            next.push(path);
                        }
                        if next.len() > 1024 {
                            return Err(
                                cx.fail(param.node, "parameter default evaluation path bound")
                            );
                        }
                    }
                    if next.iter().any(|flow| flow.env.len() > 256) {
                        return Err(cx.fail(param.node, "binding closure bound"));
                    }
                    flows = next;
                }
                if let Some(by) = scenario.by {
                    for flow in &flows {
                        cx.authorization_expr(by, scenario.module, &flow.env, &[])?;
                    }
                }
                let (guards, _) = cx.statements(&scenario.guards, scenario.module, flows, &[])?;
                let (continuing, mut returns) =
                    cx.statements(&scenario.effects, scenario.module, guards, &[])?;
                if !continuing.is_empty() {
                    if signature.is_some() {
                        return Err(cx.fail(scenario.node, "unaccounted result fallthrough"));
                    }
                    for path in continuing {
                        returns.push(cx.return_path(
                            scenario.node,
                            scenario.module,
                            path,
                            ValuePath::default(),
                        )?);
                    }
                }
                if returns.is_empty() {
                    return Err(cx.fail(scenario.node, "no established return path"));
                }
                // Finite first-query slice D (CAN18-v1): allow exactly one
                // whole-row replay (`return <first-let>`, proven narrow at
                // its return arm) alongside a same-model create. All other
                // provenance gaps (including bare direct returns) stay refused.
                let replay_sites = returns
                    .iter()
                    .filter(|returned| returned.model_result.is_none())
                    .map(|returned| returned.node)
                    .collect::<HashSet<_>>();
                let model_sites = returns
                    .iter()
                    .filter(|returned| returned.model_result.is_some())
                    .map(|returned| returned.node)
                    .collect::<HashSet<_>>();
                let paired_replay_sites = replay_sites.len() == 1
                    && model_sites.len() == 1
                    && replay_sites.is_disjoint(&model_sites);
                if let Some(model) = cx.result_model
                    && returns.iter().any(|returned| match returned.model_result
                    {
                        Some(origin) => origin.model() != model,
                        None => !paired_replay_sites,
                    })
                {
                    return Err(cx.fail(
                        scenario.node,
                        "result requires its newly-created model provenance",
                    ));
                }
                for path in &mut returns {
                    path.id = cx.opaque(
                        "return",
                        scenario.node,
                        &cx.decision_stamp(&path.decisions)?,
                    )?;
                    // Include the return anchor: two explicit returns under the
                    // same decisions must never collide.
                    path.id = sha256_hex(
                        format!("{}:{}:{}", path.id, path.node.start, path.node.end).as_bytes(),
                    );
                }
                Ok(CheckedScenarioDisclosure {
                    source_facts: None,
                    scenario: scenario.scenario,
                    node: scenario.node,
                    source,
                    returns,
                    effects: cx.effect_proofs.clone(),
                    require_consumptions: cx.require_consumptions.clone(),
                })
            })();
            out.insert(
                scenario.scenario,
                match result {
                    Ok(plan) => ScenarioDisclosure::Complete(plan),
                    Err(reason) => ScenarioDisclosure::Declined(reason),
                },
            );
        }
        if out
            .values()
            .filter(|value| matches!(value, ScenarioDisclosure::Complete(_)))
            .count()
            == prior_complete
        {
            break;
        }
    }
    // Source facts are collected once, independently of closure waves and
    // runtime admission. Declined read/composite/bound-call plans retain them.
    for scenario in effects.scenarios.values() {
        let mut facts = cx.checked_source_facts(scenario).map(Box::new);
        // DESIGN442 guard/presence-consumed marks: the confined
        // single-`Let(first)` plus single-`Require` hook slice
        // (hook_first_event) consumes its first-query occurrence only as a
        // decision. Mark the skeleton's own `Let` occurrence exactly when
        // the admitted first query exists (checked_first_query_source) and
        // the `Require` consumes either a stored read derived from it
        // (first_query_stored_require_read, already the
        // execution-dependency filter) or its bare presence
        // (`require budget != null`, no stored-field read). Anything else —
        // unused bindings, `require true`, unconfined shapes — keeps
        // ordinary viewer behavior.
        if let (Some(facts), Some(ScenarioDisclosure::Complete(checked))) =
            (facts.as_mut(), out.get(&scenario.scenario))
        {
            if cx.hook_first_event(scenario).is_some() {
                // The skeleton above already proved the 2-effect shape; the
                // re-match only recovers the nodes without re-proving it.
                if let [binding, guard] = scenario.effects.as_slice() {
                    let stored = checked
                        .require_consumptions
                        .iter()
                        .flat_map(|consumption| consumption.dependencies.iter())
                        .any(|dependency| {
                            cx.first_query_stored_require_read(dependency, scenario.module)
                        });
                    let presence = guard
                        .cond
                        .is_some_and(|cond| cx.first_binding_presence_consumed(binding, cond));
                    if stored || presence {
                        for query in facts
                            .queries
                            .iter_mut()
                            .flatten()
                            .filter(|query| query.first.is_some())
                        {
                            if let Some(first) = query.first.as_mut() {
                                if first.binding != binding.node {
                                    continue;
                                }
                                if stored {
                                    first.guard_consumed = true;
                                } else {
                                    first.presence_consumed = true;
                                }
                            }
                        }
                    }
                }
            }
            // Ordinary-scenario guard slice (CAN18-v1 first-query absence
            // conjunctions): the confined let-first + require-conjunction +
            // create + scalar-return skeleton consumes the first binding
            // plus stored control reads as its Require decision. Mark
            // guard-consumed only when a stored read is present; bare
            // presence stays unmarked under the pure-control profile.
            // Anything else keeps ordinary viewer behavior.
            if let Some((binding, guard)) = cx.ordinary_first_decision(scenario) {
                let stored = checked
                    .require_consumptions
                    .iter()
                    .flat_map(|consumption| consumption.dependencies.iter())
                    .any(|dependency| {
                        cx.first_query_stored_require_read(dependency, scenario.module)
                    });
                let presence = guard
                    .cond
                    .is_some_and(|cond| cx.first_binding_presence_consumed(binding, cond));
                if stored && presence {
                    for query in facts
                        .queries
                        .iter_mut()
                        .flatten()
                        .filter(|query| query.first.is_some())
                    {
                        if let Some(first) = query.first.as_mut() {
                            if first.binding != binding.node {
                                continue;
                            }
                            first.guard_consumed = true;
                        }
                    }
                }
            }
            // A leading checked ANY followed by a decision-only first has a
            // second, separately authored owner decision. Admit only the
            // confined let/nonnull-require/create tail; the selected binding
            // must not flow into the create's values or a caller result.
            if scenario.on.is_none() && !scenario.read && scenario.by.is_some()
                && scenario.result.is_none() && scenario.cohort.is_none()
                && scenario.guards.len() == 1
                && let [binding, guard, create] = scenario.effects.as_slice()
                && binding.verb == EffectVerb::Let
                && guard.verb == EffectVerb::Require
                && create.verb == EffectVerb::Create
                && cx.checked_first_query_source(scenario, binding).is_some()
                && let Some(cond) = guard.cond
                && cx.first_binding_nonnull_only(binding, cond)
                && !cx.first_binding_used_in_node(binding, create.node)
                && cx.checked_decision_sites(scenario).is_some_and(|sites| sites.iter().any(|site|
                    site.stage == CheckedDecisionStage::LeadingRequire
                        && site.calls.iter().any(|call| matches!(&call.target,
                            CheckedDecisionCallTarget::Builtin { id, .. } if id == "any"))))
            {
                for query in facts.queries.iter_mut().flatten().filter(|query| query.first.is_some()) {
                    if let Some(first) = query.first.as_mut() && first.binding == binding.node {
                        first.presence_consumed = true;
                    }
                }
            }
            if let Some(binding) = cx.first_null_branch_decision(scenario) {
                let single_query = facts.queries.as_ref().is_some_and(|queries|
                    queries.len() == 1 && queries[0].first.is_some());
                let paired_query = facts.queries.as_ref().is_some_and(|queries|
                    cx.first_target_companion_any(scenario, binding, queries));
                let paired_assign = facts.queries.as_ref().is_some_and(|queries|
                    cx.first_target_companion_assign_count(scenario, binding, queries));
                let target_only = (single_query || paired_query || paired_assign) &&
                    cx.first_null_branch_target_only(scenario).is_some();
                let assign_guard = paired_assign && target_only &&
                    cx.first_null_branch_assign_guard(scenario, binding).is_some_and(|guard|
                        checked.require_consumptions.iter().any(|consumption|
                            consumption.statement == guard.node && consumption.condition == guard.cond.unwrap()
                            && consumption.dependencies.len() == 1
                            && consumption.dependencies[0].model_name == "member_terms.Seat"
                            && consumption.dependencies[0].field_name == "active"
                            && consumption.dependencies[0].role == DependencyRole::Control));
                for query in facts.queries.iter_mut().flatten().filter(|query| query.first.is_some()) {
                    if let Some(first) = query.first.as_mut() && first.binding == binding.node {
                        first.target_decision_shape = true;
                        first.target_consumed = target_only;
                        if assign_guard { first.guard_consumed = true; }
                    }
                }
            }
        }
        match out.get_mut(&scenario.scenario) {
            Some(ScenarioDisclosure::Complete(value)) => value.source_facts = facts,
            Some(ScenarioDisclosure::Declined(value)) => value.source_facts = facts,
            None => {}
        }
    }
    out
}

/// Collect original read/where expressions from a clean checked source cohort.
/// The ordinal belongs to the owning model's authored policy order. These
/// bounded facts identify selected calls and grant no runtime authority.
/// The selected helper closure: every derive body the checked decision walk
/// may descend into from a sealed read. Derive bodies are small one-step
/// helpers; the Given/When bulk around them stays unindexed.
fn helper_closure_keys(effects: &EffectTables) -> HashSet<NodeKey> {
    let mut required = HashSet::new();
    for data in effects.derives.values() {
        required.extend(data.expr);
        for param in &data.params {
            required.extend(param.default);
        }
    }
    required
}

/// Exact-consumed CST scope for one seal read: the required anchors plus the
/// selected helper closure. Unrelated bulk never spends the finite node
/// budget (same 200k entries/depth 256 bounds); a missing anchor refuses
/// exactly like the previous whole-tree map did.
fn pruned_closure_nodes<'t>(
    trees: &'t [(SourceId, SyntaxNode)],
    anchors: &HashSet<NodeKey>,
    effects: &EffectTables,
) -> Option<HashMap<NodeKey, &'t SyntaxNode>> {
    let mut required = anchors.clone();
    required.extend(helper_closure_keys(effects));
    let contains = |node: &SyntaxNode, key: &NodeKey| {
        node.span.file == key.file && node.span.start <= key.start && node.span.end >= key.end
    };
    fn index_subtree<'t>(
        node: &'t SyntaxNode,
        depth: usize,
        nodes: &mut HashMap<NodeKey, &'t SyntaxNode>,
    ) -> Option<()> {
        let mut pending = vec![(node, depth)];
        while let Some((node, depth)) = pending.pop() {
            if nodes.len() >= 200000 || depth > 256 {
                return None;
            }
            nodes.insert(NodeKey::of(node), node);
            pending.extend(node.children.iter().map(|child| (child, depth + 1)));
        }
        Some(())
    }
    let mut nodes = HashMap::new();
    for (_, tree) in trees {
        if !required.iter().any(|key| contains(tree, key)) {
            continue;
        }
        let mut pending = vec![(tree, 0usize)];
        while let Some((node, depth)) = pending.pop() {
            if nodes.len() >= 200000 || depth > 256 {
                return None;
            }
            if required.contains(&NodeKey::of(node)) {
                index_subtree(node, depth, &mut nodes)?;
                continue;
            }
            pending.extend(
                node.children
                    .iter()
                    .filter(|child| required.iter().any(|key| contains(child, key)))
                    .map(|child| (child, depth + 1)),
            );
        }
    }
    Some(nodes)
}

pub fn checked_read_decision_sites(
    db: &SourceDb,
    trees: &[(SourceId, SyntaxNode)],
    resolve: &ResolveTables,
    types: &TypeTable,
    effects: &EffectTables,
    model: SymbolId,
    ordinal: usize,
) -> Option<Vec<CheckedDecisionSite>> {
    let declaration = resolve.symbols.get(model.0 as usize)?;
    let data = effects.models.get(&model)?;
    let policy = data.policies.get(ordinal)?;
    if declaration.id != model
        || data.model != model
        || !matches!(declaration.kind, SymbolKind::Model { .. })
        || declaration.module != data.module
        || policy.module != data.module
    {
        return None;
    }
    // Only this policy plus the selected helper closure spend the finite
    // node budget. Unrelated bulk remains in the checked cohort unindexed.
    let mut anchors = HashSet::from([policy.node]);
    anchors.extend(policy.read);
    anchors.extend(policy.where_predicate);
    let nodes = pruned_closure_nodes(trees, &anchors, effects)?;
    let node = nodes.get(&policy.node)?;
    let text = &db.get(policy.node.file)?.text;
    if node.kind != SyntaxKind::Policy
        || super::attribute_value(node, "read", text).map(NodeKey::of) != policy.read
        || super::attribute_value(node, "where", text).map(NodeKey::of) != policy.where_predicate
    {
        return None;
    }
    let cx = Closure::new(db, resolve, types, effects, nodes, None);
    let mut sites = Vec::new();
    let mut steps = 0;
    let mut call_count = 0;
    for key in std::iter::once(policy.read?).chain(policy.where_predicate) {
        if key.file != policy.node.file
            || key.start < policy.node.start
            || key.end > policy.node.end
            || key.start >= key.end
            || types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        let mut calls = Vec::new();
        cx.checked_decision_expression(
            key,
            policy.module,
            &[],
            &mut HashSet::new(),
            &mut calls,
            &mut steps,
            &mut call_count,
            0,
        )?;
        sites.push(CheckedDecisionSite {
            owner: model,
            source: cx.source(policy.module, key).ok()?,
            node: key,
            statement: policy.node,
            stage: CheckedDecisionStage::ReadPolicy,
            position: Vec::new(),
            calls,
        });
    }
    Some(sites)
}

/// Original named-page model-query predicate, separate from policy grants.
/// Transitive call facts retain their actual selected expression provenance.
#[allow(clippy::too_many_arguments)]
pub fn checked_read_predicate_site(
    db: &SourceDb,
    trees: &[(SourceId, SyntaxNode)],
    resolve: &ResolveTables,
    types: &TypeTable,
    effects: &EffectTables,
    module: ModuleId,
    page: NodeKey,
    query: NodeKey,
) -> Option<CheckedDecisionSite> {
    let (owner, predicate, clause) =
        read_predicate_query(types, resolve, effects, module, page, query)?;
    // Only this page, query and predicate plus the selected helper closure
    // spend the finite node budget. Unrelated bulk remains unindexed.
    let anchors = HashSet::from([page, query, predicate]);
    let nodes = pruned_closure_nodes(trees, &anchors, effects)?;
    if nodes.get(&page)?.kind != SyntaxKind::Page
        || nodes.get(&query)?.kind != SyntaxKind::Query
        || nodes.get(&clause)?.kind != SyntaxKind::QueryClause
        || predicate.file != query.file
        || predicate.start < query.start
        || predicate.end > query.end
    {
        return None;
    }
    let cx = Closure::new(db, resolve, types, effects, nodes, None);
    let mut calls = Vec::new();
    let mut steps = 0;
    let mut count = 0;
    cx.checked_decision_expression(
        predicate,
        module,
        &[],
        &mut HashSet::new(),
        &mut calls,
        &mut steps,
        &mut count,
        0,
    )?;
    Some(CheckedDecisionSite {
        owner,
        source: cx.source(module, predicate).ok()?,
        node: predicate,
        statement: query,
        stage: CheckedDecisionStage::ReadPredicate,
        position: Vec::new(),
        calls,
    })
}

/// Validate a read-predicate query: a stored-model collection domain on
/// this page with exactly one boolean `where` predicate. Returns the
/// owner, the predicate and its clause.
fn read_predicate_query(
    types: &TypeTable,
    resolve: &ResolveTables,
    effects: &EffectTables,
    module: ModuleId,
    page: NodeKey,
    query: NodeKey,
) -> Option<(SymbolId, NodeKey, NodeKey)> {
    let checked = types.checked_queries.get(&query)?;
    let ResolvedType::Array { element, .. } = &checked.domain_type else {
        return None;
    };
    let ResolvedType::Record {
        symbol: owner,
        stored: true,
    } = element.as_ref()
    else {
        return None;
    };
    let owner = *owner;
    if !matches!(
        resolve.symbols.get(owner.0 as usize)?.kind,
        SymbolKind::Model { .. }
    ) || !effects
        .modules
        .get(&module)?
        .pages
        .iter()
        .any(|candidate| candidate.node == page)
        || query.file != page.file
        || query.start < page.start
        || query.end > page.end
    {
        return None;
    }
    let mut clauses = checked
        .clauses
        .iter()
        .filter(|clause| matches!(clause.kind, CheckedQueryClauseKind::Where));
    let clause = clauses.next()?;
    let [predicate] = clause.expressions.as_slice() else {
        return None;
    };
    if clauses.next().is_some()
        || types.node_types.get(predicate) != Some(&ResolvedType::Scalar(Scalar::Bool))
    {
        return None;
    }
    Some((owner, *predicate, clause.node))
}

/// Complete original callable census for a checked Boolean page requirement or
/// derived field. The codegen consumer independently authenticates its owner.
#[allow(clippy::too_many_arguments)]
pub fn checked_read_boolean_site(
    db: &SourceDb,
    trees: &[(SourceId, SyntaxNode)],
    resolve: &ResolveTables,
    types: &TypeTable,
    effects: &EffectTables,
    module: ModuleId,
    owner: SymbolId,
    predicate: NodeKey,
    statement: NodeKey,
) -> Option<CheckedDecisionSite> {
    // A Boolean result never defines permission to read (DESIGN §3): the
    // caller admits every valid derived/page consumer shape, including
    // non-Boolean derived fields reusing this same observer join. The
    // predicate type still travels in each serialized call argument.
    let collected = collect_read_calls(db, trees, resolve, types, effects, module, predicate)?;
    Some(CheckedDecisionSite {
        owner,
        source: collected.source,
        node: predicate,
        statement,
        stage: CheckedDecisionStage::ReadPredicate,
        position: Vec::new(),
        calls: collected.calls,
    })
}

/// Owning call set behind a checked read observer: the verified source origin
/// plus every checked decision call under the predicate, in source order.
#[derive(Debug, Clone, PartialEq)]
pub struct CollectedReadCalls {
    pub source: DisclosureSource,
    pub calls: Vec<CheckedDecisionCall>,
}

/// Model- or page-scoped callers wrap this with their own owner/stage; a
/// page without a record owner serializes the same set without inventing one.
#[allow(clippy::too_many_arguments)]
pub fn collect_read_calls(
    db: &SourceDb,
    trees: &[(SourceId, SyntaxNode)],
    resolve: &ResolveTables,
    types: &TypeTable,
    effects: &EffectTables,
    module: ModuleId,
    predicate: NodeKey,
) -> Option<CollectedReadCalls> {
    // Only this predicate plus the selected helper closure spend the finite
    // node budget. Unrelated bulk remains in the checked cohort unindexed.
    let nodes = pruned_closure_nodes(trees, &HashSet::from([predicate]), effects)?;
    let cx = Closure::new(db, resolve, types, effects, nodes, None);
    let mut calls = Vec::new();
    cx.checked_decision_expression(
        predicate,
        module,
        &[],
        &mut HashSet::new(),
        &mut calls,
        &mut 0,
        &mut 0,
        0,
    )?;
    Some(CollectedReadCalls {
        source: cx.source(module, predicate).ok()?,
        calls,
    })
}

/// Finite membership dependency through the selected derive calls, including
/// calls in argument defaults. This grants no execution authority.
pub fn expression_reads_membership(
    types: &TypeTable,
    effects: &EffectTables,
    root: NodeKey,
) -> bool {
    let mut pending = vec![root];
    let mut seen = HashSet::new();
    while let Some(key) = pending.pop() {
        if !seen.insert(key) {
            continue;
        }
        if seen.len() > 4096 {
            return false;
        }
        for (node, selected) in &types.selected_calls {
            if node.file != key.file || node.start < key.start || node.end > key.end {
                continue;
            }
            match &selected.target {
                SelectedCallTarget::Builtin { id, .. } if id == "active_member" => return true,
                SelectedCallTarget::DeriveFn(id) => {
                    if let Some(data) = effects.derives.get(id) {
                        pending.extend(data.expr);
                        for (param, slot) in data.params.iter().zip(&selected.slots) {
                            if slot.is_none() {
                                pending.extend(param.default);
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }
    false
}

/// Assignment correspondence used by the bounded create source proof. Unknown
/// values never qualify; concrete arrays may carry a stronger nonempty fact.
fn created_input_type_matches(
    actual: &ResolvedType,
    expected: &ResolvedType,
    depth: usize,
) -> bool {
    if depth > 64 || !actual.is_resolved_shape() || !expected.is_resolved_shape() {
        return false;
    }
    match (actual, expected) {
        (ResolvedType::Null, ResolvedType::Nullable(_)) => true,
        (ResolvedType::Nullable(actual), ResolvedType::Nullable(expected)) => {
            created_input_type_matches(actual, expected, depth + 1)
        }
        (_, ResolvedType::Nullable(expected)) => {
            created_input_type_matches(actual, expected, depth + 1)
        }
        (
            ResolvedType::Array {
                element: actual,
                ordered: actual_order,
                nonempty: actual_nonempty,
            },
            ResolvedType::Array {
                element: expected,
                ordered: expected_order,
                nonempty,
            },
        ) => {
            actual_order == expected_order
                && (!nonempty || *actual_nonempty)
                && created_input_type_matches(actual, expected, depth + 1)
        }
        (ResolvedType::StdNominal { .. }, ResolvedType::StdNominal { .. }) => {
            checked_standard_nominal_name(actual).is_some()
                && checked_standard_nominal_name(actual) == checked_standard_nominal_name(expected)
                && actual == expected
        }
        _ => actual == expected,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Local {
    Symbol(SymbolId),
    Let(NodeKey),
    For(NodeKey),
    Send(NodeKey),
    Call(NodeKey),
    Create(NodeKey),
}
type Env = HashMap<Local, ValuePath>;

/// Canonical stored Contract values retain their whole owning-field read.
/// These are local wire values, never stored record receivers or grants.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContractValue {
    Singular(SymbolId),
    Array(SymbolId),
    Reference,
}

#[derive(Debug, Clone)]
struct ContractPredicateAlias {
    node: NodeKey,
    contract: SymbolId,
    ty: ResolvedType,
    projection: Option<DisclosureQueryProjection>,
}

#[derive(Debug, Clone, Default, PartialEq)]
struct ValuePath {
    reads: Vec<DisclosureDependency>,
    intrinsics: Vec<DisclosureIntrinsic>,
    observed: Vec<(NodeKey, Vec<NodeKey>)>,
    decisions: Vec<DisclosureDecision>,
    influences: Vec<DisclosureInfluence>,
    /// Original first call and Let; never a copied/foreign record receiver.
    first_query: Option<(NodeKey, NodeKey)>,
    /// Only the original guarded current Let can own this stored Revision.
    current_revision: Option<NodeKey>,
    record: Option<SymbolId>,
    model_result: Option<DisclosureModelResult>,
    reference: Option<DisclosureIntrinsicKind>,
    input: Option<(SymbolId, String, Scalar)>,
    members: Option<Vec<(String, ValuePath)>>,
    schema: Option<String>,
    delivery: Option<ResolvedType>,
    /// Exact Complete query child whose actual call occurrence owns this wire.
    /// This marker admits only direct cardinality consumption, never a row view.
    query_child: Option<SymbolId>,
    /// Only exact transcript-origin TextMessage concat/count consumers use these.
    transcript_messages: Option<NodeKey>,
    transcript_count: bool,
    contract_value: Option<ContractValue>,
    /// Original input and at most two checked implicit containment edges.
    reference_origin: Option<ReferenceOrigin>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReferenceOrigin {
    Parameter(SymbolId),
    /// Original `event.term` in the exact declared notice handler.
    EventRow { field: SymbolId, node: NodeKey },
    /// Required Model slot reached through the original Contract parameter.
    ParameterMember {
        parameter: SymbolId,
        node: NodeKey,
    },
    /// Canonical optional input slot; no row/version intrinsic or field promotion.
    NullableParameter(SymbolId),
    Parent {
        parameter: SymbolId,
        model: SymbolId,
        depth: u8,
    },
    Field {
        parameter: SymbolId,
        model: SymbolId,
        field: SymbolId,
    },
}

/// Original successful Template.current guard and its one lexical Revision.
/// This is source lineage, never a nullable row facade or runtime admission.
#[derive(Debug, Clone)]
struct CurrentRevisionSource {
    parameter: SymbolId,
    template: SymbolId,
    field: SymbolId,
    revision: SymbolId,
    active: Option<(NodeKey, SymbolId)>,
    presence: NodeKey,
    presence_read: NodeKey,
    published: NodeKey,
    published_read: NodeKey,
    binding: NodeKey,
    value: NodeKey,
    digest_presence: NodeKey,
    digest_read: NodeKey,
}

impl ValuePath {
    fn join(&mut self, other: &Self) {
        for influence in &other.influences {
            if !self.influences.iter().any(|prior| prior.id == influence.id) {
                self.influences.push(influence.clone());
            }
        }
        for read in &other.observed {
            if !self.observed.contains(read) {
                self.observed.push(read.clone());
            }
        }
        for read in &other.reads {
            if !self.reads.iter().any(|r| r.id == read.id) {
                self.reads.push(read.clone());
            }
        }
        for intrinsic in &other.intrinsics {
            if !self.intrinsics.iter().any(|prior| prior.id == intrinsic.id) {
                self.intrinsics.push(intrinsic.clone());
            }
        }
        for decision in &other.decisions {
            if !self.decisions.contains(decision) {
                self.decisions.push(decision.clone());
            }
        }
    }
}

#[derive(Debug, Clone, Default)]
struct Flow {
    env: Env,
    controls: ValuePath,
    /// Dependencies of writes already executed on this path survive a common
    /// postdominator even when its scalar return no longer depends on a branch.
    writes: ValuePath,
    effect_guards: ValuePath,
    executed_effect: bool,
    repeated_observations: usize,
    evaluated: Vec<DisclosureDecision>,
    observed: Vec<(NodeKey, Vec<NodeKey>)>,
}

impl Flow {
    fn observe_value(&mut self, value: &ValuePath) {
        for read in &value.observed {
            if !self.observed.contains(read) {
                self.observed.push(read.clone());
            }
        }
        for decision in &value.decisions {
            if !self.evaluated.contains(decision) {
                self.evaluated.push(decision.clone());
            }
        }
    }
}

/// Reuse completed compiler analysis, never an evaluated application value.
/// Every lexical value and its ordered provenance participate in equality.
struct CompletedStatementExpression {
    node: NodeKey,
    module: ModuleId,
    calls: Vec<NodeKey>,
    authorization: bool,
    result_model: Option<SymbolId>,
    env: Env,
    values: Vec<ValuePath>,
}

/// Completed source checks against this Closure's immutable analysis tables.
/// No lexical environment, traversal state, or recursive prerequisite is cached.
#[derive(Default)]
struct ImmutableSourceFacts {
    models: HashMap<(SymbolId, ModuleId), Option<Rc<CheckedScenarioCreatedModel>>>,
    revisions: HashMap<(SymbolId, ModuleId, NodeKey), Option<CurrentRevisionSource>>,
    revision_owners: HashMap<(NodeKey, ModuleId), Option<CurrentRevisionSource>>,
    reference_identity_operands: Option<HashSet<NodeKey>>,
}

struct Closure<'a> {
    complete_children: HashSet<SymbolId>,
    complete_model_children: HashMap<SymbolId, SymbolId>,
    result_model: Option<SymbolId>,
    catalog: Option<&'a Catalog>,
    db: &'a SourceDb,
    resolve: &'a ResolveTables,
    types: &'a TypeTable,
    effects: &'a EffectTables,
    nodes: HashMap<NodeKey, &'a SyntaxNode>,
    stack: HashSet<SymbolId>,
    steps: usize,
    depth: usize,
    statement_depth: usize,
    authorization: bool,
    effect_proofs: Vec<DisclosureEffect>,
    require_consumptions: Vec<CheckedRequireConsumption>,
    effect_visits: usize,
    loop_node: Option<NodeKey>,
    statement_expressions: Option<Vec<CompletedStatementExpression>>,
    source_facts: RefCell<ImmutableSourceFacts>,
}

/// Existing required-reference source profiles; neither variant grants
/// traversal beyond its independently checked original field occurrence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScalarReferenceKind {
    Profile,
    Run,
}

/// A value observed while proving a derived body: plain data attached
/// to an admitted row, or a row of the owning parent lineage.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BodyValue {
    Scalar,
    Row(SymbolId),
}

impl<'a> Closure<'a> {
    fn new(
        db: &'a SourceDb,
        resolve: &'a ResolveTables,
        types: &'a TypeTable,
        effects: &'a EffectTables,
        nodes: HashMap<NodeKey, &'a SyntaxNode>,
        catalog: Option<&'a Catalog>,
    ) -> Self {
        Self {
            catalog,
            db,
            resolve,
            types,
            effects,
            nodes,
            stack: HashSet::new(),
            steps: 0,
            depth: 0,
            statement_depth: 0,
            authorization: false,
            effect_proofs: Vec::new(),
            require_consumptions: Vec::new(),
            effect_visits: 0,
            loop_node: None,
            complete_children: HashSet::new(),
            complete_model_children: HashMap::new(),
            result_model: None,
            statement_expressions: None,
            source_facts: RefCell::new(ImmutableSourceFacts::default()),
        }
    }

    fn authorization_expr(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        let prior = self.authorization;
        self.authorization = true;
        let result = self.expr(key, module, env, calls);
        self.authorization = prior;
        result
    }

    /// The original nullable Model slot may be empty, with an implicit null
    /// or an authored literal-null default. Only original checked non-null
    /// occurrences gain navigation; runtime still admits each supplied ref.
    fn nullable_model_input(
        &self,
        scenario: &super::effects::ScenarioData,
        parameter: &super::effects::ParamData,
    ) -> Option<SymbolId> {
        let symbol = self.resolve.symbols.get(parameter.param.0 as usize)?;
        let SymbolKind::Param {
            owner,
            index,
            type_node,
        } = symbol.kind
        else {
            return None;
        };
        let ResolvedType::Nullable(inner) = self.types.symbol_types.get(&parameter.param)? else {
            return None;
        };
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = inner.as_ref()
        else {
            return None;
        };
        let valid_default=parameter.default.is_none_or(|default|self.nodes.get(&default).is_some_and(|node|
            default.file==scenario.node.file && node.kind==SyntaxKind::Literal
                &&self.word(node)==Some("null")
                &&self.types.node_types.get(&default)==Some(&ResolvedType::Null)));
        if owner != scenario.scenario
            || symbol.module != scenario.module
            || scenario.params.get(index)?.param != parameter.param
            || type_node != parameter.type_node
            || scenario.read
            || scenario.on.is_some()
            || !valid_default
            || !matches!(
                self.resolve.symbols.get(model.0 as usize)?.kind,
                SymbolKind::Model { .. }
            )
        {
            return None;
        }
        Some(*model)
    }

    fn admitted_actor_default(&self, key: NodeKey, declared: &ResolvedType) -> bool {
        let user = |ty: &ResolvedType| match ty {
            ResolvedType::Scalar(Scalar::User) => true,
            ResolvedType::Nullable(inner) => {
                matches!(inner.as_ref(), ResolvedType::Scalar(Scalar::User))
            }
            _ => false,
        };
        if !user(declared) || !self.types.node_types.get(&key).is_some_and(user) {
            return false;
        }
        let mut key = key;
        for _ in 0..64 {
            let Some(node) = self.nodes.get(&key) else {
                return false;
            };
            if node.kind != SyntaxKind::Group {
                return node.kind == SyntaxKind::NameRef
                    && self.types.node_types.get(&key).is_some_and(user)
                    && matches!(
                        self.resolve.node_binding.get(&key),
                        Some(Binding::Context(ContextVar::Actor(_)))
                    );
            }
            let mut children = node.children.iter().filter(|child| expression(child.kind));
            let Some(child) = children.next() else {
                return false;
            };
            if children.next().is_some() {
                return false;
            }
            key = NodeKey::of(child);
        }
        false
    }

    /// Canonical Model references are operands only, never ordinary
    /// disclosure return types or general stored-field traversal values.
    /// Singular nullable references keep their `?` suffix, matching the
    /// stored-contract type identity the worker validates null against.
    fn reference_operand_type_id(&self, ty: &ResolvedType) -> Option<String> {
        let (base, array, nullable) = match ty {
            ResolvedType::Array {
                element,
                ordered: true,
                nonempty: false,
            } => (element.as_ref(), true, false),
            ResolvedType::Nullable(inner) => (inner.as_ref(), false, true),
            ty => (ty, false, false),
        };
        let ResolvedType::Record {
            symbol,
            stored: true,
        } = base
        else {
            return None;
        };
        let declaration = self.resolve.symbols.get(symbol.0 as usize)?;
        if !matches!(declaration.kind, SymbolKind::Model { .. }) {
            return None;
        }
        Some(format!(
            "{}{}{}",
            declaration.canonical,
            if array { "[]" } else { "" },
            if nullable { "?" } else { "" }
        ))
    }

    /// An original required reference-field argument is consumed by its actual
    /// derive formal. Its receiver may retain the existing two parent edges;
    /// this grants no permission to copy or otherwise traverse that reference.
    fn checked_required_reference_path(
        &self,
        argument: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, NodeKey, SymbolId, SymbolId, SymbolId, u8)> {
        let argument = self.query_group(argument)?;
        let (receiver, name) = self.count_member(argument)?;
        let ResolvedType::Record {
            symbol: source,
            stored: true,
        } = self.types.node_types.get(&receiver)?
        else {
            return None;
        };
        let ResolvedType::Record {
            symbol: target,
            stored: true,
        } = self.types.node_types.get(&argument)?
        else {
            return None;
        };
        let owner = self.resolve.symbols.get(source.0 as usize)?;
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return None;
        };
        let field = fields.iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|field| field.name == name)
        })?;
        if !matches!(self.resolve.symbols.get(field.0 as usize)?.kind,
            SymbolKind::Field { owner, .. } if owner == *source)
            || self.types.symbol_types.get(&field) != self.types.node_types.get(&argument)
            || self
                .reference_operand_type_id(self.types.node_types.get(&argument)?)
                .is_none()
        {
            return None;
        }
        let declaration = self
            .effects
            .models
            .get(source)?
            .fields
            .iter()
            .find(|declaration| declaration.field == field)?;
        if declaration.default.is_some()
            || declaration.server.is_some()
            || declaration.required_array
        {
            return None;
        }
        let (parameter, depth) = self
            .effects
            .scenarios
            .values()
            .filter(|scenario| scenario.module == module && !scenario.read && scenario.on.is_none())
            .flat_map(|scenario| &scenario.params)
            .find_map(|parameter| {
                let (model, depth) = self.checked_call_parent_path(receiver, parameter.param, 0)?;
                (model == *source).then_some((parameter.param, depth))
            })?;
        Some((parameter, receiver, *source, field, *target, depth))
    }

    fn checked_helper_reference_argument(
        &self,
        argument: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, NodeKey, SymbolId, SymbolId, SymbolId, u8)> {
        let path = self.checked_required_reference_path(argument, module)?;
        let argument = self.query_group(argument)?;
        let supplied = self.types.selected_calls.values().any(|selected| {
            let SelectedCallTarget::DeriveFn(derive) = &selected.target else {
                return false;
            };
            let Some(derive) = self.effects.derives.get(derive) else {
                return false;
            };
            selected
                .arguments
                .iter()
                .enumerate()
                .any(|(index, actual)| {
                    self.query_group(*actual) == Some(argument)
                        && derive
                            .params
                            .iter()
                            .zip(&selected.slots)
                            .any(|(formal, slot)| {
                                *slot == Some(index)
                                    && self.types.symbol_types.get(&formal.param)
                                        == self.types.node_types.get(&argument)
                            })
                })
        });
        supplied.then_some(path)
    }

    /// Only the authored identity selector consumes this required reference.
    /// Copies, nullable/defaulted fields and further navigation remain refused.
    fn checked_reference_identity_operand(
        &self,
        reference: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, NodeKey, SymbolId, SymbolId, SymbolId, u8)> {
        let path = self.checked_required_reference_path(reference, module)?;
        let reference = self.query_group(reference)?;
        let SymbolKind::Model { fields, .. } = &self.resolve.symbols.get(path.4.0 as usize)?.kind
        else {
            return None;
        };
        if fields.iter().any(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_none_or(|field| field.name == "id")
        }) {
            return None;
        }
        // This census depends only on the immutable source/type tables, not
        // the active scenario, lexical environment or recursive admission.
        // Build it once instead of scanning every CST node for each receiver.
        if self.source_facts.borrow().reference_identity_operands.is_none() {
            let operands = self.nodes.keys().filter_map(|key| {
                if self.types.node_types.get(key) != Some(&ResolvedType::Scalar(Scalar::Text))
                { return None; }
                let (base, name) = self.count_member(*key)?;
                (name == "id").then(|| self.query_group(base)).flatten()
            }).collect();
            self.source_facts.borrow_mut().reference_identity_operands = Some(operands);
        }
        self.source_facts.borrow().reference_identity_operands.as_ref()?
            .contains(&reference).then_some(path)
    }

    /// The original successful presence/published guard narrows exactly one
    /// required Template.current into its original lexical Revision binding.
    fn checked_current_revision_source(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<CurrentRevisionSource> {
        // Only the immutable table's own declaration can use its identity key.
        // A copied or altered declaration still receives the full source check.
        if !self
            .effects
            .scenarios
            .get(&scenario.scenario)
            .is_some_and(|original| std::ptr::eq(original, scenario))
        {
            return self.check_current_revision_source(scenario);
        }
        let key = (scenario.scenario, scenario.module, scenario.node);
        if let Some(result) = self.source_facts.borrow().revisions.get(&key) {
            return result.clone();
        }
        let result = self.check_current_revision_source(scenario);
        self.source_facts
            .borrow_mut()
            .revisions
            .insert(key, result.clone());
        result
    }

    fn check_current_revision_source(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<CurrentRevisionSource> {
        if scenario.read
            || scenario.on.is_some()
            || scenario.module.0 as usize >= self.resolve.modules.len()
        {
            return None;
        }
        let mut candidates = scenario
            .effects
            .iter()
            .enumerate()
            .filter_map(|(index, binding)| {
                if binding.verb != EffectVerb::Let || binding.binding.is_none() {
                    return None;
                }
                let value = self.query_group(binding.value?)?;
                let (receiver, name) = self.count_member(value)?;
                if name != "current" {
                    return None;
                }
                let parameter = self.query_parameter(scenario, receiver)?;
                let ResolvedType::Record {
                    symbol: template,
                    stored: true,
                } = self.types.symbol_types.get(&parameter)?
                else {
                    return None;
                };
                Some((index, binding, value, parameter, *template))
            });
        let (index, binding, value, parameter, template) = candidates.next()?;
        if candidates.next().is_some()
            || scenario.effects[..index]
                .iter()
                .any(|effect| !matches!(effect.verb, EffectVerb::Let | EffectVerb::Require))
        {
            return None;
        }
        let template_definition = self.checked_created_model(template, scenario.module)?;
        let field = template_definition
            .fields
            .iter()
            .find(|field| field.name == "current")?;
        let current_data = template_definition
            .declaration
            .fields
            .iter()
            .find(|data| data.field == field.field)?;
        let ResolvedType::Nullable(inner) = &field.ty else {
            return None;
        };
        let ResolvedType::Record {
            symbol: revision,
            stored: true,
        } = inner.as_ref()
        else {
            return None;
        };
        let revision = *revision;
        let revision_definition = self.checked_created_model(revision, scenario.module)?;
        let revision_symbol = self.resolve.symbols.get(revision.0 as usize)?;
        let parameter_data = scenario
            .params
            .iter()
            .find(|data| data.param == parameter)?;
        let parameter_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let text = &self.db.get(scenario.node.file)?.text;
        if !matches!(revision_symbol.kind,SymbolKind::Model {owner:ModelOwner::ChildOf(parent),..} if parent==template)
            || revision_definition.declaration.owner != ModelOwner::ChildOf(template)
            || current_data.default.is_some()
            || current_data.server.is_some()
            || current_data.required_array
            || self.types.field_reuse_sources.contains_key(&field.field)
            || !matches!(parameter_symbol.kind,SymbolKind::Param {owner,type_node,..} if owner==scenario.scenario && type_node==parameter_data.type_node)
            || parameter_symbol.module != scenario.module
            || self.nodes.get(&binding.node)?.kind != SyntaxKind::Let
            || self.types.node_types.get(&value) != Some(inner.as_ref())
        {
            return None;
        }
        let is_current = |node: NodeKey, ty: &ResolvedType| {
            self.count_member(node).is_some_and(|(base,name)| {
                name=="current" && matches!(self.query_binding(base),Some(Binding::Symbol(id)) if *id==parameter)
                    && self.types.node_types.get(&base)==Some(&ResolvedType::Record {symbol:template,stored:true})
                    && self.types.node_types.get(&node)==Some(ty)
            })
        };
        if !is_current(value, inner) {
            return None;
        }
        let mut leading = None;
        for guard in &scenario.guards {
            if guard.verb != EffectVerb::Require {
                return None;
            }
            let cond = guard.cond?;
            let mut pending = vec![cond];
            let mut operands = Vec::new();
            while let Some(node) = pending.pop() {
                if operands.len() + pending.len() > 200 {
                    return None;
                }
                if let Some((left, right)) = self.query_binary(node, "and") {
                    pending.extend([right, left]);
                } else {
                    operands.push(self.query_group(node)?);
                }
            }
            for (position, pair) in operands.windows(2).enumerate() {
                let Some((read, null)) = self.query_binary(pair[0], "!=") else {
                    continue;
                };
                let Some((published_read, name)) = self.count_member(pair[1]) else {
                    continue;
                };
                if is_current(read, &field.ty)
                    && self.nodes.get(&null)?.kind == SyntaxKind::Literal
                    && self.word(self.nodes.get(&null)?) == Some("null")
                    && self.types.node_types.get(&null) == Some(&ResolvedType::Null)
                    && name == "published"
                    && is_current(published_read, inner)
                    && self.types.node_types.get(&pair[0])
                        == Some(&ResolvedType::Scalar(Scalar::Bool))
                    && self.types.node_types.get(&pair[1])
                        == Some(&ResolvedType::Scalar(Scalar::Bool))
                    && guard.node.end <= binding.node.start
                {
                    if leading.is_some() {
                        return None;
                    }
                    let active = operands.get(position.wrapping_sub(1)).and_then(|node| {
                        let (receiver, name) = self.count_member(*node)?;
                        if name != "active" {
                            return None;
                        }
                        let active = template_definition.fields.iter().find(|field| field.name == "active")?;
                        let declaration = template_definition.declaration.fields.iter().find(|field| field.field == active.field)?;
                        (matches!(self.query_binding(receiver), Some(Binding::Symbol(id)) if *id == parameter)
                            && self.types.node_types.get(&receiver) == Some(&ResolvedType::Record { symbol: template, stored: true })
                            && self.types.node_types.get(node) == Some(&ResolvedType::Scalar(Scalar::Bool))
                            && active.ty == ResolvedType::Scalar(Scalar::Bool)
                            && declaration.server.is_none()
                            && !self.types.field_reuse_sources.contains_key(&active.field)
                            && text.get(declaration.type_node.start as usize..declaration.type_node.end as usize)?.trim() == "bool")
                            .then_some((*node, active.field))
                    });
                    leading = Some((active, pair[0], read, pair[1], published_read));
                }
            }
        }
        let (active, presence, presence_read, published, published_read) = leading?;
        let published_field = revision_definition
            .fields
            .iter()
            .find(|field| field.name == "published")?;
        if published_field.ty != ResolvedType::Scalar(Scalar::Bool) {
            return None;
        }
        let digest_field = revision_definition
            .fields
            .iter()
            .find(|field| field.name == "digest")?;
        if digest_field.ty != ResolvedType::Nullable(Box::new(ResolvedType::Scalar(Scalar::Text))) {
            return None;
        }
        let mut digest_presence = None;
        for effect in &scenario.effects[index + 1..] {
            if !matches!(effect.verb, EffectVerb::Let | EffectVerb::Require) {
                break;
            }
            if effect.verb != EffectVerb::Require {
                continue;
            }
            let Some((read, null)) = effect.cond.and_then(|cond| self.query_binary(cond, "!="))
            else {
                continue;
            };
            let Some((base, name)) = self.count_member(read) else {
                continue;
            };
            if name == "digest"
                && matches!(self.query_binding(base),Some(Binding::Let {node}) if *node==binding.node)
                && self.types.node_types.get(&base) == Some(inner.as_ref())
                && self.types.node_types.get(&read) == Some(&digest_field.ty)
                && self.types.node_types.get(&null) == Some(&ResolvedType::Null)
                && self.nodes.get(&null)?.kind == SyntaxKind::Literal
                && self.word(self.nodes.get(&null)?) == Some("null")
                && self.types.node_types.get(&effect.cond?)
                    == Some(&ResolvedType::Scalar(Scalar::Bool))
            {
                digest_presence = Some((self.query_group(effect.cond?)?, read));
                break;
            }
        }
        let (digest_presence, digest_read) = digest_presence?;
        Some(CurrentRevisionSource {
            parameter,
            template,
            field: field.field,
            revision,
            active,
            presence,
            presence_read,
            published,
            published_read,
            binding: binding.node,
            value,
            digest_presence,
            digest_read,
        })
    }

    fn current_revision_at(
        &self,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<CurrentRevisionSource> {
        let key = (node, module);
        if let Some(result) = self.source_facts.borrow().revision_owners.get(&key) {
            return result.clone();
        }
        let result = self.check_current_revision_at(node, module);
        self.source_facts
            .borrow_mut()
            .revision_owners
            .insert(key, result.clone());
        result
    }

    fn check_current_revision_at(
        &self,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<CurrentRevisionSource> {
        let mut owners = self.effects.scenarios.values().filter(|scenario| {
            scenario.module == module
                && scenario.node.file == node.file
                && scenario.node.start <= node.start
                && node.end <= scenario.node.end
        });
        let owner = owners.next()?;
        if owners.next().is_some() {
            return None;
        }
        self.checked_current_revision_source(owner)
    }

    fn checked_current_revision_leaf(
        &self,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<(CurrentRevisionSource, SymbolId)> {
        let fact = self.current_revision_at(node, module)?;
        let (receiver, name) = self.count_member(node)?;
        if node != fact.published
            && !matches!(self.query_binding(receiver),Some(Binding::Let {node}) if *node==fact.binding)
        {
            return None;
        }
        if node == fact.published && receiver != fact.published_read {
            return None;
        }
        if self.types.node_types.get(&receiver)
            != Some(&ResolvedType::Record {
                symbol: fact.revision,
                stored: true,
            })
        {
            return None;
        }
        let definition = self.checked_created_model(fact.revision, module)?;
        let field = definition.fields.iter().find(|field| field.name == name)?;
        let declared = Self::revision_leaf_declared(name, &field.ty)?;
        let data = definition
            .declaration
            .fields
            .iter()
            .find(|data| data.field == field.field)?;
        let actual = self.types.node_types.get(&node)?;
        self.revision_leaf_valid(
            node,
            &fact,
            name,
            &field.ty,
            field.field,
            &declared,
            data.default.is_some(),
            data.required_array,
            data.server.is_some(),
            actual,
        )?;
        Some((fact, field.field))
    }

    /// The declared type of a current-Revision leaf by member name.
    fn revision_leaf_declared(name: &str, field_ty: &ResolvedType) -> Option<ResolvedType> {
        match name {
            "definition"
                if checked_standard_nominal_name(field_ty) == Some("WorkflowDefinition") =>
            {
                Some(field_ty.clone())
            }
            "published" => Some(ResolvedType::Scalar(Scalar::Bool)),
            "digest" => Some(ResolvedType::Nullable(Box::new(ResolvedType::Scalar(
                Scalar::Text,
            )))),
            "outputs" => Some(ResolvedType::Scalar(Scalar::Int)),
            "duration" => Some(ResolvedType::Scalar(Scalar::Duration)),
            _ => None,
        }
    }

    /// Validate a current-Revision leaf: declared type, no defaults or
    /// reuse, owned by the revision, and the checked type matches.
    #[allow(clippy::too_many_arguments)]
    fn revision_leaf_valid(
        &self,
        node: NodeKey,
        fact: &CurrentRevisionSource,
        name: &str,
        field_ty: &ResolvedType,
        field_id: SymbolId,
        declared: &ResolvedType,
        has_default: bool,
        required_array: bool,
        has_server: bool,
        actual: &ResolvedType,
    ) -> Option<()> {
        if *field_ty != *declared
            || name == "definition" && (has_default || required_array)
            || has_server
            || self.types.field_reuse_sources.contains_key(&field_id)
            || !matches!(self.resolve.symbols.get(field_id.0 as usize)?.kind,SymbolKind::Field {owner,..} if owner==fact.revision)
        {
            return None;
        }
        if actual != declared
            && !(name == "digest"
                && actual == &ResolvedType::Scalar(Scalar::Text)
                && fact.digest_presence.end <= node.start)
        {
            return None;
        }
        Some(())
    }

    fn current_revision_control(
        &self,
        dependency: &DisclosureDependency,
        module: ModuleId,
    ) -> bool {
        if !dependency.calls.is_empty() || dependency.query_id.is_some() {
            return false;
        }
        self.current_revision_at(dependency.node, module)
            .is_some_and(|fact| {
                dependency.model == fact.template
                    && dependency.field == fact.field
                    && [fact.presence_read, fact.published_read, fact.value]
                        .contains(&dependency.node)
                    || fact.active.is_some_and(|(node, field)| {
                        dependency.node == node
                            && dependency.model == fact.template
                            && dependency.field == field
                            && dependency.field_name == "active"
                            && dependency.ty == ResolvedType::Scalar(Scalar::Bool)
                    })
                    || self
                        .checked_current_revision_leaf(dependency.node, module)
                        .is_some_and(|(fact, field)| {
                            dependency.model == fact.revision
                                && dependency.field == field
                                && [fact.published, fact.digest_read].contains(&dependency.node)
                        })
            })
    }

    fn current_revision_member(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if !calls.is_empty() || self.statement_depth != 1 || self.loop_node.is_some() {
            return Ok(None);
        }
        let Some(fact) = self.current_revision_at(key, module) else {
            return Ok(None);
        };
        if [fact.presence_read, fact.published_read, fact.value].contains(&key) {
            return self.current_revision_direct(key, module, env, calls, fact);
        }
        let Some((fact, field)) = self.checked_current_revision_leaf(key, module) else {
            return Ok(None);
        };
        self.current_revision_leaf(key, module, env, calls, fact, field)
    }

    /// A direct current-Revision occurrence reads its template's `current`
    /// through the original required Template parameter.
    fn current_revision_direct(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        fact: CurrentRevisionSource,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if !env.get(&Local::Symbol(fact.parameter)).is_some_and(|value| {
            value.record==Some(fact.template) && matches!(value.reference_origin,Some(ReferenceOrigin::Parameter(parameter)) if parameter==fact.parameter)
        }) {return Err(self.fail(key,"current Revision needs its original required Template"));}
        let ty = self
            .types
            .node_types
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing checked current Revision occurrence"))?
            .clone();
        let owner = self
            .resolve
            .symbols
            .get(fact.template.0 as usize)
            .ok_or_else(|| self.fail(key, "missing current Revision source owner"))?;
        let target = self
            .resolve
            .symbols
            .get(fact.revision.0 as usize)
            .ok_or_else(|| self.fail(key, "missing current Revision target"))?;
        let nullable = matches!(ty, ResolvedType::Nullable(_));
        Ok(Some(vec![ValuePath {
            reads: vec![DisclosureDependency {
                id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
                source: self.source(module, key)?,
                node: key,
                calls: Vec::new(),
                role: DependencyRole::Data,
                model: fact.template,
                field: fact.field,
                model_name: owner.canonical.clone(),
                field_name: "current".into(),
                ty,
                type_id: format!("{}{}", target.canonical, if nullable { "?" } else { "" }),
                query_id: None,
            }],
            observed: vec![(key, Vec::new())],
            record: Some(fact.revision),
            current_revision: Some(fact.binding),
            reference_origin: Some(ReferenceOrigin::Field {
                parameter: fact.parameter,
                model: fact.template,
                field: fact.field,
            }),
            ..ValuePath::default()
        }]))
    }

    /// A current-Revision leaf re-reads through its exact original
    /// receiver, recording the leaf dependency on every value.
    fn current_revision_leaf(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        fact: CurrentRevisionSource,
        field: SymbolId,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        let (base, _) = self
            .count_member(key)
            .ok_or_else(|| self.fail(key, "missing current Revision member"))?;
        let mut values = self.expr(base, module, env, calls)?;
        let declaration = self
            .resolve
            .symbols
            .get(field.0 as usize)
            .ok_or_else(|| self.fail(key, "missing current Revision field"))?;
        let model = self
            .resolve
            .symbols
            .get(fact.revision.0 as usize)
            .ok_or_else(|| self.fail(key, "missing current Revision model"))?;
        let ty = self
            .types
            .node_types
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing current Revision leaf type"))?
            .clone();
        let type_id = if declaration.name == "definition"
            && checked_standard_nominal_name(&ty) == Some("WorkflowDefinition")
        {
            "WorkflowDefinition".into()
        } else {
            self.field_type_id(key, field, &ty)?
        };
        for value in &mut values {
            if value.current_revision != Some(fact.binding)
                || value.record != Some(fact.revision)
                || !matches!(value.reference_origin,Some(ReferenceOrigin::Field {parameter,model,field}) if parameter==fact.parameter && model==fact.template && field==fact.field)
            {
                return Err(self.fail(
                    key,
                    "current Revision leaf needs its exact original receiver",
                ));
            }
            value.reads.push(DisclosureDependency {
                id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
                source: self.source(module, key)?,
                node: key,
                calls: Vec::new(),
                role: DependencyRole::Data,
                model: fact.revision,
                field,
                model_name: model.canonical.clone(),
                field_name: declaration.name.clone(),
                ty: ty.clone(),
                type_id: type_id.clone(),
                query_id: None,
            });
            value.observed.push((key, Vec::new()));
            value.record = None;
            value.reference = None;
            value.reference_origin = None;
            value.current_revision = None;
        }
        Ok(Some(values))
    }

    /// Reconstruct the original required scalar-reference source once: the
    /// actual scenario parameter, owning Model field, stored target, authored
    /// type spellings and complete checked schemas. The closed profiles retain
    /// their distinct scope and leading-guard requirements below; this proves
    /// source correspondence, never a generic stored-row traversal grant.
    fn checked_scalar_reference(
        &self,
        kind: ScalarReferenceKind,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, SymbolId, SymbolId)> {
        let (receiver, name) = self.count_member(node)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(receiver) else {
            return None;
        };
        let parameter = *parameter;
        let (root, depth) = self.checked_call_parent_path(receiver, parameter, 0)?;
        let declaration = self.resolve.symbols.get(root.0 as usize)?;
        let SymbolKind::Model {
            fields,
            owner: root_parent,
            ..
        } = &declaration.kind
        else {
            return None;
        };
        let parameter_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param {
            owner: scenario, ..
        } = parameter_symbol.kind
        else {
            return None;
        };
        let scenario = self.effects.scenarios.get(&scenario)?;
        let parameter_data = scenario
            .params
            .iter()
            .find(|param| param.param == parameter)?;
        let mut fields = fields
            .iter()
            .filter_map(|field| self.resolve.symbols.get(field.0 as usize))
            .filter(|field| field.name == name);
        let field = fields.next()?;
        let ResolvedType::Record {
            symbol: target_id,
            stored: true,
        } = self.types.symbol_types.get(&field.id)?
        else {
            return None;
        };
        let target_id = *target_id;
        let target = self.resolve.symbols.get(target_id.0 as usize)?;
        let data = self
            .effects
            .models
            .get(&root)?
            .fields
            .iter()
            .find(|data| data.field == field.id)?;
        let text = &self.db.get(node.file)?.text;
        let expected_name = match kind {
            ScalarReferenceKind::Profile => "profile",
            ScalarReferenceKind::Run => "run",
        };
        if name != expected_name
            || depth != 0
            || declaration.module != module
            || target.module != module
            || parameter_symbol.module != module
            || scenario.module != module
            || scenario.read
            || scenario.on.is_some()
            || node.file != scenario.node.file
            || node.start < scenario.node.start
            || node.end > scenario.node.end
            || !matches!(field.kind, SymbolKind::Field { owner, .. } if owner == root)
            || field.module != module
            || data.default.is_some()
            || data.server.is_some()
            || data.required_array
            || self.types.field_reuse_sources.contains_key(&field.id)
            || self.types.node_types.get(&node) != self.types.symbol_types.get(&field.id)
            || text
                .get(data.type_node.start as usize..data.type_node.end as usize)
                .is_none_or(|spelling| spelling.trim() != target.name)
            || text
                .get(parameter_data.type_node.start as usize..parameter_data.type_node.end as usize)
                .is_none_or(|spelling| spelling.trim() != declaration.name)
        {
            return None;
        }
        if kind == ScalarReferenceKind::Run {
            let SymbolKind::Model {
                owner: target_parent,
                ..
            } = &target.kind
            else {
                return None;
            };
            let by = scenario.by?;
            if fields.next().is_some()
                || !matches!((root_parent, target_parent),
                    (ModelOwner::ChildOf(left), ModelOwner::ChildOf(right)) if left == right)
                || scenario.cohort.is_some()
                || !matches!(self.query_binding(by), Some(Binding::Predicate))
                || self
                    .db
                    .get(by.file)?
                    .text
                    .get(by.start as usize..by.end as usize)?
                    .trim()
                    != "members"
            {
                return None;
            }
        }
        if self.checked_created_model(root, module).is_none()
            || self.checked_created_model(target_id, module).is_none()
        {
            return None;
        }
        if kind == ScalarReferenceKind::Run {
            let boolean = ResolvedType::Scalar(Scalar::Bool);
            // Find the real leading Require operand, not an arbitrary occurrence
            // with a matching span inside a default, helper, or do statement.
            let mut matched = false;
            let mut visited = 0usize;
            for guard in &scenario.guards {
                let condition = guard.cond?;
                if guard.verb != EffectVerb::Require
                    || self.nodes.get(&guard.node)?.kind != SyntaxKind::Require
                    || self.types.node_types.get(&condition) != Some(&boolean)
                {
                    return None;
                }
                let mut pending = vec![*self.nodes.get(&condition)?];
                while let Some(candidate) = pending.pop() {
                    visited += 1;
                    if visited > 16384 {
                        return None;
                    }
                    if candidate.kind == SyntaxKind::Unary {
                        let operands: Vec<_> = candidate
                            .children
                            .iter()
                            .filter(|child| expression(child.kind))
                            .collect();
                        let words: Vec<_> = candidate
                            .children
                            .iter()
                            .filter(|child| {
                                matches!(child.kind, SyntaxKind::Name | SyntaxKind::Punct)
                            })
                            .map(|child| self.word(child))
                            .collect::<Option<Vec<_>>>()?;
                        if let [leaf] = operands.as_slice()
                            && self.count_member(NodeKey::of(leaf)) == Some((node, "unfinished"))
                        {
                            if matched
                                || words != ["not"]
                                || self.types.node_types.get(&NodeKey::of(candidate))
                                    != Some(&boolean)
                                || self.types.node_types.get(&NodeKey::of(leaf)) != Some(&boolean)
                            {
                                return None;
                            }
                            matched = true;
                        }
                    }
                    pending.extend(candidate.children.iter());
                }
            }
            if !matched {
                return None;
            }
        }
        Some((parameter, root, field.id, target_id))
    }

    fn checked_profile_scalar(
        &self,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, SymbolId, SymbolId, SymbolId)> {
        let (reference, name) = self.count_member(node)?;
        let (parameter, branch, reference_field, profile) =
            self.checked_scalar_reference(ScalarReferenceKind::Profile, reference, module)?;
        let expected = match name {
            "active" => Scalar::Bool,
            "system_prompt" | "provider_key" | "policy_revision" => Scalar::Text,
            "input_tokens" | "output_tokens" => Scalar::Int,
            "duration" => Scalar::Duration,
            _ => return None,
        };
        let declaration = self.resolve.symbols.get(profile.0 as usize)?;
        let SymbolKind::Model { fields, .. } = &declaration.kind else {
            return None;
        };
        let field = fields
            .iter()
            .filter_map(|field| self.resolve.symbols.get(field.0 as usize))
            .find(|field| field.name == name)?;
        let SymbolKind::Field {
            owner: field_owner,
            type_node,
        } = field.kind
        else {
            return None;
        };
        self.profile_scalar_valid(
            node,
            module,
            profile,
            field.id,
            field_owner,
            type_node,
            field.module,
            expected,
        )?;
        Some((parameter, branch, reference_field, profile, field.id))
    }

    /// A scalar may consume an original required stored reference on a
    /// required input or its checked parent path. Retain both owning DATA
    /// observations; the actual getter still authorizes each reached field.
    fn checked_required_reference_scalar(&self, key: NodeKey, module: ModuleId)
        -> Option<(SymbolId, SymbolId, SymbolId, SymbolId, SymbolId)> {
        let (reference, name) = self.count_member(key)?;
        let (root, _) = self.count_member(reference)?;
        let (source, reference_field, target) = self.checked_required_model_reference(reference, module)?;
        let scenario = self.effects.scenarios.values().find(|scenario|
            scenario.module == module && !scenario.read && scenario.on.is_none()
            && scenario.node.file == key.file && scenario.node.start <= key.start
            && key.end <= scenario.node.end)?;
        let parameter = scenario.params.iter().find(|parameter|
            parameter.default.is_none() && !self.types.value_constraints.contains_key(&parameter.param)
                && self.checked_call_parent_path(root, parameter.param, 0)
                    .is_some_and(|(model, _)| model == source))?.param;
        let SymbolKind::Model { fields, .. } = &self.resolve.symbols.get(target.0 as usize)?.kind else { return None; };
        let field = fields.iter().filter_map(|id| self.resolve.symbols.get(id.0 as usize))
            .find(|field| field.name == name && matches!(field.kind, SymbolKind::Field {owner, ..} if owner == target))?;
        let ty = self.types.symbol_types.get(&field.id)?;
        if (!primitive_type(ty) && *ty != ResolvedType::Scalar(Scalar::Timezone))
            || self.types.node_types.get(&key) != Some(ty)
            || self.types.field_reuse_sources.contains_key(&field.id) { return None; }
        Some((parameter, source, reference_field, target, field.id))
    }

    /// Validate a profile scalar field declaration: owned by the profile
    /// with the expected scalar spelling, type and no reuse.
    #[allow(clippy::too_many_arguments)]
    fn profile_scalar_valid(
        &self,
        node: NodeKey,
        module: ModuleId,
        profile: SymbolId,
        field_id: SymbolId,
        field_owner: SymbolId,
        type_node: NodeKey,
        field_module: ModuleId,
        expected: Scalar,
    ) -> Option<()> {
        let data = self
            .effects
            .models
            .get(&profile)?
            .fields
            .iter()
            .find(|data| data.field == field_id)?;
        let authored = self.nodes.get(&data.node)?;
        let source = self.db.get(data.type_node.file)?;
        let ty = ResolvedType::Scalar(expected);
        if field_owner != profile
            || type_node != data.type_node
            || authored.kind != SyntaxKind::Field
            || !authored
                .children
                .iter()
                .any(|child| NodeKey::of(child) == data.type_node)
            || source
                .text
                .get(data.type_node.start as usize..data.type_node.end as usize)?
                .trim()
                != expected.as_str()
            || field_module != module
            || self.types.symbol_types.get(&field_id) != Some(&ty)
            || self.types.node_types.get(&node) != Some(&ty)
            || self.types.field_reuse_sources.contains_key(&field_id)
        {
            return None;
        }
        Some(())
    }

    fn checked_run_unfinished(
        &self,
        node: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, SymbolId, SymbolId, SymbolId)> {
        let (reference, name) = self.count_member(node)?;
        let (parameter, turn, reference_field, run) =
            self.checked_scalar_reference(ScalarReferenceKind::Run, reference, module)?;
        let SymbolKind::Model { fields, .. } = &self.resolve.symbols.get(run.0 as usize)?.kind
        else {
            return None;
        };
        let mut fields = fields
            .iter()
            .filter_map(|field| self.resolve.symbols.get(field.0 as usize))
            .filter(|field| field.name == name);
        let field = fields.next()?;
        let SymbolKind::Field { owner, type_node } = field.kind else {
            return None;
        };
        let data = self
            .effects
            .models
            .get(&run)?
            .fields
            .iter()
            .find(|data| data.field == field.id)?;
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        if name != "unfinished"
            || fields.next().is_some()
            || owner != run
            || type_node != data.type_node
            || field.module != module
            || self.types.symbol_types.get(&field.id) != Some(&boolean)
            || self.types.node_types.get(&node) != Some(&boolean)
            || self.types.field_reuse_sources.contains_key(&field.id)
            || self
                .db
                .get(type_node.file)?
                .text
                .get(type_node.start as usize..type_node.end as usize)?
                .trim()
                != "bool"
        {
            return None;
        }
        Some((parameter, turn, reference_field, run, field.id))
    }

    fn run_unfinished_control(&self, read: &DisclosureDependency, module: ModuleId) -> bool {
        read.calls.is_empty()
            && read.query_id.is_none()
            && read.field_name == "unfinished"
            && read.ty == ResolvedType::Scalar(Scalar::Bool)
            && self
                .checked_run_unfinished(read.node, module)
                .is_some_and(|(_, _, _, run, field)| read.model == run && read.field == field)
    }

    /// A stored reference array must genuinely reuse the exact child Scope
    /// field, with the same inherited literal range and no receiving skew.
    fn reference_field_bounds(&self, field: SymbolId, parameter: SymbolId) -> bool {
        let Some(alias) = self.query_parameter_bounds(parameter) else {
            return false;
        };
        self.types.symbol_types.get(&field) == self.types.symbol_types.get(&parameter)
            && self.reference_array_source_bounds(field, alias)
    }

    fn reference_array_source_bounds(&self, field: SymbolId, alias: SymbolId) -> bool {
        if self.types.field_reuse_sources.get(&field) != Some(&alias)
            || !matches!(self.resolve.symbols.get(alias.0 as usize).map(|symbol| &symbol.kind),
                Some(SymbolKind::Field { owner, .. }) if matches!(self.resolve.symbols.get(owner.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Contract { .. })))
        {
            return false;
        }
        let literal_bounds = |start: SymbolId| -> Option<(u64, u64)> {
            let mut current = start;
            let mut seen = HashSet::new();
            let mut chain = Vec::new();
            loop {
                if !seen.insert(current) || seen.len() > 128 {
                    return None;
                }
                let SymbolKind::Field { owner, .. } =
                    self.resolve.symbols.get(current.0 as usize)?.kind
                else {
                    return None;
                };
                let data = self
                    .effects
                    .models
                    .get(&owner)
                    .and_then(|model| model.fields.iter().find(|data| data.field == current))
                    .or_else(|| {
                        self.effects.records.get(&owner).and_then(|record| {
                            record.fields.iter().find(|data| data.field == current)
                        })
                    })?;
                if self.types.symbol_types.get(&current) != self.types.symbol_types.get(&field) {
                    return None;
                }
                chain.push(data);
                let Some(next) = self.types.field_reuse_sources.get(&current) else {
                    break;
                };
                current = *next;
            }
            let mut min = None;
            let mut max = None;
            for data in chain.into_iter().rev() {
                for modifier in &data.modifiers {
                    let slot = match modifier.name.as_str() {
                        "min" => &mut min,
                        "max" => &mut max,
                        _ => continue,
                    };
                    let key = self.query_group(modifier.value?)?;
                    if self.nodes.get(&key)?.kind != SyntaxKind::Literal
                        || self.types.node_types.get(&key)
                            != Some(&ResolvedType::Scalar(Scalar::Int))
                    {
                        return None;
                    }
                    let value = self
                        .db
                        .get(key.file)?
                        .text
                        .get(key.start as usize..key.end as usize)?
                        .trim()
                        .parse::<u64>()
                        .ok()?;
                    // Repeating the inherited literal is harmless; changing it
                    // loses correspondence even when the new range narrows.
                    if slot.is_some_and(|prior| prior != value) {
                        return None;
                    }
                    *slot = Some(value);
                }
            }
            let (min, max) = (min?, max?);
            (min >= 1 && min <= max && max <= 200).then_some((min, max))
        };
        literal_bounds(field).is_some() && literal_bounds(field) == literal_bounds(alias)
    }

    /// Require the actual original parameter syntax, so a copied lexical value
    /// cannot acquire the new parent-edge permission from its carried marker.
    fn original_reference_parameter(&self, key: NodeKey, parameter: SymbolId) -> bool {
        self.nodes
            .get(&key)
            .is_some_and(|node| node.kind == SyntaxKind::NameRef)
            && matches!(self.query_binding(key), Some(Binding::Symbol(id)) if *id == parameter)
    }

    /// The one-hop containment navigation off the original parameter
    /// (`i.parent`): a member whose base is the parameter itself and
    /// whose field is the containment link.
    fn original_navigation_parameter(&self, key: NodeKey, parameter: SymbolId) -> bool {
        let (base, field) = match self.count_member(key) {
            Some(parts) => parts,
            None => return false,
        };
        field == "parent" && self.original_reference_parameter(base, parameter)
    }

    /// A mutation CALL may pass the original required reference or its two
    /// authored containment edges. Copied lexical values cannot acquire this
    /// lineage, and a parent link is never an ordinary declared field.
    fn checked_call_parent_path(
        &self,
        key: NodeKey,
        parameter: SymbolId,
        depth: usize,
    ) -> Option<(SymbolId, u8)> {
        if depth > 2 {
            return None;
        }
        let node = self.nodes.get(&key)?;
        if node.kind == SyntaxKind::NameRef {
            return self.call_parent_nameref(key, parameter);
        }
        // A required Model leaf in the original Contract parameter owns the
        // same admitted containment lineage as a direct Model parameter. Its
        // Contract selectors do not consume the two authored parent hops.
        if node.kind == SyntaxKind::Member {
            let module = self.resolve.symbols.get(parameter.0 as usize)?.module;
            if let Some((root, model, _)) = self.checked_contract_input_reference(key, module) {
                return (root == parameter).then_some((model, 0));
            }
        }
        self.call_parent_hop(key, parameter, node, depth)
    }

    /// The parameter itself as a parent path: an original required
    /// reference to a stored model with no default.
    fn call_parent_nameref(&self, key: NodeKey, parameter: SymbolId) -> Option<(SymbolId, u8)> {
        if !self.original_reference_parameter(key, parameter) {
            return None;
        }
        let SymbolKind::Param { owner, .. } =
            self.resolve.symbols.get(parameter.0 as usize)?.kind
        else {
            return None;
        };
        let param = self
            .effects
            .scenarios
            .get(&owner)?
            .params
            .iter()
            .find(|param| param.param == parameter)?;
        let ResolvedType::Record {
            symbol,
            stored: true,
        } = self.types.symbol_types.get(&parameter)?
        else {
            return None;
        };
        (param.default.is_none()
            && self.types.node_types.get(&key) == self.types.symbol_types.get(&parameter)
            && matches!(
                self.resolve.symbols.get(symbol.0 as usize)?.kind,
                SymbolKind::Model { .. }
            ))
        .then_some((*symbol, 0))
    }

    /// One `.parent` hop off an already-admitted path.
    fn call_parent_hop(
        &self,
        key: NodeKey,
        parameter: SymbolId,
        node: &SyntaxNode,
        depth: usize,
    ) -> Option<(SymbolId, u8)> {
        if node.kind != SyntaxKind::Member || depth == 2 {
            return None;
        }
        let mut operands = node.children.iter().filter(|part| expression(part.kind));
        let base = NodeKey::of(operands.next()?);
        if operands.next().is_some()
            || node
                .children
                .iter()
                .rev()
                .find(|part| part.kind == SyntaxKind::Name)
                .and_then(|part| self.word(part))
                != Some("parent")
        {
            return None;
        }
        let (child, prior) = self.checked_call_parent_path(base, parameter, depth + 1)?;
        self.call_parent_hop_valid(key, base, child, prior)
    }

    /// Validate one `.parent` hop: the child is contained, `parent` is
    /// not an ordinary field, and both ends check as stored records.
    fn call_parent_hop_valid(
        &self,
        key: NodeKey,
        base: NodeKey,
        child: SymbolId,
        prior: u8,
    ) -> Option<(SymbolId, u8)> {
        self.call_parent_hop_valid_with_limit(key, base, child, prior, 2)
    }

    fn call_parent_hop_valid_with_limit(
        &self,
        key: NodeKey,
        base: NodeKey,
        child: SymbolId,
        prior: u8,
        limit: u8,
    ) -> Option<(SymbolId, u8)> {
        let declaration = self.resolve.symbols.get(child.0 as usize)?;
        let SymbolKind::Model {
            owner: ModelOwner::ChildOf(parent),
            fields,
            ..
        } = &declaration.kind
        else {
            return None;
        };
        let expected = ResolvedType::Record {
            symbol: *parent,
            stored: true,
        };
        if prior >= limit
            || fields.iter().any(|field| {
                self.resolve
                    .symbols
                    .get(field.0 as usize)
                    .is_none_or(|field| field.name == "parent")
            })
            || self.effects.models.get(&child)?.owner != ModelOwner::ChildOf(*parent)
            || self.types.node_types.get(&key) != Some(&expected)
            || self.types.node_types.get(&base)
                != Some(&ResolvedType::Record {
                    symbol: child,
                    stored: true,
                })
        {
            return None;
        }
        Some((*parent, prior + 1))
    }

    /// A stored-record field selected off an original required record
    /// parameter: the base keeps bare-parameter provenance and the field
    /// names its own stored model. `parent` keeps its hop semantics and
    /// never matches here, so a rejected hop cannot re-enter as a field.
    fn call_parameter_field(&self, key: NodeKey, parameter: SymbolId) -> Option<SymbolId> {
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let mut operands = node.children.iter().filter(|part| expression(part.kind));
        let base = operands.next()?;
        if operands.next().is_some() {
            return None;
        }
        if node
            .children
            .iter()
            .rev()
            .find(|part| part.kind == SyntaxKind::Name)
            .and_then(|part| self.word(part))
            == Some("parent")
        {
            return None;
        }
        let base_key = self.query_group(NodeKey::of(base))?;
        self.call_parent_nameref(base_key, parameter)?;
        let symbol = match self.types.node_types.get(&key)? {
            ResolvedType::Record { symbol, stored: true } => *symbol,
            ResolvedType::Nullable(inner) => match inner.as_ref() {
                ResolvedType::Record { symbol, stored: true } => *symbol,
                _ => return None,
            },
            _ => return None,
        };
        matches!(
            self.resolve.symbols.get(symbol.0 as usize)?.kind,
            SymbolKind::Model { .. }
        )
        .then_some(symbol)
    }

    /// A nullable direct stored field may feed one original required-model
    /// CALL only in its checked non-null IF arm. This does not grant a copied
    /// reference, a second navigation hop, or a reference-valued return.
    fn nullable_field_call_branch(&self, key: NodeKey, module: ModuleId)
        -> Option<(NodeKey, NodeKey, SymbolId, SymbolId, SymbolId, SymbolId)>
    {
        let mut owners = self.effects.scenarios.values().filter(|owner| owner.module == module
            && owner.on.is_none() && !owner.read && owner.node.file == key.file
            && owner.node.start <= key.start && key.end <= owner.node.end);
        let owner = owners.next()?;
        if owners.next().is_some() { return None; }
        for branch in &owner.effects {
            if branch.verb != EffectVerb::If { continue; }
            let condition = branch.cond?;
            let Some(node) = self.nodes.get(&condition) else { continue; };
            let children = node.children.iter().filter(|node| expression(node.kind)).collect::<Vec<_>>();
            let [reference, null] = children.as_slice() else { continue; };
            if node.kind != SyntaxKind::Binary || self.word(null) != Some("null")
                || !node.children.iter().any(|node| node.kind == SyntaxKind::Punct && self.word(node) == Some("!="))
            { continue; }
            let reference = NodeKey::of(reference);
            let Some((base, name)) = self.count_member(reference) else { continue; };
            let Some(Binding::Symbol(parameter)) = self.query_binding(base) else { continue; };
            let Some(root) = owner.params.iter().find(|param| param.param == *parameter && param.default.is_none()) else { continue; };
            let Some(ResolvedType::Record { symbol: source, stored: true }) = self.types.symbol_types.get(&root.param) else { continue; };
            let Some(SymbolKind::Model { fields, .. }) = self.resolve.symbols.get(source.0 as usize).map(|symbol| &symbol.kind) else { continue; };
            let Some(field) = fields.iter().filter_map(|field| self.resolve.symbols.get(field.0 as usize)).find(|field| field.name == name) else { continue; };
            let Some(ResolvedType::Nullable(inner)) = self.types.symbol_types.get(&field.id) else { continue; };
            let ResolvedType::Record { symbol: target, stored: true } = inner.as_ref() else { continue; };
            if self.types.node_types.get(&reference) != self.types.symbol_types.get(&field.id)
                || self.call_parameter_field(reference, *parameter) != Some(*target)
            { continue; }
            let [guard, call] = branch.then_effects.as_slice() else { continue; };
            let Some(EffectTarget::Operation(operation)) = call.target else { continue; };
            if guard.verb != EffectVerb::Require || call.verb != EffectVerb::Call
                || !self.complete_children.contains(&operation) { continue; }
            let child = self.effects.scenarios.get(&operation)?;
            let Some(argument) = call.args.iter().find(|argument| {
                let value = argument.value.unwrap_or(argument.key_node);
                self.count_member(value).is_some_and(|(receiver, field_name)| field_name == name
                    && matches!(self.query_binding(receiver), Some(Binding::Symbol(actual)) if actual == parameter))
                    && self.types.node_types.get(&value) == Some(inner.as_ref())
                    && child.params.iter().any(|formal| formal.default.is_none()
                        && self.resolve.symbols.get(formal.param.0 as usize).is_some_and(|symbol| symbol.name == argument.key)
                        && self.types.symbol_types.get(&formal.param) == Some(inner.as_ref()))
            }) else { continue; };
            let operand = argument.value.unwrap_or(argument.key_node);
            if key == condition || key == reference || key == operand {
                return Some((condition, operand, *parameter, *source, field.id, *target));
            }
        }
        None
    }

    /// One original nullable stored field is non-null only in the right
    /// operand and then arm of its checked IF. Keep its nullable read; the
    /// narrowed occurrence supplies navigation, never a reference result.
    /// A genuine optional Model formal at its original flow-checked non-null
    /// occurrence. The stored model and original null default stay sealed;
    /// lexical copies and nullable occurrences cannot use this carrier.
    fn narrowed_model_input(&self, key: NodeKey, module: ModuleId) -> Option<(SymbolId, SymbolId)> {
        let key = self.query_group(key)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(key) else {
            return None;
        };
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.node_types.get(&key)?
        else {
            return None;
        };
        if self.types.symbol_types.get(parameter)
            != Some(&ResolvedType::Nullable(Box::new(ResolvedType::Record {
                symbol: *model,
                stored: true,
            })))
        {
            return None;
        }
        let owner = self.effects.scenarios.values().find(|owner| {
            owner.module == module
                && owner.on.is_none()
                && !owner.read
                && owner.node.file == key.file
                && owner.node.start <= key.start
                && key.end <= owner.node.end
                && owner.params.iter().enumerate().any(|(index, input)| {
                    input.param == *parameter
                        && (input.default.is_none()
                            && self.nullable_model_input(owner, input) == Some(*model)
                            || self.source_require_null_model_input(owner, input, index))
                })
        })?;
        owner
            .params
            .iter()
            .any(|input| input.param == *parameter)
            .then_some((*parameter, *model))
    }

    fn nullable_field_if_branch(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<(NodeKey, NodeKey, SymbolId, SymbolId, SymbolId, SymbolId)> {
        let mut owners = self.effects.scenarios.values().filter(|owner| {
            owner.module == module
                && owner.on.is_none()
                && !owner.read
                && owner.node.file == key.file
                && owner.node.start <= key.start
                && key.end <= owner.node.end
        });
        let owner = owners.next()?;
        if owners.next().is_some() {
            return None;
        }
        let within =
            |outer: NodeKey| outer.file == key.file && outer.start <= key.start && key.end <= outer.end;
        let mut pending = owner.effects.iter().collect::<Vec<_>>();
        let mut steps = 0;
        while let Some(branch) = pending.pop() {
            steps += 1;
            if steps > 16384 {
                return None;
            }
            pending.extend(branch.then_effects.iter());
            pending.extend(branch.else_effects.iter());
            for arm in &branch.match_arms {
                pending.extend(arm.effects.iter());
            }
            if branch.verb != EffectVerb::If {
                continue;
            }
            let Some(condition) = branch.cond else {
                continue;
            };
            let (presence, right) = match self.query_binary(condition, "and") {
                Some((left, right)) => (left, Some(right)),
                None => (condition, None),
            };
            let Some((reference, null)) = self.query_binary(presence, "!=") else {
                continue;
            };
            if self.types.node_types.get(&null) != Some(&ResolvedType::Null)
                || self.word(self.nodes.get(&null)?) != Some("null")
            {
                continue;
            }
            let Some((root, name)) = self.count_member(reference) else {
                continue;
            };
            let Some(Binding::Symbol(parameter)) = self.query_binding(root) else {
                continue;
            };
            if !owner
                .params
                .iter()
                .any(|formal| formal.param == *parameter && formal.default.is_none())
            {
                continue;
            }
            let Some(ResolvedType::Record {
                symbol: source,
                stored: true,
            }) = self.types.symbol_types.get(parameter)
            else {
                continue;
            };
            let Some(field) = self
                .resolve
                .symbols
                .get(source.0 as usize)?
                .fields_of()
                .iter()
                .filter_map(|id| self.resolve.symbols.get(id.0 as usize))
                .find(|field| field.name == name)
            else {
                continue;
            };
            let Some(ResolvedType::Nullable(inner)) = self.types.symbol_types.get(&field.id) else {
                continue;
            };
            let ResolvedType::Record {
                symbol: target,
                stored: true,
            } = inner.as_ref()
            else {
                continue;
            };
            if self.call_parameter_field(reference, *parameter) != Some(*target)
                || self.types.node_types.get(&reference) != self.types.symbol_types.get(&field.id)
            {
                continue;
            }
            if key == presence {
                return Some((presence, reference, *parameter, *source, field.id, *target));
            }
            let dominated = right.is_some_and(within)
                || branch.then_effects.iter().any(|effect| within(effect.node));
            if !dominated {
                continue;
            }
            let Some((receiver, actual)) = self.count_member(key) else {
                continue;
            };
            if actual == name
                && matches!(self.query_binding(receiver), Some(Binding::Symbol(actual)) if actual == parameter)
                && self.types.node_types.get(&key) == Some(inner.as_ref())
                && self.call_parameter_field(key, *parameter) == Some(*target)
            {
                return Some((presence, key, *parameter, *source, field.id, *target));
            }
        }
        None
    }

    fn field_type_id(
        &self,
        key: NodeKey,
        field: SymbolId,
        ty: &ResolvedType,
    ) -> Result<String, DisclosureDecline> {
        // A stored File is an opaque source dependency, never a scalar result
        // or a byte/disclosure grant. Its actual field schema remains checked.
        let stored_file = *ty == ResolvedType::Scalar(Scalar::File)
            || matches!(ty, ResolvedType::Nullable(inner) if **inner == ResolvedType::Scalar(Scalar::File));
        let field_type_id = || if stored_file {
            Some(if matches!(ty, ResolvedType::Nullable(_)) { "file?" } else { "file" }.to_string())
        } else { exact_type_id(ty, self.resolve) };
        if !result_type(ty) && *ty != ResolvedType::Scalar(Scalar::Timezone) && !stored_file {
            return Err(self.fail(key, "unsupported stored field type"));
        }
        let owner = match self.resolve.symbols.get(field.0 as usize).map(|s| &s.kind) {
            Some(SymbolKind::Field { owner, .. }) => *owner,
            _ => return Err(self.fail(key, "missing stored field owner")),
        };
        if self.types.given_fields.contains_key(&field) {
            let module = self
                .resolve
                .symbols
                .get(owner.0 as usize)
                .ok_or_else(|| self.fail(key, "missing contributed field owner"))?
                .module;
            let definition = self
                .checked_created_model(owner, module)
                .ok_or_else(|| self.fail(key, "unestablished contributed field schema"))?;
            let original = definition
                .contributed
                .iter()
                .find(|candidate| candidate.field == field)
                .ok_or_else(|| self.fail(key, "missing checked contributed field"))?;
            if &original.ty != ty {
                return Err(self.fail(key, "contributed field type mismatch"));
            }
            return field_type_id()
                .ok_or_else(|| self.fail(key, "unsupported contributed stored field type"));
        }
        let declaration = self
            .effects
            .models
            .get(&owner)
            .and_then(|model| {
                model
                    .fields
                    .iter()
                    .find(|candidate| candidate.field == field)
            })
            .ok_or_else(|| self.fail(key, "missing checked stored field declaration"))?;
        if stored_file && self.types.symbol_types.get(&field) != Some(ty) {
            return Err(self.fail(key, "stored File field type mismatch"));
        }
        if declaration.required_array {
            return Err(self.fail(key, "required stored array is outside disclosure profile"));
        }
        let Some(alias) = self
            .types
            .value_constraints
            .get(&field)
            .and_then(|constraints| constraints.alias)
        else {
            return field_type_id()
                .ok_or_else(|| self.fail(key, "unsupported stored field type"));
        };
        let owner = self
            .resolve
            .symbols
            .get(alias.0 as usize)
            .ok_or_else(|| self.fail(key, "dangling stored field alias"))?;
        if owner.id != alias
            || !matches!(owner.kind, SymbolKind::Field { .. })
            || self
                .types
                .value_constraints
                .get(&alias)
                .and_then(|constraints| constraints.alias)
                != Some(alias)
            || !matches!(
                self.types.symbol_types.get(&alias),
                Some(ResolvedType::Scalar(Scalar::Text))
            )
            || self.types.judgments.is_empty()
        {
            return Err(self.fail(key, "unestablished alias inventory owner"));
        }
        let mut base = ty;
        let mut suffix = String::new();
        for _ in 0..64 {
            if let ResolvedType::Nullable(inner) = base {
                base = inner;
                suffix.push('?');
            } else {
                break;
            }
        }
        if !matches!(base, ResolvedType::Scalar(Scalar::Text)) {
            return Err(self.fail(key, "alias underlying type mismatch"));
        }
        Ok(format!("{}{suffix}", owner.canonical))
    }

    fn key_stamp(&self, key: NodeKey) -> Result<String, DisclosureDecline> {
        let source = self
            .db
            .get(key.file)
            .ok_or_else(|| self.fail(key, "missing source identity"))?;
        let mut owners = self.resolve.modules.iter().filter(|module| {
            module.file == key.file && module.span.start <= key.start && key.end <= module.span.end
        });
        let owner = owners
            .next()
            .ok_or_else(|| self.fail(key, "missing checked anchor module"))?;
        if owners.next().is_some() {
            return Err(self.fail(key, "ambiguous checked anchor module"));
        }
        Ok(format!(
            "{}:{}:{}:{}:{}",
            source.path, source.sha256, owner.name, key.start, key.end
        ))
    }

    fn call_stamp(&self, calls: &[NodeKey]) -> Result<String, DisclosureDecline> {
        calls
            .iter()
            .map(|key| self.key_stamp(*key))
            .collect::<Result<Vec<_>, _>>()
            .map(|parts| parts.join("/"))
    }

    fn decision_stamp(
        &self,
        decisions: &[DisclosureDecision],
    ) -> Result<String, DisclosureDecline> {
        decisions
            .iter()
            .map(|decision| {
                Ok(format!(
                    "{}:{}:{}",
                    self.key_stamp(decision.node)?,
                    self.call_stamp(&decision.calls)?,
                    match &decision.choice {
                        DisclosureChoice::Then => "then".to_string(),
                        DisclosureChoice::Else => "else".to_string(),
                        DisclosureChoice::Match(case) => format!("match:{}:{case}", case.len()),
                        DisclosureChoice::RhsEvaluated => "rhs-evaluated".to_string(),
                        DisclosureChoice::RhsSkipped => "rhs-skipped".to_string(),
                        DisclosureChoice::DefaultEvaluated => "default-evaluated".to_string(),
                        DisclosureChoice::DefaultProvided => "default-provided".to_string(),
                    }
                ))
            })
            .collect::<Result<Vec<_>, DisclosureDecline>>()
            .map(|parts| parts.join("/"))
    }

    fn fail(&self, node: NodeKey, reason: &'static str) -> DisclosureDecline {
        DisclosureDecline {
            source_facts: None,
            node,
            reason,
            influences: Vec::new(),
        }
    }

    /// Whether a node is anchored in one scenario's span: ordered,
    /// contained and present.
    fn source_anchor(&self, scenario: &super::effects::ScenarioData, node: NodeKey) -> bool {
        node.file == scenario.node.file
            && node.start >= scenario.node.start
            && node.end <= scenario.node.end
            && node.start <= node.end
            && self.nodes.contains_key(&node)
    }

    /// A scenario's checked parameters with their types and constraints.
    fn source_fact_params(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedScenarioParameter>> {
        let mut parameters = Vec::new();
        for param in &scenario.params {
            let ty = self.types.symbol_types.get(&param.param)?;
            if !self.source_anchor(scenario, param.node)
                || !self.source_anchor(scenario, param.type_node)
                || param
                    .default
                    .is_some_and(|node| !self.source_anchor(scenario, node))
                || !ty.is_resolved_shape()
            {
                return None;
            }
            parameters.push(CheckedScenarioParameter {
                parameter: param.param,
                node: param.node,
                type_node: param.type_node,
                ty: ty.clone(),
                default: param.default,
                constraints: self.types.value_constraints.get(&param.param).cloned(),
            });
        }
        Some(parameters)
    }

    /// A scenario's checked calls in preorder statement order.
    fn source_fact_calls(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedScenarioSourceCall>> {
        let mut pending: Vec<_> = scenario
            .guards
            .iter()
            .chain(&scenario.effects)
            .map(|effect| (effect, 0usize))
            .collect();
        pending.reverse();
        let mut calls = Vec::new();
        let mut steps = 0usize;
        while let Some((effect, depth)) = pending.pop() {
            steps += 1;
            if steps > 16384 || depth > 64 || !self.source_anchor(scenario, effect.node) {
                return None;
            }
            if effect.verb == EffectVerb::Call {
                self.source_fact_call(scenario, effect, &mut calls)?;
            }
            // Preorder follows authored statement/branch/arm order, not hash
            // table iteration. This records source structure, not execution.
            for arm in effect.match_arms.iter().rev() {
                for child in arm.effects.iter().rev() {
                    pending.push((child, depth + 1));
                }
            }
            for child in effect.else_effects.iter().rev() {
                pending.push((child, depth + 1));
            }
            for child in effect.then_effects.iter().rev() {
                pending.push((child, depth + 1));
            }
            if pending.len() > 16384 {
                return None;
            }
        }
        Some(calls)
    }

    /// One checked call: its operation target and uniquely named inputs.
    fn source_fact_call(
        &self,
        scenario: &super::effects::ScenarioData,
        effect: &Effect,
        calls: &mut Vec<CheckedScenarioSourceCall>,
    ) -> Option<()> {
        if calls.len() >= 200 || effect.args.len() > 200 {
            return None;
        }
        let Some(EffectTarget::Operation(operation)) = effect.target.as_ref() else {
            return None;
        };
        let target_node = effect.target_node?;
        if !self.source_anchor(scenario, target_node)
            || self.types.node_types.get(&target_node)
                != Some(&ResolvedType::Operation(*operation))
            || self.resolve.symbols.get(operation.0 as usize).is_none()
        {
            return None;
        }
        let result = self.types.effect_call_results.get(&effect.node)?.clone();
        if result.as_ref().is_some_and(|ty| !ty.is_resolved_shape()) {
            return None;
        }
        let inputs = self.source_fact_call_inputs(scenario, effect)?;
        calls.push(CheckedScenarioSourceCall {
            node: effect.node,
            target_node,
            operation: *operation,
            inputs,
            binding: effect.binding.clone(),
            result,
        });
        Some(())
    }

    /// One checked call's inputs: anchored, uniquely named, checked types.
    fn source_fact_call_inputs(
        &self,
        scenario: &super::effects::ScenarioData,
        effect: &Effect,
    ) -> Option<Vec<CheckedScenarioCallInput>> {
        let mut inputs = Vec::new();
        let mut names = HashSet::new();
        for argument in &effect.args {
            let node = argument.value.unwrap_or(argument.key_node);
            let ty = self.types.node_types.get(&node)?;
            if !self.source_anchor(scenario, argument.key_node)
                || !self.source_anchor(scenario, node)
                || !names.insert(argument.key.as_str())
                || !ty.is_resolved_shape()
            {
                return None;
            }
            inputs.push(CheckedScenarioCallInput {
                name: argument.key.clone(),
                node,
                ty: ty.clone(),
            });
        }
        Some(inputs)
    }

    /// A scenario's `by` role: a NameRef resolving to a Role in scope.
    fn source_fact_by_role(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<(NodeKey, SymbolId, String)> {
        let node = scenario.by?;
        let authored = self.nodes.get(&node)?;
        if authored.kind != SyntaxKind::NameRef {
            return None;
        }
        let spelling = super::name_text(
            super::kids(authored).first()?,
            &self.db.get(node.file)?.text,
        )?;
        let id = match self
            .resolve
            .module_scopes
            .get(scenario.module.0 as usize)?
            .prod
            .get(spelling)?
        {
            ScopedName::Local(id)
            | ScopedName::Imported {
                target: id,
                bound: false,
            } => *id,
            _ => return None,
        };
        let role = self.resolve.symbols.get(id.0 as usize)?;
        matches!(role.kind, SymbolKind::Role).then(|| (node, id, role.canonical.clone()))
    }

    fn checked_source_facts(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<CheckedScenarioSource> {
        let source = self.source(scenario.module, scenario.node).ok()?;
        let authored = self.db.get(scenario.node.file)?;
        if source.path.is_empty()
            || source.sha256 != sha256_hex(authored.text.as_bytes())
            || self
                .db
                .iter()
                .filter(|(_, value)| value.path == source.path)
                .count()
                != 1
            || scenario.params.len() > 200
        {
            return None;
        }
        if !self.source_anchor(scenario, scenario.node) {
            return None;
        }
        let result = self.types.symbol_results.get(&scenario.scenario)?.clone();
        if result.as_ref().is_some_and(|ty| !ty.is_resolved_shape()) {
            return None;
        }
        let parameters = self.source_fact_params(scenario)?;
        let calls = self.source_fact_calls(scenario)?;
        let by_role = self.source_fact_by_role(scenario);
        let decision_sites = self.checked_decision_sites(scenario);
        let unproved_helper_contained_requires = !scenario.read && scenario.on.is_none() &&
            scenario.cohort.is_none() && !scenario.scope_authority &&
            self.source_require_params_ok(scenario) && decision_sites.as_ref().is_some_and(|sites|
            sites.iter().any(|site| matches!(site.stage,
                CheckedDecisionStage::LeadingRequire | CheckedDecisionStage::BodyRequire) &&
                site.calls.iter().any(|call| self.unproved_helper_contained_any(scenario, call))));
        Some(CheckedScenarioSource {
            by_role,
            scenario: scenario.scenario,
            node: scenario.node,
            source,
            read: scenario.read,
            parameters,
            result,
            calls,
            expression_types: self.checked_create_expression_types(scenario.node, scenario.module),
            creates: self.checked_create_sources(scenario),
            decision_sites,
            unproved_helper_contained_requires,
            source_requires: self.checked_source_requires(scenario),
            unread_file_parameters: scenario.params.iter().enumerate().filter_map(|(index, parameter)|
                self.source_require_unread_file_input(scenario, parameter, index).then_some(parameter.param)).collect(),
            queries: self.checked_query_sources(scenario),
            transcripts: self.checked_transcript_sources(scenario),
            inline_selections: self.checked_inline_selection_sources(scenario),
            stored_contracts: self.checked_stored_contracts(scenario),
        })
    }

    /// Retain only the original direct prefix+WHERE/ORDER/SELECT Let. This
    /// source inventory survives unrelated closure declines without granting execution.
    fn checked_inline_selection_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedInlineSelectionSource>> {
        let mut out = Vec::new();
        for statement in &scenario.effects {
            if statement.verb != EffectVerb::Let {
                continue;
            }
            let Some(value) = statement.value else {
                continue;
            };
            let Some((_, selected)) = self.query_binary(value, "+") else {
                continue;
            };
            let Some(query) = self.query_group(selected) else {
                continue;
            };
            if self.nodes.get(&query)?.kind != SyntaxKind::Query
                || !self
                    .types
                    .node_types
                    .get(&query)
                    .is_some_and(transcript_message_array)
            {
                continue;
            }
            if out.len() >= 200 {
                return None;
            }
            out.push(self.checked_inline_selection_source(scenario, statement)?);
        }
        Some(out)
    }

    fn inline_selection_statement_ok(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: &Effect,
    ) -> Option<(NodeKey, Vec<&'a str>)> {
        if scenario.read
            || scenario.on.is_some()
            || statement.verb != EffectVerb::Let
            || !statement.then_effects.is_empty()
            || !statement.else_effects.is_empty()
            || !statement.match_arms.is_empty()
            || statement.when.is_some()
        {
            return None;
        }
        let value = statement.value?;
        let let_node = self.nodes.get(&statement.node)?;
        let values: Vec<_> = let_node
            .children
            .iter()
            .filter(|part| expression(part.kind))
            .map(NodeKey::of)
            .collect();
        let names: Vec<_> = let_node
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Name)
            .map(|part| self.word(part))
            .collect::<Option<Vec<_>>>()?;
        if let_node.kind != SyntaxKind::Let
            || values != [value]
            || names.len() != 2
            || names[0] != "let"
            || statement.binding.as_deref() != Some(names[1])
        {
            return None;
        }
        Some((value, names))
    }

    fn inline_selection_query_shape(
        &self,
        value: NodeKey,
    ) -> Option<(
        NodeKey,
        NodeKey,
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
        &'a String,
        NodeKey,
        NodeKey,
        NodeKey,
        NodeKey,
        &'a ResolvedType,
    )> {
        let (prefix_node, selected) = self.query_binary(value, "+")?;
        let query_node = self.query_group(selected)?;
        let checked = self.types.checked_queries.get(&query_node)?;
        let [alias, predicate, order, select] = checked.clauses.as_slice() else {
            return None;
        };
        let CheckedQueryClauseKind::As { name } = &alias.kind else {
            return None;
        };
        let [predicate_node] = predicate.expressions.as_slice() else {
            return None;
        };
        let [order_node] = order.expressions.as_slice() else {
            return None;
        };
        let [select_node] = select.expressions.as_slice() else {
            return None;
        };
        let ty = self.types.node_types.get(&value)?;
        let query_syntax = self.nodes.get(&query_node)?;
        if !checked.matches_source_nodes(query_syntax, expression)
            || checked.node != query_node
            || checked.projection.is_some()
            || !alias.expressions.is_empty()
            || predicate.kind != CheckedQueryClauseKind::Where
            || order.kind != CheckedQueryClauseKind::Order
            || select.kind != CheckedQueryClauseKind::Select
            || checked.result != *ty
            || self.types.node_types.get(&query_node) != Some(ty)
            || self.types.node_types.get(&selected) != Some(ty)
            || self.types.node_types.get(&prefix_node) != Some(ty)
            || !matches!(ty, ResolvedType::Array {element,ordered:true,nonempty:false}
                if checked_standard_nominal_name(element)==Some("TextMessage"))
        {
            return None;
        }
        Some((
            prefix_node,
            selected,
            checked,
            alias,
            predicate,
            order,
            select,
            name,
            *predicate_node,
            *order_node,
            *select_node,
            query_node,
            ty,
        ))
    }

    fn inline_selection_clause_spelling(
        &self,
        alias: &super::types::CheckedQueryClause,
        predicate: &super::types::CheckedQueryClause,
        order: &super::types::CheckedQueryClause,
        select: &super::types::CheckedQueryClause,
        predicate_node: NodeKey,
        order_node: NodeKey,
        select_node: NodeKey,
        name: &String,
    ) -> Option<()> {
        // Clauses retain their actual original expression anchors and spelling.
        for (clause, keyword, expressions) in [
            (alias, "as", vec![]),
            (predicate, "where", vec![predicate_node]),
            (order, "order", vec![order_node]),
            (select, "select", vec![select_node]),
        ] {
            let node = self.nodes.get(&clause.node)?;
            if node.kind != SyntaxKind::QueryClause
                || node
                    .children
                    .iter()
                    .find(|part| part.kind == SyntaxKind::Name)
                    .and_then(|part| self.word(part))
                    != Some(keyword)
                || node
                    .children
                    .iter()
                    .filter(|part| expression(part.kind))
                    .map(NodeKey::of)
                    .collect::<Vec<_>>()
                    != expressions
                || (keyword == "as"
                    && node
                        .children
                        .iter()
                        .filter(|part| part.kind == SyntaxKind::Name)
                        .map(|part| self.word(part))
                        .collect::<Option<Vec<_>>>()?
                        != ["as", name.as_str()])
            {
                return None;
            }
        }
        Some(())
    }

    fn inline_selection_domain(
        &self,
        scenario: &super::effects::ScenarioData,
        checked: &super::types::CheckedQuery,
    ) -> Option<(
        NodeKey,
        SymbolId,
        SymbolId,
        SymbolId,
        &'a Symbol,
        DisclosureQueryParentEdge,
        Rc<CheckedScenarioCreatedModel>,
        ResolvedType,
    )> {
        let (domain_parent, child_name) = self.count_member(checked.domain)?;
        let (argument, parent_name) = self.count_member(domain_parent)?;
        let parameter = self.query_parameter(scenario, argument)?;
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.symbol_types.get(&parameter)?
        else {
            return None;
        };
        let model = *model;
        let turn = self.checked_created_model(model, scenario.module)?;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let parent =
            self.checked_count_parent_edge(domain_parent, argument, model, scenario.module)?;
        let branch = self.checked_created_model(parent.parent, scenario.module)?;
        let array = ResolvedType::Array {
            element: Box::new(ResolvedType::Record {
                symbol: model,
                stored: true,
            }),
            ordered: true,
            nonempty: false,
        };
        if child_name != owner.name
            || parent_name != "parent"
            || checked.domain_type != array
            || self.types.node_types.get(&checked.domain) != Some(&array)
            || self.checked_call_parent_path(domain_parent, parameter, 0)
                != Some((parent.parent, 1))
            || branch.fields.iter().any(|field| field.name == child_name)
        {
            return None;
        }
        Some((
            argument,
            parameter,
            model,
            parent.parent,
            owner,
            parent,
            turn,
            array,
        ))
    }

    fn inline_selection_parameter<'t>(
        &self,
        scenario: &'t super::effects::ScenarioData,
        parameter: SymbolId,
        model: SymbolId,
    ) -> Option<&'t super::effects::ParamData> {
        let actual = scenario
            .params
            .iter()
            .find(|actual| actual.param == parameter)?;
        let actual_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        if !matches!(actual_symbol.kind,SymbolKind::Param {owner,type_node,..}
            if owner==scenario.scenario && type_node==actual.type_node)
            || actual_symbol.module != scenario.module
            || !self.checked_created_field_type(
                actual.type_node,
                scenario.module,
                &ResolvedType::Record {
                    symbol: model,
                    stored: true,
                },
                0,
            )
        {
            return None;
        }
        Some(actual)
    }

    fn inline_selection_prefix(
        &self,
        scenario: &super::effects::ScenarioData,
        prefix_node: NodeKey,
        parameter: SymbolId,
        model: SymbolId,
        ty: &ResolvedType,
        branch: &CheckedScenarioCreatedModel,
        parent: SymbolId,
    ) -> Option<(SymbolId, NodeKey, NodeKey, DisclosureQueryParentEdge)> {
        let (prefix_receiver, prefix_name) = self.count_member(prefix_node)?;
        let (prefix_argument, prefix_parent_name) = self.count_member(prefix_receiver)?;
        let prefix_parent = self.checked_count_parent_edge(
            prefix_receiver,
            prefix_argument,
            model,
            scenario.module,
        )?;
        let prefix = branch
            .fields
            .iter()
            .find(|field| field.name == prefix_name)?;
        let prefix_data = branch
            .declaration
            .fields
            .iter()
            .find(|field| field.field == prefix.field)?;
        let prefix_max = prefix_data
            .modifiers
            .iter()
            .find(|modifier| modifier.name == "max")?
            .value?;
        if prefix_parent_name != "parent"
            || self.query_parameter(scenario, prefix_argument) != Some(parameter)
            || prefix_parent.parent != parent
            || prefix.ty != *ty
            || prefix_data.required_array
            || prefix_data.default.is_some()
            || prefix_data.server.is_some()
            || self.declared_message_bound(prefix_max).is_none()
        {
            return None;
        }
        Some((prefix.field, prefix_node, prefix_max, prefix_parent))
    }

    fn inline_selection_bound(
        &self,
        scenario: &super::effects::ScenarioData,
        predicate_node: NodeKey,
        order_node: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
        parameter: SymbolId,
    ) -> Option<(NodeKey, NodeKey, SymbolId)> {
        let (candidate_node, bound_node) = self.query_binary(predicate_node, "<")?;
        let candidate = self.query_member(candidate_node, alias_node, model)?;
        let position = self.query_member(order_node, alias_node, model)?;
        let (bound_receiver, bound_name) = self.count_member(bound_node)?;
        if candidate != position
            || self.resolve.symbols.get(position.0 as usize)?.name != bound_name
            || self.query_parameter(scenario, bound_receiver) != Some(parameter)
            || self.types.node_types.get(&bound_receiver) != self.types.symbol_types.get(&parameter)
            || self.types.symbol_types.get(&position) != Some(&ResolvedType::Scalar(Scalar::Int))
            || [candidate_node, bound_node, order_node]
                .iter()
                .any(|node| {
                    self.types.node_types.get(node) != Some(&ResolvedType::Scalar(Scalar::Int))
                })
            || self.types.node_types.get(&predicate_node)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some((candidate_node, bound_node, position))
    }

    fn inline_selection_constructor<'r>(
        &self,
        scenario: &super::effects::ScenarioData,
        select_node: NodeKey,
        ty: &'r ResolvedType,
    ) -> Option<(&'a SyntaxNode, &'r ResolvedType)> {
        let constructor = *self.nodes.get(&select_node)?;
        let head = constructor
            .children
            .iter()
            .find(|part| expression(part.kind))?;
        let imported = self.word(head)?;
        let ResolvedType::Array { element, .. } = ty else {
            return None;
        };
        if constructor.kind != SyntaxKind::Construct
            || checked_standard_nominal_name(element) != Some("TextMessage")
            || self.types.node_types.get(&select_node) != Some(element.as_ref())
            || !matches!(
                self.resolve.node_typeref.get(&NodeKey::of(head)),
                Some(TypeRef::External)
            )
            || !matches!(self.resolve.module_scopes.get(scenario.module.0 as usize)?.prod.get(imported),
                Some(ScopedName::External {provider,name}) if provider=="std" && name=="TextMessage")
        {
            return None;
        }
        Some((constructor, element.as_ref()))
    }

    fn inline_selection_attachments_ok(
        &self,
        declaration: &super::effects::FieldData,
    ) -> Option<()> {
        let maximum = declaration
            .modifiers
            .iter()
            .find(|modifier| modifier.name == "max")?
            .value?;
        if self.word(self.nodes.get(&maximum)?) != Some("8")
            || self.types.node_types.get(&maximum)
                != Some(&ResolvedType::Scalar(Scalar::Int))
        {
            return None;
        }
        Some(())
    }

    fn inline_selection_entry_field(
        &self,
        entry: &SyntaxNode,
        expected: &String,
        expected_ty: &ResolvedType,
        alias_node: NodeKey,
        model: SymbolId,
        turn: &CheckedScenarioCreatedModel,
    ) -> Option<CheckedTranscriptField> {
        let key = entry.children.first()?;
        let mut values = entry.children.iter().filter(|part| expression(part.kind));
        let value_node = NodeKey::of(values.next()?);
        let source_field = self.query_member(value_node, alias_node, model)?;
        let field = turn
            .fields
            .iter()
            .find(|field| field.field == source_field)?;
        let declaration = turn
            .declaration
            .fields
            .iter()
            .find(|field| field.field == source_field)?;
        if key.kind != SyntaxKind::Name
            || self.word(key)? != expected
            || values.next().is_some()
            || self.query_member_name(value_node, alias_node, model)
                != Some(field.name.as_str())
            || field.ty != *expected_ty
            || self.types.node_types.get(&value_node) != Some(expected_ty)
            || declaration.default.is_some()
            || declaration.server.is_some()
            || declaration.required_array
        {
            return None;
        }
        if expected == "attachments" {
            self.inline_selection_attachments_ok(declaration)?;
        }
        Some(CheckedTranscriptField {
            name: expected.clone(),
            key_node: NodeKey::of(key),
            value_node,
            source_field,
            ty: expected_ty.clone(),
        })
    }

    fn inline_selection_entry_fields(
        &self,
        constructor: &SyntaxNode,
        element: &ResolvedType,
        alias_node: NodeKey,
        model: SymbolId,
        turn: &CheckedScenarioCreatedModel,
    ) -> Option<Vec<CheckedTranscriptField>> {
        let object = constructor
            .children
            .iter()
            .find(|part| part.kind == SyntaxKind::Object)?;
        let entries: Vec<_> = object
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::ObjectEntry)
            .collect();
        let schema = checked_text_schema_fields(element, Some("TextMessage"))?;
        if entries.len() != 3 || schema.len() != 3 {
            return None;
        }
        let mut fields = Vec::new();
        for (entry, (expected, expected_ty)) in entries.iter().zip(schema) {
            fields.push(self.inline_selection_entry_field(
                entry,
                expected,
                expected_ty,
                alias_node,
                model,
                turn,
            )?);
        }
        Some(fields)
    }

    fn inline_selection_dependency(
        &self,
        scenario_module: ModuleId,
        node: NodeKey,
        field: SymbolId,
        role: DependencyRole,
        model: SymbolId,
        owner: &Symbol,
        query_id: &str,
    ) -> Option<DisclosureDependency> {
        let declaration = self.resolve.symbols.get(field.0 as usize)?;
        let ty = self.types.symbol_types.get(&field)?;
        Some(DisclosureDependency {
            id: self
                .opaque(
                    if role == DependencyRole::Data {
                        "read-data"
                    } else {
                        "read-control"
                    },
                    node,
                    "",
                )
                .ok()?,
            source: self.source(scenario_module, node).ok()?,
            node,
            calls: Vec::new(),
            role,
            model,
            field,
            model_name: owner.canonical.clone(),
            field_name: declaration.name.clone(),
            ty: ty.clone(),
            type_id: checked_stored_contract_type_id(ty, None, self.resolve, 0)?,
            query_id: Some(query_id.to_owned()),
        })
    }

    fn inline_selection_emit(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: &Effect,
        value: NodeKey,
        parameter: SymbolId,
        argument: NodeKey,
        checked: &super::types::CheckedQuery,
        query_node: NodeKey,
        model: SymbolId,
        owner: &Symbol,
        alias_node: NodeKey,
        predicate_node: NodeKey,
        order_node: NodeKey,
        select_node: NodeKey,
        ty: &ResolvedType,
        parent: DisclosureQueryParentEdge,
        prefix_parent: DisclosureQueryParentEdge,
        prefix_field: SymbolId,
        prefix_node: NodeKey,
        prefix_max: NodeKey,
        candidate_node: NodeKey,
        bound_node: NodeKey,
        position: SymbolId,
        fields: Vec<CheckedTranscriptField>,
    ) -> Option<CheckedInlineSelectionSource> {
        let returned = scenario.effects.last()?;
        if returned.verb != EffectVerb::Return {
            return None;
        }
        let source = self.source(scenario.module, query_node).ok()?;
        let id = self.opaque("inline-selection-query", query_node, "").ok()?;
        let predicate_dependency = self.inline_selection_dependency(
            scenario.module,
            candidate_node,
            position,
            DependencyRole::Control,
            model,
            owner,
            &id,
        )?;
        let bound_dependency = self.inline_selection_dependency(
            scenario.module,
            bound_node,
            position,
            DependencyRole::Control,
            model,
            owner,
            &id,
        )?;
        let order_dependency = self.inline_selection_dependency(
            scenario.module,
            order_node,
            position,
            DependencyRole::Control,
            model,
            owner,
            &id,
        )?;
        let dependencies = fields
            .iter()
            .map(|field| {
                self.inline_selection_dependency(
                    scenario.module,
                    field.value_node,
                    field.source_field,
                    DependencyRole::Data,
                    model,
                    owner,
                    &id,
                )
            })
            .collect::<Option<Vec<_>>>()?;
        let query_dependencies = std::iter::once(&predicate_dependency)
            .chain(std::iter::once(&order_dependency))
            .chain(&dependencies)
            .map(|dependency| {
                let mut query = dependency.clone();
                query.id = self
                    .opaque(
                        if query.role == DependencyRole::Data {
                            "query-data"
                        } else {
                            "query-control"
                        },
                        query.node,
                        &id,
                    )
                    .ok()?;
                query.query_id = None;
                Some(query)
            })
            .collect::<Option<Vec<_>>>()?;
        let parent_dependency = DisclosureDependency {
            id: self.opaque("read-data", parent.node, "").ok()?,
            source: source.clone(),
            node: parent.node,
            calls: Vec::new(),
            role: DependencyRole::Data,
            model,
            field: model,
            model_name: owner.canonical.clone(),
            field_name: "parent".into(),
            ty: ResolvedType::Record {
                symbol: parent.parent,
                stored: true,
            },
            type_id: self
                .resolve
                .symbols
                .get(parent.parent.0 as usize)?
                .canonical
                .clone(),
            query_id: None,
        };
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", query_node, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node: query_node,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(CheckedInlineSelectionSource {
            query: DisclosureQuery {
                id,
                source,
                node: query_node,
                domain: checked.domain,
                model,
                model_name: owner.canonical.clone(),
                alias: Some(alias_node),
                predicate: Some(predicate_node),
                inputs: vec![(argument, parameter)],
                dependencies: query_dependencies,
                order: vec![DisclosureQueryOrder {
                    field: Some(position),
                    field_name: "position".into(),
                    descending: false,
                    node: order_node,
                }],
                limit: None,
                archived: false,
                cardinality_guard: None,
                return_node: returned.node,
                projection: None,
                first: None,
                count: None,
                influences,
            },
            checked: checked.clone(),
            statement: statement.node,
            value,
            parameter,
            argument,
            parent,
            prefix_parent,
            parent_dependency,
            prefix: prefix_field,
            prefix_node,
            prefix_max,
            bound_node,
            bound_field: position,
            bound_dependency,
            order_dependency,
            predicate_dependency,
            select: select_node,
            ty: ty.clone(),
            fields,
            dependencies,
            expression_types: Some(
                self.checked_create_expression_types(statement.node, scenario.module)?,
            ),
        })
    }

    fn inline_selection_tail(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: &Effect,
        value: NodeKey,
        checked: &super::types::CheckedQuery,
        query_node: NodeKey,
        alias_node: NodeKey,
        predicate_node: NodeKey,
        order_node: NodeKey,
        select_node: NodeKey,
        ty: &ResolvedType,
        argument: NodeKey,
        parameter: SymbolId,
        model: SymbolId,
        owner: &Symbol,
        turn: Rc<CheckedScenarioCreatedModel>,
        branch: Rc<CheckedScenarioCreatedModel>,
        parent: DisclosureQueryParentEdge,
        parent_parent: SymbolId,
        prefix_node: NodeKey,
    ) -> Option<CheckedInlineSelectionSource> {
        let (prefix_field, prefix_node, prefix_max, prefix_parent) = self
            .inline_selection_prefix(
                scenario,
                prefix_node,
                parameter,
                model,
                ty,
                &branch,
                parent_parent,
            )?;
        let (candidate_node, bound_node, position) = self.inline_selection_bound(
            scenario,
            predicate_node,
            order_node,
            alias_node,
            model,
            parameter,
        )?;
        let (constructor, element) =
            self.inline_selection_constructor(scenario, select_node, ty)?;
        let fields = self.inline_selection_entry_fields(
            constructor,
            element,
            alias_node,
            model,
            &turn,
        )?;
        self.inline_selection_emit(
            scenario,
            statement,
            value,
            parameter,
            argument,
            checked,
            query_node,
            model,
            owner,
            alias_node,
            predicate_node,
            order_node,
            select_node,
            ty,
            parent,
            prefix_parent,
            prefix_field,
            prefix_node,
            prefix_max,
            candidate_node,
            bound_node,
            position,
            fields,
        )
    }

    fn checked_inline_selection_source(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: &Effect,
    ) -> Option<CheckedInlineSelectionSource> {
        let (value, _) = self.inline_selection_statement_ok(scenario, statement)?;
        let (
            prefix_node,
            _,
            checked,
            alias,
            predicate,
            order,
            select,
            name,
            predicate_node,
            order_node,
            select_node,
            query_node,
            ty,
        ) = self.inline_selection_query_shape(value)?;
        self.inline_selection_clause_spelling(
            alias,
            predicate,
            order,
            select,
            predicate_node,
            order_node,
            select_node,
            name,
        )?;
        let (
            argument,
            parameter,
            model,
            parent_parent,
            owner,
            parent,
            turn,
            _,
        ) = self.inline_selection_domain(scenario, checked)?;
        let branch = self.checked_created_model(parent_parent, scenario.module)?;
        let _ = self.inline_selection_parameter(scenario, parameter, model)?;
        self.inline_selection_tail(
            scenario,
            statement,
            value,
            checked,
            query_node,
            alias.node,
            predicate_node,
            order_node,
            select_node,
            ty,
            argument,
            parameter,
            model,
            owner,
            turn,
            branch,
            parent,
            parent_parent,
            prefix_node,
        )
    }

    fn inline_selection_at(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<CheckedInlineSelectionSource> {
        let node = self.nodes.get(&key)?;
        if node.kind != SyntaxKind::Query && node.kind != SyntaxKind::Member {
            return None;
        }
        self.effects
            .scenarios
            .values()
            .filter(|scenario| {
                scenario.module == module
                    && scenario.node.file == key.file
                    && scenario.node.start <= key.start
                    && key.end <= scenario.node.end
            })
            .find_map(|scenario| {
                self.checked_inline_selection_sources(scenario)?
                    .into_iter()
                    .find(|fact| fact.query.node == key || fact.prefix_node == key)
            })
    }

    /// Abstract source evaluation only. Bound reads stay at their original
    /// per-candidate WHERE site; this does not hoist runtime reads or select rows.
    fn inline_selection_value(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        let fact = self
            .inline_selection_at(key, module)
            .ok_or_else(|| self.fail(key, "inline selection needs exact original source"))?;
        if !calls.is_empty()
            || self.statement_depth != 1
            || self.loop_node.is_some()
            || !env
                .get(&Local::Symbol(fact.parameter))
                .is_some_and(|input| {
                    input.record == Some(fact.parent.child)
                        && input.reference_origin
                            == Some(ReferenceOrigin::Parameter(fact.parameter))
                })
        {
            return Err(self.fail(key, "inline selection needs original required Turn input"));
        }
        let edge = if key == fact.prefix_node {
            &fact.prefix_parent
        } else {
            &fact.parent
        };
        let mut values = self.expr(edge.node, module, env, calls)?;
        if values.len() != 1
            || !values.iter().all(|value| {
                value.record == Some(edge.parent)
                    && value.reference_origin
                        == Some(ReferenceOrigin::Parent {
                            parameter: fact.parameter,
                            model: edge.parent,
                            depth: 1,
                        })
            })
        {
            return Err(self.fail(key, "inline selection parent source lineage"));
        }
        let value = &mut values[0];
        value.record = None;
        value.reference = None;
        value.reference_origin = None;
        if key == fact.prefix_node {
            value.reads.push(DisclosureDependency {
                id: self.opaque("read-data", key, "")?,
                source: fact.query.source.clone(),
                node: key,
                calls: Vec::new(),
                role: DependencyRole::Data,
                model: edge.parent,
                field: fact.prefix,
                model_name: self.resolve.symbols[edge.parent.0 as usize]
                    .canonical
                    .clone(),
                field_name: self.resolve.symbols[fact.prefix.0 as usize].name.clone(),
                ty: fact.ty,
                type_id: "TextMessage[]".into(),
                query_id: None,
            });
            value.observed.push((key, Vec::new()));
        } else {
            if !value.reads.contains(&fact.parent_dependency) {
                return Err(self.fail(key, "inline selection exact domain parent read"));
            }
            // Candidate WHERE and engine ORDER controls remain in the query.
            // Ordinary observations preserve the real bound, then eager SELECT.
            for dependency in std::iter::once(fact.bound_dependency).chain(fact.dependencies) {
                value.observed.push((dependency.node, Vec::new()));
                value.reads.push(dependency);
            }
            value.influences = fact.query.influences;
        }
        Ok(values)
    }

    /// Read the owning field's checked literal maximum; authored spellings
    /// and a particular draft's chosen maximum are not source authority.
    fn declared_message_bound(&self, key: NodeKey) -> Option<u64> {
        let node = self.nodes.get(&key)?;
        if node.kind != SyntaxKind::Literal
            || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Int))
        {
            return None;
        }
        let bound = self.word(node)?.parse::<u64>().ok()?;
        (bound > 0).then_some(bound)
    }

    fn transcript_bound_matches(&self, key: NodeKey, paths: &[ValuePath]) -> bool {
        let Some(bound) = self.declared_message_bound(key) else {
            return false;
        };
        !paths.is_empty()
            && paths.iter().all(|path| {
                path.reads.iter().any(|read| {
                    transcript_message_array(&read.ty)
                        && self
                            .effects
                            .models
                            .get(&read.model)
                            .and_then(|model| {
                                model.fields.iter().find(|field| field.field == read.field)
                            })
                            .and_then(|field| {
                                field
                                    .modifiers
                                    .iter()
                                    .find(|modifier| modifier.name == "max")
                            })
                            .and_then(|modifier| modifier.value)
                            .and_then(|maximum| self.declared_message_bound(maximum))
                            == Some(bound)
                })
            })
    }

    fn checked_transcript_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedTranscriptSource>> {
        let mut out = Vec::new();
        let mut visits = 0;
        for statement in scenario.guards.iter().chain(&scenario.effects) {
            let mut pending = vec![*self.nodes.get(&statement.node)?];
            while let Some(node) = pending.pop() {
                visits += 1;
                if visits > 16384 || out.len() > 200 {
                    return None;
                }
                let key = NodeKey::of(node);
                if matches!(
                    self.types.selected_calls.get(&key).map(|call| &call.target),
                    Some(SelectedCallTarget::DeriveFn(_))
                ) && self
                    .types
                    .node_types
                    .get(&key)
                    .is_some_and(transcript_message_array)
                    && let Some(fact) =
                        self.checked_transcript_source(scenario, statement.node, key)
                {
                    out.push(fact);
                }
                // Source order, including nested operands; no derive invocation
                // is hoisted, reused or replaced with a cardinality shortcut.
                pending.extend(node.children.iter().rev());
            }
        }
        out.sort_by_key(|fact| (fact.call.start, fact.call.end));
        Some(out)
    }

    fn transcript_statement_ok(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
    ) -> Option<()> {
        if scenario.read
            || scenario.on.is_some()
            || !scenario
                .guards
                .iter()
                .chain(&scenario.effects)
                .any(|effect| effect.node == statement)
            || call.file != statement.file
            || call.start < statement.start
            || call.end > statement.end
        {
            return None;
        }
        Some(())
    }

    fn transcript_declaration_identity(
        &self,
        scenario: &super::effects::ScenarioData,
        id: SymbolId,
        declaration: &Symbol,
        data: &super::effects::DeriveData,
        params: &[SymbolId],
        result_node: NodeKey,
        result: NodeKey,
        selected: &super::types::SelectedCall,
        formal: &super::effects::ParamData,
        actual: &super::effects::ParamData,
    ) -> Option<()> {
        if declaration.module != scenario.module
            || declaration.canonical
                != format!(
                    "{}.{}",
                    self.resolve.modules.get(scenario.module.0 as usize)?.name,
                    declaration.name
                )
            || data.module != scenario.module
            || data.derive != id
            || data.model.is_some()
            || params != [formal.param]
            || result_node != data.node
            || selected.slots.as_slice() != [Some(0)]
            || formal.default.is_some()
            || actual.default.is_some()
        {
            return None;
        }
        Some(())
    }

    fn transcript_parameter_name(
        &self,
        parameter: &super::effects::ParamData,
        symbol: &super::resolve::Symbol,
    ) -> bool {
        self.nodes
            .get(&parameter.node)
            .and_then(|node| {
                node.children
                    .iter()
                    .find(|child| child.kind == SyntaxKind::Name)
            })
            .is_some_and(|name| {
                self.word(name) == Some(symbol.name.as_str()) && name.span == symbol.span
            })
    }

    fn transcript_declaration_types(
        &self,
        scenario: &super::effects::ScenarioData,
        declaration: &Symbol,
        formal: &super::effects::ParamData,
        actual: &super::effects::ParamData,
        formal_symbol: &Symbol,
        actual_symbol: &Symbol,
        derive: SymbolId,
        branch_ty: &ResolvedType,
        argument: &NodeKey,
    ) -> Option<()> {
        if formal_symbol.module != scenario.module
            || actual_symbol.module != scenario.module
            || !self.transcript_parameter_name(formal, formal_symbol)
            || !self.transcript_parameter_name(actual, actual_symbol)
            || formal_symbol.canonical
                != format!("{}.{}", declaration.canonical, formal_symbol.name)
            || !matches!(formal_symbol.kind,SymbolKind::Param {owner,type_node,..} if owner==derive && type_node==formal.type_node)
            || !matches!(actual_symbol.kind,SymbolKind::Param {owner,type_node,..} if owner==scenario.scenario && type_node==actual.type_node)
            || self.types.symbol_types.get(&formal.param) != Some(branch_ty)
            || self.types.node_types.get(argument) != Some(branch_ty)
            || !self.checked_created_field_type(formal.type_node, scenario.module, branch_ty, 0)
            || !self.checked_created_field_type(actual.type_node, scenario.module, branch_ty, 0)
        {
            return None;
        }
        Some(())
    }

    fn transcript_call_syntax(
        &self,
        call: NodeKey,
        data: &super::effects::DeriveData,
        text: &str,
        result: NodeKey,
        result_ty: &ResolvedType,
        body: NodeKey,
        argument: &NodeKey,
        derive: SymbolId,
    ) -> Option<()> {
        let call_node = self.nodes.get(&call)?;
        let mut syntax_arguments = call_node
            .children
            .iter()
            .filter(|child| child.kind == SyntaxKind::Argument);
        let syntax_argument = syntax_arguments.next()?;
        let syntax_values: Vec<_> = syntax_argument
            .children
            .iter()
            .filter(|child| expression(child.kind))
            .map(NodeKey::of)
            .collect();
        let head = call_node
            .children
            .iter()
            .find(|child| expression(child.kind))?;
        if text.get(result.start as usize..result.end as usize)?.trim() != "TextMessage[]"
            || !self
                .nodes
                .get(&data.node)?
                .children
                .iter()
                .any(|child| NodeKey::of(child) == result)
            || !transcript_message_array(result_ty)
            || self.types.node_types.get(&call) != Some(result_ty)
            || self.types.node_types.get(&body) != Some(result_ty)
            || call_node.kind != SyntaxKind::Call
            || syntax_arguments.next().is_some()
            || syntax_values.as_slice() != [*argument]
            || !matches!(self.query_binding(NodeKey::of(head)),Some(Binding::Symbol(id)) if *id==derive)
        {
            return None;
        }
        Some(())
    }

    fn transcript_prefix_context(
        &self,
        scenario: &super::effects::ScenarioData,
        body: NodeKey,
        branch: SymbolId,
        branch_ty: &ResolvedType,
        result_ty: &ResolvedType,
        formal_param: SymbolId,
    ) -> Option<(SymbolId, NodeKey, NodeKey, NodeKey)> {
        let branch_definition = self.checked_created_model(branch, scenario.module)?;
        let (prefix_node, query_group) = self.query_binary(body, "+")?;
        let (prefix_receiver, prefix_name) = self.count_member(prefix_node)?;
        if !matches!(self.query_binding(prefix_receiver),Some(Binding::Symbol(id)) if *id==formal_param)
            || self.types.node_types.get(&prefix_receiver) != Some(branch_ty)
            || self.types.node_types.get(&prefix_node) != Some(result_ty)
        {
            return None;
        }
        let prefix_field = branch_definition
            .fields
            .iter()
            .find(|field| field.name == prefix_name)?;
        let prefix_data = branch_definition
            .declaration
            .fields
            .iter()
            .find(|field| field.field == prefix_field.field)?;
        let prefix_max = prefix_data
            .modifiers
            .iter()
            .find(|modifier| modifier.name == "max")?
            .value?;
        if prefix_field.ty != *result_ty
            || prefix_data.required_array
            || prefix_data.default.is_some()
            || prefix_data.server.is_some()
            || self.declared_message_bound(prefix_max).is_none()
        {
            return None;
        }
        Some((prefix_field.field, prefix_node, prefix_max, query_group))
    }

    fn transcript_query_context(
        &self,
        query_group: NodeKey,
        result_ty: &ResolvedType,
    ) -> Option<(
        NodeKey,
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedQueryClause,
        &'a String,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
        NodeKey,
        NodeKey,
    )> {
        let query_node = self.query_group(query_group)?;
        let query = self.types.checked_queries.get(&query_node)?;
        let [alias, order, select] = query.clauses.as_slice() else {
            return None;
        };
        let CheckedQueryClauseKind::As { name: alias_name } = &alias.kind else {
            return None;
        };
        if query.node != query_node
            || self.nodes.get(&query_node)?.kind != SyntaxKind::Query
            || query.projection.is_some()
            || order.kind != CheckedQueryClauseKind::Order
            || select.kind != CheckedQueryClauseKind::Select
            || self
                .nodes
                .get(&alias.node)?
                .children
                .iter()
                .filter(|child| child.kind == SyntaxKind::Name)
                .map(|child| self.word(child))
                .collect::<Option<Vec<_>>>()?
                != ["as", alias_name.as_str()]
            || query.result != *result_ty
            || self.types.node_types.get(&query_node) != Some(result_ty)
        {
            return None;
        }
        let [order_node] = order.expressions.as_slice() else {
            return None;
        };
        let [select_node] = select.expressions.as_slice() else {
            return None;
        };
        Some((
            query_node,
            query,
            alias,
            alias_name,
            order,
            select,
            *order_node,
            *select_node,
        ))
    }

    fn transcript_domain_context(
        &self,
        scenario: &super::effects::ScenarioData,
        query: &super::types::CheckedQuery,
        alias_node: NodeKey,
        order_node: NodeKey,
        formal_param: SymbolId,
        branch: SymbolId,
        branch_ty: &ResolvedType,
        branch_definition: &Rc<CheckedScenarioCreatedModel>,
    ) -> Option<(
        SymbolId,
        Rc<CheckedScenarioCreatedModel>,
        &'a Symbol,
        SymbolId,
    )> {
        let (domain_receiver, child_name) = self.count_member(query.domain)?;
        let ResolvedType::Array {
            element,
            ordered: true,
            nonempty: false,
        } = &query.domain_type
        else {
            return None;
        };
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = element.as_ref()
        else {
            return None;
        };
        let model = *model;
        let model_definition = self.checked_created_model(model, scenario.module)?;
        let model_symbol = self.resolve.symbols.get(model.0 as usize)?;
        if model_symbol.name != child_name
            || !matches!(model_symbol.kind,SymbolKind::Model {owner:ModelOwner::ChildOf(parent),..} if parent==branch)
            || branch_definition
                .fields
                .iter()
                .any(|field| field.name == child_name)
            || !matches!(self.query_binding(domain_receiver),Some(Binding::Symbol(id)) if *id==formal_param)
            || self.types.node_types.get(&domain_receiver) != Some(branch_ty)
            || self.types.node_types.get(&query.domain) != Some(&query.domain_type)
        {
            return None;
        }
        let position = self.query_member(order_node, alias_node, model)?;
        if self.types.symbol_types.get(&position) != Some(&ResolvedType::Scalar(Scalar::Int))
            || self.types.node_types.get(&order_node) != Some(&ResolvedType::Scalar(Scalar::Int))
        {
            return None;
        }
        Some((model, model_definition, model_symbol, position))
    }

    fn transcript_constructor_context<'r>(
        &self,
        scenario: &super::effects::ScenarioData,
        select_node: NodeKey,
        result_ty: &'r ResolvedType,
    ) -> Option<(&'a SyntaxNode, &'r ResolvedType, &'a str)> {
        let constructor = *self.nodes.get(&select_node)?;
        let constructor_head = constructor
            .children
            .iter()
            .find(|child| expression(child.kind))?;
        let imported = self.word(constructor_head)?;
        let element_ty = match result_ty {
            ResolvedType::Array { element, .. } => element.as_ref(),
            _ => return None,
        };
        if constructor.kind != SyntaxKind::Construct
            || checked_standard_nominal_name(element_ty) != Some("TextMessage")
            || self.types.node_types.get(&select_node) != Some(element_ty)
            || !matches!(
                self.resolve
                    .node_typeref
                    .get(&NodeKey::of(constructor_head)),
                Some(TypeRef::External)
            )
            || !matches!(self.resolve.module_scopes.get(scenario.module.0 as usize)?.prod.get(imported),Some(ScopedName::External {provider,name}) if provider=="std" && name=="TextMessage")
        {
            return None;
        }
        Some((constructor, element_ty, imported))
    }

    fn transcript_attachments_ok(
        &self,
        text: &str,
        source_data: &super::effects::FieldData,
    ) -> Option<()> {
        let maximum = source_data
            .modifiers
            .iter()
            .find(|modifier| modifier.name == "max")?
            .value?;
        if text
            .get(maximum.start as usize..maximum.end as usize)?
            .trim()
            != "8"
            || self.types.node_types.get(&maximum)
                != Some(&ResolvedType::Scalar(Scalar::Int))
        {
            return None;
        }
        Some(())
    }

    fn transcript_entry_field(
        &self,
        text: &str,
        entry: &SyntaxNode,
        expected: &String,
        expected_ty: &ResolvedType,
        alias_node: NodeKey,
        model: SymbolId,
        model_definition: &CheckedScenarioCreatedModel,
    ) -> Option<CheckedTranscriptField> {
        let key_node = entry.children.first()?;
        let mut values = entry.children.iter().filter(|child| expression(child.kind));
        let value_node = NodeKey::of(values.next()?);
        let source_field = self.query_member(value_node, alias_node, model)?;
        let field = model_definition
            .fields
            .iter()
            .find(|field| field.field == source_field)?;
        let source_data = model_definition
            .declaration
            .fields
            .iter()
            .find(|field| field.field == source_field)?;
        if key_node.kind != SyntaxKind::Name
            || self.word(key_node)? != expected
            || values.next().is_some()
            || self.query_member_name(value_node, alias_node, model)
                != Some(field.name.as_str())
            || field.ty != *expected_ty
            || self.types.node_types.get(&value_node) != Some(expected_ty)
            || source_data.default.is_some()
            || source_data.server.is_some()
            || source_data.required_array
        {
            return None;
        }
        if expected == "attachments" {
            self.transcript_attachments_ok(text, source_data)?;
        }
        Some(CheckedTranscriptField {
            name: expected.clone(),
            key_node: NodeKey::of(key_node),
            value_node,
            source_field,
            ty: expected_ty.clone(),
        })
    }

    fn transcript_entry_fields(
        &self,
        text: &str,
        constructor: &SyntaxNode,
        element_ty: &ResolvedType,
        alias_node: NodeKey,
        model: SymbolId,
        model_definition: &CheckedScenarioCreatedModel,
    ) -> Option<Vec<CheckedTranscriptField>> {
        let object = constructor
            .children
            .iter()
            .find(|child| child.kind == SyntaxKind::Object)?;
        let entries: Vec<_> = object
            .children
            .iter()
            .filter(|child| child.kind == SyntaxKind::ObjectEntry)
            .collect();
        let schema = checked_text_schema_fields(element_ty, Some("TextMessage"))?;
        if entries.len() != 3 || schema.len() != 3 {
            return None;
        }
        let mut fields = Vec::new();
        for (entry, (expected, expected_ty)) in entries.iter().zip(schema) {
            fields.push(self.transcript_entry_field(
                text,
                entry,
                expected,
                expected_ty,
                alias_node,
                model,
                model_definition,
            )?);
        }
        Some(fields)
    }

    fn transcript_emit(
        &self,
        scenario: &super::effects::ScenarioData,
        derive: SymbolId,
        data_node: NodeKey,
        body: NodeKey,
        call: NodeKey,
        statement: NodeKey,
        selected_slots: &[Option<usize>],
        argument: NodeKey,
        parameter: SymbolId,
        formal_param: SymbolId,
        branch: SymbolId,
        prefix_field: SymbolId,
        prefix_node: NodeKey,
        prefix_max: NodeKey,
        query: &super::types::CheckedQuery,
        query_node: NodeKey,
        model: SymbolId,
        model_symbol: &Symbol,
        alias_node: NodeKey,
        position: SymbolId,
        order_node: NodeKey,
        select_node: NodeKey,
        result_ty: &ResolvedType,
        fields: Vec<CheckedTranscriptField>,
    ) -> Option<CheckedTranscriptSource> {
        let source = self.source(scenario.module, call).ok()?;
        if source.sha256 != sha256_hex(self.db.get(call.file)?.text.as_bytes()) {
            return None;
        }
        let calls = vec![call];
        let call_stamp = self.call_stamp(&calls).ok()?;
        let id = self
            .opaque("transcript-query", query_node, &call_stamp)
            .ok()?;
        let order_dependency = DisclosureDependency {
            id: self.opaque("read-control", order_node, &call_stamp).ok()?,
            source: self.source(scenario.module, order_node).ok()?,
            node: order_node,
            calls: calls.clone(),
            role: DependencyRole::Control,
            model,
            field: position,
            model_name: model_symbol.canonical.clone(),
            field_name: self.resolve.symbols.get(position.0 as usize)?.name.clone(),
            ty: ResolvedType::Scalar(Scalar::Int),
            type_id: "int".into(),
            query_id: None,
        };
        let dependencies = fields
            .iter()
            .map(|field| {
                Some(DisclosureDependency {
                    id: self
                        .opaque("read-data", field.value_node, &call_stamp)
                        .ok()?,
                    source: self.source(scenario.module, field.value_node).ok()?,
                    node: field.value_node,
                    calls: calls.clone(),
                    role: DependencyRole::Data,
                    model,
                    field: field.source_field,
                    model_name: model_symbol.canonical.clone(),
                    field_name: self
                        .resolve
                        .symbols
                        .get(field.source_field.0 as usize)?
                        .name
                        .clone(),
                    ty: field.ty.clone(),
                    type_id: checked_stored_contract_type_id(&field.ty, None, self.resolve, 0)?,
                    query_id: Some(id.clone()),
                })
            })
            .collect::<Option<Vec<_>>>()?;
        let query_dependencies = dependencies
            .iter()
            .map(|dependency| {
                let mut query = dependency.clone();
                query.id = self.opaque("query-data", query.node, &id).ok()?;
                query.query_id = None;
                Some(query)
            })
            .collect::<Option<Vec<_>>>()?;
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", query_node, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node: query_node,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(CheckedTranscriptSource {
            id,
            source,
            derive,
            declaration: data_node,
            body,
            call,
            statement,
            slots: selected_slots.to_vec(),
            argument,
            parameter,
            formal: formal_param,
            branch,
            prefix: prefix_field,
            prefix_node,
            prefix_max,
            query: query.clone(),
            model,
            alias: alias_node,
            order: position,
            order_node,
            order_dependency,
            select: select_node,
            ty: result_ty.clone(),
            fields,
            dependencies,
            query_dependencies,
            influences,
        })
    }

    fn transcript_query_stage(
        &self,
        scenario: &super::effects::ScenarioData,
        derive: SymbolId,
        data_node: NodeKey,
        body: NodeKey,
        call: NodeKey,
        statement: NodeKey,
        selected_slots: &[Option<usize>],
        argument: NodeKey,
        parameter: SymbolId,
        formal_param: SymbolId,
        branch: SymbolId,
        branch_ty: &ResolvedType,
        branch_definition: Rc<CheckedScenarioCreatedModel>,
        result_ty: &ResolvedType,
        text: &str,
    ) -> Option<CheckedTranscriptSource> {
        let (prefix_field, prefix_node, prefix_max, query_group) = self
            .transcript_prefix_context(scenario, body, branch, branch_ty, result_ty, formal_param)?;
        let (query_node, query, alias, _, _, _, order_node, select_node) =
            self.transcript_query_context(query_group, result_ty)?;
        let (model, model_definition, model_symbol, position) =
            self.transcript_domain_context(
                scenario,
                query,
                alias.node,
                order_node,
                formal_param,
                branch,
                branch_ty,
                &branch_definition,
            )?;
        let (constructor, element_ty, _) =
            self.transcript_constructor_context(scenario, select_node, result_ty)?;
        let fields = self.transcript_entry_fields(
            text,
            constructor,
            element_ty,
            alias.node,
            model,
            &model_definition,
        )?;
        self.transcript_emit(
            scenario,
            derive,
            data_node,
            body,
            call,
            statement,
            selected_slots,
            argument,
            parameter,
            formal_param,
            branch,
            prefix_field,
            prefix_node,
            prefix_max,
            query,
            query_node,
            model,
            model_symbol,
            alias.node,
            position,
            order_node,
            select_node,
            result_ty,
            fields,
        )
    }

    fn checked_transcript_source(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
    ) -> Option<CheckedTranscriptSource> {
        self.transcript_statement_ok(scenario, statement, call)?;
        let selected = self.types.selected_calls.get(&call)?;
        let SelectedCallTarget::DeriveFn(derive) = &selected.target else {
            return None;
        };
        let derive = *derive;
        let data = self.effects.derives.get(&derive)?;
        let declaration = self.resolve.symbols.get(derive.0 as usize)?;
        let SymbolKind::DeriveFn {
            params,
            result_node,
        } = &declaration.kind
        else {
            return None;
        };
        let [formal] = data.params.as_slice() else {
            return None;
        };
        let [argument] = selected.arguments.as_slice() else {
            return None;
        };
        let parameter = self.query_parameter(scenario, *argument)?;
        let actual = scenario
            .params
            .iter()
            .find(|param| param.param == parameter)?;
        let formal_symbol = self.resolve.symbols.get(formal.param.0 as usize)?;
        let actual_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let ResolvedType::Record {
            symbol: branch,
            stored: true,
        } = self.types.symbol_types.get(&parameter)?
        else {
            return None;
        };
        let branch = *branch;
        let branch_ty = ResolvedType::Record {
            symbol: branch,
            stored: true,
        };
        let body = data.expr?;
        let result = data.result?;
        let text = &self.db.get(data.node.file)?.text;
        let result_ty = self.types.symbol_results.get(&derive)?.as_ref()?;
        self.transcript_declaration_identity(
            scenario,
            derive,
            declaration,
            data,
            params,
            *result_node,
            result,
            selected,
            formal,
            actual,
        )?;
        self.transcript_declaration_types(
            scenario,
            declaration,
            formal,
            actual,
            formal_symbol,
            actual_symbol,
            derive,
            &branch_ty,
            argument,
        )?;
        self.transcript_call_syntax(
            call,
            data,
            text,
            result,
            result_ty,
            body,
            argument,
            derive,
        )?;
        let branch_definition = self.checked_created_model(branch, scenario.module)?;
        self.transcript_query_stage(
            scenario,
            derive,
            data.node,
            body,
            call,
            statement,
            selected.slots.as_slice(),
            *argument,
            parameter,
            formal.param,
            branch,
            &branch_ty,
            branch_definition,
            result_ty,
            text,
        )
    }

    fn checked_create_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedScenarioCreate>> {
        let mut pending: Vec<_> = scenario
            .effects
            .iter()
            .rev()
            .map(|effect| (effect, 0))
            .collect();
        let mut creates = Vec::new();
        let mut steps = 0;
        while let Some((effect, depth)) = pending.pop() {
            steps += 1;
            if steps > 16384 || depth > 64 {
                return None;
            }
            if effect.verb == EffectVerb::Create {
                if creates.len() >= 200 {
                    return None;
                }
                creates.push(self.checked_create_source(effect, scenario.module)?);
            }
            for arm in effect.match_arms.iter().rev() {
                pending.extend(arm.effects.iter().rev().map(|child| (child, depth + 1)));
            }
            pending.extend(
                effect
                    .else_effects
                    .iter()
                    .rev()
                    .map(|child| (child, depth + 1)),
            );
            pending.extend(
                effect
                    .then_effects
                    .iter()
                    .rev()
                    .map(|child| (child, depth + 1)),
            );
        }
        let mut authored: Vec<_> = self
            .nodes
            .keys()
            .filter(|key| {
                key.kind == SyntaxKind::Create as u8
                    && key.file == scenario.node.file
                    && key.start >= scenario.node.start
                    && key.end <= scenario.node.end
            })
            .copied()
            .collect();
        authored.sort_by_key(|key| key.start);
        if !authored
            .iter()
            .copied()
            .eq(creates.iter().map(|created| created.node))
        {
            return None;
        }
        Some(creates)
    }

    /// Compare the authored object and its checked owning declaration before
    /// retaining any source facts. Public CRUD is a separate operation surface.
    fn checked_create_source(
        &self,
        effect: &Effect,
        module: ModuleId,
    ) -> Option<CheckedScenarioCreate> {
        let node = self.nodes.get(&effect.node)?;
        let Some(EffectTarget::Model(model)) = effect.target else {
            return None;
        };
        let definition = self.checked_created_model(model, module)?;
        let text = &self.db.get(effect.node.file)?.text;
        let parts = super::kids(node);
        let target = parts.iter().find(|part| part.kind == SyntaxKind::Path)?;
        let target_node = NodeKey::of(target);
        self.create_source_shape(effect, model, node, text, target_node)?;
        let binding = parts.windows(2).find_map(|pair| {
            super::is_name(pair[0], text, "as")
                .then(|| super::name_text(pair[1], text))
                .flatten()
        })?;
        if binding.is_empty() || effect.binding.as_deref() != Some(binding) {
            return None;
        }
        let object = parts.iter().find(|part| part.kind == SyntaxKind::Object)?;
        let entries: Vec<_> = object
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::ObjectEntry)
            .collect();
        if entries.len() != effect.args.len() || entries.len() > 200 {
            return None;
        }
        let (inputs, seen) = self.create_source_inputs(effect, text, &definition, &entries)?;
        if matches!(definition.declaration.owner, ModelOwner::ChildOf(_))
            && !seen.contains("parent")
        {
            return None;
        }
        self.create_source_required(&definition, &seen)?;
        Some(CheckedScenarioCreate {
            node: effect.node,
            target_node,
            source: self.source(module, effect.node).ok()?,
            model,
            binding: binding.into(),
            inputs,
            definition: definition.as_ref().clone(),
            expression_types: self.checked_create_expression_types(effect.node, module)?,
        })
    }

    /// One create source's shape: a `Create` node for this model with
    /// no `when` or branches.
    fn create_source_shape(
        &self,
        effect: &Effect,
        model: SymbolId,
        node: &SyntaxNode,
        text: &str,
        target_node: NodeKey,
    ) -> Option<()> {
        if node.kind != SyntaxKind::Create
            || self.resolve.node_symbol.get(&target_node) != Some(&model)
            || super::attribute_value(node, "when", text).map(NodeKey::of) != effect.when
            || effect.when.is_some()
            || !effect.then_effects.is_empty()
            || !effect.else_effects.is_empty()
            || !effect.match_arms.is_empty()
        {
            return None;
        }
        Some(())
    }

    /// One create source's inputs: each entry matches its argument by
    /// name, nodes and checked type, resolving `parent` or a field.
    fn create_source_inputs(
        &self,
        effect: &Effect,
        text: &str,
        definition: &CheckedScenarioCreatedModel,
        entries: &[&SyntaxNode],
    ) -> Option<(Vec<CheckedScenarioCreateInput>, HashSet<String>)> {
        let mut inputs = Vec::new();
        let mut seen = HashSet::new();
        for (entry, argument) in entries.iter().zip(&effect.args) {
            let parts = super::kids(entry);
            let key = *parts.first()?;
            let name = super::name_text(key, text)?;
            let value = parts.iter().find(|part| expression(part.kind)).copied();
            let key_node = NodeKey::of(key);
            let value_node = value.map(NodeKey::of).unwrap_or(key_node);
            let ty = self.types.node_types.get(&value_node)?;
            if argument.key != name
                || argument.key_node != key_node
                || argument.value != value.map(NodeKey::of)
                || !seen.insert(name.to_string())
                || !ty.is_resolved_shape()
            {
                return None;
            }
            let field = if name == "parent" {
                let ModelOwner::ChildOf(parent) = definition.declaration.owner else {
                    return None;
                };
                if ty
                    != &(ResolvedType::Record {
                        symbol: parent,
                        stored: true,
                    })
                {
                    return None;
                }
                None
            } else {
                let field = definition.fields.iter().find(|field| field.name == name)?;
                let data = definition
                    .declaration
                    .fields
                    .iter()
                    .find(|data| data.field == field.field)?;
                if data.server.is_some() || !created_input_type_matches(ty, &field.ty, 0) {
                    return None;
                }
                Some(field.field)
            };
            inputs.push(CheckedScenarioCreateInput {
                name: name.into(),
                field,
                key_node,
                value_node,
                ty: ty.clone(),
            });
        }
        Some((inputs, seen))
    }

    /// A create source covers every required field: no missing
    /// default-free, server-free, nonnullable inputs.
    fn create_source_required(
        &self,
        definition: &CheckedScenarioCreatedModel,
        seen: &HashSet<String>,
    ) -> Option<()> {
        for (data, field) in definition.declaration.fields.iter().zip(&definition.fields) {
            if !seen.contains(field.name.as_str())
                && data.default.is_none()
                // Checked Given field-trait defaults make omission legal in
                // the owning type checker and lower to the existing default.
                && !self.types.given_constraints.get(&field.field).is_some_and(|constraints|
                    constraints.iter().any(|constraint| constraint.default.is_some()))
                && data.server.is_none()
                && !matches!(field.ty, ResolvedType::Nullable(_))
                && (!matches!(field.ty, ResolvedType::Array { .. }) || data.required_array)
            {
                return None;
            }
        }
        Some(())
    }

    fn checked_create_expression_types(
        &self,
        created: NodeKey,
        module: ModuleId,
    ) -> Option<Vec<(NodeKey, ResolvedType)>> {
        let owner = self.create_expression_owner(created, module)?;
        let anchors = self.create_expression_anchors(owner)?;
        // Include shorthand Name nodes as well as expressions: their checked
        // binding type belongs to the authored key occurrence. Unknown/error
        // entries are retained faithfully and cannot become an admitted value.
        let mut retained: Vec<_> = self
            .types
            .node_types
            .iter()
            .filter(|(node, _)| {
                anchors.iter().any(|anchor| {
                    node.file == anchor.file && anchor.start <= node.start && node.end <= anchor.end
                }) && self.nodes.contains_key(node)
            })
            .map(|(node, ty)| (*node, ty.clone()))
            .collect();
        if retained.len() > 16384 {
            return None;
        }
        retained.sort_by_key(|(node, _)| (node.file, node.start, node.end, node.kind));
        Some(retained)
    }

    /// The scenario owning one created node: the unique scenario
    /// spanning it in this module.
    fn create_expression_owner(
        &self,
        created: NodeKey,
        module: ModuleId,
    ) -> Option<&super::effects::ScenarioData> {
        let mut owners = self.effects.scenarios.values().filter(|scenario| {
            scenario.module == module
                && scenario.node.file == created.file
                && scenario.node.start <= created.start
                && created.end <= scenario.node.end
        });
        let owner = owners.next()?;
        if owners.next().is_some() || !self.nodes.contains_key(&owner.node) {
            return None;
        }
        Some(owner)
    }

    /// Anchor nodes for create-expression types: the owner, its
    /// transcript declarations and its require-gate derive bodies.
    fn create_expression_anchors(
        &self,
        owner: &super::effects::ScenarioData,
    ) -> Option<Vec<NodeKey>> {
        let mut anchors = vec![owner.node];
        for transcript in self.checked_transcript_sources(owner).unwrap_or_default() {
            if !anchors.contains(&transcript.declaration) {
                anchors.push(transcript.declaration);
            }
        }
        for site in self.checked_decision_sites(owner)? {
            if !matches!(
                site.stage,
                CheckedDecisionStage::LeadingRequire | CheckedDecisionStage::BodyRequire
            ) {
                continue;
            }
            for call in site.calls {
                if let CheckedDecisionCallTarget::DeriveFn(derive) = call.target {
                    self.collect_derive_anchor(derive, &mut anchors)?;
                }
            }
        }
        Some(anchors)
    }

    /// One require-gate derive body anchor: validated before anchoring.
    fn collect_derive_anchor(
        &self,
        derive: SymbolId,
        anchors: &mut Vec<NodeKey>,
    ) -> Option<()> {
        let data = self.effects.derives.get(&derive)?;
        let declaration = self.resolve.symbols.get(derive.0 as usize)?;
        let body = data.expr?;
        if data.derive != derive
            || declaration.id != derive
            || declaration.module != data.module
            || !matches!(declaration.kind, SymbolKind::DeriveFn { .. })
            || self.source(data.module, data.node).ok()?
                != self.source(data.module, body).ok()?
            || body.file != data.node.file
            || body.start < data.node.start
            || body.end > data.node.end
        {
            return None;
        }
        if !anchors.contains(&data.node) {
            anchors.push(data.node);
        }
        Some(())
    }

    fn checked_created_model(
        &self,
        model: SymbolId,
        module: ModuleId,
    ) -> Option<Rc<CheckedScenarioCreatedModel>> {
        let key = (model, module);
        if let Some(result) = self.source_facts.borrow().models.get(&key) {
            return result.clone();
        }
        // Insert only a finished check, including refusal. Never mark an
        // in-progress model as admitted or suppress recursive validation.
        let result = self.check_created_model(model, module).map(Rc::new);
        self.source_facts
            .borrow_mut()
            .models
            .insert(key, result.clone());
        result
    }

    fn check_created_model(
        &self,
        model: SymbolId,
        module: ModuleId,
    ) -> Option<CheckedScenarioCreatedModel> {
        let symbol = self.resolve.symbols.get(model.0 as usize)?;
        let SymbolKind::Model {
            fields: order,
            owner,
            ..
        } = &symbol.kind
        else {
            return None;
        };
        let data = self.effects.models.get(&model)?;
        // Resolver membership also includes separately declared derives. Only
        // original stored fields are writable/defaulted constructor slots.
        let mut stored_order = Vec::new();
        let mut contributed = Vec::new();
        for id in order {
            let member = self.resolve.symbols.get(id.0 as usize)?;
            if member.id != *id || member.module != module {
                return None;
            }
            match member.kind {
                SymbolKind::Field { owner, .. } if owner == model => {
                    if let Some(value) = self.types.given_fields.get(id) {
                        let ty = self.types.symbol_types.get(id)?;
                        if member.canonical != format!("{}.{}", symbol.canonical, value.name)
                            || member.name != value.name
                            || value.default.is_none()
                            || !ty.is_resolved_shape()
                        {
                            return None;
                        }
                        contributed.push(CheckedScenarioContributedField {
                            field: *id,
                            canonical: member.canonical.clone(),
                            source: self
                                .source(
                                    module,
                                    NodeKey {
                                        file: member.span.file,
                                        start: member.span.start,
                                        end: member.span.end,
                                        kind: SyntaxKind::Field as u8,
                                    },
                                )
                                .ok()?,
                            span: member.span,
                            ty: ty.clone(),
                            value: value.clone(),
                            constraints: self.types.value_constraints.get(id).cloned(),
                        });
                    } else {
                        stored_order.push(*id);
                    }
                }
                SymbolKind::DeriveField { model: owner, .. } if owner == model => {}
                _ => return None,
            }
        }
        let node = self.nodes.get(&data.node)?;
        let text = &self.db.get(data.node.file)?.text;
        let parts = super::kids(node);
        let name = parts
            .iter()
            .filter_map(|part| super::name_text(part, text))
            .find(|name| *name != "export")?;
        let parent = parts
            .windows(2)
            .find_map(|pair| super::is_name(pair[0], text, "in").then_some(pair[1]));
        let authored_owner = if let Some(parent) = parent {
            let segments = super::path_segments(parent, text);
            let [name] = segments.as_slice() else {
                return None;
            };
            if *name == "app" {
                ModelOwner::App
            } else {
                let id = match self
                    .resolve
                    .module_scopes
                    .get(module.0 as usize)?
                    .prod
                    .get(*name)?
                {
                    ScopedName::Local(id) => *id,
                    ScopedName::Imported {
                        target,
                        bound: false,
                    } => *target,
                    _ => return None,
                };
                if !matches!(
                    self.resolve.symbols.get(id.0 as usize)?.kind,
                    SymbolKind::Model { .. }
                ) {
                    return None;
                }
                ModelOwner::ChildOf(id)
            }
        } else {
            ModelOwner::Team
        };
        if node.kind != SyntaxKind::Model
            || symbol.id != model
            || symbol.module != module
            || symbol.name != name
            || data.model != model
            || data.module != module
            || symbol.canonical
                != format!(
                    "{}.{}",
                    self.resolve.modules.get(module.0 as usize)?.name,
                    name
                )
            || text.get(symbol.span.start as usize..symbol.span.end as usize) != Some(name)
            || *owner != authored_owner
            || data.owner != *owner
            || order.len() > 200
            || !stored_order
                .iter()
                .copied()
                .eq(data.fields.iter().map(|field| field.field))
        {
            return None;
        }
        let authored: Vec<_> = node
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Field)
            .collect();
        if authored.len() != data.fields.len() {
            return None;
        }
        let mut fields = Vec::new();
        for (node, data) in authored.iter().zip(&data.fields) {
            let field = self.resolve.symbols.get(data.field.0 as usize)?;
            let SymbolKind::Field {
                owner, type_node, ..
            } = &field.kind
            else {
                return None;
            };
            let ty = self.types.symbol_types.get(&data.field)?;
            if *owner != model
                || field.module != module
                || field.id != data.field
                || *type_node != data.type_node
                || field.canonical != format!("{}.{}", symbol.canonical, field.name)
                || text.get(field.span.start as usize..field.span.end as usize)
                    != Some(field.name.as_str())
                || NodeKey::of(node) != data.node
                || !ty.is_resolved_shape()
                || !self.checked_created_field_type(data.type_node, module, ty, 0)
                || !self.checked_created_field(node, data, &field.name, ty)
            {
                return None;
            }
            let mut modifier_sources = Vec::new();
            let mut current = data.field;
            let mut seen = HashSet::new();
            loop {
                if !seen.insert(current) || seen.len() > 128 {
                    return None;
                }
                let member = self.resolve.symbols.get(current.0 as usize)?;
                let SymbolKind::Field { owner, .. } = member.kind else {
                    return None;
                };
                let Some(original) = self
                    .effects
                    .models
                    .get(&owner)
                    .and_then(|value| value.fields.iter().find(|field| field.field == current))
                    .or_else(|| {
                        self.effects.records.get(&owner).and_then(|value| {
                            value.fields.iter().find(|field| field.field == current)
                        })
                    })
                else {
                    break;
                };
                let reuse = self.types.field_reuse_sources.get(&current).copied();
                modifier_sources.push((
                    original.clone(),
                    self.source(member.module, original.node).ok()?,
                    self.types.symbol_types.get(&current)?.clone(),
                    reuse,
                    self.types
                        .given_constraints
                        .get(&current)
                        .cloned()
                        .unwrap_or_default(),
                ));
                let Some(parent) = reuse else {
                    break;
                };
                current = parent;
            }
            fields.push(CheckedScenarioCreatedField {
                field: data.field,
                name: field.name.clone(),
                canonical: field.canonical.clone(),
                source: self.source(module, data.node).ok()?,
                ty: ty.clone(),
                constraints: self.types.value_constraints.get(&data.field).cloned(),
                reuse: self.types.field_reuse_sources.get(&data.field).copied(),
                modifier_sources,
            });
        }
        if !self.checked_created_rules(data) {
            return None;
        }
        Some(CheckedScenarioCreatedModel {
            canonical: symbol.canonical.clone(),
            source: self.source(module, data.node).ok()?,
            span: symbol.span,
            declaration: data.clone(),
            fields,
            contributed,
        })
    }

    /// Match only the original create field vocabulary against its declared
    /// type owner. This does not infer a schema from an object value's shape.
    fn checked_created_field_type(
        &self,
        key: NodeKey,
        module: ModuleId,
        ty: &ResolvedType,
        depth: usize,
    ) -> bool {
        if depth > 64 {
            return false;
        }
        let Some(node) = self.nodes.get(&key) else {
            return false;
        };
        let Some(source) = self.db.get(key.file) else {
            return false;
        };
        let text = &source.text;
        match (node.kind, ty) {
            (SyntaxKind::NullableType, ResolvedType::Nullable(inner))
            | (SyntaxKind::ArrayType, ResolvedType::Array { element: inner, .. }) => node
                .children
                .iter()
                .find(|part| {
                    matches!(
                        part.kind,
                        SyntaxKind::NamedType
                            | SyntaxKind::NullableType
                            | SyntaxKind::ArrayType
                            | SyntaxKind::EnumType
                            | SyntaxKind::DeliveryType
                    )
                })
                .is_some_and(|part| {
                    self.checked_created_field_type(NodeKey::of(part), module, inner, depth + 1)
                }),
            (SyntaxKind::NamedType, _) => {
                let Some(path) = node
                    .children
                    .iter()
                    .find(|part| part.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                let segments = super::path_segments(path, text);
                match self.resolve.node_typeref.get(&NodeKey::of(path)) {
                    Some(TypeRef::Scalar(name)) => {
                        super::types::std_schema_type(name).as_ref() == Some(ty)
                    }
                    Some(TypeRef::Symbol(id)) => {
                        self.types.symbol_types.get(id) == Some(ty)
                            // Bare owning Model/Contract names resolve to this
                            // exact record type; their declarations are not
                            // field/parameter entries in symbol_types.
                            || matches!(ty, ResolvedType::Record {symbol, stored: true} if symbol == id && matches!(self.resolve.symbols.get(id.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Model {..} | SymbolKind::Contract {..})))
                    }
                    Some(TypeRef::FieldChain {
                        fields, consumed, ..
                    }) => {
                        *consumed == segments.len()
                            && fields
                                .last()
                                .is_some_and(|field| self.types.symbol_types.get(field) == Some(ty))
                    }
                    Some(TypeRef::External) => {
                        let Some(ScopedName::External { provider, name }) =
                            segments.first().and_then(|name| {
                                self.resolve
                                    .module_scopes
                                    .get(module.0 as usize)?
                                    .prod
                                    .get(*name)
                            })
                        else {
                            return false;
                        };
                        if provider != "std" {
                            return false;
                        }
                        let Some(mut schema) = nominal_schema(name) else {
                            return false;
                        };
                        if segments.len() == 1 {
                            return checked_standard_nominal_name(ty) == Some(schema.name);
                        }
                        for (index, segment) in segments.iter().enumerate().skip(1) {
                            let Some((_, declared)) =
                                schema.fields.iter().find(|(name, _)| name == segment)
                            else {
                                return false;
                            };
                            if index == segments.len() - 1 {
                                return super::types::std_schema_type(declared).as_ref()
                                    == Some(ty);
                            }
                            let Some(nested) = nominal_schema(declared) else {
                                return false;
                            };
                            schema = nested;
                        }
                        false
                    }
                    _ => false,
                }
            }
            (SyntaxKind::EnumType, ResolvedType::Enum { cases, .. }) => node
                .children
                .iter()
                .filter(|part| part.kind == SyntaxKind::Path)
                .flat_map(|part| super::path_segments(part, text))
                .eq(cases.iter().map(String::as_str)),
            (SyntaxKind::DeliveryType, ResolvedType::Delivery { op }) => {
                let Some(path) = node.children.iter().find(|part| part.kind == SyntaxKind::Path) else { return false; };
                let segments = super::path_segments(path, text);
                let [binding, operation] = segments.as_slice() else { return false; };
                let Some(ScopedName::Imported {target, bound:true}) = self.resolve.module_scopes.get(module.0 as usize)
                    .and_then(|scope| scope.prod.get(*binding)) else { return false; };
                let Some(SymbolKind::Capability {ops,..}) = self.resolve.symbols.get(target.0 as usize).map(|symbol| &symbol.kind) else { return false; };
                ops.contains(op) && self.resolve.symbols.get(op.0 as usize).is_some_and(|symbol|
                    symbol.name == *operation && matches!(symbol.kind, SymbolKind::CapabilityOp {..}))
            }
            (SyntaxKind::DeliveryType, ResolvedType::StdDelivery { capability, op }) => {
                let Some(path) = node
                    .children
                    .iter()
                    .find(|part| part.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                let segments = super::path_segments(path, text);
                let [binding, operation] = segments.as_slice() else {
                    return false;
                };
                let Some(ScopedName::External { provider, name }) = self
                    .resolve
                    .module_scopes
                    .get(module.0 as usize)
                    .and_then(|scope| scope.prod.get(*binding))
                else {
                    return false;
                };
                provider == "std"
                    && std_capability(name).is_some_and(|actual| actual.name == *capability)
                    && std_operation(name, operation).is_some_and(|actual| actual == *op)
            }
            _ => false,
        }
    }

    fn checked_created_field(
        &self,
        node: &SyntaxNode,
        data: &super::effects::FieldData,
        name: &str,
        ty: &ResolvedType,
    ) -> bool {
        let Some(source) = self.db.get(data.node.file) else {
            return false;
        };
        let text = &source.text;
        let parts = super::kids(node);
        if parts.first().and_then(|part| super::name_text(part, text)) != Some(name) {
            return false;
        }
        let Some(type_at) = parts
            .iter()
            .position(|part| NodeKey::of(part) == data.type_node)
        else {
            return false;
        };
        let mut at = type_at + 1;
        let required = parts
            .get(at)
            .is_some_and(|part| super::is_punct(part, text, "!"));
        at += usize::from(required);
        let mut default = None;
        let mut server = None;
        if parts
            .get(at)
            .is_some_and(|part| super::is_punct(part, text, "="))
        {
            default = parts
                .get(at + 1)
                .filter(|part| expression(part.kind))
                .map(|part| NodeKey::of(part));
            at += 2;
        } else if parts
            .get(at)
            .is_some_and(|part| super::is_name(part, text, "server"))
        {
            server = parts
                .get(at + 2)
                .filter(|part| expression(part.kind))
                .map(|part| NodeKey::of(part));
            at += 3;
        }
        let mut modifiers = Vec::new();
        while let Some(part) = parts.get(at) {
            if matches!(
                part.kind,
                SyntaxKind::DescriptionValue | SyntaxKind::Annotation
            ) {
                at += 1;
                continue;
            }
            let Some(name) = super::name_text(part, text) else {
                break;
            };
            let value = match name {
                "trim" | "unique" | "machine" => None,
                "min" | "max" => parts
                    .get(at + 2)
                    .filter(|part| expression(part.kind))
                    .map(|part| NodeKey::of(part)),
                _ => break,
            };
            modifiers.push(super::effects::ModifierData {
                name: name.into(),
                node: NodeKey::of(part),
                value,
            });
            at += if matches!(name, "min" | "max") { 3 } else { 1 };
        }
        required == data.required_array
            && default == data.default
            && server == data.server
            && modifiers == data.modifiers
            && default.into_iter().chain(server).all(|key| {
                self.types
                    .node_types
                    .get(&key)
                    .is_some_and(|actual| created_input_type_matches(actual, ty, 0)
                        || *actual==ResolvedType::Scalar(Scalar::Int) && *ty==ResolvedType::Scalar(Scalar::Decimal)
                            && self.nodes.get(&key).is_some_and(|node|node.kind==SyntaxKind::Literal)
                            && self.db.get(key.file).and_then(|source|source.text.get(key.start as usize..key.end as usize))
                                .is_some_and(|value|value.parse::<i128>().is_ok()))
            })
    }

    fn checked_created_rules(&self, data: &super::effects::ModelData) -> bool {
        let matches_nodes = |kind: SyntaxKind, retained: Vec<NodeKey>| {
            let mut authored: Vec<_> = self
                .nodes
                .iter()
                .filter_map(|(key, node)| {
                    if node.kind != kind || key.file != data.node.file {
                        return None;
                    }
                    let target = node
                        .children
                        .iter()
                        .find(|part| part.kind == SyntaxKind::Path)?;
                    (self.resolve.node_symbol.get(&NodeKey::of(target)) == Some(&data.model))
                        .then_some(*key)
                })
                .collect();
            authored.sort_by_key(|key| key.start);
            authored == retained
        };
        let selectors = |key: NodeKey, field_node: Option<NodeKey>, fields: &[String]| {
            let Some(node) = self.nodes.get(&key) else {
                return false;
            };
            let Some(source) = self.db.get(key.file) else {
                return false;
            };
            let value = super::attribute_value(node, "fields", &source.text);
            value.map(NodeKey::of) == field_node
                && value.is_some_and(|value| {
                    let Some(text) = source
                        .text
                        .get(value.span.start as usize..value.span.end as usize)
                    else {
                        return false;
                    };
                    text.split(',')
                        .map(str::trim)
                        .eq(fields.iter().map(String::as_str))
                })
        };
        let attribute = |key: NodeKey, name: &str, retained: Option<NodeKey>| {
            self.nodes
                .get(&key)
                .zip(self.db.get(key.file))
                .is_some_and(|(node, source)| {
                    super::attribute_value(node, name, &source.text).map(NodeKey::of) == retained
                })
        };
        matches_nodes(
            SyntaxKind::Invariant,
            data.invariants.iter().map(|rule| rule.node).collect(),
        ) && matches_nodes(
            SyntaxKind::Unique,
            data.uniques.iter().map(|rule| rule.node).collect(),
        ) && matches_nodes(
            SyntaxKind::Lock,
            data.locks.iter().map(|rule| rule.node).collect(),
        ) && matches_nodes(
            SyntaxKind::Retain,
            data.retains.iter().map(|rule| rule.node).collect(),
        ) && data.invariants.iter().all(|rule| {
            rule.target == data.model
                && rule.module == data.module
                && self.nodes.get(&rule.node).is_some_and(|node| {
                    node.children
                        .iter()
                        .find(|part| expression(part.kind) && part.kind != SyntaxKind::Path)
                        .map(NodeKey::of)
                        == rule.predicate
                })
        }) && data.uniques.iter().all(|rule| {
            rule.module == data.module
                && selectors(rule.node, rule.fields_node, &rule.fields)
                && attribute(rule.node, "where", rule.where_predicate)
        }) && data.locks.iter().all(|rule| {
            rule.module == data.module
                && selectors(rule.node, rule.fields_node, &rule.fields)
                && attribute(rule.node, "when", rule.when)
        }) && data
            .retains
            .iter()
            .all(|rule| rule.module == data.module && attribute(rule.node, "until", rule.until))
    }

    /// Resolve only required Contract fields rooted at the original parameter.
    /// The slot is the existing admission path, never a stored-field read.
    fn checked_contract_input_reference(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, String)> {
        let (parameter, ty, path) = self.checked_contract_input_path(key, module, 0)?;
        let ResolvedType::Record { symbol: target, .. } = ty else {
            return None;
        };
        (!path.is_empty()
            && matches!(
                self.resolve.symbols.get(target.0 as usize)?.kind,
                SymbolKind::Model { .. }
            ))
        .then(|| {
            let name = &self.resolve.symbols[parameter.0 as usize].name;
            (parameter, target, format!("{name}/{}", path.join("/")))
        })
    }

    fn checked_contract_input_path(
        &self,
        key: NodeKey,
        module: ModuleId,
        depth: usize,
    ) -> Option<(SymbolId, ResolvedType, Vec<String>)> {
        if depth >= 16 {
            return None;
        }
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        if node.kind == SyntaxKind::NameRef {
            return self.contract_input_nameref(key, module);
        }
        if node.kind != SyntaxKind::Member {
            return None;
        }
        self.contract_input_member(key, module, node, depth)
    }

    /// A contract input's parameter root: a default-free contract
    /// parameter of this scenario checking at its declared type.
    fn contract_input_nameref(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, ResolvedType, Vec<String>)> {
        let Binding::Symbol(parameter) = self.query_binding(key)? else {
            return None;
        };
        let symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param { owner, index, .. } = symbol.kind else {
            return None;
        };
        let scenario = self.effects.scenarios.get(&owner)?;
        let param = scenario.params.get(index)?;
        let ResolvedType::Record {
            symbol: contract, ..
        } = self.types.symbol_types.get(parameter)?
        else {
            return None;
        };
        if symbol.module != module
            || scenario.module != module
            || scenario.read
            || scenario.on.is_some()
            || param.param != *parameter
            || param.default.is_some()
            || key.file != scenario.node.file
            || key.start < scenario.node.start
            || key.end > scenario.node.end
            || self.types.node_types.get(&key) != self.types.symbol_types.get(parameter)
            || !matches!(
                self.resolve.symbols.get(contract.0 as usize)?.kind,
                SymbolKind::Contract { .. }
            )
        {
            return None;
        }
        Some((
            *parameter,
            self.types.symbol_types.get(parameter)?.clone(),
            Vec::new(),
        ))
    }

    /// Extend a contract input path through one member: the base must be
    /// a contract input and the member a primitive or contract/model
    /// reference without required arrays.
    fn contract_input_member(
        &self,
        key: NodeKey,
        module: ModuleId,
        node: &SyntaxNode,
        depth: usize,
    ) -> Option<(SymbolId, ResolvedType, Vec<String>)> {
        let mut operands = node.children.iter().filter(|child| expression(child.kind));
        let base = NodeKey::of(operands.next()?);
        if operands.next().is_some() {
            return None;
        }
        let (parameter, receiver, mut path) =
            self.checked_contract_input_path(base, module, depth + 1)?;
        let ResolvedType::Record {
            symbol: contract, ..
        } = receiver
        else {
            return None;
        };
        let name = self.word(
            node.children
                .iter()
                .rev()
                .find(|child| child.kind == SyntaxKind::Name)?,
        )?;
        let ty = self.types.node_types.get(&key)?;
        let field = self.contract_member(contract, name, ty)?;
        let declaration = self
            .effects
            .records
            .get(&contract)?
            .fields
            .iter()
            .find(|data| data.field == field)?;
        if declaration.required_array
            || !primitive_type(ty)
                && !matches!(ty, ResolvedType::Record {symbol, ..}
                if self.resolve.symbols.get(symbol.0 as usize).is_some_and(|owner|
                    matches!(owner.kind, SymbolKind::Contract { .. } | SymbolKind::Model { .. })))
        {
            return None;
        }
        path.push(name.into());
        Some((parameter, ty.clone(), path))
    }

    fn contract_input_stored_read(&self, read: &DisclosureDependency, module: ModuleId) -> bool {
        let Some(node) = self.nodes.get(&read.node) else {
            return false;
        };
        let Some(base) = node.children.iter().find(|node| expression(node.kind)) else {
            return false;
        };
        read.calls.is_empty()
            && read.query_id.is_none()
            && self
                .checked_contract_input_reference(NodeKey::of(base), module)
                .is_some_and(|(_, model, _)| model == read.model)
    }

    /// Executed operands retain field authority even when the helper result
    /// does not consume their data. `observed` is the original evaluation lane.
    fn require_observed_stored_read(
        &self,
        node: NodeKey,
        calls: &[NodeKey],
        caller: ModuleId,
    ) -> Option<DisclosureDependency> {
        let (base, name) = self.count_member(node)?;
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.node_types.get(&self.query_group(base)?)?
        else {
            return None;
        };
        let model = *model;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        if !matches!(owner.kind, SymbolKind::Model { .. }) {
            return None;
        }
        let ty = self.types.node_types.get(&node)?.clone();
        let field = self
            .effects
            .models
            .get(&model)?
            .fields
            .iter()
            .find_map(|declaration| {
                let field = self.resolve.symbols.get(declaration.field.0 as usize)?;
                (field.name == name
                    && matches!(field.kind,SymbolKind::Field {owner,..} if owner==model)
                    && self.types.symbol_types.get(&field.id) == Some(&ty))
                .then_some(field)
            })?;
        let module = match calls.last() {
            Some(call) => {
                let SelectedCallTarget::DeriveFn(id) = self.types.selected_calls.get(call)?.target
                else {
                    return None;
                };
                self.effects.derives.get(&id)?.module
            }
            None => caller,
        };
        let type_id = match &ty {
            ResolvedType::Record { symbol, .. }
                if self
                    .resolve
                    .symbols
                    .get(symbol.0 as usize)
                    .is_some_and(|declaration| {
                        matches!(declaration.kind, SymbolKind::Contract { .. })
                    }) =>
            {
                self.resolve
                    .symbols
                    .get(symbol.0 as usize)?
                    .canonical
                    .clone()
            }
            _ => self
                .reference_operand_type_id(&ty)
                .or_else(|| self.field_type_id(node, field.id, &ty).ok())?,
        };
        Some(DisclosureDependency {
            query_id: None,
            id: self
                .opaque("read-data", node, &self.call_stamp(calls).ok()?)
                .ok()?,
            source: self.source(module, node).ok()?,
            node,
            calls: calls.to_vec(),
            role: DependencyRole::Data,
            model,
            field: field.id,
            model_name: owner.canonical.clone(),
            field_name: field.name.clone(),
            ty,
            type_id,
        })
    }

    /// Census unsupported helper shapes too: an unproved execution read must
    /// refuse at the existing original-call join, never disappear with pruning.
    fn first_query_stored_require_read(
        &self,
        read: &DisclosureDependency,
        module: ModuleId,
    ) -> bool {
        if read.query_id.is_some() || self.reference_operand_type_id(&read.ty).is_some() {
            return false;
        }
        let Some((mut receiver, field)) = self.count_member(read.node) else {
            return false;
        };
        if field != read.field_name {
            return false;
        }
        for call in read.calls.iter().rev() {
            let Some(selected) = self.types.selected_calls.get(call) else {
                return false;
            };
            let SelectedCallTarget::DeriveFn(id) = selected.target else {
                return false;
            };
            let Some(derive) = self.effects.derives.get(&id) else {
                return false;
            };
            let mut supplied = None;
            for _ in 0..64 {
                let Some(Binding::Symbol(parameter)) = self.query_binding(receiver) else {
                    return false;
                };
                let Some((index, formal)) = derive
                    .params
                    .iter()
                    .enumerate()
                    .find(|(_, formal)| formal.param == *parameter)
                else {
                    return false;
                };
                match selected.slots.get(index) {
                    Some(Some(index)) => {
                        supplied = selected.arguments.get(*index).copied();
                        break;
                    }
                    Some(None) => {
                        let Some(default) = formal.default else {
                            return false;
                        };
                        receiver = default;
                    }
                    None => return false,
                }
            }
            let Some(actual) = supplied else {
                return false;
            };
            receiver = actual;
        }
        let mut pending = vec![receiver];
        let mut steps = 0;
        while let Some(key) = pending.pop() {
            steps += 1;
            if steps > 16384 {
                return false;
            }
            if let Some(Binding::Let { node }) = self.query_binding(key) {
                for scenario in self
                    .effects
                    .scenarios
                    .values()
                    .filter(|scenario| scenario.module == module)
                {
                    let mut statements: Vec<_> = scenario.effects.iter().collect();
                    while let Some(binding) = statements.pop() {
                        statements.extend(binding.then_effects.iter());
                        statements.extend(binding.else_effects.iter());
                        if binding.node == *node {
                            if self
                                .checked_first_query_source(scenario, binding)
                                .is_some_and(|query| query.model == read.model)
                            {
                                return true;
                            }
                            if let Some(value) = binding.value {
                                if value != key {
                                    pending.push(value);
                                }
                            }
                        }
                    }
                }
            }
            if let Some(node) = self.nodes.get(&key) {
                pending.extend(
                    node.children
                        .iter()
                        .filter(|child| expression(child.kind))
                        .map(NodeKey::of),
                );
            }
        }
        false
    }

    /// Original required Model-valued field, used by expression provenance and
    /// the owning schema census. This prepares source facts, never a row view.
    fn checked_required_model_reference(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, SymbolId)> {
        self.checked_required_model_reference_inner(key, module, 0)
    }

    fn checked_required_model_reference_inner(
        &self,
        key: NodeKey,
        module: ModuleId,
        depth: usize,
    ) -> Option<(SymbolId, SymbolId, SymbolId)> {
        if depth >= 16 {
            return None;
        }
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let mut operands = node.children.iter().filter(|child| expression(child.kind));
        let base = self.query_group(NodeKey::of(operands.next()?))?;
        if operands.next().is_some() {
            return None;
        }
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.node_types.get(&base)?
        else {
            return None;
        };
        let original =
            self.required_reference_origin(key, module, base, model, depth)?;
        if !original
            && !self
                .checked_contract_input_reference(base, module)
                .is_some_and(|(_, target, _)| target == *model)
        {
            return None;
        }
        self.required_reference_field(key, node, model)
    }

    /// Whether a member base is an original model reference: a parent
    /// path, a first-query `let`, or a nested required reference.
    fn required_reference_origin(
        &self,
        key: NodeKey,
        module: ModuleId,
        base: NodeKey,
        model: &SymbolId,
        depth: usize,
    ) -> Option<bool> {
        let scenario = self.effects.scenarios.values().find(|scenario| {
            scenario.module == module
                && scenario.node.file == key.file
                && scenario.node.start <= key.start
                && key.end <= scenario.node.end
        })?;
        if scenario.read || (scenario.on.is_some()
            && self.resolve.symbols.get(scenario.scenario.0 as usize)?.canonical != "appointments.remind") {
            return None;
        }
        if scenario.on.is_some()
            && (self.count_member(key).is_none_or(|(_, name)| name != "contact")
                || self.resolve.symbols.get(model.0 as usize)?.canonical != "appointments.Appointment"
                || self.hook_delivery_field(base, module).is_none_or(|(_, field)|
                    self.resolve.symbols.get(field.0 as usize)
                        .is_none_or(|symbol| symbol.name != "appointment")))
        { return None; }
        if scenario.params.iter().any(|parameter|
            self.checked_call_parent_path(base, parameter.param, 0).is_some_and(|(actual, _)| actual == *model)) {
            return Some(true);
        }
        Some(match self.query_binding(base) {
            Some(Binding::Symbol(parameter)) => {
                self.checked_call_parent_path(base, *parameter, 0) == Some((*model, 0))
            }
            Some(Binding::Let { node }) => scenario
                .effects
                .iter()
                .find(|binding| binding.node == *node)
                .and_then(|binding| self.checked_first_query_source(scenario, binding))
                .is_some_and(|query| {
                    query.model == *model && query.first.is_some_and(|first| first.binding == *node)
                }),
            _ => self
                .checked_required_model_reference_inner(base, module, depth + 1)
                .is_some_and(|(_, _, target)| target == *model)
                || self.count_member(key).is_some_and(|(_, name)| name == "contact")
                    && self.types.node_types.get(&key).is_some_and(|ty|
                        matches!(ty, ResolvedType::Record {symbol, stored: true}
                            if self.resolve.symbols.get(symbol.0 as usize)
                                .is_some_and(|target| target.canonical == "customer.Contact")))
                    && self.hook_delivery_field(base, module)
                    .is_some_and(|(_, field)| self.resolve.symbols.get(field.0 as usize)
                        .is_some_and(|symbol| symbol.name == "appointment")
                        && self.types.symbol_types.get(&field) == Some(&ResolvedType::Record {
                            symbol: *model, stored: true,
                        })),
        })
    }

    /// A required model reference's field: an owned stored-model field
    /// of record type checking at both ends without required arrays.
    fn required_reference_field(
        &self,
        key: NodeKey,
        node: &SyntaxNode,
        model: &SymbolId,
    ) -> Option<(SymbolId, SymbolId, SymbolId)> {
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return None;
        };
        let name = self.word(
            node.children
                .iter()
                .rev()
                .find(|child| child.kind == SyntaxKind::Name)?,
        )?;
        let field = fields
            .iter()
            .filter_map(|id| self.resolve.symbols.get(id.0 as usize))
            .find(|field| {
                field.name == name
                    && field.module == owner.module
                    && matches!(field.kind, SymbolKind::Field {owner, ..} if owner == *model)
            })?;
        let ResolvedType::Record {
            symbol: target,
            stored: true,
        } = self.types.symbol_types.get(&field.id)?
        else {
            return None;
        };
        if self.types.node_types.get(&key) != self.types.symbol_types.get(&field.id)
            || !matches!(
                self.resolve.symbols.get(target.0 as usize)?.kind,
                SymbolKind::Model { .. }
            )
            || self
                .effects
                .models
                .get(model)?
                .fields
                .iter()
                .find(|declaration| declaration.field == field.id)?
                .required_array
        {
            return None;
        }
        Some((*model, field.id, *target))
    }

    fn checked_stored_contracts(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedStoredContractSchema>> {
        let result = self.checked_stored_contracts_inner(scenario);
        result
    }

    fn is_contract_symbol(&self, id: SymbolId) -> bool {
        self.resolve
            .symbols
            .get(id.0 as usize)
            .is_some_and(|symbol| matches!(symbol.kind, SymbolKind::Contract { .. }))
    }

    fn stored_contract_param_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        for parameter in &scenario.params {
            // The sealed optional input still owns its actual model schema;
            // null/default paths create no row view or reference observation.
            if let Some(model) = self.nullable_model_input(scenario, parameter) {
                pending.push((model, true));
                continue;
            }
            let Some(ResolvedType::Record { symbol, .. }) =
                self.types.symbol_types.get(&parameter.param)
            else {
                continue;
            };
            if self.is_contract_symbol(*symbol) {
                pending.push((*symbol, false));
            } else if matches!(
                self.resolve.symbols.get(symbol.0 as usize)?.kind,
                SymbolKind::Model { .. }
            ) {
                pending.push((*symbol, true));
                let mut child = *symbol;
                for _ in 0..2 {
                    let SymbolKind::Model {
                        owner: ModelOwner::ChildOf(parent),
                        ..
                    } = self.resolve.symbols.get(child.0 as usize)?.kind
                    else {
                        break;
                    };
                    if self.effects.models.get(&child)?.owner != ModelOwner::ChildOf(parent) {
                        return None;
                    }
                    pending.push((parent, true));
                    child = parent;
                }
            }
        }
        for binding in &scenario.effects {
            if binding.verb == EffectVerb::Let
                && let Some(query) = self.checked_first_query_source(scenario, binding)
            {
                pending.push((query.model, true));
            }
        }
        Some(())
    }

    fn stored_contract_member_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        node: &SyntaxNode,
        pending: &mut Vec<(SymbolId, bool)>,
    ) {
        if node.kind == SyntaxKind::Member
            && let Some((_, target, _)) =
                self.checked_contract_input_reference(NodeKey::of(node), scenario.module)
        {
            pending.push((target, true));
        }
        // Capture only actually authored implicit-parent targets. Required
        // Contract Model leaves are discovered above; the parent proof
        // retains the same original parameter and checked containment.
        if node.kind == SyntaxKind::Member
            && self
                .count_member(NodeKey::of(node))
                .is_some_and(|(_, field)| field == "parent")
        {
            for parameter in &scenario.params {
                if let Some((parent, hops)) =
                    self.checked_call_parent_path(NodeKey::of(node), parameter.param, 0)
                    && hops > 0
                {
                    pending.push((parent, true));
                }
            }
        }
        if node.kind == SyntaxKind::Member
            && let Some((_, _, target)) =
                self.checked_required_model_reference(NodeKey::of(node), scenario.module)
        {
            pending.push((target, true));
        }
        if node.kind == SyntaxKind::Member
            && let Some((_, _, _, profile)) = self
                .checked_scalar_reference(ScalarReferenceKind::Profile, NodeKey::of(node), scenario.module)
                .or_else(|| {
                    self.checked_scalar_reference(ScalarReferenceKind::Run, NodeKey::of(node), scenario.module)
                })
        {
            pending.push((profile, true));
        }
        if node.kind == SyntaxKind::Member
            && let Some((_, _, _, _, target, _)) = self
                .checked_reference_identity_operand(NodeKey::of(node), scenario.module)
                .or_else(|| {
                    self.checked_helper_reference_argument(NodeKey::of(node), scenario.module)
                })
        {
            pending.push((target, true));
        }
    }

    fn stored_contract_expression_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        // Only an actual original stored reference adds its target census.
        // No runtime view is issued.
        let mut expressions: Vec<_> = scenario
            .guards
            .iter()
            .chain(&scenario.effects)
            .filter_map(|statement| self.nodes.get(&statement.node).copied())
            .collect();
        let mut visited = 0usize;
        while let Some(node) = expressions.pop() {
            visited += 1;
            if visited > 16384 {
                return None;
            }
            if node.kind == SyntaxKind::Examples {
                continue;
            }
            self.stored_contract_member_seed(scenario, node, pending);
            expressions.extend(node.children.iter());
        }
        Some(())
    }

    fn stored_contract_decision_domain<'c>(
        &self,
        call: &'c CheckedDecisionCall,
    ) -> Option<Option<(NodeKey, &'c ResolvedType, &'a super::types::CheckedQuery)>> {
        let (domain, domain_type) = call.arguments.get(call.slots.first().copied()??)?;
        if self.nodes.get(domain)?.kind != SyntaxKind::Query {
            return Some(None);
        }
        let query = self.types.checked_queries.get(domain)?;
        Some(Some((*domain, domain_type, query)))
    }

    fn stored_contract_decision_call(
        &self,
        call: &CheckedDecisionCall,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        // A direct checked contained collection also owns its model census.
        // Schema inventory is evidence only and issues no executable query.
        let CheckedDecisionCallTarget::Builtin { ref id, overload } = call.target else {
            return Some(());
        };
        if !matches!(id.as_str(), "any" | "all" | "count" | "first") {
            return Some(());
        }
        let Some((domain, domain_type, query)) = self.stored_contract_decision_domain(call)? else {
            return Some(());
        };
        if self.source_require_value_query(query) {
            if let ResolvedType::Array {element, ..} = &query.domain_type
                && let ResolvedType::Record {symbol, ..} = element.as_ref() {
                pending.push((*symbol, false));
            }
            return Some(());
        }
        let stored = matches!(&query.domain_type, ResolvedType::Array { element, .. }
            if matches!(element.as_ref(), ResolvedType::Record { symbol, stored: true }
                if matches!(self.resolve.symbols.get(symbol.0 as usize).map(|s| &s.kind), Some(SymbolKind::Model {..}))));
        let collection = self.types.checked_collection_calls.get(&call.node);
        if !stored && collection.is_none() {
            return Some(());
        }
        let collection = collection?;
        let model = collection.model;
        let row = ResolvedType::Record {
            symbol: model,
            stored: true,
        };
        let array = ResolvedType::Array {
            element: Box::new(row),
            ordered: true,
            nonempty: false,
        };
        let alias = query
            .clauses
            .iter()
            .find(|clause| clause.node == collection.alias)?;
        let CheckedQueryClauseKind::As { name } = &alias.kind else {
            return None;
        };
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let source = self.source(call.module, call.node).ok()?;
        let query_node = self.nodes.get(&domain)?;
        if !self.stored_contract_collection_shape(
            call,
            id,
            overload,
            collection,
            query,
            domain,
            domain_type,
            &array,
            alias,
            name,
            query_node,
        ) || !self.stored_contract_collection_source(
            call,
            collection,
            domain,
            owner,
            model,
            &source,
        ) {
            return None;
        }
        pending.push((model, true));
        Some(())
    }

    fn stored_contract_collection_shape(
        &self,
        call: &CheckedDecisionCall,
        builtin_id: &String,
        overload: usize,
        collection: &super::types::CheckedCollectionCall,
        query: &super::types::CheckedQuery,
        domain: NodeKey,
        domain_type: &ResolvedType,
        array: &ResolvedType,
        alias: &super::types::CheckedQueryClause,
        name: &String,
        query_node: &SyntaxNode,
    ) -> bool {
        collection.node == call.node
            && collection.builtin == *builtin_id
            && collection.overload == overload
            && collection.query == domain
            && query.node == domain
            && query.domain_type == *array
            && query.result == *array
            && *domain_type == *array
            && self.types.node_types.get(&domain) == Some(array)
            && self.types.node_types.get(&query.domain) == Some(array)
            && alias.expressions.is_empty()
            && !name.is_empty()
            && query.matches_source_nodes(query_node, expression)
    }

    fn stored_contract_collection_source(
        &self,
        call: &CheckedDecisionCall,
        collection: &super::types::CheckedCollectionCall,
        domain: NodeKey,
        owner: &Symbol,
        model: SymbolId,
        source: &DisclosureSource,
    ) -> bool {
        call.source == *source
            && self.source(call.module, domain).ok().as_ref() == Some(source)
            && matches!(owner.kind, SymbolKind::Model { .. })
            && owner.id == model
            && self.checked_created_model(model, owner.module).is_some()
            && call.defaults.is_empty()
            && collection
                .predicate
                .as_ref()
                .map(|predicate| (predicate.node, predicate.ty.clone()))
                == call
                    .slots
                    .get(1)
                    .copied()
                    .flatten()
                    .and_then(|slot| call.arguments.get(slot))
                    .cloned()
    }

    fn stored_contract_query_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        for query in self.checked_count_query_sources(scenario)? {
            pending.push((query.model, true));
            if let Some((_, parameter)) = query.count.as_ref()?.contained_parent
                && let Some(ResolvedType::Record {
                    symbol,
                    stored: true,
                }) = self.types.symbol_types.get(&parameter)
            {
                pending.push((*symbol, true));
            }
            for edge in &query.count.as_ref()?.parent_edges {
                pending.push((edge.child, true));
                pending.push((edge.parent, true));
            }
        }
        for query in self.checked_any_query_sources(scenario)? {
            pending.push((query.model, true));
        }
        for transcript in self
            .checked_transcript_sources(scenario)
            .unwrap_or_default()
        {
            pending.push((transcript.model, true));
        }
        Some(())
    }

    fn stored_contract_send_payload_seed(
        &self,
        node: NodeKey,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        // A typed payload owns its declared Contract schema just
        // as a Contract-valued create field does. Census alone
        // supplies no send, stored-row or read authority.
        let mut payload = vec![node];
        let mut visits = 0usize;
        while let Some(key) = payload.pop() {
            visits += 1;
            if visits > 16384 {
                return None;
            }
            if let Some(ResolvedType::Record { symbol, .. }) =
                self.types.node_types.get(&key)
                && self.is_contract_symbol(*symbol)
            {
                pending.push((*symbol, false));
            }
            payload.extend(self.nodes.get(&key)?.children.iter().map(NodeKey::of));
        }
        Some(())
    }

    fn stored_contract_create_field_seed(
        &self,
        model: SymbolId,
        pending: &mut Vec<(SymbolId, bool)>,
    ) {
        let Some(symbol) = self.resolve.symbols.get(model.0 as usize) else {
            return;
        };
        let SymbolKind::Model { fields, .. } = &symbol.kind else {
            return;
        };
        for field in fields {
            let Some(mut ty) = self.types.symbol_types.get(field) else {
                continue;
            };
            while let ResolvedType::Nullable(inner)
            | ResolvedType::Array { element: inner, .. } = ty
            {
                ty = inner;
            }
            if let ResolvedType::Record { symbol, .. } = ty
                && self.is_contract_symbol(*symbol)
            {
                pending.push((*symbol, false));
            }
        }
    }

    fn stored_contract_create_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        pending: &mut Vec<(SymbolId, bool)>,
    ) -> Option<()> {
        // Created models own their stored schemas: seed each created model
        // and its contract-valued field targets (unwrapping nullable/array
        // exactly like the codegen `referenced` walk) so nominal
        // correspondence can prove them. Seeding is census only and never
        // fails the inventory: every use still proves exact schema, field,
        // type and source correspondence, and a missing entry keeps the
        // existing refusal. Unresolvable creates are skipped here because
        // their own create-source facts already refuse elsewhere.
        let mut work: Vec<(&Effect, usize)> =
            scenario.effects.iter().map(|effect| (effect, 0)).collect();
        let mut steps = 0usize;
        let mut seeded = 0usize;
        while let Some((effect, depth)) = work.pop() {
            steps += 1;
            if steps > 16384 || depth > 64 || seeded > 200 {
                break;
            }
            for arm in effect.match_arms.iter() {
                work.extend(arm.effects.iter().map(|child| (child, depth + 1)));
            }
            work.extend(effect.then_effects.iter().map(|child| (child, depth + 1)));
            work.extend(effect.else_effects.iter().map(|child| (child, depth + 1)));
            if effect.verb == EffectVerb::Send {
                self.stored_contract_send_payload_seed(effect.node, pending)?;
            }
            if effect.verb != EffectVerb::Create {
                continue;
            }
            let Some(EffectTarget::Model(model)) = effect.target else {
                continue;
            };
            seeded += 1;
            pending.push((model, true));
            self.stored_contract_create_field_seed(model, pending);
        }
        Some(())
    }

    fn stored_contract_observer_member(
        &self,
        key: NodeKey,
        node: &SyntaxNode,
        observer_fields: &mut HashSet<(SymbolId, SymbolId)>,
    ) -> Option<()> {
        if node.kind == SyntaxKind::Member
            && let Some(ty @ ResolvedType::Array { .. }) = self.types.node_types.get(&key)
            && self.reference_operand_type_id(ty).is_some()
            && let Some((base, name)) = self.count_member(key)
            && let Some(ResolvedType::Record {symbol: owner, stored: true}) = self.types.node_types.get(&base)
        {
            // A contained `input.Child` collection is query-owned,
            // rather than a stored field in this Member census.
            if let Some(field) = self.effects.models.get(owner)?.fields.iter().find(|field| {
                self.resolve.symbols.get(field.field.0 as usize).is_some_and(|decl| decl.name == name)
            }) {
                if self.types.symbol_types.get(&field.field) != Some(ty) { return None; }
                observer_fields.insert((*owner, field.field));
            }
        }
        Some(())
    }

    fn stored_contract_observer_seed(
        &self,
        scenario: &super::effects::ScenarioData,
        source_requires: &[CheckedDecisionSite],
        observer_fields: &mut HashSet<(SymbolId, SymbolId)>,
    ) -> Option<()> {
        let mut expressions: Vec<_> = source_requires.iter().map(|site| site.node).collect();
        expressions.extend(scenario.effects.iter().map(|effect| effect.node));
        for call in source_requires.iter().flat_map(|site| &site.calls) {
            if let CheckedDecisionCallTarget::DeriveFn(id) = call.target {
                expressions.push(self.effects.derives.get(&id)?.expr?);
            }
        }
        let mut visited = 0usize;
        while let Some(key) = expressions.pop() {
            visited += 1;
            if visited > 16384 { return None; }
            let node = self.nodes.get(&key)?;
            self.stored_contract_observer_member(key, node, observer_fields)?;
            expressions.extend(node.children.iter().map(NodeKey::of));
        }
        Some(())
    }

    fn stored_contract_field_skip(
        &self,
        id: SymbolId,
        model: bool,
        member: &Symbol,
        field: &SymbolId,
        ty: &ResolvedType,
        file_array: bool,
        inline_selections: &[CheckedInlineSelectionSource],
        current_revision: &Option<CurrentRevisionSource>,
        notice_event: bool,
    ) -> bool {
        model
            && !matches!(ty, ResolvedType::Record { symbol, .. } if self.is_contract_symbol(*symbol))
            && !matches!(ty, ResolvedType::Array { element, ordered: true, nonempty: false }
                if matches!(element.as_ref(), ResolvedType::Record { symbol, .. }
                    if self.is_contract_symbol(*symbol))
                    && self.source_require_plain_value(ty, 0))
            && !(notice_event
                && self.resolve.symbols.get(id.0 as usize)
                    .is_some_and(|owner| owner.canonical == "agreements.Term")
                && member.canonical == "agreements.Term.snapshot"
                && matches!(ty, ResolvedType::Nullable(inner)
                    if matches!(inner.as_ref(), ResolvedType::Record {symbol,..}
                        if self.resolve.symbols.get(symbol.0 as usize)
                            .is_some_and(|contract| contract.canonical == "agreements.ExecutedParties"
                                && matches!(contract.kind, SymbolKind::Contract { .. })))))
            && self.reference_operand_type_id(ty).is_none()
            && !result_type(ty)
            // Timezone has its own stored DATA codec, even though a bare
            // timezone is outside the ordinary scalar result profile.
            && *ty != ResolvedType::Scalar(Scalar::Timezone)
            && !file_array
            && !inline_selections
                .iter()
                .any(|fact| id == fact.parent.parent && *field == fact.prefix)
            && !current_revision
                .as_ref()
                .is_some_and(|fact| id == fact.template && *field == fact.field)
    }

    fn stored_contract_contributed_field(
        &self,
        id: SymbolId,
        declaration: &Symbol,
        member: &Symbol,
        field: &SymbolId,
        ty: &ResolvedType,
        fields: &mut Vec<CheckedStoredContractField>,
    ) -> Option<()> {
        let definition = self.checked_created_model(id, declaration.module)?;
        let contributed = definition
            .contributed
            .iter()
            .find(|candidate| candidate.field == *field)?
            .clone();
        if contributed.ty != *ty || !result_type(ty) {
            return None;
        }
        let declared = exact_type_id(ty, self.resolve)?;
        fields.push(CheckedStoredContractField {
            id: *field,
            canonical: member.canonical.clone(),
            name: member.name.clone(),
            owner: id,
            span: member.span,
            source: contributed.source.clone(),
            ty: ty.clone(),
            required_array: false,
            declared,
            constraints: contributed.constraints.clone(),
            trim: contributed.value.trim,
            contributed: Some(contributed),
            reuse: None,
            min: None,
            max: None,
        });
        Some(())
    }

    fn stored_contract_field_checked_data(
        &self,
        id: SymbolId,
        field: &SymbolId,
        declaration_module: ModuleId,
        member_name: &str,
        ty: &ResolvedType,
        file_array: bool,
    ) -> Option<(NodeKey, bool)> {
        let data = self
            .effects
            .models
            .get(&id)
            .and_then(|record| record.fields.iter().find(|data| data.field == *field))
            .or_else(|| {
                self.effects.records.get(&id).and_then(|record| {
                    record.fields.iter().find(|data| data.field == *field)
                })
            })?;
        if !self.checked_created_field_type(data.type_node, declaration_module, ty, 0)
            || !self.checked_created_field(
                self.nodes.get(&data.node)?,
                data,
                member_name,
                ty,
            )
            || (file_array
                && (data.required_array
                    || data.default.is_some()
                    || data.server.is_some()
                    || self.types.field_reuse_sources.contains_key(field)))
        {
            return None;
        }
        Some((data.node, data.required_array))
    }

    fn stored_contract_field_reuse(
        &self,
        field: SymbolId,
    ) -> Option<(
        bool,
        Option<(NodeKey, i64, DisclosureSource)>,
        Option<(NodeKey, i64, DisclosureSource)>,
        Vec<SymbolId>,
    )> {
        let mut trim = false;
        let mut min = None;
        let mut max = None;
        let mut current = field;
        let mut reused = HashSet::new();
        let mut reused_order = Vec::new();
        loop {
            if !reused.insert(current) || reused.len() > 64 {
                return None;
            }
            reused_order.push(current);
            let symbol = self.resolve.symbols.get(current.0 as usize)?;
            let SymbolKind::Field { owner, .. } = &symbol.kind else {
                return None;
            };
            let data = self
                .effects
                .models
                .get(owner)
                .and_then(|record| record.fields.iter().find(|data| data.field == current))
                .or_else(|| {
                    self.effects.records.get(owner).and_then(|record| {
                        record.fields.iter().find(|data| data.field == current)
                    })
                })?;
            for modifier in &data.modifiers {
                if modifier.name == "trim" {
                    trim = true;
                }
                let slot = match modifier.name.as_str() {
                    "min" => &mut min,
                    "max" => &mut max,
                    _ => continue,
                };
                if slot.is_none() {
                    let key = modifier.value?;
                    let text = &self.db.get(key.file)?.text;
                    let value = text
                        .get(key.start as usize..key.end as usize)?
                        .trim()
                        .parse()
                        .ok()?;
                    *slot = Some((key, value, self.source(symbol.module, key).ok()?));
                }
            }
            let Some(next) = self.types.field_reuse_sources.get(&current) else {
                break;
            };
            current = *next;
        }
        Some((trim, min, max, reused_order))
    }

    fn stored_contract_field_push(
        &self,
        id: SymbolId,
        member: &Symbol,
        field: &SymbolId,
        ty: &ResolvedType,
        data_required_array: bool,
        member_source: DisclosureSource,
        trim: bool,
        min: Option<(NodeKey, i64, DisclosureSource)>,
        max: Option<(NodeKey, i64, DisclosureSource)>,
        reused_order: &[SymbolId],
        inline_selections: &[CheckedInlineSelectionSource],
        pending: &mut Vec<(SymbolId, bool)>,
        fields: &mut Vec<CheckedStoredContractField>,
    ) -> Option<()> {
        // Every reused field retains its owning Contract declaration, even
        // when its resolved type is scalar. Construction checks inherited
        // traits against this exact source census; resolved type alone does
        // not identify the provider. This inventory grants no row access.
        for reused_field in reused_order {
            let SymbolKind::Field { owner, .. } =
                self.resolve.symbols.get(reused_field.0 as usize)?.kind
            else {
                return None;
            };
            if self.is_contract_symbol(owner) {
                pending.push((owner, false));
            }
        }
        let constraints = self.types.value_constraints.get(field).cloned();
        let mut declared = if inline_selections
            .iter()
            .any(|fact| id == fact.parent.parent && *field == fact.prefix && *ty == fact.ty)
        {
            "TextMessage[]".into()
        } else {
            checked_stored_contract_type_id(
                ty,
                if self.reference_operand_type_id(ty).is_some() {
                    None
                } else {
                    constraints.as_ref().and_then(|value| value.alias)
                },
                self.resolve,
                0,
            )?
        };
        if data_required_array {
            declared.push('!');
        }
        fields.push(CheckedStoredContractField {
            id: *field,
            canonical: member.canonical.clone(),
            name: member.name.clone(),
            owner: id,
            span: member.span,
            source: member_source,
            ty: ty.clone(),
            required_array: data_required_array,
            declared,
            constraints,
            contributed: None,
            reuse: self.types.field_reuse_sources.get(field).copied(),
            trim,
            min,
            max,
        });
        let mut base = ty;
        let mut depth = 0;
        while let ResolvedType::Nullable(inner)
        | ResolvedType::Array { element: inner, .. } = base
        {
            depth += 1;
            if depth > 64 {
                return None;
            }
            base = inner;
        }
        if let ResolvedType::Record { symbol, .. } = base
            && self.is_contract_symbol(*symbol)
        {
            pending.push((*symbol, false));
            if pending.len() > 4096 {
                return None;
            }
        }
        Some(())
    }

    fn stored_contract_field_array_guarded(
        &self,
        id: SymbolId,
        model: bool,
        field: &SymbolId,
        ty: &ResolvedType,
        helper_query_fields: &HashSet<(SymbolId, SymbolId)>,
        observer_fields: &HashSet<(SymbolId, SymbolId)>,
    ) -> bool {
        model
            && matches!(ty, ResolvedType::Array { .. })
            && self.reference_operand_type_id(ty).is_some()
            && !helper_query_fields.contains(&(id, *field))
            && !observer_fields.contains(&(id, *field))
            && self
                .types
                .field_reuse_sources
                .get(field)
                .is_none_or(|alias| !self.reference_array_source_bounds(*field, *alias))
    }

    fn stored_contract_inventory_field(
        &self,
        id: SymbolId,
        model: bool,
        field: &SymbolId,
        declaration: &Symbol,
        field_count: &mut usize,
        pending: &mut Vec<(SymbolId, bool)>,
        fields: &mut Vec<CheckedStoredContractField>,
        helper_query_fields: &HashSet<(SymbolId, SymbolId)>,
        observer_fields: &HashSet<(SymbolId, SymbolId)>,
        inline_selections: &[CheckedInlineSelectionSource],
        current_revision: &Option<CurrentRevisionSource>,
        notice_event: bool,
    ) -> Option<()> {
        let member = self.resolve.symbols.get(field.0 as usize)?;
        if model
            && matches!(member.kind, SymbolKind::DeriveField { model: owner, .. } if owner == id)
        {
            return Some(());
        }
        let ty = self.types.symbol_types.get(field)?;
        let file_array = matches!(ty, ResolvedType::Array {
            element, ordered: true, nonempty: false,
        } if element.as_ref() == &ResolvedType::Scalar(Scalar::File));
        if self.stored_contract_field_skip(
            id,
            model,
            member,
            field,
            ty,
            file_array,
            inline_selections,
            current_revision,
            notice_event,
        ) {
            return Some(());
        }
        *field_count += 1;
        if *field_count > 4096 {
            return None;
        }
        let SymbolKind::Field { owner, .. } = &member.kind else {
            return None;
        };
        if member.id != *field || *owner != id || member.module != declaration.module {
            return None;
        }
        if model && self.types.given_fields.contains_key(field) {
            self.stored_contract_contributed_field(id, declaration, member, field, ty, fields)?;
            return Some(());
        }
        let (data_node, data_required_array) = self.stored_contract_field_checked_data(
            id,
            field,
            declaration.module,
            &member.name,
            ty,
            file_array,
        )?;
        if self.stored_contract_field_array_guarded(
            id,
            model,
            field,
            ty,
            helper_query_fields,
            observer_fields,
        ) {
            return Some(());
        }
        let member_source = self.source(member.module, data_node).ok()?;
        let (trim, min, max, reused_order) = self.stored_contract_field_reuse(*field)?;
        self.stored_contract_field_push(
            id,
            member,
            field,
            ty,
            data_required_array,
            member_source,
            trim,
            min,
            max,
            &reused_order,
            inline_selections,
            pending,
            fields,
        )
    }

    fn stored_contract_inventory_item(
        &self,
        id: SymbolId,
        model: bool,
        field_count: &mut usize,
        pending: &mut Vec<(SymbolId, bool)>,
        inventory: &mut Vec<CheckedStoredContractSchema>,
        helper_query_fields: &HashSet<(SymbolId, SymbolId)>,
        observer_fields: &HashSet<(SymbolId, SymbolId)>,
        inline_selections: &[CheckedInlineSelectionSource],
        current_revision: &Option<CurrentRevisionSource>,
        notice_event: bool,
    ) -> Option<()> {
        let declaration = self.resolve.symbols.get(id.0 as usize)?;
        let (order, node) = match &declaration.kind {
            SymbolKind::Model { fields, .. } if model => {
                (fields, self.effects.models.get(&id)?.node)
            }
            SymbolKind::Contract { fields } if !model => {
                (fields, self.effects.records.get(&id)?.node)
            }
            _ => return None,
        };
        if declaration.id != id || order.len() > 200 {
            return None;
        }
        let source = self.source(declaration.module, node).ok()?;
        let parent = match declaration.kind {
            SymbolKind::Model {
                owner: super::resolve::ModelOwner::ChildOf(parent),
                ..
            } => Some(parent),
            _ => None,
        };
        let mut fields = Vec::new();
        for field in order {
            self.stored_contract_inventory_field(
                id,
                model,
                field,
                declaration,
                field_count,
                pending,
                &mut fields,
                helper_query_fields,
                observer_fields,
                inline_selections,
                current_revision,
                notice_event,
            )?;
        }
        if !model || !fields.is_empty() || parent.is_some() {
            inventory.push(CheckedStoredContractSchema {
                id,
                canonical: declaration.canonical.clone(),
                module: declaration.module,
                span: declaration.span,
                source,
                model,
                parent,
                owner: match declaration.kind {
                    SymbolKind::Model { owner, .. } => Some(owner),
                    _ => None,
                },
                field_order: order.clone(),
                fields,
            });
        }
        Some(())
    }

    fn checked_stored_contracts_inner(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedStoredContractSchema>> {
        let mut pending = Vec::new();
        let current_revision = self.checked_current_revision_source(scenario);
        let inline_selections = match self.checked_inline_selection_sources(scenario) {
        Some(v) => v,
        None => return None,
        };
        if let Some(fact) = &current_revision {
            pending.push((fact.revision, true));
        }
        self.stored_contract_param_seed(scenario, &mut pending)?;
        if let Some((_, row, _)) = self.hook_delivery_event(scenario) {
            let ResolvedType::Record { symbol: model, stored: true } =
                self.types.symbol_types.get(&row)? else { return None; };
            pending.push((*model, true));
            let hops = if matches!(self.resolve.symbols.get(scenario.scenario.0 as usize)?.canonical.as_str(),
                "agreements.due" | "appointments.remind") { 2 } else { 1 };
            let mut child = *model;
            for _ in 0..hops {
                let SymbolKind::Model { owner: ModelOwner::ChildOf(parent), .. } =
                    self.resolve.symbols.get(child.0 as usize)?.kind else { return None; };
                if self.effects.models.get(&child)?.owner != ModelOwner::ChildOf(parent) {
                    return None;
                }
                pending.push((parent, true));
                child = parent;
            }
        }
        self.stored_contract_expression_seed(scenario, &mut pending)?;
        // Retain the owning Model census of actual helper query calls. These
        // original source facts supply no query execution or reference grant.
        // The call chain keeps caller Require occurrences separate from the
        // query and predicate in their defining helper source.
        for site in self.checked_decision_sites(scenario)? {
            if !matches!(
                site.stage,
                CheckedDecisionStage::LeadingRequire | CheckedDecisionStage::BodyRequire
            ) {
                continue;
            }
            for call in site.calls {
                self.stored_contract_decision_call(&call, &mut pending)?;
            }
        }
        self.stored_contract_query_seed(scenario, &mut pending)?;
        self.stored_contract_create_seed(scenario, &mut pending)?;
        // A helper's lazy CONTROL census needs the exact declared reference
        // array even when it is not a reusable bounded Create operand. This
        // inventory is source evidence; it grants no array read or write.
        let helper_query_fields: HashSet<_> = self
            .checked_helper_any_query_sources(scenario)
            .into_iter()
            .flatten()
            .flat_map(|query| query.dependencies)
            .filter(|read| read.role == DependencyRole::Control)
            .map(|read| (read.model, read.field))
            .collect();
        // Only actual reference-array Member reads of the full observer guard,
        // its checked helper closure, and its body need this extra census.
        // These original fields carry no borrowed Scope bounds or admission.
        let source_requires = self.checked_source_requires(scenario).unwrap_or_default();
        let mut observer_fields = HashSet::new();
        if !source_requires.is_empty() {
            self.stored_contract_observer_seed(scenario, &source_requires, &mut observer_fields)?;
        }
        let mut seen = HashSet::new();
        let mut inventory = Vec::new();
        let mut field_count = 0usize;
        let notice_event = self.hook_delivery_event(scenario).is_some()
            && self.resolve.symbols.get(scenario.scenario.0 as usize)
                .is_some_and(|owner| owner.canonical == "agreements.notice");
        while let Some((id, model)) = pending.pop() {
            if !seen.insert(id) {
                continue;
            }
            if seen.len() > 200 {
                return None;
            }
            self.stored_contract_inventory_item(
                id,
                model,
                &mut field_count,
                &mut pending,
                &mut inventory,
                &helper_query_fields,
                &observer_fields,
                &inline_selections,
                &current_revision,
                notice_event,
            )?;
        }
        Some(inventory)
    }

    /// Prove the finite whole read declaration separately from its source inventory.
    /// Query candidates remain in the query inventory, never scalar observations.
    /// A complete query's scenario shape: a read scenario with two
    /// default-free parameters and established source facts.
    fn complete_query_shape(
        &mut self,
        scenario: &super::effects::ScenarioData,
    ) -> Result<(), DisclosureDecline> {
        let fail = || self.fail(scenario.node, "incomplete finite query declaration");
        if !scenario.read
            || scenario.on.is_some()
            || scenario.scope_authority
            || scenario.cohort.is_some()
            || scenario.params.len() != 2
            || scenario.params.iter().any(|param| param.default.is_some())
            || self.checked_source_facts(scenario).is_none()
        {
            return Err(fail());
        }
        Ok(())
    }

    /// A complete query's inputs: distinct targets/location parameters
    /// covering both params, with the targets array over the model and
    /// owning positive finite bounds.
    fn complete_query_inputs(
        &mut self,
        scenario: &super::effects::ScenarioData,
        query: &DisclosureQuery,
    ) -> Result<(SymbolId, SymbolId, SymbolId), DisclosureDecline> {
        let fail = || self.fail(scenario.node, "incomplete finite query declaration");
        let targets = query.inputs[0].1;
        let location = query.inputs[1].1;
        if targets == location
            || query.inputs[2].1 != targets
            || !scenario
                .params
                .iter()
                .all(|param| param.param == targets || param.param == location)
        {
            return Err(fail());
        }
        let record = ResolvedType::Record {
            symbol: query.model,
            stored: true,
        };
        let Some(ResolvedType::Array {
            element,
            ordered: true,
            nonempty: false,
        }) = self.types.symbol_types.get(&targets)
        else {
            return Err(fail());
        };
        if **element != record {
            return Err(fail());
        }
        // Parameters retain ordinary array omission semantics; the field-only
        // `!` is not borrowed. Exact positive finite bounds still refuse empty
        // inputs through their owning admission contract.
        let alias = self.query_parameter_bounds(targets).ok_or_else(|| {
            self.fail(
                scenario.node,
                "query parameter needs owning positive finite bounds",
            )
        })?;
        Ok((targets, location, alias))
    }

    /// A complete query's result: the location is a stored model and the
    /// scenario returns the projected contract collection.
    fn complete_query_result(
        &self,
        scenario: &super::effects::ScenarioData,
        contract: SymbolId,
        location: SymbolId,
    ) -> Result<(), DisclosureDecline> {
        let fail = || self.fail(scenario.node, "incomplete finite query declaration");
        if !matches!(self.types.symbol_types.get(&location),
            Some(ResolvedType::Record {symbol, stored: true})
            if matches!(self.resolve.symbols.get(symbol.0 as usize).map(|s| &s.kind), Some(SymbolKind::Model {..})))
            || !matches!(self.types.symbol_results.get(&scenario.scenario),
                Some(Some(ResolvedType::Array {element, ordered: true, nonempty: false}))
                if matches!(element.as_ref(), ResolvedType::Record {symbol, ..} if *symbol == contract)
                    && matches!(self.resolve.symbols.get(contract.0 as usize).map(|s| &s.kind), Some(SymbolKind::Contract {..})))
        {
            return Err(fail());
        }
        Ok(())
    }

    /// A complete query's parameters name their owning types: the
    /// targets alias (or its field chain) and the location model.
    fn complete_query_params(
        &self,
        scenario: &super::effects::ScenarioData,
        targets: SymbolId,
        location: SymbolId,
        alias: SymbolId,
    ) -> Result<(), DisclosureDecline> {
        let fail = || self.fail(scenario.node, "incomplete finite query declaration");
        for param in &scenario.params {
            let node = self.nodes.get(&param.type_node).ok_or_else(fail)?;
            if node.kind != SyntaxKind::NamedType {
                return Err(self.fail(
                    param.type_node,
                    "query parameter needs exact owning named type",
                ));
            }
            let mut paths = node
                .children
                .iter()
                .filter(|child| child.kind == SyntaxKind::Path);
            let path = paths.next().ok_or_else(fail)?;
            if paths.next().is_some() {
                return Err(fail());
            }
            let declaration = self.resolve.node_typeref.get(&NodeKey::of(path));
            let owns_type = if param.param == targets {
                matches!(declaration, Some(TypeRef::Symbol(id)) if *id == alias)
                    || matches!(declaration, Some(TypeRef::FieldChain {fields, ..}) if fields.last() == Some(&alias))
            } else {
                matches!((declaration, self.types.symbol_types.get(&location)),
                    (Some(TypeRef::Symbol(id)), Some(ResolvedType::Record {symbol, stored: true})) if id == symbol)
            };
            if !owns_type {
                return Err(self.fail(param.type_node, "query parameter named type correspondence"));
            }
        }
        Ok(())
    }

    /// A complete query's guards: a closed role-gate authorization and
    /// admitted count header guards.
    fn complete_query_guards(
        &mut self,
        scenario: &super::effects::ScenarioData,
        targets: SymbolId,
    ) -> Result<(), DisclosureDecline> {
        let fail = || self.fail(scenario.node, "incomplete finite query declaration");
        let env = scenario
            .params
            .iter()
            .map(|param| (Local::Symbol(param.param), ValuePath::default()))
            .collect();
        let by = scenario.by.ok_or_else(fail)?;
        let authorization = self.authorization_expr(by, scenario.module, &env, &[])?;
        if authorization.iter().any(|path| {
            !path.reads.is_empty() || !path.intrinsics.is_empty() || !path.decisions.is_empty()
        }) {
            return Err(self.fail(by, "query authorization needs a closed role gate"));
        }
        for guard in &scenario.guards {
            let cond = guard
                .cond
                .ok_or_else(|| self.fail(guard.node, "missing query header guard"))?;
            if guard.verb != EffectVerb::Require
                || !guard.then_effects.is_empty()
                || !guard.else_effects.is_empty()
                || !guard.match_arms.is_empty()
                || !self.frozen_query_count_guard(scenario, cond, targets)
            {
                return Err(self.fail(
                    cond,
                    "query header needs original admitted count and literal comparison",
                ));
            }
        }
        Ok(())
    }

    fn complete_query(
        &mut self,
        scenario: &super::effects::ScenarioData,
    ) -> Result<Option<CheckedScenarioDisclosure>, DisclosureDecline> {
        let Some(queries) = self.checked_query_sources(scenario) else {
            return Ok(None);
        };
        let [query] = queries.as_slice() else {
            return Ok(None);
        };
        let Some(projection) = query.projection.as_ref() else {
            return Ok(None);
        };
        self.complete_query_shape(scenario)?;
        let (targets, location, alias) = self.complete_query_inputs(scenario, query)?;
        self.complete_query_result(scenario, projection.contract, location)?;
        self.complete_query_params(scenario, targets, location, alias)?;
        self.complete_query_guards(scenario, targets)?;
        Ok(Some(CheckedScenarioDisclosure {
            source_facts: None,
            scenario: scenario.scenario,
            node: scenario.node,
            source: self.source(scenario.module, scenario.node)?,
            returns: vec![DisclosureReturn {
                id: query.return_id(),
                source: query.source.clone(),
                node: query.return_node,
                decisions: Vec::new(),
                dependencies: Vec::new(),
                intrinsics: Vec::new(),
                influences: query.influences.clone(),
                model_result: None,
            }],
            effects: Vec::new(),
            require_consumptions: Vec::new(),
        }))
    }

    /// Match the checked field-reuse layers used by parameter lowering. Ordinary
    /// authored arrays keep bounds on their declarations, not value_constraints.
    fn query_parameter_bounds(&self, parameter: SymbolId) -> Option<SymbolId> {
        let alias = *self.types.field_reuse_sources.get(&parameter)?;
        let Some(ResolvedType::Array {
            element,
            ordered: true,
            nonempty: false,
        }) = self.types.symbol_types.get(&parameter)
        else {
            return None;
        };
        let chain = self.query_reuse_chain(alias, element)?;
        let (min, max) = self.query_chain_bounds(&chain)?;
        (min >= 1 && min <= max && max <= 200).then_some(alias)
    }

    /// Walk one field-reuse chain through contract-owned array fields of
    /// the same element type.
    fn query_reuse_chain(
        &self,
        alias: SymbolId,
        element: &ResolvedType,
    ) -> Option<Vec<&super::effects::FieldData>> {
        let mut current = alias;
        let mut seen = HashSet::new();
        let mut chain = Vec::new();
        loop {
            if !seen.insert(current) || chain.len() >= 128 {
                return None;
            }
            let SymbolKind::Field { owner, .. } =
                self.resolve.symbols.get(current.0 as usize)?.kind
            else {
                return None;
            };
            if !matches!(self.resolve.symbols.get(owner.0 as usize)?.kind,
                SymbolKind::Contract {ref fields} if fields.contains(&current))
                || !matches!(self.types.symbol_types.get(&current),
                    Some(ResolvedType::Array {element: source, ordered: true, ..}) if source.as_ref() == element)
            {
                return None;
            }
            let field = self
                .effects
                .records
                .get(&owner)?
                .fields
                .iter()
                .find(|field| field.field == current)?;
            chain.push(field);
            let Some(next) = self.types.field_reuse_sources.get(&current) else {
                break;
            };
            current = *next;
        }
        Some(chain)
    }

    /// Fold one reuse chain's `min=`/`max=` literal modifiers to its
    /// exact inherited range.
    fn query_chain_bounds(
        &self,
        chain: &[&super::effects::FieldData],
    ) -> Option<(u64, u64)> {
        let mut min = None;
        let mut max = None;
        for field in chain.iter().rev() {
            for modifier in &field.modifiers {
                let minimum = match modifier.name.as_str() {
                    "min" => true,
                    "max" => false,
                    _ => continue,
                };
                let key = self.query_group(modifier.value?)?;
                if self.nodes.get(&key)?.kind != SyntaxKind::Literal
                    || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Int))
                {
                    return None;
                }
                let value = self
                    .db
                    .get(key.file)?
                    .text
                    .get(key.start as usize..key.end as usize)?
                    .trim()
                    .parse::<u64>()
                    .ok()?;
                let slot = if minimum { &mut min } else { &mut max };
                // Receiving bounds must narrow the exact inherited literal range.
                if slot.is_some_and(|prior| {
                    if minimum {
                        value < prior
                    } else {
                        value > prior
                    }
                }) {
                    return None;
                }
                *slot = Some(value);
            }
        }
        Some((min?, max?))
    }

    fn frozen_query_count_guard(
        &self,
        scenario: &super::effects::ScenarioData,
        key: NodeKey,
        targets: SymbolId,
    ) -> bool {
        if self
            .types
            .node_types
            .get(&self.query_group(key).unwrap_or(key))
            != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return false;
        }
        ["==", "!=", ">", ">=", "<", "<="].iter().any(|operator| {
            let Some((left, right)) = self.query_binary(key, operator) else {
                return false;
            };
            [(left, right), (right, left)]
                .iter()
                .any(|(count, literal)| {
                    let Some(argument) = self.query_count(*count) else {
                        return false;
                    };
                    let Some(literal) = self.query_group(*literal) else {
                        return false;
                    };
                    self.query_parameter(scenario, argument) == Some(targets)
                        && self.types.node_types.get(&argument)
                            == self.types.symbol_types.get(&targets)
                        && self
                            .nodes
                            .get(&literal)
                            .is_some_and(|node| node.kind == SyntaxKind::Literal)
                        && self.types.node_types.get(&literal)
                            == Some(&ResolvedType::Scalar(Scalar::Int))
                        && self
                            .db
                            .get(literal.file)
                            .and_then(|file| {
                                file.text.get(literal.start as usize..literal.end as usize)
                            })
                            .and_then(|text| text.trim().parse::<u16>().ok())
                            .is_some_and(|value| value <= 200)
                })
        })
    }

    /// The currently released query ABI supports a genuine viewer scan and
    /// exact reference/version/scalar contract projection. The finite profile
    /// here is the authored Workbench lineage: admitted target membership,
    /// direct location equality, cardinality guard, then nominal select. It
    /// neither certifies preceding guards nor upgrades native admission.
    fn checked_query_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<DisclosureQuery>> {
        if !scenario.read {
            let mut first = self.checked_count_query_sources(scenario)?;
            first.extend(self.checked_any_query_sources(scenario)?);
            first.extend(self.checked_helper_any_query_sources(scenario)?);
            // Derive-bodied boolean `any` queries share the direct emitter
            // tail, so their facts join the same receipt inventory; the
            // walker verifies each call site by span before admitting it.
            // An unverifiable nested inventory contributes nothing rather
            // than failing the whole query inventory: absent facts keep the
            // pre-existing verdict and still refuse receipt admission.
            first.extend(
                self.checked_nested_any_query_sources(scenario)
                    .unwrap_or_default()
                    .into_iter()
                    .map(|nested| nested.query),
            );
            first.extend(
                self.checked_inline_selection_sources(scenario)?
                    .into_iter()
                    .map(|fact| fact.query),
            );
            for binding in &scenario.effects {
                let Some(value) = binding.value.and_then(|key| self.query_group(key)) else {
                    continue;
                };
                if binding.verb == EffectVerb::Let
                    && matches!(self.types.selected_calls.get(&value).map(|call| &call.target),
                        Some(SelectedCallTarget::Builtin {id,..}) if id == "first")
                {
                    first.push(self.checked_first_query_source(scenario, binding)?);
                    if first.len() > 200 {
                        return None;
                    }
                }
            }
            if !first.is_empty() {
                first.sort_by_key(|query| {
                    let call = query
                        .first
                        .as_ref()
                        .map(|fact| fact.call)
                        .or_else(|| query.count.as_ref().map(|fact| fact.call))
                        .unwrap_or(query.node);
                    (call.start, call.end)
                });
                return Some(first);
            }
        }
        let authored = self.nodes.get(&scenario.node)?;
        let mut pending = vec![*authored];
        let mut query_nodes = Vec::new();
        let mut visits = 0usize;
        while let Some(node) = pending.pop() {
            visits += 1;
            if visits > 16384 {
                return None;
            }
            if node.kind == SyntaxKind::Query {
                query_nodes.push(NodeKey::of(node));
            }
            pending.extend(node.children.iter());
        }
        if query_nodes.is_empty() {
            return Some(Vec::new());
        }
        if !scenario.read
            || scenario.on.is_some()
            || query_nodes.len() != 2
            || scenario.effects.len() != 3
        {
            return None;
        }
        let [binding, guard, returned] = scenario.effects.as_slice() else {
            return None;
        };
        if binding.verb != EffectVerb::Let
            || guard.verb != EffectVerb::Require
            || returned.verb != EffectVerb::Return
            || scenario.effects.iter().any(|effect| {
                !effect.then_effects.is_empty()
                    || !effect.else_effects.is_empty()
                    || !effect.match_arms.is_empty()
            })
        {
            return None;
        }
        let scan_key = binding.value?;
        let select_key = returned.value?;
        let scan = self.types.checked_queries.get(&scan_key)?;
        let select = self.types.checked_queries.get(&select_key)?;
        if scan.node != scan_key
            || select.node != select_key
            || !query_nodes.contains(&scan_key)
            || !query_nodes.contains(&select_key)
            || scan.projection.is_some()
            || scan.clauses.len() != 2
            || select.clauses.len() != 2
        {
            return None;
        }
        let [scan_alias, predicate_clause] = scan.clauses.as_slice() else {
            return None;
        };
        let [select_alias, select_clause] = select.clauses.as_slice() else {
            return None;
        };
        if !matches!(scan_alias.kind, CheckedQueryClauseKind::As { .. })
            || predicate_clause.kind != CheckedQueryClauseKind::Where
            || predicate_clause.expressions.len() != 1
            || !matches!(select_alias.kind, CheckedQueryClauseKind::As { .. })
            || select_clause.kind != CheckedQueryClauseKind::Select
            || select_clause.expressions.len() != 1
        {
            return None;
        }
        let Some(Binding::Symbol(model)) = self.query_binding(scan.domain) else {
            return None;
        };
        let model = *model;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        if !matches!(owner.kind, SymbolKind::Model { .. }) {
            return None;
        }
        let record_ty = ResolvedType::Record {
            symbol: model,
            stored: true,
        };
        if !matches!(&scan.domain_type, ResolvedType::Array { element, ordered: true, nonempty: false } if **element == record_ty)
            || self.types.node_types.get(&scan.domain) != Some(&scan.domain_type)
            || !matches!(&scan.result, ResolvedType::Array { element, ordered: true, .. } if **element == record_ty)
            || select.domain_type != scan.result
            || !matches!(self.query_binding(select.domain), Some(Binding::Let {node}) if *node == binding.node)
        {
            return None;
        }
        let predicate = predicate_clause.expressions[0];
        let conjunction = self.query_binary(predicate, "and")?;
        let membership = self.query_binary(conjunction.0, "in")?;
        if !self.query_row(membership.0, scan_alias.node, model) {
            return None;
        }
        let targets = self.query_parameter(scenario, membership.1)?;
        if !matches!(self.types.symbol_types.get(&targets), Some(ResolvedType::Array {element,..}) if **element == record_ty)
        {
            return None;
        }
        let equality = self.query_binary(conjunction.1, "==")?;
        let location = self.query_parameter(scenario, equality.1)?;
        // The predicate must compare a direct owning record reference field
        // with an admitted nonnullable reference of that same model.
        let field = self.query_member(equality.0, scan_alias.node, model)?;
        let field_ty = self.types.symbol_types.get(&field)?;
        let ResolvedType::Record {
            symbol: location_model,
            stored: true,
        } = self.types.symbol_types.get(&location)?
        else {
            return None;
        };
        let location_ty = ResolvedType::Record {
            symbol: *location_model,
            stored: true,
        };
        if field_ty != &location_ty
            && !matches!(field_ty, ResolvedType::Nullable(inner) if **inner == location_ty)
        {
            return None;
        }
        let cond = guard.cond?;
        let counts = self.query_binary(cond, "==")?;
        let visible_argument = self.query_count(counts.0)?;
        let targets_argument = self.query_count(counts.1)?;
        if !matches!(self.query_binding(visible_argument), Some(Binding::Let {node}) if *node == binding.node)
            || self.query_parameter(scenario, targets_argument) != Some(targets)
            || self.types.node_types.get(&visible_argument) != Some(&scan.result)
        {
            return None;
        }
        let projection = select.projection.as_deref()?;
        if projection.model != model
            || projection.alias != select_alias.node
            || select_clause.expressions[0] != projection.node
            || !matches!(self.types.symbol_results.get(&scenario.scenario)?.as_ref()?,
                ResolvedType::Array {element, nonempty: false, ..}
                if matches!(element.as_ref(), ResolvedType::Record {symbol,..} if *symbol == projection.contract))
            || !matches!(&select.result, ResolvedType::Array {element, ordered: true, ..}
                if **element == ResolvedType::Record {symbol: projection.contract, stored: false})
        {
            return None;
        }
        let contract = self.resolve.symbols.get(projection.contract.0 as usize)?;
        let SymbolKind::Contract { fields } = &contract.kind else {
            return None;
        };
        if fields.len() != projection.fields.len() || fields.len() > 200 {
            return None;
        }
        let id = self.opaque("query", scan_key, "").ok()?;
        let mut dependencies = vec![self.query_dependency(
            equality.0,
            scenario.module,
            model,
            field,
            DependencyRole::Control,
            &id,
        )?];
        let mut references = 0;
        let mut versions = 0;
        let mut seen = HashSet::new();
        for projected in &projection.fields {
            if !fields.contains(&projected.field)
                || !seen.insert(projected.field)
                || !matches!(self.resolve.symbols.get(projected.field.0 as usize)?.kind,
                    SymbolKind::Field {owner,..} if owner == projection.contract)
                || self.types.node_types.get(&projected.node) != Some(&projected.ty)
            {
                return None;
            }
            match projected.mapping {
                CheckedQueryProjectionMapping::StoredReference => {
                    if projected.ty != record_ty
                        || !self.query_row(projected.node, select_alias.node, model)
                    {
                        return None;
                    }
                    references += 1;
                }
                CheckedQueryProjectionMapping::Version => {
                    if projected.ty != ResolvedType::Scalar(Scalar::Int)
                        || !self.query_version(projected.node, select_alias.node, model)
                    {
                        return None;
                    }
                    versions += 1;
                }
                CheckedQueryProjectionMapping::DirectField { field } => {
                    if self.query_member(projected.node, select_alias.node, model) != Some(field)
                        || self.types.symbol_types.get(&field) != Some(&projected.ty)
                    {
                        return None;
                    }
                    dependencies.push(self.query_dependency(
                        projected.node,
                        scenario.module,
                        model,
                        field,
                        DependencyRole::Data,
                        &id,
                    )?);
                }
            }
        }
        if references != 1 || versions != 1 || dependencies.len() > 200 {
            return None;
        }
        let source = self.source(scenario.module, scan_key).ok()?;
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", scan_key, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node: scan_key,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(vec![DisclosureQuery {
            id,
            source,
            node: scan_key,
            domain: scan.domain,
            model,
            model_name: owner.canonical.clone(),
            alias: Some(scan_alias.node),
            predicate: Some(predicate),
            inputs: vec![
                (membership.1, targets),
                (equality.1, location),
                (targets_argument, targets),
            ],
            dependencies,
            order: Vec::new(),
            limit: None,
            archived: false,
            cardinality_guard: Some(guard.node),
            return_node: returned.node,
            projection: Some(DisclosureQueryProjection {
                node: select_key,
                source: self.source(scenario.module, select_key).ok()?,
                contract: projection.contract,
                model,
                alias: projection.alias,
                fields: projection.fields.clone(),
            }),
            first: None,
            count: None,
            influences,
        }])
    }

    /// A `param.parent.field` required reference: one containment hop off
    /// an original scenario parameter, then an ordinary stored-model
    /// record field. Returns the consumer's (source model, field, target)
    /// triple. (The shared required-reference check covers ordinary-field
    /// chains; the containment link is not an ordinary field, so the
    /// helper seals this one-hop shape locally from the same pieces. The
    /// consumer re-verifies the live reference edge before admitting.)
    fn helper_parent_chained_reference(
        &self,
        scenario: &super::effects::ScenarioData,
        argument: NodeKey,
    ) -> Option<(SymbolId, SymbolId, SymbolId)> {
        let argument = self.query_group(argument)?;
        let node = self.nodes.get(&argument)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let (base, _) = self.count_member(argument)?;
        let (param_base, link) = self.count_member(base)?;
        if link != "parent" {
            return None;
        }
        let parameter = self.query_parameter(scenario, param_base)?;
        let ResolvedType::Record { symbol: child, stored: true } =
            self.types.symbol_types.get(&parameter)?
        else {
            return None;
        };
        let (parent, _) = self.call_parent_hop_valid(base, param_base, *child, 0)?;
        let triple = self.required_reference_field(argument, node, &parent)?;
        Some(triple)
    }

    /// Preserve a helper Require's exact root ANY source census.
    /// This records its lazy candidate reads; it admits no query execution.
    fn checked_helper_any_query_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<DisclosureQuery>> {
        if scenario.read || scenario.on.is_some() || self.catalog.is_none() {
            return Some(Vec::new());
        }
        let mut queries = Vec::new();
        let observers = self.checked_source_helper_count_sites(scenario);
        for site in self.checked_decision_sites(scenario)? {
            if observers.iter().any(|original| original.statement == site.statement
                && original.node == site.node && original.source == site.source
                && self.source_require_helper_count_site(scenario, original))
            {
                continue;
            }
            if !matches!(
                site.stage,
                CheckedDecisionStage::LeadingRequire | CheckedDecisionStage::BodyRequire
            ) {
                continue;
            }
            for call in site.calls.iter().filter(|call| call.chain.is_empty()) {
                let CheckedDecisionCallTarget::DeriveFn(derive) = call.target else {
                    continue;
                };
                let data = self.effects.derives.get(&derive)?;
                let body = self.query_group(data.expr?)?;
                let Some(selected) = self.types.selected_calls.get(&body) else {
                    continue;
                };
                if !matches!(&selected.target, SelectedCallTarget::Builtin { id, .. } if id == "any")
                    || data.params.len() != 2
                    || self.types.symbol_types.get(&data.params[0].param)
                        != Some(&ResolvedType::Scalar(Scalar::User))
                {
                    continue;
                }
                if call
                    .slots
                    .get(1)
                    .copied()
                    .flatten()
                    .and_then(|slot| call.arguments.get(slot))
                    .and_then(|(argument, _)| {
                        self.checked_contract_input_reference(*argument, scenario.module)
                            .map(|(_, model, _)| model)
                            .or_else(|| {
                                (site.stage == CheckedDecisionStage::BodyRequire)
                                    .then(|| {
                                        self.checked_required_model_reference(
                                            *argument,
                                            scenario.module,
                                        )
                                    })
                                    .flatten()
                                    .map(|(_, _, model)| model)
                            })
                            .or_else(|| {
                                self.helper_parent_chained_reference(scenario, *argument)
                                    .map(|(_, _, model)| model)
                            })
                    })
                    .is_none()
                {
                    continue;
                }
                queries.push(
                    self.checked_helper_any_query_source(scenario, &site, call, derive, body)?,
                );
                if queries.len() > 200 {
                    return None;
                }
            }
        }
        Some(queries)
    }

    fn checked_helper_any_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        site: &CheckedDecisionSite,
        outer: &CheckedDecisionCall,
        derive: SymbolId,
        body: NodeKey,
    ) -> Option<DisclosureQuery> {
        let data = self.effects.derives.get(&derive)?;
        let declaration = self.resolve.symbols.get(derive.0 as usize)?;
        let [person, location] = data.params.as_slice() else {
            return None;
        };
        let ResolvedType::Record {
            symbol: location_model,
            stored: true,
        } = self.types.symbol_types.get(&location.param)?
        else {
            return None;
        };
        let [Some(actor_slot), Some(location_slot)] = outer.slots.as_slice() else {
            return None;
        };
        if outer.arguments.len() != 2 || actor_slot == location_slot {
            return None;
        }
        let actor = outer.arguments.get(*actor_slot)?;
        let argument = outer.arguments.get(*location_slot)?;
        let (parameter, actual_model) = if let Some((parameter, model, _)) =
            self.checked_contract_input_reference(argument.0, scenario.module)
        {
            (Some(parameter), model)
        } else if let Some((_, _, model)) =
            self.helper_parent_chained_reference(scenario, argument.0)
        {
            // A `param.parent.field` chain seals like a required model
            // reference; the consumer re-verifies the live edge.
            (None, model)
        } else {
            if site.stage != CheckedDecisionStage::BodyRequire {
                return None;
            }
            let (_, _, model) =
                self.checked_required_model_reference(argument.0, scenario.module)?;
            (None, model)
        };
        let location_path = self
            .nodes
            .get(&location.type_node)?
            .children
            .iter()
            .find(|child| child.kind == SyntaxKind::Path)?;
        let selected = self.types.selected_calls.get(&body)?;
        let [domain, predicate] = selected.arguments.as_slice() else {
            return None;
        };
        let checked = self.types.checked_queries.get(domain)?;
        let collection = self.types.checked_collection_calls.get(&body)?;
        let [alias] = checked.clauses.as_slice() else {
            return None;
        };
        let CheckedQueryClauseKind::As { name } = &alias.kind else {
            return None;
        };
        let model = self.resolve.symbols.get(collection.model.0 as usize)?;
        let array = ResolvedType::Array {
            element: Box::new(ResolvedType::Record {
                symbol: model.id,
                stored: true,
            }),
            ordered: true,
            nonempty: false,
        };
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let source = self.source(data.module, body).ok()?;
        let frame = CheckedDecisionCallFrame {
            node: outer.node,
            module: scenario.module,
            source: outer.source.clone(),
            derive,
        };
        let nested = site.calls.iter().find(|call| {
            call.node == body && call.chain.as_slice() == std::slice::from_ref(&frame)
        })?;
        let call_node = self.nodes.get(&outer.node)?;
        let head = call_node
            .children
            .iter()
            .find(|child| expression(child.kind))?;
        let binding = self
            .resolve
            .module_scopes
            .get(scenario.module.0 as usize)?
            .prod
            .get(self.word(head)?)?;
        let matches_owner = match binding {
            ScopedName::Local(target) => *target == derive && declaration.module == scenario.module,
            ScopedName::Imported {
                target,
                bound: false,
            } => *target == derive && declaration.exported && declaration.module != scenario.module,
            _ => false,
        };
        let query_node = self.nodes.get(domain)?;
        let alias_words: Vec<_> = self
            .nodes
            .get(&alias.node)?
            .children
            .iter()
            .filter(|child| child.kind == SyntaxKind::Name)
            .map(|child| self.word(child))
            .collect::<Option<Vec<_>>>()?;
        if !matches_owner
            || declaration.module != data.module
            || data.derive != derive
            || !matches!(&declaration.kind, SymbolKind::DeriveFn { params, .. } if params.as_slice() == [person.param, location.param])
            || data.params.iter().any(|formal| formal.default.is_some())
            || self
                .db
                .get(person.type_node.file)?
                .text
                .get(person.type_node.start as usize..person.type_node.end as usize)?
                .trim()
                != "user"
            || !matches!(self.resolve.node_typeref.get(&NodeKey::of(location_path)), Some(TypeRef::Symbol(target)) if target == location_model)
            || actual_model != *location_model
            || argument.1
                != (ResolvedType::Record {
                    symbol: *location_model,
                    stored: true,
                })
            || actor.1 != ResolvedType::Scalar(Scalar::User)
            || !matches!(
                self.query_binding(actor.0),
                Some(Binding::Context(ContextVar::Actor(_)))
            )
            || outer.module != scenario.module
            || outer.source != site.source
            || !outer.defaults.is_empty()
            || selected.slots.as_slice() != [Some(0), Some(1)]
            || collection.node != body
            || collection.builtin != "any"
            || collection.query != *domain
            || collection.model != model.id
            || nested.target
                != (CheckedDecisionCallTarget::Builtin {
                    id: "any".into(),
                    overload: collection.overload,
                })
            || nested.arguments != vec![(*domain, array.clone()), (*predicate, boolean.clone())]
            || nested.source != source
            || nested.module != data.module
            || !nested.defaults.is_empty()
            || nested.slots.as_slice() != [Some(0), Some(1)]
            || !checked.matches_source_nodes(query_node, expression)
            || alias_words != ["as", name.as_str()]
            || self.types.symbol_results.get(&derive) != Some(&Some(boolean.clone()))
            || checked.node != *domain
            || checked.domain_type != array
            || checked.result != array
            || checked.projection.is_some()
            || alias.node != collection.alias
            || !alias.expressions.is_empty()
            || name.is_empty()
            || collection
                .predicate
                .as_ref()
                .is_none_or(|value| value.node != *predicate || value.ty != boolean)
            || !matches!(self.query_binding(checked.domain), Some(Binding::Symbol(target)) if *target == model.id)
            || !matches!(
                model.kind,
                SymbolKind::Model {
                    owner: ModelOwner::Team | ModelOwner::App,
                    ..
                }
            )
            || self.types.node_types.get(&body) != Some(&boolean)
            || self.types.node_types.get(predicate) != Some(&boolean)
        {
            return None;
        }
        self.checked_created_model(model.id, model.module)?;
        self.checked_created_model(
            *location_model,
            self.resolve.symbols.get(location_model.0 as usize)?.module,
        )?;
        for (index, formal) in data.params.iter().enumerate() {
            if !matches!(self.resolve.symbols.get(formal.param.0 as usize)?.kind,
                SymbolKind::Param { owner, index: position, type_node } if owner == derive && position == index && type_node == formal.type_node)
            {
                return None;
            }
        }
        let mut eager = self.query_group(*predicate)?;
        for _ in 0..64 {
            let next = self
                .query_binary(eager, "and")
                .or_else(|| self.query_binary(eager, "or"));
            match next {
                Some((left, _)) => eager = self.query_group(left)?,
                None => break,
            }
        }
        let (left, right) = self.query_binary(eager, "==")?;
        let (first_read, compared) = if self.query_member(left, alias.node, model.id).is_some() {
            (left, right)
        } else {
            (right, left)
        };
        let first_field = self.query_member(first_read, alias.node, model.id)?;
        if self.types.symbol_types.get(&first_field) != Some(&ResolvedType::Scalar(Scalar::User))
            || !matches!(self.query_binding(self.query_group(compared)?), Some(Binding::Symbol(target)) if *target == person.param)
        {
            return None;
        }
        let id = self
            .opaque("query", *domain, &self.key_stamp(outer.node).ok()?)
            .ok()?;
        let mut dependencies = Vec::new();
        let mut pending = vec![*self.nodes.get(predicate)?];
        let mut visits = 0;
        while let Some(node) = pending.pop() {
            visits += 1;
            if visits > 16384 {
                return None;
            }
            if node.kind == SyntaxKind::Member {
                let key = NodeKey::of(node);
                let field = self.query_member(key, alias.node, model.id)?;
                if self.types.node_types.get(&key) != self.types.symbol_types.get(&field) {
                    return None;
                }
                let mut read = self.query_dependency(
                    key,
                    data.module,
                    model.id,
                    field,
                    DependencyRole::Control,
                    &id,
                )?;
                read.calls.push(outer.node);
                dependencies.push(read);
            }
            pending.extend(node.children.iter().rev());
        }
        let first_read = self.query_group(first_read)?;
        if dependencies
            .first()
            .is_none_or(|read| read.node != first_read || read.field != first_field)
        {
            return None;
        }
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", *domain, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node: *domain,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(DisclosureQuery {
            id,
            source,
            node: *domain,
            domain: checked.domain,
            model: model.id,
            model_name: model.canonical.clone(),
            alias: Some(alias.node),
            predicate: Some(*predicate),
            inputs: parameter
                .map(|parameter| vec![(argument.0, parameter)])
                .unwrap_or_default(),
            dependencies,
            order: Vec::new(),
            limit: None,
            archived: false,
            cardinality_guard: None,
            return_node: scenario.effects.last()?.node,
            projection: None,
            first: None,
            count: None,
            influences,
        })
    }

    /// The original leading unfinished-Run check has an external predicate.
    /// Its candidate reads stay query-owned, never a fabricated where clause
    /// or one parent decision shared across repeated candidate evaluations.
    fn checked_any_query_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<DisclosureQuery>> {
        if scenario.read || scenario.on.is_some() || self.catalog.is_none() {
            return Some(Vec::new());
        }
        let mut queries = Vec::new();
        let mut visits = 0usize;
        // A retained-reference FIRST is composed with independently sealed
        // whole leading observers. Their exact ANY occurrences execute in
        // those original observers, rather than a duplicate query frame.
        let reference_first=scenario.effects.iter().filter(|effect|effect.verb==EffectVerb::Let)
            .any(|effect|self.checked_first_query_source(scenario,effect).is_some_and(|query|
                query.first.as_ref().is_some_and(|first|first.reference_predicate.is_some())));
        let observers=if reference_first{self.checked_source_requires(scenario)?}else{Vec::new()};
        for guard in &scenario.guards {
            if observers.iter().any(|site|site.stage==CheckedDecisionStage::LeadingRequire && site.statement==guard.node){continue;}
            let mut pending = vec![*self.nodes.get(&guard.node)?];
            while let Some(node) = pending.pop() {
                visits += 1;
                if visits > 16384 {
                    return None;
                }
                pending.extend(node.children.iter().rev());
                if node.kind != SyntaxKind::Call {
                    continue;
                }
                let call = NodeKey::of(node);
                let Some(selected) = self.types.selected_calls.get(&call) else {
                    continue;
                };
                if !matches!(&selected.target,SelectedCallTarget::Builtin {id,..} if id=="any") {
                    continue;
                }
                let domain = *selected.arguments.get(selected.slots.first().copied()??)?;
                let domain = self.query_group(domain)?;
                // Supplied value arrays retain their existing pure closure.
                // This finite inventory is solely a true stored model query.
                if self.nodes.get(&domain)?.kind != SyntaxKind::Query
                    || !matches!(self.types.node_types.get(&domain),
                        Some(ResolvedType::Array {element,..})
                        if matches!(element.as_ref(),ResolvedType::Record {stored:true,..}))
                {
                    continue;
                }
                if let Some(query) = self.checked_any_query_source(scenario, guard, call) {
                    queries.push(query);
                }
                if queries.len() > 1 {
                    return None;
                }
            }
        }
        Some(queries)
    }

    fn any_query_guard_cursor(
        &self,
        condition: NodeKey,
        call: NodeKey,
    ) -> Option<Option<&'a SyntaxNode>> {
        // A bare `any(...)` guard is the positive dual of the negated
        // composition: the condition itself carries the call, with no
        // `not` wrapper to descend through. (`query_group` sees through
        // parentheses only, so a negated guard never takes this arm.)
        if self.query_group(condition)? == call {
            return Some(None);
        }
        // A leading guard may conjoin several Requirements with `and`;
        // descend to the conjunct carrying this call. Anything else (`or`,
        // double negation) keeps the established refusal below:
        // the guard holds only if every conjunct holds, so the isolated
        // `not any(...)` conjunct is proven on its own.
        let mut cursor = condition;
        loop {
            let grouped = self.query_group(cursor)?;
            if grouped == call {
                return None;
            }
            let node = self.nodes.get(&grouped)?;
            if node.kind == SyntaxKind::Unary {
                return Some(Some(*node));
            }
            let (left, right) = self.query_binary(grouped, "and")?;
            let contains = |key: NodeKey| {
                key.file == call.file && key.start <= call.start && call.end <= key.end
            };
            if contains(right) {
                cursor = right;
            } else if contains(left) {
                cursor = left;
            } else {
                return None;
            }
        }
    }

    fn any_query_call_shape(
        &self,
        call: NodeKey,
    ) -> Option<(&'a SyntaxNode, &'a SyntaxNode, Vec<NodeKey>)> {
        let call_node = self.nodes.get(&call)?;
        let target = call_node
            .children
            .iter()
            .find(|part| expression(part.kind))?;
        let arguments: Vec<_> = call_node
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Argument)
            .map(|part| {
                let mut values = part.children.iter().filter(|value| expression(value.kind));
                let value = NodeKey::of(values.next()?);
                values.next().is_none().then_some(value)
            })
            .collect::<Option<Vec<_>>>()?;
        Some((*call_node, target, arguments))
    }

    fn any_query_signature_shape(
        &self,
        builtin: &String,
        catalog: &Catalog,
        signature: &super::catalog::SigOverload,
        domain_input: &super::catalog::SigParam,
        predicate_input: &super::catalog::SigParam,
        selected: &super::types::SelectedCall,
        call: NodeKey,
        predicate: &NodeKey,
        condition: NodeKey,
        boolean: &ResolvedType,
    ) -> Option<()> {
        if builtin != "any"
            || catalog.effects(builtin) != Some(Effects::Pure)
            || domain_input.name != "domain"
            || domain_input.ty != SigType::Collection(Box::new(SigType::Any))
            || domain_input.alias.is_none()
            || domain_input.in_scope.is_some()
            || predicate_input.name != "predicate"
            || predicate_input.ty != SigType::Named("bool".into())
            || predicate_input.alias.is_some()
            || predicate_input.in_scope != domain_input.alias
            || signature.result != SigType::Named("bool".into())
            || selected.slots.as_slice() != [Some(0), Some(1)]
            || self.types.node_types.get(&call) != Some(boolean)
            || self.types.node_types.get(predicate) != Some(boolean)
            || self.types.node_types.get(&condition) != Some(boolean)
        {
            return None;
        }
        Some(())
    }

    fn any_query_call_shape_ok(
        &self,
        guard: &Effect,
        condition: NodeKey,
        unary: Option<&SyntaxNode>,
        unary_words: &[&str],
        unary_values: &[NodeKey],
        call: NodeKey,
        call_node: &SyntaxNode,
        arguments: &[NodeKey],
        selected_arguments: &[NodeKey],
        target: &SyntaxNode,
    ) -> Option<()> {
        if {
            let hit = guard.verb != EffectVerb::Require;
            hit
        }
            || self.nodes.get(&guard.node)?.kind != SyntaxKind::Require
            || call_node.kind != SyntaxKind::Call
            || arguments != selected_arguments
            || target.kind != SyntaxKind::NameRef
            || self.word(target)? != "any"
            || !matches!(self.query_binding(NodeKey::of(target)),Some(Binding::Builtin {id}) if id=="any")
        {
            return None;
        }
        match unary {
            Some(unary) => {
                if unary.kind != SyntaxKind::Unary
                    || unary_words != ["not"]
                    || unary_values.len() != 1
                    || self.query_group(unary_values[0])? != call
                {
                    return None;
                }
            }
            // Positive dual: no wrapper exists, so no wrapper words or
            // values may travel; the guard condition itself carries the
            // exact original call.
            None => {
                if !unary_words.is_empty()
                    || !unary_values.is_empty()
                    || self.query_group(condition)? != call
                {
                    return None;
                }
            }
        }
        Some(())
    }

    fn any_query_scope_shape_ok(
        &self,
        scenario: &super::effects::ScenarioData,
        guard: &Effect,
        call: NodeKey,
        by: NodeKey,
    ) -> Option<()> {
        if scenario.read
            || scenario.on.is_some()
            || scenario.cohort.is_some()
            || {
                let binding = self.query_binding(by);
                let is_role = match &binding {
                    Some(Binding::Symbol(id)) => self.resolve.symbols.get(id.0 as usize).is_some_and(|symbol| matches!(symbol.kind, SymbolKind::Role)),
                    _ => false,
                };
                !(matches!(&binding, Some(Binding::Predicate)) || is_role)
            }
            || {
                // The census is a model inventory, not a membership proof:
                // the observer bridge proves the actual membership
                // separately. Genuine declared roles gate exactly like the
                // built-in predicates; anything else keeps its refusal.
                let text = self.db
                    .get(by.file)?
                    .text
                    .get(by.start as usize..by.end as usize)?
                    .trim();
                !(matches!(text, "members" | "authenticated")
                    || matches!(self.query_binding(by), Some(Binding::Symbol(id))
                        if self.resolve.symbols.get(id.0 as usize).is_some_and(|symbol| matches!(symbol.kind, SymbolKind::Role))))
            }
            || guard.node.file != scenario.node.file
            || call.file != guard.node.file
            || guard.node.start < scenario.node.start
            || guard.node.end > scenario.node.end
            || call.start < guard.node.start
            || call.end > guard.node.end
        {
            return None;
        }
        Some(())
    }

    /// A derive formal in scope resolves exactly like the scenario
    /// parameter its outer-call argument spells: the sealed lineage
    /// crosses one derive boundary unchanged.
    fn query_parameter_scoped(
        &self,
        scenario: &super::effects::ScenarioData,
        key: NodeKey,
        scope: Option<&NestedAnyScope>,
    ) -> Option<SymbolId> {
        if let Some(parameter) = self.query_parameter(scenario, key) {
            return Some(parameter);
        }
        let scope = scope?;
        let Some(Binding::Symbol(formal)) = self.query_binding(key) else {
            return None;
        };
        let parameter = scope
            .formals
            .iter()
            .find_map(|(candidate, _, mapped)| (*candidate == *formal).then_some(*mapped))??;
        scenario
            .params
            .iter()
            .find(|param| param.param == parameter && param.default.is_none())?;
        Some(parameter)
    }

    /// A scoped formal name: the formal must belong to the scope's derive.
    fn nested_scope_formal(&self, scope: &NestedAnyScope, formal: SymbolId) -> Option<String> {
        scope.formals.iter().find(|(candidate, _, _)| *candidate == formal)?;
        let symbol = self.resolve.symbols.get(formal.0 as usize)?;
        match symbol.kind {
            SymbolKind::Param { owner, .. } if owner == scope.derive => Some(symbol.name.clone()),
            _ => None,
        }
    }

    /// The scoped original-parameter checks: the existing scenario checks,
    /// plus a formal mapped to the same scenario parameter through the
    /// nested scope. A copied lexical value still acquires nothing.
    fn scoped_reference_parameter(
        &self,
        key: NodeKey,
        parameter: SymbolId,
        scope: Option<&NestedAnyScope>,
    ) -> bool {
        self.original_reference_parameter(key, parameter)
            || scope.is_some_and(|scope| {
                matches!(self.query_binding(key), Some(Binding::Symbol(id))
                    if scope.formals.iter().any(|(formal, _, mapped)| formal == id && *mapped == Some(parameter)))
            })
    }

    /// The scoped one-hop containment navigation off the original
    /// parameter, through either a scenario parameter or a mapped formal.
    fn scoped_navigation_parameter(
        &self,
        key: NodeKey,
        parameter: SymbolId,
        scope: Option<&NestedAnyScope>,
    ) -> bool {
        self.original_navigation_parameter(key, parameter)
            || {
                let Some(scope) = scope else {
                    return false;
                };
                let Some((base, field)) = self.count_member(key) else {
                    return false;
                };
                field == "parent" && self.scoped_reference_parameter(base, parameter, Some(scope))
            }
    }

    fn any_query_domain_owner<'s>(
        &'s self,
        scenario: &super::effects::ScenarioData,
        supplied: NodeKey,
        call: NodeKey,
        scope: Option<&NestedAnyScope>,
    ) -> Option<(
        NodeKey,
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedCollectionCall,
        &'a super::types::CheckedQueryClause,
        &'a String,
        SymbolId,
        &'s Symbol,
        NodeKey,
        &'s str,
        SymbolId,
    )> {
        let node = self.query_group(supplied)?;
        let query = self.types.checked_queries.get(&node)?;
        let fact = self.types.checked_collection_calls.get(&call)?;
        let [alias] = query.clauses.as_slice() else {
            return None;
        };
        let CheckedQueryClauseKind::As { name } = &alias.kind else {
            return None;
        };
        let model = fact.model;
        let owner = self.checked_count_model(model, scenario.module)?;
        let (receiver, collection) = self.count_member(query.domain)?;
        // Direct `p.C`: the receiver is the parameter itself. Navigation
        // `i.parent.C`: the receiver is the one-hop containment link off
        // a default-free stored-record parameter (mirrors the admitted
        // first-query domain owner: base must bind the scenario parameter
        // through the `parent` link; the path helper below seals lineage).
        // A nested scope additionally admits a derive formal mapped to its
        // original scenario parameter through the outer call argument.
        let parameter = match self.query_parameter_scoped(scenario, receiver, scope) {
            Some(parameter) => parameter,
            None => {
                let (base, field) = self.count_member(receiver)?;
                if field != "parent" {
                    return None;
                }
                self.query_parameter_scoped(scenario, base, scope)?
            }
        };
        Some((
            node, query, fact, alias, name, model, owner, receiver, collection, parameter,
        ))
    }

    fn any_query_domain_parameter<'t>(
        &self,
        scenario: &'t super::effects::ScenarioData,
        receiver: NodeKey,
        parameter: SymbolId,
        model: SymbolId,
        scope: Option<&NestedAnyScope>,
    ) -> Option<(
        SymbolId,
        u8,
        SymbolId,
        &'a Symbol,
        NodeKey,
        &'t super::effects::ParamData,
        ResolvedType,
    )> {
        // A nested receiver spells exactly `formal.parent`: the base binds
        // a scoped formal mapped to this scenario parameter, and the
        // parent model follows the same one-hop containment validation as
        // a direct receiver (the formal's model is contained in it, and
        // the receiver carries the parent type).
        let (parent, hops) = match scope {
            Some(scope) => {
                let (base, field) = self.count_member(receiver)?;
                if field != "parent" {
                    return None;
                }
                let Some(Binding::Symbol(formal)) = self.query_binding(base) else {
                    return None;
                };
                if !scope
                    .formals
                    .iter()
                    .any(|(candidate, _, mapped)| *candidate == *formal && *mapped == Some(parameter))
                {
                    return None;
                }
                self.nested_scope_formal(scope, *formal)?;
                let formal_ty = self.types.symbol_types.get(formal)?.clone();
                let ResolvedType::Record { symbol: child, stored: true } = &formal_ty else {
                    return None;
                };
                let declaration = self.resolve.symbols.get(child.0 as usize)?;
                let SymbolKind::Model {
                    owner: ModelOwner::ChildOf(parent),
                    fields,
                    ..
                } = &declaration.kind
                else {
                    return None;
                };
                let expected = ResolvedType::Record {
                    symbol: *parent,
                    stored: true,
                };
                if fields.iter().any(|field| {
                    self.resolve
                        .symbols
                        .get(field.0 as usize)
                        .is_none_or(|field| field.name == "parent")
                }) || self.effects.models.get(child)?.owner != ModelOwner::ChildOf(*parent)
                    || self.types.node_types.get(&receiver) != Some(&expected)
                    || self.types.node_types.get(&base) != Some(&formal_ty)
                {
                    return None;
                }
                (*parent, 1)
            }
            None => self.checked_call_parent_path(receiver, parameter, 0)?,
        };
        self.checked_count_model(parent, scenario.module)?;
        let parameter_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param {
            owner: parameter_owner,
            index,
            type_node,
        } = parameter_symbol.kind
        else {
            return None;
        };
        let parameter_data = scenario.params.get(index)?;
        let array = ResolvedType::Array {
            element: Box::new(ResolvedType::Record {
                symbol: model,
                stored: true,
            }),
            ordered: true,
            nonempty: false,
        };
        Some((
            parent,
            hops,
            parameter_owner,
            parameter_symbol,
            type_node,
            parameter_data,
            array,
        ))
    }

    fn any_query_operand_class(
        &self,
        scenario: &super::effects::ScenarioData,
        operand: NodeKey,
        field_ty: &ResolvedType,
    ) -> Option<(bool, bool, bool)> {
        let case_operand = matches!(field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())
            && self.types.resolved_cases.contains(&operand);
        let actor_operand = matches!(
            self.query_binding(operand),
            Some(Binding::Context(ContextVar::Actor(_)))
        ) && *field_ty == ResolvedType::Scalar(Scalar::User)
            && self.word(self.nodes.get(&operand)?)? == "actor";
        let member_operand = if case_operand || actor_operand {
            false
        } else {
            self.query_member_operand(scenario, operand)
                .filter(|(_, operand_field, _)| {
                    self.types.symbol_types.get(operand_field) == Some(field_ty)
                })
                .is_some()
        };
        Some((case_operand, actor_operand, member_operand))
    }

    fn any_query_equality_conjunct(
        &self,
        scenario: &super::effects::ScenarioData,
        conjunct: NodeKey,
        member: NodeKey,
        operand: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
        operator: &str,
    ) -> Option<(NodeKey, SymbolId)> {
        // `==` and `!=` share the sealed control shape: a deterministic
        // boolean control over the same member and operand reads.
        if !matches!(operator, "==" | "!=") {
            return None;
        }
        let field = self.query_member(member, alias_node, model)
            .or_else(|| self.query_derived_member(member, alias_node, model))?;
        let field_ty = self.types.symbol_types.get(&field)?.clone();
        let operand = self.query_group(operand)?;
        // A null comparison constrains a nullable field; the member read
        // stays the recorded control either way.
        if self.types.node_types.get(&operand) == Some(&ResolvedType::Null) {
            let leaf = match &field_ty {
                ResolvedType::Nullable(inner) => inner.as_ref(),
                _ => return None,
            };
            if !(primitive_type(leaf)
                || matches!(leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                || self.types.node_types.get(&self.query_group(member)?) != Some(&field_ty)
                || self.types.node_types.get(&conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
            {
                return None;
            }
            return Some((member, field));
        }
        // Nullability only shapes runtime semantics (null never equals);
        // the recorded control is the same member read either way, so both
        // sides compare by their unwrapped leaf.
        let field_leaf = match &field_ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        let operand_ty = self.types.node_types.get(&operand)?.clone();
        let operand_leaf = match &operand_ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        let (case_operand, actor_operand, member_operand) =
            self.any_query_operand_class(scenario, operand, &field_ty)?;
        // Stored-record comparison is the same sealed control shape as a
        // scalar one: the member ref read is recorded, and reference
        // identity touches no further row.
        if !(primitive_type(field_leaf)
            || matches!(field_leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty())
            || matches!(field_leaf, ResolvedType::Record { stored: true, .. }))
            || self.types.node_types.get(&self.query_group(member)?) != Some(&field_ty)
            || (!case_operand
                && !actor_operand
                && !member_operand
                && self.nodes.get(&operand)?.kind != SyntaxKind::NameRef)
            || operand_leaf != field_leaf
            || self.types.node_types.get(&conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some((member, field))
    }

    /// A sealed outer-call argument for one nested formal: an original
    /// required scenario parameter reference, or a sealed non-parameter
    /// value (literal, enum case, or `now`). Anything else is unsealed.
    fn nested_sealed_argument(
        &self,
        scenario: &super::effects::ScenarioData,
        argument: NodeKey,
    ) -> Option<Option<SymbolId>> {
        let grouped = self.query_group(argument)?;
        let node = self.nodes.get(&grouped)?;
        if node.kind == SyntaxKind::Literal || self.types.resolved_cases.contains(&grouped) {
            return Some(None);
        }
        if let Some(Binding::Symbol(parameter)) = self.query_binding(grouped) {
            if scenario
                .params
                .iter()
                .any(|param| param.param == *parameter && param.default.is_none())
            {
                return Some(Some(*parameter));
            }
            return None;
        }
        if matches!(
            self.query_binding(grouped),
            Some(Binding::Context(ContextVar::Now))
        ) {
            return Some(None);
        }
        None
    }

    /// A bare alias row compared to a sealed record operand
    /// (`booking!=skip`): row iteration is authorized by the domain owner,
    /// so the comparison records no extra field read.
    #[allow(clippy::too_many_arguments)]
    fn any_query_row_identity_conjunct(
        &self,
        scenario: &super::effects::ScenarioData,
        conjunct: NodeKey,
        left: NodeKey,
        right: NodeKey,
        operator: &str,
        alias_node: NodeKey,
        model: SymbolId,
        scope: Option<&NestedAnyScope>,
    ) -> Option<()> {
        if !matches!(operator, "==" | "!=") {
            return None;
        }
        let left = self.query_group(left)?;
        let right = self.query_group(right)?;
        let operand = if self.query_row(left, alias_node, model) {
            right
        } else if self.query_row(right, alias_node, model) {
            left
        } else {
            return None;
        };
        // The operand is a sealed record reference: a scenario parameter
        // or a scoped formal standing in for one, with the model record
        // type (nullable when the formal is optional).
        let operand_ty = self.types.node_types.get(&operand)?.clone();
        let record_ok = match &operand_ty {
            ResolvedType::Record { symbol, stored: true } => *symbol == model,
            ResolvedType::Nullable(inner) => matches!(
                inner.as_ref(),
                ResolvedType::Record { symbol, stored: true } if *symbol == model
            ),
            _ => false,
        };
        if !record_ok
            || self.types.node_types.get(&conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        match self.query_binding(operand) {
            Some(Binding::Symbol(parameter)) if scenario.params.iter().any(|param| {
                param.param == *parameter && param.default.is_none()
            }) => Some(()),
            Some(Binding::Symbol(formal)) if scope.is_some_and(|scope| {
                self.nested_scope_formal(scope, *formal).is_some()
                    && scope.formals.iter().any(|(candidate, _, _)| candidate == formal)
            }) => Some(()),
            _ => None,
        }
    }

    /// A pure `overlaps` interval call over datetime operands: alias-rooted
    /// member arguments become control dependencies, every other argument
    /// must be a sealed operand (scenario parameter, scoped formal,
    /// literal, enum case, or `now`).
    fn any_query_overlaps_conjunct(
        &self,
        scenario: &super::effects::ScenarioData,
        conjunct: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
        scope: Option<&NestedAnyScope>,
    ) -> Option<Vec<(NodeKey, SymbolId)>> {
        let grouped = self.query_group(conjunct)?;
        if self.nodes.get(&grouped)?.kind != SyntaxKind::Call {
            return None;
        }
        let selected = self.types.selected_calls.get(&grouped)?;
        let SelectedCallTarget::Builtin { id, .. } = &selected.target else {
            return None;
        };
        if id != "overlaps"
            || self.catalog?.effects("overlaps") != Some(Effects::Pure)
            || selected.arguments.len() != 4
            || self.types.node_types.get(&grouped) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.node_types.get(&conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let mut members = Vec::new();
        for argument in &selected.arguments {
            let argument = self.query_group(*argument)?;
            if let Some(field) = self
                .query_member(argument, alias_node, model)
                .or_else(|| self.query_derived_member(argument, alias_node, model))
            {
                let field_ty = self.types.symbol_types.get(&field)?.clone();
                let leaf = match &field_ty {
                    ResolvedType::Nullable(inner) => inner.as_ref(),
                    ty => ty,
                };
                // The read may carry a narrowed (non-null) type from an
                // earlier null check; the recorded control is the same
                // field read either way, so both sides compare by leaf.
                let arg_leaf = match self.types.node_types.get(&argument)? {
                    ResolvedType::Nullable(inner) => inner.as_ref(),
                    ty => ty,
                };
                if !matches!(
                    leaf,
                    ResolvedType::Scalar(Scalar::Date | Scalar::Datetime)
                ) || arg_leaf != leaf
                {
                    return None;
                }
                members.push((argument, field));
                continue;
            }
            // A sealed operand: scenario parameter, scoped formal, literal,
            // enum case, or `now`, carrying a date or datetime value.
            let sealed = match self.query_binding(argument) {
                Some(Binding::Symbol(parameter))
                    if scenario
                        .params
                        .iter()
                        .any(|param| param.param == *parameter && param.default.is_none()) =>
                {
                    true
                }
                Some(Binding::Symbol(formal))
                    if scope.is_some_and(|scope| {
                        self.nested_scope_formal(scope, *formal).is_some()
                    }) =>
                {
                    true
                }
                _ => {
                    self.nodes.get(&argument).is_some_and(|node| {
                        node.kind == SyntaxKind::Literal
                    }) || self.types.resolved_cases.contains(&argument)
                        || matches!(
                            self.query_binding(argument),
                            Some(Binding::Context(ContextVar::Now))
                        )
                }
            };
            let arg_ty = self.types.node_types.get(&argument)?;
            let leaf = match arg_ty {
                ResolvedType::Nullable(inner) => inner.as_ref(),
                ty => ty,
            };
            if !sealed
                || !matches!(
                    leaf,
                    ResolvedType::Scalar(Scalar::Date | Scalar::Datetime)
                ) || self.types.node_types.get(&conjunct) != Some(&boolean)
            {
                return None;
            }
        }
        Some(members)
    }

    fn any_query_membership_conjunct(
        &self,
        conjunct: NodeKey,
        member: NodeKey,
        array: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
    ) -> Option<(NodeKey, SymbolId)> {
        // Literal array membership over a stored or derived row
        // member (`i.state in [failed]`). The array contributes only
        // checked literal scalar/enum alternatives; the leaf type
        // pins every alternative, mirroring the source observer.
        let field = match self.query_member(member, alias_node, model)
            .or_else(|| self.query_derived_member(member, alias_node, model)) {
            Some(field) => field,
            None => return None,
        };
        let field_ty = match self.types.symbol_types.get(&field) {
            Some(ty) => ty.clone(),
            None => return None,
        };
        let leaf = match &field_ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        if !(primitive_type(leaf)
            || matches!(leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
        {
            return None;
        }
        if self.types.node_types.get(&self.query_group(member)?) != Some(&field_ty) {
            return None;
        }
        let array_node = match self.nodes.get(&self.query_group(array)?) {
            Some(node) => node,
            None => return None,
        };
        if array_node.kind != SyntaxKind::Array {
            return None;
        }
        let mut has_alternative = false;
        for child in array_node.children.iter().filter(|child| expression(child.kind)) {
            let element = self.query_group(NodeKey::of(child))?;
            let literal = match &leaf {
                ResolvedType::Enum { .. } => self.types.resolved_cases.contains(&element),
                _ => self.nodes.get(&element).is_some_and(|node| node.kind == SyntaxKind::Literal),
            };
            if !literal {
                return None;
            }
            has_alternative = true;
        }
        if !has_alternative
            || self.types.node_types.get(&conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some((member, field))
    }

    fn any_query_fact_shape_ok(
        &self,
        call: NodeKey,
        fact: &super::types::CheckedCollectionCall,
        overload: usize,
        node: NodeKey,
        alias: &super::types::CheckedQueryClause,
        predicate: NodeKey,
        boolean: &ResolvedType,
        authored: &SyntaxNode,
        query: &super::types::CheckedQuery,
        array: &ResolvedType,
        supplied: NodeKey,
        alias_words: &[&str],
        name: &String,
        owner: &Symbol,
        collection: &str,
        hops: u8,
    ) -> Option<()> {
        if fact.node != call
            || fact.builtin != "any"
            || fact.overload != overload
            || fact.query != node
            || fact.alias != alias.node
            || fact
                .predicate
                .as_ref()
                .is_none_or(|actual| actual.node != predicate || actual.ty != *boolean)
            || authored.kind != SyntaxKind::Query
            || query.node != node
            || query.projection.is_some()
            || query.domain_type != *array
            || query.result != *array
            || self.types.node_types.get(&node) != Some(array)
            || self.types.node_types.get(&supplied) != Some(array)
            || self.types.node_types.get(&query.domain) != Some(array)
            || !query.matches_source_nodes(authored, expression)
            || !alias.expressions.is_empty()
            || alias_words != ["as", name.as_str()]
            || collection != owner.name
            || hops > 1
        {
            return None;
        }
        Some(())
    }

    fn any_query_receiver_spelling_scoped(
        &self,
        receiver: NodeKey,
        hops: u8,
        parameter_symbol: &Symbol,
        scope: Option<&NestedAnyScope>,
    ) -> Option<()> {
        // Direct receiver spells exactly the parameter name.
        // A navigated `param.parent` receiver spells exactly the
        // parameter base plus the sealed single-hop containment
        // link (structural lineage is proven by
        // original_navigation_parameter above).
        if self.word(self.nodes.get(&receiver)?)? == parameter_symbol.name {
            return Some(());
        }
        let (base, field) = self.count_member(receiver)?;
        if hops != 1 || field != "parent" {
            return None;
        }
        // A nested receiver spells the mapped formal, not the scenario
        // parameter: the lineage proof above already ties the formal to
        // this parameter through the outer call argument.
        if let Some(scope) = scope {
            let Some(Binding::Symbol(formal)) = self.query_binding(base) else {
                return None;
            };
            let name = self.nested_scope_formal(scope, *formal)?;
            return (self.word(self.nodes.get(&base)?)? == name).then_some(());
        }
        if self.word(self.nodes.get(&base)?)? != parameter_symbol.name {
            return None;
        }
        Some(())
    }

    fn any_query_fact_owner_ok(
        &self,
        scenario: &super::effects::ScenarioData,
        receiver: NodeKey,
        parameter: SymbolId,
        parent: SymbolId,
        collection: &str,
        owner: &Symbol,
        model: SymbolId,
        parameter_owner: SymbolId,
        parameter_symbol: &Symbol,
        parameter_data: &super::effects::ParamData,
        type_node: NodeKey,
        hops: u8,
        scope: Option<&NestedAnyScope>,
    ) -> Option<()> {
        if !(self.scoped_reference_parameter(receiver, parameter, scope)
            || self.scoped_navigation_parameter(receiver, parameter, scope))
            || self.model_has_field(parent, collection)
            || !matches!(owner.kind,SymbolKind::Model {owner:ModelOwner::ChildOf(actual),..} if actual==parent)
            || self.effects.models.get(&model)?.owner != ModelOwner::ChildOf(parent)
            || parameter_owner != scenario.scenario
            || parameter_symbol.module != scenario.module
            || parameter_symbol.id != parameter
            || parameter_data.param != parameter
            || parameter_data.type_node != type_node
            || parameter_data.default.is_some()
        {
            return None;
        }
        self.any_query_receiver_spelling_scoped(receiver, hops, parameter_symbol, scope)
    }

    fn any_query_call_site(
        &self,
        scenario: &super::effects::ScenarioData,
        guard: &Effect,
        condition: NodeKey,
        node: NodeKey,
        call: NodeKey,
        supplied: NodeKey,
        predicate: NodeKey,
        array: &ResolvedType,
        boolean: &ResolvedType,
        selected_slots: &[Option<usize>],
        overload: usize,
    ) -> Option<(DisclosureSource, CheckedDecisionCall)> {
        let source = self.source(scenario.module, node).ok()?;
        let sites = self.checked_decision_sites(scenario)?;
        let mut matching = sites.iter().filter(|site| {
            site.owner == scenario.scenario
                && site.statement == guard.node
                && site.node == condition
                && site.stage == CheckedDecisionStage::LeadingRequire
                && site.source == source
        });
        let site = matching.next()?;
        let mut original_calls = site.calls.iter().filter(|original| original.node == call);
        let original = original_calls.next()?;
        if matching.next().is_some()
            || original_calls.next().is_some()
            || original.module != scenario.module
            || original.source != source
            || original.target
                != (CheckedDecisionCallTarget::Builtin {
                    id: "any".into(),
                    overload,
                })
            || original.arguments != vec![(supplied, array.clone()), (predicate, boolean.clone())]
            || original.slots != selected_slots
            || !original.defaults.is_empty()
            || !original.chain.is_empty()
        {
            return None;
        }
        Some((source, original.clone()))
    }

    fn any_query_emit_stage<'s, 't>(
        &'s self,
        scenario: &'t super::effects::ScenarioData,
        guard: &Effect,
        condition: NodeKey,
        call: NodeKey,
        overload: usize,
        supplied: NodeKey,
        predicate: NodeKey,
        boolean: &ResolvedType,
        node: NodeKey,
        query: &'a super::types::CheckedQuery,
        fact: &'a super::types::CheckedCollectionCall,
        alias: &'a super::types::CheckedQueryClause,
        name: &'a String,
        model: SymbolId,
        owner: &'a Symbol,
        receiver: NodeKey,
        collection: &'s str,
        parameter: SymbolId,
        parent: SymbolId,
        hops: u8,
        parameter_owner: SymbolId,
        parameter_symbol: &'a Symbol,
        type_node: NodeKey,
        parameter_data: &'t super::effects::ParamData,
        array: &ResolvedType,
        authored: &'a SyntaxNode,
        alias_words: &[&str],
        members: &[(NodeKey, SymbolId)],
        selected_slots: &[Option<usize>],
        scope: Option<&NestedAnyScope>,
    ) -> Option<DisclosureQuery> {
        self.any_query_fact_shape_ok(
            call, fact, overload, node, alias, predicate, boolean, authored, query,
            array, supplied, alias_words, name, owner, collection, hops,
        )?;
        self.any_query_fact_owner_ok(
            scenario,
            receiver,
            parameter,
            parent,
            collection,
            owner,
            model,
            parameter_owner,
            parameter_symbol,
            parameter_data,
            type_node,
            hops,
            scope,
        )?;
        let (source, _original) = self.any_query_call_site(
            scenario,
            guard,
            condition,
            node,
            call,
            supplied,
            predicate,
            array,
            boolean,
            selected_slots,
            overload,
        )?;
        let returned = scenario.effects.last()?;
        // Value-bearing tails anchor the query on their explicit return
        // (the long-standing admitted shape). Void effect tails anchor on
        // the final effect itself, mirroring the helper-any owner; the
        // collector still proves the scenario's own return/effect
        // correspondence downstream.
        let return_node = returned.node;
        self.any_query_emit_tail(
            source,
            node,
            query.domain,
            model,
            owner.canonical.clone(),
            alias.node,
            predicate,
            vec![(receiver, parameter)],
            members,
            return_node,
            scenario.module,
            &[],
        )
    }

    /// The shared query-record tail: member control dependencies, the four
    /// query influences, and the disclosure record. Nested queries record
    /// their control reads in the derive's module and stamp the outer
    /// invocation chain onto each read.
    #[allow(clippy::too_many_arguments)]
    fn any_query_emit_tail(
        &self,
        source: DisclosureSource,
        node: NodeKey,
        domain: NodeKey,
        model: SymbolId,
        model_name: String,
        alias_node: NodeKey,
        predicate: NodeKey,
        inputs: Vec<(NodeKey, SymbolId)>,
        members: &[(NodeKey, SymbolId)],
        return_node: NodeKey,
        dep_module: ModuleId,
        dep_calls: &[NodeKey],
    ) -> Option<DisclosureQuery> {
        let id = self.opaque("query", node, "").ok()?;
        let mut dependencies = Vec::new();
        for (member, field) in members {
            let mut read = self
                .query_dependency(
                    *member,
                    dep_module,
                    model,
                    *field,
                    DependencyRole::Control,
                    &id,
                )
                .or_else(|| {
                    self.query_derived_dependency(
                        *member,
                        dep_module,
                        model,
                        *field,
                        DependencyRole::Control,
                        &id,
                    )
                })?;
            for call in dep_calls {
                read.calls.push(*call);
            }
            dependencies.push(read);
        }
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", node, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(DisclosureQuery {
            id,
            source,
            node,
            domain,
            model,
            model_name,
            alias: Some(alias_node),
            predicate: Some(predicate),
            inputs,
            dependencies,
            order: Vec::new(),
            limit: None,
            archived: false,
            cardinality_guard: None,
            return_node,
            projection: None,
            first: None,
            count: None,
            influences,
        })
    }

    /// Decompose only authored `and` nodes, preserving left-to-right leaf
    /// occurrences. Each profile keeps its original frontier bound; leaf
    /// qualification and source/type/owner checks remain with that profile.
    fn query_conjuncts(&self, predicate: NodeKey, max_parts: Option<usize>) -> Option<Vec<NodeKey>> {
        let mut pending = vec![predicate];
        let mut conjuncts = Vec::new();
        while let Some(node) = pending.pop() {
            if let Some((left, right)) = self.query_binary(node, "and") {
                pending.push(right);
                pending.push(left);
            } else {
                conjuncts.push(node);
            }
            if max_parts.is_some_and(|bound| conjuncts.len() + pending.len() > bound) {
                return None;
            }
        }
        (!conjuncts.is_empty()).then_some(conjuncts)
    }

    /// One `any` predicate's member control reads: the flattened `and`
    /// conjuncts, each either a `member == operand` / `member != operand`
    /// comparison (null included), a bare-alias row comparison against a
    /// sealed record (no extra field read), a literal-array membership, a
    /// pure `overlaps` interval call, or a bare bool member read.
    fn any_query_conjunct_members(
        &self,
        scenario: &super::effects::ScenarioData,
        predicate_node: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
        boolean: &ResolvedType,
        scope: Option<&NestedAnyScope>,
    ) -> Option<Vec<(NodeKey, SymbolId)>> {
        let conjuncts = self.query_conjuncts(predicate_node, None)?;
        let mut members: Vec<(NodeKey, SymbolId)> = Vec::new();
        for conjunct in &conjuncts {
            if let Some((member, operand, operator)) = self
                .query_binary(*conjunct, "==")
                .map(|(member, operand)| (member, operand, "=="))
                .or_else(|| {
                    self.query_binary(*conjunct, "!=")
                        .map(|(member, operand)| (member, operand, "!="))
                })
            {
                if self
                    .query_member(member, alias_node, model)
                    .or_else(|| self.query_derived_member(member, alias_node, model))
                    .is_some()
                {
                    let (member, field) = self.any_query_equality_conjunct(
                        scenario,
                        *conjunct,
                        member,
                        operand,
                        alias_node,
                        model,
                        operator,
                    )?;
                    members.push((member, field));
                } else if self
                    .any_query_row_identity_conjunct(
                        scenario,
                        *conjunct,
                        member,
                        operand,
                        operator,
                        alias_node,
                        model,
                        scope,
                    )
                    .is_some()
                {
                    // Row iteration is authorized by the domain owner;
                    // no extra field read travels with the comparison.
                } else {
                    return None;
                }
            } else if let Some((member, array)) = self.query_binary(*conjunct, "in") {
                let (member, field) = self.any_query_membership_conjunct(
                    *conjunct,
                    member,
                    array,
                    alias_node,
                    model,
                )?;
                members.push((member, field));
            } else if self
                .nodes
                .get(conjunct)
                .is_some_and(|node| node.kind == SyntaxKind::Call)
            {
                for (member, field) in self.any_query_overlaps_conjunct(
                    scenario,
                    *conjunct,
                    alias_node,
                    model,
                    scope,
                )? {
                    members.push((member, field));
                }
            } else {
                let field = self.query_member(*conjunct, alias_node, model)?;
                if self.types.symbol_types.get(&field) != Some(boolean)
                    || self.types.node_types.get(conjunct)
                        != Some(&ResolvedType::Scalar(Scalar::Bool))
                {
                    return None;
                }
                members.push((*conjunct, field));
            }
        }
        Some(members)
    }

    fn any_query_domain_stage(
        &self,
        scenario: &super::effects::ScenarioData,
        guard: &Effect,
        condition: NodeKey,
        call: NodeKey,
        overload: usize,
        supplied: NodeKey,
        predicate: NodeKey,
        boolean: &ResolvedType,
        selected_slots: &[Option<usize>],
        scope: Option<&NestedAnyScope>,
    ) -> Option<DisclosureQuery> {
        let (node, query, fact, alias, name, model, owner, receiver, collection, parameter) =
            self.any_query_domain_owner(scenario, supplied, call, scope)?;
        let (parent, hops, parameter_owner, parameter_symbol, type_node, parameter_data, array) =
            self.any_query_domain_parameter(scenario, receiver, parameter, model, scope)?;
        let authored = self.nodes.get(&node)?;
        let alias_words: Vec<_> = self
            .nodes
            .get(&alias.node)?
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Name)
            .map(|part| self.word(part))
            .collect::<Option<Vec<_>>>()?;
        let predicate_node = self.query_group(predicate)?;
        // An any predicate is one bool conjunct or an `and` chain of them,
        // flattened order-preserving (mirrors the admitted first-query
        // where owner). Each conjunct shape is handled in the members
        // helper; the former single `unfinished` profile is the
        // one-conjunct bare case.
        let members = self.any_query_conjunct_members(
            scenario,
            predicate_node,
            alias.node,
            model,
            boolean,
            scope,
        )?;
        self.any_query_emit_stage(
            scenario,
            guard,
            condition,
            call,
            overload,
            supplied,
            predicate,
            boolean,
            node,
            query,
            fact,
            alias,
            name,
            model,
            owner,
            receiver,
            collection,
            parameter,
            parent,
            hops,
            parameter_owner,
            parameter_symbol,
            type_node,
            parameter_data,
            &array,
            authored,
            &alias_words,
            &members,
            selected_slots,
            scope,
        )
    }

    fn checked_any_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        guard: &Effect,
        call: NodeKey,
    ) -> Option<DisclosureQuery> {
        let selected = self.types.selected_calls.get(&call)?;
        let SelectedCallTarget::Builtin {
            id: builtin,
            overload,
        } = &selected.target
        else {
            return None;
        };
        let [supplied, predicate] = selected.arguments.as_slice() else {
            return None;
        };
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let catalog = self.catalog?;
        let signature = catalog.overloads(builtin)?.get(*overload)?;
        let [domain_input, predicate_input] = signature.params.as_slice() else {
            return None;
        };
        let condition = guard.cond?;
        // The outer refusal stays whole; the inner layer is the `not`
        // wrapper when present and absent for the positive dual, whose
        // guard condition carries the call itself.
        let unary = self.any_query_guard_cursor(condition, call)?;
        let (unary_node, unary_words, unary_values) = match unary {
            Some(unary) => (
                Some(unary),
                unary
                    .children
                    .iter()
                    .filter(|part| matches!(part.kind, SyntaxKind::Name | SyntaxKind::Punct))
                    .map(|part| self.word(part))
                    .collect::<Option<Vec<_>>>()?,
                unary
                    .children
                    .iter()
                    .filter(|part| expression(part.kind))
                    .map(NodeKey::of)
                    .collect(),
            ),
            None => (None, Vec::new(), Vec::new()),
        };
        let (call_node, target, arguments) = self.any_query_call_shape(call)?;
        let by = scenario.by?;
        self.any_query_signature_shape(
            builtin,
            catalog,
            signature,
            domain_input,
            predicate_input,
            selected,
            call,
            predicate,
            condition,
            &boolean,
        )?;
        self.any_query_call_shape_ok(
            guard,
            condition,
            unary_node,
            &unary_words,
            &unary_values,
            call,
            call_node,
            &arguments,
            selected.arguments.as_slice(),
            target,
        )?;
        self.any_query_scope_shape_ok(scenario, guard, call, by)?;
        self.any_query_domain_stage(
            scenario,
            guard,
            condition,
            call,
            *overload,
            *supplied,
            *predicate,
            &boolean,
            selected.slots.as_slice(),
            None,
        )
    }

    /// One derive-nested `any` inventory: every `any` builtin call inside a
    /// derive body invoked from a Require guard, with its outer call chain.
    /// This records the nested query's lazy candidate reads; it admits no
    /// query execution by itself (the evaluator consumer re-verifies the
    /// live formal lineage before short-circuiting).
    fn checked_nested_any_query_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<NestedAnyQuery>> {
        if scenario.read || scenario.on.is_some() || self.catalog.is_none() {
            return Some(Vec::new());
        }
        let mut queries = Vec::new();
        let sites = self.checked_decision_sites(scenario);
        for site in sites? {
            if site.owner != scenario.scenario
                || !matches!(
                    site.stage,
                    CheckedDecisionStage::LeadingRequire | CheckedDecisionStage::BodyRequire
                )
            {
                continue;
            }
            let Some(guard) = scenario
                .guards
                .iter()
                .find(|guard| guard.node == site.statement)
            else {
                continue;
            };
            if guard.verb != EffectVerb::Require {
                continue;
            }
            for outer in site.calls.iter().filter(|call| call.chain.is_empty()) {
                let CheckedDecisionCallTarget::DeriveFn(derive) = outer.target else {
                    continue;
                };
                let frame = CheckedDecisionCallFrame {
                    node: outer.node,
                    module: scenario.module,
                    source: outer.source.clone(),
                    derive,
                };
                for nested in site.calls.iter().filter(|call| {
                    matches!(
                        &call.target,
                        CheckedDecisionCallTarget::Builtin { id, .. } if id == "any"
                    ) && call.chain.as_slice() == std::slice::from_ref(&frame)
                }) {
                    // One unsealed shape skips; it must not starve the
                    // other derives' admissions (the evaluator still
                    // refuses the skipped call through its own path).
                    if let Some(query) = self.checked_nested_any_query_source(
                        scenario, site.source.clone(), guard, outer, derive, nested,
                    ) {
                        queries.push(query);
                    }
                    if queries.len() > 200 {
                        return None;
                    }
                }
            }
        }
        Some(queries)
    }

    /// One nested `any` admission: the outer derive call resolves in the
    /// scenario module, every formal seals to an outer argument, and the
    /// nested query passes the shared sealed stages with a scope threading
    /// each formal back to its original scenario parameter.
    #[allow(clippy::too_many_arguments)]
    fn checked_nested_any_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        site_source: DisclosureSource,
        guard: &super::effects::Effect,
        outer: &CheckedDecisionCall,
        derive: SymbolId,
        nested: &CheckedDecisionCall,
    ) -> Option<NestedAnyQuery> {
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let data = self.effects.derives.get(&derive)?;
        let declaration = self.resolve.symbols.get(derive.0 as usize)?;
        let expected: Vec<SymbolId> = data.params.iter().map(|formal| formal.param).collect();
        if declaration.module != data.module
            || data.derive != derive
            || !matches!(&declaration.kind, SymbolKind::DeriveFn { params, .. } if params.as_slice() == expected.as_slice())
            || data.params.iter().any(|formal| formal.default.is_some())
            || self.types.symbol_results.get(&derive) != Some(&Some(boolean.clone()))
        {
            return None;
        }
        let body = self.query_group(data.expr?)?;
        if self.types.node_types.get(&body) != Some(&boolean)
            || nested.module != data.module
            || nested.node.file != body.file
            || nested.node.start < body.start
            || nested.node.end > body.end
            || outer.module != scenario.module
            || outer.source != site_source
            || !outer.defaults.is_empty()
            || outer.slots.len() != data.params.len()
            || outer.arguments.len() != data.params.len()
        {
            return None;
        }
        // Every formal seals to its outer argument: an original required
        // scenario parameter reference, or a sealed non-parameter value.
        // A stricter-than-needed whole-derive seal keeps unreferenced
        // formals from smuggling arbitrary values into the query closure.
        let mut formals = Vec::new();
        for (formal, slot) in data.params.iter().zip(&outer.slots) {
            let argument = outer.arguments.get((*slot)?)?.0;
            formals.push((formal.param, argument, self.nested_sealed_argument(scenario, argument)?));
        }
        let scope = NestedAnyScope { derive, formals };
        let call_node = self.nodes.get(&outer.node)?;
        let head = call_node.children.iter().find(|child| expression(child.kind))?;
        let binding = self
            .resolve
            .module_scopes
            .get(scenario.module.0 as usize)?
            .prod
            .get(self.word(head)?)?;
        match binding {
            ScopedName::Local(target)
                if *target == derive && declaration.module == scenario.module => {}
            ScopedName::Imported { target, bound: false }
                if *target == derive && declaration.exported && declaration.module != scenario.module => {}
            _ => return None,
        }
        let selected = self.types.selected_calls.get(&nested.node)?;
        let SelectedCallTarget::Builtin { id: builtin, overload } = &selected.target else {
            return None;
        };
        if builtin != "any" {
            return None;
        }
        let [supplied, predicate] = selected.arguments.as_slice() else {
            return None;
        };
        let catalog = self.catalog?;
        let signature = catalog.overloads(builtin)?.get(*overload)?;
        let [domain_input, predicate_input] = signature.params.as_slice() else {
            return None;
        };
        let condition = body;
        let unary = self.any_query_guard_cursor(condition, nested.node)?;
        let (unary_node, unary_words, unary_values) = match unary {
            Some(unary) => (
                Some(unary),
                unary
                    .children
                    .iter()
                    .filter(|part| matches!(part.kind, SyntaxKind::Name | SyntaxKind::Punct))
                    .map(|part| self.word(part))
                    .collect::<Option<Vec<_>>>()?,
                unary
                    .children
                    .iter()
                    .filter(|part| expression(part.kind))
                    .map(NodeKey::of)
                    .collect(),
            ),
            None => (None, Vec::new(), Vec::new()),
        };
        let (nested_node, target, arguments) = self.any_query_call_shape(nested.node)?;
        let by = scenario.by?;
        self.any_query_signature_shape(
            builtin,
            catalog,
            signature,
            domain_input,
            predicate_input,
            selected,
            nested.node,
            predicate,
            condition,
            &boolean,
        )?;
        self.any_query_call_shape_ok(
            guard,
            condition,
            unary_node,
            &unary_words,
            &unary_values,
            nested.node,
            nested_node,
            &arguments,
            selected.arguments.as_slice(),
            target,
        )?;
        // The outer call is the direct guard call the scope check proves;
        // the nested call lives in the derive body proven spanned above.
        self.any_query_scope_shape_ok(scenario, guard, outer.node, by)?;
        let (node, query, fact, alias, name, model, owner, receiver, collection, parameter) =
            self.any_query_domain_owner(scenario, *supplied, nested.node, Some(&scope))?;
        let (parent, hops, parameter_owner, parameter_symbol, type_node, parameter_data, array) =
            self.any_query_domain_parameter(scenario, receiver, parameter, model, Some(&scope))?;
        let authored = self.nodes.get(&node)?;
        let alias_words: Vec<_> = self
            .nodes
            .get(&alias.node)?
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Name)
            .map(|part| self.word(part))
            .collect::<Option<Vec<_>>>()?;
        let predicate_node = self.query_group(*predicate)?;
        let members = self.any_query_conjunct_members(
            scenario,
            predicate_node,
            alias.node,
            model,
            &boolean,
            Some(&scope),
        )?;
        self.any_query_fact_shape_ok(
            nested.node, fact, *overload, node, alias, *predicate, &boolean, authored, query,
            &array, *supplied, &alias_words, name, owner, collection, hops,
        )?;
        self.any_query_fact_owner_ok(
            scenario,
            receiver,
            parameter,
            parent,
            collection,
            owner,
            model,
            parameter_owner,
            parameter_symbol,
            parameter_data,
            type_node,
            hops,
            Some(&scope),
        )?;
        // The domain formal roots the navigation: resolve it off the
        // receiver so the evaluator re-verifies this exact formal's live
        // binding against the original scenario parameter. The stored
        // lineage model is the formal's own record type, mirroring the
        // direct consumer (which stores its parameter's type).
        let (base, field) = self.count_member(receiver)?;
        if field != "parent" {
            return None;
        }
        let Some(Binding::Symbol(formal)) = self.query_binding(base) else {
            return None;
        };
        if self.nested_scope_formal(&scope, *formal).is_none()
            || !scope
                .formals
                .iter()
                .any(|(candidate, _, mapped)| *candidate == *formal && *mapped == Some(parameter))
        {
            return None;
        }
        let ResolvedType::Record {
            symbol: formal_model,
            stored: true,
        } = self.types.symbol_types.get(formal)?
        else {
            return None;
        };
        let formal_model = *formal_model;
        let source = self.source(data.module, nested.node).ok()?;
        let return_node = scenario.effects.last()?.node;
        let query = self.any_query_emit_tail(
            source,
            node,
            query.domain,
            model,
            owner.canonical.clone(),
            alias.node,
            *predicate,
            vec![(receiver, parameter)],
            &members,
            return_node,
            data.module,
            std::slice::from_ref(&outer.node),
        )?;
        Some(NestedAnyQuery {
            query,
            call: nested.node,
            chain: vec![outer.node],
            formal: *formal,
            parameter,
            parent: formal_model,
        })
    }

    /// Retain original model counts independently from executable disclosure.
    /// Supplied arrays and derived value arrays remain ordinary pure count.
    fn checked_count_query_sources(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<DisclosureQuery>> {
        if scenario.read || scenario.on.is_some() {
            return Some(Vec::new());
        }
        let mut queries = Vec::new();
        let mut visited = 0usize;
        // Only successfully admitted whole sites may replace a native count
        // fragment. Failed candidates keep the original independent refusal.
        let observers = self.checked_source_helper_count_sites(scenario);
        let statements=self.count_query_statements(scenario)?;
        let statement_nodes:HashSet<_>=statements.iter().map(|statement|statement.node).collect();
        for statement in statements {
            let mut pending = vec![*self.nodes.get(&statement.node)?];
            while let Some(node) = pending.pop() {
                visited += 1;
                if visited > 16384 {
                    return None;
                }
                if node.kind == SyntaxKind::Examples || NodeKey::of(node)!=statement.node && statement_nodes.contains(&NodeKey::of(node)) {
                    continue;
                }
                pending.extend(node.children.iter().rev());
                let Some(call_step) = self.count_call_supplied(node) else {
                    return None;
                };
                let Some((call, supplied)) = call_step else {
                    continue;
                };
                let Some(model_step) = self.count_domain_model(supplied) else {
                    return None;
                };
                let Some(model) = model_step else {
                    continue;
                };
                if observers.iter().any(|site|
                    site.statement == statement.node
                        && self.source_require_helper_count_site(scenario, site)
                        && site.calls.iter().any(|source| source.node == call
                            && source.chain.is_empty()
                            && matches!(&source.target, CheckedDecisionCallTarget::Builtin { id, .. } if id == "count")
                            && self.source_require_observer_count(scenario, source)))
                {
                    continue;
                }
                // Every other released native count keeps priority; only an
                // otherwise unsupported exact leading count uses the fallback.
                if let Some(query)=self.checked_assign_count_query_source(
                    scenario,statement.node,call,supplied,model,
                ).or_else(||self.checked_count_query_source(scenario,statement.node,call,supplied,model)) {
                    queries.push(query);
                }else if !self.checked_source_requires(scenario).is_some_and(|sites|
                    sites.iter().any(|site|site.stage==CheckedDecisionStage::LeadingRequire
                        && site.statement==statement.node && site.calls.iter().any(|source|
                            source.node==call && matches!(&source.target,CheckedDecisionCallTarget::Builtin{id,..} if id=="count")
                                && self.source_require_contained_collection(scenario,source,"count"))))
                {return None;}
                if queries.len() > 200 {
                    return None;
                }
            }
        }
        queries.sort_by_key(|query| (query.count.as_ref().unwrap().call.start, query.node.end));
        Some(queries)
    }

    /// Each original IF arm owns its own query occurrence. A parent's
    /// syntax walk must not relabel a child CREATE count as the outer IF.
    fn count_query_statements<'b>(&self,scenario:&'b super::effects::ScenarioData)->Option<Vec<&'b Effect>> {
        let mut pending:Vec<_>=scenario.guards.iter().chain(&scenario.effects).rev().map(|effect|(effect,0)).collect();
        let mut statements=Vec::new();
        while let Some((effect,depth))=pending.pop(){
            if depth>=64||statements.len()>=16384{return None;}
            statements.push(effect);
            if effect.verb==EffectVerb::If&&effect.match_arms.is_empty(){
                pending.extend(effect.else_effects.iter().rev().map(|child|(child,depth+1)));
                pending.extend(effect.then_effects.iter().rev().map(|child|(child,depth+1)));
            }
        }
        Some(statements)
    }

    /// A `count` call's single supplied argument. Outer `None` keeps the
    /// original `?` boundary (the whole inventory is declined); inner
    /// `None` keeps the original `continue` (this node is not a count call).
    fn count_call_supplied(
        &self,
        node: &SyntaxNode,
    ) -> Option<Option<(NodeKey, NodeKey)>> {
        if node.kind != SyntaxKind::Call {
            return Some(None);
        }
        let call = NodeKey::of(node);
        let callee = node.children.iter().find(|part| expression(part.kind))?;
        let is_count = matches!(self.query_binding(NodeKey::of(callee)),
            Some(Binding::Builtin {id}) if id == "count");
        if !is_count {
            return Some(None);
        }
        let mut arguments = node
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Argument);
        let argument = arguments.next()?;
        let mut values = argument
            .children
            .iter()
            .filter(|part| expression(part.kind));
        let supplied = NodeKey::of(values.next()?);
        if arguments.next().is_some() || values.next().is_some() {
            return None;
        }
        Some(Some((call, supplied)))
    }

    /// A count domain's stored model. Outer `None` keeps the original `?`
    /// boundary (the whole inventory is declined); inner `None` keeps the
    /// original `continue` (a pure-value domain, not a model query).
    fn count_domain_model(&self, supplied: NodeKey) -> Option<Option<SymbolId>> {
        let domain = self.query_group(supplied)?;
        let Some(ResolvedType::Array { element, .. }) = self.types.node_types.get(&domain)
        else {
            return Some(None);
        };
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = element.as_ref()
        else {
            return Some(None);
        };
        // Parameter arrays and other local arrays are pure values.
        // A model-query inventory requires its actual Query or Member.
        // (The domain node is captured once: both reads below saw the
        // same table entry in the original, with no mutation between.)
        let domain_node = self.nodes.get(&domain)?;
        if !matches!(
            domain_node.kind,
            SyntaxKind::Query | SyntaxKind::Member
        ) {
            return Some(None);
        }
        if domain_node.kind == SyntaxKind::Member {
            let (receiver, name) = self.count_member(domain)?;
            if let Some(ResolvedType::Record { symbol, .. }) =
                self.types.node_types.get(&receiver)
                && self
                    .resolve
                    .symbols
                    .get(symbol.0 as usize)?
                    .fields_of()
                    .iter()
                    .any(|field| {
                        self.resolve
                            .symbols
                            .get(field.0 as usize)
                            .is_some_and(|field| field.name == name)
                    })
            {
                // An authored field array is a supplied value. It must
                // never borrow implicit child-collection provenance.
                return Some(None);
            }
        }
        Some(Some(*model))
    }

    fn count_query_signature_ok(
        &self,
        builtin: &String,
        selected: &super::types::SelectedCall,
        call: NodeKey,
        supplied: NodeKey,
        statement: NodeKey,
        scenario: &super::effects::ScenarioData,
        node: NodeKey,
        array: &ResolvedType,
    ) -> Option<()> {
        if builtin != "count"
            || selected.arguments.as_slice() != [supplied]
            || selected.slots.as_slice() != [Some(0)]
            || self.types.node_types.get(&call) != Some(&ResolvedType::Scalar(Scalar::Int))
            || self.types.node_types.get(&node) != Some(array)
            || self.types.node_types.get(&supplied) != Some(array)
            || statement.file != call.file
            || statement.start > call.start
            || statement.end < call.end
            || scenario.node.file != statement.file
            || scenario.node.start > statement.start
            || scenario.node.end < statement.end
        {
            return None;
        }
        Some(())
    }

    fn count_query_member_domain(
        &self,
        scenario: &super::effects::ScenarioData,
        node: NodeKey,
        call: NodeKey,
        model: SymbolId,
        owner: &Symbol,
    ) -> Option<(
        NodeKey,
        Option<NodeKey>,
        Option<NodeKey>,
        Option<(NodeKey, SymbolId)>,
        Vec<(NodeKey, SymbolId)>,
    )> {
        if self.types.checked_queries.contains_key(&node)
            || self.types.checked_collection_calls.contains_key(&call)
        {
            return None;
        }
        let (receiver, name) = self.count_member(node)?;
        let created=scenario.result.is_none().then(||self.created_parent_source(receiver,scenario.module)).flatten();
        let parameter = self.query_parameter(scenario, receiver).or_else(||created.as_ref().map(|(_,_,parameter)|*parameter)).or_else(|| {
            scenario.result.is_none().then(||scenario.params.iter().find(|parameter|
                self.checked_call_parent_path(receiver,parameter.param,0).is_some_and(|(_,hops)|hops==1))
                .map(|parameter|parameter.param)).flatten()
        })?;
        let (parent, hops) = self.checked_call_parent_path(receiver, parameter, 0)
            .or_else(||created.as_ref().map(|(_,parent,_)|(*parent,0)))?;
        let SymbolKind::Model {
            owner: ModelOwner::ChildOf(actual_parent),
            ..
        } = &owner.kind
        else {
            return None;
        };
        let parent_owner = self.checked_count_model(parent, scenario.module)?;
        if hops > 1 || hops != 0 && scenario.result.is_some()
            || *actual_parent != parent
            || owner.name != name
            || self.model_has_field(parent, name)
            || self.effects.models.get(&model)?.owner != ModelOwner::ChildOf(parent)
            || parent_owner.id != parent
        {
            return None;
        }
        Some((
            node,
            None,
            None,
            Some((receiver, parameter)),
            vec![(receiver, parameter)],
        ))
    }

    fn count_query_statement_shape(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
    ) -> Option<()> {
        // This original ancestor scan is a real owning Require, not
        // a copied count tree or a selected-call annotation alone.
        let mut statements = scenario
            .guards
            .iter()
            .chain(&scenario.effects)
            .filter(|effect| effect.node == statement);
        let required = statements.next()?;
        let authored_statement = self.nodes.get(&statement)?;
        let authored_condition = authored_statement
            .children
            .iter()
            .find(|part| expression(part.kind))
            .map(NodeKey::of)?;
        let authored_call = self.nodes.get(&call)?;
        let callee = authored_call
            .children
            .iter()
            .find(|part| expression(part.kind))?;
        if statements.next().is_some()
            || required.verb != EffectVerb::Require
            || authored_statement.kind != SyntaxKind::Require
            || required.cond != Some(authored_condition)
            || self.types.node_types.get(&authored_condition)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
            || authored_call.kind != SyntaxKind::Call
            || callee.kind != SyntaxKind::NameRef
            || self.word(callee)? != "count"
            || !matches!(self.query_binding(NodeKey::of(callee)),
                Some(Binding::Builtin {id}) if id == "count")
        {
            return None;
        }
        Some(())
    }

    fn count_query_fact_lookup(
        &self,
        call: NodeKey,
        node: NodeKey,
    ) -> Option<(
        &'a super::types::CheckedCollectionCall,
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
    )> {
        let fact = self.types.checked_collection_calls.get(&call)?;
        let query = self.types.checked_queries.get(&node)?;
        let [alias, predicate] = query.clauses.as_slice() else {
            return None;
        };
        Some((fact, query, alias, predicate))
    }

    fn count_query_fact_attrs(
        &self,
        fact: &super::types::CheckedCollectionCall,
        call: NodeKey,
        node: NodeKey,
        model: SymbolId,
        overload: usize,
        alias_node: NodeKey,
    ) -> Option<()> {
        if fact.node != call
            || fact.builtin != "count"
            || fact.overload != overload
            || fact.query != node
            || fact.model != model
            || fact.alias != alias_node
            || fact.predicate.is_some()
        {
            return None;
        }
        Some(())
    }

    fn count_query_syntax_attrs(
        &self,
        query: &super::types::CheckedQuery,
        node: NodeKey,
        array: &ResolvedType,
        owner: &Symbol,
        model: SymbolId,
        alias: &super::types::CheckedQueryClause,
        predicate: &super::types::CheckedQueryClause,
        alias_names: &[&str],
        where_names: &[&str],
    ) -> Option<()> {
        if query.node != node
            || query.projection.is_some()
            || query.domain_type != *array
            || query.result != *array
            || self.types.node_types.get(&query.domain) != Some(array)
            || !matches!(self.query_binding(query.domain), Some(Binding::Symbol(id)) if *id == model)
            || self.nodes.get(&query.domain)?.kind != SyntaxKind::NameRef
            || self.word(self.nodes.get(&query.domain)?)? != owner.name
            || !matches!(&alias.kind, CheckedQueryClauseKind::As { name }
                if alias_names == ["as", name.as_str()])
            || !alias.expressions.is_empty()
            || predicate.kind != CheckedQueryClauseKind::Where
            || predicate.expressions.len() != 1
            || !query.matches_source_nodes(self.nodes.get(&node)?, expression)
            || where_names != ["where"]
        {
            return None;
        }
        Some(())
    }

    fn count_query_fact_shape(
        &self,
        scenario: &super::effects::ScenarioData,
        call: NodeKey,
        node: NodeKey,
        model: SymbolId,
        overload: usize,
        array: &ResolvedType,
        owner: &Symbol,
    ) -> Option<(
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
    )> {
        let (fact, query, alias, predicate) = self.count_query_fact_lookup(call, node)?;
        self.count_query_fact_attrs(fact, call, node, model, overload, alias.node)?;
        let alias_names: Vec<_> = self
            .nodes
            .get(&alias.node)?
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Name)
            .map(|part| self.word(part))
            .collect::<Option<Vec<_>>>()?;
        let where_names: Vec<_> = self
            .nodes
            .get(&predicate.node)?
            .children
            .iter()
            .filter(|part| part.kind == SyntaxKind::Name)
            .map(|part| self.word(part))
            .collect::<Option<Vec<_>>>()?;
        self.count_query_syntax_attrs(
            query,
            node,
            array,
            owner,
            model,
            alias,
            predicate,
            &alias_names,
            &where_names,
        )?;
        Some((query, alias, predicate))
    }

    fn count_query_containment_edges(
        &self,
        scenario: &super::effects::ScenarioData,
        predicate_node: NodeKey,
        equality: NodeKey,
        alias_node: NodeKey,
        model: SymbolId,
    ) -> Option<(
        DisclosureQueryParentEdge,
        DisclosureQueryParentEdge,
        DisclosureQueryParentEdge,
        NodeKey,
        SymbolId,
    )> {
        let (candidate_parent, supplied_parent) = self.query_binary(equality, "==")?;
        let (outer_receiver, outer_name) = self.count_member(candidate_parent)?;
        let (candidate, inner_name) = self.count_member(outer_receiver)?;
        if outer_name != "parent"
            || inner_name != "parent"
            || !self.query_row(candidate, alias_node, model)
        {
            return None;
        }
        let first_edge = self.checked_count_parent_edge(
            outer_receiver,
            candidate,
            model,
            scenario.module,
        )?;
        let second_edge = self.checked_count_parent_edge(
            candidate_parent,
            outer_receiver,
            first_edge.parent,
            scenario.module,
        )?;
        let (parameter_node, parameter_name) = self.count_member(supplied_parent)?;
        let parameter = self.query_parameter(scenario, parameter_node)?;
        let (parameter_model, hops) =
            self.checked_call_parent_path(parameter_node, parameter, 0)?;
        let supplied_edge = self.checked_count_parent_edge(
            supplied_parent,
            parameter_node,
            parameter_model,
            scenario.module,
        )?;
        if parameter_name != "parent"
            || hops != 0
            || parameter_model != first_edge.parent
            || supplied_edge.parent != second_edge.parent
            || self.types.node_types.get(&equality)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some((
            first_edge,
            second_edge,
            supplied_edge,
            parameter_node,
            parameter,
        ))
    }

    fn count_query_predicate_edges(
        &self,
        scenario: &super::effects::ScenarioData,
        predicate: &super::types::CheckedQueryClause,
        alias_node: NodeKey,
        model: SymbolId,
    ) -> Option<(
        DisclosureQueryParentEdge,
        DisclosureQueryParentEdge,
        DisclosureQueryParentEdge,
        NodeKey,
        NodeKey,
        SymbolId,
        NodeKey,
        SymbolId,
    )> {
        let predicate_node = predicate.expressions[0];
        let actual_predicates: Vec<_> = self
            .nodes
            .get(&predicate.node)?
            .children
            .iter()
            .filter(|part| expression(part.kind))
            .map(NodeKey::of)
            .collect();
        if actual_predicates != [predicate_node]
            || self.types.node_types.get(&predicate_node)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        let (equality, unfinished) = self.query_binary(predicate_node, "and")?;
        let (first_edge, second_edge, supplied_edge, parameter_node, parameter) =
            self.count_query_containment_edges(scenario, predicate_node, equality, alias_node, model)?;
        let field = self.query_member(unfinished, alias_node, model)?;
        if self.resolve.symbols.get(field.0 as usize)?.name != "unfinished"
            || self.types.symbol_types.get(&field)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.node_types.get(&unfinished)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some((
            first_edge,
            second_edge,
            supplied_edge,
            predicate_node,
            unfinished,
            field,
            parameter_node,
            parameter,
        ))
    }

    fn count_query_edge_dependencies(
        &self,
        scenario: &super::effects::ScenarioData,
        first_edge: &DisclosureQueryParentEdge,
        unfinished: NodeKey,
        model: SymbolId,
        field: SymbolId,
        owner: &Symbol,
        query_id: &str,
    ) -> Option<Vec<DisclosureDependency>> {
        // This is original containment metadata, not an authored
        // field. Its owning query captures the candidate's first hop.
        let mut dependencies = vec![DisclosureDependency {
            id: self.opaque("query-control", first_edge.node, query_id).ok()?,
            source: self.source(scenario.module, first_edge.node).ok()?,
            node: first_edge.node,
            calls: Vec::new(),
            role: DependencyRole::Control,
            model,
            field: model,
            model_name: owner.canonical.clone(),
            field_name: "parent".into(),
            ty: ResolvedType::Record {
                symbol: first_edge.parent,
                stored: true,
            },
            type_id: self
                .resolve
                .symbols
                .get(first_edge.parent.0 as usize)?
                .canonical
                .clone(),
            query_id: None,
        }];
        dependencies.push(self.query_dependency(
            unfinished,
            scenario.module,
            model,
            field,
            DependencyRole::Control,
            query_id,
        )?);
        Some(dependencies)
    }

    fn count_query_scan_domain(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
        node: NodeKey,
        model: SymbolId,
        overload: usize,
        array: &ResolvedType,
        owner: &Symbol,
        query_id: &str,
    ) -> Option<(
        NodeKey,
        Option<NodeKey>,
        Option<NodeKey>,
        Option<(NodeKey, SymbolId)>,
        Vec<(NodeKey, SymbolId)>,
        Vec<DisclosureDependency>,
        Vec<DisclosureQueryParentEdge>,
    )> {
        self.count_query_statement_shape(scenario, statement, call)?;
        let (query, alias, predicate) =
            self.count_query_fact_shape(scenario, call, node, model, overload, array, owner)?;
        let (
            first_edge,
            second_edge,
            supplied_edge,
            predicate_node,
            unfinished,
            field,
            parameter_node,
            parameter,
        ) = self.count_query_predicate_edges(scenario, predicate, alias.node, model)?;
        let dependencies = self.count_query_edge_dependencies(
            scenario,
            &first_edge,
            unfinished,
            model,
            field,
            owner,
            query_id,
        )?;
        let inputs = vec![(parameter_node, parameter)];
        let parent_edges = vec![first_edge, second_edge, supplied_edge];
        Some((
            query.domain,
            Some(alias.node),
            Some(predicate_node),
            None,
            inputs,
            dependencies,
            parent_edges,
        ))
    }

    /// The original assign capacity Require counts active Seats within the
    /// versioned Term parameter before selecting a prior Seat. It does not
    /// create a count+1 result, so its proof is separate from that profile.
    fn checked_assign_count_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
        supplied: NodeKey,
        model: SymbolId,
    ) -> Option<DisclosureQuery> {
        if scenario.read || scenario.on.is_some() || scenario.by.is_none()
            || scenario.result.is_some() || scenario.cohort.is_some()
            || self.resolve.modules.get(scenario.module.0 as usize)?.name != "member_terms"
            || self.resolve.symbols.get(scenario.scenario.0 as usize)?.name != "assign"
        { return None; }
        let owner = self.checked_count_model(model, scenario.module)?;
        let node = self.query_group(supplied)?;
        let selected = self.types.selected_calls.get(&call)?;
        let SelectedCallTarget::Builtin { id, overload } = &selected.target else { return None; };
        let array = ResolvedType::Array {
            element: Box::new(ResolvedType::Record { symbol: model, stored: true }),
            ordered: true,
            nonempty: false,
        };
        self.count_query_signature_ok(id, selected, call, supplied, statement, scenario, node, &array)?;
        self.count_query_statement_shape(scenario, statement, call)?;
        let required = scenario.guards.iter().find(|effect| effect.node == statement)?;
        let (count_operand, seats_operand) = self.query_binary(required.cond?, "<")?;
        if self.query_group(count_operand)? != call
            || self.types.node_types.get(&seats_operand) != Some(&ResolvedType::Scalar(Scalar::Int))
        { return None; }
        let (seats_receiver, seats_name) = self.count_member(seats_operand)?;
        let parameter = self.query_parameter(scenario, seats_receiver)?;
        let ResolvedType::Record { symbol: term, stored: true } = self.types.symbol_types.get(&parameter)? else { return None; };
        let term_owner = self.resolve.symbols.get(term.0 as usize)?;
        let seats = term_owner.fields_of().iter().copied().find(|field|
            self.resolve.symbols.get(field.0 as usize).is_some_and(|symbol| symbol.name == "seats"))?;
        if term_owner.name != "Term" || self.types.symbol_types.get(&seats) != Some(&ResolvedType::Scalar(Scalar::Int))
            || seats_name != "seats" || self.checked_call_parent_path(seats_receiver, parameter, 0) != Some((*term, 0))
        { return None; }
        let fact = self.types.checked_collection_calls.get(&call)?;
        let query = self.types.checked_queries.get(&node)?;
        let [alias, where_clause] = query.clauses.as_slice() else { return None; };
        self.count_query_fact_attrs(fact, call, node, model, *overload, alias.node)?;
        let (receiver, name) = self.count_member(query.domain)?;
        let domain_parameter = self.query_parameter(scenario, receiver)?;
        let ModelOwner::ChildOf(parent) = self.effects.models.get(&model)?.owner else { return None; };
        if self.nodes.get(&node)?.kind != SyntaxKind::Query
            || query.projection.is_some() || query.domain_type != array || query.result != array
            || self.types.node_types.get(&query.domain) != Some(&array)
            || self.nodes.get(&query.domain)?.kind != SyntaxKind::Member
            || domain_parameter != parameter || parent != *term
            || owner.name != "Seat" || name != "Seat" || self.model_has_field(*term, name)
            || self.checked_call_parent_path(receiver, parameter, 0) != Some((*term, 0))
            || !matches!(&alias.kind, CheckedQueryClauseKind::As { name } if name == "seat")
            || !alias.expressions.is_empty()
            || where_clause.kind != CheckedQueryClauseKind::Where
            || where_clause.expressions.len() != 1
        { return None; }
        let predicate = where_clause.expressions[0];
        let field = self.query_member(predicate, alias.node, model)?;
        if self.resolve.symbols.get(field.0 as usize)?.name != "active"
            || self.types.symbol_types.get(&field) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.node_types.get(&predicate) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.nodes.get(&where_clause.node)?.children.iter().filter(|part| expression(part.kind))
                .map(NodeKey::of).collect::<Vec<_>>() != [predicate]
            || self.nodes.get(&node)?.children.iter().filter(|part| part.kind == SyntaxKind::QueryClause)
                .map(NodeKey::of).collect::<Vec<_>>() != [alias.node, where_clause.node]
        { return None; }
        let source = self.source(scenario.module, node).ok()?;
        let query_id = self.opaque("query", node, "").ok()?;
        let dependencies = vec![self.query_dependency(
            predicate, scenario.module, model, field, DependencyRole::Control, &query_id,
        )?];
        let influences = [InfluenceKind::QueryExistence, InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership, InfluenceKind::QueryOrder].into_iter().map(|kind| {
            Some(DisclosureInfluence {
                id: self.opaque("query-influence", node, &format!("{query_id}:{kind:?}")).ok()?,
                source: source.clone(), node, kind, query_id: Some(query_id.clone()),
            })
        }).collect::<Option<Vec<_>>>()?;
        Some(DisclosureQuery {
            id: query_id, source, node, domain: query.domain, model,
            model_name: owner.canonical.clone(), alias: Some(alias.node),
            predicate: Some(predicate), inputs: vec![(receiver, parameter)], dependencies,
            order: Vec::new(), limit: None, archived: false, cardinality_guard: None,
            return_node: scenario.effects.last()?.node, projection: None, first: None,
            count: Some(DisclosureCountQuery { call, overload: *overload,
                slots: selected.slots.clone(), statement,
                contained_parent: Some((receiver, parameter)), parent_edges: Vec::new() }),
            influences,
        })
    }

    fn checked_count_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        statement: NodeKey,
        call: NodeKey,
        supplied: NodeKey,
        model: SymbolId,
    ) -> Option<DisclosureQuery> {
        let selected = self.types.selected_calls.get(&call)?;
        let SelectedCallTarget::Builtin {
            id: builtin,
            overload,
        } = &selected.target
        else {
            return None;
        };
        let node = self.query_group(supplied)?;
        let record = ResolvedType::Record {
            symbol: model,
            stored: true,
        };
        let array = ResolvedType::Array {
            element: Box::new(record.clone()),
            ordered: true,
            nonempty: false,
        };
        let owner = self.checked_count_model(model, scenario.module)?;
        self.count_query_signature_ok(
            builtin,
            selected,
            call,
            supplied,
            statement,
            scenario,
            node,
            &array,
        )?;
        let source = self.source(scenario.module, node).ok()?;
        let id = self.opaque("query", node, "").ok()?;
        let (domain, alias, predicate, contained_parent, inputs, dependencies, parent_edges) =
            match self.nodes.get(&node)?.kind {
                SyntaxKind::Member => {
                    let (domain, alias, predicate, contained_parent, inputs) =
                        self.count_query_member_domain(scenario, node, call, model, owner)?;
                    (
                        domain,
                        alias,
                        predicate,
                        contained_parent,
                        inputs,
                        Vec::new(),
                        Vec::new(),
                    )
                }
                SyntaxKind::Query => self.count_query_scan_domain(
                    scenario,
                    statement,
                    call,
                    node,
                    model,
                    *overload,
                    &array,
                    owner,
                    &id,
                )?,
                _ => return None,
            };
        let returned = scenario.effects.last()?;
        if returned.verb != EffectVerb::Return && scenario.result.is_some() {
            return None;
        }
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", node, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(DisclosureQuery {
            id,
            source,
            node,
            domain,
            model,
            model_name: owner.canonical.clone(),
            alias,
            predicate,
            inputs,
            dependencies,
            order: Vec::new(),
            limit: None,
            archived: false,
            cardinality_guard: None,
            return_node: if scenario.result.is_none() {scenario.node} else {returned.node},
            projection: None,
            first: None,
            count: Some(DisclosureCountQuery {
                call,
                overload: *overload,
                slots: selected.slots.clone(),
                statement,
                contained_parent,
                parent_edges,
            }),
            influences,
        })
    }

    fn count_member(&self, key: NodeKey) -> Option<(NodeKey, &str)> {
        let node = self.nodes.get(&key)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let mut receivers = node.children.iter().filter(|part| expression(part.kind));
        let receiver = NodeKey::of(receivers.next()?);
        if receivers.next().is_some() {
            return None;
        }
        let name = node
            .children
            .iter()
            .rev()
            .find(|part| part.kind == SyntaxKind::Name)?;
        Some((receiver, self.word(name)?))
    }

    fn model_has_field(&self, model: SymbolId, name: &str) -> bool {
        let Some(owner) = self.resolve.symbols.get(model.0 as usize) else {
            return true;
        };
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return true;
        };
        fields.iter().any(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_none_or(|member| member.name == name)
        })
    }

    fn checked_count_model(
        &self,
        model: SymbolId,
        module: ModuleId,
    ) -> Option<&super::resolve::Symbol> {
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let data = self.effects.models.get(&model)?;
        let definition = self.checked_created_model(model, module)?;
        if owner.id != model
            || owner.module != module
            || data.module != module
            || definition.declaration.model != model
            || definition.declaration.node != data.node
        {
            return None;
        }
        Some(owner)
    }

    fn checked_count_parent_edge(
        &self,
        node: NodeKey,
        receiver: NodeKey,
        child: SymbolId,
        module: ModuleId,
    ) -> Option<DisclosureQueryParentEdge> {
        let (actual_receiver, name) = self.count_member(node)?;
        let owner = self.checked_count_model(child, module)?;
        let SymbolKind::Model {
            owner: ModelOwner::ChildOf(parent),
            ..
        } = owner.kind
        else {
            return None;
        };
        self.checked_count_model(parent, module)?;
        if actual_receiver != receiver
            || name != "parent"
            || self.model_has_field(child, "parent")
            || self.effects.models.get(&child)?.owner != ModelOwner::ChildOf(parent)
            || self.types.node_types.get(&receiver)
                != Some(&ResolvedType::Record {
                    symbol: child,
                    stored: true,
                })
            || self.types.node_types.get(&node)
                != Some(&ResolvedType::Record {
                    symbol: parent,
                    stored: true,
                })
        {
            return None;
        }
        Some(DisclosureQueryParentEdge {
            node,
            receiver,
            child,
            parent,
        })
    }

    /// C23 hook slice completeness: the skeleton below plus an actual
    /// admitted first-query fact for the leading `let`. Hooks without an
    /// admittable first query keep the trusted-handler refusal exactly.
    fn hook_first_complete(&self, scenario: &super::effects::ScenarioData) -> Option<()> {
        self.hook_first_event(scenario)?;
        let [binding, _] = scenario.effects.as_slice() else {
            return None;
        };
        self.checked_first_query_source(scenario, binding)?;
        Some(())
    }

    /// Checked delivery handlers own either a conditional agreement SEND/CREATE
    /// or the reminder's header-guarded flat SEND/CREATE. Every event row use
    /// retains its original declared field and owning stored model.
    fn hook_delivery_event(&self, scenario: &super::effects::ScenarioData) -> Option<(SymbolId, SymbolId, SymbolId)> {
        let HandlerSource::Event(event) = scenario.on.as_ref()? else { return None; };
        let scenario_symbol = self.resolve.symbols.get(scenario.scenario.0 as usize)?;
        let event_symbol = self.resolve.symbols.get(event.0 as usize)?;
        if scenario_symbol.canonical == "events.attendee_notice" {
            let fields = event_symbol.fields_of();
            let [subject, body, send, create] = scenario.effects.as_slice() else { return None; };
            let [guard] = scenario.guards.as_slice() else { return None; };
            if event_symbol.canonical != "events.AttendeeNotice" || fields.len() != 4
                || scenario.read || scenario.by.is_some() || scenario.result.is_some()
                || scenario.cohort.is_some() || !scenario.params.is_empty()
                || guard.verb != EffectVerb::Require || subject.verb != EffectVerb::Let
                || body.verb != EffectVerb::Let || send.verb != EffectVerb::Send
                || send.when.is_none() || create.verb != EffectVerb::Create
                || !matches!(create.target,Some(EffectTarget::Model(model)) if
                    self.resolve.symbols.get(model.0 as usize).is_some_and(|model| model.canonical == "events.Notice"))
            { return None; }
            let [row, kind, revision, body] = fields else { return None; };
            if self.resolve.symbols.get(row.0 as usize)?.name != "registration"
                || self.resolve.symbols.get(kind.0 as usize)?.name != "kind"
                || self.resolve.symbols.get(revision.0 as usize)?.name != "revision"
                || self.resolve.symbols.get(body.0 as usize)?.name != "body"
                || !matches!(self.types.symbol_types.get(row), Some(ResolvedType::Record {symbol,stored:true}) if
                    self.resolve.symbols.get(symbol.0 as usize).is_some_and(|model| model.canonical == "events.Registration"))
                || !matches!(self.types.symbol_types.get(kind),Some(ResolvedType::Enum {cases,..}) if cases == &["confirmation","change","cancellation"])
                || self.types.symbol_types.get(revision) != Some(&ResolvedType::Scalar(Scalar::Int))
                || self.types.symbol_types.get(body) != Some(&ResolvedType::Scalar(Scalar::Text))
                || !fields.iter().all(|field| matches!(self.resolve.symbols.get(field.0 as usize).map(|symbol|&symbol.kind),Some(SymbolKind::Field {owner,..}) if *owner == *event))
            { return None; }
            return Some((*event,*row,*revision));
        }
        if scenario_symbol.canonical == "maintain.remind" {
            let [binding, branch] = scenario.effects.as_slice() else { return None; };
            let [send, set] = branch.then_effects.as_slice() else { return None; };
            if event_symbol.canonical != "maintain.Reminder"
                || scenario_symbol.module != scenario.module || event_symbol.module != scenario.module
                || scenario.read || scenario.by.is_some() || scenario.result.is_some()
                || scenario.cohort.is_some() || !scenario.params.is_empty()
                || !scenario.guards.is_empty() || event_symbol.fields_of().len() != 2
                || binding.verb != EffectVerb::Let || binding.binding.as_deref() != Some("inspection")
                || branch.verb != EffectVerb::If || branch.cond.is_none()
                || !branch.else_effects.is_empty() || !branch.match_arms.is_empty()
                || send.verb != EffectVerb::Send || send.when.is_none()
                || set.verb != EffectVerb::Set
                || !matches!(set.target, Some(EffectTarget::Record { model: Some(model) })
                    if self.resolve.symbols.get(model.0 as usize).is_some_and(|model|
                        model.canonical == "maintain.Inspection"))
            { return None; }
            let source_row = binding.value?;
            let (root, field_name) = self.count_member(source_row)?;
            if field_name != "inspection"
                || !matches!(self.query_binding(root), Some(Binding::Context(ContextVar::Event)))
            { return None; }
            let fields = event_symbol.fields_of();
            let row = fields.iter().copied().find(|field|
                self.resolve.symbols.get(field.0 as usize).is_some_and(|field|
                    field.name == "inspection"))?;
            let revision = fields.iter().copied().find(|field|
                self.resolve.symbols.get(field.0 as usize).is_some_and(|field|
                    field.name == "revision"))?;
            let ResolvedType::Record { symbol: model, stored: true } =
                self.types.symbol_types.get(&row)? else { return None; };
            if self.resolve.symbols.get(model.0 as usize)?.canonical != "maintain.Inspection"
                || self.types.node_types.get(&source_row) != self.types.symbol_types.get(&row)
                || self.types.symbol_types.get(&revision) != Some(&ResolvedType::Scalar(Scalar::Int))
                || !fields.iter().all(|field| self.resolve.symbols.get(field.0 as usize)
                    .is_some_and(|symbol| matches!(symbol.kind,
                        SymbolKind::Field { owner, .. } if owner == *event)))
            { return None; }
            return Some((*event, row, revision));
        }
        let (event_name, row_name, model_name, created_name, reminder) = match scenario_symbol.canonical.as_str() {
            "agreements.notice" => ("agreements.Notice", "term", "agreements.Term", "agreements.NoticeDelivery", false),
            "agreements.due" => ("agreements.ObligationDue", "obligation", "agreements.Obligation", "agreements.NoticeDelivery", false),
            "appointments.remind" => ("appointments.Reminder", "appointment", "appointments.Appointment", "appointments.Notice", true),
            _ => return None,
        };
        let SymbolKind::Event { fields } = &event_symbol.kind else { return None; };
        let (send, create) = if reminder {
            let [send, create] = scenario.effects.as_slice() else { return None; };
            let [guard] = scenario.guards.as_slice() else { return None; };
            if guard.verb != EffectVerb::Require || guard.cond.is_none()
                || !guard.then_effects.is_empty() || !guard.else_effects.is_empty()
                || !guard.match_arms.is_empty() { return None; }
            (send, create)
        } else {
            let [branch] = scenario.effects.as_slice() else { return None; };
            let [send, create] = branch.then_effects.as_slice() else { return None; };
            if branch.verb != EffectVerb::If || branch.cond.is_none()
                || !branch.else_effects.is_empty() || !branch.match_arms.is_empty()
                || !scenario.guards.is_empty() { return None; }
            (send, create)
        };
        let EffectTarget::Model(created) = create.target.as_ref()? else { return None; };
        if event_symbol.canonical != event_name
            || scenario_symbol.module != scenario.module || event_symbol.module != scenario.module
            || scenario.read || scenario.by.is_some() || scenario.result.is_some()
            || scenario.cohort.is_some() || !scenario.params.is_empty()
            || fields.len() != 2
            || send.verb != EffectVerb::Send || send.when.is_none() || send.binding.is_none()
            || create.verb != EffectVerb::Create || create.binding.is_none()
            || !send.then_effects.is_empty() || !send.else_effects.is_empty()
            || !create.then_effects.is_empty() || !create.else_effects.is_empty()
            || self.resolve.symbols.get(created.0 as usize)?.canonical != created_name
        { return None; }
        let row = fields.iter().copied().find(|field|
            self.resolve.symbols.get(field.0 as usize).is_some_and(|field| field.name == row_name))?;
        let revision = fields.iter().copied().find(|field|
            self.resolve.symbols.get(field.0 as usize).is_some_and(|field| field.name == "revision"))?;
        let ResolvedType::Record { symbol: model, stored: true } =
            self.types.symbol_types.get(&row)? else { return None; };
        if self.resolve.symbols.get(model.0 as usize)?.canonical != model_name
            || self.types.symbol_types.get(&revision) != Some(&ResolvedType::Scalar(Scalar::Int))
            || !fields.iter().all(|field| self.resolve.symbols.get(field.0 as usize)
                .is_some_and(|symbol| matches!(symbol.kind,
                    SymbolKind::Field { owner, .. } if owner == *event)))
        { return None; }
        Some((*event, row, revision))
    }

    fn hook_delivery_field(&self, key: NodeKey, module: ModuleId) -> Option<(SymbolId, SymbolId)> {
        let (receiver, name) = self.count_member(key)?;
        let node = self.nodes.get(&receiver)?;
        if node.kind != SyntaxKind::NameRef
            || !matches!(self.query_binding(receiver), Some(Binding::Context(ContextVar::Event)))
        { return None; }
        let mut owners = self.effects.scenarios.values().filter(|scenario|
            scenario.module == module && scenario.node.file == key.file
                && scenario.node.start <= key.start && key.end <= scenario.node.end);
        let owner = owners.next()?;
        if owners.next().is_some() { return None; }
        let (_, row, revision) = self.hook_delivery_event(owner)?;
        let field = if self.resolve.symbols.get(row.0 as usize)?.name == name {
            row
        } else if name == "revision" {
            revision
        } else if self.resolve.symbols.get(owner.scenario.0 as usize)?.canonical == "events.attendee_notice"
            && matches!(name, "kind" | "body") {
            let HandlerSource::Event(event) = owner.on.as_ref()? else { return None; };
            *self.resolve.symbols.get(event.0 as usize)?.fields_of().iter().find(|field|
                self.resolve.symbols.get(field.0 as usize).is_some_and(|field| field.name == name))?
        } else {
            return None;
        };
        (self.types.node_types.get(&key) == self.types.symbol_types.get(&field))
            .then_some((owner.scenario, field))
    }

    /// Direct containment hops from the original declared event row. The
    /// first member must be the handler's exact declared event row; copied
    /// lexical rows cannot inherit this path.
    fn checked_delivery_parent_path(
        &self,
        key: NodeKey,
        module: ModuleId,
        field: SymbolId,
        remaining: usize,
    ) -> Option<(SymbolId, u8)> {
        if remaining > 2 { return None; }
        if self.hook_delivery_field(key, module).is_some_and(|(_, original)| original == field) {
            let ResolvedType::Record { symbol, stored: true } =
                self.types.symbol_types.get(&field)? else { return None; };
            return Some((*symbol, 0));
        }
        if remaining == 0 { return None; }
        let (base, name) = self.count_member(key)?;
        if name != "parent" { return None; }
        let (child, prior) = self.checked_delivery_parent_path(base, module, field, remaining - 1)?;
        self.call_parent_hop_valid(key, base, child, prior)
    }

    /// C23 hook slice skeleton: a declared-event handler (`on=Event`) with no
    /// caller parameters, no result, no cohort, no header guards and exactly
    /// one `let` plus one `require`. The returned event symbol authorizes the
    /// operand arm below; anything else keeps the trusted-handler refusal.
    fn hook_first_event(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<SymbolId> {
        let Some(HandlerSource::Event(event)) = &scenario.on else {
            return None;
        };
        let event = *event;
        if scenario.read
            || scenario.by.is_some()
            || scenario.result.is_some()
            || scenario.cohort.is_some()
            || !scenario.params.is_empty()
            || !scenario.guards.is_empty()
        {
            return None;
        }
        let [binding, guard] = scenario.effects.as_slice() else {
            return None;
        };
        if binding.verb != EffectVerb::Let
            || guard.verb != EffectVerb::Require
            || guard.cond.is_none()
        {
            return None;
        }
        Some(event)
    }

    /// Ordinary-scenario guard skeleton (CAN18-v1 first-query absence
    /// conjunctions): an ordinary (event-less) scenario whose effects are
    /// exactly let-first, require-with-condition, create and return. Only
    /// this confined shape may gain the guard-consumed mark below; any
    /// other tail, extra effect or branch keeps ordinary viewer behavior.
    /// Parameters are allowed (checked inputs, not authority); guards,
    /// cohorts, reads and result-less shapes are out of scope.
    fn ordinary_first_decision<'b>(
        &self,
        scenario: &'b super::effects::ScenarioData,
    ) -> Option<(&'b super::effects::Effect, &'b super::effects::Effect)> {
        if scenario.on.is_some() {
            return None;
        }
        if scenario.read
            || scenario.by.is_none()
            || scenario.result.is_none()
            || scenario.cohort.is_some()
            || !scenario.guards.is_empty()
        {
            return None;
        }
        let [binding, guard, create, ret] = scenario.effects.as_slice() else {
            return None;
        };
        if binding.verb != EffectVerb::Let
            || guard.verb != EffectVerb::Require
            || guard.cond.is_none()
            || create.verb != EffectVerb::Create
            || ret.verb != EffectVerb::Return
        {
            return None;
        }
        Some((binding, guard))
    }

    /// DESIGN442 presence consumption: the confined hook `Require` consumes
    /// the first binding's presence when its condition references the `Let`
    /// occurrence (a null check or a stored-read base). Reuses the
    /// structural 2-effect skeleton above: only the skeleton's own `Let`
    /// counts, so an unused binding or `require true` references nothing
    /// and gains no decision authority. Body/value copies are out of scope:
    /// only the decision reads ride the mark.
    fn first_binding_presence_consumed(
        &self,
        binding: &Effect,
        cond: NodeKey,
    ) -> bool {
        let mut pending = vec![cond];
        let mut steps = 0;
        while let Some(key) = pending.pop() {
            steps += 1;
            if steps > 16384 {
                return false;
            }
            let Some(key) = self.query_group(key) else {
                continue;
            };
            if matches!(self.query_binding(key), Some(Binding::Let { node }) if *node == binding.node) {
                return true;
            }
            if let Some(node) = self.nodes.get(&key) {
                pending.extend(
                    node.children
                        .iter()
                        .filter(|child| expression(child.kind))
                        .map(NodeKey::of),
                );
            }
        }
        false
    }

    fn first_binding_nonnull_only(&self, binding: &Effect, cond: NodeKey) -> bool {
        let Some((left, right)) = self.query_binary(cond, "!=") else { return false; };
        [(left, right), (right, left)].iter().any(|(value, null)|
            matches!(self.query_binding(*value), Some(Binding::Let { node }) if *node == binding.node)
                && self.types.node_types.get(null) == Some(&ResolvedType::Null))
    }

    fn first_binding_used_in_node(&self, binding: &Effect, root: NodeKey) -> bool {
        let mut pending = vec![root];
        let mut steps = 0;
        while let Some(key) = pending.pop() {
            steps += 1;
            if steps > 16384 { return true; }
            if matches!(self.query_binding(key), Some(Binding::Let { node }) if *node == binding.node) {
                return true;
            }
            if let Some(node) = self.nodes.get(&key) {
                pending.extend(node.children.iter().map(NodeKey::of));
            }
        }
        false
    }

    fn first_null_branch_decision<'b>(
        &self, scenario: &'b super::effects::ScenarioData,
    ) -> Option<&'b Effect> {
        if scenario.on.is_some() || scenario.read || scenario.by.is_none() ||
            scenario.result.is_some() || scenario.cohort.is_some() {
            return None;
        }
        let [binding, branch, ..] = scenario.effects.as_slice() else { return None; };
        if binding.verb != EffectVerb::Let || branch.verb != EffectVerb::If ||
            !branch.match_arms.is_empty() { return None; }
        self.checked_first_query_source(scenario, binding)?;
        let (left, right) = self.query_binary(branch.cond?, "==")?;
        if ![(left, right), (right, left)].iter().any(|(value, null)|
            matches!(self.query_binding(*value), Some(Binding::Let { node }) if *node == binding.node)
                && self.types.node_types.get(null) == Some(&ResolvedType::Null)) {
            return None;
        }
        Some(binding)
    }

    fn first_null_branch_target_only<'b>(
        &self, scenario: &'b super::effects::ScenarioData,
    ) -> Option<&'b Effect> {
        let binding = self.first_null_branch_decision(scenario)?;
        let [_, branch, suffix @ ..] = scenario.effects.as_slice() else { return None; };
        let query = self.checked_first_query_source(scenario, binding)?;
        // An order-only selection has no control dependencies by design.
        // Its original contained-parent path still bounds the owner domain;
        // an unscoped order-only scan cannot acquire target authority here.
        if (query.dependencies.is_empty() && query.first.as_ref()?.contained_parent.is_none()) ||
            query.archived || query.limit.is_some() {
            return None;
        }
        // The selected row may be the write target in this branch only.
        // Subsequent effects execute in source order but receive no grant to
        // read or transport that row. A use in any later effect needs its
        // own checked value/result flow and remains refused here.
        if suffix.iter().any(|effect| self.first_binding_used_in_node(binding, effect.node)) {
            return None;
        }
        let [create] = branch.then_effects.as_slice() else { return None; };
        let set = match branch.else_effects.as_slice() {
            [set] => set,
            [_, set] if self.first_null_branch_assign_guard(scenario, binding).is_some() => set,
            _ => return None,
        };
        if create.verb != EffectVerb::Create || set.verb != EffectVerb::Set ||
            !matches!(set.target, Some(EffectTarget::Record { model: Some(model) }) if model == query.model) ||
            self.first_binding_used_in_node(binding, create.node) ||
            set.args.iter().any(|arg| arg.value.is_some_and(|value| self.first_binding_used_in_node(binding, value))) {
            return None;
        }
        let set_node = self.nodes.get(&set.node)?;
        let target = set_node.children.iter().find(|child| child.kind == SyntaxKind::Path)?;
        let source = self.db.get(target.span.file)?;
        if source.text.get(target.span.start as usize..target.span.end as usize)?.trim() != binding.binding.as_deref()? {
            return None;
        }
        Some(binding)
    }

    /// Original `assign` body: the selected Seat's active bit is checked at
    /// its authored else-stage before the same row is reactivated.
    fn first_null_branch_assign_guard<'b>(
        &self,
        scenario: &'b super::effects::ScenarioData,
        binding: &Effect,
    ) -> Option<&'b Effect> {
        if self.resolve.symbols.get(scenario.scenario.0 as usize)?.canonical != "member_terms.assign"
            || scenario.guards.len() != 3 || scenario.effects.len() != 3
        { return None; }
        let branch = scenario.effects.get(1)?;
        let [guard, set] = branch.else_effects.as_slice() else { return None; };
        if guard.verb != EffectVerb::Require || set.verb != EffectVerb::Set
            || self.nodes.get(&guard.node)?.kind != SyntaxKind::Require
        { return None; }
        let condition = self.query_group(guard.cond?)?;
        let unary = self.nodes.get(&condition)?;
        if unary.kind != SyntaxKind::Unary
            || unary.children.iter().filter(|node| matches!(node.kind, SyntaxKind::Name | SyntaxKind::Punct))
                .map(|node| self.word(node)).collect::<Option<Vec<_>>>()? != ["not"]
        { return None; }
        let operands = unary.children.iter().filter(|node| expression(node.kind)).collect::<Vec<_>>();
        let [operand] = operands.as_slice() else { return None; };
        let (receiver, field) = self.count_member(NodeKey::of(operand))?;
        if field != "active"
            || !matches!(self.query_binding(receiver), Some(Binding::Let { node }) if *node == binding.node)
            || self.types.node_types.get(&NodeKey::of(operand)) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.node_types.get(&condition) != Some(&ResolvedType::Scalar(Scalar::Bool))
        { return None; }
        let query = self.checked_first_query_source(scenario, binding)?;
        let seat = self.resolve.symbols.get(query.model.0 as usize)?;
        if seat.canonical != "member_terms.Seat" || self.types.node_types.get(&receiver)
            != Some(&ResolvedType::Record { symbol: query.model, stored: true })
            || !seat.fields_of().iter().any(|candidate|
                self.resolve.symbols.get(candidate.0 as usize).is_some_and(|field_symbol|
                    field_symbol.name == "active"
                    && self.types.symbol_types.get(candidate) == Some(&ResolvedType::Scalar(Scalar::Bool))))
        { return None; }
        Some(guard)
    }

    fn first_target_companion_assign_count(
        &self,
        scenario: &super::effects::ScenarioData,
        binding: &Effect,
        queries: &[DisclosureQuery],
    ) -> bool {
        let [count, first] = queries else { return false; };
        if scenario.guards.len() != 3 { return false; }
        let Some(capacity) = count.count.as_ref() else { return false; };
        let Some(selected) = first.first.as_ref() else { return false; };
        count.model == first.model && count.model_name == "member_terms.Seat"
            && count.source == first.source && count.return_node == first.return_node
            && capacity.statement == scenario.guards[2].node
            && capacity.call.end <= selected.binding.start
            && selected.binding == binding.node
            && capacity.contained_parent.is_some_and(|(count_receiver, parameter)|
                selected.contained_parent.is_some_and(|(first_receiver, first_parameter)|
                    parameter == first_parameter
                    && self.checked_call_parent_path(count_receiver, parameter, 0)
                        == self.checked_call_parent_path(first_receiver, parameter, 0)))
            && count.dependencies.len() == 1
            && count.dependencies[0].field_name == "active"
            && count.dependencies[0].role == DependencyRole::Control
            && self.first_null_branch_assign_guard(scenario, binding).is_some()
    }

    /// A leading source Require may use the same contained owner domain as a
    /// later null-branch first target. This pairs the two original query
    /// occurrences without extending target authority to another model,
    /// parent path or effect value. The receipt and State recheck the pair.
    fn first_target_companion_any(
        &self,
        scenario: &super::effects::ScenarioData,
        binding: &Effect,
        queries: &[DisclosureQuery],
    ) -> bool {
        let [any, first] = queries else { return false; };
        let Some(selected) = first.first.as_ref() else { return false; };
        let Some((first_receiver, parameter)) = selected.contained_parent else { return false; };
        let Some((any_receiver, child_name)) = self.count_member(any.domain) else { return false; };
        let Some((first_parent, first_hops)) = self.checked_call_parent_path(first_receiver, parameter, 0) else { return false; };
        let Some((any_parent, any_hops)) = self.checked_call_parent_path(any_receiver, parameter, 0) else { return false; };
        let Some(model) = self.resolve.symbols.get(first.model.0 as usize) else { return false; };
        if selected.binding != binding.node || any.first.is_some() || any.count.is_some() ||
            any.alias.is_none() || any.predicate.is_none() || any.projection.is_some() ||
            any.cardinality_guard.is_some() || any.model != first.model ||
            any.source != first.source || any.return_node != first.return_node ||
            any.node.end > binding.node.start || any.inputs.len() != 1 || first.inputs.len() != 1 ||
            any.inputs[0].1 != first.inputs[0].1 || first_parent != any_parent ||
            first_hops != any_hops || model.name != child_name {
            return false;
        }
        self.checked_decision_sites(scenario).is_some_and(|sites| sites.iter().any(|site|
            site.stage == CheckedDecisionStage::LeadingRequire &&
            site.calls.iter().any(|call| matches!(&call.target,
                CheckedDecisionCallTarget::Builtin { id, .. } if id == "any") &&
                self.types.checked_collection_calls.get(&call.node).is_some_and(|fact|
                    fact.query == any.node && fact.model == any.model))))
    }

    /// C23 hook event operand: the predicate compares the row field against
    /// one declared text field read off the handler's `event` binding
    /// (`event.source`, never a longer chain). The event declaration owns
    /// the field and its type equals the predicate field type, so the value
    /// is handler context like `actor` and carries no transported input.
    fn query_hook_event_operand(
        &self,
        event: SymbolId,
        operand: NodeKey,
        field_ty: &ResolvedType,
    ) -> Option<()> {
        if *field_ty != ResolvedType::Scalar(Scalar::Text) {
            return None;
        }
        let operand = self.query_group(operand)?;
        let node = self.nodes.get(&operand)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let base = node
            .children
            .iter()
            .find(|child| expression(child.kind))?;
        if !matches!(
            self.query_binding(NodeKey::of(base)),
            Some(Binding::Context(ContextVar::Event))
        ) {
            return None;
        }
        let name = node
            .children
            .iter()
            .rev()
            .find(|child| child.kind == SyntaxKind::Name)?;
        let spelling = self.word(name)?;
        let SymbolKind::Event { fields } = &self.resolve.symbols.get(event.0 as usize)?.kind
        else {
            return None;
        };
        let field = fields.iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|symbol| symbol.name == spelling)
        })?;
        (self.types.symbol_types.get(&field)? == field_ty
            && self.types.node_types.get(&operand) == Some(field_ty))
        .then_some(())
    }

    /// An original scalar-equality scan selects one owning mutable row. The
    /// whole candidate domain remains retained; first is never a query limit.
    /// This inventory is available even when another original source leaf
    /// declines. Native execution still needs the complete owner/source join.
    /// Checked semantic enum case for a sealed query operand. This mirrors
    /// IR lowering so every admitted spelling seals the same authored
    /// case: bare cases lower their own name text, while qualified cases
    /// lower the final case token (`decode_member` reads
    /// `kids(node).get(2)`). Sealing raw span text would pin the
    /// qualifier and reject honest qualified source.
    fn checked_case_operand_text(&self, operand: NodeKey) -> Option<String> {
        let node = self.nodes.get(&operand)?;
        let text = &self.db.get(node.span.file)?.text;
        if node.kind == SyntaxKind::Member {
            let parts = kids(node);
            let part = parts.get(2)?;
            name_text(part, text).map(str::to_string)
        } else {
            text.get(node.span.start as usize..node.span.end as usize)
                .map(|snippet| snippet.trim().to_string())
        }
    }

    fn checked_first_reference_predicate(
        &self,
        scenario: &super::effects::ScenarioData,
        alias: NodeKey,
        alias_name: &str,
        model: SymbolId,
        predicate: NodeKey,
    ) -> Option<DisclosureFirstReferencePredicate> {
        let clauses = self.query_conjuncts(predicate, Some(8))?;
        let [identity, reference, presence] = clauses.as_slice() else {
            return None;
        };
        let (row, identity_operand) = self.query_binary(*identity, "==")?;
        let (member, reference_operand) = self.query_binary(*reference, "==")?;
        let (guard_operand, null_operand) = self.query_binary(*presence, "!=")?;
        let (identity_parameter, identity_field, identity_receiver) =
            self.query_member_operand(scenario, identity_operand)?;
        let reference_field = self.query_member(member, alias, model)?;
        let Some(Binding::Symbol(reference_parameter)) = self.query_binding(reference_operand) else {
            return None;
        };
        let (index, input) = scenario
            .params
            .iter()
            .enumerate()
            .find(|(_, input)| input.param == *reference_parameter)?;
        let ty = self.types.symbol_types.get(reference_parameter)?;
        let ResolvedType::Nullable(inner) = ty else {
            return None;
        };
        let ResolvedType::Record {
            symbol: target,
            stored: true,
        } = inner.as_ref()
        else {
            return None;
        };
        if !self.effects.models.contains_key(target)
            || !(input.default.is_none() && self.nullable_model_input(scenario, input) == Some(*target)
                || self.source_require_null_model_input(scenario, input, index))
            || !self.query_row(row, alias, model)
            || self.types.symbol_types.get(&identity_field)
                != Some(&ResolvedType::Nullable(Box::new(ResolvedType::Record {
                    symbol: model,
                    stored: true,
                })))
            || self
                .types
                .node_types
                .get(&self.query_group(identity_operand)?)
                != self.types.symbol_types.get(&identity_field)
            || self.types.symbol_types.get(&reference_field) != Some(ty)
            || self.types.node_types.get(&self.query_group(member)?) != Some(ty)
            || self
                .types
                .node_types
                .get(&self.query_group(reference_operand)?)
                != Some(ty)
            || self.types.node_types.get(&self.query_group(guard_operand)?) != Some(ty)
            || !matches!(self.query_binding(guard_operand),Some(Binding::Symbol(parameter)) if parameter==reference_parameter)
            || self.types.node_types.get(&self.query_group(null_operand)?) != Some(&ResolvedType::Null)
            || self.nodes.get(&self.query_group(null_operand)?)?.kind != SyntaxKind::Literal
            || self.word(self.nodes.get(&self.query_group(null_operand)?)?) != Some("null")
            || clauses.iter().any(|node| {
                self.types.node_types.get(node) != Some(&ResolvedType::Scalar(Scalar::Bool))
            })
        {
            return None;
        }
        Some(DisclosureFirstReferencePredicate {
            alias_name: alias_name.to_owned(),
            identity_parameter_name: self
                .resolve
                .symbols
                .get(identity_parameter.0 as usize)?
                .name
                .clone(),
            identity_field_name: self
                .resolve
                .symbols
                .get(identity_field.0 as usize)?
                .name
                .clone(),
            reference_parameter_name: self
                .resolve
                .symbols
                .get(reference_parameter.0 as usize)?
                .name
                .clone(),
            reference_field_name: self
                .resolve
                .symbols
                .get(reference_field.0 as usize)?
                .name
                .clone(),
            identity_row: self.query_group(row)?,
            identity_operand: self.query_group(identity_operand)?,
            identity_receiver,
            identity_parameter,
            identity_field,
            reference_member: self.query_group(member)?,
            reference_field,
            reference_operand: self.query_group(reference_operand)?,
            reference_parameter: *reference_parameter,
            guard_operand: self.query_group(guard_operand)?,
            null_operand: self.query_group(null_operand)?,
        })
    }

    fn checked_first_query_source(
        &self,
        scenario: &super::effects::ScenarioData,
        binding: &Effect,
    ) -> Option<DisclosureQuery> {
        // C23 hook slice: a declared-event handler with the exact void
        // single-first skeleton may prove its query facts; every other
        // trusted shape keeps the closure refusal below.
        let hook_event = self.hook_first_event(scenario);
        if scenario.read
            || (scenario.on.is_some() && hook_event.is_none())
            || binding.verb != EffectVerb::Let
            || !binding.then_effects.is_empty()
            || !binding.else_effects.is_empty()
            || !binding.match_arms.is_empty()
        {
            return None;
        }
        let call = self.query_group(binding.value?)?;
        let fact = self.types.checked_collection_calls.get(&call)?;
        let selected = self.types.selected_calls.get(&call)?;
        if fact.node != call
            || fact.builtin != "first"
            || fact.predicate.is_some()
            || !matches!(&selected.target, SelectedCallTarget::Builtin {id,overload}
                if id == "first" && *overload == fact.overload)
            || selected.arguments.len() != 1
            || selected.slots.as_slice() != [Some(0)]
            || self.query_group(selected.arguments[0])? != fact.query
        {
            return None;
        }
        let query = self.types.checked_queries.get(&fact.query)?;
        let owner = self.resolve.symbols.get(fact.model.0 as usize)?;
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return None;
        };
        let record = ResolvedType::Record {
            symbol: fact.model,
            stored: true,
        };
        let array = ResolvedType::Array {
            element: Box::new(record.clone()),
            ordered: true,
            nonempty: false,
        };
        // The grammar orders clauses `archived/as/where/order`: an
        // `archived=include` clause leads when present (the parser admits
        // only the exact `include` spelling; absence keeps the default).
        // Anything else keeps the closure refusal below.
        // Guarded archived arms lead: the unguarded `[alias, predicate,
        // order]` arm below would otherwise swallow a 3-clause
        // `[archived, alias, predicate]` shape (binding archived as the
        // alias) and fail As/Where validation, leaving the archived-3 arm
        // unreachable. Length-4 archived shapes never reach the plain arms.
        let (alias, predicate, order, archived) = match query.clauses.as_slice() {
            [archived, alias, predicate]
                if matches!(archived.kind, CheckedQueryClauseKind::Archived) =>
            {
                (alias, Some(predicate), None, Some(archived))
            }
            [archived, alias, predicate, order]
                if matches!(archived.kind, CheckedQueryClauseKind::Archived) =>
            {
                (alias, Some(predicate), Some(order), Some(archived))
            }
            // Order-only first (no where predicate): the id-ordered scan
            // records no predicate, no dependencies and no transported
            // inputs; the authored order re-verifies in the order follow-up.
            [alias, order]
                if matches!(order.kind, CheckedQueryClauseKind::Order) =>
            {
                (alias, None, Some(order), None)
            }
            [alias, predicate] => (alias, Some(predicate), None, None),
            [alias, predicate, order] => (alias, Some(predicate), Some(order), None),
            _ => return None,
        };
        // The grammar admits only the exact `archived=include` spelling, so
        // a present Archived clause always selects archived rows and its
        // absence keeps the default. No value reading is needed or possible.
        let archived = archived.is_some();
        // The C23 hook slice admits only the unordered engine-default
        // selection; authored ordering stays a sequenced follow-up.
        if hook_event.is_some() && order.is_some() {
            return None;
        }
        // The domain names its model plainly, or selects a contained child
        // through the original required parent parameter (domain
        // correspondence below). Anything else keeps the closure refusal.
        let contained_parent =
            self.checked_first_query_domain(scenario, query, fact.model, owner)?;
        if query.node != fact.query
            || query.projection.is_some()
            || query.domain_type != array
            || query.result != array
            || self.types.node_types.get(&query.domain) != Some(&array)
            || self.types.node_types.get(&fact.query) != Some(&array)
            || self.types.node_types.get(&call)
                != Some(&ResolvedType::Nullable(Box::new(record.clone())))
            || alias.node != fact.alias
            || !matches!(alias.kind, CheckedQueryClauseKind::As { .. })
            || !alias.expressions.is_empty()
            || predicate.is_some_and(|predicate| {
                predicate.kind != CheckedQueryClauseKind::Where
                    || predicate.expressions.len() != 1
            })
            || order.is_some_and(|order| {
                order.kind != CheckedQueryClauseKind::Order || order.expressions.len() != 1
            })
            || (owner.module != scenario.module
                && !self.imported_query_source(scenario.module, &owner.canonical))
        {
            return None;
        }
        // An order-only first (no where predicate) records no conjuncts, no
        // dependencies and no transported inputs; the authored order
        // re-verifies in the order follow-up below.
        let mut members: Vec<(
            NodeKey,
            SymbolId,
            ResolvedType,
            NodeKey,
            Option<(NodeKey, SymbolId)>,
        )> = Vec::new();
        let reference_predicate=predicate.and_then(|predicate|{
            let CheckedQueryClauseKind::As{name}=&alias.kind else{return None;};
            self.checked_first_reference_predicate(scenario,alias.node,name,fact.model,predicate.expressions[0])});
        let mut operand_texts: Vec<Option<String>> = Vec::new();
        let mut operand_receivers: Vec<Option<NodeKey>> = Vec::new();
        let predicate_node: Option<NodeKey> = if let Some(predicate) = predicate {
            let predicate_node = predicate.expressions[0];
            // A where predicate is one `==` conjunct or an `and` chain of them,
            // flattened order-preserving. Any other shape (`or`, comparisons,
            // calls) keeps the closure refusal below.
            let conjuncts = self.query_conjuncts(predicate_node, None)?;
        if fields.iter().any(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_none_or(|field| field.name == "id")
        }) {
            return None;
        }
        // Each conjunct admits exactly like the former single predicate: a
        // stored-row field compared against an actor/param/event operand.
        // Dependencies and transported inputs accumulate per conjunct.
        for conjunct in &conjuncts {
            if let Some(reference)=&reference_predicate {
                if *conjunct!=conjuncts[1]{continue;}
                let ty=self.types.symbol_types.get(&reference.reference_field)?.clone();
                members.push((reference.reference_member,reference.reference_field,ty,
                    reference.reference_operand,Some((reference.reference_operand,reference.reference_parameter))));
                operand_texts.push(None);operand_receivers.push(None);continue;
            }
            let (member, operand) = self.query_binary(*conjunct, "==")?;
            let field = self.query_member(member, alias.node, fact.model)?;
            let field_ty = self.types.symbol_types.get(&field)?.clone();
            let operand = self.query_group(operand)?;
            // C23 hook slice: the row field compares against one declared text
            // field of the trusted event payload. The event value is handler
            // context, so the query carries no transported input.
            let event_operand = hook_event.is_some_and(|event| {
                self.query_hook_event_operand(event, operand, &field_ty)
                    .is_some()
            });
            // Closed enum cases compare like the former scalar operands; a
            // case literal carries no transported input.
            let case_operand = matches!(&field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())
                && self.types.resolved_cases.contains(&operand);
            // Param-row member reads (`i.role`) compare against the
            // caller's admitted row field; the value is read from the
            // admitted row at predicate evaluation. The read field must
            // carry exactly the compared enum type (same domain, per the
            // type checker). The sealed path pins the exact authored
            // base and field for the predicate join.
            let member_operand: Option<((NodeKey, SymbolId), String, NodeKey)> = if event_operand
                || case_operand
            {
                None
            } else {
                self.query_member_operand(scenario, operand)
                    .filter(|(_, field, _)| self.types.symbol_types.get(field) == Some(&field_ty))
                    .and_then(|(base, field, receiver)| {
                        let base_name = &self.resolve.symbols.get(base.0 as usize)?.name;
                        let field_name = &self.resolve.symbols.get(field.0 as usize)?.name;
                        Some((
                            (operand, base),
                            format!("{base_name}.{field_name}"),
                            receiver,
                        ))
                    })
            };
            if !fields.contains(&field)
                || !(primitive_type(&field_ty)
                    || matches!(&field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                || self.types.node_types.get(&self.query_group(member)?) != Some(&field_ty)
                || (!event_operand
                    && !case_operand
                    && member_operand.is_none()
                    && self.nodes.get(&operand)?.kind != SyntaxKind::NameRef)
                || self.types.node_types.get(&operand) != Some(&field_ty)
                || self.types.node_types.get(conjunct) != Some(&ResolvedType::Scalar(Scalar::Bool))
            {
                return None;
            }
            let input = if event_operand || case_operand {
                None
            } else if matches!(
                self.query_binding(operand),
                Some(Binding::Context(ContextVar::Actor(_)))
            ) && field_ty == ResolvedType::Scalar(Scalar::User)
                && self.word(self.nodes.get(&operand)?)? == "actor"
            {
                None
            } else if let Some(member) = member_operand.as_ref() {
                Some(member.0)
            } else {
                let parameter = self.query_parameter(scenario, operand)?;
                if self.types.symbol_types.get(&parameter) != Some(&field_ty) {
                    return None;
                }
                Some((operand, parameter))
            };
            members.push((member, field, field_ty, operand, input));
            // Sealed authored operand identity for the predicate join:
            // closed cases seal the checked semantic case
            // (spelling-independent); member reads seal the exact
            // authored `base.field` path so a same-domain sibling field
            // cannot substitute.
            operand_texts.push(if case_operand {
                Some(self.checked_case_operand_text(operand)?)
            } else {
                member_operand.as_ref().map(|(_, path, _)| path.clone())
            });
            // The exact original receiver occurrence for member reads:
            // grouping and trivia shift surface spans, so the predicate
            // join compares the IR base against this recorded occurrence
            // instead of span arithmetic.
            operand_receivers.push(member_operand.as_ref().map(|(_, _, receiver)| *receiver));
        }
            Some(predicate_node)
        } else {
            None
        };
        // Bound before dependencies: the opaque query id anchors them.
        let id = self.opaque("query", fact.query, "").ok()?;
        let dependencies = members
            .iter()
            .map(|(member, field, _, _, _)| {
                self.query_dependency(
                    *member,
                    scenario.module,
                    fact.model,
                    *field,
                    DependencyRole::Control,
                    &id,
                )
            })
            .collect::<Option<Vec<_>>>()?;
        let inputs = if let Some(reference)=&reference_predicate {
            vec![(reference.identity_operand,reference.identity_parameter),
                (reference.reference_operand,reference.reference_parameter)]
        }else{members.iter().filter_map(|(_,_,_,_,input)|*input).collect::<Vec<_>>()};
        // An order-only first carries no predicate operand: the alias
        // anchors the required field, and no reader touches it while
        // dependencies and inputs stay empty (checked_first_query_predicate
        // takes the where-less branch for exactly that state).
        let operand = members.first().map(|member| member.3).unwrap_or(alias.node);
        let extra_operands = members
            .iter()
            .skip(1)
            .map(|member| member.3)
            .collect::<Vec<_>>();
        // Only authored ordering has a source node. An empty list preserves
        // the canonical stored-query created/id default at the engine boundary.
        let order = if let Some(order) = order {
            let order_node = self.query_group(order.expressions[0])?;
            if self.query_member_name(order_node, alias.node, fact.model) != Some("id")
                || self.types.node_types.get(&order_node)
                    != Some(&ResolvedType::Scalar(Scalar::Text))
                || self.nodes.get(&order.node)?.children.iter().any(|node| {
                    matches!(
                        node.kind,
                        SyntaxKind::Selectors | SyntaxKind::Descending | SyntaxKind::Path
                    )
                })
            {
                return None;
            }
            vec![DisclosureQueryOrder {
                field: None,
                field_name: "id".into(),
                descending: false,
                node: order_node,
            }]
        } else {
            Vec::new()
        };
        // Query execution is independent from its eventual result. This is
        // the actual terminal source anchor; only the checked Return census
        // may publish return identities or disclosure associations.
        let returned = scenario.effects.last()?;
        let source = self.source(scenario.module, fact.query).ok()?;
        let influences = [
            InfluenceKind::QueryExistence,
            InfluenceKind::QueryCardinality,
            InfluenceKind::QueryMembership,
            InfluenceKind::QueryOrder,
        ]
        .into_iter()
        .map(|kind| {
            Some(DisclosureInfluence {
                id: self
                    .opaque("query-influence", fact.query, &format!("{id}:{kind:?}"))
                    .ok()?,
                source: source.clone(),
                node: fact.query,
                kind,
                query_id: Some(id.clone()),
            })
        })
        .collect::<Option<Vec<_>>>()?;
        Some(DisclosureQuery {
            dependencies,
            id,
            source,
            node: fact.query,
            domain: query.domain,
            model: fact.model,
            model_name: owner.canonical.clone(),
            alias: Some(alias.node),
            predicate: predicate_node,
            inputs,
            order,
            limit: None,
            archived,
            cardinality_guard: None,
            return_node: returned.node,
            projection: None,
            first: Some(DisclosureFirstQuery {
                call,
                overload: fact.overload,
                binding: binding.node,
                operand,
                reference_predicate,
                extra_operands,
                operand_texts,
                operand_receivers,
                // DESIGN442: the guard/presence-consumed marks land in the
                // source-facts pass below, where the Require consumptions
                // for this scenario are known. Unmarked here so every
                // other shape keeps ordinary viewer behavior.
                guard_consumed: false,
                presence_consumed: false,
                target_consumed: false,
                target_decision_shape: false,
                contained_parent,
            }),
            count: None,
            influences,
        })
    }

    /// A first-query domain names its model plainly, or selects a contained
    /// child through the original required parent parameter. The qualified
    /// spelling carries no rename: the receiver names a default-free
    /// scenario Model parameter, the child stays ChildOf that parent, and
    /// the spelling names the child itself. Anything else refuses, keeping
    /// the closure fail-closed. Mirrors the count contained-Member
    /// correspondence; the predicate operand keeps its own input entry.
    fn checked_first_query_domain(
        &self,
        scenario: &super::effects::ScenarioData,
        query: &crate::analysis::types::CheckedQuery,
        model: SymbolId,
        owner: &super::resolve::Symbol,
    ) -> Option<Option<(NodeKey, SymbolId)>> {
        if matches!(self.query_binding(query.domain), Some(Binding::Symbol(actual)) if *actual == model) {
            return Some(None);
        }
        let (receiver, name) = self.count_member(query.domain)?;
        // Direct `p.C`: the receiver is the parameter itself. Navigation
        // `i.parent.C`: the receiver is the one-hop containment link off
        // a default-free stored-record parameter. The path helper seals
        // the ChildOf lineage, the declared-type match and the absence of
        // a shadowing `parent` field; exactly one authored hop is
        // admitted (a bare parameter always yields depth 0, a member
        // receiver always yields depth >= 1).
        let parameter = match self.query_parameter(scenario, receiver) {
            Some(parameter) => parameter,
            None => {
                let (base, field) = self.count_member(receiver)?;
                if field != "parent" {
                    return None;
                }
                self.query_parameter(scenario, base)?
            }
        };
        let (parent, hops) = self.checked_call_parent_path(receiver, parameter, 0)?;
        let SymbolKind::Model {
            owner: ModelOwner::ChildOf(actual_parent),
            ..
        } = &owner.kind
        else {
            return None;
        };
        if hops > 1
            || *actual_parent != parent
            || owner.name != name
            || !(self.original_reference_parameter(receiver, parameter)
                || self.original_navigation_parameter(receiver, parameter))
            || self.model_has_field(parent, name)
            || self.effects.models.get(&model)?.owner != ModelOwner::ChildOf(parent)
        {
            return None;
        }
        Some(Some((receiver, parameter)))
    }

    /// A cross-package query domain must arrive through the consumer's
    /// checked `use`: the owner canonical matches one imported provider
    /// member exactly. Same-module domains keep their existing path;
    /// aliasing never renames the source, so only the provider-side
    /// spelling counts. Nothing else crosses modules here.
    fn imported_query_source(&self, consumer: ModuleId, canonical: &str) -> bool {
        let Some(module) = self.resolve.modules.get(consumer.0 as usize) else {
            return false;
        };
        module.imports.iter().any(|import| {
            import.members.iter().any(|member| {
                import.provider.len() + 1 + member.name.len() == canonical.len()
                    && canonical.starts_with(import.provider.as_str())
                    && canonical.as_bytes().get(import.provider.len()) == Some(&b'.')
                    && canonical[import.provider.len() + 1..] == member.name
            })
        })
    }

    fn query_group(&self, mut key: NodeKey) -> Option<NodeKey> {
        for _ in 0..64 {
            let node = self.nodes.get(&key)?;
            if node.kind != SyntaxKind::Group {
                return Some(key);
            }
            let mut children = node.children.iter().filter(|child| expression(child.kind));
            key = NodeKey::of(children.next()?);
            if children.next().is_some() {
                return None;
            }
        }
        None
    }

    fn query_binding(&self, key: NodeKey) -> Option<&Binding> {
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        if !matches!(
            node.kind,
            SyntaxKind::NameRef | SyntaxKind::Path | SyntaxKind::Name
        ) {
            return None;
        }
        self.resolve.node_binding.get(&key).or_else(|| {
            node.children
                .iter()
                .find_map(|child| self.resolve.node_binding.get(&NodeKey::of(child)))
        })
    }

    fn query_parameter(
        &self,
        scenario: &super::effects::ScenarioData,
        key: NodeKey,
    ) -> Option<SymbolId> {
        let Some(Binding::Symbol(parameter)) = self.query_binding(key) else {
            return None;
        };
        scenario
            .params
            .iter()
            .find(|param| param.param == *parameter && param.default.is_none())?;
        Some(*parameter)
    }

    fn query_row(&self, key: NodeKey, alias: NodeKey, model: SymbolId) -> bool {
        let Some(grouped) = self.query_group(key) else {
            return false;
        };
        matches!(self.query_binding(grouped), Some(Binding::QueryAlias {node}) if *node == alias)
            && self.types.node_types.get(&grouped)
                == Some(&ResolvedType::Record {
                    symbol: model,
                    stored: true,
                })
    }

    fn query_binary(&self, key: NodeKey, operator: &str) -> Option<(NodeKey, NodeKey)> {
        let node = self.nodes.get(&self.query_group(key)?)?;
        if node.kind != SyntaxKind::Binary {
            return None;
        }
        let mut children = node.children.iter().filter(|child| expression(child.kind));
        let left = NodeKey::of(children.next()?);
        let right = NodeKey::of(children.next()?);
        if children.next().is_some()
            || !node.children.iter().any(|child| {
                matches!(child.kind, SyntaxKind::Name | SyntaxKind::Punct)
                    && self.db.get(child.span.file).and_then(|source| {
                        source
                            .text
                            .get(child.span.start as usize..child.span.end as usize)
                    }) == Some(operator)
            })
        {
            return None;
        }
        Some((left, right))
    }

    fn query_member_name(&self, key: NodeKey, alias: NodeKey, model: SymbolId) -> Option<&str> {
        let node = self.nodes.get(&self.query_group(key)?)?;
        if node.kind != SyntaxKind::Member {
            return None;
        }
        let base = node.children.iter().find(|child| expression(child.kind))?;
        if !self.query_row(NodeKey::of(base), alias, model) {
            return None;
        }
        let name = node
            .children
            .iter()
            .rev()
            .find(|child| child.kind == SyntaxKind::Name)?;
        self.db
            .get(name.span.file)?
            .text
            .get(name.span.start as usize..name.span.end as usize)
    }

    fn query_member(&self, key: NodeKey, alias: NodeKey, model: SymbolId) -> Option<SymbolId> {
        let name = self.query_member_name(key, alias, model)?;
        let SymbolKind::Model { fields, .. } = &self.resolve.symbols.get(model.0 as usize)?.kind
        else {
            return None;
        };
        fields.iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|symbol| {
                    symbol.name == name
                        && matches!(symbol.kind, SymbolKind::Field {owner,..} if owner == model)
                })
        })
    }

    /// Query-row derived member (`i.state`): the same row/alias proof as a
    /// stored member, but the field keeps its exact owning DeriveField
    /// declaration and complete body instead of a stored declaration.
    fn query_derived_member(&self, key: NodeKey, alias: NodeKey, model: SymbolId) -> Option<SymbolId> {
        let name = match self.query_member_name(key, alias, model) {
            Some(name) => name,
            None => return None,
        };
        let field = match self.resolve.symbols.iter().find(|field| {
            field.name == name
                && matches!(&field.kind, SymbolKind::DeriveField { model: owner, .. } if *owner == model)
        }) {
            Some(field) => field,
            None => return None,
        };
        if self.admitted_derived_read(field.id, model, &mut Vec::new()).is_none() {
            return None;
        }
        Some(field.id)
    }

    /// Param-row member operand (`i.role`): the base binds to a
    /// default-free scenario param of stored-record type, and the final
    /// field belongs to that record. Returns the base param and the
    /// field. The value travels with the invocation; the predicate join
    /// pins the exact base, field and enum correspondence.
    fn query_member_operand(
        &self,
        scenario: &super::effects::ScenarioData,
        key: NodeKey,
    ) -> Option<(SymbolId, SymbolId, NodeKey)> {
        let (receiver, name) = self.count_member(key)?;
        // Normalize grouping/trivia off the recorded receiver: the IR
        // erases groups when decoding, so the sealed occurrence is the
        // normalized base (`i` for both `i.role` and `(i).role`).
        let receiver = self.query_group(receiver)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(receiver) else {
            return None;
        };
        scenario
            .params
            .iter()
            .find(|param| param.param == *parameter && param.default.is_none())?;
        let ResolvedType::Record {
            symbol: record,
            stored: true,
        } = self.types.symbol_types.get(parameter)?
        else {
            return None;
        };
        let SymbolKind::Model { fields, .. } = &self.resolve.symbols.get(record.0 as usize)?.kind
        else {
            return None;
        };
        let field = fields.iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|symbol| {
                    symbol.name == name
                        && matches!(symbol.kind, SymbolKind::Field {owner,..} if owner == *record)
                })
        })?;
        Some((*parameter, field, receiver))
    }

    fn query_version(&self, key: NodeKey, alias: NodeKey, model: SymbolId) -> bool {
        self.query_member_name(key, alias, model) == Some("version")
    }

    fn query_count(&self, key: NodeKey) -> Option<NodeKey> {
        let selected = self.types.selected_calls.get(&self.query_group(key)?)?;
        if !matches!(&selected.target, SelectedCallTarget::Builtin {id,..} if id == "count")
            || selected.arguments.len() != 1
            || selected.slots.as_slice() != [Some(0)]
        {
            return None;
        }
        Some(selected.arguments[0])
    }

    /// Each predicate is evaluated by Values at its existing per-element site.
    /// The parent retains only whole stored Contract reads and Complete child
    /// associations; local short-circuit choices never become parent decisions.
    fn query_child_collection(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
    ) -> Option<ValuePath> {
        self.contract_collection(key, module, env, &[], 0, &mut 0)
    }

    fn contract_collection(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        aliases: &[ContractPredicateAlias],
        depth: usize,
        visits: &mut usize,
    ) -> Option<ValuePath> {
        if aliases.len() >= 2 || depth > 64 {
            return None;
        }
        let fact = self.contract_call_shape(key)?;
        let (alias_ty, domain_ty) = self.contract_query_shape(&fact, aliases)?;
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let (mut value, projection) =
            self.contract_call_domain(module, env, &fact, aliases, &domain_ty)?;
        let mut local_aliases = aliases.to_vec();
        local_aliases.push(ContractPredicateAlias {
            node: fact.alias,
            contract: fact.contract,
            ty: alias_ty,
            projection,
        });
        if self.query_child_predicate(
            fact.predicate.node,
            (module, env, &local_aliases),
            depth + 1,
            visits,
            &mut value,
        )? != boolean
        {
            return None;
        }
        value.contract_value = None;
        Some(value)
    }

    /// A contract collection call's shape: the fact with matching
    /// builtin, arguments, slots and boolean types.
    fn contract_call_shape(
        &self,
        key: NodeKey,
    ) -> Option<super::types::CheckedContractCollectionCall> {
        let fact = self
            .types
            .checked_contract_collection_calls
            .get(&key)?
            .clone();
        let selected = self.types.selected_calls.get(&key)?;
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        if fact.node != key
            || !matches!(&selected.target, SelectedCallTarget::Builtin {id, overload}
                if id == &fact.builtin && *overload == fact.overload && matches!(id.as_str(), "any" | "all"))
            || selected.arguments != fact.arguments
            || selected.slots.as_slice() != [Some(fact.slots[0]), Some(fact.slots[1])]
            || fact.slots[0] == fact.slots[1]
            || selected.arguments.len() != 2
            || self.query_group(*selected.arguments.get(fact.slots[0])?)? != fact.query
            || selected.arguments.get(fact.slots[1]) != Some(&fact.predicate.node)
            || fact.predicate.ty != boolean
            || self.types.node_types.get(&key) != Some(&boolean)
            || self.types.node_types.get(&fact.predicate.node) != Some(&boolean)
        {
            return None;
        }
        Some(fact)
    }

    /// A contract collection call's query shape: the single alias over
    /// the contract record array. Returns the alias and domain types.
    fn contract_query_shape(
        &self,
        fact: &super::types::CheckedContractCollectionCall,
        aliases: &[ContractPredicateAlias],
    ) -> Option<(ResolvedType, ResolvedType)> {
        let checked = self.types.checked_queries.get(&fact.query)?;
        let [alias] = checked.clauses.as_slice() else {
            return None;
        };
        if checked.node != fact.query
            || checked.domain != fact.domain
            || alias.node != fact.alias
            || aliases.iter().any(|prior| prior.node == fact.alias)
            || !matches!(alias.kind, CheckedQueryClauseKind::As { .. })
            || !alias.expressions.is_empty()
            || checked.projection.is_some()
            || checked.result != checked.domain_type
            || !matches!(&checked.result, ResolvedType::Array {element, ordered:true,nonempty:false}
                if matches!(element.as_ref(), ResolvedType::Record {symbol,..} if *symbol == fact.contract))
            || self.types.node_types.get(&fact.domain) != Some(&checked.domain_type)
        {
            return None;
        }
        let ResolvedType::Array { element, .. } = &checked.result else {
            return None;
        };
        Some((element.as_ref().clone(), checked.domain_type.clone()))
    }

    /// A contract collection call's domain value: a complete child's
    /// projection or the root stored Contract's single observation.
    fn contract_call_domain(
        &mut self,
        module: ModuleId,
        env: &Env,
        fact: &super::types::CheckedContractCollectionCall,
        aliases: &[ContractPredicateAlias],
        domain_ty: &ResolvedType,
    ) -> Option<(ValuePath, Option<DisclosureQueryProjection>)> {
        if let Some(call) = fact.call {
            self.contract_child_call_domain(call, env, fact, aliases, domain_ty)
        } else {
            // The root stored Contract is observed once at its actual field
            // occurrence. Copies, helper results and unrelated queries cannot
            // supply this direct Contract-member array domain.
            if !aliases.is_empty() || self.nodes.get(&fact.domain)?.kind != SyntaxKind::Member {
                return None;
            }
            let mut values = self.expr(fact.domain, module, env, &[]).ok()?;
            if values.len() != 1 {
                return None;
            }
            let value = values.pop()?;
            if !matches!(value.contract_value, Some(ContractValue::Array(contract)) if contract == fact.contract)
                || value.reads.is_empty()
            {
                return None;
            }
            Some((value, None))
        }
    }

    /// A complete child call supplies its single checked Contract projection.
    fn contract_child_call_domain(
        &mut self,
        call: NodeKey,
        env: &Env,
        fact: &super::types::CheckedContractCollectionCall,
        aliases: &[ContractPredicateAlias],
        domain_ty: &ResolvedType,
    ) -> Option<(ValuePath, Option<DisclosureQueryProjection>)> {
        if !matches!(self.query_binding(fact.domain), Some(Binding::CallAs {node}) if *node == call)
            || aliases.iter().any(|prior| prior.projection.is_some())
        {
            return None;
        }
        let child = env.get(&Local::Call(call))?.query_child?;
        if !self.complete_children.contains(&child)
            || self.types.effect_call_results.get(&call)
                != self.types.symbol_results.get(&child)
            || self
                .types
                .effect_call_results
                .get(&call)
                .and_then(Option::as_ref)
                != Some(domain_ty)
        {
            return None;
        }
        let scenario = self.effects.scenarios.get(&child)?.clone();
        self.complete_query(&scenario).ok()??;
        let queries = self.checked_query_sources(&scenario)?;
        let [query] = queries.as_slice() else {
            return None;
        };
        let projection = query.projection.as_ref()?;
        if projection.contract != fact.contract {
            return None;
        }
        Some((ValuePath::default(), Some(projection.clone())))
    }

    fn query_child_predicate(
        &mut self,
        key: NodeKey,
        scope: (ModuleId, &Env, &[ContractPredicateAlias]),
        depth: usize,
        visits: &mut usize,
        value: &mut ValuePath,
    ) -> Option<ResolvedType> {
        *visits += 1;
        if depth > 64 || *visits > 4096 {
            return None;
        }
        let grouped = self.query_group(key)?;
        let node = *self.nodes.get(&grouped)?;
        let ty = self.types.node_types.get(&grouped)?.clone();
        if self.types.node_types.get(&key) != Some(&ty) {
            return None;
        }
        match node.kind {
            SyntaxKind::Literal | SyntaxKind::NameRef | SyntaxKind::Path | SyntaxKind::Member => {
                self.child_predicate_leaf(grouped, node, &ty, scope.2)?;
            }
            _ => {
                self.child_predicate_composite(grouped, node, &ty, scope, depth, visits, value)?;
            }
        }
        Some(ty)
    }

    /// One scalar leaf in a child predicate: a scalar literal, a resolved
    /// enum case, or an alias member.
    /// (This was the `Literal`, `NameRef`/`Path`, and `Member` arms: each
    /// keeps its original guard.)
    fn child_predicate_leaf(
        &self,
        grouped: NodeKey,
        node: &SyntaxNode,
        ty: &ResolvedType,
        aliases: &[ContractPredicateAlias],
    ) -> Option<()> {
        match node.kind {
            SyntaxKind::Literal if predicate_scalar(ty) => {}
            SyntaxKind::NameRef | SyntaxKind::Path
                if self.types.resolved_cases.contains(&grouped)
                    && matches!(ty, ResolvedType::Enum { .. }) => {}
            SyntaxKind::Member => {
                self.child_predicate_member(node, ty, aliases)?;
            }
            _ => return None,
        }
        Some(())
    }

    /// One composite in a child predicate: a collection call, a unary, or
    /// a boolean binary.
    /// (This was the `Call`, `Unary`, and `Binary` arms: each keeps its
    /// original guard.)
    fn child_predicate_composite(
        &mut self,
        grouped: NodeKey,
        node: &SyntaxNode,
        ty: &ResolvedType,
        scope: (ModuleId, &Env, &[ContractPredicateAlias]),
        depth: usize,
        visits: &mut usize,
        value: &mut ValuePath,
    ) -> Option<()> {
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let (module, env, aliases) = scope;
        match node.kind {
            SyntaxKind::Call if *ty == boolean => {
                self.child_predicate_call(grouped, module, env, aliases, depth, visits, value)?;
            }
            SyntaxKind::Unary => {
                self.child_predicate_unary(scope, node, ty, depth, visits, value)?;
            }
            SyntaxKind::Binary if *ty == boolean => {
                self.child_predicate_binary(grouped, scope, depth, visits, value)?;
            }
            _ => return None,
        }
        Some(())
    }

    /// One collection call in a child predicate: the nested contract
    /// collection joins the predicate value.
    /// (This was the `Call` arm: resolve the nested collection, then join.)
    fn child_predicate_call(
        &mut self,
        grouped: NodeKey,
        module: ModuleId,
        env: &Env,
        aliases: &[ContractPredicateAlias],
        depth: usize,
        visits: &mut usize,
        value: &mut ValuePath,
    ) -> Option<()> {
        let nested =
            self.contract_collection(grouped, module, env, aliases, depth + 1, visits)?;
        value.join(&nested);
        Some(())
    }

    /// One member in a child predicate: an alias field, projected or
    /// scalar, through the contract member.
    fn child_predicate_member(
        &self,
        node: &SyntaxNode,
        ty: &ResolvedType,
        aliases: &[ContractPredicateAlias],
    ) -> Option<()> {
        let mut children = node.children.iter().filter(|child| expression(child.kind));
        let base = NodeKey::of(children.next()?);
        if children.next().is_some() {
            return None;
        }
        let Some(Binding::QueryAlias { node: bound }) = self.query_binding(base) else {
            return None;
        };
        let alias = aliases.iter().find(|alias| alias.node == *bound)?;
        if self.types.node_types.get(&base) != Some(&alias.ty) {
            return None;
        }
        let name = node
            .children
            .iter()
            .rev()
            .find(|child| child.kind == SyntaxKind::Name)?;
        let name = self
            .db
            .get(name.span.file)?
            .text
            .get(name.span.start as usize..name.span.end as usize)?;
        let field = self.contract_member(alias.contract, name, ty)?;
        Self::child_projection_check(alias, field, ty)
    }

    /// One member's projection check: projected fields match, otherwise
    /// scalars and stored records pass.
    fn child_projection_check(
        alias: &ContractPredicateAlias,
        field: SymbolId,
        ty: &ResolvedType,
    ) -> Option<()> {
        if let Some(projection) = &alias.projection {
            let projected = projection
                .fields
                .iter()
                .find(|member| member.field == field)?;
            if projected.ty != *ty
                || !(predicate_scalar(ty)
                    || matches!((ty, &projected.mapping),
                    (ResolvedType::Record {symbol,stored:true}, CheckedQueryProjectionMapping::StoredReference)
                    if *symbol == projection.model))
            {
                return None;
            }
        } else if !(predicate_scalar(ty) || matches!(ty, ResolvedType::Record { stored: true, .. }))
        {
            return None;
        }
        Some(())
    }

    /// One unary in a child predicate: `not`/`!` over booleans, `-`
    /// over int/decimal identities.
    fn child_predicate_unary(
        &mut self,
        scope: (ModuleId, &Env, &[ContractPredicateAlias]),
        node: &SyntaxNode,
        ty: &ResolvedType,
        depth: usize,
        visits: &mut usize,
        value: &mut ValuePath,
    ) -> Option<()> {
        let mut children = node.children.iter().filter(|child| expression(child.kind));
        let child = NodeKey::of(children.next()?);
        if children.next().is_some() {
            return None;
        }
        let child_ty =
            self.query_child_predicate(child, scope, depth + 1, visits, value)?;
        let operator = node
            .children
            .iter()
            .find(|child| matches!(child.kind, SyntaxKind::Name | SyntaxKind::Punct))?;
        let operator = self
            .db
            .get(operator.span.file)?
            .text
            .get(operator.span.start as usize..operator.span.end as usize)?;
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        if !((matches!(operator, "not" | "!") && *ty == boolean && child_ty == boolean)
            || (operator == "-"
                && *ty == child_ty
                && matches!(ty, ResolvedType::Scalar(Scalar::Int | Scalar::Decimal))))
        {
            return None;
        }
        Some(())
    }

    /// One binary in a child predicate: conjunctions over booleans,
    /// comparisons over scalars and stored records.
    fn child_predicate_binary(
        &mut self,
        grouped: NodeKey,
        scope: (ModuleId, &Env, &[ContractPredicateAlias]),
        depth: usize,
        visits: &mut usize,
        value: &mut ValuePath,
    ) -> Option<()> {
        let boolean = ResolvedType::Scalar(Scalar::Bool);
        let (operator, left, right) = ["and", "or", "==", "!=", "<", "<=", ">", ">="]
            .into_iter()
            .find_map(|operator| {
                self.query_binary(grouped, operator)
                    .map(|(left, right)| (operator, left, right))
            })?;
        let left = self.query_child_predicate(left, scope, depth + 1, visits, value)?;
        let right = self.query_child_predicate(right, scope, depth + 1, visits, value)?;
        if left != right
            || !(match operator {
                "and" | "or" => left == boolean,
                "==" | "!=" => {
                    predicate_scalar(&left)
                        || matches!(left, ResolvedType::Record { stored: true, .. })
                }
                _ => predicate_scalar(&left) && left != boolean,
            })
        {
            return None;
        }
        Some(())
    }

    fn contract_member(
        &self,
        contract: SymbolId,
        name: &str,
        ty: &ResolvedType,
    ) -> Option<SymbolId> {
        let owner = self.resolve.symbols.get(contract.0 as usize)?;
        let SymbolKind::Contract { fields } = &owner.kind else {
            return None;
        };
        fields.iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|symbol| {
                    symbol.name == name
                        && symbol.module == owner.module
                        && matches!(symbol.kind, SymbolKind::Field {owner,..} if owner == contract)
                        && self.types.symbol_types.get(field) == Some(ty)
                })
        })
    }

    fn query_dependency(
        &self,
        node: NodeKey,
        module: ModuleId,
        model: SymbolId,
        field: SymbolId,
        role: DependencyRole,
        query: &str,
    ) -> Option<DisclosureDependency> {
        // Group lowering erases wrappers. Retain the actual protected member
        // occurrence so capture cannot miss a grouped predicate/projection read.
        let node = self.query_group(node)?;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let declaration = self.resolve.symbols.get(field.0 as usize)?;
        if !matches!(declaration.kind, SymbolKind::Field {owner,..} if owner == model)
            || [
                "id",
                "version",
                "created",
                "updated",
                "createdBy",
                "updatedBy",
                "archivedAt",
                "parent",
            ]
            .contains(&declaration.name.as_str())
        {
            return None;
        }
        let ty = self.types.symbol_types.get(&field)?;
        let type_id = self.query_dependency_type_id(node, field, ty)?;
        Some(DisclosureDependency {
            query_id: None,
            id: self
                .opaque(
                    if role == DependencyRole::Data {
                        "query-data"
                    } else {
                        "query-control"
                    },
                    node,
                    query,
                )
                .ok()?,
            source: self.source(module, node).ok()?,
            node,
            calls: Vec::new(),
            role,
            model,
            field,
            model_name: owner.canonical.clone(),
            field_name: declaration.name.clone(),
            ty: ty.clone(),
            type_id,
        })
    }

    /// The type identity of a query dependency: stored records by
    /// canonical, nullable records suffixed, reference arrays by operand,
    /// inline enums by cases, anything else by field type.
    fn query_dependency_type_id(
        &self,
        node: NodeKey,
        field: SymbolId,
        ty: &ResolvedType,
    ) -> Option<String> {
        match ty {
            ResolvedType::Record {
                symbol,
                stored: true,
            } => Some(
                self.resolve
                    .symbols
                    .get(symbol.0 as usize)?
                    .canonical
                    .clone(),
            ),
            ResolvedType::Nullable(inner)
                if matches!(inner.as_ref(), ResolvedType::Record { stored: true, .. }) =>
            {
                let ResolvedType::Record { symbol, .. } = inner.as_ref() else {
                    return None;
                };
                Some(format!(
                    "{}?",
                    self.resolve.symbols.get(symbol.0 as usize)?.canonical
                ))
            }
            ResolvedType::Array { .. } if self.reference_operand_type_id(ty).is_some() => {
                self.reference_operand_type_id(ty)
            }
            // The State query owner recomputes an inline enum's identity
            // from the artifact field descriptor (`enum(a,b)`), so
            // first-query enum dependencies spell the cases rather than
            // the owner canonical. Sealed checks still run first; the exact
            // declaration binding stays with the schema owners.
            ResolvedType::Enum { cases, .. } if !cases.is_empty() => {
                self.field_type_id(node, field, ty).ok()?;
                Some(format!("enum({})", cases.join(",")))
            }
            _ => self.field_type_id(node, field, ty).ok(),
        }
    }

    /// Query-row derived dependency (`i.state` in an ANY filter): the same
    /// Control registration as a stored member, but the field keeps its
    /// exact owning DeriveField declaration and complete body. Only scalar
    /// and owned-enum leaves qualify; the leaf type pins the compared value.
    fn query_derived_dependency(
        &self,
        node: NodeKey,
        module: ModuleId,
        model: SymbolId,
        field: SymbolId,
        role: DependencyRole,
        query: &str,
    ) -> Option<DisclosureDependency> {
        let node = self.query_group(node)?;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let declaration = self.resolve.symbols.get(field.0 as usize)?;
        if !matches!(&declaration.kind, SymbolKind::DeriveField { model: owner, .. } if *owner == model) {
            return None;
        }
        // Declaration/type-only admission is not closure proof: the body
        // must transitively observe only its admitted row (above).
        self.admitted_derived_read(field, model, &mut Vec::new())?;
        let ty = self.types.symbol_types.get(&field)?;
        let leaf = match ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        if !(primitive_type(leaf)
            || matches!(leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
        {
            return None;
        }
        let type_id = match leaf {
            ResolvedType::Enum { cases, .. } => format!("enum({})", cases.join(",")),
            _ => self.field_type_id(node, field, ty).ok()?,
        };
        Some(DisclosureDependency {
            query_id: None,
            id: self
                .opaque(
                    if role == DependencyRole::Data {
                        "query-data"
                    } else {
                        "query-control"
                    },
                    node,
                    query,
                )
                .ok()?,
            source: self.source(module, node).ok()?,
            node,
            calls: Vec::new(),
            role,
            model,
            field,
            model_name: owner.canonical.clone(),
            field_name: declaration.name.clone(),
            ty: ty.clone(),
            type_id,
        })
    }

    /// Original leading guards whose imported helper query is evaluated by
    /// the scenario observer. This is a source inventory, not permission.
    /// Direct stored ANY retains its established query profile.
    /// A direct ANY guard reads one declared child domain behind an original
    /// required input's admitted parent path. Global scans keep their old profile.
    fn source_require_contained_any(
        &self,
        scenario: &super::effects::ScenarioData,
        query: &super::types::CheckedQuery,
        model: SymbolId,
    ) -> Option<()> {
        let (receiver, name) = self.count_member(query.domain)?;
        let (parent, _) = scenario.params.iter().find_map(|parameter| {
            self.checked_call_parent_path(receiver, parameter.param, 0)
        })?;
        let child = self.resolve.symbols.get(model.0 as usize)?;
        (child.name == name
            && child.module == scenario.module
            && matches!(child.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(owner), .. } if owner == parent)
            && self.effects.models.get(&model)?.owner == ModelOwner::ChildOf(parent))
            .then_some(())
    }

    /// Literal scalar/owned-enum alternatives are data, never transported row,
    /// File, delivery, Contract or copied lexical authority.
    fn source_require_literal_array(&self, key: NodeKey) -> Option<()> {
        let ResolvedType::Array { element, .. } = self.types.node_types.get(&key)? else {
            return None;
        };
        let element = match element.as_ref() {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            element => element,
        };
        if !primitive_type(element)
            && !matches!(element, ResolvedType::Enum { cases, .. } if !cases.is_empty())
        {
            return None;
        }
        self.nodes.get(&key)?.children.iter().filter(|node| expression(node.kind))
            .all(|node| self.query_group(NodeKey::of(node)).is_some_and(|key| {
                self.types.resolved_cases.contains(&key)
                    || self.nodes.get(&key).is_some_and(|node| node.kind == SyntaxKind::Literal)
            })).then_some(())
    }

    /// An admitted derived read: exact owning declaration, complete body,
    /// and a body observing only its admitted row (below). `visited` guards
    /// nested derived reads against dependency cycles; each top-level read
    /// starts with its own empty guard.
    fn admitted_derived_read(
        &self,
        field: SymbolId,
        model: SymbolId,
        visited: &mut Vec<(SymbolId, SymbolId)>,
    ) -> Option<()> {
        self.derived_member_body(field, model)?;
        self.derived_body_row_closure(field, model, visited)
    }

    /// Classify derived-member data in its original context. Row reads may
    /// reach only their checked owning parent; an embedded-data step admits
    /// neither stored nor unstored Model references. Native slots keep their
    /// existing, distinct row/data consumer qualification.
    fn classify_member_value(&self, ty: &ResolvedType, base: BodyValue) -> Option<BodyValue> {
        let leaf = ty.nullable_inner().unwrap_or(ty);
        if primitive_type(leaf)
            || matches!(leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty())
        {
            return Some(BodyValue::Scalar);
        }
        match leaf {
            ResolvedType::Array { element, .. } => {
                let inner = element.nullable_inner().unwrap_or(element);
                (primitive_type(inner)
                    || matches!(inner, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                    .then_some(BodyValue::Scalar)
            }
            ResolvedType::Record { symbol, stored } => {
                let target = self.resolve.symbols.get(symbol.0 as usize)?;
                if !matches!(&target.kind, SymbolKind::Model { .. }) {
                    return Some(BodyValue::Scalar);
                }
                let BodyValue::Row(row_model) = base else {
                    return None;
                };
                if !stored {
                    return Some(BodyValue::Scalar);
                }
                let owner = self.resolve.symbols.get(row_model.0 as usize)?;
                match &owner.kind {
                    SymbolKind::Model { owner: ModelOwner::ChildOf(parent), .. }
                        if *parent == *symbol => Some(BodyValue::Row(*symbol)),
                    _ => None,
                }
            }
            ResolvedType::Delivery { .. } | ResolvedType::StdDelivery { .. } => Some(BodyValue::Scalar),
            _ if matches!(base, BodyValue::Row(_)) => Some(BodyValue::Scalar),
            _ => None,
        }
    }

    /// Resolve one member step against the row it reads: the named target
    /// must be a stored leaf, the owning parent lineage, a receipt/native
    /// slot, or a transitively admitted nested derive. Unresolved targets
    /// and foreign rows keep their refusal.
    fn admitted_body_member_step(
        &self,
        model: SymbolId,
        name: &str,
        visited: &mut Vec<(SymbolId, SymbolId)>,
    ) -> Option<BodyValue> {
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let SymbolKind::Model {
            owner: model_owner,
            fields,
            ..
        } = &owner.kind
        else {
            return None;
        };
        // The owning parent link is synthetic (proven creation
        // containment, not a declared field): ChildOf models step into
        // their owner row, anything else refuses.
        if name == "parent" {
            match model_owner {
                ModelOwner::ChildOf(parent) => return Some(BodyValue::Row(*parent)),
                _ => return None,
            }
        }
        let member = fields.iter().find_map(|field| {
            let symbol = self.resolve.symbols.get(field.0 as usize)?;
            (symbol.name == name).then_some(symbol)
        })?;
        match &member.kind {
            SymbolKind::DeriveField { model: owner, .. } if *owner == model => {
                if visited.contains(&(member.id, model)) {
                    return None;
                }
                visited.push((member.id, model));
                let admitted = self.admitted_derived_read(member.id, model, visited);
                visited.pop();
                admitted?;
                let ty = self.types.symbol_types.get(&member.id)?;
                self.classify_member_value(ty, BodyValue::Row(model))
            }
            SymbolKind::Field { .. } => {
                let ty = self.types.symbol_types.get(&member.id)?;
                self.classify_member_value(ty, BodyValue::Row(model))
            }
            _ => None,
        }
    }

    /// Resolve one member step inside already-admitted data through the
    /// base's declared type.
    fn admitted_data_member_step(&self, base: NodeKey, name: &str) -> Option<BodyValue> {
        let leaf = self
            .types
            .node_types
            .get(&base)
            .map(|ty| ty.nullable_inner().unwrap_or(ty))?;
        match leaf {
            // Computed scalar data: the step stays inside admitted data.
            ty if primitive_type(ty)
                || matches!(ty, ResolvedType::Enum { cases, .. } if !cases.is_empty()) =>
            {
                Some(BodyValue::Scalar)
            }
            ResolvedType::Array { element, .. } => self.classify_member_value(element, BodyValue::Scalar),
            // Embedded contracts resolve their named member; a stored
            // model reference inside refuses below.
            // Embedded contracts resolve their named member however the
            // value is stored; a model-typed value here is unestablished.
            ResolvedType::Record { symbol, .. } => {
                let target = self.resolve.symbols.get(symbol.0 as usize)?;
                if matches!(&target.kind, SymbolKind::Model { .. }) {
                    return None;
                }
                let record = self.effects.records.get(symbol)?;
                let member = record.fields.iter().find_map(|field| {
                    let symbol = self.resolve.symbols.get(field.field.0 as usize)?;
                    (symbol.name == name).then_some(field.field)
                })?;
                let ty = self.types.symbol_types.get(&member)?;
                self.classify_member_value(ty, BodyValue::Scalar)
            }
            // Native objects resolve their named member the same way.
            ResolvedType::Object(fields) | ResolvedType::StdNominal { fields, .. } => {
                let (_, ty) = fields.iter().find(|(field, _)| field == name)?;
                self.classify_member_value(ty, BodyValue::Scalar)
            }
            // Receipt slots stay admitted: the exact-receipt census and
            // the codegen seal still qualify the actual read.
            ResolvedType::Delivery { .. } | ResolvedType::StdDelivery { .. } => {
                Some(BodyValue::Scalar)
            }
            _ => None,
        }
    }

    /// Prove one body expression observes only admitted values: member
    /// targets resolve (above), `row` grounds at the admitted row model,
    /// literals/enum cases/booleans are data, operators combine proven
    /// children. Calls, queries, branches and foreign names keep refusal.
    fn admitted_body_value(
        &self,
        key: NodeKey,
        row_model: SymbolId,
        visited: &mut Vec<(SymbolId, SymbolId)>,
        depth: usize,
    ) -> Option<BodyValue> {
        // Iterative worklist predecessors capped traversal steps; the
        // recursive proof caps nesting instead, so adversarial deep
        // expressions decline instead of overflowing the stack.
        if depth > 128 || visited.len() > 32 {
            return None;
        }
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        match node.kind {
            SyntaxKind::Member => {
                self.admitted_body_member(key, row_model, visited, depth)
            }
            SyntaxKind::NameRef => self.admitted_body_nameref(key, node, row_model),
            SyntaxKind::Literal => Some(BodyValue::Scalar),
            SyntaxKind::Binary | SyntaxKind::Unary | SyntaxKind::Array | SyntaxKind::Group => {
                for part in node.children.iter().filter(|part| expression(part.kind)) {
                    self.admitted_body_value(NodeKey::of(part), row_model, visited, depth + 1)?;
                }
                Some(BodyValue::Scalar)
            }
            _ => None,
        }
    }

    /// Prove one member access in a body observes only admitted values:
    /// row steps resolve their target, data steps resolve through the
    /// base's declared type.
    fn admitted_body_member(
        &self,
        key: NodeKey,
        row_model: SymbolId,
        visited: &mut Vec<(SymbolId, SymbolId)>,
        depth: usize,
    ) -> Option<BodyValue> {
        let (base, name) = self.count_member(key)?;
        let grouped_base = self.query_group(base)?;
        match self.admitted_body_value(base, row_model, visited, depth + 1)? {
            // Row steps resolve their named target (above):
            // foreign rows and unproven nested derives refuse.
            BodyValue::Row(model) => self.admitted_body_member_step(model, name, visited),
            // Steps inside already-admitted data resolve through
            // the base's declared type: computed scalar data stays
            // admitted, embedded contracts and native objects
            // resolve their named member, receipt slots stay
            // admitted for the existing consumer to qualify, and
            // unestablished reference paths (including model
            // references hidden inside embedded values) refuse.
            BodyValue::Scalar => self.admitted_data_member_step(grouped_base, name),
        }
    }

    /// Prove one name reference in a body is admitted: the `row` model,
    /// literals, enum cases and booleans.
    fn admitted_body_nameref(
        &self,
        key: NodeKey,
        node: &SyntaxNode,
        row_model: SymbolId,
    ) -> Option<BodyValue> {
        let word = self.word(node)?;
        if word == "row" {
            match self.query_binding(key) {
                Some(Binding::Context(ContextVar::RowModel(actual))) if *actual == row_model => {
                    Some(BodyValue::Row(*actual))
                }
                _ => None,
            }
        } else if word == "true" || word == "false" || word == "null"
            || self.types.resolved_cases.contains(&key)
        {
            Some(BodyValue::Scalar)
        } else {
            None
        }
    }

    /// A derived body observes only its admitted row: member chains rooted
    /// at `row` with resolved targets (above), literals, enum cases and
    /// pure operators. Calls, queries, branches and foreign names keep
    /// their refusal, so the recorded row read is the body's complete
    /// observation.
    fn derived_body_row_closure(
        &self,
        field: SymbolId,
        model: SymbolId,
        visited: &mut Vec<(SymbolId, SymbolId)>,
    ) -> Option<()> {
        let root = self.query_group(self.effects.derives.get(&field)?.expr?)?;
        // The body's value may be data or (degenerately) the row itself;
        // every member step inside already resolved above.
        self.admitted_body_value(root, model, visited, 0).map(|_| ())
    }

    /// A derived member read keeps its exact owning declaration and complete
    /// body. Only parameter-free bodies over the admitted row qualify; the
    /// codegen seal re-verifies the complete member against fresh IR.
    fn derived_member_body(&self, field: SymbolId, model: SymbolId) -> Option<()> {
        let derive = self.effects.derives.get(&field)?;
        let declaration = self.resolve.symbols.get(field.0 as usize)?;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        if derive.derive != field
            || derive.model != Some(model)
            || !derive.params.is_empty()
            || declaration.module != derive.module
            || owner.module != derive.module
            || !matches!(&owner.kind, SymbolKind::Model { fields, .. } if fields.contains(&field))
            || !matches!(&declaration.kind, SymbolKind::DeriveField { model: owner, .. } if *owner == model)
        {
            return None;
        }
        let body = self.query_group(derive.expr?)?;
        if self.types.node_types.get(&body)? != self.types.symbol_types.get(&field)? {
            return None;
        }
        Some(())
    }

    /// The source observer's expression grammar is independent of call/domain
    /// ownership. Arrays contribute only the checked literal alternatives above.
    fn source_require_expression_shape(&self, key: NodeKey) -> Option<()> {
        let node = self.nodes.get(&key)?;
        if node.kind == SyntaxKind::Array {
            return self.source_require_literal_array(key);
        }
        (!expression(node.kind) || matches!(node.kind,
            SyntaxKind::Literal | SyntaxKind::NameRef | SyntaxKind::Group
                | SyntaxKind::Member | SyntaxKind::Call | SyntaxKind::Unary
                | SyntaxKind::Binary | SyntaxKind::Query)).then_some(())
    }

    /// Original immutable Values inputs carry no row, File, delivery or
    /// opaque-provider authority. Resolve every contract leaf in this check.
    fn source_require_plain_value(&self, ty: &ResolvedType, depth: usize) -> bool {
        if depth >= 16 { return false; }
        match ty {
            ResolvedType::Scalar(scalar) => !matches!(scalar, Scalar::File | Scalar::Secret | Scalar::Member | Scalar::Json | Scalar::Bytes),
            ResolvedType::Nullable(inner) => self.source_require_plain_value(inner, depth + 1),
            ResolvedType::Array { element, ordered: true, .. } => self.source_require_plain_value(element, depth + 1),
            ResolvedType::Object(fields) => fields.len() <= 200 && fields.iter().all(|(_, ty)| self.source_require_plain_value(ty, depth + 1)),
            ResolvedType::Record { symbol, .. } => match self.resolve.symbols.get(symbol.0 as usize).map(|symbol| &symbol.kind) {
                Some(SymbolKind::Contract { fields, .. }) => !fields.is_empty() && fields.len() <= 200
                    && fields.iter().all(|field| self.types.symbol_types.get(field).is_some_and(|ty| self.source_require_plain_value(ty, depth + 1))),
                _ => false,
            },
            _ => false,
        }
    }

    fn source_require_value_parameter(&self, scenario: &super::effects::ScenarioData,
        parameter: &super::effects::ParamData) -> bool {
        let Some(ty) = self.types.symbol_types.get(&parameter.param) else { return false; };
        if !self.source_require_plain_value(ty, 0) || self.types.value_constraints.contains_key(&parameter.param) { return false; }
        let Some(default) = parameter.default else { return true; };
        let Some(node) = self.nodes.get(&default) else { return false; };
        match node.kind {
            SyntaxKind::Literal => self.types.node_types.get(&default) == Some(ty)
                || matches!(ty, ResolvedType::Nullable(_)) && self.types.node_types.get(&default) == Some(&ResolvedType::Null),
            SyntaxKind::Array => matches!(ty, ResolvedType::Array { .. })
                && !node.children.iter().any(|child| expression(child.kind))
                && self.types.node_types.get(&default) == Some(ty),
            SyntaxKind::NameRef => self.explicit_param_reference_default(parameter, scenario, default),
            _ => false,
        }
    }

    fn source_require_value_query(&self, query: &super::types::CheckedQuery) -> bool {
        matches!(&query.domain_type, ResolvedType::Array { element, ordered: true, .. }
            if self.source_require_plain_value(element, 0))
            && self.types.node_types.get(&query.domain) == Some(&query.domain_type)
            && matches!(self.query_binding(query.domain), Some(Binding::Symbol(parameter))
                if matches!(self.resolve.symbols.get(parameter.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Param { .. })))
            && query.clauses.iter().all(|clause| matches!(clause.kind,
                CheckedQueryClauseKind::As { .. } | CheckedQueryClauseKind::Where | CheckedQueryClauseKind::Select | CheckedQueryClauseKind::Order))
            && query.clauses.iter().filter(|clause| matches!(clause.kind, CheckedQueryClauseKind::As { .. })).count() == 1
    }

    /// A bounded original dates expression carries only immutable civil
    /// dates. It creates no stored-model query or additional read authority.
    fn source_require_dates_call(&self, node: NodeKey) -> bool {
        let Some(call)=self.types.selected_calls.get(&node) else{return false;};
        if !matches!(&call.target,SelectedCallTarget::Builtin{id,..} if id=="dates")
            || call.slots.as_slice()!=[Some(0),Some(1),Some(2)] || call.arguments.len()!=3 {return false;}
        let maximum=call.arguments[2];
        self.nodes.get(&maximum).is_some_and(|node|node.kind==SyntaxKind::Literal
            && self.word(node).and_then(|word|word.parse::<usize>().ok()).is_some_and(|value|(1..=1000).contains(&value)))
            && self.types.node_types.get(&maximum)==Some(&ResolvedType::Scalar(Scalar::Int))
            && call.arguments[..2].iter().all(|node|self.types.node_types.get(node)==Some(&ResolvedType::Scalar(Scalar::Date)))
            && self.types.node_types.get(&node)==Some(&ResolvedType::Array{element:Box::new(ResolvedType::Scalar(Scalar::Date)),ordered:true,nonempty:false})
    }

    fn source_require_dates_query(&self, query:&super::types::CheckedQuery) -> bool {
        self.source_require_dates_call(query.domain)
            && query.result==query.domain_type && query.projection.is_none()
            && self.types.node_types.get(&query.domain)==Some(&query.domain_type)
            && matches!(query.clauses.as_slice(),[clause] if matches!(&clause.kind,CheckedQueryClauseKind::As{name} if !name.is_empty()) && clause.expressions.is_empty())
    }

    fn source_require_input(&self, ty: &ResolvedType) -> bool {
        if self.source_require_plain_value(ty, 0) { return true; }
        match ty {
            ResolvedType::Nullable(inner) if matches!(inner.as_ref(), ResolvedType::Record { stored: true, .. }) =>
                self.source_require_input(inner),
            ResolvedType::Scalar(_) => true,
            ResolvedType::Array { element, ordered: true, nonempty: false }
                if matches!(element.as_ref(), ResolvedType::Record { stored: true, .. }) =>
                    self.source_require_input(element),
            // Values admits these non-File primitive arrays before the
            // original observer runs; they carry no model/query authority.
            ResolvedType::Array { element, ordered: true, nonempty: false }
                if element.as_ref() == &ResolvedType::Scalar(Scalar::Text) => true,
            ResolvedType::Record {
                symbol,
                stored: true,
            } => self
                .resolve
                .symbols
                .get(symbol.0 as usize)
                .is_some_and(|decl| matches!(decl.kind, SymbolKind::Model { .. })),
            _ => false,
        }
    }

    /// A helper's role parameter may reuse one declared enum field. Keep the
    /// original field domain and exact checked type: an arbitrary enum alias,
    /// default, or constrained value is not an owner-decision input here.
    fn source_require_owned_enum_formal(&self, parameter: &super::effects::ParamData) -> bool {
        let Some(ty @ ResolvedType::Enum { cases, .. }) =
            self.types.symbol_types.get(&parameter.param) else {
            return false;
        };
        if cases.is_empty()
            || parameter.default.is_some()
            || self.types.value_constraints.contains_key(&parameter.param)
        {
            return false;
        }
        let Some(node) = self.nodes.get(&parameter.type_node) else {
            return false;
        };
        if node.kind != SyntaxKind::NamedType {
            return false;
        }
        let Some(path) = node.children.iter().find(|child| child.kind == SyntaxKind::Path) else {
            return false;
        };
        let Some(TypeRef::FieldChain { fields, .. }) =
            self.resolve.node_typeref.get(&NodeKey::of(path)) else {
            return false;
        };
        let [field] = fields.as_slice() else {
            return false;
        };
        self.types.field_reuse_sources.get(&parameter.param) == Some(field)
            && self.types.symbol_types.get(field) == Some(ty)
            && matches!(
                self.resolve.symbols.get(field.0 as usize).map(|symbol| &symbol.kind),
                Some(SymbolKind::Field { .. })
            )
    }

    /// An unread original nullable File or ordered File array stays with its
    /// canonical File assignment path. Its exact declaration/default remains
    /// checked, but no observer receives or copies the File values.
    fn source_require_unread_file_input(
        &self,
        scenario: &super::effects::ScenarioData,
        parameter: &super::effects::ParamData,
        index: usize,
    ) -> bool {
        let Some(symbol) = self.resolve.symbols.get(parameter.param.0 as usize) else {
            return false;
        };
        let SymbolKind::Param { owner, index: declared, type_node } = symbol.kind else {
            return false;
        };
        let Some(resolved) = self.types.symbol_types.get(&parameter.param) else { return false; };
        let nullable = matches!(resolved, ResolvedType::Nullable(inner)
            if inner.as_ref() == &ResolvedType::Scalar(Scalar::File));
        let array = matches!(resolved, ResolvedType::Array { element, ordered: true, nonempty: false }
            if element.as_ref() == &ResolvedType::Scalar(Scalar::File));
        if (!nullable && !array) || owner != scenario.scenario || symbol.module != scenario.module
            || declared != index || type_node != parameter.type_node
        {
            return false;
        }
        let Some(ty) = self.nodes.get(&parameter.type_node) else { return false; };
        if nullable {
            // Preserve the original singular nullable File profile.
            let mut named = ty.children.iter().filter(|child| child.kind == SyntaxKind::NamedType);
            let Some(named_type) = named.next() else { return false; };
            if ty.kind != SyntaxKind::NullableType || named.next().is_some()
                || !self.direct_builtin_parameter_type(NodeKey::of(named_type), Scalar::File)
                || self.types.value_constraints.contains_key(&parameter.param)
                || self.types.field_reuse_sources.contains_key(&parameter.param)
            {
                return false;
            }
        } else if let Some(field) = self.types.field_reuse_sources.get(&parameter.param) {
            // Reuse retains the declared field's File-array identity and all
            // inherited bounds. Canonical admission still validates those bounds.
            let Some(path) = ty.children.iter().find(|child| child.kind == SyntaxKind::Path) else { return false; };
            if ty.kind != SyntaxKind::NamedType
                || !matches!(self.resolve.node_typeref.get(&NodeKey::of(path)),
                    Some(TypeRef::FieldChain { fields, .. }) if fields.as_slice() == [*field])
                || self.types.symbol_types.get(field) != Some(resolved)
                || !matches!(self.resolve.symbols.get(field.0 as usize).map(|source| &source.kind),
                    Some(SymbolKind::Field { .. }))
            {
                return false;
            }
        } else {
            let mut named = ty.children.iter().filter(|child| child.kind == SyntaxKind::NamedType);
            let Some(named_type) = named.next() else { return false; };
            if ty.kind != SyntaxKind::ArrayType || named.next().is_some()
                || !self.direct_builtin_parameter_type(NodeKey::of(named_type), Scalar::File)
            {
                return false;
            }
        }
        if let Some(default) = parameter.default {
            let Some(literal) = self.nodes.get(&default) else { return false; };
            if !self.source_anchor(scenario, default) || if nullable {
                literal.kind != SyntaxKind::Literal || self.word(literal) != Some("null")
                    || self.types.node_types.get(&default) != Some(&ResolvedType::Null)
            } else {
                literal.kind != SyntaxKind::Array
                    || literal.children.iter().any(|child| expression(child.kind))
                    || self.types.node_types.get(&default) != Some(resolved)
            } {
                return false;
            }
        }
        let Some(sites) = self.checked_decision_sites(scenario) else { return false; };
        let mut pending = sites.into_iter()
            .filter(|site| matches!(site.stage, CheckedDecisionStage::LeadingRequire
                | CheckedDecisionStage::BodyRequire | CheckedDecisionStage::BodyCondition))
            .map(|site| site.node).collect::<Vec<_>>();
        let mut visited = 0usize;
        while let Some(key) = pending.pop() {
            visited += 1;
            if visited > 16384 || matches!(self.query_binding(key),
                Some(Binding::Symbol(id)) if *id == parameter.param) {
                return false;
            }
            let Some(node) = self.nodes.get(&key) else { return false; };
            pending.extend(node.children.iter().map(NodeKey::of));
        }
        true
    }

    /// These defaults/nullable enums carry admitted primitive values, never
    /// a nullable model or a query capability. Preserve the declared source
    /// field identity and accept only the checked literal empty-array default.
    fn source_require_optional_primitive_input(&self, parameter: &super::effects::ParamData) -> bool {
        let Some(ty) = self.types.symbol_types.get(&parameter.param) else { return false; };
        if self.types.value_constraints.contains_key(&parameter.param) { return false; }
        match ty {
            ResolvedType::Array { element, ordered: true, nonempty: false }
                if element.as_ref() == &ResolvedType::Scalar(Scalar::Text) => {
                let Some(default) = parameter.default else { return false; };
                self.nodes.get(&default).is_some_and(|node| node.kind == SyntaxKind::Array
                    && !node.children.iter().any(|child| expression(child.kind)))
                    && self.types.node_types.get(&default) == Some(ty)
            }
            ResolvedType::Nullable(inner) if matches!(inner.as_ref(), ResolvedType::Enum { cases, .. } if !cases.is_empty())
                && parameter.default.is_none() => {
                let Some(field) = self.types.field_reuse_sources.get(&parameter.param) else { return false; };
                let Some(node) = self.nodes.get(&parameter.type_node) else { return false; };
                let Some(named) = node.children.iter().find(|node| node.kind == SyntaxKind::NamedType) else { return false; };
                let Some(path) = named.children.iter().find(|node| node.kind == SyntaxKind::Path) else { return false; };
                node.kind == SyntaxKind::NullableType
                    && matches!(self.resolve.node_typeref.get(&NodeKey::of(path)),
                        Some(TypeRef::FieldChain { fields, .. }) if fields.as_slice() == [*field])
                    && self.types.symbol_types.get(field) == Some(inner.as_ref())
                    && matches!(self.resolve.symbols.get(field.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Field { .. }))
            }
            _ => false,
        }
    }

    /// A nullable Model formal with implicit null or a literal-null default
    /// may cross this observer. Admission still checks any supplied reference;
    /// null contributes neither a row nor a version witness.
    fn source_require_null_model_input(
        &self, scenario: &super::effects::ScenarioData,
        parameter: &super::effects::ParamData, index: usize,
    ) -> bool {
        let Some(symbol)=self.resolve.symbols.get(parameter.param.0 as usize) else{return false;};
        let SymbolKind::Param{owner,index:declared,type_node}=&symbol.kind else{return false;};
        let Some(ResolvedType::Nullable(inner))=self.types.symbol_types.get(&parameter.param) else{return false;};
        let ResolvedType::Record{symbol:target,stored:true}=inner.as_ref() else{return false;};
        if parameter.default.is_none(){
            return *declared==index && !self.types.value_constraints.contains_key(&parameter.param)
                && self.nullable_model_input(scenario,parameter)==Some(*target);
        }
        let Some(default)=parameter.default else{return false;};
        let Some(literal)=self.nodes.get(&default) else{return false;};
        *owner==scenario.scenario && *declared==index && symbol.module==scenario.module && *type_node==parameter.type_node
            && self.effects.models.contains_key(target)
            && matches!(self.resolve.symbols.get(target.0 as usize).map(|item|&item.kind),Some(SymbolKind::Model{..}))
            && !self.types.value_constraints.contains_key(&parameter.param)
            && default.file==scenario.node.file && literal.kind==SyntaxKind::Literal && self.word(literal)==Some("null")
            && self.types.node_types.get(&default)==Some(&ResolvedType::Null)

    }

    fn source_require_params_ok(&self, scenario: &super::effects::ScenarioData) -> bool {
        !scenario.params.iter().enumerate().any(|(index, param)| {
            (param.default.is_some()
                || self.types.symbol_types.get(&param.param)
                    .is_none_or(|ty| !self.source_require_input(ty)
                        && !self.source_require_owned_enum_formal(param)))
                && !self.source_require_optional_primitive_input(param)
                && !self.source_require_value_parameter(scenario, param)
                && !self.source_require_unread_file_input(scenario, param, index)
                && !self.source_require_null_model_input(scenario, param, index)

        }) && scenario
            .params
            .iter()
            .filter(|param| {
                matches!(self.types.symbol_types.get(&param.param),
                    Some(ResolvedType::Record {stored: true, ..}))
            })
            .count()
            != 0
    }

    fn source_require_before_write(&self, effect: &Effect) -> bool {
        effect.match_arms.is_empty()
            && match effect.verb {
                EffectVerb::Let | EffectVerb::Require => {
                    effect.then_effects.is_empty() && effect.else_effects.is_empty()
                }
                EffectVerb::If => effect
                    .then_effects
                    .iter()
                    .chain(&effect.else_effects)
                    .all(|nested| {
                        matches!(nested.verb, EffectVerb::Require | EffectVerb::Return)
                            && nested.then_effects.is_empty()
                            && nested.else_effects.is_empty()
                            && nested.match_arms.is_empty()
                    }),
                _ => false,
            }
    }

    fn source_require_aggregate_decl(
        &self,
        id: SymbolId,
        model: SymbolId,
    ) -> Option<NodeKey> {
        let derive = self.effects.derives.get(&id)?;
        let declaration = self.resolve.symbols.get(id.0 as usize)?;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        if derive.derive != id
            || derive.model != Some(model)
            || !derive.params.is_empty()
            || declaration.module != derive.module
            || owner.module != derive.module
            || !matches!(&owner.kind, SymbolKind::Model { fields, .. } if fields.contains(&id))
            || !matches!(declaration.kind, SymbolKind::DeriveField { model: owner, .. } if owner == model)
        {
            return None;
        }
        self.query_group(derive.expr?)
    }

    fn source_require_aggregate_call(
        &self,
        id: SymbolId,
        body: NodeKey,
    ) -> Option<(
        &'a super::types::CheckedQuery,
        &'a super::types::CheckedQueryClause,
        &'a super::types::CheckedQueryClause,
        SymbolId,
    )> {
        let selected = self.types.selected_calls.get(&body)?;
        if !matches!(&selected.target, SelectedCallTarget::Builtin { id, .. } if id == "sum")
            || selected.arguments.len() != 1
            || selected.slots.as_slice() != [Some(0)]
            || self.types.node_types.get(&body) != self.types.symbol_types.get(&id)
            || !self.types.symbol_types.get(&id).is_some_and(primitive_type)
        {
            return None;
        }
        let query = self
            .types
            .checked_queries
            .get(&self.query_group(selected.arguments[0])?)?;
        let [alias, select] = query.clauses.as_slice() else {
            return None;
        };
        let (row, _) = self.count_member(query.domain)?;
        let ResolvedType::Array {
            element,
            ordered: true,
            nonempty: false,
        } = &query.domain_type
        else {
            return None;
        };
        let ResolvedType::Record {
            symbol: child,
            stored: true,
        } = element.as_ref()
        else {
            return None;
        };
        let _ = row;
        Some((query, alias, select, *child))
    }

    fn source_require_aggregate_domain(
        &self,
        query: &super::types::CheckedQuery,
        alias: &super::types::CheckedQueryClause,
        select: &super::types::CheckedQueryClause,
        child: SymbolId,
        model: SymbolId,
    ) -> Option<()> {
        let (row, child_name) = self.count_member(query.domain)?;
        let child_decl = self.resolve.symbols.get(child.0 as usize)?;
        if !matches!(self.query_binding(row), Some(Binding::Context(ContextVar::RowModel(actual))) if *actual == model)
            || child_decl.name != child_name
            || !matches!(child_decl.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(parent), .. } if parent == model)
            || !matches!(alias.kind, CheckedQueryClauseKind::As { .. })
            || !alias.expressions.is_empty()
            || select.kind != CheckedQueryClauseKind::Select
            || select.expressions.len() != 1
            || query.projection.is_some()
        {
            return None;
        }
        let field = self.query_member(select.expressions[0], alias.node, child)?;
        if !matches!(self.resolve.symbols.get(field.0 as usize)?.kind, SymbolKind::Field { owner, .. } if owner == child)
            || !self
                .types
                .symbol_types
                .get(&field)
                .is_some_and(primitive_type)
            || self.types.node_types.get(&select.expressions[0])
                != self.types.symbol_types.get(&field)
        {
            return None;
        }
        Some(())
    }

    /// A stored integer minus a filtered census of its own children keeps
    /// the initial owner stage. The predicate may read only that child’s
    /// original stored scalar fields and `now`; it acquires no foreign rows.
    fn source_require_remaining_count_field(&self, id: SymbolId, model: SymbolId) -> Option<()> {
        let body = self.source_require_aggregate_decl(id, model)?;
        let (base, aggregate) = self.query_binary(body, "-")?;
        let integer = ResolvedType::Scalar(Scalar::Int);
        let (row, name) = self.count_member(base)?;
        let field = self
            .effects
            .models
            .get(&model)?
            .fields
            .iter()
            .find(|field| {
                self.resolve
                    .symbols
                    .get(field.field.0 as usize)
                    .is_some_and(|symbol| symbol.name == name)
            })?;
        let selected = self.types.selected_calls.get(&aggregate)?;
        if !matches!(self.resolve.symbols.get(field.field.0 as usize)?.kind,
                SymbolKind::Field { owner, .. } if owner == model)
            || self.types.symbol_types.get(&id) != Some(&integer)
            || self.types.symbol_types.get(&field.field) != Some(&integer)
            || self.types.node_types.get(&base) != Some(&integer)
            || self.types.node_types.get(&aggregate) != Some(&integer)
            || !matches!(self.query_binding(row), Some(Binding::Context(ContextVar::RowModel(actual))) if *actual == model)
            || !matches!(&selected.target, SelectedCallTarget::Builtin { id, overload: 0 } if id == "count")
            || selected.arguments.len() != 1
            || selected.slots.as_slice() != [Some(0)]
        {
            return None;
        }
        let query = self
            .types
            .checked_queries
            .get(&self.query_group(selected.arguments[0])?)?;
        let [alias, filter] = query.clauses.as_slice() else {
            return None;
        };
        let [predicate] = filter.expressions.as_slice() else {
            return None;
        };
        let (owner, child_name) = self.count_member(query.domain)?;
        let ResolvedType::Array {
            element,
            ordered: true,
            nonempty: false,
        } = &query.domain_type
        else {
            return None;
        };
        let ResolvedType::Record {
            symbol: child,
            stored: true,
        } = element.as_ref()
        else {
            return None;
        };
        let declaration = self.resolve.symbols.get(child.0 as usize)?;
        if !matches!(self.query_binding(owner), Some(Binding::Context(ContextVar::RowModel(actual))) if *actual == model)
            || declaration.name != child_name
            || !matches!(declaration.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(parent), .. } if parent == model)
            || self.effects.models.get(child)?.owner != ModelOwner::ChildOf(model)
            || !matches!(alias.kind, CheckedQueryClauseKind::As { .. })
            || !alias.expressions.is_empty()
            || filter.kind != CheckedQueryClauseKind::Where
            || query.projection.is_some()
            || self.types.node_types.get(predicate) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        let mut pending = vec![*predicate];
        let mut steps = 0;
        while let Some(key) = pending.pop() {
            steps += 1;
            if steps > 1024 {
                return None;
            }
            let node = self.nodes.get(&key)?;
            self.source_require_expression_shape(key)?;
            if matches!(node.kind, SyntaxKind::Call | SyntaxKind::Query) {
                return None;
            }
            if node.kind == SyntaxKind::Member {
                let field = self.query_member(key, alias.node, *child)?;
                let ty = self.types.symbol_types.get(&field)?;
                if !matches!(self.resolve.symbols.get(field.0 as usize)?.kind, SymbolKind::Field { owner, .. } if owner == *child)
                    || !(primitive_type(ty)
                        || matches!(ty, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                    || self.types.node_types.get(&key) != Some(ty)
                {
                    return None;
                }
            }
            if node.kind == SyntaxKind::NameRef {
                match self.query_binding(key) {
                    Some(Binding::QueryAlias { node }) if *node == alias.node => {}
                    Some(Binding::Context(ContextVar::Now)) => {}
                    // An unbound checked enum case has its original literal type.
                    _ if self.types.resolved_cases.contains(&key) => {}
                    _ => return None,
                }
            }
            pending.extend(node.children.iter().map(NodeKey::of));
        }
        Some(())
    }

    /// Currency comes from this row's stored currency or stored Money field.
    /// A same-typed parent/foreign expression carries no aggregate authority.
    fn source_require_money_currency(&self, key:NodeKey, model:SymbolId)->Option<()> {
        let key=self.query_group(key)?;
        if self.types.node_types.get(&key)!=Some(&ResolvedType::Scalar(Scalar::Currency)){return None;}
        let (base,name)=self.count_member(key)?;
        let (row,name,expected)=if name=="currency" && self.types.node_types.get(&base)==Some(&ResolvedType::Scalar(Scalar::Money)) {
            let (row,name)=self.count_member(base)?;(row,name,ResolvedType::Scalar(Scalar::Money))
        } else {(base,name,ResolvedType::Scalar(Scalar::Currency))};
        if !matches!(self.query_binding(row),Some(Binding::Context(ContextVar::RowModel(owner))) if *owner==model){return None;}
        let field=self.effects.models.get(&model)?.fields.iter().find(|field|
            self.resolve.symbols.get(field.field.0 as usize).is_some_and(|declaration|declaration.name==name))?;
        (matches!(self.resolve.symbols.get(field.field.0 as usize)?.kind,SymbolKind::Field{owner,..} if owner==model)
            && self.types.symbol_types.get(&field.field)==Some(&expected)).then_some(())
    }

    /// This source-Require-only algebra keeps complete same-owner child
    /// censuses, nested derived selectors and nullable Money fallbacks. The
    /// ordinary DATA closure does not inherit this Boolean observer proof.
    fn source_require_money_aggregate(&self,body:NodeKey,model:SymbolId,depth:usize)->Option<()> {
        self.source_require_money_value(body,model,depth,&mut Vec::new(),&mut 4096)
    }

    fn source_require_money_value(&self, body:NodeKey, model:SymbolId, depth:usize,
        visited:&mut Vec<(SymbolId,SymbolId)>,budget:&mut usize)->Option<()> {
        if depth>32 || *budget==0{return None;} *budget-=1;
        let body=self.query_group(body)?;
        let money=ResolvedType::Scalar(Scalar::Money);
        if self.types.node_types.get(&body)!=Some(&money){return None;}
        if let Some((base,name))=self.count_member(body) {
            if !matches!(self.query_binding(base),Some(Binding::Context(ContextVar::RowModel(owner))) if *owner==model){return None;}
            let SymbolKind::Model{fields,..}=&self.resolve.symbols.get(model.0 as usize)?.kind else{return None;};
            let field=fields.iter().find_map(|id|self.resolve.symbols.get(id.0 as usize).filter(|field|field.name==name))?;
            if self.types.symbol_types.get(&field.id)!=Some(&money){return None;}
            return match field.kind {
                SymbolKind::Field{owner,..} if owner==model=>Some(()),
                SymbolKind::DeriveField{model:owner,..} if owner==model && !visited.contains(&(field.id,model))=>{
                    let expr=self.source_require_aggregate_decl(field.id,model)?;
                    visited.push((field.id,model));
                    let result=self.source_require_money_value(expr,model,depth+1,visited,budget);
                    visited.pop();result
                },
                _=>None,
            };
        }
        if let Some((left,right))=self.query_binary(body,"+").or_else(||self.query_binary(body,"-")) {
            self.source_require_money_value(left,model,depth+1,visited,budget)?;
            return self.source_require_money_value(right,model,depth+1,visited,budget);
        }
        let selected=self.types.selected_calls.get(&body)?;
        let SelectedCallTarget::Builtin{id,..}=&selected.target else{return None;};
        if id=="money" && selected.arguments.len()==2 && selected.slots.as_slice()==[Some(0),Some(1)] {
            let zero=self.nodes.get(&selected.arguments[0])?;
            if zero.kind!=SyntaxKind::Literal || self.word(zero)!=Some("0"){return None;}
            return self.source_require_money_currency(selected.arguments[1],model);
        }
        if id=="max" && selected.arguments.len()==1 && selected.slots.as_slice()==[Some(0)] {
            let array=self.nodes.get(&self.query_group(selected.arguments[0])?)?;
            if array.kind!=SyntaxKind::Array{return None;}
            let mut count=0;
            for value in array.children.iter().filter(|value|expression(value.kind)) {
                self.source_require_money_value(NodeKey::of(value),model,depth+1,visited,budget)?;count+=1;
            }
            return (count>0).then_some(());
        }
        if id!="sum" || selected.arguments.len()!=2 || selected.slots.as_slice()!=[Some(0),Some(1)]{return None;}
        self.source_require_money_currency(selected.arguments[1],model)?;
        let query=self.types.checked_queries.get(&self.query_group(selected.arguments[0])?)?;
        let (alias,filter,select)=match query.clauses.as_slice() {
            [alias,select]=>(alias,None,select),
            [alias,filter,select] if filter.kind==CheckedQueryClauseKind::Where=>(alias,Some(filter),select),
            _=>return None,
        };
        let ResolvedType::Array{element,ordered:true,nonempty:false}=&query.domain_type else{return None;};
        let ResolvedType::Record{symbol:child,stored:true}=element.as_ref() else{return None;};
        let (row,name)=self.count_member(query.domain)?;
        let child_decl=self.resolve.symbols.get(child.0 as usize)?;
        if !matches!(self.query_binding(row),Some(Binding::Context(ContextVar::RowModel(owner))) if *owner==model)
            || child_decl.name!=name || !matches!(child_decl.kind,SymbolKind::Model{owner:ModelOwner::ChildOf(owner),..} if owner==model)
            || self.effects.models.get(child)?.owner!=ModelOwner::ChildOf(model)
            || !matches!(alias.kind,CheckedQueryClauseKind::As{..}) || !alias.expressions.is_empty()
            || select.kind!=CheckedQueryClauseKind::Select || select.expressions.len()!=1 || query.projection.is_some()
        {return None;}
        let selector=self.query_group(select.expressions[0])?;
        if self.types.node_types.get(&selector)!=Some(&money){return None;}
        let (selected_value,fallback)=if let Some((value,fallback))=self.query_binary(selector,"??") {
            (value,Some(fallback))
        } else {(selector,None)};
        if let Some(field)=self.query_member(selected_value,alias.node,*child) {
            let expected=if fallback.is_some(){ResolvedType::Nullable(Box::new(money.clone()))}else{money.clone()};
            if self.types.symbol_types.get(&field)!=Some(&expected){return None;}
            if let Some(fallback)=fallback {self.source_require_money_value(fallback,model,depth+1,visited,budget)?;}
        } else {
            if fallback.is_some(){return None;}
            let name=self.query_member_name(selector,alias.node,*child)?;
            let field=self.resolve.symbols.iter().find(|field|field.name==name
                && matches!(field.kind,SymbolKind::DeriveField{model,..} if model==*child))?.id;
            if visited.contains(&(field,*child)){return None;}
            let expr=self.source_require_aggregate_decl(field,*child)?;
            visited.push((field,*child));
            let result=self.source_require_money_value(expr,*child,depth+1,visited,budget);
            visited.pop();result?;
        }
        if let Some(filter)=filter {
            let [predicate]=filter.expressions.as_slice() else{return None;};
            if self.types.node_types.get(predicate)!=Some(&ResolvedType::Scalar(Scalar::Bool)){return None;}
            self.source_require_child_predicate(*predicate, alias.node, *child, budget)?;
        }
        Some(())
    }

    /// A closed child predicate is shared by Money SUM and Boolean ANY.
    /// Stored scalar fields stay on the exact checked alias; no navigation,
    /// derived child reads, helper calls or foreign rows enter this domain.
    fn source_require_child_predicate(&self, predicate:NodeKey, alias:NodeKey,
        child:SymbolId,budget:&mut usize)->Option<()> {
        if self.types.node_types.get(&predicate)!=Some(&ResolvedType::Scalar(Scalar::Bool)){return None;}
        let mut pending=vec![predicate];
        while let Some(key)=pending.pop() {
            if *budget==0{return None;}*budget-=1;
            let node=self.nodes.get(&key)?;
            self.source_require_expression_shape(key)?;
            if matches!(node.kind,SyntaxKind::Call|SyntaxKind::Query){return None;}
            if node.kind==SyntaxKind::Member {
                let field=self.query_member(key,alias,child)?;
                let ty=self.types.symbol_types.get(&field)?;
                if !matches!(self.resolve.symbols.get(field.0 as usize)?.kind,SymbolKind::Field{owner,..} if owner==child)
                    || !(primitive_type(ty)||matches!(ty,ResolvedType::Enum{cases,..} if !cases.is_empty()))
                    || self.types.node_types.get(&key)!=Some(ty){return None;}
            }
            if node.kind==SyntaxKind::NameRef {
                match self.query_binding(key) {
                    Some(Binding::QueryAlias{node}) if *node==alias=>{},
                    Some(Binding::Context(ContextVar::Now))=>{},
                    _ if self.types.resolved_cases.contains(&key)=>{},
                    _=>return None,
                }
            }
            pending.extend(node.children.iter().map(NodeKey::of));
        }
        Some(())
    }

    /// Only an initial source Require may combine row scalar algebra,
    /// independently sealed Money aggregates and closed contained ANY.
    /// This does not change the general derived read or query DATA grammar.
    fn source_require_derived_control(&self,field:SymbolId,model:SymbolId,
        visited:&mut Vec<(SymbolId,SymbolId)>,budget:&mut usize)->Option<()> {
        if visited.len()>=32||visited.contains(&(field,model)){return None;}
        self.derived_member_body(field,model)?;
        let ty=self.types.symbol_types.get(&field)?;
        if !(primitive_type(ty)||matches!(ty,ResolvedType::Enum{cases,..} if !cases.is_empty())){return None;}
        if self.source_require_aggregate_field(field,model).is_some(){return Some(());}
        visited.push((field,model));
        let body=self.effects.derives.get(&field)?.expr?;
        let result=self.source_require_control_value(body,model,visited,budget,0);
        visited.pop();result
    }

    fn source_require_control_value(&self,key:NodeKey,model:SymbolId,
        visited:&mut Vec<(SymbolId,SymbolId)>,budget:&mut usize,depth:usize)->Option<()> {
        if *budget==0||depth>64{return None;}*budget-=1;
        let key=self.query_group(key)?;let node=self.nodes.get(&key)?;
        if self.types.resolved_cases.contains(&key)||node.kind==SyntaxKind::Literal{return Some(());}
        if node.kind==SyntaxKind::Member {
            let (base,name)=self.count_member(key)?;
            if matches!(self.query_binding(base),Some(Binding::Context(ContextVar::RowModel(owner)))if *owner==model) {
                let SymbolKind::Model{fields,..}=&self.resolve.symbols.get(model.0 as usize)?.kind else{return None;};
                let field=fields.iter().find_map(|id|self.resolve.symbols.get(id.0 as usize).filter(|field|field.name==name))?;
                let ty=self.types.symbol_types.get(&field.id)?;
                if self.types.node_types.get(&key)!=Some(ty)
                    || !(primitive_type(ty)||matches!(ty,ResolvedType::Enum{cases,..}if !cases.is_empty())){return None;}
                return match field.kind {
                    SymbolKind::Field{owner,..}if owner==model=>Some(()),
                    SymbolKind::DeriveField{model:owner,..}if owner==model=>self.source_require_derived_control(field.id,model,visited,budget),
                    _=>None,
                };
            }
            self.source_require_control_value(base,model,visited,budget,depth+1)?;
            self.admitted_data_member_step(base,name)?;return Some(());
        }
        if matches!(node.kind,SyntaxKind::Binary|SyntaxKind::Unary|SyntaxKind::Group) {
            for child in node.children.iter().filter(|child|expression(child.kind)) {
                self.source_require_control_value(NodeKey::of(child),model,visited,budget,depth+1)?;
            }
            return Some(());
        }
        let call=self.types.selected_calls.get(&key)?;
        let SelectedCallTarget::Builtin{id,overload}=&call.target else{return None;};
        if id!="any"||call.arguments.len()!=2||call.slots.as_slice()!=[Some(0),Some(1)]{return None;}
        let fact=self.types.checked_collection_calls.get(&key)?;
        let domain=self.query_group(call.arguments[0])?;let predicate=call.arguments[1];
        let query=self.types.checked_queries.get(&domain)?;let [alias]=query.clauses.as_slice()else{return None;};
        let array=ResolvedType::Array{element:Box::new(ResolvedType::Record{symbol:fact.model,stored:true}),ordered:true,nonempty:false};
        let (row,name)=self.count_member(query.domain)?;
        let child=self.resolve.symbols.get(fact.model.0 as usize)?;
        if fact.node!=key||fact.builtin!=*id||fact.overload!=*overload||fact.query!=domain||fact.alias!=alias.node
            || fact.predicate.as_ref().is_none_or(|p|p.node!=predicate||p.ty!=ResolvedType::Scalar(Scalar::Bool))
            ||query.domain_type!=array||query.result!=array||query.projection.is_some()
            ||self.types.node_types.get(&query.domain)!=Some(&array)||self.types.node_types.get(&key)!=Some(&ResolvedType::Scalar(Scalar::Bool))
            ||!matches!(alias.kind,CheckedQueryClauseKind::As{..})||!alias.expressions.is_empty()
            ||!matches!(self.query_binding(row),Some(Binding::Context(ContextVar::RowModel(owner)))if *owner==model)
            ||child.name!=name||!matches!(child.kind,SymbolKind::Model{owner:ModelOwner::ChildOf(owner),..}if owner==model)
            ||self.effects.models.get(&fact.model)?.owner!=ModelOwner::ChildOf(model){return None;}
        self.source_require_child_predicate(predicate,alias.node,fact.model,budget)
    }

    fn source_require_aggregate_field(
        &self,
        id: SymbolId,
        model: SymbolId,
    ) -> Option<()> {
        if self.source_require_remaining_count_field(id, model).is_some() {
            return Some(());
        }
        let body = self.source_require_aggregate_decl(id, model)?;
        if self.types.symbol_types.get(&id)==Some(&ResolvedType::Scalar(Scalar::Money))
            && self.source_require_money_aggregate(body,model,0).is_some() {return Some(());}
        let aggregate = if self.source_require_aggregate_call(id, body).is_some() { body }
        else {
            // An integer base quantity plus one owned child sum remains an
            // initial-stage observer. Both operands retain their original
            // row/field and collection correspondence; no stage gate changes.
            let (base, aggregate) = self.query_binary(body, "+")?;
            let (row, name) = self.count_member(base)?;
            if self.types.symbol_types.get(&id) != Some(&ResolvedType::Scalar(Scalar::Int))
                || !matches!(self.query_binding(row), Some(Binding::Context(ContextVar::RowModel(actual))) if *actual == model)
            { return None; }
            let field = self.effects.models.get(&model)?.fields.iter().find(|field|
                self.resolve.symbols.get(field.field.0 as usize).is_some_and(|symbol| symbol.name == name))?;
            if !matches!(self.resolve.symbols.get(field.field.0 as usize)?.kind, SymbolKind::Field { owner, .. } if owner == model)
                || self.types.symbol_types.get(&field.field) != Some(&ResolvedType::Scalar(Scalar::Int))
                || self.types.node_types.get(&base) != Some(&ResolvedType::Scalar(Scalar::Int))
            { return None; }
            aggregate
        };
        let (query, alias, select, child) = self.source_require_aggregate_call(id, aggregate)?;
        self.source_require_aggregate_domain(query, alias, select, child, model)
    }

    fn source_require_derive_call(
        &self,
        id: &SymbolId,
        supported: &mut bool,
    ) -> Option<bool> {
        let data = self.effects.derives.get(id)?;
        if data.params.iter().any(|param| {
            param.default.is_some()
                || self
                    .types
                    .symbol_types
                    .get(&param.param)
                    .is_none_or(|ty| !self.source_require_input(ty))
                    && !self.source_require_owned_enum_formal(param)
        }) || !self.types.symbol_results.get(id).is_some_and(|result| result.as_ref().is_some_and(|ty|
            self.source_require_input(ty) || matches!(ty, ResolvedType::Nullable(inner)
                if matches!(inner.as_ref(), ResolvedType::Scalar(_)))))
        {
            *supported = false;
            return Some(false);
        }
        Some(true)
    }

    fn source_require_any_attrs(
        &self,
        fact: &super::types::CheckedCollectionCall,
        call: &CheckedDecisionCall,
        id: &String,
        overload: &usize,
        domain: &NodeKey,
        predicate: &NodeKey,
        query: &super::types::CheckedQuery,
        alias: &super::types::CheckedQueryClause,
        array: &ResolvedType,
        domain_ty: &ResolvedType,
        predicate_ty: &ResolvedType,
    ) -> bool {
        fact.node == call.node
            && fact.builtin == *id
            && fact.overload == *overload
            && fact.query == *domain
            && fact.alias == alias.node
            && matches!(&alias.kind, CheckedQueryClauseKind::As {name} if !name.is_empty())
            && alias.expressions.is_empty()
            && query.node == *domain
            && query.domain_type == *array
            && query.result == *array
            && *domain_ty == *array
            && self.types.node_types.get(&query.domain) == Some(array)
            && self.types.node_types.get(&call.node)
                == Some(&ResolvedType::Scalar(Scalar::Bool))
            && *predicate_ty == ResolvedType::Scalar(Scalar::Bool)
            && fact
                .predicate
                .as_ref()
                .is_some_and(|value| value.node == *predicate && value.ty == *predicate_ty)
            && query.projection.is_none()
    }

    fn source_require_any_member(
        &self,
        query: &super::types::CheckedQuery,
        array: &ResolvedType,
        call: &CheckedDecisionCall,
    ) -> Option<bool> {
        let (base, name) = self.count_member(query.domain)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(base) else {
            return None;
        };
        let frame = call.chain.last()?;
        let helper = self.effects.derives.get(&frame.derive)?;
        let Some(ResolvedType::Record {
            symbol: owner,
            stored: true,
        }) = self.types.symbol_types.get(parameter)
        else {
            return None;
        };
        let field = self
            .effects
            .models
            .get(owner)?
            .fields
            .iter()
            .find(|field| {
                self.resolve
                    .symbols
                    .get(field.field.0 as usize)
                    .is_some_and(|decl| decl.name == name)
            })?;
        if !helper.params.iter().any(|param| param.param == *parameter)
            || self.nodes.get(&base)?.kind != SyntaxKind::NameRef
            || self.types.symbol_types.get(&field.field) != Some(array)
            || field.default.is_some()
            || field.server.is_some()
        {
            Some(false)
        } else {
            Some(true)
        }
    }

    /// Follow a helper's original formal, optionally through `.parent`,
    /// without treating a lexical copy or a same-typed derive result as the
    /// admitted owner row. Each hop uses the same checked ChildOf validation
    /// as a direct scenario-parameter path.
    fn source_require_helper_parent_path(
        &self,
        key: NodeKey,
        derive: SymbolId,
        depth: usize,
    ) -> Option<(SymbolId, SymbolId, u8)> {
        if depth > 2 {
            return None;
        }
        let key = self.query_group(key)?;
        let node = self.nodes.get(&key)?;
        if node.kind == SyntaxKind::NameRef {
            let Some(Binding::Symbol(formal)) = self.query_binding(key) else {
                return None;
            };
            let helper = self.effects.derives.get(&derive)?;
            let parameter = helper.params.iter().find(|param| param.param == *formal)?;
            let ResolvedType::Record { symbol: model, stored: true } =
                self.types.symbol_types.get(formal)? else {
                    return None;
                };
            if parameter.default.is_some()
                || self.types.node_types.get(&key) != self.types.symbol_types.get(formal)
                || !matches!(self.resolve.symbols.get(model.0 as usize)?.kind, SymbolKind::Model { .. })
            {
                return None;
            }
            return Some((*formal, *model, 0));
        }
        if node.kind != SyntaxKind::Member || depth == 2 {
            return None;
        }
        let (base, name) = self.count_member(key)?;
        if name != "parent" {
            return None;
        }
        let (formal, child, prior) = self.source_require_helper_parent_path(base, derive, depth + 1)?;
        let (parent, hops) = self.call_parent_hop_valid(key, base, child, prior)?;
        Some((formal, parent, hops))
    }

    /// The original member removal passes its Seat's Customer ancestor to
    /// `customer.has_role`. Admit that third containment edge only for this
    /// exact helper/domain and original required Seat parameter. The regular
    /// source Require parent-path limit remains two everywhere else.
    fn source_require_remove_role_customer_path(
        &self,
        scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall,
        argument: NodeKey,
        customer: SymbolId,
        company_role: SymbolId,
    ) -> Option<(SymbolId, u8)> {
        let [frame] = call.chain.as_slice() else { return None; };
        let scenario_symbol = self.resolve.symbols.get(scenario.scenario.0 as usize)?;
        let scenario_module = self.resolve.modules.get(scenario.module.0 as usize)?;
        let helper_symbol = self.resolve.symbols.get(frame.derive.0 as usize)?;
        let helper_module = self.resolve.modules.get(helper_symbol.module.0 as usize)?;
        let customer_symbol = self.resolve.symbols.get(customer.0 as usize)?;
        let role_symbol = self.resolve.symbols.get(company_role.0 as usize)?;
        if scenario_symbol.name != "remove"
            || scenario_symbol.module != scenario.module
            || scenario_module.name != "member_terms"
            || helper_symbol.name != "has_role"
            || helper_module.name != "customer"
            || customer_symbol.name != "Customer"
            || customer_symbol.module != helper_symbol.module
            || role_symbol.name != "CompanyRole"
            || role_symbol.module != helper_symbol.module
        {
            return None;
        }
        let seat = scenario.params.iter().find(|param| {
            self.resolve.symbols.get(param.param.0 as usize).is_some_and(|symbol|
                symbol.name == "seat"
                    && symbol.module == scenario.module
                    && matches!(symbol.kind, SymbolKind::Param { owner, .. } if owner == scenario.scenario))
        })?;
        if seat.default.is_some() { return None; }
        let ResolvedType::Record { symbol: seat_model, stored: true } =
            self.types.symbol_types.get(&seat.param)? else { return None; };
        let seat_symbol = self.resolve.symbols.get(seat_model.0 as usize)?;
        let ModelOwner::ChildOf(term) = self.effects.models.get(seat_model)?.owner else { return None; };
        let term_symbol = self.resolve.symbols.get(term.0 as usize)?;
        let ModelOwner::ChildOf(membership) = self.effects.models.get(&term)?.owner else { return None; };
        let membership_symbol = self.resolve.symbols.get(membership.0 as usize)?;
        if seat_symbol.name != "Seat" || seat_symbol.module != scenario.module
            || term_symbol.name != "Term" || term_symbol.module != scenario.module
            || membership_symbol.name != "Membership" || membership_symbol.module != scenario.module
            || self.effects.models.get(&membership)?.owner != ModelOwner::ChildOf(customer)
        {
            return None;
        }
        let (base, name) = self.count_member(argument)?;
        if name != "parent" || self.nodes.get(&argument)?.kind != SyntaxKind::Member
            || self.checked_call_parent_path(base, seat.param, 0) != Some((membership, 2))
        {
            return None;
        }
        let (actual, hops) = self.call_parent_hop_valid_with_limit(argument, base, membership, 2, 3)?;
        (actual == customer && hops == 3).then_some((actual, hops))
    }

    /// A helper-contained `parent.Child` has the same owner domain as a
    /// direct source Require only when every call frame substitutes its
    /// formal with an exact original parent path. Matching Model types alone
    /// cannot establish which owner row the query will scan.
    fn source_require_helper_contained_any(
        &self,
        scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall,
        query: &super::types::CheckedQuery,
        model: SymbolId,
    ) -> Option<()> {
        let frame = call.chain.last()?;
        let (receiver, name) = self.count_member(query.domain)?;
        let (mut formal, parent, mut hops) =
            self.source_require_helper_parent_path(receiver, frame.derive, 0)?;
        let child = self.resolve.symbols.get(model.0 as usize)?;
        let defining_module = self.resolve.symbols.get(frame.derive.0 as usize)?.module;
        let imported_assign_contact = child.name == "Contact"
            && name == "Contact"
            && self.resolve.modules.get(scenario.module.0 as usize).is_some_and(|module| module.name == "member_terms")
            && self.resolve.symbols.get(scenario.scenario.0 as usize).is_some_and(|symbol| symbol.name == "assign")
            && call.chain.len() == 1
            && self.resolve.symbols.get(frame.derive.0 as usize).is_some_and(|symbol|
                symbol.name == "eligible_account" && symbol.module == scenario.module)
            && self.resolve.symbols.get(parent.0 as usize).is_some_and(|symbol|
                symbol.name == "Customer" && symbol.module == child.module);
        if child.name != name
            || (child.module != call.module && child.module != defining_module && !imported_assign_contact)
            || !matches!(child.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(owner), .. } if owner == parent)
            || self.effects.models.get(&model)?.owner != ModelOwner::ChildOf(parent)
        {
            return None;
        }
        for index in (0..call.chain.len()).rev() {
            let frame = &call.chain[index];
            let helper = self.effects.derives.get(&frame.derive)?;
            let selected = self.types.selected_calls.get(&frame.node)?;
            let SelectedCallTarget::DeriveFn(target) = &selected.target else {
                return None;
            };
            let slot = helper.params.iter().position(|param| param.param == formal)?;
            if *target != frame.derive || selected.slots.len() != helper.params.len()
                || helper.params[slot].default.is_some()
            {
                return None;
            }
            let argument = *selected.arguments.get(*selected.slots.get(slot)?.as_ref()?)?;
            if self.types.node_types.get(&argument) != self.types.symbol_types.get(&formal) {
                return None;
            }
            if index == 0 {
                let ordinary = scenario.params.iter().enumerate().find_map(|(index, parameter)| {
                    self.checked_call_parent_path(argument, parameter.param, 0)
                        .or_else(|| {
                            // This exact occurrence is flow-narrowed by the original
                            // source guard; a same-typed sibling value is not its input.
                            let argument = self.query_group(argument)?;
                            let ResolvedType::Record { symbol: actual, stored: true } =
                                self.types.node_types.get(&argument)? else {
                                    return None;
                                };
                            (matches!(self.query_binding(argument), Some(Binding::Symbol(input)) if *input == parameter.param)
                                && self.types.symbol_types.get(&parameter.param) == Some(&ResolvedType::Nullable(Box::new(
                                    ResolvedType::Record { symbol: *actual, stored: true },
                                )))
                                && (parameter.default.is_none()
                                    || self.source_require_null_model_input(scenario, parameter, index)))
                                .then_some((*actual, 0))
                        })
                });
                let ResolvedType::Record { symbol: expected, stored: true } =
                    self.types.symbol_types.get(&formal)? else {
                        return None;
                    };
                let (actual, path_hops, limit) = if let Some((actual, path_hops)) = ordinary {
                    (actual, path_hops, 2)
                } else {
                    let (actual, path_hops) = self.source_require_remove_role_customer_path(
                        scenario, call, argument, *expected, model,
                    )?;
                    (actual, path_hops, 3)
                };
                if actual != *expected || hops.checked_add(path_hops)? > limit {
                    return None;
                }
            } else {
                let (outer_formal, actual, path_hops) =
                    self.source_require_helper_parent_path(argument, call.chain[index - 1].derive, 0)?;
                let ResolvedType::Record { symbol: expected, stored: true } =
                    self.types.symbol_types.get(&formal)? else {
                        return None;
                    };
                if actual != *expected {
                    return None;
                }
                hops = hops.checked_add(path_hops)?;
                if hops > 2 {
                    return None;
                }
                formal = outer_formal;
            }
        }
        Some(())
    }

    fn unproved_helper_contained_any(
        &self,
        scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall,
    ) -> bool {
        let Some(frame) = call.chain.last() else { return false; };
        if !matches!(&call.target, CheckedDecisionCallTarget::Builtin { id, .. } if id == "any") {
            return false;
        }
        let Some(fact) = self.types.checked_collection_calls.get(&call.node) else { return false; };
        let Some(query) = self.types.checked_queries.get(&fact.query) else { return false; };
        let Some((base, name)) = self.count_member(query.domain) else { return false; };
        let Some(Binding::Symbol(parameter)) = self.query_binding(base) else { return false; };
        let Some(helper) = self.effects.derives.get(&frame.derive) else { return false; };
        let Some(ResolvedType::Record { symbol: parent, stored: true }) = self.types.symbol_types.get(parameter) else { return false; };
        let Some(child) = self.resolve.symbols.get(fact.model.0 as usize) else { return false; };
        helper.params.iter().any(|param| param.param == *parameter) && child.name == name &&
            matches!(child.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(owner), .. } if owner == *parent) &&
            self.effects.models.get(&fact.model).is_some_and(|model| model.owner == ModelOwner::ChildOf(*parent)) &&
            self.source_require_helper_contained_any(scenario, call, query, fact.model).is_none()
                && !self.source_require_contained_collection(scenario, call, "any")
    }

    /// A duplicate veto may be one negative conjunct of the original
    /// Require. Positive ANY, OR and negated compound forms confer no key
    /// observation; the whole source guard still preserves short-circuiting.
    fn source_require_negative_conjunct(&self,condition:NodeKey,call:NodeKey,depth:usize)->bool {
        if depth>32{return false;}
        let Some(condition)=self.query_group(condition)else{return false;};
        if let Some((left,right))=self.query_binary(condition,"and") {
            return self.source_require_negative_conjunct(left,call,depth+1)
                ||self.source_require_negative_conjunct(right,call,depth+1);
        }
        let Some(node)=self.nodes.get(&condition)else{return false;};
        node.kind==SyntaxKind::Unary&&node.children.iter().any(|child|self.word(child)==Some("not"))
            &&node.children.iter().filter(|child|expression(child.kind)).map(NodeKey::of).collect::<Vec<_>>()==[call]
    }

    /// The authored pre-CREATE duplicate check may inspect one declared
    /// unique Text or original admitted Model identity key. The following
    /// CREATE in that same lexical arm must claim this exact key; no sibling
    /// arm or general global collection receives authority.
    fn source_require_unique_any(
        &self,
        scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall,
        query: &super::types::CheckedQuery,
        alias: &super::types::CheckedQueryClause,
        predicate: NodeKey,
        model: SymbolId,
    ) -> Option<()> {
        if !call.chain.is_empty()
            || self.resolve.symbols.get(model.0 as usize)?.module != scenario.module
            || !matches!(self.query_binding(query.domain),Some(Binding::Symbol(actual)) if *actual==model)
        {
            return None;
        }
        fn guard_tail<'b>(closure:&Closure<'_>,body:&'b [Effect],call:NodeKey,depth:usize)
            ->Option<(&'b Effect,&'b [Effect])> {
            if depth>=64{return None;}
            for (index,effect) in body.iter().enumerate(){
                if effect.verb==EffectVerb::Require && effect.cond.is_some_and(|condition|
                    closure.source_require_negative_conjunct(condition,call,0)) {
                    return Some((effect,&body[index+1..]));
                }
                if effect.verb==EffectVerb::If&&effect.match_arms.is_empty(){
                    // The true arm claims exactly the key whose absence was
                    // observed. A sibling/else CREATE cannot establish it.
                    if effect.else_effects.is_empty() && matches!(effect.then_effects.as_slice(),[create] if create.verb==EffectVerb::Create && create.when.is_none()
                            &&create.then_effects.is_empty()&&create.else_effects.is_empty()&&create.match_arms.is_empty())
                        && effect.cond.is_some_and(|condition|closure.source_require_negative_conjunct(condition,call,0)) {
                        return Some((effect,effect.then_effects.as_slice()));
                    }
                    if let Some(found)=guard_tail(closure,&effect.then_effects,call,depth+1){return Some(found);}
                    if let Some(found)=guard_tail(closure,&effect.else_effects,call,depth+1){return Some(found);}
                }
            }
            None
        }
        let (guard,tail)=scenario.guards.iter().find(|effect|effect.verb==EffectVerb::Require
            && effect.cond.is_some_and(|condition|self.source_require_negative_conjunct(condition,call.node,0)))
            .map(|guard|(guard,scenario.effects.as_slice()))
            .or_else(||guard_tail(self,&scenario.effects,call.node,0))?;
        let (left, right) = self.query_binary(predicate, "==")?;
        let field = self.query_member(left, alias.node, model)?;
        let declaration = self
            .effects
            .models
            .get(&model)?
            .fields
            .iter()
            .find(|item| item.field == field)?;
        let field_ty=self.types.symbol_types.get(&field)?;
        let expected=match field_ty {
            ResolvedType::Scalar(Scalar::Text)=>field_ty,
            ResolvedType::Record{stored:true,..}=>field_ty,
            ResolvedType::Nullable(inner) if matches!(inner.as_ref(),ResolvedType::Record{stored:true,..})=>inner.as_ref(),
            _=>return None,
        };
        if declaration.default.is_some()
            || declaration.server.is_some()
            || !declaration
                .modifiers
                .iter()
                .any(|modifier| modifier.name == "unique" && modifier.value.is_none())
        {
            return None;
        }
        let input = |key: NodeKey| -> Option<(SymbolId, Option<SymbolId>, bool)> {
            let key = self.query_group(key)?;
            let (key, trimmed) = if let Some(call) = self.types.selected_calls.get(&key) {
                if *expected!=ResolvedType::Scalar(Scalar::Text)
                    || !matches!(&call.target,SelectedCallTarget::Builtin{id,overload:0} if id=="trim")
                    || call.arguments.len() != 1
                    || call.slots.as_slice() != [Some(0)]
                {
                    return None;
                }
                (self.query_group(call.arguments[0])?, true)
            } else {
                (key, false)
            };
            if *expected==ResolvedType::Scalar(Scalar::Text) && let Some((root,name))=self.count_member(key) {
                let Binding::Symbol(parameter)=self.query_binding(root)? else{return None;};
                let parameter_data=scenario.params.iter().find(|input|input.param==*parameter&&input.default.is_none())?;
                let ResolvedType::Record{symbol:source,stored:true}=self.types.symbol_types.get(&parameter_data.param)? else{return None;};
                if self.types.node_types.get(&root)!=self.types.symbol_types.get(parameter)
                    ||self.types.node_types.get(&key)!=Some(expected){return None;}
                let source_model=self.effects.models.get(source)?;
                let source_field=source_model.fields.iter().find(|field|
                    self.resolve.symbols.get(field.field.0 as usize).is_some_and(|field|field.name==name))?;
                if source_field.server.is_some() || source_field.default.is_some()
                    ||self.types.symbol_types.get(&source_field.field)!=Some(expected){return None;}
                return Some((*parameter,Some(source_field.field),trimmed));
            }
            let Binding::Symbol(parameter) = self.query_binding(key)? else {
                return None;
            };
            let parameter_data=scenario.params.iter().find(|input|input.param==*parameter)?;
            let admitted=if let ResolvedType::Record{symbol:target,stored:true}=expected {
                self.types.node_types.get(&key)==Some(expected) &&
                    (parameter_data.default.is_none()&&self.types.symbol_types.get(parameter)==Some(expected)
                        ||self.narrowed_model_input(key,scenario.module)==Some((*parameter,*target)))
            }else{
                parameter_data.default.is_none()&&self.types.symbol_types.get(parameter)==Some(expected)
            };
            admitted.then_some((*parameter,None,trimmed))
        };
        let value = input(right)?;
        let guarded_end=if guard.verb==EffectVerb::If{guard.cond?.end}else{guard.node.end};
        let found=tail.iter().any(|effect| {
                effect.node.file == guard.node.file
                    && effect.node.start >= guarded_end
                    && effect.verb == EffectVerb::Create
                    && matches!(effect.target,Some(EffectTarget::Model(actual)) if actual==model)
                    && effect.args.iter().any(|argument| {
                        argument.key == self.resolve.symbols[field.0 as usize].name
                            && input(argument.value.unwrap_or(argument.key_node)) == Some(value)
                    })
            });
        found.then_some(())
    }

    fn source_require_any_call(
        &self,
        scenario: &super::effects::ScenarioData,
        body: bool,
        call: &CheckedDecisionCall,
        id: &String,
        overload: &usize,
        helper_query: &mut bool,
        supported: &mut bool,
    ) -> Option<bool> {
        let _ = body;
        let fact = self.types.checked_collection_calls.get(&call.node)?;
        let [Some(domain_slot), Some(predicate_slot)] = call.slots.as_slice() else {
            return None;
        };
        let (domain, domain_ty) = call.arguments.get(*domain_slot)?;
        let (predicate, predicate_ty) = call.arguments.get(*predicate_slot)?;
        let query = self.types.checked_queries.get(domain)?;
        let [alias] = query.clauses.as_slice() else {
            return None;
        };
        let array = ResolvedType::Array {
            element: Box::new(ResolvedType::Record {
                symbol: fact.model,
                stored: true,
            }),
            ordered: true,
            nonempty: false,
        };
        if !self.source_require_any_attrs(
            fact,
            call,
            id,
            overload,
            domain,
            predicate,
            query,
            alias,
            &array,
            domain_ty,
            predicate_ty,
        ) {
            *supported = false;
            return Some(false);
        }
        let domain_node = self.nodes.get(&query.domain)?;
        if call.chain.is_empty() {
            if self
                .source_require_contained_any(scenario, query, fact.model)
                .is_none()
                && !self.source_require_reference_query(scenario, call, query)
                && self
                    .source_require_unique_any(scenario, call, query, alias, *predicate, fact.model)
                    .is_none()
                && !self.source_require_contained_collection(scenario, call, "any")
            {
                *supported = false;
                return Some(false);
            }
            // An independently admitted native [any, first] composition
            // keeps its original flow influences and owner frame. If that
            // exact ANY profile is unavailable, the sealed whole leading
            // observer may own it beside the independently proven FIRST.
            if !body
                && scenario.effects.iter().any(|binding| {
                    binding.verb == EffectVerb::Let
                        && self
                            .checked_first_query_source(scenario, binding)
                            .is_some_and(|first| {
                                first.first.is_some() && first.model == fact.model
                            })
                })
                && scenario.guards.iter().any(|guard|
                    guard.node.file == call.node.file && guard.node.start <= call.node.start
                        && call.node.end <= guard.node.end
                        && self.checked_any_query_source(scenario, guard, call.node).is_some())
            {
                *supported = false;
                return Some(false);
            }
        } else if domain_node.kind == SyntaxKind::Member {
            if !self.source_require_reference_query(scenario, call, query)
                && !self.source_require_any_member(query, &array, call).unwrap_or(false)
                && self.source_require_helper_contained_any(scenario, call, query, fact.model).is_none()
                && !self.source_require_contained_collection(scenario, call, "any")
            {
                *supported = false;
                return Some(false);
            }
        } else if domain_node.kind != SyntaxKind::NameRef
            || !matches!(self.query_binding(query.domain), Some(Binding::Symbol(model)) if *model == fact.model)
        {
            *supported = false;
            return Some(false);
        }
        *helper_query = true;
        Some(true)
    }

    /// A source decision may traverse an exact admitted reference array or a
    /// declared stored reference field reached from that input. Helper formals
    /// and aliases must resolve through their original call frames. The owner
    /// observer retains the complete array, order and reached rows; this fact
    /// grants no ordinary data read and admits no copied or computed domain.
    fn source_require_reference_domain(
        &self, scenario: &super::effects::ScenarioData, call: &CheckedDecisionCall,
        domain: NodeKey, frames: usize, depth: usize,
    ) -> bool {
        if depth >= 32 { return false; }
        let Some(domain) = self.query_group(domain) else { return false; };
        let Some(ty @ ResolvedType::Array { element, ordered: true, nonempty: false }) =
            self.types.node_types.get(&domain) else { return false; };
        let ResolvedType::Record { symbol: model, stored: true } = element.as_ref()
            else { return false; };
        if !self.effects.models.contains_key(model) { return false; }
        if let Some(Binding::Symbol(formal)) = self.query_binding(domain) {
            if scenario.params.iter().any(|parameter| parameter.param == *formal && parameter.default.is_none())
                && self.types.symbol_types.get(formal) == Some(ty) { return true; }
            return self.source_require_helper_argument(call, *formal, frames)
                .is_some_and(|(argument, index)| self.types.node_types.get(&argument) == Some(ty)
                    && self.source_require_reference_domain(scenario, call, argument, index, depth + 1));
        }
        let Some((receiver, name)) = self.count_member(domain) else { return false; };
        let Some(owner) = self.source_require_query_receiver(scenario, call, receiver, frames, depth + 1)
            else { return false; };
        self.effects.models.get(&owner).is_some_and(|owner| owner.fields.iter().any(|field|
            self.resolve.symbols.get(field.field.0 as usize).is_some_and(|declaration|
                declaration.name == name && matches!(declaration.kind, SymbolKind::Field { owner: actual, .. } if actual == owner.model))
                && self.types.symbol_types.get(&field.field) == Some(ty)))
    }

    fn source_require_reference_query(
        &self, scenario: &super::effects::ScenarioData, call: &CheckedDecisionCall,
        query: &super::types::CheckedQuery,
    ) -> bool {
        matches!(query.clauses.as_slice(), [alias] if matches!(&alias.kind,
            CheckedQueryClauseKind::As { name } if !name.is_empty()) && alias.expressions.is_empty())
            && query.projection.is_none() && query.result == query.domain_type
            && self.types.node_types.get(&query.domain) == Some(&query.domain_type)
            && self.source_require_reference_domain(scenario, call, query.domain, call.chain.len(), 0)
    }

    /// Substitute only the selected argument of the original helper frame.
    /// The frame index shrinks on recursion, so a formal cannot prove itself.
    fn source_require_helper_argument(
        &self, call: &CheckedDecisionCall, formal: SymbolId, frames: usize,
    ) -> Option<(NodeKey, usize)> {
        let index = (0..frames).rev().find(|index| self.effects.derives.get(&call.chain[*index].derive)
            .is_some_and(|derive| derive.params.iter().any(|parameter| parameter.param == formal)))?;
        let frame = &call.chain[index];
        let derive = self.effects.derives.get(&frame.derive)?;
        let slot = derive.params.iter().position(|parameter| parameter.param == formal)?;
        let selected = self.types.selected_calls.get(&frame.node)?;
        if !matches!(selected.target, SelectedCallTarget::DeriveFn(id) if id == frame.derive)
            || selected.slots.len() != derive.params.len() || derive.params[slot].default.is_some()
        { return None; }
        let argument = *selected.arguments.get(*selected.slots.get(slot)?.as_ref()?)?;
        (self.types.node_types.get(&argument) == self.types.symbol_types.get(&formal))
            .then_some((argument, index))
    }

    /// Resolve the actual owner of a contained read through original helper
    /// substitutions and query aliases. Equal nominal types alone do not
    /// establish which admitted parent a helper will scan.
    fn source_require_query_receiver(
        &self,
        scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall,
        key: NodeKey,
        frames: usize,
        depth: usize,
    ) -> Option<SymbolId> {
        if depth >= 32 { return None; }
        let key = self.query_group(key)?;
        let ResolvedType::Record {symbol: expected, stored:true} = self.types.node_types.get(&key)? else { return None; };
        match self.query_binding(key) {
            Some(Binding::Symbol(formal)) => {
                if scenario.params.iter().any(|parameter| parameter.param == *formal)
                    && self.types.symbol_types.get(formal) == self.types.node_types.get(&key)
                { return Some(*expected); }
                let (argument, index) = self.source_require_helper_argument(call, *formal, frames)?;
                let actual = self.source_require_query_receiver(scenario, call, argument, index, depth + 1)?;
                (actual == *expected).then_some(actual)
            }
            Some(Binding::QueryAlias {node: alias}) => {
                let query = self.types.checked_queries.values().find(|query| query.clauses.iter()
                    .any(|clause| clause.node == *alias && matches!(clause.kind, CheckedQueryClauseKind::As {..})))?;
                let ResolvedType::Array {element, ..} = &query.domain_type else { return None; };
                if element.as_ref() != &(ResolvedType::Record {symbol:*expected,stored:true})
                    || !(self.source_require_contained_query_at(scenario, call, query, frames, depth + 1)
                        || self.source_require_reference_domain(scenario, call, query.domain, frames, depth + 1))
                { return None; }
                Some(*expected)
            }
            _ => {
                let (base, field) = self.count_member(key)?;
                let owner = self.source_require_query_receiver(scenario, call, base, frames, depth + 1)?;
                if field == "parent" {
                    return (self.effects.models.get(&owner)?.owner == ModelOwner::ChildOf(*expected)).then_some(*expected);
                }
                // A required singular stored field preserves the original
                // admitted receiver through this exact helper substitution.
                // A same-type helper result, derived field, nullable reference
                // or arbitrary model expression grants no contained domain.
                let declared = self.effects.models.get(&owner)?.fields.iter().find(|candidate|
                    self.resolve.symbols.get(candidate.field.0 as usize).is_some_and(|symbol|
                        symbol.name == field && matches!(symbol.kind,SymbolKind::Field{owner:actual,..} if actual==owner)))?;
                (self.types.symbol_types.get(&declared.field) == self.types.node_types.get(&key))
                    .then_some(*expected)
            }
        }
    }

    fn source_require_contained_query_at(
        &self, scenario: &super::effects::ScenarioData, call: &CheckedDecisionCall,
        query: &super::types::CheckedQuery, frames: usize, depth: usize,
    ) -> bool {
        let Some((receiver, name)) = self.count_member(query.domain) else { return false; };
        let Some(parent) = self.source_require_query_receiver(scenario, call, receiver, frames, depth) else { return false; };
        let ResolvedType::Array {element, ordered:true, nonempty:false} = &query.domain_type else { return false; };
        let ResolvedType::Record {symbol:child,stored:true} = element.as_ref() else { return false; };
        let Some(declaration) = self.resolve.symbols.get(child.0 as usize) else { return false; };
        declaration.name == name && matches!(declaration.kind,
            SymbolKind::Model {owner:ModelOwner::ChildOf(owner),..} if owner == parent)
            && self.effects.models.get(child).is_some_and(|model| model.owner == ModelOwner::ChildOf(parent))
            && query.clauses.iter().all(|clause| matches!(clause.kind,
                CheckedQueryClauseKind::As {..} | CheckedQueryClauseKind::Where
                    | CheckedQueryClauseKind::Select | CheckedQueryClauseKind::Order))
            && query.clauses.iter().filter(|clause| matches!(clause.kind,CheckedQueryClauseKind::As {..})).count() == 1
            && query.projection.is_none()
            && query.clauses.iter().filter(|clause| matches!(clause.kind,CheckedQueryClauseKind::Select))
                .all(|clause| clause.expressions.len() == 1 && self.types.node_types.get(&clause.expressions[0])
                    .is_some_and(|ty| matches!(ty,ResolvedType::Scalar(_))
                        || matches!(ty,ResolvedType::Nullable(inner) if matches!(inner.as_ref(),ResolvedType::Scalar(_)))))
    }

    fn source_require_contained_query(&self, scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall, query: &super::types::CheckedQuery) -> bool {
        // Select the call frame that really contains this original query;
        // an unrelated helper's parameter with an equal type is insufficient.
        let in_arguments = call.arguments.iter().any(|(argument,_)| argument.file == query.node.file
            && argument.start <= query.node.start && query.node.end <= argument.end);
        in_arguments && self.source_require_contained_query_at(scenario,call,query,call.chain.len(),0)
    }

    fn source_require_contained_collection(&self, scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall, builtin: &str) -> bool {
        let Some(fact) = self.types.checked_collection_calls.get(&call.node) else { return false; };
        let Some(query) = self.types.checked_queries.get(&fact.query) else { return false; };
        fact.node == call.node && fact.builtin == builtin && query.projection.is_none()
            && query.result == query.domain_type
            && !query.clauses.iter().any(|clause| matches!(clause.kind,CheckedQueryClauseKind::Select))
            && self.source_require_contained_query(scenario,call,query)
    }

    /// A leading integer or Money SUM observes one complete original contained
    /// domain. Its checked signature and scalar projection remain exact; every
    /// reached predicate/projection read executes in the source observer.
    fn source_require_contained_sum(&self,scenario:&super::effects::ScenarioData,
        call:&CheckedDecisionCall)->bool {
        let Some(result)=self.types.node_types.get(&call.node)else{return false;};
        let values=match (result,call.slots.as_slice()) {
            (ResolvedType::Scalar(Scalar::Int),[Some(values)]) if call.arguments.len()==1=>*values,
            (ResolvedType::Scalar(Scalar::Money),[Some(values),Some(currency)])
                if call.arguments.len()==2&&call.arguments.get(*currency)
                    .is_some_and(|(_,ty)|*ty==ResolvedType::Scalar(Scalar::Currency))=>*values,
            _=>return false,
        };
        let Some((values,ty))=call.arguments.get(values)else{return false;};
        if !matches!(ty,ResolvedType::Array{element,ordered:true,nonempty:false}if element.as_ref()==result){return false;}
        let Some(query)=self.query_group(*values).and_then(|key|self.types.checked_queries.get(&key))else{return false;};
        let clauses=query.clauses.as_slice();
        let select=match clauses {
            [alias,select] if matches!(alias.kind,CheckedQueryClauseKind::As{..})=>select,
            [alias,filter,select] if matches!(alias.kind,CheckedQueryClauseKind::As{..})
                &&filter.kind==CheckedQueryClauseKind::Where&&filter.expressions.len()==1
                &&self.types.node_types.get(&filter.expressions[0])==Some(&ResolvedType::Scalar(Scalar::Bool))=>select,
            _=>return false,
        };
        select.kind==CheckedQueryClauseKind::Select&&select.expressions.len()==1
            &&self.types.node_types.get(&select.expressions[0])==Some(result)
            &&self.source_require_contained_query(scenario,call,query)
    }

    /// Raw native count correspondence stays independent of observer/query
    /// inventories, so selecting a whole observer cannot recurse into itself.
    fn source_require_native_count(
        &self, scenario: &super::effects::ScenarioData, call: &CheckedDecisionCall,
    ) -> Option<DisclosureQuery> {
        let (supplied, _) = call.slots.first().copied().flatten().and_then(|slot| call.arguments.get(slot))?;
        let model = self.count_domain_model(*supplied)??;
        scenario.guards.iter().find_map(|guard| {
            let node = guard.cond?;
            if node.file != call.node.file || node.start > call.node.start || call.node.end > node.end {
                return None;
            }
            self.checked_assign_count_query_source(scenario, guard.node, call.node, *supplied, model)
                .or_else(|| self.checked_count_query_source(scenario, guard.node, call.node, *supplied, model))
        })
    }

    fn source_require_observer_count(&self, scenario: &super::effects::ScenarioData,
        call: &CheckedDecisionCall) -> bool {
        self.source_require_contained_collection(scenario, call, "count")
            || self.source_require_native_count(scenario, call).is_some_and(|query|
                query.count.is_some_and(|count| count.contained_parent.is_some()))
    }

    /// One leading guard may need a helper's Model ANY and a contained
    /// COUNT together. Prefer its complete observer only after the ordinary
    /// call, expression and parameter checks admit the entire source site.
    /// This candidate test never calls the query inventory or grants a query.
    fn source_require_helper_count_site(
        &self,
        scenario: &super::effects::ScenarioData,
        site: &CheckedDecisionSite,
    ) -> bool {
        if site.stage != CheckedDecisionStage::LeadingRequire {
            return false;
        }
        let contained_count = site.calls.iter().any(|call|
            call.chain.is_empty()
                && matches!(&call.target, CheckedDecisionCallTarget::Builtin { id, .. } if id == "count")
                && self.types.node_types.get(&call.node) == Some(&ResolvedType::Scalar(Scalar::Int))
                && self.source_require_observer_count(scenario, call));
        contained_count && site.calls.iter().any(|call| {
            let CheckedDecisionCallTarget::Builtin { id, overload } = &call.target else {
                return false;
            };
            if id != "any" || call.chain.is_empty() {
                return false;
            }
            let mut helper_query = false;
            let mut supported = true;
            self.source_require_any_call(scenario, false, call, id, overload,
                &mut helper_query, &mut supported) == Some(true)
                && supported && helper_query
        })
    }

    fn checked_source_helper_count_sites(&self, scenario: &super::effects::ScenarioData) -> Vec<CheckedDecisionSite> {
        // Avoid adding observer preparation to unrelated released query paths.
        if !self.checked_decision_sites(scenario).is_some_and(|sites|
            sites.iter().any(|site| self.source_require_helper_count_site(scenario, site)))
        {
            return Vec::new();
        }
        self.checked_source_requires(scenario).unwrap_or_default().into_iter()
            .filter(|site| self.source_require_helper_count_site(scenario, site)).collect()
    }

    fn source_require_call(
        &self,
        scenario: &super::effects::ScenarioData,
        body: bool,
        whole_count_observer: bool,
        call: &CheckedDecisionCall,
        helper_query: &mut bool,
        supported: &mut bool,
    ) -> Option<bool> {
        if !call.defaults.is_empty() || call.slots.iter().any(Option::is_none) {
            *supported = false;
            return Some(false);
        }
        // These original calendar operations are checked pure Values calls.
        // All model-backed arguments still pass the source observer's field
        // readers; only the dates allocation has an additional finite bound.
        if let CheckedDecisionCallTarget::Builtin{id,..}=&call.target {
            if matches!(id.as_str(),"dates"|"local_date"|"local_instant"|"add_days"|"weekday"|"overlaps")
                && self.catalog.and_then(|catalog|catalog.effects(id))==Some(super::catalog::Effects::Pure)
                && (id!="dates" || self.source_require_dates_call(call.node))
                && call.arguments.iter().all(|(_,ty)|self.source_require_plain_value(ty,0)
                    || matches!(ty,ResolvedType::Enum{cases,..} if !cases.is_empty()))
                && self.types.node_types.get(&call.node).is_some_and(|ty|self.source_require_plain_value(ty,0))
            {return Some(true);}
            if matches!(id.as_str(),"any"|"all") && call.slots.as_slice()==[Some(0),Some(1)]
                && call.arguments.len()==2 && call.arguments[1].1==ResolvedType::Scalar(Scalar::Bool)
                && self.types.node_types.get(&call.node)==Some(&ResolvedType::Scalar(Scalar::Bool))
                && self.types.checked_queries.get(&call.arguments[0].0).is_some_and(|query|self.source_require_dates_query(query))
            {return Some(true);}
        }
        // Pure checked Values collections run over the admitted input, never
        // through State's stored-model collection reader.
        if let CheckedDecisionCallTarget::Builtin { id, .. } = &call.target {
            if matches!(id.as_str(), "all" | "count" | "group" | "min" | "max")
                && call.arguments.iter().all(|(_, ty)| self.source_require_plain_value(ty, 0))
                && self.types.node_types.get(&call.node).is_some_and(|ty| self.source_require_plain_value(ty, 0))
                && call.arguments.iter().all(|(node, _)| self.types.checked_queries.get(node)
                    .is_none_or(|query| self.source_require_value_query(query)))
            { return Some(true); }
        }
        match &call.target {
            CheckedDecisionCallTarget::Role(id)=>{
                let user=|ty:&ResolvedType|ty==&ResolvedType::Scalar(Scalar::User)
                    ||matches!(ty,ResolvedType::Nullable(inner)if inner.as_ref()==&ResolvedType::Scalar(Scalar::User));
                let valid=self.resolve.symbols.get(id.0 as usize).is_some_and(|role|matches!(role.kind,SymbolKind::Role))
                    &&call.slots.as_slice()==[Some(0)]&&call.arguments.len()==1&&call.defaults.is_empty()
                    &&user(&call.arguments[0].1)&&self.types.node_types.get(&call.node)==Some(&ResolvedType::Scalar(Scalar::Bool));
                if !valid{*supported=false;}Some(valid)
            },
            CheckedDecisionCallTarget::DeriveFn(id) => {
                self.source_require_derive_call(id, supported)
            }
            CheckedDecisionCallTarget::Builtin { id, overload } if id == "any" => {
                self.source_require_any_call(scenario, body, call, id, overload, helper_query, supported)
            }
            CheckedDecisionCallTarget::Builtin { id, overload: 0 } if id == "all" => {
                let reference_array = (|| {
                    let fact = self.types.checked_collection_calls.get(&call.node)?;
                    let [(domain, domain_ty), (predicate, predicate_ty)] = call.arguments.as_slice() else { return None; };
                    let query = self.types.checked_queries.get(domain)?;
                    let [alias] = query.clauses.as_slice() else { return None; };
                    let array = ResolvedType::Array {
                        element: Box::new(ResolvedType::Record { symbol: fact.model, stored: true }),
                        ordered: true, nonempty: false,
                    };
                    (call.slots.as_slice() == [Some(0), Some(1)]
                        && self.source_require_any_attrs(fact, call, id, &0, domain, predicate,
                            query, alias, &array, domain_ty, predicate_ty)
                        && self.source_require_reference_query(scenario, call, query)).then_some(())
                })().is_some();
                if !reference_array
                    && !self.source_require_contained_collection(scenario, call, "all") {
                    *supported = false;
                    return Some(false);
                }
                Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, .. } if id == "first" => {
                if !self.source_require_contained_collection(scenario, call, "first") {
                    *supported = false; return Some(false);
                }
                *helper_query = true;
                Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, .. } if id == "min" => {
                let scalar = |ty: &ResolvedType| matches!(ty, ResolvedType::Scalar(_))
                    || matches!(ty, ResolvedType::Nullable(inner) if matches!(inner.as_ref(), ResolvedType::Scalar(_)));
                if call.slots.as_slice() != [Some(0)] || call.arguments.len() != 1
                    || !matches!(&call.arguments[0].1, ResolvedType::Array {element, ordered:true, ..} if scalar(element))
                    || !self.types.node_types.get(&call.node).is_some_and(scalar)
                { *supported = false; return Some(false); }
                Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, overload: 0 } if id == "trim" => {
                if call.arguments.len() != 1
                    || call.slots.as_slice() != [Some(0)]
                    || call.arguments[0].1 != ResolvedType::Scalar(Scalar::Text)
                    || self.types.node_types.get(&call.node)
                        != Some(&ResolvedType::Scalar(Scalar::Text))
                {
                    *supported = false;
                    return Some(false);
                }
                Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, .. } if id == "active_member" => {
                self.checked_membership_signature(call.node, call.module)?;
                Some(true)
            }
            // A leading COUNT may use an independently checked contained
            // Model collection. The existing primitive Text-array count
            // remains separate and carries no collection-query authority.
            CheckedDecisionCallTarget::Builtin { id, .. } if id == "sum" && !body => {
                if !self.source_require_contained_sum(scenario,call){*supported=false;return Some(false);}
                *helper_query=true;Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, .. } if id == "count" && !body => {
                if !whole_count_observer && self.source_require_native_count(scenario,call).is_some(){*supported=false;return Some(false);}
                if (self.source_require_contained_collection(scenario,call,"count")
                    || whole_count_observer && self.source_require_observer_count(scenario, call)
                    || call.slots.as_slice() == [Some(0)] && call.arguments.len() == 1
                        && self.source_require_reference_domain(scenario, call, call.arguments[0].0, call.chain.len(), 0))
                    && self.types.node_types.get(&call.node)==Some(&ResolvedType::Scalar(Scalar::Int))
                { *helper_query=true; return Some(true); }
                if call.slots.as_slice() != [Some(0)] || call.arguments.len() != 1
                    || !matches!(&call.arguments[0].1, ResolvedType::Array { element, .. }
                        if element.as_ref() == &ResolvedType::Scalar(Scalar::Text))
                    || self.types.node_types.get(&call.node) != Some(&ResolvedType::Scalar(Scalar::Int))
                { *supported = false; return Some(false); }
                Some(true)
            }
            CheckedDecisionCallTarget::Builtin { id, .. }
                if body
                    && matches!(
                        id.as_str(),
                        "sum"
                            | "count"
                            | "money"
                            | "abs"
                            | "round"
                            | "min"
                            | "max"
                            | "date"
                            | "datetime"
                    ) =>
            {
                if matches!(id.as_str(), "sum" | "count") {
                    *helper_query = true;
                }
                Some(true)
            }
            _ => {
                *supported = false;
                Some(false)
            }
        }
    }

    fn source_require_walk_member(
        &self,
        scenario: &super::effects::ScenarioData,
        site: &CheckedDecisionSite,
        body: bool,
        key: NodeKey,
        node: &SyntaxNode,
        supported: &mut bool,
        helper_query: &mut bool,
    ) -> Option<bool> {
        // A nullable admitted model must retain its null/row identity and
        // any later narrowed parent/field reads inside the same observer.
        // Ordinary scalar null checks remain on their existing path.
        if matches!(self.query_binding(key), Some(Binding::Symbol(parameter))
            if scenario.params.iter().any(|input| input.param == *parameter)
                && matches!(self.types.symbol_types.get(parameter),Some(ResolvedType::Nullable(inner))
                    if matches!(inner.as_ref(),ResolvedType::Record {stored:true,..})))
        { *helper_query = true; }
        // Nullable immutable Values inputs keep their original boolean
        // short-circuit recipe, rather than expanding mutually exclusive
        // null/value cases into unrelated static return paths. These slots
        // grant no row/query authority; the whole source observer stays sealed.
        if matches!(self.query_binding(key), Some(Binding::Symbol(parameter))
            if scenario.params.iter().any(|input| input.param == *parameter)
                && matches!(self.types.symbol_types.get(parameter), Some(ResolvedType::Nullable(inner))
                    if matches!(inner.as_ref(), ResolvedType::Scalar(_))
                        && self.source_require_plain_value(inner, 0)))
        { *helper_query = true; }
        // Required stored-reference guards are owner decisions too. Keep
        // their original lazy navigation inside the independently sealed
        // guard observer; no field grant escapes into a later expression.
        if !body && node.kind == SyntaxKind::Member
            && self.checked_required_reference_scalar(key, scenario.module).is_some()
        { *helper_query = true; }
        // A required input’s original nullable stored reference must keep
        // its authored null test and lazy navigation in this same observer.
        // Matching a target Model type does not prove an input field path.
        if node.kind == SyntaxKind::Member
            && let Some((base, name)) = self.count_member(key)
            && let Some(ResolvedType::Record { symbol: model, stored: true }) = self.types.node_types.get(&base)
            && scenario.params.iter().any(|parameter|
                self.checked_call_parent_path(base, parameter.param, 0) == Some((*model, 0)))
            && self.effects.models.get(model).is_some_and(|owner| owner.fields.iter().any(|field|
                self.resolve.symbols.get(field.field.0 as usize).is_some_and(|declaration|
                    declaration.name == name && matches!(declaration.kind, SymbolKind::Field { owner, .. } if owner == *model))
                && matches!(self.types.symbol_types.get(&field.field), Some(ResolvedType::Nullable(inner))
                    if matches!(inner.as_ref(), ResolvedType::Record { stored: true, .. }))))
        { *helper_query = true; }
        if site.stage==CheckedDecisionStage::BodyCondition && node.kind==SyntaxKind::Member
            && self.count_member(key).is_some_and(|(base,name)|name=="version"
                && matches!(self.types.node_types.get(&base),Some(ResolvedType::Record{stored:true,..})))
        {
            let admitted=self.source_require_loop_condition(scenario,site).is_some()
                &&self.count_member(key).is_some_and(|(base,_)|matches!(self.query_binding(base),Some(Binding::Symbol(id))
                    if scenario.params.iter().any(|parameter|parameter.param==*id)));
            if !admitted{*supported=false;return Some(false);}
        }
        if body {
            match self.query_binding(key) {
                Some(Binding::ForItem{node}) if self.source_require_loop_condition(scenario,site).is_some_and(|(outer,_)|outer.node==*node)=>{},
                Some(Binding::Let { .. } | Binding::CreateAs { .. } | Binding::SendAs { .. }
                    | Binding::ForItem { .. } | Binding::CallAs { .. } | Binding::CohortChild { .. }
                    | Binding::External { .. } | Binding::Error) => { *supported = false; return Some(false); }
                Some(Binding::Symbol(id)) if matches!(self.resolve.symbols.get(id.0 as usize)?.kind, SymbolKind::Param { .. })
                    && !scenario.params.iter().any(|parameter| parameter.param == *id)
                    && !site.calls.iter().any(|call| matches!(call.target, CheckedDecisionCallTarget::DeriveFn(derive)
                        if self.effects.derives.get(&derive).is_some_and(|derive| derive.params.iter().any(|parameter| parameter.param == *id)))) => {
                    *supported = false; return Some(false);
                }
                _ => {}
            }
        }
        if node.kind == SyntaxKind::Member
            && let Some((base, name)) = self.count_member(key)
            && let Some(ResolvedType::Record { symbol: model, stored: true }) = self.types.node_types.get(&base)
            && let Some(field) = self.resolve.symbols.iter().find(|field| field.name == name
                && matches!(field.kind, SymbolKind::DeriveField { model: owner, .. } if owner == *model))
        {
            if self.source_require_derived_control(field.id, *model, &mut Vec::new(), &mut 4096).is_none()
                && self.admitted_derived_read(field.id, *model, &mut Vec::new()).is_none()
            {
                *supported = false; return Some(false);
            }
            *helper_query = true;
        }
        Some(true)
    }

    fn source_require_walk_query(
        &self,
        scenario: &super::effects::ScenarioData,
        site: &CheckedDecisionSite,
        body: bool,
        key: NodeKey,
        node: &SyntaxNode,
        supported: &mut bool,
    ) -> Option<bool> {
        if self.source_require_expression_shape(key).is_none() {
            *supported = false;
            return Some(false);
        }
        if node.kind == SyntaxKind::Query
            && self.types.checked_queries.get(&key).is_some_and(|query| self.source_require_value_query(query) || self.source_require_dates_query(query))
        { return Some(true); }
        if node.kind == SyntaxKind::Query
            && self.types.checked_queries.get(&key).is_some_and(|query|
                site.calls.iter().any(|call| self.source_require_contained_query(scenario, call, query)))
        {
            return Some(true);
        }
        if node.kind == SyntaxKind::Query
            && !site.calls.iter().any(|call| {
                matches!(&call.target, CheckedDecisionCallTarget::Builtin {id, ..} if id == "any")
                    && self.types.checked_collection_calls.get(&call.node).is_some_and(|fact| fact.query == key)
                    || matches!(&call.target, CheckedDecisionCallTarget::Builtin {id, ..} if id == "all")
                        && self.types.checked_collection_calls.get(&call.node).is_some_and(|fact| fact.query == key)
                    || body && matches!(&call.target, CheckedDecisionCallTarget::Builtin {id, ..} if matches!(id.as_str(), "sum" | "count"))
                        && call.arguments.iter().any(|(argument, _)| self.query_group(*argument) == Some(key))
            })
        {
            *supported = false;
            return Some(false);
        }
        if body && node.kind == SyntaxKind::Query
            && site.calls.iter().any(|call| {
                matches!(&call.target, CheckedDecisionCallTarget::Builtin { id, .. } if matches!(id.as_str(), "sum" | "count"))
                    && call.arguments.iter().any(|(argument, _)| self.query_group(*argument) == Some(key))
            })
        {
            let query = self.types.checked_queries.get(&key)?;
            let Some((receiver, child_name)) = self.count_member(query.domain) else { *supported = false; return Some(false); };
            let Some(ResolvedType::Record { symbol: parent, stored: true }) = self.types.node_types.get(&receiver) else { *supported = false; return Some(false); };
            let ResolvedType::Array { element, ordered: true, nonempty: false } = &query.domain_type else { *supported = false; return Some(false); };
            let ResolvedType::Record { symbol: child, stored: true } = element.as_ref() else { *supported = false; return Some(false); };
            let declaration = self.resolve.symbols.get(child.0 as usize)?;
            if declaration.name != child_name
                || !matches!(declaration.kind, SymbolKind::Model { owner: ModelOwner::ChildOf(owner), .. } if owner == *parent)
                || query.projection.is_some()
                || query.clauses.iter().any(|clause| !matches!(clause.kind,
                    CheckedQueryClauseKind::As { .. } | CheckedQueryClauseKind::Where | CheckedQueryClauseKind::Select))
            { *supported = false; return Some(false); }
        }
        Some(true)
    }

    fn source_require_observer_walk(
        &self,
        scenario: &super::effects::ScenarioData,
        site: &CheckedDecisionSite,
        body: bool,
        supported: &mut bool,
        helper_query: &mut bool,
    ) -> Option<()> {
        // Do not turn an arbitrary otherwise-unsupported expression into
        // an observer guard. Only this evaluator's scalar expression forms
        // and the checked ANY query domains above can enter this source fact.
        let mut pending = vec![site.node];
        pending.extend(site.calls.iter().filter_map(|call| match call.target {
            CheckedDecisionCallTarget::DeriveFn(id) => self.effects.derives.get(&id)?.expr,
            _ => None,
        }));
        let mut steps = 0usize;
        while let Some(key) = pending.pop() {
            steps += 1;
            if steps > 16384 {
                return None;
            }
            let node = self.nodes.get(&key)?;
            if !self.source_require_walk_member(scenario, site, body, key, node, supported, helper_query)? {
                break;
            }
            if !self.source_require_walk_query(scenario, site, body, key, node, supported)? {
                break;
            }
            pending.extend(node.children.iter().map(NodeKey::of));
        }
        Some(())
    }

    fn source_require_site_guard(
        &self,
        guard: &Effect,
        site: &CheckedDecisionSite,
    ) -> Option<()> {
        if guard.verb != EffectVerb::Require
            || guard.node != site.statement
            || guard.cond != Some(site.node)
            || !guard.then_effects.is_empty()
            || !guard.else_effects.is_empty()
            || !guard.match_arms.is_empty()
            || self.nodes.get(&guard.node)?.kind != SyntaxKind::Require
            || self.types.node_types.get(&site.node)
                != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        Some(())
    }

    /// A reached IF arm may contain an initial-stage Require. Every prefix
    /// on that exact original path must be write-free; loop/match bodies and
    /// guards after any staged effect keep their independent refusal.
    fn source_require_body_guard<'b>(&self,scenario:&'b super::effects::ScenarioData,
        path:&[CheckedDecisionPosition])->Option<&'b Effect> {
        let (CheckedDecisionPosition::Body(index),nested)=path.split_first()? else{return None;};
        if !scenario.effects.get(..*index)?.iter().all(|effect|self.source_require_before_write(effect)){return None;}
        let mut effect=scenario.effects.get(*index)?;
        for position in nested {
            if effect.verb!=EffectVerb::If || !effect.match_arms.is_empty(){return None;}
            let (branch,index)=match position {
                CheckedDecisionPosition::Then(index)=>(&effect.then_effects,*index),
                CheckedDecisionPosition::Else(index)=>(&effect.else_effects,*index),
                _=>return None,
            };
            if !branch.get(..index)?.iter().all(|effect|self.source_require_before_write(effect)){return None;}
            effect=branch.get(index)?;
        }
        Some(effect)
    }

    fn source_require_loop_condition<'b>(&self,scenario:&'b super::effects::ScenarioData,site:&CheckedDecisionSite)->Option<(&'b Effect,&'b Effect)> {
        let [CheckedDecisionPosition::Body(index),CheckedDecisionPosition::Loop(child)]=site.position.as_slice() else{return None;};
        let outer=scenario.effects.get(*index)?;
        let condition=outer.then_effects.get(*child)?;
        if outer.verb!=EffectVerb::For||*child!=0||outer.then_effects.len()!=1||outer.cond.is_some()
            ||!outer.else_effects.is_empty()||!outer.match_arms.is_empty()
            ||condition.verb!=EffectVerb::If||condition.cond!=Some(site.node)||condition.node!=site.statement
            ||!condition.else_effects.is_empty()||!condition.match_arms.is_empty()
            ||!matches!(condition.then_effects.as_slice(),[effect]if effect.verb==EffectVerb::Set)
        {return None;}
        Some((outer,condition))
    }

    fn source_require_site(
        &self,
        scenario: &super::effects::ScenarioData,
        site: CheckedDecisionSite,
        out: &mut Vec<CheckedDecisionSite>,
    ) -> Option<()> {
        let (guard, body) = match (site.position.as_slice(), site.stage) {
            ([CheckedDecisionPosition::Guard(index)], CheckedDecisionStage::LeadingRequire) => {
                (scenario.guards.get(*index)?, false)
            }
            (path,CheckedDecisionStage::BodyRequire) if self.source_require_body_guard(scenario,path).is_some()=>{
                (self.source_require_body_guard(scenario,path)?,true)
            }
            (path,CheckedDecisionStage::BodyCondition) if matches!(path,[CheckedDecisionPosition::Body(_)]) || self.source_require_loop_condition(scenario,&site).is_some() => {
                let effect=if let Some((_,condition))=self.source_require_loop_condition(scenario,&site){condition}else{
                    let [CheckedDecisionPosition::Body(index)]=path else{return None;};scenario.effects.get(*index)?};
                // One original top-level IF observes the actual owner stage.
                // Loop locals and branch-local aliases need their own producer.
                if effect.verb!=EffectVerb::If||effect.cond!=Some(site.node)
                    ||effect.node!=site.statement||!effect.match_arms.is_empty()
                    ||self.types.node_types.get(&site.node)!=Some(&ResolvedType::Scalar(Scalar::Bool))
                    ||scenario.params.iter().filter(|parameter|matches!(self.types.symbol_types.get(&parameter.param),
                        Some(ResolvedType::Record{stored:true,..}))).count()!=1
                    ||scenario.params.iter().any(|parameter|matches!(self.types.symbol_types.get(&parameter.param),
                        Some(ResolvedType::Nullable(inner)|ResolvedType::Array{element:inner,..})
                            if matches!(inner.as_ref(),ResolvedType::Record{stored:true,..})))
                    ||scenario.params.iter().any(|parameter|matches!(self.types.symbol_types.get(&parameter.param),
                        Some(ResolvedType::Scalar(Scalar::File)))||matches!(self.types.symbol_types.get(&parameter.param),
                        Some(ResolvedType::Nullable(inner)) if inner.as_ref()==&ResolvedType::Scalar(Scalar::File)))
                {return Some(());}
                (effect,true)
            }
            _ => return Some(()),
        };
        if site.stage!=CheckedDecisionStage::BodyCondition { self.source_require_site_guard(guard, &site)?; }
        let mut supported = true;
        let mut helper_query = false;
        let whole_count_observer = self.source_require_helper_count_site(scenario, &site);
        for call in &site.calls {
            if !self.source_require_call(scenario, body, whole_count_observer, call, &mut helper_query, &mut supported)? {
                break;
            }
        }
        self.source_require_observer_walk(scenario, &site, body, &mut supported, &mut helper_query)?;
        if supported && helper_query {
            out.push(site);
        }
        Some(())
    }

    fn checked_source_requires(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedDecisionSite>> {
        if scenario.read
            || scenario.on.is_some()
            || scenario.cohort.is_some()
            || scenario.scope_authority
        {
            return Some(Vec::new());
        }
        if !self.source_require_params_ok(scenario) {
            return Some(Vec::new());
        }
        let mut out = Vec::new();
        for site in self.checked_decision_sites(scenario)? {
            self.source_require_site(scenario, site, &mut out)?;
        }
        Some(out)
    }

    /// A body read of the same original required Model input may carry its
    /// declared reference array into a checked create/set. No Scope bounds are
    /// borrowed, and the whole stored field remains an ordinary dependency.
    fn source_require_reference_array(&self, key: NodeKey, module: ModuleId) -> Option<String> {
        let (base, name) = self.count_member(key)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(base) else {
            return None;
        };
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.symbol_types.get(parameter)?
        else {
            return None;
        };
        let scenario = self.effects.scenarios.values().find(|scenario| {
            scenario.module == module
                && scenario
                    .params
                    .iter()
                    .any(|param| param.param == *parameter)
        })?;
        if !scenario
            .effects
            .iter()
            .any(|effect| effect.node.start <= key.start && key.end <= effect.node.end)
            || self.checked_source_requires(scenario)?.is_empty()
            || self.checked_call_parent_path(base, *parameter, 0) != Some((*model, 0))
        {
            return None;
        }
        let field = self
            .effects
            .models
            .get(model)?
            .fields
            .iter()
            .find(|field| {
                self.resolve
                    .symbols
                    .get(field.field.0 as usize)
                    .is_some_and(|decl| decl.name == name)
            })?;
        let ty = self.types.symbol_types.get(&field.field)?;
        if !matches!(ty, ResolvedType::Array { .. })
            || self.types.node_types.get(&key) != Some(ty)
            || field.default.is_some()
            || field.server.is_some()
        {
            return None;
        }
        self.reference_operand_type_id(ty)
    }

    fn checked_decision_sites(
        &self,
        scenario: &super::effects::ScenarioData,
    ) -> Option<Vec<CheckedDecisionSite>> {
        let mut sites = Vec::new();
        let mut steps = 0usize;
        let mut calls = 0usize;
        let mut pending = Vec::new();
        for (index, effect) in scenario.effects.iter().enumerate().rev() {
            pending.push((effect, vec![CheckedDecisionPosition::Body(index)], false));
        }
        for (index, effect) in scenario.guards.iter().enumerate().rev() {
            pending.push((effect, vec![CheckedDecisionPosition::Guard(index)], true));
        }
        while let Some((effect, position, leading)) = pending.pop() {
            steps += 1;
            if steps > 16384 || position.len() > 64 || !self.nodes.contains_key(&effect.node) {
                return None;
            }
            if let Some((node, stage)) = Self::decision_effect_stage(effect, leading) {
                self.decision_site(
                    scenario,
                    node,
                    stage,
                    effect.node,
                    position.clone(),
                    &mut sites,
                    &mut steps,
                    &mut calls,
                )?;
            }
            Self::push_nested_effects(&mut pending, effect, &position);
            if pending.len() > 16384 {
                return None;
            }
        }
        Some(sites)
    }

    /// The decision a scenario effect carries: `require`/`if` conditions
    /// and `send` dispatches.
    fn decision_effect_stage(
        effect: &Effect,
        leading: bool,
    ) -> Option<(NodeKey, CheckedDecisionStage)> {
        match effect.verb {
            EffectVerb::Require => Some((
                effect.cond?,
                if leading {
                    CheckedDecisionStage::LeadingRequire
                } else {
                    CheckedDecisionStage::BodyRequire
                },
            )),
            EffectVerb::Send => effect
                .when
                .map(|node| (node, CheckedDecisionStage::SendDispatch)),
            EffectVerb::If => Some((effect.cond?, CheckedDecisionStage::BodyCondition)),
            _ => None,
        }
    }

    /// Record one decision site: its expression must check and its source
    /// resolve.
    #[allow(clippy::too_many_arguments)]
    fn decision_site(
        &self,
        scenario: &super::effects::ScenarioData,
        node: NodeKey,
        stage: CheckedDecisionStage,
        statement: NodeKey,
        position: Vec<CheckedDecisionPosition>,
        sites: &mut Vec<CheckedDecisionSite>,
        steps: &mut usize,
        calls: &mut usize,
    ) -> Option<()> {
        if sites.len() >= 200
            || self.types.node_types.get(&node) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        let mut selected = Vec::new();
        self.checked_decision_expression(
            node,
            scenario.module,
            &[],
            &mut HashSet::new(),
            &mut selected,
            steps,
            calls,
            0,
        )?;
        sites.push(CheckedDecisionSite {
            owner: scenario.scenario,
            source: self.source(scenario.module, node).ok()?,
            node,
            statement,
            stage,
            position,
            calls: selected,
        });
        Some(())
    }

    /// Queue an effect's nested arms for decision collection.
    fn push_nested_effects<'e>(
        pending: &mut Vec<(&'e Effect, Vec<CheckedDecisionPosition>, bool)>,
        effect: &'e Effect,
        position: &[CheckedDecisionPosition],
    ) {
        for (arm_index, arm) in effect.match_arms.iter().enumerate().rev() {
            for (index, child) in arm.effects.iter().enumerate().rev() {
                let mut nested = position.to_vec();
                nested.push(CheckedDecisionPosition::Match {
                    arm: arm_index,
                    statement: index,
                });
                pending.push((child, nested, false));
            }
        }
        for (index, child) in effect.else_effects.iter().enumerate().rev() {
            let mut nested = position.to_vec();
            nested.push(CheckedDecisionPosition::Else(index));
            pending.push((child, nested, false));
        }
        for (index, child) in effect.then_effects.iter().enumerate().rev() {
            let mut nested = position.to_vec();
            nested.push(if effect.verb == EffectVerb::For {
                CheckedDecisionPosition::Loop(index)
            } else {
                CheckedDecisionPosition::Then(index)
            });
            pending.push((child, nested, false));
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn checked_decision_expression(
        &self,
        key: NodeKey,
        module: ModuleId,
        chain: &[CheckedDecisionCallFrame],
        stack: &mut HashSet<SymbolId>,
        out: &mut Vec<CheckedDecisionCall>,
        steps: &mut usize,
        calls: &mut usize,
        depth: usize,
    ) -> Option<()> {
        *steps += 1;
        if *steps > 16384 || depth > 64 || chain.len() > 16 {
            return None;
        }
        let node = self.nodes.get(&key)?;
        let source = self.source(module, key).ok()?;
        if matches!(node.kind, SyntaxKind::Error | SyntaxKind::BadToken) {
            return None;
        }
        // Structural traversal preserves every lazy operand's source. It does
        // not assert which operands execute, or evaluate any expression.
        for child in &node.children {
            self.checked_decision_expression(
                NodeKey::of(child),
                module,
                chain,
                stack,
                out,
                steps,
                calls,
                depth + 1,
            )?;
        }
        if node.kind != SyntaxKind::Call {
            return Some(());
        }
        *calls += 1;
        if *calls > 200 {
            return None;
        }
        if !self.types.node_types.get(&key)?.is_resolved_shape() {
            return None;
        }
        let selected = self.types.selected_calls.get(&key)?;
        let arguments = self.decision_call_arguments(key, module, selected)?;
        let (target, defaults) = self.decision_call_target(chain, stack, selected)?;
        out.push(CheckedDecisionCall {
            node: key,
            module,
            source: source.clone(),
            target: target.clone(),
            arguments,
            slots: selected.slots.clone(),
            defaults: defaults.clone(),
            chain: chain.to_vec(),
        });
        if let CheckedDecisionCallTarget::DeriveFn(id) = target {
            self.decision_derive_recurse(
                key, module, source, chain, stack, out, steps, calls, id, defaults,
            )?;
        }
        Some(())
    }

    /// One decision call's arguments: present, sourced and checked,
    /// with slots covering them exactly once.
    fn decision_call_arguments(
        &self,
        key: NodeKey,
        module: ModuleId,
        selected: &super::types::SelectedCall,
    ) -> Option<Vec<(NodeKey, ResolvedType)>> {
        let mut arguments = Vec::new();
        for argument in &selected.arguments {
            self.nodes.get(argument)?;
            self.source(module, *argument).ok()?;
            let ty = self.types.node_types.get(argument)?;
            if !ty.is_resolved_shape() {
                return None;
            }
            arguments.push((*argument, ty.clone()));
        }
        let mut seen = HashSet::new();
        for index in selected.slots.iter().flatten() {
            if *index >= arguments.len() || !seen.insert(*index) {
                return None;
            }
        }
        if seen.len() != arguments.len() {
            return None;
        }
        Some(arguments)
    }

    /// One decision call's target: a fully-slotted builtin or an
    /// admitted derive with its defaulted parameters.
    fn decision_call_target(
        &self,
        chain: &[CheckedDecisionCallFrame],
        stack: &HashSet<SymbolId>,
        selected: &super::types::SelectedCall,
    ) -> Option<(CheckedDecisionCallTarget, Vec<(SymbolId, NodeKey)>)> {
        match &selected.target {
            SelectedCallTarget::Role(id) if selected.arguments.len()==1&&selected.slots.as_slice()==[Some(0)]
                &&self.resolve.symbols.get(id.0 as usize).is_some_and(|role|matches!(role.kind,SymbolKind::Role))=>
                Some((CheckedDecisionCallTarget::Role(*id),Vec::new())),
            SelectedCallTarget::Builtin { id, overload } => {
                if selected.slots.iter().any(Option::is_none) {
                    return None;
                }
                Some((
                    CheckedDecisionCallTarget::Builtin {
                        id: id.clone(),
                        overload: *overload,
                    },
                    Vec::new(),
                ))
            }
            SelectedCallTarget::DeriveFn(id) => {
                let data = self.effects.derives.get(id)?;
                let declaration = self.resolve.symbols.get(id.0 as usize)?;
                if !matches!(declaration.kind, SymbolKind::DeriveFn { .. })
                    || declaration.module != data.module
                    || data.derive != *id
                    || data.params.len() != selected.slots.len()
                    || chain.len() >= 16
                    || stack.contains(id)
                {
                    return None;
                }
                let mut defaults = Vec::new();
                for (param, slot) in data.params.iter().zip(&selected.slots) {
                    if slot.is_none() {
                        let default = param.default?;
                        self.nodes.get(&default)?;
                        self.source(data.module, default).ok()?;
                        if !self.types.node_types.get(&default)?.is_resolved_shape() {
                            return None;
                        }
                        defaults.push((param.param, default));
                    }
                }
                Some((CheckedDecisionCallTarget::DeriveFn(*id), defaults))
            }
            _ => None,
        }
    }

    /// Recurse into one derive target: its defaults and body under a
    /// pushed call frame with cycle protection.
    #[allow(clippy::too_many_arguments)]
    fn decision_derive_recurse(
        &self,
        key: NodeKey,
        module: ModuleId,
        source: DisclosureSource,
        chain: &[CheckedDecisionCallFrame],
        stack: &mut HashSet<SymbolId>,
        out: &mut Vec<CheckedDecisionCall>,
        steps: &mut usize,
        calls: &mut usize,
        id: SymbolId,
        defaults: Vec<(SymbolId, NodeKey)>,
    ) -> Option<()> {
        let data = self.effects.derives.get(&id)?;
        let mut nested = chain.to_vec();
        nested.push(CheckedDecisionCallFrame {
            node: key,
            module,
            source,
            derive: id,
        });
        stack.insert(id);
        for (_, default) in defaults {
            self.checked_decision_expression(
                default,
                data.module,
                &nested,
                stack,
                out,
                steps,
                calls,
                0,
            )?;
        }
        self.checked_decision_expression(
            data.expr?,
            data.module,
            &nested,
            stack,
            out,
            steps,
            calls,
            0,
        )?;
        stack.remove(&id);
        Some(())
    }

    fn source(
        &self,
        module: ModuleId,
        node: NodeKey,
    ) -> Result<DisclosureSource, DisclosureDecline> {
        let owner = self
            .resolve
            .modules
            .get(module.0 as usize)
            .ok_or_else(|| self.fail(node, "missing declaring module"))?;
        let source = self
            .db
            .get(node.file)
            .ok_or_else(|| self.fail(node, "missing source"))?;
        if owner.file != node.file || node.start > node.end || node.end as usize > source.text.len()
        {
            return Err(self.fail(node, "source/module anchor mismatch"));
        }
        Ok(DisclosureSource {
            path: source.path.clone(),
            sha256: source.sha256.clone(),
            module: owner.name.clone(),
        })
    }

    fn opaque(
        &self,
        kind: &str,
        node: NodeKey,
        discriminator: &str,
    ) -> Result<String, DisclosureDecline> {
        Ok(sha256_hex(
            format!(
                "scenario-disclosure/v1:{kind}:{}:{discriminator}",
                self.key_stamp(node)?
            )
            .as_bytes(),
        ))
    }

    fn control(&self, mut value: ValuePath) -> Result<ValuePath, DisclosureDecline> {
        for read in &mut value.reads {
            // Constructing the original selected TextMessage eagerly consumes
            // its DATA fields even when count later uses only cardinality.
            // Query association alone never exempts another ordinary read.
            if self.transcript_selection_dependency(read) {
                continue;
            }
            read.role = DependencyRole::Control;
            read.id = self.opaque("read-control", read.node, &self.call_stamp(&read.calls)?)?;
        }
        for intrinsic in &mut value.intrinsics {
            intrinsic.role = DependencyRole::Control;
            intrinsic.id = self.opaque(
                "intrinsic-control",
                intrinsic.node,
                &self.call_stamp(&intrinsic.calls)?,
            )?;
        }
        Ok(value)
    }

    fn transcript_selection_dependency(&self, read: &DisclosureDependency) -> bool {
        let [call] = read.calls.as_slice() else {
            return false;
        };
        let Some(query_id) = read.query_id.as_deref() else {
            return false;
        };
        if read.role != DependencyRole::Data {
            return false;
        }
        self.effects.scenarios.values().any(|scenario| {
            scenario
                .guards
                .iter()
                .chain(&scenario.effects)
                .any(|statement| {
                    statement.node.file == call.file
                        && statement.node.start <= call.start
                        && call.end <= statement.node.end
                        && self
                            .checked_transcript_source(scenario, statement.node, *call)
                            .is_some_and(|fact| {
                                fact.id == query_id
                                    && fact.call == *call
                                    && fact.source == read.source
                                    && fact.dependencies.iter().any(|original| original == read)
                            })
                })
        })
    }

    fn influence(
        &self,
        node: NodeKey,
        module: ModuleId,
        kinds: &[InfluenceKind],
        reason: &'static str,
    ) -> DisclosureDecline {
        let mut declined = self.fail(node, reason);
        if let Ok(source) = self.source(module, node) {
            for kind in kinds {
                if let Ok(id) = self.opaque("influence", node, &format!("{kind:?}")) {
                    declined.influences.push(DisclosureInfluence {
                        id,
                        source: source.clone(),
                        node,
                        kind: *kind,
                        query_id: None,
                    });
                }
            }
        }
        declined
    }

    fn expr(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if self.depth >= 64 {
            return Err(self.fail(key, "expression closure depth bound"));
        }
        // Only top-level straight-line expression analyses share a statement.
        // Nested statements, derive frames and input-loop scopes stay separate.
        let reuse = self.depth == 0
            && self.statement_depth == 1
            && self.loop_node.is_none()
            && self.stack.is_empty()
            && calls.is_empty();
        if reuse
            && let Some(completed) = self.statement_expressions.as_ref().and_then(|entries| {
                entries.iter().find(|entry| {
                    entry.node == key
                        && entry.module == module
                        && entry.calls == calls
                        && entry.authorization == self.authorization
                        && entry.result_model == self.result_model
                        && entry.env == *env
                })
            })
        {
            return Ok(completed.values.clone());
        }
        let bookkeeping = (
            self.effect_proofs.len(),
            self.effect_visits,
            self.loop_node,
            self.result_model,
            self.authorization,
        );
        self.depth += 1;
        let result = self.expr_inner(key, module, env, calls);
        self.depth -= 1;
        // Expression traversal normally restores these values. Never reuse an
        // analysis which published an effect or left a changed scope behind.
        if reuse
            && bookkeeping
                == (
                    self.effect_proofs.len(),
                    self.effect_visits,
                    self.loop_node,
                    self.result_model,
                    self.authorization,
                )
            && self.stack.is_empty()
            && let Ok(values) = &result
            && let Some(entries) = self.statement_expressions.as_mut()
            && entries.len() < 1024
        {
            entries.push(CompletedStatementExpression {
                node: key,
                module,
                calls: calls.to_vec(),
                authorization: self.authorization,
                result_model: self.result_model,
                env: env.clone(),
                values: values.clone(),
            });
        }
        result
    }

    fn literal_message_descriptor(&self, key: NodeKey) -> bool {
        self.types.node_types.get(&key) == Some(&ResolvedType::InlineMessage)
            && self.nodes.get(&key).is_some_and(|node| {
                node.kind == SyntaxKind::MessageValue
                    && node.children.iter().filter(|child| expression(child.kind))
                        .all(|child| child.kind == SyntaxKind::Literal)
                    && node.children.iter().filter(|child| child.kind == SyntaxKind::MessageVariant)
                        .all(|variant| variant.children.iter().filter(|child| expression(child.kind))
                            .all(|child| child.kind == SyntaxKind::Literal))
            })
    }

    /// A named zero-parameter message is immutable presentation data, not an
    /// environment value. Require its original checked declaration; a lexical
    /// value with the same spelling must keep its own provenance.
    fn static_named_message_descriptor(&self, key: NodeKey) -> Option<SymbolId> {
        let key = self.query_group(key)?;
        let ResolvedType::Message(id) = self.types.node_types.get(&key)? else {
            return None;
        };
        if !matches!(self.query_binding(key), Some(Binding::Symbol(actual)) if actual == id) {
            return None;
        }
        let symbol = self.resolve.symbols.get(id.0 as usize)?;
        let SymbolKind::Message { params } = &symbol.kind else {
            return None;
        };
        let message = self.effects.messages.get(id)?;
        let declaration = self.nodes.get(&message.node)?;
        if symbol.id != *id || message.message != *id || message.module != symbol.module
            || !params.is_empty() || !message.params.is_empty()
            || declaration.kind != SyntaxKind::Message
            || symbol.span.file != message.node.file
            || symbol.span.start < message.node.start || symbol.span.end > message.node.end
            || self.source(symbol.module, message.node).is_err()
        {
            return None;
        }
        let mut values = declaration.children.iter().filter(|child| child.kind == SyntaxKind::MessageValue);
        let value = values.next()?;
        if values.next().is_some()
            || !value.children.iter().filter(|child| expression(child.kind))
                .all(|child| child.kind == SyntaxKind::Literal)
            || !value.children.iter().filter(|child| child.kind == SyntaxKind::MessageVariant)
                .all(|variant| variant.children.iter().filter(|child| expression(child.kind))
                    .all(|child| child.kind == SyntaxKind::Literal))
        {
            return None;
        }
        Some(*id)
    }

    fn literal_value(&self, key: NodeKey) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if self.nodes.get(&key).is_some_and(|node| node.kind == SyntaxKind::Literal)
            || self.literal_message_descriptor(key) {
            Ok(vec![ValuePath::default()])
        } else {
            Err(self.fail(key, "unsupported literal descriptor"))
        }
    }

    /// A finite authored enum filter is a Values expression. Its predicate
    /// retains ordinary DATA dependencies; it acquires no model query census.
    fn literal_enum_value_query(&self,query:&super::types::CheckedQuery)->Option<NodeKey> {
        let ResolvedType::Array{element,ordered:true,nonempty:true}=&query.domain_type else{return None;};
        let ResolvedType::Enum{owner:Some(owner),cases}=element.as_ref() else{return None;};
        if cases.is_empty() || self.types.symbol_types.get(owner)!=Some(element.as_ref())
            || query.result!=(ResolvedType::Array{element:element.clone(),ordered:true,nonempty:false}) || query.projection.is_some()
            || self.types.node_types.get(&query.domain)!=Some(&query.domain_type) {return None;}
        let domain=self.nodes.get(&query.domain)?;
        if domain.kind!=SyntaxKind::Array{return None;}
        let entries:Vec<_>=domain.children.iter().filter(|child|expression(child.kind)).collect();
        if entries.is_empty() || entries.len()>200 || entries.iter().any(|entry|
            !self.types.resolved_cases.contains(&NodeKey::of(entry))
                || self.types.node_types.get(&NodeKey::of(entry))!=Some(element.as_ref())) {return None;}
        let [alias,filter]=query.clauses.as_slice() else{return None;};
        let [predicate]=filter.expressions.as_slice() else{return None;};
        if !matches!(alias.kind,CheckedQueryClauseKind::As{..}) || filter.kind!=CheckedQueryClauseKind::Where
            || self.types.node_types.get(predicate)!=Some(&ResolvedType::Scalar(Scalar::Bool)){return None;}
        let (left,right)=self.query_binary(*predicate,"==")?;
        let formal_case=|formal:NodeKey,case:NodeKey|{
            let Some(Binding::Symbol(parameter))=self.query_binding(formal) else{return false;};
            let Some(SymbolKind::Param{owner,..})=self.resolve.symbols.get(parameter.0 as usize).map(|symbol|&symbol.kind) else{return false;};
            matches!(self.types.symbol_types.get(parameter),Some(ResolvedType::Enum{owner:Some(_),cases}) if !cases.is_empty())
                && self.types.node_types.get(&formal)==self.types.symbol_types.get(parameter)
                && self.types.node_types.get(&case)==self.types.symbol_types.get(parameter)
                && self.types.resolved_cases.contains(&case)
                && self.original_reference_parameter(formal,*parameter)
                && self.effects.derives.get(owner).is_some_and(|derive|derive.params.iter()
                    .any(|param|param.param==*parameter&&param.default.is_none()))
        };
        (formal_case(left,right)||formal_case(right,left)).then_some(*predicate)
    }

    fn constructor_value_order_query(&mut self, key: NodeKey, module: ModuleId, env: &Env,
        calls: &[NodeKey]) -> Option<Vec<ValuePath>> {
        let query = self.types.checked_queries.get(&key)?.clone();
        let [alias, order] = query.clauses.as_slice() else { return None; };
        let [ordered] = order.expressions.as_slice() else { return None; };
        if !calls.is_empty() || !self.source_require_value_query(&query)
            || !matches!(alias.kind, CheckedQueryClauseKind::As { .. })
            || order.kind != CheckedQueryClauseKind::Order || query.projection.is_some()
            || query.result != query.domain_type || !self.effects.scenarios.values().any(|scenario|
                scenario.module == module && scenario.effects.iter().any(|effect| effect.verb == EffectVerb::Create
                    && effect.args.iter().any(|argument| argument.value == Some(key)))) { return None; }
        let (receiver, name) = self.count_member(*ordered)?;
        if !matches!(self.query_binding(receiver), Some(Binding::QueryAlias {node}) if *node == alias.node) { return None; }
        let ResolvedType::Array {element,..} = &query.domain_type else { return None; };
        let ResolvedType::Record {symbol: contract,..} = element.as_ref() else { return None; };
        let field_type = self.types.node_types.get(ordered)?;
        if !primitive_type(field_type) || self.contract_member(*contract, name, field_type).is_none() { return None; }
        self.expr(query.domain, module, env, calls).ok()
    }

    fn expr_inner(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        self.steps += 1;
        if self.steps > 16384 || calls.len() > 64 {
            return Err(self.fail(key, "closure resource bound"));
        }
        let node = *self
            .nodes
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing expression anchor"))?;
        let ty = self
            .types
            .node_types
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing checked expression type"))?;
        if matches!(
            ty,
            ResolvedType::Unknown | ResolvedType::Error | ResolvedType::Opaque(_)
        ) {
            return Err(self.fail(key, "unresolved expression type"));
        }
        // A qualified enum case is one checked literal. Its type/member
        // prefix is a namespace, not a stored row expression to evaluate.
        if node.kind == SyntaxKind::Member && self.types.resolved_cases.contains(&key)
            && matches!(ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())
        {
            return Ok(vec![ValuePath::default()]);
        }
        let children: Vec<_> = node
            .children
            .iter()
            .filter(|n| expression(n.kind))
            .collect();
        match node.kind {
            SyntaxKind::Literal | SyntaxKind::MessageValue => self.literal_value(key),
            SyntaxKind::NameRef | SyntaxKind::Path => {
                self.expr_nameref(key, module, env, calls, node, ty)
            }
            SyntaxKind::Object => self.object((key, node), ty, module, env, calls, None),
            SyntaxKind::Construct => {
                self.expr_construct(key, module, env, calls, node, ty, &children)
            }
            SyntaxKind::Group | SyntaxKind::Unary => {
                if children.len() != 1 {
                    return Err(self.fail(key, "invalid unary/group shape"));
                }
                self.expr(NodeKey::of(children[0]), module, env, calls)
            }
            SyntaxKind::Array => self.expr_array(key, module, env, calls, children),
            SyntaxKind::Binary => self.expr_binary(key, module, env, calls, node, children),
            SyntaxKind::Member => self.expr_member(key, module, env, calls, node, children),
            SyntaxKind::Call => self.call(key, module, env, calls),
            SyntaxKind::Query if self.inline_selection_at(key, module).is_some() => {
                self.inline_selection_value(key, module, env, calls)
            }
            SyntaxKind::Query if self.types.checked_queries.get(&key).and_then(|query|self.literal_enum_value_query(query)).is_some() => {
                let predicate=self.literal_enum_value_query(&self.types.checked_queries[&key]).unwrap();
                self.expr(predicate,module,env,calls)
            }
            SyntaxKind::Query => if let Some(value) = self.constructor_value_order_query(key, module, env, calls) {
                Ok(value)
            } else { Err(self.influence(
                key,
                module,
                &[
                    InfluenceKind::QueryExistence,
                    InfluenceKind::QueryCardinality,
                    InfluenceKind::QueryMembership,
                    InfluenceKind::QueryOrder,
                ],
                "query closure is not supported",
            )) },
            _ => Err(self.fail(key, "unsupported expression closure")),
        }
    }

    /// A name/path reference: enum cases and lexical bindings resolve
    /// through the environment with their admission checks.
    #[allow(clippy::too_many_arguments)]
    fn expr_nameref(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        node: &SyntaxNode,
        ty: &ResolvedType,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        // The checker may claim a builtin spelling as an enum case;
        // that checked type wins over its non-value builtin binding.
        if self.types.resolved_cases.contains(&key)
            && matches!(ty, ResolvedType::Enum { .. })
        {
            return Ok(vec![ValuePath::default()]);
        }
        let binding = self.resolve.node_binding.get(&key).or_else(|| {
            node.children
                .iter()
                .find_map(|n| self.resolve.node_binding.get(&NodeKey::of(n)))
        });
        match binding {
            // Invocation facts carry no stored-read authority. Preserve
            // their checked lexical binding and exact scalar identity;
            // lowering is matched against the same source occurrence.
            Some(Binding::Context(ContextVar::Actor(_)))
                if ty == &ResolvedType::Scalar(Scalar::User) =>
            {
                Ok(vec![ValuePath::default()])
            }
            Some(Binding::Context(ContextVar::Now))
                if ty == &ResolvedType::Scalar(Scalar::Datetime) =>
            {
                Ok(vec![ValuePath::default()])
            }
            Some(Binding::Symbol(id)) => {
                self.expr_symbol_binding(key, module, env, calls, ty, *id)
            }
            Some(Binding::ForItem { node }) => env
                .get(&Local::For(*node))
                .cloned()
                .map(|value| vec![value])
                .ok_or_else(|| self.fail(key, "unaccounted loop item")),
            Some(Binding::Let { node }) => env
                .get(&Local::Let(*node))
                .cloned()
                .filter(|value| {
                    value.record.is_none()
                        || value
                            .first_query
                            .is_none_or(|(_, original)| original == *node)
                            && value
                                .current_revision
                                .is_none_or(|original| original == *node)
                })
                .map(|p| vec![p])
                .ok_or_else(|| self.fail(key, "unaccounted immutable binding")),
            Some(Binding::CreateAs { node }) => env
                .get(&Local::Create(*node))
                .cloned()
                .map(|value| vec![value])
                .ok_or_else(|| self.fail(key, "unaccounted created binding")),
            Some(Binding::SendAs { node }) => env
                .get(&Local::Send(*node))
                .cloned()
                .map(|value| vec![value])
                .ok_or_else(|| self.fail(key, "unaccounted send binding")),
            Some(Binding::CallAs { .. }) => Err(self.fail(
                key,
                "bound child result consumption needs its owning provenance",
            )),
            Some(Binding::Predicate) => {
                if self.authorization {
                    Ok(vec![ValuePath::default()])
                } else {
                    Err(self.fail(key, "authority-dependent predicate value"))
                }
            }
            None if self.types.resolved_cases.contains(&key) => {
                Ok(vec![ValuePath::default()])
            }
            _ => Err(self.fail(key, "unsupported lexical value")),
        }
    }

    /// A symbol binding in an expression: roles need authorization,
    /// models are query domains, anything else reads the environment.
    #[allow(clippy::too_many_arguments)]
    fn expr_symbol_binding(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        ty: &ResolvedType,
        id: SymbolId,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if matches!(
            self.resolve
                .symbols
                .get(id.0 as usize)
                .map(|symbol| &symbol.kind),
            Some(SymbolKind::Role)
        ) {
            if self.authorization {
                return Ok(vec![ValuePath::default()]);
            } else {
                return Err(self.fail(key, "authority-dependent role value"));
            }
        }
        if matches!(
            self.resolve
                .symbols
                .get(id.0 as usize)
                .map(|symbol| &symbol.kind),
            Some(SymbolKind::Model { .. })
        ) {
            return Err(self.influence(
                key,
                module,
                &[
                    InfluenceKind::QueryExistence,
                    InfluenceKind::QueryCardinality,
                    InfluenceKind::QueryMembership,
                    InfluenceKind::QueryOrder,
                ],
                "stored model query domain",
            ));
        }
        if ty == &ResolvedType::Message(id)
            && self.static_named_message_descriptor(key) == Some(id)
        {
            return Ok(vec![ValuePath::default()]);
        }
        let value = env
            .get(&Local::Symbol(id))
            .cloned()
            .ok_or_else(|| self.fail(key, "unaccounted symbol value"))?;
        Ok(vec![self.input_value(key, module, calls, value)?])
    }

    fn declared_constructor_default(
        &self,
        key: NodeKey,
        ty: &ResolvedType,
        depth: usize,
        visits: &mut usize,
    ) -> Option<()> {
        *visits += 1;
        if depth > 32 || *visits > 4096 {
            return None;
        }
        let key = self.query_group(key)?;
        let actual = self.types.node_types.get(&key)?;
        if actual == &ResolvedType::Null && matches!(ty, ResolvedType::Nullable(_)) {
            return Some(());
        }
        let leaf = match ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        let array_literal = matches!((actual, leaf),
            (ResolvedType::Array {element: a, ordered: ao, nonempty: an},
             ResolvedType::Array {element: b, ordered: bo, nonempty: bn})
                if a == b && ao == bo && (!bn || *an));
        if actual != ty && actual != leaf && !array_literal {
            return None;
        }
        let node = self.nodes.get(&key)?;
        match node.kind {
            SyntaxKind::Literal if primitive_type(leaf) => Some(()),
            SyntaxKind::NameRef
                if self.types.resolved_cases.contains(&key)
                    && matches!(leaf, ResolvedType::Enum {cases,..} if !cases.is_empty()) =>
            {
                Some(())
            }
            SyntaxKind::Array => {
                let ResolvedType::Array { element, .. } = leaf else {
                    return None;
                };
                for child in node.children.iter().filter(|child| expression(child.kind)) {
                    self.declared_constructor_default(
                        NodeKey::of(child),
                        element,
                        depth + 1,
                        visits,
                    )?;
                }
                Some(())
            }
            _ => None,
        }
    }

    /// Declared value constructors keep their defining nominal schema. This
    /// census authorizes no member value: `object` still proves each authored
    /// field through the ordinary DATA expression path below.
    fn declared_constructor_schema(
        &self,
        ty: &ResolvedType,
        depth: usize,
        active: &mut HashSet<SymbolId>,
        fields: &mut usize,
    ) -> Option<()> {
        if depth > 32 {
            return None;
        }
        match ty {
            ResolvedType::Nullable(inner) | ResolvedType::Array { element: inner, .. } => {
                self.declared_constructor_schema(inner, depth + 1, active, fields)
            }
            ResolvedType::Record {
                symbol,
                stored: false,
            } if self.is_contract_symbol(*symbol) => {
                if !active.insert(*symbol) {
                    return None;
                }
                let declaration = self.resolve.symbols.get(symbol.0 as usize)?;
                let SymbolKind::Contract { fields: order } = &declaration.kind else {
                    return None;
                };
                let record = self.effects.records.get(symbol)?;
                if record.record != *symbol
                    || record.module != declaration.module
                    || order.len() > 200
                    || record
                        .fields
                        .iter()
                        .map(|field| field.field)
                        .collect::<Vec<_>>()
                        != *order
                {
                    return None;
                }
                for field in &record.fields {
                    *fields += 1;
                    if *fields > 4096 || field.server.is_some() {
                        return None;
                    }
                    let member = self.resolve.symbols.get(field.field.0 as usize)?;
                    let field_ty = self.types.symbol_types.get(&field.field)?;
                    if member.module != declaration.module
                        || !matches!(member.kind, SymbolKind::Field {owner, ..} if owner == *symbol)
                        || self
                            .stored_contract_field_checked_data(
                                *symbol,
                                &field.field,
                                declaration.module,
                                &member.name,
                                field_ty,
                                false,
                            )
                            .is_none()
                    {
                        return None;
                    }
                    if let Some(default) = field.default {
                        self.declared_constructor_default(default, field_ty, 0, &mut 0)?;
                    }
                    self.declared_constructor_schema(field_ty, depth + 1, active, fields)?;
                }
                active.remove(symbol);
                Some(())
            }
            ResolvedType::Unknown => None,
            // A schema reference carries no instance authority. Actual Model,
            // File, delivery and other opaque values retain their DATA gates.
            _ => Some(()),
        }
    }

    /// Source-owned Contracts and closed std schemas keep their defining
    /// nominal identity; every object field retains its ordinary DATA proof.
    #[allow(clippy::too_many_arguments)]
    fn expr_construct(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        node: &SyntaxNode,
        ty: &ResolvedType,
        children: &[&SyntaxNode],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        let head = children
            .first()
            .ok_or_else(|| self.fail(key, "missing schema construct head"))?;
        if let Some(TypeRef::Symbol(symbol)) = self.resolve.node_typeref.get(&NodeKey::of(head)) {
            if ty != &(ResolvedType::Record { symbol: *symbol, stored: false })
                || !self.is_contract_symbol(*symbol)
                || self.declared_constructor_schema(ty, 0, &mut HashSet::new(), &mut 0).is_none()
            { return Err(self.fail(key, "declared constructor needs its complete original Contract schema")); }
            let object = node.children.iter().find(|node| node.kind == SyntaxKind::Object)
                .ok_or_else(|| self.fail(key, "missing declared Contract object"))?;
            return self.object((key, object), ty, module, env, calls, None);
        }
        if !matches!(
            self.resolve.node_typeref.get(&NodeKey::of(head)),
            Some(TypeRef::External)
        ) {
            return Err(self.fail(key, "unsupported construct owner"));
        }
        let alias = self
            .word(head)
            .ok_or_else(|| self.fail(key, "missing schema import alias"))?;
        let Some(ScopedName::External { provider, name }) = self
            .resolve
            .module_scopes
            .get(module.0 as usize)
            .and_then(|scope| scope.prod.get(alias))
        else {
            return Err(self.fail(key, "missing checked schema import"));
        };
        if provider != "std"
            || !matches!(
                name.as_str(),
                "TextRequest"
                    | "TextMessage"
                    | "WorkflowInput"
                    | "WorkflowDefinition"
                    | "ImageRequest"
            )
        {
            return Err(self.fail(key, "unsupported closed std schema"));
        }
        let schema = nominal_schema(name)
            .ok_or_else(|| self.fail(key, "missing defining std schema"))?;
        let fields = checked_text_schema_fields(ty, Some(name.as_str()))
            .ok_or_else(|| self.fail(key, "missing checked schema object type"))?;
        if fields.len() != schema.fields.len()
            || fields
                .iter()
                .zip(schema.fields)
                .any(|((name, _), (declared, _))| name != declared)
        {
            return Err(self.fail(key, "checked schema fields disagree"));
        }
        let object = node
            .children
            .iter()
            .find(|n| n.kind == SyntaxKind::Object)
            .ok_or_else(|| self.fail(key, "missing checked schema object"))?;
        self.object((key, object), ty, module, env, calls, Some(name.clone()))
    }

    fn expr_member_selection_prefix(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if self
            .inline_selection_at(key, module)
            .is_some_and(|fact| fact.prefix_node == key)
        {
            return Ok(Some(self.inline_selection_value(key, module, env, calls)?));
        }
        if let Some(values) = self.current_revision_member(key, module, env, calls)? {
            return Ok(Some(values));
        }
        Ok(None)
    }

    fn expr_member_intrinsics(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if matches!(
            self.types.node_types.get(&base_key),
            Some(ResolvedType::Nullable(_))
        ) {
            return Err(self.influence(
                key,
                module,
                &[InfluenceKind::AbsentReference],
                "nullable record traversal",
            ));
        }
        if matches!(
            self.types.node_types.get(&base_key),
            Some(ResolvedType::OperationContext)
        ) {
            if field_name != "id"
                || *ty != ResolvedType::Scalar(Scalar::Text)
                || !self.operation_context(base_key)
            {
                return Err(self.fail(key, "unsupported operation intrinsic"));
            }
            return Ok(Some(vec![self.intrinsic(
                key,
                module,
                calls,
                DisclosureIntrinsicKind::OperationId,
                Scalar::Text,
            )?]));
        }
        Ok(None)
    }

    fn expr_member_context_inputs(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if calls.is_empty() && self.loop_node.is_none()
            && let Some((_, field)) = self.hook_delivery_field(key, module)
        {
            let name = self.resolve.symbols.get(field.0 as usize)
                .ok_or_else(|| self.fail(key, "missing declared event field"))?.name.as_str();
            if name == "term" || name == "obligation" || name == "appointment" || name == "inspection" || name == "registration" {
                let ResolvedType::Record { symbol: model, stored: true } = ty else {
                    return Err(self.fail(key, "notice event Term type mismatch"));
                };
                let model_name = self.resolve.symbols.get(model.0 as usize)
                    .ok_or_else(|| self.fail(key, "missing notice Term model"))?.canonical.clone();
                return Ok(Some(vec![ValuePath {
                    record: Some(*model),
                    reference_origin: Some(ReferenceOrigin::EventRow { field, node: key }),
                    reference: Some(DisclosureIntrinsicKind::AdmittedReferenceVersion {
                        parameter: field, parameter_name: "eventTerm".into(),
                        model: *model, model_name,
                    }),
                    ..ValuePath::default()
                }]));
            }
            if matches!(name, "kind" | "body") {
                let mut value = self.intrinsic(key,module,calls,DisclosureIntrinsicKind::AdmittedInput {
                    parameter: field, parameter_name: if name == "kind" {"eventKind"} else {"eventBody"}.into(),
                },Scalar::Text)?;
                value.intrinsics[0].ty = ty.clone();
                value.intrinsics[0].type_id = if name == "kind" {"enum(confirmation,change,cancellation)".into()} else {"text".into()};
                return Ok(Some(vec![value]));
            }
            if name == "revision" && *ty == ResolvedType::Scalar(Scalar::Int) {
                let input = ValuePath {
                    input: Some((field, "eventRevision".into(), Scalar::Int)),
                    ..ValuePath::default()
                };
                return self.input_value(key, module, calls, input).map(|value| Some(vec![value]));
            }
        }
        if calls.is_empty()
            && self.loop_node.is_none()
            && let Some((parameter, ResolvedType::Scalar(scalar), path)) =
                self.checked_contract_input_path(key, module, 0)
            && !path.is_empty()
            && env.contains_key(&Local::Symbol(parameter))
        {
            let name = &self.resolve.symbols[parameter.0 as usize].name;
            return self
                .input_value(
                    key,
                    module,
                    calls,
                    ValuePath {
                        input: Some((parameter, format!("{name}/{}", path.join("/")), scalar)),
                        ..ValuePath::default()
                    },
                )
                .map(|value| Some(vec![value]));
        }
        if calls.is_empty()
            && self.loop_node.is_none()
            && let Some((parameter, model, slot)) =
                self.checked_contract_input_reference(key, module)
            && env.contains_key(&Local::Symbol(parameter))
        {
            let key = self
                .query_group(key)
                .ok_or_else(|| self.fail(key, "missing input member"))?;
            let owner = self
                .resolve
                .symbols
                .get(model.0 as usize)
                .ok_or_else(|| self.fail(key, "missing input member model"))?;
            return Ok(Some(vec![ValuePath {
                record: Some(model),
                reference_origin: Some(ReferenceOrigin::ParameterMember {
                    parameter,
                    node: key,
                }),
                reference: Some(DisclosureIntrinsicKind::AdmittedReferenceVersion {
                    parameter,
                    parameter_name: slot,
                    model,
                    model_name: owner.canonical.clone(),
                }),
                ..ValuePath::default()
            }]));
        }
        // Checked contextual actor facts (CAN18-v1 actor guard slice): the
        // literal `actor` context exposes exactly `email`/`email_verified`
        // through the existing `actorFacts` carrier (same field/type pairs
        // the IR decoder and policy profile already honor). The resolver
        // binds only the literal context spelling (grouping-transparent via
        // `query_binding`); aliases, user-typed inputs, and hook bindings
        // never match, so they keep the stored-read refusal below. No store
        // grant is recorded: the host supplies these caller facts with the
        // invocation context, and emission lowers them to `c.actorFacts`.
        if calls.is_empty()
            && self.loop_node.is_none()
            && matches!(
                self.query_binding(base_key),
                Some(Binding::Context(ContextVar::Actor(_)))
            )
            && matches!(
                (field_name, ty),
                ("email", ResolvedType::Scalar(Scalar::Email))
                    | ("email_verified", ResolvedType::Scalar(Scalar::Bool))
            )
            && self
                .types
                .node_types
                .get(&self.query_group(base_key).unwrap_or(base_key))
                == Some(&ResolvedType::Scalar(Scalar::User))
        {
            return Ok(Some(vec![ValuePath::default()]));
        }
        Ok(None)
    }

    fn expr_member_envelope(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        values: &mut Vec<ValuePath>,
    ) -> Result<bool, DisclosureDecline> {
        if self.types.node_types.get(&base_key) == Some(&ResolvedType::Scalar(Scalar::Money))
            && matches!(
                (field_name, ty),
                ("minor", ResolvedType::Scalar(Scalar::Int))
                    | ("currency", ResolvedType::Scalar(Scalar::Currency))
            )
            && values.iter().all(|value| {
                value.intrinsics.iter().any(|intrinsic| {
                    intrinsic.ty == ResolvedType::Scalar(Scalar::Money)
                        && matches!(
                            intrinsic.kind,
                            DisclosureIntrinsicKind::AdmittedInput { .. }
                        )
                }) || value.reads.iter().any(|dependency| {
                    // A selector over an already observed whole Money value
                    // keeps that exact stored field dependency and authority.
                    dependency.node == base_key
                        && dependency.ty == ResolvedType::Scalar(Scalar::Money)
                        && self.types.symbol_types.get(&dependency.field) == Some(&dependency.ty)
                        && matches!(self.resolve.symbols.get(dependency.field.0 as usize).map(|field| &field.kind),
                            Some(SymbolKind::Field { owner, .. }) if *owner == dependency.model)
                })
            })
        {
            return Ok(true);
        }
        // Same-transaction send-result envelope reads (CAN18-v1 dispatch
        // fence persistence, e.g. cancel/retry_release): `delivery.id`
        // stores the sealed send fence. The base must be a flow-visible
        // send binding (effects disclose in order, so a later use sees
        // only already-executed sends); the leaf comes from the closed
        // `DeliveryResult` envelope with its checker-resolved scalar
        // type. Ordering is structural; source/owner/failure stay sealed
        // by the existing receipt checks. The clone drops only the
        // carrier flag — reads/observed/decisions are preserved.
        let send_visible = match self.resolve.node_binding.get(&base_key) {
            Some(Binding::SendAs { node }) => env.contains_key(&Local::Send(*node)),
            _ => false,
        };
        if result_type(ty)
            && send_visible
            && values.iter().all(|value| {
                matches!(
                    value.delivery,
                    Some(ResolvedType::Delivery { .. })
                        | Some(ResolvedType::StdDelivery { .. })
                )
            })
            && nominal_schema("DeliveryResult")
                .is_some_and(|schema| schema.fields.iter().any(|(name, _)| *name == field_name))
        {
            for value in &mut *values {
                value.delivery = None;
            }
            return Ok(true);
        }
        Ok(false)
    }

    fn expr_member_model_guard(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        value: &ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let helper_scalar=self.helper_reference_scalar(key,module,calls).is_some_and(|(source,reference,target,_)|
            matches!(value.model_result,Some(DisclosureModelResult::Reference{model,node,source_model,field})
                if model==target&&node==base_key&&source_model==source&&field==reference)
                &&value.reads.iter().any(|read|read.node==base_key&&read.model==source&&read.field==reference
                    &&read.calls==calls&&read.query_id.is_none()));
        let reminder_contact_email = self.count_member(key)
            .is_some_and(|(base, name)| base == base_key && name == "email")
            && self.count_member(base_key).is_some_and(|(event_row, name)|
                name == "contact"
                    && self.hook_delivery_field(event_row, module)
                        .is_some_and(|(scenario, field)|
                            self.resolve.symbols.get(scenario.0 as usize)
                                .is_some_and(|symbol| symbol.canonical == "appointments.remind")
                            && self.resolve.symbols.get(field.0 as usize)
                                .is_some_and(|symbol| symbol.name == "appointment")))
            && matches!(value.model_result,
                Some(DisclosureModelResult::Reference {node, ..}) if node == base_key);
        if matches!(
            value.model_result,
            Some(DisclosureModelResult::Reference { .. })
        ) && !reminder_contact_email && !helper_scalar && !matches!(value.model_result,
            Some(DisclosureModelResult::Reference {model, node, ..})
                if Some(node) == self.query_group(base_key)
                    && self.checked_required_model_reference(key, module)
                        .is_some_and(|(source, _, _)| source == model))
            && self
                .checked_profile_scalar(key, module)
                .or_else(|| self.checked_run_unfinished(key, module))
                .or_else(|| self.checked_required_reference_scalar(key, module))
                .is_none()
        {
            return Err(self.fail(
                key,
                "stored Model reference needs its direct result consumer",
            ));
        }
        if value.current_revision.is_some() {
            return Err(self.fail(
                key,
                "current Revision needs its exact original scalar member",
            ));
        }
        Ok(())
    }

    fn expr_member_contract_value(
        &self,
        key: NodeKey,
        module: ModuleId,
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if let Some(origin) = value.contract_value {
            let ContractValue::Singular(contract) = origin else {
                return Err(self.fail(key, "canonical wire is not a record receiver"));
            };
            if !matches!(self.types.node_types.get(&base_key),
                Some(ResolvedType::Record {symbol,..}) if *symbol == contract)
                || self.contract_member(contract, field_name, ty).is_none()
            {
                return Err(self.fail(key, "canonical Contract member identity mismatch"));
            }
            value.contract_value = match ty {
                ResolvedType::Record {
                    symbol,
                    stored: true,
                } if matches!(
                    self.resolve
                        .symbols
                        .get(symbol.0 as usize)
                        .map(|symbol| &symbol.kind),
                    Some(SymbolKind::Model { .. })
                ) =>
                {
                    Some(ContractValue::Reference)
                }
                ResolvedType::Array {
                    element,
                    ordered: true,
                    nonempty: false,
                } if matches!(element.as_ref(), ResolvedType::Record {symbol, ..}
                        if matches!(self.resolve.symbols.get(symbol.0 as usize).map(|symbol| &symbol.kind),
                            Some(SymbolKind::Contract { .. }))) =>
                {
                    let ResolvedType::Record { symbol, .. } = element.as_ref() else {
                        unreachable!();
                    };
                    Some(ContractValue::Array(*symbol))
                }
                ty if result_type(ty) => None,
                _ => return Err(self.fail(key, "unsupported canonical Contract member value")),
            };
            // Selecting a local member consumes the already observed whole
            // owning field. It must never synthesize a dotted stored read.
        }
        Ok(())
    }

    fn expr_member_composite_value(
        &self,
        key: NodeKey,
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        value: &mut ValuePath,
    ) -> Result<Option<SymbolId>, DisclosureDecline> {
        if let Some(members) = &value.members {
            let receiver = self
                .types
                .node_types
                .get(&base_key)
                .ok_or_else(|| self.fail(key, "missing composite receiver type"))?;
            let fields = checked_text_schema_fields(receiver, value.schema.as_deref())
                .ok_or_else(|| self.fail(key, "unestablished composite receiver"))?;
            if !fields
                .iter()
                .any(|(name, field_ty)| name == field_name && field_ty == ty)
                || !result_type(ty)
            {
                return Err(self.fail(key, "unsupported schema member selection"));
            }
            let mut selected = members
                .iter()
                .find(|(name, _)| name == field_name)
                .map(|(_, value)| value.clone())
                .ok_or_else(|| self.fail(key, "missing composite member provenance"))?;
            selected.observed = value.observed.clone();
            let mut decisions = value.decisions.clone();
            for decision in &selected.decisions {
                if !decisions.contains(decision) {
                    decisions.push(decision.clone());
                }
            }
            selected.decisions = decisions;
            *value = selected;
            return Ok(None);
        }
        if value.delivery.is_some() {
            return Err(self.fail(
                key,
                "delivery inspection needs its defining observation closure",
            ));
        }
        let model = value
            .record
            .ok_or_else(|| self.fail(key, "non-direct stored field traversal"))?;
        Ok(Some(model))
    }

    fn expr_member_id_origin(
        &self,
        key: NodeKey,
        module: ModuleId,
        base_key: NodeKey,
        model: SymbolId,
        value: &ValuePath,
    ) -> Result<(SymbolId, bool), DisclosureDecline> {
        let reference_identity = self
            .checked_reference_identity_operand(base_key, module)
            .filter(|(_, _, source, field, target, _)| {
                *target == model
                    && value.reads.iter().any(|read| {
                        read.node == base_key
                            && read.model == *source
                            && read.field == *field
                            && read.ty
                                == ResolvedType::Record {
                                    symbol: model,
                                    stored: true,
                                }
                            && read.calls.is_empty()
                            && read.query_id.is_none()
                    })
            });
        let (parameter, member) = match value.reference_origin {
            Some(ReferenceOrigin::Parameter(parameter)) => (parameter, false),
            Some(ReferenceOrigin::NullableParameter(parameter)) if self.narrowed_model_input(base_key,module)==Some((parameter,model)) => (parameter,false),
            Some(ReferenceOrigin::ParameterMember { parameter, node })
                if Some(node) == self.query_group(base_key)
                    && self
                        .checked_contract_input_reference(node, module)
                        .is_some_and(|(root, target, _)| {
                            root == parameter && target == model
                        }) =>
            {
                (parameter, true)
            }
            Some(ReferenceOrigin::Field {
                parameter,
                model: source,
                field,
            }) if reference_identity.is_some_and(
                |(root, _, actual, declared, _, _)| {
                    root == parameter && actual == source && declared == field
                },
            ) =>
            {
                (parameter, true)
            }
            _ => {
                return Err(self.fail(key, "id needs required original scenario parameter"));
            }
        };
        Ok((parameter, member))
    }

    fn expr_member_id_source(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        parameter: SymbolId,
        member: bool,
        model: SymbolId,
        ty: &ResolvedType,
    ) -> Result<String, DisclosureDecline> {
        let owner = self
            .resolve
            .symbols
            .get(model.0 as usize)
            .ok_or_else(|| self.fail(key, "missing intrinsic id model"))?;
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return Err(self.fail(key, "id needs checked stored model"));
        };
        let Some(SymbolKind::Param {
            owner: scenario, ..
        }) = self
            .resolve
            .symbols
            .get(parameter.0 as usize)
            .map(|parameter| &parameter.kind)
        else {
            return Err(self.fail(key, "missing intrinsic id input owner"));
        };
        let scenario = self
            .effects
            .scenarios
            .get(scenario)
            .ok_or_else(|| self.fail(key, "missing intrinsic id source scenario"))?;
        if !calls.is_empty()
            || self.loop_node.is_some()
            || !member
                && self.checked_call_parent_path(base_key, parameter, 0) != Some((model, 0))
                && self.narrowed_model_input(base_key,module)!=Some((parameter,model))
            || !member && owner.module != module && self.narrowed_model_input(base_key,module)!=Some((parameter,model))
                && !self.original_reference_parameter(base_key, parameter)
            || scenario.module != module
            || scenario.read
            || scenario.on.is_some()
            || key.file != scenario.node.file
            || key.start < scenario.node.start
            || key.end > scenario.node.end
            || fields.iter().any(|field| {
                self.resolve
                    .symbols
                    .get(field.0 as usize)
                    .is_none_or(|field| field.name == "id")
            })
            || *ty != ResolvedType::Scalar(Scalar::Text)
        {
            return Err(self.fail(key, "intrinsic id source correspondence"));
        }
        Ok(owner.canonical.clone())
    }

    fn expr_member_id_leaf(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let created = self.created_binding_source(base_key, module)
            .filter(|source| calls.is_empty() && self.loop_node.is_none() && source.model == model
                && matches!(value.model_result, Some(DisclosureModelResult::Create { model: actual, node })
                    if actual == model && node == source.node));
        let model_name = if created.is_some() {
            let owner = self.resolve.symbols.get(model.0 as usize)
                .ok_or_else(|| self.fail(key, "created identity model declaration"))?;
            let SymbolKind::Model { fields, .. } = &owner.kind else { return Err(self.fail(key, "created identity model")); };
            if *ty != ResolvedType::Scalar(Scalar::Text) || fields.iter().any(|field|
                self.resolve.symbols.get(field.0 as usize).is_none_or(|field| field.name == "id")) {
                return Err(self.fail(key, "created identity reserved text field"));
            }
            owner.canonical.clone()
        } else {
            let (parameter, member) = self.expr_member_id_origin(key, module, base_key, model, value)?;
            self.expr_member_id_source(key, module, calls, base_key, parameter, member, model, ty)?
        };
        // Reserved row identity is an owning stored observation. It is
        // neither an authored field nor a version/context intrinsic.
        value.reads.push(DisclosureDependency {
            query_id: None,
            id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
            source: self.source(module, key)?,
            node: key,
            calls: calls.to_vec(),
            role: DependencyRole::Data,
            model,
            field: model,
            model_name,
            field_name: "id".into(),
            ty: ty.clone(),
            type_id: "text".into(),
        });
        value.observed.push((key, calls.to_vec()));
        value.record = None;
        value.reference = None;
        value.reference_origin = None;
        if created.is_some() { value.model_result = None; }
        Ok(())
    }

    /// A created row's immutable parent keeps its own CreateAs identity. The
    /// association below seals the authored parent input; it does not admit
    /// the new row or its parent as another scenario parameter.
    fn created_parent_source(&self,key:NodeKey,module:ModuleId)
        ->Option<(CheckedScenarioCreate,SymbolId,SymbolId)> {
        let (base,name)=self.count_member(key)?;
        if name!="parent"{return None;}
        let source=self.created_binding_source(base,module)?;
        let ModelOwner::ChildOf(parent)=source.definition.declaration.owner else{return None;};
        let input=source.inputs.iter().find(|input|input.name=="parent"&&input.field.is_none())?;
        let Some(Binding::Symbol(parameter))=self.query_binding(input.value_node) else{return None;};
        if self.checked_call_parent_path(input.value_node,*parameter,0)!=Some((parent,0))
            ||self.types.node_types.get(&key)!=Some(&ResolvedType::Record{symbol:parent,stored:true}) {return None;}
        Some((source,parent,*parameter))
    }

    fn expr_member_parent_implicit(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let created=self.created_parent_source(key,module).filter(|(source,_,_)|
            calls.is_empty()&&self.loop_node.is_none()&&source.model==model
                &&matches!(value.model_result,Some(DisclosureModelResult::Create{model:actual,node}) if actual==model&&node==source.node));
        let (parameter, depth, event_row) = if let Some((_,_,parameter))=&created {(*parameter,0,false)}else{match value.reference_origin {
            Some(ReferenceOrigin::Parameter(parameter)) => (parameter, 0, false),
            Some(ReferenceOrigin::EventRow { field, node }) if node == base_key
                && self.hook_delivery_field(base_key, module)
                    .is_some_and(|(_, original)| original == field) => (field, 0, true),
            Some(ReferenceOrigin::ParameterMember { parameter, node })
                if Some(node) == self.query_group(base_key)
                    && self
                        .checked_contract_input_reference(node, module)
                        .is_some_and(|(root, target, _)| {
                            root == parameter && target == model
                        }) =>
            {
                (parameter, 0, false)
            }
            Some(ReferenceOrigin::Parent {
                parameter,
                model: original,
                depth,
            }) if original == model && depth == 1 => (parameter, depth, false),
            _ => {
                return Err(
                    self.fail(key, "parent needs required original scenario parameter")
                );
            }
        }};
        let owner = self
            .resolve
            .symbols
            .get(model.0 as usize)
            .ok_or_else(|| self.fail(key, "missing implicit parent model"))?;
        let SymbolKind::Model {
            owner: super::resolve::ModelOwner::ChildOf(parent),
            fields,
            ..
        } = &owner.kind
        else {
            return Err(self.fail(key, "parent needs checked child containment"));
        };
        let expected = ResolvedType::Record {
            symbol: *parent,
            stored: true,
        };
        let helper_parent=self.original_helper_model_path(key,module,calls)==Some((parameter,*parent,depth+1));
        if !calls.is_empty() && !helper_parent
            || (event_row
                && self.hook_delivery_field(base_key, module)
                    .is_none_or(|(_, field)| field != parameter))
            || (!event_row && created.is_none() && !helper_parent
                && self.checked_call_parent_path(key, parameter, 0)
                    != Some((*parent, depth + 1))
                && self.checked_delivery_parent_path(key, module, parameter, 2)
                    != Some((*parent, depth + 1)))
            || fields.iter().any(|field| {
                self.resolve
                    .symbols
                    .get(field.0 as usize)
                    .is_some_and(|field| field.name == "parent")
            })
            || self.effects.models.get(&model).is_none_or(|model| {
                model.owner != super::resolve::ModelOwner::ChildOf(*parent)
            })
            || *ty != expected
        {
            return Err(self.fail(key, "implicit parent source correspondence"));
        }
        let type_id = self
            .reference_operand_type_id(&expected)
            .ok_or_else(|| self.fail(key, "missing implicit parent owning declaration"))?;
        value.reads.push(DisclosureDependency {
            query_id: None,
            id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
            source: self.source(module, key)?,
            node: key,
            calls: calls.to_vec(),
            role: DependencyRole::Data,
            model,
            field: model,
            model_name: owner.canonical.clone(),
            field_name: "parent".into(),
            ty: expected,
            type_id,
        });
        value.observed.push((key, calls.to_vec()));
        value.record = Some(*parent);
        value.reference = None;
        value.reference_origin = if created.is_some(){None}else{Some(ReferenceOrigin::Parent {
            parameter,
            model: *parent,
            depth: depth + 1,
        })};
        if created.is_some(){value.model_result=None;}
        Ok(())
    }

    fn expr_member_parent_leaf(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if self.expr_member_parent_replay(key, module, env, calls, base_key, ty, model, value)? {
            return Ok(());
        }
        if matches!(
            value.reference_origin,
            Some(ReferenceOrigin::Parent { depth: 2, .. })
        ) && !(calls.is_empty()
            && self.loop_node.is_none()
            && (primitive_type(ty)
                || matches!(ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())))
            && self
                .checked_helper_reference_argument(key, module)
                .is_none()
            && self
                .checked_reference_identity_operand(key, module)
                .is_none()
        {
            return Err(self.fail(
                key,
                "two-parent reference needs direct child input consumer",
            ));
        }
        self.expr_member_parent_implicit(key, module, calls, base_key, ty, model, value)
    }

    fn expr_member_version_leaf(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if *ty != ResolvedType::Scalar(Scalar::Int) {
            return Err(self.fail(key, "unestablished intrinsic version type"));
        }
        let kind = value.reference.clone().ok_or_else(|| {
            self.fail(
                key,
                "version needs required original versioned scenario reference",
            )
        })?;
        if !matches!(&kind, DisclosureIntrinsicKind::AdmittedReferenceVersion {model: original,..} if *original == model)
        {
            return Err(self.fail(key, "original reference model mismatch"));
        }
        let intrinsic = self.intrinsic(key, module, calls, kind, Scalar::Int)?;
        value.join(&intrinsic);
        value.record = None;
        value.reference = None;
        Ok(())
    }

    /// Recover only the original dominating CREATE spelling and stored type.
    /// Flow consumers must additionally match their live CreateAs provenance.
    fn created_binding_source(&self, base: NodeKey, module: ModuleId) -> Option<CheckedScenarioCreate> {
        let Some(Binding::CreateAs { node: created }) = self.query_binding(base) else { return None; };
        let scenario = self.effects.scenarios.values().find(|owner| owner.module == module
            && owner.node.file == base.file && owner.node.start <= created.start
            && created.end <= base.start && base.end <= owner.node.end)?;
        let source = self.checked_create_sources(scenario)?.into_iter().find(|source| source.node == *created)?;
        (self.word(self.nodes.get(&base)?) == Some(source.binding.as_str())
            && self.types.node_types.get(&base) == Some(&ResolvedType::Record { symbol: source.model, stored: true }))
            .then_some(source)
    }

    /// Only the exact `.id` consumer of a dominating created row’s required
    /// stored reference is a local identity selection. It cannot navigate a
    /// target row, and it retains the whole original reference-field read.
    fn created_reference_identity(&self, key: NodeKey, module: ModuleId)
        -> Option<(SymbolId, SymbolId, SymbolId, NodeKey)> {
        let (base, name) = self.count_member(key)?;
        let source = self.created_binding_source(base, module)?;
        if !self.nodes.values().any(|node| node.kind == SyntaxKind::Member
                && self.count_member(NodeKey::of(node)) == Some((key, "id"))
                && self.types.node_types.get(&NodeKey::of(node)) == Some(&ResolvedType::Scalar(Scalar::Text)))
        { return None; }
        let field = self.effects.models.get(&source.model)?.fields.iter().find(|field|
            self.resolve.symbols.get(field.field.0 as usize).is_some_and(|symbol|
                symbol.name == name && matches!(symbol.kind, SymbolKind::Field {owner,..} if owner == source.model)))?;
        let ResolvedType::Record { symbol: target, stored: true } = self.types.symbol_types.get(&field.field)? else { return None; };
        if self.types.node_types.get(&key) != self.types.symbol_types.get(&field.field)
            || !matches!(self.resolve.symbols.get(target.0 as usize)?.kind, SymbolKind::Model {..})
        { return None; }
        Some((source.model, field.field, *target, source.node))
    }

    /// Resolve a helper's required Model formal to its original admitted
    /// scenario input, retaining only the already-checked parent edges.
    fn original_helper_model_path(&self,key:NodeKey,module:ModuleId,calls:&[NodeKey])
        ->Option<(SymbolId,SymbolId,u8)> {
        let [call]=calls else{return None;};
        let selected=self.types.selected_calls.get(call)?;
        let SelectedCallTarget::DeriveFn(derive)=selected.target else{return None;};
        let helper=self.effects.derives.get(&derive)?;
        let body=helper.expr?;
        if helper.module!=module || key.file!=body.file || key.start<body.start || key.end>body.end{return None;}
        let (formal,model,depth)=self.source_require_helper_parent_path(key,derive,0)?;
        let ResolvedType::Record{symbol:root,stored:true}=self.types.symbol_types.get(&formal)? else{return None;};
        let index=helper.params.iter().position(|param|param.param==formal)?;
        let argument=*selected.arguments.get(selected.slots.get(index)?.as_ref().copied()?)?;
        let Some(Binding::Symbol(parameter))=self.query_binding(argument) else{return None;};
        (self.original_reference_parameter(argument,*parameter)
            && self.checked_call_parent_path(argument,*parameter,0)==Some((*root,0)))
            .then_some((*parameter,model,depth))
    }

    /// The source reference remains the original required helper formal's
    /// stored Model field; consumers below admit identity or one stored leaf.
    fn helper_reference_source(&self,key:NodeKey,module:ModuleId,calls:&[NodeKey])
        ->Option<(SymbolId,SymbolId,SymbolId)> {
        let (base,_)=self.count_member(key)?;
        let (_,source,_)=self.original_helper_model_path(base,module,calls)?;
        let association=self.required_reference_field(key,self.nodes.get(&key)?,&source)?;
        let field=self.effects.models.get(&source)?.fields.iter().find(|field|field.field==association.1)?;
        (field.default.is_none()&&field.server.is_none()).then_some(association)
    }

    fn helper_reference_scalar(&self,key:NodeKey,module:ModuleId,calls:&[NodeKey])
        ->Option<(SymbolId,SymbolId,SymbolId,SymbolId)> {
        let (base,name)=self.count_member(key)?;
        let (source,reference,target)=self.helper_reference_source(base,module,calls)?;
        let field=self.resolve.symbols.get(target.0 as usize)?.fields_of().iter()
            .filter_map(|id|self.resolve.symbols.get(id.0 as usize))
            .find(|field|field.name==name&&matches!(field.kind,SymbolKind::Field{owner,..}if owner==target))?;
        let ty=self.types.symbol_types.get(&field.id)?;
        (self.types.node_types.get(&key)==Some(ty)
            &&(primitive_type(ty)||*ty==ResolvedType::Scalar(Scalar::Timezone)
                ||matches!(ty,ResolvedType::Enum{cases,..}if !cases.is_empty())))
            .then_some((source,reference,target,field.id))
    }

    fn helper_reference_identity(&self,key:NodeKey,module:ModuleId,calls:&[NodeKey])
        ->Option<(SymbolId,SymbolId,SymbolId)> {
        let association=self.helper_reference_source(key,module,calls)?;
        self.nodes.keys().any(|consumer|self.count_member(*consumer).is_some_and(|(base,name)|base==key
            &&(name=="id"&&self.types.node_types.get(consumer)==Some(&ResolvedType::Scalar(Scalar::Text))
                ||self.helper_reference_scalar(*consumer,module,calls).is_some())))
            .then_some(association)
    }

    fn expr_member_required_reference(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        model: SymbolId,
        field_id: SymbolId,
        value: &ValuePath,
    ) -> Option<SymbolId> {
        if self.loop_node.is_none()
            && let Some((source,field,target))=self.helper_reference_identity(key,module,calls)
            && source==model && field==field_id
            && self.original_helper_model_path(base_key,module,calls).is_some_and(|(parameter,model,depth)|
                model==source && (depth==0 && value.reference_origin==Some(ReferenceOrigin::Parameter(parameter))
                    || depth>0 && value.reference_origin==Some(ReferenceOrigin::Parent{parameter,model,depth}))) {
            return Some(target);
        }
        // A required stored Model field is a reference to its actual row,
        // never a local Contract shell. Retain the exact original receiver;
        // lexical copies and further traversal are separate consumers.
        if calls.is_empty() && self.loop_node.is_none()
            && let Some((source, field, target, created)) = self.created_reference_identity(key, module)
            && source == model && field == field_id
            && matches!(value.model_result, Some(DisclosureModelResult::Create {model, node})
                if model == source && node == created)
        { return Some(target); }
        self.checked_required_model_reference(key, module)
            .filter(|(source, reference, _)| *source == model && *reference == field_id)
            .filter(|_| calls.is_empty() && self.loop_node.is_none()
                && (matches!(value.reference_origin, Some(ReferenceOrigin::Parameter(parameter))
                    if matches!(self.query_binding(base_key), Some(Binding::Symbol(actual)) if *actual == parameter))
                    || matches!(value.reference_origin, Some(ReferenceOrigin::Parent {parameter, model: parent, depth})
                        if parent == model
                            && self.checked_call_parent_path(base_key, parameter, 0) == Some((model, depth))
                            && value.reads.iter().any(|read| read.node == base_key && read.model != model
                                && read.field_name == "parent" && read.ty == ResolvedType::Record {symbol:model,stored:true}
                                && read.calls.is_empty() && read.query_id.is_none()))
                    || value.first_query.is_some_and(|(_, binding)| {
                        matches!(self.query_binding(base_key), Some(Binding::Let {node}) if *node == binding)
                    })
                    || matches!(value.reference_origin,
                        Some(ReferenceOrigin::ParameterMember {parameter, node})
                            if Some(node) == self.query_group(base_key)
                                && self.checked_contract_input_reference(node, module)
                                    .is_some_and(|(root, target, _)| root == parameter && target == model))
                    || matches!(value.reference_origin,
                        Some(ReferenceOrigin::EventRow {field, node})
                            if node == base_key
                                && self.hook_delivery_field(base_key, module)
                                    .is_some_and(|(_, original)| original == field)
                                && self.resolve.symbols.get(field.0 as usize)
                                    .is_some_and(|symbol| symbol.name == "appointment"))
                    || matches!(value.model_result,
                        Some(DisclosureModelResult::Reference {model: target, node, source_model, field})
                            if target == model && Some(node) == self.query_group(base_key)
                                && self.checked_required_model_reference(node, module)
                                    == Some((source_model, field, target))
                                && value.reads.iter().any(|read| read.node == node
                                    && read.model == source_model && read.field == field
                                    && read.ty == ResolvedType::Record {symbol: target, stored: true}
                                    && read.calls.is_empty() && read.query_id.is_none()))))
            .map(|(_, _, target)| target)
    }

    fn expr_member_profile_scalar_leaf(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        model: SymbolId,
        field_id: SymbolId,
        profile_scalar: Option<(SymbolId, SymbolId, SymbolId, SymbolId, SymbolId)>,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if matches!(value.reference_origin, Some(ReferenceOrigin::Field { .. }))
            && self
                .checked_scalar_reference(ScalarReferenceKind::Profile, base_key, module)
                .or_else(|| {
                    self.checked_scalar_reference(ScalarReferenceKind::Run, base_key, module)
                })
                .is_some()
            && profile_scalar.is_none()
        {
            return Err(self.fail(key, "Profile scalar declaration source correspondence"));
        }
        let Some((parameter, branch, reference, profile, scalar)) = profile_scalar
        else {
            return Ok(());
        };
        if !calls.is_empty()
            || self.loop_node.is_some()
            || model != profile
            || field_id != scalar
            || !matches!(value.reference_origin,Some(ReferenceOrigin::Field {parameter:actual,model:source,field})
                if actual == parameter && source == branch && field == reference)
            || !value.reads.iter().any(|read| {
                read.node == base_key
                    && read.model == branch
                    && read.field == reference
                    && read.ty
                        == (ResolvedType::Record {
                            symbol: profile,
                            stored: true,
                        })
                    && self
                        .resolve
                        .symbols
                        .get(reference.0 as usize)
                        .is_some_and(|field| read.field_name == field.name)
                    && read.calls.is_empty()
                    && read.query_id.is_none()
            })
        {
            return Err(self.fail(
                key,
                "Profile scalar needs its original stored reference receiver",
            ));
        }
        // This scalar consumes exactly its original stored receiver.
        // The separate owning reference read remains in provenance.
        value.reference_origin = None;
        Ok(())
    }

    fn expr_member_profile_reference_type(
        &self,
        key: NodeKey,
        calls: &[NodeKey],
        env: &Env,
        model: SymbolId,
        field_id: SymbolId,
        profile_reference: Option<(SymbolId, SymbolId, SymbolId, SymbolId)>,
        value: &mut ValuePath,
    ) -> Result<Option<String>, DisclosureDecline> {
        let Some((parameter, branch, reference, profile)) = profile_reference
        else {
            return Ok(None);
        };
        if !calls.is_empty() || self.loop_node.is_some() || model != branch || field_id != reference
            || !matches!(value.reference_origin,Some(ReferenceOrigin::Parameter(actual)) if actual == parameter)
            || !env.get(&Local::Symbol(parameter)).is_some_and(|input| {
                matches!(input.reference_origin,Some(ReferenceOrigin::Parameter(actual)) if actual == parameter)
            })
        {
            return Err(self.fail(key,"Profile reference needs its original required Branch input"));
        }
        value.reference_origin = Some(ReferenceOrigin::Field {
            parameter,
            model: branch,
            field: reference,
        });
        Ok(Some(
            self.reference_operand_type_id(&ResolvedType::Record {
                symbol: profile,
                stored: true,
            })
            .ok_or_else(|| {
                self.fail(key, "Profile reference lacks its owning model declaration")
            })?,
        ))
    }

    fn expr_member_parent_scalar_type(
        &self,
        key: NodeKey,
        module: ModuleId,
        base_key: NodeKey,
        model: SymbolId,
        calls: &[NodeKey],
        parent_origin: Option<SymbolId>,
        field_id: SymbolId,
        field_ty: &ResolvedType,
        value: &mut ValuePath,
    ) -> Result<Option<String>, DisclosureDecline> {
        let original_helper_parent=parent_origin.is_some_and(|parameter|
            matches!(value.reference_origin,Some(ReferenceOrigin::Parent{parameter:actual,model:parent,depth})
                if actual==parameter&&parent==model
                    &&self.original_helper_model_path(base_key,module,calls)==Some((parameter,model,depth))));
        if !(parent_origin.is_some()
            && (calls.is_empty()||original_helper_parent)
            && self.loop_node.is_none()
            && ((primitive_type(field_ty) || *field_ty == ResolvedType::Scalar(Scalar::Timezone))
                || matches!(field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())))
        {
            return Ok(None);
        }
        // A scalar leaf consumes the authenticated parent path. Keep
        // every preceding edge read and the leaf's own dependency.
        value.reference_origin = None;
        Ok(Some(self.field_type_id(key, field_id, field_ty)?))
    }

    fn expr_member_parent_ref_type(
        &self,
        key: NodeKey,
        calls: &[NodeKey],
        model: SymbolId,
        field_id: SymbolId,
        field_ty: &ResolvedType,
        parent_origin: Option<SymbolId>,
        value: &mut ValuePath,
    ) -> Result<Option<String>, DisclosureDecline> {
        let Some(parameter) = parent_origin else {
            return Ok(None);
        };
        let declaration = self
            .effects
            .models
            .get(&model)
            .and_then(|model| {
                model
                    .fields
                    .iter()
                    .find(|candidate| candidate.field == field_id)
            })
            .ok_or_else(|| self.fail(key, "missing checked reference field declaration"))?;
        if declaration.default.is_some()
            || declaration.server.is_some()
            || !calls.is_empty()
        {
            return Err(
                self.fail(key, "reference operand needs required direct stored field")
            );
        }
        if matches!(field_ty, ResolvedType::Array { .. }) {
            let alias = self
                .types
                .field_reuse_sources
                .get(&field_id)
                .ok_or_else(|| {
                    self.fail(key, "reference array needs genuine Scope field reuse")
                })?;
            if !matches!(self.resolve.symbols.get(alias.0 as usize).map(|symbol| &symbol.kind),
                Some(SymbolKind::Field { owner, .. }) if matches!(self.resolve.symbols.get(owner.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Contract { .. })))
            {
                return Err(self.fail(key, "reference array needs owning Scope field"));
            }
        }
        value.reference_origin = Some(ReferenceOrigin::Field {
            parameter,
            model,
            field: field_id,
        });
        Ok(Some(
            self.reference_operand_type_id(field_ty)
                .ok_or_else(|| self.fail(key, "reference operand canonical type"))?,
        ))
    }

    fn expr_member_required_type(
        &self,
        key: NodeKey,
        model: SymbolId,
        field_id: SymbolId,
        field_ty: &ResolvedType,
        required_reference: Option<SymbolId>,
        value: &mut ValuePath,
    ) -> Result<Option<String>, DisclosureDecline> {
        if required_reference.is_none() {
            return Ok(None);
        }
        if self.effects.models.get(&model).is_none_or(|owner| {
            !owner.fields.iter().any(|declaration| {
                declaration.field == field_id && !declaration.required_array
            })
        }) {
            return Err(self.fail(key, "missing required stored Model field declaration"));
        }
        value.contract_value = None;
        value.first_query = None;
        value.reference_origin = None;
        Ok(Some(
            self.reference_operand_type_id(field_ty).ok_or_else(|| {
                self.fail(key, "missing required stored Model target declaration")
            })?,
        ))
    }

    /// A nullable stored-record field selected off an original required
    /// record parameter: a sealed handle whose admitted consumer is the
    /// same-model equality in `binary_parent_comparison`. Non-nullable
    /// fields keep the required-reference path above; this arm never
    /// re-admits a shape that path refused. Keeps no lineage; the
    /// field's own read stays on the emitted value.
    fn expr_member_parameter_field_reference(
        &self,
        key: NodeKey,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_ty: &ResolvedType,
        value: &mut ValuePath,
    ) -> Result<Option<String>, DisclosureDecline> {
        if !calls.is_empty()
            || self.loop_node.is_some()
            || !matches!(field_ty, ResolvedType::Nullable(_))
        {
            return Ok(None);
        }
        let Some(ReferenceOrigin::Parameter(parameter)) = value.reference_origin else {
            return Ok(None);
        };
        if !matches!(self.query_binding(base_key), Some(Binding::Symbol(actual)) if *actual == parameter)
        {
            return Ok(None);
        }
        let Some(target) = self.call_parameter_field(key, parameter) else {
            return Ok(None);
        };
        let Some(canonical) = self
            .resolve
            .symbols
            .get(target.0 as usize)
            .map(|symbol| symbol.canonical.clone())
        else {
            return Ok(None);
        };
        value.contract_value = None;
        value.first_query = None;
        value.reference_origin = None;
        Ok(Some(format!("{canonical}?")))
    }

    fn expr_member_contract_record_type(
        &self,
        key: NodeKey,
        calls: &[NodeKey],
        base_key: NodeKey,
        model: SymbolId,
        field_ty: &ResolvedType,
        field_id: SymbolId,
        owner: &'a Symbol,
        value: &mut ValuePath,
    ) -> Result<String, DisclosureDecline> {
        let (contract, nullable) = match field_ty {
            ResolvedType::Record { symbol, .. } => (*symbol, false),
            ResolvedType::Nullable(inner)
                if matches!(inner.as_ref(), ResolvedType::Record { .. }) => {
                let ResolvedType::Record { symbol, .. } = inner.as_ref() else {
                    return Err(self.fail(key, "missing owning canonical Contract declaration"));
                };
                let Some((_, event_field)) = self.hook_delivery_field(base_key, owner.module) else {
                    return Err(self.fail(key, "nullable Contract needs original notice event row"));
                };
                if !calls.is_empty()
                    || self.loop_node.is_some()
                    || owner.canonical != "agreements.Term"
                    || self.resolve.symbols.get(event_field.0 as usize)
                        .is_none_or(|event_field| event_field.name != "term")
                    || self.count_member(key) != Some((base_key, "snapshot"))
                    || self.resolve.symbols.get(field_id.0 as usize)
                        .is_none_or(|field| field.name != "snapshot")
                {
                    return Err(self.fail(key, "nullable Contract needs original notice snapshot"));
                }
                (*symbol, true)
            }
            _ => return Err(self.fail(key, "missing owning canonical Contract declaration")),
        };
        let contract = self
            .resolve
            .symbols
            .get(contract.0 as usize)
            .filter(|contract| {
                matches!(contract.kind, SymbolKind::Contract { .. })
                    && contract.module == owner.module
            })
            .ok_or_else(|| {
                self.fail(key, "missing owning canonical Contract declaration")
            })?;
        let declaration = self
            .effects
            .models
            .get(&model)
            .and_then(|model| {
                model
                    .fields
                    .iter()
                    .find(|candidate| candidate.field == field_id)
            })
            .ok_or_else(|| {
                self.fail(key, "missing checked stored Contract field declaration")
            })?;
        if declaration.required_array || !calls.is_empty() {
            return Err(self.fail(key, "unsupported stored Contract field occurrence"));
        }
        value.contract_value = Some(ContractValue::Singular(contract.id));
        Ok(format!("{}{}", contract.canonical, if nullable { "?" } else { "" }))
    }

    fn expr_member_parent_origin(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        base_key: NodeKey,
        model: SymbolId,
        field_ty: &ResolvedType,
        value: &ValuePath,
    ) -> Result<Option<SymbolId>, DisclosureDecline> {
        let parent_origin = match value.reference_origin {
            Some(ReferenceOrigin::Parent {
                parameter,
                model: parent,
                depth,
            }) if parent == model
                && (depth == 1
                    || depth == 2
                        && ((calls.is_empty()
                            && self.loop_node.is_none()
                            && ((primitive_type(field_ty) || *field_ty == ResolvedType::Scalar(Scalar::Timezone))
                                || matches!(field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())))
                            || self
                                .checked_helper_reference_argument(key, module)
                                .is_some()
                            || self
                                .checked_reference_identity_operand(key, module)
                                .is_some())) =>
            {
                Some(parameter)
            }
            _ => None,
        };
        if parent_origin.is_some()
            && (!((primitive_type(field_ty) || *field_ty == ResolvedType::Scalar(Scalar::Timezone))
                || matches!(field_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty())
                || self.reference_operand_type_id(field_ty).is_some())
                || !self
                    .nodes
                    .get(&base_key)
                    .is_some_and(|node| node.kind == SyntaxKind::Member)
                || !value
                    .reads
                    .iter()
                    .any(|read| read.node == base_key && read.field_name == "parent"))
        {
            return Err(self.fail(
                key,
                "parent edge needs direct required Model reference field",
            ));
        }
        Ok(parent_origin)
    }

    fn expr_member_field_emit(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        model: SymbolId,
        owner: &'a Symbol,
        field: &'a Symbol,
        field_ty: &'a ResolvedType,
        required_reference: Option<SymbolId>,
        profile_reference: Option<(SymbolId, SymbolId, SymbolId, SymbolId)>,
        type_id: String,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        value.reads.push(DisclosureDependency {
            query_id: None,
            id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
            source: self.source(module, key)?,
            node: key,
            calls: calls.to_vec(),
            role: DependencyRole::Data,
            model,
            field: field.id,
            model_name: owner.canonical.clone(),
            field_name: field.name.clone(),
            ty: field_ty.clone(),
            type_id,
        });
        value.observed.push((key, calls.to_vec()));
        value.record = required_reference
            .or_else(|| self.nullable_field_call_branch(key, module).or_else(||self.nullable_field_if_branch(key,module))
                .filter(|(_, operand, _, _, _, _)| *operand == key).map(|(_, _, _, _, _, target)| target))
            .or_else(|| profile_reference.map(|(_, _, _, profile)| profile))
            .or_else(|| {
                self.checked_reference_identity_operand(key, module)
                    .map(|(_, _, _, _, target, _)| target)
            });
        value.model_result =
            required_reference.map(|target| DisclosureModelResult::Reference {
                model: target,
                node: key,
                source_model: model,
                field: field.id,
            });
        if let Some((parameter, _, source, reference, _, _)) =
            self.checked_reference_identity_operand(key, module)
        {
            value.reference_origin = Some(ReferenceOrigin::Field {
                parameter,
                model: source,
                field: reference,
            });
            value.model_result = None;
        }
        value.reference = None;
        Ok(())
    }

    fn expr_member_field_decl(
        &self,
        key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        model: SymbolId,
    ) -> Result<(&'a Symbol, &'a Symbol, &'a ResolvedType), DisclosureDecline> {
        let owner = self
            .resolve
            .symbols
            .get(model.0 as usize)
            .ok_or_else(|| self.fail(key, "missing model owner"))?;
        let SymbolKind::Model { fields, .. } = &owner.kind else {
            return Err(self.fail(key, "non-model field owner"));
        };
        let field = fields
            .iter()
            .find_map(|id| {
                self.resolve
                    .symbols
                    .get(id.0 as usize)
                    .filter(|s| s.name == field_name)
            })
            .ok_or_else(|| self.fail(key, "reserved or unresolved stored field"))?;
        let field_ty = self
            .types
            .symbol_types
            .get(&field.id)
            .ok_or_else(|| self.fail(key, "missing stored field type"))?;
        // Flow checking can narrow a nullable field after a successful
        // `require field != null`. Keep the declared nullable field in the
        // source dependency below; only its checked non-null occurrence may
        // use the narrower expression type.
        let narrowed_nullable =
            matches!(field_ty, ResolvedType::Nullable(inner) if inner.as_ref() == ty);
        if (field_ty != ty && !narrowed_nullable) || field.module != owner.module {
            return Err(self.fail(key, "stored field schema identity mismatch"));
        }
        Ok((owner, field, field_ty))
    }

    fn expr_member_field_leaf(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let (owner, field, field_ty) =
            self.expr_member_field_decl(key, field_name, ty, model)?;
        self.expr_member_derived_field(key, calls, base_key, model, field, field_ty, value)?;
        let profile_reference = self
            .checked_scalar_reference(ScalarReferenceKind::Profile, key, module)
            .or_else(|| {
                self.checked_scalar_reference(ScalarReferenceKind::Run, key, module)
            });
        let profile_scalar = self
            .checked_profile_scalar(key, module)
            .or_else(|| self.checked_run_unfinished(key, module));
        let required_reference = self.expr_member_required_reference(
            key,
            module,
            calls,
            base_key,
            model,
            field.id,
            value,
        );
        if let Some((_, source, reference, target, scalar)) = self.checked_required_reference_scalar(key, module) {
            if !calls.is_empty() || self.loop_node.is_some() || model != target || field.id != scalar
                || !matches!(value.model_result, Some(DisclosureModelResult::Reference {
                    model, node, source_model, field }) if model == target && node == base_key
                    && source_model == source && field == reference)
                || !value.reads.iter().any(|read| read.node == base_key && read.model == source
                    && read.field == reference && read.ty == ResolvedType::Record {symbol: target, stored: true}
                    && read.calls.is_empty() && read.query_id.is_none()) {
                return Err(self.fail(key, "scalar needs its original required stored reference receiver"));
            }
            value.reference_origin = None;
        }
        self.expr_member_profile_scalar_leaf(
            key,
            module,
            calls,
            base_key,
            model,
            field.id,
            profile_scalar,
            value,
        )?;
        let parent_origin = if required_reference.is_some() && !calls.is_empty() {None}else{
            self.expr_member_parent_origin(key,module,calls,base_key,model,field_ty,value)?
        };
        let guarded_parent = calls.is_empty() && self.loop_node.is_none()
            && self.nullable_field_if_branch(base_key,module).is_some_and(|(_, operand, parameter, source, link, target)|
                operand==base_key && target==model
                && value.reference_origin==Some(ReferenceOrigin::Field{parameter,model:source,field:link})
                && value.reads.iter().any(|read|read.node==base_key && read.model==source && read.field==link
                    && read.ty==ResolvedType::Nullable(Box::new(ResolvedType::Record{symbol:target,stored:true}))));
        let type_id = if guarded_parent {
            value.reference_origin=None;
            if matches!(field_ty,ResolvedType::Record{stored:true,..})
                || matches!(field_ty,ResolvedType::Nullable(inner) if matches!(inner.as_ref(),ResolvedType::Record{stored:true,..})) {
                self.reference_operand_type_id(field_ty).ok_or_else(||self.fail(key,"guarded reference field schema mismatch"))?
            }else{self.field_type_id(key,field.id,field_ty)?}
        }else if calls.is_empty() && self.loop_node.is_none()
            && let Some((_, operand, parameter, source, original_field, target)) = self.nullable_field_call_branch(key, module).or_else(||self.nullable_field_if_branch(key,module))
            && operand == key && source == model && original_field == field.id && ty == &(ResolvedType::Record { symbol: target, stored: true })
            && value.reference_origin == Some(ReferenceOrigin::Parameter(parameter))
        {
            value.reference_origin = Some(ReferenceOrigin::Field { parameter, model, field: field.id });
            self.reference_operand_type_id(field_ty).ok_or_else(|| self.fail(key, "narrowed CALL field lacks its model type"))?
        } else if let Some(type_id) = self.expr_member_profile_reference_type(
            key,
            calls,
            env,
            model,
            field.id,
            profile_reference,
            value,
        )? {
            type_id
        } else if let Some(type_id) = self.expr_member_parent_scalar_type(
            key,
            module,
            base_key,
            model,
            calls,
            parent_origin,
            field.id,
            field_ty,
            value,
        )? {
            type_id
        } else if let Some(type_id) = self.expr_member_parent_ref_type(
            key,
            calls,
            model,
            field.id,
            field_ty,
            parent_origin,
            value,
        )? {
            type_id
        } else if let Some(type_id) = self.expr_member_required_type(
            key,
            model,
            field.id,
            field_ty,
            required_reference,
            value,
        )? {
            type_id
        } else if let Some(type_id) = self.expr_member_parameter_field_reference(
            key,
            calls,
            base_key,
            field_ty,
            value,
        )? {
            type_id
        } else if calls.is_empty()
            && self.loop_node.is_none()
            && let Some(type_id) = self.source_require_reference_array(key, module)
        {
            value.contract_value = None;
            value.first_query = None;
            value.reference_origin = None;
            type_id
        } else if let ResolvedType::Array{element,ordered:true,nonempty:false}=field_ty
            && let ResolvedType::Record{symbol:contract,..}=element.as_ref()
            && self.is_contract_symbol(*contract)
            && self.source_require_plain_value(field_ty,0)
            && self.effects.models.get(&model).is_some_and(|model|model.fields.iter().any(|declaration|
                declaration.field==field.id&&!declaration.required_array))
        {
            // One ordered whole-value observation. Elements remain canonical
            // Contract data and cannot issue a Model/File/reference view.
            value.contract_value=Some(ContractValue::Array(*contract));
            checked_stored_contract_type_id(field_ty,None,self.resolve,0)
                .ok_or_else(||self.fail(key,"stored Contract array needs its exact declared nominal type"))?
        } else if matches!(field_ty, ResolvedType::Record { .. })
            || matches!(field_ty, ResolvedType::Nullable(inner)
                if matches!(inner.as_ref(), ResolvedType::Record { .. }))
        {
            self.expr_member_contract_record_type(
                key,
                calls,
                base_key,
                model,
                field_ty,
                field.id,
                owner,
                value,
            )?
        } else {
            self.field_type_id(key, field.id, field_ty)?
        };
        self.expr_member_field_emit(
            key,
            module,
            calls,
            model,
            owner,
            field,
            field_ty,
            required_reference,
            profile_reference,
            type_id,
            value,
        )
    }

    fn expr_member_value(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        field_name: &str,
        ty: &ResolvedType,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if field_name == "id" && *ty == ResolvedType::Scalar(Scalar::Text)
            && calls.is_empty() && self.loop_node.is_none()
            && let Some((source, field, target, _)) = self.created_reference_identity(base_key, module)
            && matches!(value.model_result, Some(DisclosureModelResult::Reference {model, node, source_model, field: actual})
                if model == target && node == base_key && source_model == source && actual == field)
            && value.reads.iter().any(|read| read.node == base_key && read.model == source && read.field == field
                && read.ty == ResolvedType::Record {symbol: target, stored: true}
                && read.calls.is_empty() && read.query_id.is_none())
        {
            value.record = None; value.model_result = None;
            value.reference = None; value.reference_origin = None;
            return Ok(());
        }
        if field_name=="id" && *ty==ResolvedType::Scalar(Scalar::Text) && self.loop_node.is_none()
            && let Some((source,field,target))=self.helper_reference_identity(base_key,module,calls)
            && matches!(value.model_result,Some(DisclosureModelResult::Reference{model,node,source_model,field:actual})
                if model==target && node==base_key && source_model==source && actual==field)
            && value.reads.iter().any(|read|read.node==base_key && read.model==source && read.field==field
                && read.ty==ResolvedType::Record{symbol:target,stored:true} && read.calls==calls && read.query_id.is_none()) {
            value.record=None;value.model_result=None;value.reference=None;value.reference_origin=None;
            return Ok(());
        }
        self.expr_member_model_guard(key, module, calls, base_key, value)?;
        let notice_snapshot_title = field_name == "title"
            && *ty == ResolvedType::Scalar(Scalar::Text)
            && matches!(value.contract_value, Some(ContractValue::Singular(contract))
                if self.resolve.symbols.get(contract.0 as usize)
                    .is_some_and(|contract| contract.canonical == "agreements.ExecutedParties"))
            && self.count_member(base_key).is_some_and(|(event_term, name)|
                name == "snapshot"
                    && self.hook_delivery_field(event_term, module)
                        .is_some_and(|(_, field)| self.resolve.symbols.get(field.0 as usize)
                            .is_some_and(|field| field.name == "term")))
            && value.reads.iter().any(|read| read.node == base_key
                && read.model_name == "agreements.Term" && read.field_name == "snapshot"
                && read.calls.is_empty() && read.query_id.is_none());
        self.expr_member_contract_value(key, module, base_key, field_name, ty, value)?;
        if notice_snapshot_title {
            // The whole nullable Contract was observed at its original Term
            // field; its checked local title has no separate stored row.
            return Ok(());
        }
        let Some(model) =
            self.expr_member_composite_value(key, base_key, field_name, ty, value)?
        else {
            return Ok(());
        };
        if field_name == "id" {
            self.expr_member_id_leaf(key, module, calls, base_key, ty, model, value)?;
            return Ok(());
        }
        if field_name == "parent" {
            self.expr_member_parent_leaf(
                key,
                module,
                env,
                calls,
                base_key,
                ty,
                model,
                value,
            )?;
            return Ok(());
        }
        if field_name == "version" {
            self.expr_member_version_leaf(key, module, calls, ty, model, value)?;
            return Ok(());
        }
        self.expr_member_field_leaf(
            key,
            module,
            env,
            calls,
            base_key,
            field_name,
            ty,
            model,
            value,
        )
    }

    fn expr_member_derived_field(
        &self,
        key: NodeKey,
        calls: &[NodeKey],
        base_key: NodeKey,
        model: SymbolId,
        field: &'a Symbol,
        field_ty: &'a ResolvedType,
        value: &ValuePath,
    ) -> Result<(), DisclosureDecline> {
        if !matches!(field.kind, SymbolKind::Field { owner, .. } if owner == model) {
            // Derived members keep their exact owning declaration and
            // complete body over an exact required Model reference. The
            // codegen seal re-verifies the complete member against fresh
            // IR, so a changed body keeps its refusal there.
            let leaf = match field_ty {
                ResolvedType::Nullable(inner) => inner.as_ref(),
                ty => ty,
            };
            if !matches!(field.kind, SymbolKind::DeriveField { model: owner, .. } if owner == model)
                || self.admitted_derived_read(field.id, model, &mut Vec::new()).is_none()
                || !(primitive_type(leaf)
                    || matches!(leaf, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                || !calls.is_empty()
                || self.loop_node.is_some()
                || !matches!(&value.reference_origin, Some(ReferenceOrigin::Parameter(parameter))
                    if matches!(self.query_binding(base_key), Some(Binding::Symbol(actual)) if actual == parameter))
            {
                return Err(self.fail(key, "derived field requires its complete body closure"));
            }
        }
        Ok(())
    }

    fn expr_member_parent_replay_query(
        &self,
        module: ModuleId,
        base_key: NodeKey,
        model: SymbolId,
        value: &ValuePath,
    ) -> Option<DisclosureQuery> {
        if self.loop_node.is_some() {
            return None;
        }
        let (call, binding) = value.first_query?;
        let Binding::Let { node } = self.query_binding(base_key)? else {
            return None;
        };
        if *node != binding {
            return None;
        }
        self.effects.scenarios.values().find_map(|scenario| {
            if scenario.module != module {
                return None;
            }
            let effect = scenario
                .effects
                .iter()
                .find(|effect| effect.node == binding)?;
            let query = self.checked_first_query_source(scenario, effect)?;
            (query.model == model && query.first.as_ref()?.call == call).then_some(query)
        })
    }

    fn expr_member_parent_replay(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        base_key: NodeKey,
        ty: &ResolvedType,
        model: SymbolId,
        value: &mut ValuePath,
    ) -> Result<bool, DisclosureDecline> {
        // Replay may compare the genuine first-selected child's parent
        // identity with an original required input. This consumes the
        // identity here; it does not establish a navigable parent row.
        if !(calls.is_empty()
            && self.loop_node.is_none()
            && value.first_query.is_some()
            && matches!(self.query_binding(base_key), Some(Binding::Let { node }) if value.first_query.is_some_and(|(_, binding)| *node == binding))
            && self
                .expr_member_parent_replay_query(module, base_key, model, value)
                .is_some())
        {
            return Ok(false);
        }
        let Some(query) = self.expr_member_parent_replay_query(module, base_key, model, value)
        else {
            return Err(self.fail(key, "selected parent needs checked child containment"));
        };
        let owner = self
            .resolve
            .symbols
            .get(model.0 as usize)
            .ok_or_else(|| self.fail(key, "missing selected child declaration"))?;
        let SymbolKind::Model {
            owner: ModelOwner::ChildOf(parent),
            fields,
            ..
        } = &owner.kind
        else {
            return Err(
                self.fail(key, "selected parent needs checked child containment")
            );
        };
        let expected = ResolvedType::Record {
            symbol: *parent,
            stored: true,
        };
        let comparison = self.nodes.keys().any(|comparison| {
            let Some((left, right)) = self.query_binary(*comparison, "==") else { return false; };
            [(left, right), (right, left)].iter().any(|(selected, input)| {
                self.query_group(*selected) == Some(key)
                    && self.types.node_types.get(input) == Some(&expected)
                    && matches!(self.query_binding(*input), Some(Binding::Symbol(parameter))
                        if self.original_reference_parameter(*input, *parameter)
                            && env.get(&Local::Symbol(*parameter)).is_some_and(|value| {
                                value.record == Some(*parent)
                                    && value.reference_origin == Some(ReferenceOrigin::Parameter(*parameter))
                            }))
            })
        });
        if !comparison
            || *ty != expected
            || fields.iter().any(|field| {
                self.resolve
                    .symbols
                    .get(field.0 as usize)
                    .is_none_or(|field| field.name == "parent")
            })
            || self
                .effects
                .models
                .get(&model)
                .is_none_or(|model| model.owner != ModelOwner::ChildOf(*parent))
            || query
                .influences
                .iter()
                .any(|influence| !value.influences.contains(influence))
        {
            return Err(
                self.fail(key, "selected parent identity source correspondence")
            );
        }
        value.reads.push(DisclosureDependency {
            query_id: None,
            id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
            source: self.source(module, key)?,
            node: key,
            calls: Vec::new(),
            role: DependencyRole::Data,
            model,
            field: model,
            model_name: owner.canonical.clone(),
            field_name: "parent".into(),
            ty: expected.clone(),
            type_id: self
                .reference_operand_type_id(&expected)
                .ok_or_else(|| self.fail(key, "missing selected parent declaration"))?,
        });
        value.observed.push((key, Vec::new()));
        value.record = None;
        value.reference = None;
        value.reference_origin = None;
        value.first_query = None;
        Ok(true)
    }

    fn expr_member(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        node: &SyntaxNode,
        children: Vec<&SyntaxNode>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if let Some(values) = self.expr_member_selection_prefix(key, module, env, calls)? {
            return Ok(values);
        }
        let ty = self
            .types
            .node_types
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing checked expression type"))?;
        let base = children
            .first()
            .ok_or_else(|| self.fail(key, "missing member base"))?;
        let base_key = NodeKey::of(base);
        let field_name = node
            .children
            .iter()
            .rev()
            .find(|n| n.kind == SyntaxKind::Name)
            .and_then(|n| {
                self.db
                    .get(n.span.file)?
                    .text
                    .get(n.span.start as usize..n.span.end as usize)
            })
            .ok_or_else(|| self.fail(key, "missing member identity"))?;
        if let Some(values) =
            self.expr_member_intrinsics(key, module, calls, base_key, field_name, ty)?
        {
            return Ok(values);
        }
        if let Some(values) = self.expr_member_context_inputs(
            key,
            module,
            env,
            calls,
            base_key,
            field_name,
            ty,
        )? {
            return Ok(values);
        }
        let mut values = self.expr(base_key, module, env, calls)?;
        if self.expr_member_envelope(
            key,
            module,
            env,
            calls,
            base_key,
            field_name,
            ty,
            &mut values,
        )? {
            return Ok(std::mem::take(&mut values));
        }
        for value in &mut values {
            self.expr_member_value(key, module, env, calls, base_key, field_name, ty, value)?;
        }
        Ok(values)
    }

    fn expr_array(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        children: Vec<&SyntaxNode>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        let ty = self
            .types
            .node_types
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing checked expression type"))?;
        let base = match ty {
            ResolvedType::Nullable(inner) => inner.as_ref(),
            ty => ty,
        };
        let ResolvedType::Array { element, .. } = base else {
            return Err(self.fail(key, "unsupported array expression type"));
        };
        // An empty literal carries no element provenance; any element shape
        // is admitted here and the declaration gate stays at the parameter.
        if children.is_empty() {
            return Ok(vec![ValuePath::default()]);
        }
        let declared_constructs = matches!(element.as_ref(), ResolvedType::Record { symbol, stored: false }
            if self.is_contract_symbol(*symbol))
            && self.declared_constructor_schema(element, 0, &mut HashSet::new(), &mut 0).is_some()
            && children.iter().all(|child| self.query_group(NodeKey::of(child)).is_some_and(|key|
                self.nodes.get(&key).is_some_and(|node| node.kind == SyntaxKind::Construct)
                    && self.types.node_types.get(&key) == Some(element.as_ref())));
        let composite = matches!(element.as_ref(), ResolvedType::Object(_))
            || checked_standard_nominal_name(element) == Some("TextMessage");
        let empty_files =
            children.is_empty() && matches!(element.as_ref(), ResolvedType::Scalar(Scalar::File));
        // Closed enum sets carry no reads, like literals. The checker retains
        // the source field's nullable nominal type on claimed enum cases;
        // only those exact resolved cases may use this nullable carrier.
        let nullable_enum = matches!(element.as_ref(), ResolvedType::Nullable(inner)
            if matches!(inner.as_ref(), ResolvedType::Enum { cases, .. } if !cases.is_empty()));
        let enum_base = match element.as_ref() {
            ResolvedType::Nullable(inner) => inner.as_ref(), ty => ty,
        };
        let closed_enum = matches!(enum_base, ResolvedType::Enum { cases, .. } if !cases.is_empty());
        if !primitive_type(element) && !composite && !empty_files && !closed_enum && !declared_constructs {
            return Err(self.fail(key, "unsupported array expression type"));
        }
        let mut paths = vec![ValuePath::default()];
        for child in children {
            let element_ty = self
                .types
                .node_types
                .get(&NodeKey::of(child))
                .ok_or_else(|| self.fail(key, "missing checked array element type"))?;
            if !declared_constructs && !primitive_type(element_ty)
                && !matches!(element_ty, ResolvedType::Object(_))
                && checked_standard_nominal_name(element_ty) != Some("TextMessage")
                && !(!nullable_enum && matches!(element_ty, ResolvedType::Enum { cases, .. } if !cases.is_empty()))
                && !(closed_enum && self.types.resolved_cases.contains(&NodeKey::of(child))
                    && match element_ty { ResolvedType::Nullable(inner) => inner.as_ref(), ty => ty } == enum_base)
            {
                return Err(self.fail(key, "unsupported array element type"));
            }
            let element = self.expr(NodeKey::of(child), module, env, calls)?;
            if composite
                && element
                    .iter()
                    .any(|value| value.schema.as_deref() != Some("TextMessage"))
            {
                return Err(self.fail(key, "array needs checked TextMessage values"));
            }
            paths = self.product(key, &paths, &element)?;
        }
        Ok(paths)
    }

    /// Optional scalar selection keeps the original coalesce decision. The
    /// required field is observed only on the selected-row branch; absence
    /// evaluates the original actor fallback without inventing a field read.
    fn first_optional_actor_coalesce(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if !calls.is_empty() || self.loop_node.is_some() {
            return Ok(None);
        }
        let Some((member, fallback)) = self.query_binary(key, "??") else {
            return Ok(None);
        };
        let Some((base, field_name)) = self.count_member(member) else {
            return Ok(None);
        };
        let Some(Binding::Let { node: binding }) = self.query_binding(base) else {
            return Ok(None);
        };
        let Some(selected) = env.get(&Local::Let(*binding)) else {
            return Ok(None);
        };
        let Some((call, original_binding)) = selected.first_query else {
            return Ok(None);
        };
        let Some(model) = selected.record else {
            return Ok(None);
        };
        if original_binding != *binding {
            return Ok(None);
        }
        let query = self.effects.scenarios.values().find_map(|scenario| {
            if scenario.module != module {
                return None;
            }
            let effect = scenario
                .effects
                .iter()
                .find(|effect| effect.node == *binding)?;
            let query = self.checked_first_query_source(scenario, effect)?;
            (query.first.as_ref()?.call == call && query.first.as_ref()?.reference_predicate.is_some())
                .then_some(query)
        });
        let Some(query) = query else {
            return Ok(None);
        };
        let Some(owner) = self.resolve.symbols.get(model.0 as usize) else {
            return Ok(None);
        };
        let Some(field) = owner.fields_of().iter().copied().find(|field| {
            self.resolve
                .symbols
                .get(field.0 as usize)
                .is_some_and(|field| field.name == field_name)
        }) else {
            return Ok(None);
        };
        let ty = ResolvedType::Scalar(Scalar::User);
        if !matches!(self.resolve.symbols[field.0 as usize].kind,SymbolKind::Field{owner,..} if owner==model)
            || self.types.symbol_types.get(&field) != Some(&ty)
            || self
                .types
                .node_types
                .get(&self.query_group(member).unwrap_or(member))
                != Some(&ResolvedType::Nullable(Box::new(ty.clone())))
            || self
                .types
                .node_types
                .get(&self.query_group(base).unwrap_or(base))
                != Some(&ResolvedType::Nullable(Box::new(ResolvedType::Record {
                    symbol: model,
                    stored: true,
                })))
            || self
                .types
                .node_types
                .get(&self.query_group(fallback).unwrap_or(fallback))
                != Some(&ty)
            || !matches!(
                self.query_binding(fallback),
                Some(Binding::Context(ContextVar::Actor(_)))
            )
            || self.types.node_types.get(&key) != Some(&ty)
            || query
                .influences
                .iter()
                .any(|influence| !selected.influences.contains(influence))
        {
            return Ok(None);
        }
        let mut present = selected.clone();
        present.record = None;
        present.first_query = None;
        present.reference = None;
        present.reference_origin = None;
        let mut absent = present.clone();
        present.reads.push(DisclosureDependency {
            query_id: None,
            id: self.opaque("read-data", member, &self.call_stamp(calls)?)?,
            source: self.source(module, member)?,
            node: member,
            calls: Vec::new(),
            role: DependencyRole::Data,
            model,
            field,
            model_name: owner.canonical.clone(),
            field_name: field_name.to_owned(),
            ty,
            type_id: "user".into(),
        });
        present.observed.push((member, Vec::new()));
        present.decisions.push(DisclosureDecision {
            node: key,
            calls: Vec::new(),
            choice: DisclosureChoice::RhsSkipped,
        });
        absent.decisions.push(DisclosureDecision {
            node: key,
            calls: Vec::new(),
            choice: DisclosureChoice::RhsEvaluated,
        });
        let fallback = self.expr(fallback, module, env, calls)?;
        let mut values = vec![present];
        for fallback in fallback {
            let mut absent = absent.clone();
            absent.join(&fallback);
            values.push(absent);
        }
        self.bounded(key, values).map(Some)
    }

    fn expr_binary(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        node: &SyntaxNode,
        children: Vec<&SyntaxNode>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if let Some(values)=self.first_optional_actor_coalesce(key,module,env,calls)?{return Ok(values);}
        if children.len() != 2 {
            return Err(self.fail(key, "invalid binary shape"));
        }
        let op = node
            .children
            .iter()
            .find(|n| matches!(n.kind, SyntaxKind::Name | SyntaxKind::Punct))
            .and_then(|n| {
                self.db
                    .get(n.span.file)?
                    .text
                    .get(n.span.start as usize..n.span.end as usize)
            })
            .ok_or_else(|| self.fail(key, "missing checked operator"))?;
        let (current_null_check, first_null_check, input_null_check) =
            self.binary_null_checks(key, module, env, calls, op, &children);
        let notice_snapshot_null_check =
            self.notice_snapshot_null_check(key, module, calls, op, &children);
        // Exact original required Model slots, direct or in Contracts, may
        // consume checked containment in equality. Both operands retain their
        // own admission provenance and must name the same model. Arbitrary
        // stored-reference fields keep their direct-child/count-only boundary.
        // The admitted shape below subsumes the nullable-record refusal: both
        // sides are sealed scenario inputs and the result keeps no lineage.
        let admitted_parent_comparison =
            self.binary_parent_comparison(module, env, calls, op, &children);
        let narrowed_call_presence = calls.is_empty() && self.nullable_field_call_branch(key, module).is_some();
        if !first_null_check
            && !input_null_check
            && !notice_snapshot_null_check
            && !admitted_parent_comparison
            && !narrowed_call_presence
            && matches!(op, "??" | "==" | "!=")
            && children.iter().any(|operand| {
                matches!(self.types.node_types.get(&NodeKey::of(operand)),
                            Some(ResolvedType::Nullable(inner))
                                if matches!(inner.as_ref(), ResolvedType::Record { .. }))
            })
        {
            return Err(self.influence(
                key,
                module,
                &[InfluenceKind::AbsentReference],
                "nullable reference selection or comparison",
            ));
        }
        let left = self.expr(NodeKey::of(children[0]), module, env, calls)?;
        if !current_null_check
            && !admitted_parent_comparison
            && left.iter().any(|value| {
                matches!(
                    value.reference_origin,
                    Some(ReferenceOrigin::Parent { .. } | ReferenceOrigin::Field { .. })
                )
            })
        {
            return Err(self.fail(
                key,
                "stored reference operand needs direct child or count consumer",
            ));
        }
        if matches!(op, "and" | "or" | "??") {
            let right = self.expr(NodeKey::of(children[1]), module, env, calls)?;
            self.binary_short_circuit(key, calls, left, right)
        } else {
            self.binary_scalar(
                key,
                module,
                env,
                calls,
                op,
                &children,
                left,
                current_null_check,
                input_null_check || notice_snapshot_null_check,
                admitted_parent_comparison,
            )
        }
    }

    /// The original notice IF may test the nullable stored Contract snapshot
    /// for presence. This observes that exact Term field as control; it does
    /// not make an arbitrary nullable reference selectable or copyable.
    fn notice_snapshot_null_check(
        &self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        op: &str,
        children: &[&SyntaxNode],
    ) -> bool {
        let [snapshot, null] = children else { return false; };
        if op != "!=" || !calls.is_empty() || self.loop_node.is_some()
            || self.types.node_types.get(&NodeKey::of(null)) != Some(&ResolvedType::Null)
            || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Bool))
        { return false; }
        let snapshot = NodeKey::of(snapshot);
        let Some((receiver, "snapshot")) = self.count_member(snapshot) else { return false; };
        let Some((scenario, term_field)) = self.hook_delivery_field(receiver, module) else {
            return false;
        };
        let Some(owner) = self.effects.scenarios.get(&scenario) else { return false; };
        let Some(branch) = owner.effects.first() else { return false; };
        if owner.effects.len() != 1 || branch.verb != EffectVerb::If
            || branch.cond.is_none_or(|cond| cond.file != key.file
                || cond.start > key.start || key.end > cond.end)
        { return false; }
        let Some(ResolvedType::Record { symbol: term, stored: true }) =
            self.types.symbol_types.get(&term_field) else { return false; };
        let Some(SymbolKind::Model { fields, .. }) =
            self.resolve.symbols.get(term.0 as usize).map(|item| &item.kind) else { return false; };
        let mut snapshots = fields.iter().filter_map(|field|
            self.resolve.symbols.get(field.0 as usize)).filter(|field| field.name == "snapshot");
        let Some(field) = snapshots.next() else { return false; };
        let Some(ResolvedType::Nullable(inner)) = self.types.symbol_types.get(&field.id) else {
            return false;
        };
        let ResolvedType::Record { symbol: contract, .. } = inner.as_ref() else {
            return false;
        };
        snapshots.next().is_none()
            && self.types.node_types.get(&snapshot) == self.types.symbol_types.get(&field.id)
            && self.resolve.symbols.get(contract.0 as usize)
                .is_some_and(|contract| contract.canonical == "agreements.ExecutedParties"
                    && matches!(contract.kind, SymbolKind::Contract { .. }))
    }

    /// A binary's null checks: the current-Revision presence test, the
    /// first-query `let` absence primitive, and exact nullable input tests.
    fn binary_null_checks(
        &self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        op: &str,
        children: &[&SyntaxNode],
    ) -> (bool, bool, bool) {
        let current_null_check = op == "!="
            && calls.is_empty()
            && self
                .current_revision_at(key, module)
                .is_some_and(|fact| fact.presence == key);
        // Absence primitive (CAN18-v1 first-query slice): a null test on the
        // first-query let binding in EITHER direction (`!=null` presence or
        // `==null` absence) consumes only that binding's presence, never a
        // stored field. Field reads off the possibly-null binding keep the
        // AbsentReference refusal below, as do require-or/if-branch shapes
        // (their own slices, still refused at the terminal tail rule).
        let first_null_check = current_null_check || calls.is_empty() && self.nullable_field_if_branch(key,module).is_some_and(|(presence,..)|presence==key) || matches!(op, "==" | "!=") && calls.is_empty()
            && [(children[0], children[1]), (children[1], children[0])].iter().any(|(value, null)| {
                let key = NodeKey::of(value);
                self.types.node_types.get(&NodeKey::of(null)) == Some(&ResolvedType::Null)
                    && matches!(self.query_binding(key), Some(Binding::Let {node})
                        if env.get(&Local::Let(*node)).is_some_and(|value| {
                            value.record.is_some() && value.first_query.is_some_and(|(_, original)| original == *node)
                        }))
            });
        let input_null_check = matches!(op, "==" | "!=") && calls.is_empty()
            && [(children[0], children[1]), (children[1], children[0])].iter().any(|(value, null)| {
                let input = NodeKey::of(value);
                if self.types.node_types.get(&NodeKey::of(null)) != Some(&ResolvedType::Null) {
                    return false;
                }
                if value.kind == SyntaxKind::NameRef {
                    return matches!(self.query_binding(input), Some(Binding::Symbol(parameter))
                        if env.get(&Local::Symbol(*parameter)).is_some_and(|value| {
                            value.reference_origin == Some(ReferenceOrigin::NullableParameter(*parameter))
                                && value.record.is_some()
                        }));
                }
                // The original required row's one nullable stored-reference
                // field is observed as a control dependency at this getter.
                // A copied row, second hop, or reference value used elsewhere
                // still has no absence carrier.
                let Some((receiver, _)) = self.count_member(input) else {
                    return false;
                };
                let Some((parameter, _)) =
                    self.original_call_model_parameter(receiver, key, module)
                else {
                    return false;
                };
                // This absence bit may authorize the owning mutation only.
                // Returning or copying the nullable reference still needs a
                // separate result grant, which this profile does not issue.
                let mut owners = self.effects.scenarios.values().filter(|scenario| {
                    scenario.module == module
                        && scenario.node.file == key.file
                        && scenario.node.start <= key.start
                        && key.end <= scenario.node.end
                });
                let Some(owner) = owners.next() else {
                    return false;
                };
                if owners.next().is_some()
                    || !owner.guards.iter().any(|guard| {
                        guard.verb == EffectVerb::Require
                            && guard.cond.is_some_and(|condition| {
                                condition.file == key.file
                                    && condition.start <= key.start
                                    && key.end <= condition.end
                            })
                    })
                {
                    return false;
                }
                matches!(self.types.node_types.get(&input),
                    Some(ResolvedType::Nullable(inner))
                        if matches!(inner.as_ref(), ResolvedType::Record { stored: true, .. }))
                    && self.call_parameter_field(input, parameter).is_some()
                    && env.get(&Local::Symbol(parameter)).is_some_and(|value| {
                        value.reference_origin == Some(ReferenceOrigin::Parameter(parameter))
                            && value.record.is_some()
                    })
            });
        (current_null_check, first_null_check, input_null_check)
    }

    /// Whether a binary equality consumes checked containment: both
    /// operands name the same model with a parent hop on either side,
    /// or a stored-record field off an original required parameter
    /// against the same model's sealed operand.
    fn binary_parent_comparison(
        &self,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        op: &str,
        children: &[&SyntaxNode],
    ) -> bool {
        matches!(op, "==" | "!=") && calls.is_empty() && self.loop_node.is_none() && {
            let operand = |node: &SyntaxNode| -> Option<(SymbolId, bool)> {
                let key = self.query_group(NodeKey::of(node))?;
                if let Some((parameter,model))=self.narrowed_model_input(key,module) {
                    return env.contains_key(&Local::Symbol(parameter)).then_some((model,false));
                }
                if let Some((parameter, model, _)) =
                    self.checked_contract_input_reference(key, module)
                {
                    return env
                        .contains_key(&Local::Symbol(parameter))
                        .then_some((model, false));
                }
                if let Some((base, name))=self.count_member(key)
                    && let Some((_, operand, _, _, _, parent))=self.nullable_field_if_branch(base,module)
                    && operand==base
                    && let Some(field)=self.resolve.symbols.get(parent.0 as usize)?.fields_of().iter()
                        .filter_map(|field|self.resolve.symbols.get(field.0 as usize)).find(|field|field.name==name)
                    && let Some(ty)=self.types.symbol_types.get(&field.id)
                    && self.types.node_types.get(&key)==Some(ty)
                {
                    let model=match ty {
                        ResolvedType::Record{symbol,stored:true}=>Some(*symbol),
                        ResolvedType::Nullable(inner)=>match inner.as_ref(){ResolvedType::Record{symbol,stored:true}=>Some(*symbol),_=>None},
                        _=>None,
                    };
                    if let Some(model)=model{return Some((model,true));}
                }
                env.keys().find_map(|local| {
                    let Local::Symbol(parameter) = local else {
                        return None;
                    };
                    if let Some((model, hops)) =
                        self.checked_call_parent_path(key, *parameter, 0)
                    {
                        return Some((model, hops > 0));
                    }
                    // A stored-record field selected off an original
                    // required record parameter names its own model with
                    // the same sealed provenance as the bare parameter.
                    self.call_parameter_field(key, *parameter)
                        .map(|model| (model, true))
                })
            };
            matches!((operand(children[0]), operand(children[1])),
                (Some((left_model, left_parent)), Some((right_model, right_parent)))
                if left_model == right_model && (left_parent || right_parent))
        }
    }

    /// Short-circuit `and`/`or`/`??`: skipped and evaluated right-hand
    /// paths under compatible decisions.
    fn binary_short_circuit(
        &mut self,
        key: NodeKey,
        calls: &[NodeKey],
        left: Vec<ValuePath>,
        right: Vec<ValuePath>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if left.len().saturating_mul(right.len().saturating_add(1)) > 1024 {
            return Err(self.fail(key, "short-circuit path bound"));
        }
        let mut out = Vec::new();
        for lhs in left {
            let mut skipped = lhs.clone();
            skipped.join(&self.control(lhs.clone())?);
            skipped.decisions.push(DisclosureDecision {
                node: key,
                calls: calls.to_vec(),
                choice: DisclosureChoice::RhsSkipped,
            });
            out.push(skipped);
            for rhs in &right {
                if !compatible(&lhs.decisions, &rhs.decisions) {
                    continue;
                }
                let mut selected = lhs.clone();
                selected.join(&self.control(lhs.clone())?);
                selected.decisions.push(DisclosureDecision {
                    node: key,
                    calls: calls.to_vec(),
                    choice: DisclosureChoice::RhsEvaluated,
                });
                selected.join(rhs);
                selected.record = None;
                selected.reference = None;
                out.push(selected);
            }
        }
        self.bounded(key, out)
    }

    /// A literal-array membership shape: a non-empty `[...]` of literals
    /// or enum cases compared for a boolean result. Query calls, member
    /// reads and other computed arrays keep the refusal.
    fn binary_membership_shape(
        &self,
        key: NodeKey,
        children: &[&SyntaxNode],
    ) -> Option<()> {
        let [left, right] = children else {
            return None;
        };
        let array = self.query_group(NodeKey::of(right))?;
        let node = self.nodes.get(&array)?;
        if node.kind != SyntaxKind::Array {
            return None;
        }
        let mut elements = node
            .children
            .iter()
            .filter(|child| expression(child.kind))
            .peekable();
        if elements.peek().is_none() {
            return None;
        }
        for element in elements {
            let element = self.query_group(NodeKey::of(element))?;
            let literal = self
                .nodes
                .get(&element)
                .is_some_and(|node| node.kind == SyntaxKind::Literal);
            if !literal && !self.types.resolved_cases.contains(&element) {
                return None;
            }
        }
        (self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Bool))
            && self.types.node_types.get(&NodeKey::of(left)).is_some())
        .then_some(())
    }

    /// A scalar binary: checked operator, admitted operands and the
    /// transcript/count refinements.
    #[allow(clippy::too_many_arguments)]
    fn binary_scalar(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        op: &str,
        children: &[&SyntaxNode],
        left: Vec<ValuePath>,
        current_null_check: bool,
        input_null_check: bool,
        admitted_parent_comparison: bool,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if !matches!(
            op,
            "+" | "-" | "*" | "/" | "%" | "==" | "!=" | "<" | "<=" | ">" | ">="
        ) {
            // `member in [literal|cases]`: the array contributes no reads;
            // the product below joins the member read like any other
            // comparison. Anything else keeps the refusal.
            if op != "in" || self.binary_membership_shape(key, children).is_none() {
                return Err(self.fail(key, "unsupported scalar operator"));
            }
        }
        let right = self.expr(NodeKey::of(children[1]), module, env, calls)?;
        if !admitted_parent_comparison
            && right.iter().any(|value| {
                matches!(
                    value.reference_origin,
                    Some(ReferenceOrigin::Parent { .. } | ReferenceOrigin::Field { .. })
                )
            })
        {
            return Err(self.fail(
                key,
                "stored reference operand needs direct child or count consumer",
            ));
        }
        let mut values = self.product(key, &left, &right)?;
        if current_null_check || input_null_check || admitted_parent_comparison {
            for value in &mut values {
                value.reference_origin = None;
                value.reference = None;
                value.record = None;
                value.current_revision = None;
            }
        }
        self.binary_transcript(key, op, children, &left, &right, &mut values);
        // Only this original cardinality guard retains query/prefix
        // controls on a scalar Return; other authorization pruning stays.
        if op == "<"
            && left.iter().all(|value| value.transcript_count)
            && self.transcript_bound_matches(NodeKey::of(children[1]), &left)
        {
            for value in &mut values {
                value.transcript_count = true;
            }
        }
        Ok(values)
    }

    /// A `+` over transcript message arrays concatenates: mark the
    /// values when both operands are message arrays with a message.
    fn binary_transcript(
        &self,
        key: NodeKey,
        op: &str,
        children: &[&SyntaxNode],
        left: &[ValuePath],
        right: &[ValuePath],
        values: &mut Vec<ValuePath>,
    ) {
        if op != "+" {
            return;
        }
        if !self
            .types
            .node_types
            .get(&key)
            .is_some_and(transcript_message_array)
        {
            return;
        }
        let operand = |node: &SyntaxNode, paths: &[ValuePath]| {
            let original = self
                .query_group(NodeKey::of(node))
                .unwrap_or(NodeKey::of(node));
            self.types
                .node_types
                .get(&NodeKey::of(node))
                .is_some_and(transcript_message_array)
                && (self
                    .nodes
                    .get(&original)
                    .is_some_and(|node| node.kind == SyntaxKind::Array)
                    || paths
                        .iter()
                        .all(|value| value.transcript_messages == Some(original)))
        };
        if operand(children[0], left)
            && operand(children[1], right)
            && left
                .iter()
                .chain(right)
                .any(|value| value.transcript_messages.is_some())
        {
            for value in values {
                value.transcript_messages = Some(key);
            }
        }
    }
    fn bounded(
        &self,
        key: NodeKey,
        paths: Vec<ValuePath>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if paths.len() > 1024 {
            Err(self.fail(key, "evaluation path bound"))
        } else {
            Ok(paths)
        }
    }

    fn product(
        &self,
        key: NodeKey,
        left: &[ValuePath],
        right: &[ValuePath],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if left.len().saturating_mul(right.len()) > 1024 {
            return Err(self.fail(key, "evaluation path bound"));
        }
        let mut out = Vec::new();
        for lhs in left {
            for rhs in right {
                // A referenced immutable alias carries its already selected path.
                // Contradictory selections cannot occur in one execution.
                if !compatible(&lhs.decisions, &rhs.decisions) {
                    continue;
                }
                let mut merged = lhs.clone();
                merged.join(rhs);
                merged.record = None;
                merged.reference = None;
                merged.input = None;
                merged.contract_value = None;
                merged.transcript_messages = None;
                merged.transcript_count = false;
                merged.current_revision = None;
                out.push(merged);
            }
        }
        Ok(out)
    }

    fn checked_membership_signature(&self, key: NodeKey, module: ModuleId) -> Option<()> {
        let catalog = self.catalog?;
        let selected = self.types.selected_calls.get(&key)?;
        let signature = catalog.overloads("active_member")?.first()?;
        if !matches!(&selected.target,
            SelectedCallTarget::Builtin {id,overload:0} if id == "active_member")
            || catalog.effects("active_member") != Some(Effects::StateRead)
            || selected.arguments.len() != 2
            || selected.slots.as_slice() != [Some(0), Some(1)]
            || signature.params.len() != 2
            || signature.result != SigType::Named("bool".into())
            || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Bool))
        {
            return None;
        }
        if !self.membership_params_ok(signature, selected) {
            return None;
        }
        let node = self.nodes.get(&key)?;
        let arguments = self.membership_call_args(node)?;
        let head = node.children.iter().find(|child| expression(child.kind))?;
        (node.kind == SyntaxKind::Call
            && arguments == selected.arguments
            && matches!(self.query_binding(NodeKey::of(head)),
                Some(Binding::Builtin {id}) if id == "active_member")
            && self.source(module, key).is_ok())
        .then_some(())
    }

    /// Whether an `active_member` call's parameters match the catalog
    /// signature with correctly typed arguments.
    fn membership_params_ok(
        &self,
        signature: &super::catalog::SigOverload,
        selected: &super::types::SelectedCall,
    ) -> bool {
        for (parameter, (name, declared, ty)) in signature.params.iter().zip([
            ("person", "user", ResolvedType::Scalar(Scalar::User)),
            ("team", "Team", ResolvedType::Team),
        ]) {
            if parameter.name != name
                || parameter.ty != SigType::Named(declared.into())
                || parameter.alias.is_some()
                || parameter.in_scope.is_some()
            {
                return false;
            }
            let index = usize::from(name == "team");
            if self.types.node_types.get(&selected.arguments[index]) != Some(&ty) {
                return false;
            }
        }
        true
    }

    /// The single-expression argument values of a membership call node.
    fn membership_call_args(&self, node: &SyntaxNode) -> Option<Vec<NodeKey>> {
        node.children
            .iter()
            .filter(|child| child.kind == SyntaxKind::Argument)
            .map(|argument| {
                let mut values = argument
                    .children
                    .iter()
                    .filter(|child| expression(child.kind));
                let value = NodeKey::of(values.next()?);
                values.next().is_none().then_some(value)
            })
            .collect::<Option<Vec<_>>>()
    }

    /// Only the original leading authorization helper consumes this parent.
    /// The checked formal observes the same row; it is never a new admitted input.
    fn authorization_declaration_identity(
        &self,
        id: SymbolId,
        declaration: &Symbol,
        declaration_name: &SyntaxNode,
        declaration_path: &SyntaxNode,
        defining_module: ModuleId,
        data: &super::effects::DeriveData,
        params: &[SymbolId],
        result_node: NodeKey,
        result: NodeKey,
    ) -> Option<()> {
        if declaration.id != id
            || self.word(declaration_name) != Some(declaration.name.as_str())
            || declaration_path.span != declaration.span
            || declaration.canonical
                != format!(
                    "{}.{}",
                    self.resolve.modules.get(defining_module.0 as usize)?.name,
                    declaration.name
                )
            || data.derive != id
            || data.module != defining_module
            || data.model.is_some()
            // Resolver retains this declaration sentinel; effects owns the
            // actual authored result type child, checked independently below.
            || result_node != data.node
            || !self.nodes.get(&data.node)?.children.iter().any(|child| NodeKey::of(child) == result)
            || self.types.symbol_results.get(&id) != Some(&Some(ResolvedType::Scalar(Scalar::Bool)))
            || data.params.len() != 2
            || !params
                .iter()
                .copied()
                .eq(data.params.iter().map(|parameter| parameter.param))
            || data
                .params
                .iter()
                .any(|parameter| parameter.default.is_some())
        {
            return None;
        }
        Some(())
    }

    fn authorization_declaration_types(
        &self,
        selected: &super::types::SelectedCall,
        key: NodeKey,
        body: NodeKey,
        text: &str,
        person: &super::effects::ParamData,
        formal: &super::effects::ParamData,
        result: NodeKey,
        owner: &Symbol,
        model: SymbolId,
        defining_module: ModuleId,
        data: &super::effects::DeriveData,
    ) -> Option<()> {
        if selected.arguments.len() != 2
            || selected.slots.as_slice() != [Some(0), Some(1)]
            || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.node_types.get(&body) != Some(&ResolvedType::Scalar(Scalar::Bool))
            || self.types.symbol_types.get(&person.param)
                != Some(&ResolvedType::Nullable(Box::new(ResolvedType::Scalar(
                    Scalar::User,
                ))))
            || text
                .get(person.type_node.start as usize..person.type_node.end as usize)?
                .trim()
                != "user?"
            || text
                .get(formal.type_node.start as usize..formal.type_node.end as usize)?
                .trim()
                != owner.name
            || text
                .get(result.start as usize..result.end as usize)?
                .trim()
                != "bool"
            || owner.module != defining_module
            || self.checked_created_model(model, defining_module).is_none()
            || self.source(defining_module, data.node).ok()? != self.source(defining_module, body).ok()?
        {
            return None;
        }
        Some(())
    }

    fn authorization_derive_params(
        &self,
        id: SymbolId,
        data: &super::effects::DeriveData,
        declaration: &Symbol,
        defining_module: ModuleId,
    ) -> Option<()> {
        for (index, parameter) in data.params.iter().enumerate() {
            let symbol = self.resolve.symbols.get(parameter.param.0 as usize)?;
            if !matches!(symbol.kind,SymbolKind::Param {owner,index:actual,type_node} if owner == id && actual == index && type_node == parameter.type_node)
                || symbol.module != defining_module
                || symbol.id != parameter.param
                || symbol.canonical != format!("{}.{}", declaration.canonical, symbol.name)
                || self
                    .nodes
                    .get(&parameter.node)?
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Name)
                    .is_none_or(|name| {
                        self.word(name) != Some(symbol.name.as_str()) || name.span != symbol.span
                    })
            {
                return None;
            }
        }
        Some(())
    }

    fn authorization_import_guard(
        &self,
        imported: bool,
        module: ModuleId,
        id: SymbolId,
        model: SymbolId,
        head: &SyntaxNode,
        declaration: &Symbol,
        owner: &Symbol,
    ) -> Option<()> {
        // Imported authorization keeps the actual exported helper/Conversation
        // identities for optional inputs and required containment paths.
        // Local parent cases retain their original source checks.
        if imported
            && (head.kind != SyntaxKind::NameRef
                || !declaration.exported
                || !owner.exported
                || !matches!(self.resolve.module_scopes.get(module.0 as usize)?.prod.get(self.word(head)?),
                    Some(ScopedName::Imported {target, bound: false}) if *target == id)
                || !self.resolve.module_scopes.get(module.0 as usize)?.prod.values().any(|name|
                    matches!(name, ScopedName::Imported {target, bound: false} if *target == model)))
        {
            return None;
        }
        Some(())
    }

    fn authorization_call_shape_ok(
        &self,
        call: &SyntaxNode,
        head: &SyntaxNode,
        actor: NodeKey,
        arguments: &[NodeKey],
        selected: &super::types::SelectedCall,
        id: SymbolId,
        formal_ty: Option<&ResolvedType>,
    ) -> Option<NodeKey> {
        let parent = selected.arguments[1];
        if call.kind != SyntaxKind::Call || arguments != selected.arguments
            || !matches!(self.query_binding(NodeKey::of(head)),Some(Binding::Symbol(actual)) if *actual == id)
            || self.nodes.get(&actor)?.kind != SyntaxKind::NameRef
            || self.word(self.nodes.get(&actor)?)? != "actor"
            || !matches!(self.query_binding(actor),Some(Binding::Context(ContextVar::Actor(_))))
            || !matches!(self.types.node_types.get(&actor),
                Some(ResolvedType::Scalar(Scalar::User)) | Some(ResolvedType::Nullable(_)))
            || self.types.node_types.get(&actor).is_some_and(|ty| {
                matches!(ty,ResolvedType::Nullable(inner) if inner.as_ref() != &ResolvedType::Scalar(Scalar::User))
            })
            || self.types.node_types.get(&parent) != formal_ty
        { return None; }
        Some(parent)
    }

    fn authorization_imported_caller(
        &self,
        key: NodeKey,
        module: ModuleId,
        receiver: NodeKey,
        parameter: SymbolId,
    ) -> Option<(
        SymbolId,
        &'a super::effects::ScenarioData,
        &'a super::effects::ParamData,
    )> {
        // Only the original caller parameter can supply either the already
        // admitted optional input or one/two genuine imported parent edges.
        let parameter_symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param {
            owner: caller,
            index,
            type_node,
        } = parameter_symbol.kind
        else {
            return None;
        };
        let scenario = self.effects.scenarios.get(&caller)?;
        let mut parameters = scenario
            .params
            .iter()
            .filter(|param| param.param == parameter);
        let parameter_data = parameters.next()?;
        if self.nodes.get(&receiver)?.kind != SyntaxKind::NameRef
            || parameters.next().is_some()
            || scenario.params.get(index)?.param != parameter
            || type_node != parameter_data.type_node
            || parameter_symbol.module != module
            || scenario.module != module
            || scenario.read
            || scenario.on.is_some()
            || scenario.cohort.is_some()
            || key.file != scenario.node.file
            || key.start < scenario.node.start
            || key.end > scenario.node.end
        {
            return None;
        }
        Some((caller, scenario, parameter_data))
    }

    fn authorization_imported_path(
        &self,
        key: NodeKey,
        module: ModuleId,
        defining_module: ModuleId,
        parent: NodeKey,
        parameter: SymbolId,
        model: SymbolId,
        hops: u8,
        receiver: NodeKey,
        parameter_data: &super::effects::ParamData,
    ) -> Option<()> {
        let ResolvedType::Record {
            symbol: root,
            stored: true,
        } = self.types.symbol_types.get(&parameter)?
        else {
            return None;
        };
        let root_declaration = self.resolve.symbols.get(root.0 as usize)?;
        let annotation = self.nodes.get(&parameter_data.type_node)?;
        if !matches!(hops, 1 | 2)
            || parameter_data.default.is_some()
            || self.checked_call_parent_path(parent, parameter, 0) != Some((model, hops))
            || root_declaration.module != defining_module
            || !root_declaration.exported
            || annotation.kind != SyntaxKind::NamedType
            || !matches!(self.resolve.module_scopes.get(module.0 as usize)?.prod.get(self.word(annotation)?),
                Some(ScopedName::Imported {target, bound: false}) if target == root)
            || self.checked_created_model(*root, defining_module).is_none()
        {
            return None;
        }
        // Seal both source declarations on the checked containment
        // path, rather than treating a carried type as an imported row.
        let mut edge = parent;
        for _ in 0..hops {
            let (base, name) = self.count_member(edge)?;
            let ResolvedType::Record {
                symbol: child,
                stored: true,
            } = self.types.node_types.get(&base)?
            else {
                return None;
            };
            if name != "parent"
                || self.resolve.symbols.get(child.0 as usize)?.module != defining_module
                || self
                    .checked_created_model(*child, defining_module)
                    .is_none()
            {
                return None;
            }
            edge = base;
        }
        if edge != receiver {
            return None;
        }
        Some(())
    }

    fn authorization_caller_owner(
        &self,
        key: NodeKey,
        module: ModuleId,
        defining_module: ModuleId,
        parent: NodeKey,
        model: SymbolId,
        imported: bool,
    ) -> Option<Option<SymbolId>> {
        // Retain the original required parameter across exactly one or two
        // authored containment edges; neither an alias nor a declared field
        // named parent can stand in for the checked ChildOf lineage.
        let mut receiver = parent;
        let mut hops = 0;
        while let Some((base, field)) = self.count_member(receiver) {
            if field != "parent" || hops == 2 {
                return None;
            }
            receiver = base;
            hops += 1;
        }
        let Some(Binding::Symbol(parameter)) = self.query_binding(receiver) else {
            return None;
        };
        if imported {
            let (caller, scenario, parameter_data) =
                self.authorization_imported_caller(key, module, receiver, *parameter)?;
            if hops == 0 {
                if parent != receiver
                    || self.nullable_model_input(scenario, parameter_data) != Some(model)
                {
                    return None;
                }
            } else {
                self.authorization_imported_path(
                    key,
                    module,
                    defining_module,
                    parent,
                    *parameter,
                    model,
                    hops,
                    receiver,
                    parameter_data,
                )?;
            }
            Some(Some(caller))
        } else {
            if !matches!(hops, 1 | 2)
                || self.checked_call_parent_path(parent, *parameter, 0) != Some((model, hops))
            {
                return None;
            }
            Some(None)
        }
    }

    fn authorization_formal_name(
        &self,
        node: NodeKey,
        parameter: SymbolId,
        ty: &ResolvedType,
    ) -> bool {
        self.nodes
            .get(&node)
            .is_some_and(|node| node.kind == SyntaxKind::NameRef)
            && matches!(self.query_binding(node),Some(Binding::Symbol(actual)) if *actual == parameter)
            && self.types.node_types.get(&node) == Some(ty)
    }

    fn authorization_formal_member(
        &self,
        node: NodeKey,
        name: &str,
        ty: &ResolvedType,
        formal_param: SymbolId,
        model: SymbolId,
        owner: &Symbol,
    ) -> bool {
        self.count_member(node).is_some_and(|(base, field)| {
            field == name && self.authorization_formal_name(base,formal_param,&ResolvedType::Record {symbol:model,stored:true})
                && self.types.node_types.get(&node) == Some(ty)
                && matches!(&owner.kind,SymbolKind::Model {fields,..} if fields.iter().any(|field| {
                    self.resolve.symbols.get(field.0 as usize).is_some_and(|field| field.name == name
                        && matches!(field.kind,SymbolKind::Field {owner,..} if owner == model)
                        && self.types.symbol_types.get(&field.id) == Some(ty))
                }))
        })
    }

    fn authorization_body_shape(
        &self,
        body: NodeKey,
    ) -> Option<(NodeKey, NodeKey, NodeKey, NodeKey, NodeKey, NodeKey)> {
        let (first_three, active) = self.query_binary(body, "and")?;
        let (first_two, equality) = self.query_binary(first_three, "and")?;
        let (null_guard, membership) = self.query_binary(first_two, "and")?;
        let (subject, absent) = self.query_binary(null_guard, "!=")?;
        let (account, compared) = self.query_binary(equality, "==")?;
        Some((active, membership, subject, absent, account, compared))
    }

    fn authorization_body_ok(
        &self,
        membership: NodeKey,
        defining_module: ModuleId,
        subject: NodeKey,
        absent: NodeKey,
        account: NodeKey,
        compared: NodeKey,
        active: NodeKey,
        person: &super::effects::ParamData,
        formal_param: SymbolId,
        model: SymbolId,
        owner: &Symbol,
    ) -> Option<()> {
        self.checked_membership_signature(membership, defining_module)?;
        let membership_call = self.types.selected_calls.get(&membership)?;
        if !self.authorization_formal_name(
            subject,
            person.param,
            self.types.symbol_types.get(&person.param)?,
        ) || self.nodes.get(&absent)?.kind != SyntaxKind::Literal
            || self.types.node_types.get(&absent) != Some(&ResolvedType::Null)
            || !self.authorization_formal_name(compared, person.param, &ResolvedType::Scalar(Scalar::User))
            || !self.authorization_formal_member(account, "account", &ResolvedType::Scalar(Scalar::User), formal_param, model, owner)
            || !self.authorization_formal_member(active, "active", &ResolvedType::Scalar(Scalar::Bool), formal_param, model, owner)
            || !self.authorization_formal_name(
                membership_call.arguments[0],
                person.param,
                &ResolvedType::Scalar(Scalar::User),
            )
            || self.nodes.get(&membership_call.arguments[1])?.kind != SyntaxKind::NameRef
            || self.word(self.nodes.get(&membership_call.arguments[1])?)? != "team"
            || !matches!(
                self.query_binding(membership_call.arguments[1]),
                Some(Binding::Context(ContextVar::Team))
            )
        {
            return None;
        }
        Some(())
    }

    fn authorization_call_site(
        &self,
        key: NodeKey,
        module: ModuleId,
        defining_module: ModuleId,
        membership: NodeKey,
        id: SymbolId,
        selected: &super::types::SelectedCall,
        imported_owner: Option<SymbolId>,
    ) -> Option<()> {
        let mut sites = self
            .effects
            .scenarios
            .values()
            .filter(|scenario| scenario.module == module)
            .filter_map(|scenario| self.checked_decision_sites(scenario))
            .flatten()
            .filter(|site| {
                site.stage == CheckedDecisionStage::LeadingRequire
                    && site.calls.iter().any(|call| {
                        call.node == key
                            && call.chain.is_empty()
                            && call.target == CheckedDecisionCallTarget::DeriveFn(id)
                            && call
                                .arguments
                                .iter()
                                .map(|(node, _)| *node)
                                .eq(selected.arguments.iter().copied())
                            && call.slots == selected.slots
                            && call.defaults.is_empty()
                    })
            });
        let site = sites.next()?;
        let original_source = self.source(module, key).ok()?;
        let membership_source = self.source(defining_module, membership).ok()?;
        if sites.next().is_some()
            || site.source != original_source
            || imported_owner.is_some_and(|owner| site.owner != owner)
            || !site.calls.iter().any(|call| {
                call.node == membership
                    && call.module == defining_module
                    && call.source == membership_source
                    && call.target
                        == CheckedDecisionCallTarget::Builtin {
                            id: "active_member".into(),
                            overload: 0,
                        }
                    && call.defaults.is_empty()
                    && call.chain.len() == 1
                    && call.chain[0].node == key
                    && call.chain[0].derive == id
                    && call.chain[0].module == module
                    && call.chain[0].source == original_source
            })
        {
            return None;
        }
        Some(())
    }

    fn authorization_derive_tail(
        &self,
        key: NodeKey,
        module: ModuleId,
        defining_module: ModuleId,
        id: SymbolId,
        model: SymbolId,
        parent: NodeKey,
        body: NodeKey,
        person: &super::effects::ParamData,
        formal_param: SymbolId,
        owner: &Symbol,
        selected: &super::types::SelectedCall,
        imported_owner: Option<SymbolId>,
    ) -> Option<(SymbolId, SymbolId, NodeKey, NodeKey)> {
        let (active, membership, subject, absent, account, compared) =
            self.authorization_body_shape(body)?;
        self.authorization_body_ok(
            membership,
            defining_module,
            subject,
            absent,
            account,
            compared,
            active,
            person,
            formal_param,
            model,
            owner,
        )?;
        self.authorization_call_site(
            key,
            module,
            defining_module,
            membership,
            id,
            selected,
            imported_owner,
        )?;
        Some((id, model, parent, membership))
    }

    fn authorization_derive_call_stage(
        &self,
        key: NodeKey,
        module: ModuleId,
        defining_module: ModuleId,
        id: SymbolId,
        model: SymbolId,
        imported: bool,
        declaration: &Symbol,
        owner: &Symbol,
        selected: &super::types::SelectedCall,
        formal: &super::effects::ParamData,
        person: &super::effects::ParamData,
        body: NodeKey,
    ) -> Option<(SymbolId, SymbolId, NodeKey, NodeKey)> {
        let call = self.nodes.get(&key)?;
        let head = call.children.iter().find(|child| expression(child.kind))?;
        let arguments: Vec<_> = call
            .children
            .iter()
            .filter(|child| child.kind == SyntaxKind::Argument)
            .map(|argument| {
                let mut values = argument
                    .children
                    .iter()
                    .filter(|child| expression(child.kind));
                let value = NodeKey::of(values.next()?);
                values.next().is_none().then_some(value)
            })
            .collect::<Option<Vec<_>>>()?;
        self.authorization_import_guard(imported, module, id, model, head, declaration, owner)?;
        let actor = selected.arguments[0];
        let parent = self.authorization_call_shape_ok(
            call,
            head,
            actor,
            &arguments,
            selected,
            id,
            self.types.symbol_types.get(&formal.param),
        )?;
        let imported_owner =
            self.authorization_caller_owner(key, module, defining_module, parent, model, imported)?;
        self.authorization_derive_tail(
            key,
            module,
            defining_module,
            id,
            model,
            parent,
            body,
            person,
            formal.param,
            owner,
            selected,
            imported_owner,
        )
    }

    fn checked_authorization_derive(
        &self,
        key: NodeKey,
        module: ModuleId,
    ) -> Option<(SymbolId, SymbolId, NodeKey, NodeKey)> {
        let selected = self.types.selected_calls.get(&key)?;
        let SelectedCallTarget::DeriveFn(id) = &selected.target else {
            return None;
        };
        let id = *id;
        let data = self.effects.derives.get(&id)?;
        let declaration = self.resolve.symbols.get(id.0 as usize)?;
        let defining_module = declaration.module;
        let imported = defining_module != module;
        let SymbolKind::DeriveFn {
            params,
            result_node,
        } = &declaration.kind
        else {
            return None;
        };
        let body = data.expr?;
        let result = data.result?;
        let text = &self.db.get(data.node.file)?.text;
        let formal = data.params.get(1)?;
        let person = data.params.first()?;
        let ResolvedType::Record {
            symbol: model,
            stored: true,
        } = self.types.symbol_types.get(&formal.param)?
        else {
            return None;
        };
        let model = *model;
        let owner = self.resolve.symbols.get(model.0 as usize)?;
        let declaration_path = self
            .nodes
            .get(&data.node)?
            .children
            .iter()
            .find(|node| node.kind == SyntaxKind::Path)?;
        let declaration_name = declaration_path
            .children
            .iter()
            .find(|node| node.kind == SyntaxKind::Name)?;
        self.authorization_declaration_identity(
            id,
            declaration,
            declaration_name,
            declaration_path,
            defining_module,
            data,
            params,
            *result_node,
            result,
        )?;
        self.authorization_declaration_types(
            selected,
            key,
            body,
            text,
            person,
            formal,
            result,
            owner,
            model,
            defining_module,
            data,
        )?;
        self.authorization_derive_params(id, data, declaration, defining_module)?;
        self.authorization_derive_call_stage(
            key,
            module,
            defining_module,
            id,
            model,
            imported,
            declaration,
            owner,
            selected,
            formal,
            person,
            body,
        )
    }

    /// These original leading guards consume an admitted value's text or
    /// cardinality only. They supply no stored-row or File authority.
    fn checked_pure_input_guard(&self, key: NodeKey, module: ModuleId) -> Option<NodeKey> {
        if !self.authorization || self.statement_depth != 1 || self.loop_node.is_some() {
            return None;
        }
        let selected = self.types.selected_calls.get(&key)?;
        let SelectedCallTarget::Builtin { id, overload: 0 } = &selected.target else {
            return None;
        };
        if !matches!(id.as_str(), "trim" | "count") || selected.slots.as_slice() != [Some(0)] {
            return None;
        }
        let [argument] = selected.arguments.as_slice() else {
            return None;
        };
        let catalog = self.catalog?;
        let signature = catalog.overloads(id)?.first()?;
        let [input] = signature.params.as_slice() else {
            return None;
        };
        let (name, input_type, result) = if id == "trim" {
            ("value", SigType::StringLike, Scalar::Text)
        } else {
            (
                "domain",
                SigType::Collection(Box::new(SigType::Any)),
                Scalar::Int,
            )
        };
        if catalog.effects(id) != Some(Effects::Pure)
            || input.name != name
            || input.ty != input_type
            || input.alias.is_some()
            || input.in_scope.is_some()
            || signature.result != SigType::Named(result.as_str().into())
            || self.types.node_types.get(&key) != Some(&ResolvedType::Scalar(result))
        {
            return None;
        }
        let node = self.nodes.get(&key)?;
        let head = node.children.iter().find(|child| expression(child.kind))?;
        let mut authored = node
            .children
            .iter()
            .filter(|child| child.kind == SyntaxKind::Argument);
        let source_argument = authored.next()?;
        let mut values = source_argument
            .children
            .iter()
            .filter(|child| expression(child.kind));
        if node.kind != SyntaxKind::Call
            || authored.next().is_some()
            || NodeKey::of(values.next()?) != *argument
            || values.next().is_some()
            || !matches!(self.query_binding(NodeKey::of(head)),Some(Binding::Builtin {id: actual}) if actual == id)
            || self.word(head)? != id
        {
            return None;
        }
        let operand = self.nodes.get(argument)?;
        let Some(Binding::Symbol(parameter)) = self.query_binding(*argument) else {
            return None;
        };
        let symbol = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param {
            owner,
            index,
            type_node,
        } = symbol.kind
        else {
            return None;
        };
        let scenario = self.effects.scenarios.get(&owner)?;
        let declaration = scenario.params.get(index)?;
        let by = scenario.by?;
        if operand.kind != SyntaxKind::NameRef
            || self.word(operand)? != symbol.name
            || symbol.id != *parameter
            || symbol.module != module
            || scenario.module != module
            || scenario.read
            || scenario.on.is_some()
            || scenario.cohort.is_some()
            || declaration.param != *parameter
            || declaration.type_node != type_node
            || !matches!(self.query_binding(by), Some(Binding::Predicate))
            || self
                .db
                .get(by.file)?
                .text
                .get(by.start as usize..by.end as usize)?
                .trim()
                != "members"
            || !scenario.guards.iter().any(|guard| {
                guard.verb == EffectVerb::Require
                    && guard.node.file == key.file
                    && guard.node.start <= key.start
                    && key.end <= guard.node.end
            })
            || self.types.node_types.get(argument) != self.types.symbol_types.get(parameter)
            || self.source(module, key).is_err()
        {
            return None;
        }
        if id == "trim" {
            if declaration.default.is_some()
                || self.types.node_types.get(argument) != Some(&ResolvedType::Scalar(Scalar::Text))
            {
                return None;
            }
        } else if !self.explicit_file_array_call_parameter(declaration) {
            return None;
        }
        Some(*argument)
    }

    fn literal_format_arguments(&self, arguments: &[NodeKey], slots: &[Option<usize>]) -> Option<()> {
        if arguments.len() != 2 || slots.len() != 2 || slots[0] == slots[1] { return None; }
        let descriptor = self.query_group(*arguments.get(slots[0]?)?)?;
        let value = self.query_group(*arguments.get(slots[1]?)?)?;
        let value_ty = self.types.node_types.get(&value)?;
        let message = (self.literal_message_descriptor(descriptor)
            || self.static_named_message_descriptor(descriptor).is_some())
            && matches!(value_ty, ResolvedType::Null | ResolvedType::Scalar(Scalar::Locale));
        // Both format overloads consume their ordinary checked arguments.
        // A literal template adds no data or reference authority of its own.
        let plain = self.catalog.and_then(|catalog| catalog.effects("format")) == Some(Effects::Pure)
            && self.types.node_types.get(&descriptor) == Some(&ResolvedType::Scalar(Scalar::Text))
            && self.nodes.get(&descriptor).is_some_and(|node| node.kind == SyntaxKind::Literal)
            && self.nodes.get(&value).is_some_and(|node| node.kind == SyntaxKind::Object)
            && matches!(value_ty, ResolvedType::Object(fields) if fields.len() <= 200
                && fields.iter().all(|(_,ty)| matches!(ty, ResolvedType::Scalar(scalar) if scalar.is_display())
                    || matches!(ty, ResolvedType::Enum {cases,..} if !cases.is_empty())));
        (message || plain).then_some(())
    }

    fn settled_scalar_call(&self, id: &str, arguments: &[NodeKey], slots: &[Option<usize>]) -> bool {
        (matches!(id, "date" | "datetime" | "money" | "abs" | "round" | "min" | "max" | "trim" | "starts_with")
            || id == "format" && self.literal_format_arguments(arguments, slots).is_some()
            || id == "local_date" && self.catalog.and_then(|catalog| catalog.effects(id)) == Some(Effects::Pure)
                && slots == [Some(0), Some(1)] && arguments.len() == 2
                && self.types.node_types.get(&arguments[0]) == Some(&ResolvedType::Scalar(Scalar::Datetime))
                && self.types.node_types.get(&arguments[1]) == Some(&ResolvedType::Scalar(Scalar::Timezone)))
            && slots.iter().all(Option::is_some)
    }

    fn call(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        let selected = self
            .types
            .selected_calls
            .get(&key)
            .ok_or_else(|| self.fail(key, "missing checked call selection"))?
            .clone();
        if let Some(paths) = self.call_origin_source_blocks(key, module, env, calls, &selected)? {
            return Ok(paths);
        }
        // Outbound Notice presentation is independently owned by its exact
        // audit sink profile. This publishes no ordinary formatted-field grant.
        if calls.is_empty() && self.loop_node.is_none()
            && matches!(&selected.target,SelectedCallTarget::Builtin {id,..} if id=="format")
            && self.effects.scenarios.values().any(|scenario|
                scenario.module==module && self.resolve.symbols.get(scenario.scenario.0 as usize)
                    .is_some_and(|symbol|symbol.canonical=="events.attendee_notice")
                && self.hook_delivery_event(scenario).is_some()
                && scenario.effects.iter().take(2).any(|effect|effect.value==Some(key)))
        { return Ok(vec![ValuePath::default()]); }
        // Nongrant closure for the exact post-write purchase ALL occurrence.
        // Its source/IR profile and complete staged domains are mandatory in
        // native receipt collection and execution; generic ALL remains refused.
        if calls.is_empty() && self.loop_node.is_none()
            && matches!(&selected.target, SelectedCallTarget::Builtin { id, overload: 0 } if id == "all")
            && self.effects.scenarios.values().any(|scenario| {
                scenario.module == module && self.resolve.symbols.get(scenario.scenario.0 as usize)
                    .is_some_and(|symbol| matches!(symbol.canonical.as_str(), "purchase.receive" | "CanPurchase.receive"))
                    && scenario.effects.get(6).and_then(|effect| effect.cond) == Some(key)
            })
            && self.db.get(key.file).and_then(|file| file.text.get(key.start as usize..key.end as usize))
                .is_some_and(|text| text.trim() == "all(line.parent.Line as item,item.accepted==item.ordered)")
        { return Ok(vec![ValuePath::default()]); }
        if let Some(paths) = self.call_count_source_blocks(key, module, env, calls, &selected)? {
            return Ok(paths);
        }
        if let Some(paths) = self.call_child_source_blocks(key, module, env, calls)? {
            return Ok(paths);
        }
        let authorization = (self.authorization && calls.is_empty() && self.loop_node.is_none())
            .then(|| self.checked_authorization_derive(key, module))
            .flatten();
        let mut helper_reference_reads = HashSet::new();
        let argument_paths = self.evaluate_call_arguments(
            key,
            module,
            env,
            calls,
            &selected,
            authorization,
            &mut helper_reference_reads,
        )?;
        self.dispatch_call_target(
            key,
            module,
            calls,
            &selected,
            authorization,
            argument_paths,
            helper_reference_reads,
        )
    }
    /// One child-collection call: the collected child value.
    /// (This was the `query_child_collection` block.)
    fn call_child_collection(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if calls.is_empty()
            && let Some(value) = self.query_child_collection(key, module, env)
        {
            return Ok(Some(vec![value]));
        }
        Ok(None)
    }

    /// One parent reference-array `count` call: exact positive finite source bounds.
    /// (This was the member array `count` block with bounded source Scope.)
    fn call_count_parent_array(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if calls.is_empty()
            && let Some(argument) = self.query_count(key)
            && self
                .nodes
                .get(&argument)
                .is_some_and(|node| node.kind == SyntaxKind::Member)
            && matches!(
                self.types.node_types.get(&argument),
                Some(ResolvedType::Array { .. })
            )
            && self
                .types
                .node_types
                .get(&argument)
                .is_some_and(|ty| self.reference_operand_type_id(ty).is_some())
            && self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Int))
        {
            let mut values = self.expr(argument, module, env, calls)?;
            for value in &mut values {
                let Some(ReferenceOrigin::Field { field, .. }) = value.reference_origin else {
                    return Err(self.fail(key, "count needs original parent reference-array field"));
                };
                let alias = self
                    .types
                    .field_reuse_sources
                    .get(&field)
                    .ok_or_else(|| self.fail(key, "count needs bounded source Scope"))?;
                // The same genuine inherited bounds apply before any child call.
                if !self.reference_array_source_bounds(field, *alias) {
                    return Err(self.fail(key, "count needs exact positive finite source bounds"));
                }
                value.reference_origin = None;
            }
            return Ok(Some(values));
        }
        Ok(None)
    }

    /// One stored-Contract array `count` call: the whole Contract origin, value cleared.
    /// (This was the member Contract-array `count` block.)
    fn call_count_contract_array(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if calls.is_empty()
            && let Some(argument) = self.query_count(key)
            && self
                .nodes
                .get(&self.query_group(argument).unwrap_or(argument))
                .is_some_and(|node| node.kind == SyntaxKind::Member)
            && matches!(self.types.node_types.get(&argument),
                Some(ResolvedType::Array {element, ordered:true, nonempty:false})
                if matches!(element.as_ref(), ResolvedType::Record {symbol, ..}
                    if matches!(self.resolve.symbols.get(symbol.0 as usize).map(|symbol| &symbol.kind),
                        Some(SymbolKind::Contract { .. }))))
            && self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Int))
        {
            let mut values = self.expr(argument, module, env, calls)?;
            for value in &mut values {
                if !matches!(value.contract_value, Some(ContractValue::Array(_)))
                    || value.reads.is_empty()
                {
                    return Err(self.fail(key, "count needs its whole stored Contract origin"));
                }
                value.contract_value = None;
            }
            return Ok(Some(values));
        }
        Ok(None)
    }

    /// One retained child-association `count`: the complete child value, query-child cleared.
    /// (This was the `CallAs` child-association block with its State comment.)
    fn call_count_child_association(
        &mut self,
        key: NodeKey,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        // State retains and reauthorizes the complete child association before
        // disclosing any parent result. Counting its exact returned wire needs
        // no fabricated parent scalar/row observation. Other uses still refuse
        // at CallAs, including aliases, helpers and field selection.
        if calls.is_empty()
            && let Some(argument) = self.query_count(key)
            && let Some(Binding::CallAs { node }) = self.query_binding(argument)
            && let Some(value) = env.get(&Local::Call(*node))
            && let Some(child) = value.query_child
            && self.complete_children.contains(&child)
            && self.types.effect_call_results.get(node) == self.types.symbol_results.get(&child)
            && self
                .types
                .effect_call_results
                .get(node)
                .and_then(Option::as_ref)
                == self.types.node_types.get(&argument)
            && self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Int))
        {
            let mut retained = value.clone();
            retained.query_child = None;
            return Ok(Some(vec![retained]));
        }
        Ok(None)
    }

    /// One `count` builtin call: original parent occurrences and the supplied edge.
    /// (This was the `count` query-source block.)
    fn call_count_builtin(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if calls.is_empty()
            && self.statement_depth <= 64
            && self.loop_node.is_none()
            && matches!(&selected.target, SelectedCallTarget::Builtin {id,..} if id == "count")
        {
            let original = self.effects.scenarios.values().find_map(|scenario| {
                if scenario.module != module {
                    return None;
                }
                self.checked_count_query_sources(scenario)?.into_iter().find(|query| {
                    let Some(count) = query.count.as_ref() else { return false; };
                    count.call == key
                        && self.count_query_statements(scenario).is_some_and(|statements|statements.iter()
                            .any(|statement| statement.node == count.statement))
                        && query.inputs.iter().all(|(receiver, parameter)| {
                            if let Some((source,_,root))=self.created_parent_source(*receiver,module) {
                                if root!=*parameter||!env.get(&Local::Create(source.node)).is_some_and(|value|
                                    value.record==Some(source.model)&&matches!(value.model_result,Some(DisclosureModelResult::Create{model,node}) if model==source.model&&node==source.node)){return false;}
                            }
                            let Some(ResolvedType::Record { symbol, stored: true }) =
                                self.types.symbol_types.get(parameter)
                            else { return false; };
                            env.get(&Local::Symbol(*parameter)).is_some_and(|value| {
                                value.record == Some(*symbol)
                                    && matches!(value.reference_origin,
                                        Some(ReferenceOrigin::Parameter(original)) if original == *parameter)
                            })
                        })
                })
            });
            if let Some(query) = original {
                let mut value = ValuePath::default();
                let count = query.count.as_ref().expect("checked count source");
                if !count.parent_edges.is_empty() {
                    self.call_count_parent_edges(key, module, env, calls, count, &query, &mut value)?;
                }
                value.influences = query.influences;
                return Ok(Some(vec![value]));
            }
        }
        Ok(None)
    }

    /// One helper-query argument: the original Model slot or a query-owned actor value.
    /// (This was the per-argument loop body: exactly one original value,
    /// admitted Model slot or required edge, otherwise actor mismatch.)
    #[allow(clippy::too_many_arguments)]
    fn call_helper_query_supplied(
        &mut self,
        supplied: NodeKey,
        argument: NodeKey,
        argument_node: NodeKey,
        model: SymbolId,
        input: &Option<(SymbolId, SymbolId, String)>,
        required: &Option<(SymbolId, SymbolId, SymbolId)>,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        result: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let mut values = self.expr(supplied, module, env, calls)?;
        // A parent-chained reference argument seals through the
        // helper-reference edges before the slot checks below: ordinary
        // evaluation records its reads, the edge walk verifies them
        // against the static edges, and the stamps mirror the shared
        // member path's record/model_result for ordinary required
        // references (which never reach this branch: their member
        // evaluation already stamps them).
        let chained = supplied == argument
            && input.is_none()
            && self.checked_required_model_reference(supplied, module).is_none()
            && required.is_some();
        if chained {
            let grouped = self
                .query_group(supplied)
                .ok_or_else(|| self.fail(supplied, "helper chained argument grouping"))?;
            let argument_index = selected
                .arguments
                .iter()
                .position(|actual| self.query_group(*actual) == Some(grouped))
                .ok_or_else(|| self.fail(supplied, "helper chained argument slot"))?;
            let mut helper_reference_reads = HashSet::new();
            self.collect_helper_reference(
                supplied,
                module,
                env,
                calls,
                selected,
                supplied,
                argument_index,
                &mut values,
                &mut helper_reference_reads,
            )?;
        }
        let [value] = values.as_mut_slice() else {
            return Err(self.fail(
                supplied,
                "helper query argument must have one original value",
            ));
        };
        if chained {
            let Some((source_model, field, target)) = required.as_ref() else {
                return Err(self.fail(supplied, "helper query original reference source mismatch"));
            };
            value.model_result = Some(DisclosureModelResult::Reference {
                model: *target,
                node: argument_node,
                source_model: *source_model,
                field: *field,
            });
        }
        if supplied == argument {
            if value.record != Some(model) || !value.intrinsics.is_empty() {
                return Err(self.fail(supplied, "helper query original Model slot"));
            }
            if let Some((parameter, _, _)) = input.as_ref() {
                if value.reference_origin
                    != Some(ReferenceOrigin::ParameterMember {
                        parameter: *parameter,
                        node: argument_node,
                    })
                    || !env.contains_key(&Local::Symbol(*parameter))
                    || !value.reads.is_empty()
                    || !value.influences.is_empty()
                {
                    return Err(self
                        .fail(supplied, "helper query original admitted Model slot"));
                }
            } else {
                let (source_model, field, target) =
                    required.expect("checked required reference");
                if value.reference_origin.is_some()
                    || value.model_result
                        != Some(DisclosureModelResult::Reference {
                            model: target,
                            node: argument_node,
                            source_model,
                            field,
                        })
                    || value.reads.last().is_none_or(|read| {
                        read.node != argument_node
                            || read.model != source_model
                            || read.field != field
                            || read.ty
                                != ResolvedType::Record {
                                    symbol: target,
                                    stored: true,
                                }
                    })
                    || value.reads.iter().any(|read| {
                        !read.calls.is_empty()
                            || read.query_id.is_some()
                            || read.role != DependencyRole::Data
                    })
                {
                    return Err(self
                        .fail(supplied, "helper query original required Model edge"));
                }
            }
            value.record = None;
            value.reference_origin = None;
            value.reference = None;
            value.model_result = None;
        } else if value.record.is_some()
            || value.reference_origin.is_some()
            || !value.reads.is_empty()
            || !value.intrinsics.is_empty()
            || !value.influences.is_empty()
        {
            return Err(self.fail(supplied, "helper query actor source mismatch"));
        }
        result.join(value);
        Ok(())
    }

    /// One `count` builtin's supplied edge: the predicate-occurrence parent path,
    /// closed to a single query-identified control read and joined in.
    /// (This was the supplied-values tail: exact path, single read closure,
    /// occurrence match, then join.)
    #[allow(clippy::too_many_arguments)]
    fn call_count_supplied_edge(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        supplied: &DisclosureQueryParentEdge,
        query: &DisclosureQuery,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
    let mut supplied_values = self.expr(supplied.node, module, env, calls)?;
    if supplied_values.len() != 1 {
        return Err(self.fail(key, "count supplied parent path"));
    }
    let mut supplied_value = self.control(supplied_values.remove(0))?;
    let [read] = supplied_value.reads.as_mut_slice() else {
        return Err(self.fail(key, "count supplied parent read closure"));
    };
    if read.node != supplied.node
        || read.model != supplied.child
        || read.field != supplied.child
        || read.field_name != "parent"
        || read.ty
            != (ResolvedType::Record {
                symbol: supplied.parent,
                stored: true,
            })
        || read.source != query.source
        || !read.calls.is_empty()
        || read.query_id.is_some()
        || !supplied_value.intrinsics.is_empty()
        || !supplied_value.decisions.is_empty()
    {
        return Err(self.fail(key, "count supplied parent occurrence mismatch"));
    }
    read.query_id = Some(query.id.clone());
    value.join(&supplied_value);
        Ok(())
    }

    /// One `count` builtin's parent edges: occurrence/source checks plus the
    /// retained supplied edge at its predicate occurrence.
    /// (This was the non-empty parent-edges block: three occurrences, read-control
    /// evidence, then the supplied parent path joined in.)
    #[allow(clippy::too_many_arguments)]
    fn call_count_parent_edges(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        count: &DisclosureCountQuery,
        query: &DisclosureQuery,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let [first, candidate, supplied] = count.parent_edges.as_slice() else {
            return Err(
                self.fail(key, "count needs its original three parent occurrences")
            );
        };
        if count.contained_parent.is_some()
            || candidate.receiver != first.node
            || candidate.child != first.parent
            || supplied.child != candidate.child
            || supplied.parent != candidate.parent
            || self
                .checked_count_parent_edge(
                    candidate.node,
                    candidate.receiver,
                    candidate.child,
                    module,
                )
                .as_ref()
                != Some(candidate)
            || self.source(module, candidate.node)? != query.source
            || self.source(module, supplied.node)? != query.source
        {
            return Err(self.fail(key, "count parent occurrence/source mismatch"));
        }
        let owner = self
            .checked_count_model(candidate.child, module)
            .ok_or_else(|| self.fail(key, "missing owning query parent model"))?;
        let parent = self
            .checked_count_model(candidate.parent, module)
            .ok_or_else(|| self.fail(key, "missing owning query ancestor model"))?;
        value.reads.push(DisclosureDependency {
            id: self.opaque(
                "read-control",
                candidate.node,
                &self.call_stamp(calls)?,
            )?,
            source: query.source.clone(),
            node: candidate.node,
            calls: Vec::new(),
            role: DependencyRole::Control,
            model: candidate.child,
            field: candidate.child,
            model_name: owner.canonical.clone(),
            field_name: "parent".into(),
            ty: ResolvedType::Record {
                symbol: candidate.parent,
                stored: true,
            },
            type_id: parent.canonical.clone(),
            query_id: Some(query.id.clone()),
        });
        value.observed.push((candidate.node, Vec::new()));
        // Retain the original supplied edge at its predicate
        // occurrence. Native execution must never hoist this read.
            self.call_count_supplied_edge(key, module, env, calls, supplied, query, value)?;
        Ok(())
    }

    /// One transcript `count` operand: the original immutable concat behind a `let`.
    /// (This was the operand match: a `let` effect value's group, else the original.)
    fn transcript_count_operand(
        &self,
        key: NodeKey,
        original: NodeKey,
        module: ModuleId,
    ) -> Result<NodeKey, DisclosureDecline> {
        match self.query_binding(original) {
            Some(Binding::Let { node }) => self
                .effects
                .scenarios
                .values()
                .filter(|scenario| scenario.module == module)
                .flat_map(|scenario| &scenario.effects)
                .find(|effect| effect.node == *node && effect.verb == EffectVerb::Let)
                .and_then(|effect| self.query_group(effect.value?)),
            _ => Some(original),
        }
        .ok_or_else(|| {
            self.fail(key, "transcript count needs its original immutable concat")
        })
    }

    /// One authorization parent read: the receiver's stored record and exact
    /// occurrence correspondence.
    /// (This was the per-read verification: receiver type, node/field/role
    /// lineage, then the module source.)
    fn check_authorization_parent_read(
        &self,
        parent: NodeKey,
        module: ModuleId,
        read: &DisclosureDependency,
        node: NodeKey,
        base: NodeKey,
    ) -> Result<(), DisclosureDecline> {
        let Some(ResolvedType::Record {
            symbol: child,
            stored: true,
        }) = self.types.node_types.get(&base)
        else {
            return Err(self.fail(parent, "authorization parent receiver mismatch"));
        };
        if read.node != node
            || read.field != *child
            || read.model != *child
            || read.field_name != "parent"
            || self.types.node_types.get(&node) != Some(&read.ty)
            || read.role != DependencyRole::Data
            || !read.calls.is_empty()
            || read.query_id.is_some()
            || read.source != self.source(module, node)?
        {
            return Err(
                self.fail(parent, "authorization parent observation mismatch")
            );
        }
                Ok(())
    }

    /// One authorization nullable input: the original optional input's scenario
    /// and admitted Model lineage.
    /// (This was the nullable-parameter branch: scenario/param lookup, module
    /// and lineage checks.)
    fn authorize_nullable_value(
        &self,
        parent: NodeKey,
        module: ModuleId,
        env: &Env,
        parameter: SymbolId,
        model: SymbolId,
        value: &ValuePath,
    ) -> Result<(), DisclosureDecline> {
        let (scenario, param) = self
            .effects
            .scenarios
            .values()
            .find_map(|scenario| {
                scenario
                    .params
                    .iter()
                    .find(|param| param.param == parameter)
                    .map(|param| (scenario, param))
            })
            .ok_or_else(|| self.fail(parent, "missing original optional input"))?;
        if scenario.module != module
            || self.nullable_model_input(scenario, param) != Some(model)
            || value.record != Some(model)
            || !value.reads.is_empty()
            || !value.intrinsics.is_empty()
            || !value.decisions.is_empty()
            || !matches!(self.query_binding(parent), Some(Binding::Symbol(actual)) if *actual == parameter)
            || env.get(&Local::Symbol(parameter)).is_none_or(|input| {
                input.reference_origin != value.reference_origin
            })
        {
            return Err(self.fail(parent, "authorization optional input mismatch"));
        }
                Ok(())
    }

    /// One authorization parent argument: the original required parent reference
    /// against every alternative value.
    /// (This was the authorization argument block: nullable admission or the
    /// required parent edge walk with per-read verification.)
    fn call_authorization_argument(
        &mut self,
        module: ModuleId,
        env: &Env,
        model: SymbolId,
        parent: NodeKey,
        alternatives: &mut Vec<ValuePath>,
    ) -> Result<(), DisclosureDecline> {
        for value in alternatives {
            if let Some(ReferenceOrigin::NullableParameter(parameter)) =
                value.reference_origin
            {
                self.authorize_nullable_value(parent, module, env, parameter, model, value)?;
                continue;
            }
            let Some(ReferenceOrigin::Parent {
                parameter,
                model: actual,
                depth,
            }) = value.reference_origin
            else {
                return Err(self.fail(
                    parent,
                    "authorization needs its original required parent reference",
                ));
            };
            if !matches!(depth, 1 | 2) || actual != model || value.record != Some(model)
                || self.checked_call_parent_path(parent,parameter,0) != Some((model,depth))
                || !env.get(&Local::Symbol(parameter)).is_some_and(|input| {
                    matches!(input.reference_origin,Some(ReferenceOrigin::Parameter(original)) if original == parameter)
                }) || value.reads.len()!=usize::from(depth)
                || !value.intrinsics.is_empty() || !value.decisions.is_empty()
            { return Err(self.fail(parent,"authorization parent observation mismatch")); }
            let mut edges = Vec::new();
            let mut edge = parent;
            for _ in 0..depth {
                let (base, field) = self.count_member(edge).ok_or_else(|| {
                    self.fail(parent, "authorization parent edge missing")
                })?;
                if field != "parent" {
                    return Err(self.fail(parent, "authorization parent edge mismatch"));
                }
                edges.push((edge, base));
                edge = base;
            }
            edges.reverse();
            for (read, (node, base)) in value.reads.iter().zip(edges) {
                self.check_authorization_parent_read(parent, module, read, node, base)?;
            }
            // Consumption into this exact formal retains the source
            // parent read. It neither admits a new parameter nor leaves
            // a general parent/field operand permission in the callee.
            value.reference_origin = None;
        }
        Ok(())
    }

    /// One helper-reference read: the Model formal's canonical source.
    /// (This was the per-read verification: model symbol, parent-or-field
    /// name, occurrence lineage, then the module source.)
    fn check_helper_reference_read(
        &self,
        key: NodeKey,
        module: ModuleId,
        read: &DisclosureDependency,
        node: NodeKey,
        model: SymbolId,
        field: SymbolId,
    ) -> Result<(), DisclosureDecline> {
        let symbol = self
            .resolve
            .symbols
            .get(model.0 as usize)
            .ok_or_else(|| self.fail(key, "helper reference model missing"))?;
        let name = if model == field {
            "parent"
        } else {
            &self
                .resolve
                .symbols
                .get(field.0 as usize)
                .ok_or_else(|| self.fail(key, "helper reference field missing"))?
                .name
        };
        if read.node != node
            || read.model != model
            || read.field != field
            || read.model_name != symbol.canonical
            || read.field_name != name
            || self.types.node_types.get(&node) != Some(&read.ty)
            || read.type_id
                != self.reference_operand_type_id(&read.ty).ok_or_else(|| {
                    self.fail(key, "helper reference type missing")
                })?
            || read.role != DependencyRole::Data
            || !read.calls.is_empty()
            || read.query_id.is_some()
            || read.source != self.source(module, node)?
        {
            return Err(self.fail(key, "helper reference source mismatch"));
        }
                Ok(())
    }

    /// Apply one helper reference: every alternative value consumes its actual
    /// Model formal, retaining the read census.
    /// (This was the per-value loop: observation match, per-read source
    /// verification, then the formal consumes its operand.)
    #[allow(clippy::too_many_arguments)]
    fn apply_helper_reference(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        parameter: SymbolId,
        target: SymbolId,
        edges: &[(NodeKey, NodeKey, SymbolId, SymbolId)],
        alternatives: &mut Vec<ValuePath>,
        helper_reference_reads: &mut HashSet<NodeKey>,
    ) -> Result<(), DisclosureDecline> {
        for value in alternatives {
            if !env.get(&Local::Symbol(parameter)).is_some_and(|input| {
                input.reference_origin == Some(ReferenceOrigin::Parameter(parameter))
            }) || value.reads.len() != edges.len()
                || !value.intrinsics.is_empty()
                || !value.decisions.is_empty()
            {
                return Err(self.fail(key, "helper reference observation mismatch"));
            }
            for (read, (node, _, model, field)) in value.reads.iter().zip(edges.iter()) {
                self.check_helper_reference_read(key, module, read, *node, *model, *field)?;
                helper_reference_reads.insert(read.node);
            }
            // The existing read census stays attached to the supplied
            // value; only this actual Model formal consumes its operand.
            value.reference_origin = None;
            value.record = Some(target);
        }
        Ok(())
    }

    /// Collect one helper reference: the checked helper%(TM)s formal edges.
    /// (This was the helper-reference block: DeriveFn declaration, formal
    /// match, parent edge walk, then application over the alternatives.)
    #[allow(clippy::too_many_arguments)]
    fn collect_helper_reference(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        argument: NodeKey,
        argument_index: usize,
        alternatives: &mut Vec<ValuePath>,
        helper_reference_reads: &mut HashSet<NodeKey>,
    ) -> Result<(), DisclosureDecline> {
        if calls.is_empty() && self.loop_node.is_none()
            && let SelectedCallTarget::DeriveFn(derive) = &selected.target
            && let Some(ReferenceOrigin::Parent { model, .. }) = alternatives.first().and_then(|value| value.reference_origin)
            && self.effects.derives.get(derive).is_some_and(|derive|
                derive.params.iter().zip(&selected.slots).any(|(formal,slot)|
                    *slot == Some(argument_index)
                        && self.types.symbol_types.get(&formal.param)
                            == Some(&ResolvedType::Record { symbol:model, stored:true })))
        {
            // An exact required parent is an ordinary Model formal, with
            // the same original edge census as an authorization argument.
            // The callee still proves and authorizes every DATA field it reads.
            self.call_authorization_argument(module,env,model,argument,alternatives)?;
            for value in alternatives.iter() {
                helper_reference_reads.extend(value.reads.iter().map(|read| read.node));
            }
        }
        if calls.is_empty()
            && self.loop_node.is_none()
            && let SelectedCallTarget::DeriveFn(derive) = &selected.target
            && let Some((parameter, receiver, source, field, target, depth)) =
                self.checked_helper_reference_argument(argument, module)
        {
            let derive = self
                .effects
                .derives
                .get(derive)
                .ok_or_else(|| self.fail(key, "missing checked helper declaration"))?;
            if !derive
                .params
                .iter()
                .zip(&selected.slots)
                .any(|(formal, slot)| {
                    *slot == Some(argument_index)
                        && self.types.symbol_types.get(&formal.param)
                            == Some(&ResolvedType::Record {
                                symbol: target,
                                stored: true,
                            })
                })
            {
                return Err(self.fail(key, "helper reference formal mismatch"));
            }
            let mut edges = vec![(
                self.query_group(argument)
                    .ok_or_else(|| self.fail(key, "helper argument grouping"))?,
                receiver,
                source,
                field,
            )];
            let mut edge = receiver;
            for _ in 0..depth {
                let (base, name) = self
                    .count_member(edge)
                    .ok_or_else(|| self.fail(key, "helper parent edge missing"))?;
                let Some(ResolvedType::Record {
                    symbol: child,
                    stored: true,
                }) = self.types.node_types.get(&base)
                else {
                    return Err(self.fail(key, "helper parent receiver mismatch"));
                };
                if name != "parent" {
                    return Err(self.fail(key, "helper parent edge mismatch"));
                }
                edges.push((edge, base, *child, *child));
                edge = base;
            }
            edges.reverse();
            self.apply_helper_reference(
                key,
                module,
                env,
                parameter,
                target,
                &edges,
                alternatives,
                helper_reference_reads,
            )?;
        }
        Ok(())
    }

    /// `assign` passes the original Term's two-hop Customer parent to its
    /// local Boolean eligibility helper. Consume this exact formal as a
    /// versioned parent observation, including both source reads. A copied
    /// Customer or a different helper keeps the ordinary refusal.
    fn assign_eligible_parent_argument(
        &self,
        _key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        argument: NodeKey,
        argument_index: usize,
    ) -> Option<SymbolId> {
        if !self.authorization || !calls.is_empty() || self.loop_node.is_some() {
            return None;
        }
        let SelectedCallTarget::DeriveFn(derive) = selected.target else { return None; };
        let helper = self.resolve.symbols.get(derive.0 as usize)?;
        let helper_data = self.effects.derives.get(&derive)?;
        if helper.name != "eligible_account" || helper.module != module
            || self.resolve.modules.get(module.0 as usize)?.name != "member_terms"
            || selected.slots.as_slice() != [Some(0), Some(1)]
            || selected.arguments.get(1) != Some(&argument)
            || argument_index != 1 || helper_data.params.len() != 2
        { return None; }
        let formal = helper_data.params[1].param;
        let ResolvedType::Record { symbol: customer, stored: true } =
            self.types.symbol_types.get(&formal)? else { return None; };
        if self.resolve.symbols.get(customer.0 as usize)?.name != "Customer" { return None; }
        let (membership_path, outer) = self.count_member(argument)?;
        let (term_path, inner) = self.count_member(membership_path)?;
        if outer != "parent" || inner != "parent" { return None; }
        let Binding::Symbol(parameter) = self.query_binding(term_path)? else { return None; };
        let param = self.resolve.symbols.get(parameter.0 as usize)?;
        let SymbolKind::Param { owner, .. } = param.kind else { return None; };
        let scenario = self.resolve.symbols.get(owner.0 as usize)?;
        let data = self.effects.scenarios.get(&owner)?;
        let ResolvedType::Record { symbol: term, stored: true } =
            self.types.symbol_types.get(parameter)? else { return None; };
        let ModelOwner::ChildOf(membership) = self.effects.models.get(term)?.owner else { return None; };
        if scenario.name != "assign" || scenario.module != module
            || param.name != "term" || data.params.iter().find(|item| item.param == *parameter)?.default.is_some()
            || self.resolve.symbols.get(term.0 as usize)?.name != "Term"
            || self.resolve.symbols.get(membership.0 as usize)?.name != "Membership"
            || self.effects.models.get(&membership)?.owner != ModelOwner::ChildOf(*customer)
            || self.checked_call_parent_path(argument, *parameter, 0) != Some((*customer, 2))
            || self.types.node_types.get(&argument) != self.types.symbol_types.get(&formal)
        { return None; }
        Some(*customer)
    }

    /// Evaluate one call%(TM)s explicit arguments in authored order: authorization
    /// admission, helper references, then the producted paths.
    /// (This was the argument loop: per-argument alternatives with
    /// authorization/helper handling, Contract-wire check, path product.)
    #[allow(clippy::too_many_arguments)]
    fn evaluate_call_arguments(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        authorization: Option<(SymbolId, SymbolId, NodeKey, NodeKey)>,
        helper_reference_reads: &mut HashSet<NodeKey>,
    ) -> Result<Vec<(ValuePath, Vec<ValuePath>)>, DisclosureDecline> {
        let mut argument_paths = vec![(ValuePath::default(), Vec::<ValuePath>::new())];
        for (argument_index, argument) in selected.arguments.iter().enumerate() {
        let mut alternatives = if (authorization.is_some()
            && selected.arguments.first() == Some(argument))
            || matches!(
                self.query_binding(*argument),
                Some(Binding::Context(ContextVar::Actor(_)))
            ) {
            // Only this original authorization call passes Actor into its
            // checked nullable User formal. It is not ordinary context data.
            vec![ValuePath::default()]
        } else {
            self.expr(*argument, module, env, calls)?
        };
        if let Some((_, model, parent, _)) = authorization
            && *argument == parent
        {
            self.call_authorization_argument(module, env, model, parent, &mut alternatives)?;
        } else if let Some(model) = self.assign_eligible_parent_argument(
            key, module, calls, selected, *argument, argument_index,
        ) {
            self.call_authorization_argument(module, env, model, *argument, &mut alternatives)?;
        }
        self.collect_helper_reference(
            key,
            module,
            env,
            calls,
            selected,
            *argument,
            argument_index,
            &mut alternatives,
            helper_reference_reads,
        )?;
        if alternatives.iter().any(|value| {
            value.contract_value.is_some()
                || matches!(
                    value.reference_origin,
                    Some(ReferenceOrigin::Parent { .. } | ReferenceOrigin::Field { .. })
                )
        }) {
            return Err(self.fail(
                key,
                "canonical Contract wire needs its direct local consumer",
            ));
        }
        let mut next = Vec::new();
        for (evaluated, supplied) in argument_paths {
            for alternative in &alternatives {
                if self
                    .product(
                        key,
                        std::slice::from_ref(&evaluated),
                        std::slice::from_ref(alternative),
                    )?
                    .is_empty()
                {
                    continue;
                }
                let mut joined = evaluated.clone();
                joined.join(alternative);
                let mut args = supplied.clone();
                args.push(alternative.clone());
                next.push((joined, args));
                if next.len() > 1024 {
                    return Err(self.fail(key, "call evaluation path bound"));
                }
            }
        }
        if next.len() > 1024 {
            return Err(self.fail(key, "call evaluation path bound"));
        }
        argument_paths = next;
        }
        Ok(argument_paths)
    }

    /// Dispatch one call's target: derive evaluation, settled builtins, roles.
    /// (This was the target match: DeriveFn, Builtin, Role, otherwise refuse.)
    #[allow(clippy::too_many_arguments)]
    fn dispatch_call_target(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        authorization: Option<(SymbolId, SymbolId, NodeKey, NodeKey)>,
        argument_paths: Vec<(ValuePath, Vec<ValuePath>)>,
        helper_reference_reads: HashSet<NodeKey>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        match &selected.target {
            SelectedCallTarget::DeriveFn(id) => self.evaluate_derive_call(
                key,
                calls,
                selected,
                *id,
                argument_paths,
                authorization,
                helper_reference_reads,
            ),
            SelectedCallTarget::Builtin { id, .. } => {
                if id=="first" && selected.slots.as_slice()==[Some(0)] && selected.arguments.len()==1
                    && self.query_group(selected.arguments[0]).and_then(|key|self.types.checked_queries.get(&key))
                        .and_then(|query|self.literal_enum_value_query(query)).is_some() {
                    return Ok(argument_paths.into_iter().map(|(value,_)|value).collect());
                }
                if matches!(id.as_str(), "count" | "first" | "any" | "sum") {
                    return Err(self.influence(
                        key,
                        module,
                        &[
                            InfluenceKind::QueryExistence,
                            InfluenceKind::QueryCardinality,
                            InfluenceKind::QueryMembership,
                        ],
                        "collection builtin closure",
                    ));
                }
                // These settled scalar constructors/math functions consume all
                // explicit operands. Catalog defaults are not source defaults.
                if !self.settled_scalar_call(&id, &selected.arguments, &selected.slots)
                {
                    return Err(self.fail(key, "unsupported builtin closure"));
                }
                Ok(argument_paths
                    .into_iter()
                    .map(|(mut value, _)| {
                        value.record = None;
                        value.reference = None;
                        value
                    })
                    .collect())
            }
            SelectedCallTarget::Role(_) => {
                if self.authorization {
                    Ok(argument_paths.into_iter().map(|(value, _)| value).collect())
                } else {
                    Err(self.fail(key, "authority-dependent role call"))
                }
            }
            _ => Err(self.fail(key, "unsupported callable closure")),
        }
    }

    /// Evaluate one DeriveFn call: recursion guard, then the checked derive body
    /// over the evaluated arguments.
    /// (This was the DeriveFn arm: the stack guard stays outside the result
    /// closure so removal runs on every path.)
    #[allow(clippy::too_many_arguments)]
    fn evaluate_derive_call(
        &mut self,
        key: NodeKey,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
        id: SymbolId,
        argument_paths: Vec<(ValuePath, Vec<ValuePath>)>,
        authorization: Option<(SymbolId, SymbolId, NodeKey, NodeKey)>,
        helper_reference_reads: HashSet<NodeKey>,
    ) -> Result<Vec<ValuePath>, DisclosureDecline> {
        if !self.stack.insert(id) {
            return Err(self.fail(key, "recursive derive closure"));
        }
        let result = (|| {
            let derive = self
                .effects
                .derives
                .get(&id)
                .ok_or_else(|| self.fail(key, "missing checked derive body"))?
                .clone();
            let body = derive
                .expr
                .ok_or_else(|| self.fail(derive.node, "missing derive expression"))?;
            if derive.params.len() > 256 {
                return Err(self.fail(derive.node, "derive binding closure bound"));
            }
            if selected.slots.len() != derive.params.len() {
                return Err(self.fail(key, "checked call slot mismatch"));
            }
            let mut nested_calls = calls.to_vec();
            nested_calls.push(key);
            let mut out = Vec::new();
            for (evaluated, arguments) in argument_paths {
                let bindings = self.bind_derive_parameters(
                    key,
                    selected,
                    &derive,
                    evaluated,
                    &arguments,
                    &nested_calls,
                )?;
                for (local, evaluated) in bindings {
                    for mut value in
                        self.expr(body, derive.module, &local, &nested_calls)?
                    {
                        self.emit_derive_value(
                            key,
                            &evaluated,
                            value,
                            authorization,
                            &helper_reference_reads,
                            &mut out,
                        )?;
                    }
                }
            }
            self.bounded(key, out)
        })();
        self.stack.remove(&id);
        result
    }

    /// Emit one derive value: compatible decisions join the census reads and
    /// merge into the output.
    /// (This was the per-value body: skip incompatible decisions, join the
    /// authorization and census reads, merge decisions and observations.)
    fn emit_derive_value(
        &self,
        key: NodeKey,
        evaluated: &ValuePath,
        mut value: ValuePath,
        authorization: Option<(SymbolId, SymbolId, NodeKey, NodeKey)>,
        helper_reference_reads: &HashSet<NodeKey>,
        out: &mut Vec<ValuePath>,
    ) -> Result<(), DisclosureDecline> {
                    if !compatible(&evaluated.decisions, &value.decisions) {
                        return Ok(());
                    }
                    if let Some((_, _, parent, _)) = authorization {
                        // This checked authorization call eagerly
                        // read its required parent before the lazy
                        // derive body. Every resulting alternative
                        // retains that same reference authority.
                        value.join(&ValuePath {
                            reads: evaluated
                                .reads
                                .iter()
                                .filter(|read| {
                                    read.node == parent
                                        && read.field_name == "parent"
                                        && read.calls.is_empty()
                                })
                                .cloned()
                                .collect(),
                            ..ValuePath::default()
                        });
                    }
                    value.join(&ValuePath {
                        reads: evaluated
                            .reads
                            .iter()
                            .filter(|read| helper_reference_reads.contains(&read.node))
                            .cloned()
                            .collect(),
                        ..ValuePath::default()
                    });
                    // Other argument reads matter only when the derive's
                    // returned value consumes them. Decisions are
                    // retained solely to identify actual evaluation.
                    let mut decisions = evaluated.decisions.clone();
                    for decision in &value.decisions {
                        if !decisions.contains(decision) {
                            decisions.push(decision.clone());
                        }
                    }
                    value.decisions = decisions;
                    let mut observed = evaluated.observed.clone();
                    for read in &value.observed {
                        if !observed.contains(read) {
                            observed.push(read.clone());
                        }
                    }
                    value.observed = observed;
                    out.push(value);
                    if out.len() > 1024 {
                        return Err(self.fail(key, "derive evaluation path bound"));
                    }
        Ok(())
    }

    /// Bind one derive evaluation: explicit arguments or checked defaults
    /// fill the derive formals.
    /// (This was the bindings loop: per-formal slot/default expansion with
    /// the path bound.)
    fn bind_derive_parameters(
        &mut self,
        key: NodeKey,
        selected: &super::types::SelectedCall,
        derive: &super::effects::DeriveData,
        evaluated: ValuePath,
        arguments: &[ValuePath],
        nested_calls: &[NodeKey],
    ) -> Result<Vec<(Env, ValuePath)>, DisclosureDecline> {
            let mut bindings = vec![(Env::new(), evaluated)];
            for (param, slot) in derive.params.iter().zip(&selected.slots) {
                let mut next = Vec::new();
                for (local, prior) in bindings {
                    let values = if let Some(index) = slot {
                        vec![arguments.get(*index).cloned().ok_or_else(|| {
                            self.fail(key, "checked argument index mismatch")
                        })?]
                    } else {
                        self.expr(
                            param.default.ok_or_else(|| {
                                self.fail(param.node, "missing checked derive default")
                            })?,
                            derive.module,
                            &local,
                            &nested_calls,
                        )?
                    };
                    for value in values {
                        let mut local = local.clone();
                        local.insert(Local::Symbol(param.param), value.clone());
                        let mut prior = prior.clone();
                        prior.join(&value);
                        next.push((local, prior));
                        if next.len() > 1024 {
                            return Err(self.fail(key, "default evaluation path bound"));
                        }
                    }
                }
                if next.len() > 1024 {
                    return Err(self.fail(key, "default evaluation path bound"));
                }
                bindings = next;
            }
        Ok(bindings)
    }

    /// One call's source group: Helper, pure-input, `any`, and transcript sources.
    /// (This was a run of the guarded source blocks, in order.)
    fn call_origin_source_blocks(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if let Some(paths) = self.call_helper_query(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_pure_input(key, module, env, calls)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_any_builtin(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_nested_any_builtin(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_transcript_derive(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        Ok(None)
    }

    /// One call's source group: Transcript-count, membership, `first`, and `count` sources.
    /// (This was a run of the guarded source blocks, in order.)
    fn call_count_source_blocks(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
        selected: &super::types::SelectedCall,
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        // Counting an original admitted primitive text array is a pure
        // Values operation. It never opens a stored collection query.
        if calls.is_empty() && self.loop_node.is_none()
            && matches!(&selected.target, SelectedCallTarget::Builtin { id, .. } if id == "count")
            && selected.slots.as_slice() == [Some(0)] && selected.arguments.len() == 1
            && let Some(Binding::Symbol(parameter)) = self.query_binding(selected.arguments[0])
            && matches!(self.resolve.symbols.get(parameter.0 as usize).map(|symbol| &symbol.kind), Some(SymbolKind::Param { .. }))
            && matches!(self.types.symbol_types.get(parameter), Some(ResolvedType::Array { element, ordered: true, nonempty: false })
                if element.as_ref() == &ResolvedType::Scalar(Scalar::Text))
            && self.types.node_types.get(&selected.arguments[0]) == self.types.symbol_types.get(parameter)
            && self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Int))
        {
            return self.expr(selected.arguments[0], module, env, calls).map(|values| Some(values.into_iter().map(|mut value| {
                value.schema = None; value.reference = None; value.reference_origin = None;
                value.contract_value = None; value.first_query = None;
                value
            }).collect()));
        }
        if let Some(paths) = self.call_transcript_count(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_membership_authorize(key, module, calls)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_first_builtin(key, module, calls, &selected)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_count_builtin(key, module, env, calls, &selected)? {
            return Ok(Some(paths));
        }
        Ok(None)
    }

    /// One call's source group: Child-association, Contract-array, parent-array, and child-collection sources.
    /// (This was a run of the guarded source blocks, in order.)
    fn call_child_source_blocks(
        &mut self,
        key: NodeKey,
        module: ModuleId,
        env: &Env,
        calls: &[NodeKey],
    ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
        if let Some(paths) = self.call_count_child_association(key, env, calls)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_count_contract_array(key, module, env, calls)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_count_parent_array(key, module, env, calls)? {
            return Ok(Some(paths));
        }
        if let Some(paths) = self.call_child_collection(key, module, env, calls)? {
            return Ok(Some(paths));
        }
        Ok(None)
    }

    /// Whether one effect precedes a direct created return: a plain admission
    /// or a branch-free if of requirements and returns.
    fn before_direct_create(effect: &Effect) -> bool {
        matches!(effect.verb, EffectVerb::Let | EffectVerb::Require)
            || effect.verb == EffectVerb::If
                && effect.match_arms.is_empty()
                && effect.then_effects.iter().chain(&effect.else_effects).all(
                    |nested| {
                        matches!(nested.verb, EffectVerb::Require | EffectVerb::Return)
                            && nested.then_effects.is_empty()
                            && nested.else_effects.is_empty()
                            && nested.match_arms.is_empty()
                    },
                )
    }
        /// Whether one effect tail keeps the created shape: a finite walk of plain
        /// admissions without nested branches.
        fn ordered_created_tail(tail: &[Effect]) -> bool {
        let mut pending = tail.iter().collect::<Vec<_>>();
        let mut visits = 0usize;
        while let Some(effect) = pending.pop() {
            visits += 1;
            if visits > 16384 || !effect.match_arms.is_empty() {
                return false;
            }
            if effect.verb == EffectVerb::If {
                if effect.cond.is_none() {
                    return false;
                }
                pending.extend(&effect.then_effects);
                pending.extend(&effect.else_effects);
            } else if !matches!(
                effect.verb,
                EffectVerb::Let | EffectVerb::Require | EffectVerb::Send | EffectVerb::Set | EffectVerb::Emit | EffectVerb::Schedule
            ) || !effect.then_effects.is_empty()
                || !effect.else_effects.is_empty()
            {
                return false;
            }
        }
        true
    }
            /// Whether one created row returns through send/set: the created call,
            /// assigned record, sent delivery, then required guards to the return.
            /// (This was the send-return shape closure.)
            fn check_created_send_return(
                &self,
                effects: &[Effect],
                model: SymbolId,
                created: &Effect,
                created_pair: bool,
            ) -> bool {
                let Some(index) = effects
                    .iter()
                    .position(|effect| effect.node == created.node)
                else {
                    return false;
                };
                let tail = &effects[index + 1 + usize::from(created_pair)..];
                if tail.len() < 4
                    || effects[..index]
                        .iter()
                        .any(|effect| !matches!(effect.verb, EffectVerb::Let | EffectVerb::Require))
                    || !matches!(created.target, Some(EffectTarget::Model(actual)) if actual == model)
                    || created.binding.is_none()
                    || tail[0].verb != EffectVerb::Set
                    || tail[1].verb != EffectVerb::Send
                    || tail[1].when.is_none()
                    || tail[1].binding.is_none()
                    || tail[2].verb != EffectVerb::Set
                    || !matches!(tail[2].target, Some(EffectTarget::Record {model: Some(actual)}) if actual == model)
                    || tail[3..tail.len() - 1]
                        .iter()
                        .any(|effect| effect.verb != EffectVerb::Require)
                    || effects.iter().any(|effect| {
                        !effect.then_effects.is_empty()
                            || !effect.else_effects.is_empty()
                            || !effect.match_arms.is_empty()
                    })
                {
                    return false;
                }
                let sent = &tail[1];
                let assigned = &tail[2];
                let receiver = self.nodes.get(&assigned.node).and_then(|node| {
                    node.children
                        .iter()
                        .find(|child| child.kind == SyntaxKind::Path)
                });
                let returned = &tail[tail.len() - 1];
                receiver.is_some_and(|receiver| {
                    matches!(self.query_binding(NodeKey::of(receiver)),
                        Some(Binding::CreateAs {node}) if *node == created.node)
                })
                    && assigned.args.iter().any(|argument| {
                        let key = argument.value.unwrap_or(argument.key_node);
                        matches!(self.query_binding(key),
                            Some(Binding::SendAs {node}) if *node == sent.node)
                            && self.query_group(key).is_some_and(|key| {
                                matches!(self.types.node_types.get(&key),
                                    Some(ResolvedType::StdDelivery { .. }))
                            })
                    })
                    && returned.verb == EffectVerb::Return
                    && returned.value.is_some_and(|key| {
                        matches!(self.query_binding(key),
                            Some(Binding::CreateAs {node}) if *node == created.node)
                            && self.query_group(key).is_some_and(|key| {
                                self.types.node_types.get(&key)
                                    == Some(&ResolvedType::Record {
                                        symbol: model,
                                        stored: true,
                                    })
                            })
                    })
            }
            /// Whether one created row returns through a child call: the created call
            /// with the exact Model edge, then the CallAs return.
            /// (This was the child-return shape closure.)
            fn check_created_child_return(
                &self,
                effects: &[Effect],
                model: SymbolId,
                created: &Effect,
            ) -> bool {
                if effects.len() < 3
                    || effects.get(effects.len() - 3).map(|effect| effect.node)
                        != Some(created.node)
                    || effects[..effects.len() - 3]
                        .iter()
                        .any(|effect| !matches!(effect.verb, EffectVerb::Let | EffectVerb::Require))
                    || effects.iter().any(|effect| {
                        !effect.then_effects.is_empty()
                            || !effect.else_effects.is_empty()
                            || !effect.match_arms.is_empty()
                    })
                {
                    return false;
                }
                let called = &effects[effects.len() - 2];
                let returned = &effects[effects.len() - 1];
                let Some(EffectTarget::Operation(operation)) = &called.target else {
                    return false;
                };
                let Some(EffectTarget::Model(created_model)) = created.target else {
                    return false;
                };
                called.verb == EffectVerb::Call
                    && called.binding.is_some()
                    && self.complete_model_children.get(operation) == Some(&model)
                    && called.args.iter().any(|argument| {
                        let key = argument.value.unwrap_or(argument.key_node);
                        matches!(self.query_binding(key), Some(Binding::CreateAs {node})
                            if *node == created.node)
                            && self.types.node_types.get(&key)
                                == Some(&ResolvedType::Record {
                                    symbol: created_model,
                                    stored: true,
                                })
                    })
                    && returned.verb == EffectVerb::Return
                    && returned.value.is_some_and(|key| {
                        matches!(self.query_binding(key), Some(Binding::CallAs {node})
                            if *node == called.node)
                            && self.query_group(key).is_some_and(|key| {
                                self.types.node_types.get(&key)
                                    == Some(&ResolvedType::Record {
                                        symbol: model,
                                        stored: true,
                                    })
                            })
                    })
            }
            /// Whether one created row returns directly: the created call leads the
            /// effects with plain admissions before it.
            /// (This was the direct-return shape closure.)
            fn check_direct_model_return(
                &self,
                effects: &[Effect],
                model: SymbolId,
                created: &Effect,
                created_pair: bool,
            ) -> bool {
                effects.len() >= 2
                    && ((!created_pair && effects.iter().position(|effect| effect.node == created.node).is_some_and(|position| {
                            position + 1 < effects.len()
                                && effects[..position].iter().all(Self::before_direct_create)
                                && Self::ordered_created_tail(&effects[position + 1..effects.len() - 1])
                        }))
                        || (created_pair && effects.len() >= 3
                            && (effects.get(effects.len() - 3).map(|effect| effect.node) == Some(created.node)
                                || effects.iter().position(|effect| effect.node == created.node).is_some_and(|position|
                                    position + 2 < effects.len()
                                        && Self::ordered_created_tail(&effects[position + 2..effects.len() - 1])))))
                    && matches!(created.target, Some(EffectTarget::Model(actual)) if actual == model)
                    && effects.last().is_some_and(|returned| {
                        returned.verb == EffectVerb::Return
                            && returned.value.is_some_and(|key| {
                                matches!(self.query_binding(key), Some(Binding::CreateAs {node}) if *node == created.node)
                                    && self.query_group(key).is_some_and(|key| {
                                        self.types.node_types.get(&key) == Some(&ResolvedType::Record {symbol: model, stored: true})
                                    })
                            })
                    })
                    && effects.iter().all(|effect| effect.verb == EffectVerb::If
                        || effect.then_effects.is_empty()
                            && effect.else_effects.is_empty() && effect.match_arms.is_empty())
            }
            /// Updating an owning bounded child domain may precede its one
            /// new revision. Individual loop/SET/CREATE proofs still execute
            /// in source order; this is only the created-result shape join.
            fn check_updated_model_return(&self, effects: &[Effect], model: SymbolId, created: &Effect) -> bool {
                let [looped, numbered, updated, actual, returned] = effects else { return false; };
                looped.verb == EffectVerb::For && looped.limit.is_some()
                    && numbered.verb == EffectVerb::Let && updated.verb == EffectVerb::Set
                    && actual.node == created.node && actual.verb == EffectVerb::Create
                    && matches!(actual.target, Some(EffectTarget::Model(target)) if target == model)
                    && returned.verb == EffectVerb::Return
                    && returned.value.is_some_and(|key| matches!(self.query_binding(key), Some(Binding::CreateAs {node}) if *node == created.node))
                    && effects[1..].iter().all(|effect| effect.then_effects.is_empty() && effect.else_effects.is_empty() && effect.match_arms.is_empty())
            }

            /// Check the straight-line created profile: create, set, required guards,
            /// then the current-field return.
            /// (This was the fallback block when no model-return shape admitted.)
            fn check_straight_line_created_return(
                &self,
                effects: &[Effect],
                module: ModuleId,
                created: &Effect,
            ) -> Result<(), DisclosureDecline> {
                // Keep this admission tied to the original straight-line created
                // row workflow. Existing late requirements may reject both stages.
                let Some(set) = effects.get(1) else {
                    return Err(self.fail(created.node, "create then set/current-field return profile required"));
                };
                let Some(returned) = effects.last() else {
                    return Err(self.fail(created.node, "create then set/current-field return profile required"));
                };
                if effects.first().map(|effect| effect.node) != Some(created.node)
                    || effects.len() < 3
                    || set.verb != EffectVerb::Set
                    || returned.verb != EffectVerb::Return
                    || effects[2..effects.len() - 1]
                        .iter()
                        .any(|effect| effect.verb != EffectVerb::Require)
                    || effects.iter().any(|effect| {
                        !effect.then_effects.is_empty()
                            || !effect.else_effects.is_empty()
                            || !effect.match_arms.is_empty()
                    })
                {
                    return Err(self.fail(created.node, "create then set/current-field return profile required"));
            }
            let receiver = self
                .nodes
                .get(&set.node)
                .and_then(|node| {
                    node.children
                        .iter()
                        .find(|child| child.kind == SyntaxKind::Path)
                })
                .ok_or_else(|| self.fail(created.node, "create then set/current-field return profile required"))?;
            let value = returned
                .value
                .and_then(|key| self.nodes.get(&key))
                .ok_or_else(|| self.fail(created.node, "create then set/current-field return profile required"))?;
            let base = value
                .children
                .iter()
                .find(|child| expression(child.kind))
                .ok_or_else(|| self.fail(created.node, "create then set/current-field return profile required"))?;
            if value.kind != SyntaxKind::Member
                || !matches!(self.query_binding(NodeKey::of(receiver)), Some(Binding::CreateAs {node}) if *node == created.node)
                || !matches!(self.query_binding(NodeKey::of(base)), Some(Binding::CreateAs {node}) if *node == created.node)
                || self.types.node_types.get(&NodeKey::of(value))
                    != Some(&ResolvedType::Scalar(Scalar::Int))
            {
                return Err(self.fail(created.node, "create then set/current-field return profile required"));
            }
                Ok(())
            }

            /// One `create` statement effect: disclose the created inputs.
            /// (This was the statement-effect match arm.)
            fn walk_effect_create(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
                let (model, inputs) = self.create(effect, module, &flow.env, calls)?;
                self.effect_visits += 1;
                for input in inputs {
                    let mut path = flow.clone();
                    path.executed_effect = true;
                    path.writes.join(&path.effect_guards);
                    path.writes.join(&path.controls);
                    path.writes.join(&input);
                    path.env.insert(
                        Local::Create(effect.node),
                        ValuePath {
                            record: Some(model),
                            model_result: Some(DisclosureModelResult::Create {
                                model,
                                node: effect.node,
                            }),
                            ..ValuePath::default()
                        },
                    );
                    if path.env.len() > 256 {
                        return Err(self.fail(effect.node, "binding closure bound"));
                    }
                    next.push(path);
                }
                Ok(())
            }

            /// One `delete` statement effect: the terminal implicit-void archive.
            /// (This was the statement-effect match arm.)
            #[allow(clippy::too_many_arguments)]
            fn walk_effect_delete(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
                effects: &[Effect],
                returns: &[DisclosureReturn],
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
                // Only the original terminal archive with implicit void;
                // no post-delete read or scalar disclosure is introduced.
                if effects.len() != 1 || !returns.is_empty() {
                    return Err(self.fail(
                        effect.node,
                        "terminal implicit-void archive profile required",
                    ));
                }
                self.delete(effect, module, &flow.env, calls)?;
                self.effect_visits += 1;
                let mut path = flow;
                path.executed_effect = true;
                path.writes.join(&path.effect_guards);
                path.writes.join(&path.controls);
                next.push(path);
                Ok(())
            }

            /// One `let` statement effect: the immutable initializer binds.
            /// (This was the statement-effect match arm.)
            fn walk_effect_let(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
                let value = effect.value.ok_or_else(|| {
                    self.fail(effect.node, "missing immutable initializer")
                })?;
                for evaluated in self.expr(value, module, &flow.env, calls)? {
                    if matches!(
                        evaluated.model_result,
                        Some(DisclosureModelResult::Reference { .. })
                    ) {
                        return Err(self.fail(
                            value,
                            "stored Model reference result cannot be copied",
                        ));
                    }
                    if matches!(
                        evaluated.reference_origin,
                        Some(
                            ReferenceOrigin::Parent { .. } | ReferenceOrigin::Field { .. }
                        )
                    ) && !evaluated.current_revision.is_some_and(|binding| {
                        binding == effect.node
                            && self.current_revision_at(value, module).is_some_and(|fact| {
                                fact.binding == effect.node
                                    && self.query_group(value) == Some(fact.value)
                            })
                    }) {
                        return Err(
                            self.fail(value, "stored reference operand cannot be copied")
                        );
                    }
                    if evaluated.record.is_some()
                        && matches!(
                            evaluated.reference_origin,
                            Some(ReferenceOrigin::ParameterMember { .. })
                        )
                    {
                        return Err(self
                            .fail(value, "original input Model member cannot be copied"));
                    }
                    if !compatible(&flow.evaluated, &evaluated.decisions) {
                        continue;
                    }
                    let mut path = flow.clone();
                    path.observe_value(&evaluated);
                    path.env.insert(Local::Let(effect.node), evaluated);
                    if path.env.len() > 256 {
                        return Err(self.fail(effect.node, "binding closure bound"));
                    }
                    next.push(path);
                    if next.len() > 1024 {
                        return Err(self.fail(effect.node, "statement path bound"));
                    }
                }
                Ok(())
            }

            /// Execute one checked write-effect lifecycle: evaluate its original
            /// operands, filter compatible paths, retain ordered write provenance,
            /// bind actual SEND/CALL results and enforce the original path limits.
            /// Each verb's evaluator still owns source/schema/permission proof.
            fn walk_write_effect(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
                let (alternatives, delivery) = match effect.verb {
                    EffectVerb::Set => (self.set(effect, module, &flow.env, calls)?, None),
                    EffectVerb::Send => self.send(effect, module, &flow.env, calls)?,
                    EffectVerb::Call => (self.static_call(effect, module, &flow.env, calls)?, None),
                    EffectVerb::Transition => {
                        // Transition spends its visit before checking the machine,
                        // including a refused transition; other writes spend it
                        // after their operand/source evaluator succeeds.
                        self.effect_visits += 1;
                        (self.transition(effect, module, &flow.env, calls)?, None)
                    }
                    EffectVerb::Emit | EffectVerb::Schedule | EffectVerb::Cancel => {
                        (self.external_effect(effect, module, &flow.env, calls)?, None)
                    }
                    _ => return Err(self.fail(effect.node, "mutation or external effect closure")),
                };
                if effect.verb != EffectVerb::Transition {
                    self.effect_visits += 1;
                }
                for evaluated in alternatives {
                    if !compatible(&flow.evaluated, &evaluated.decisions) {
                        continue;
                    }
                    let mut path = flow.clone();
                    path.executed_effect = true;
                    path.writes.join(&flow.effect_guards);
                    path.writes.join(&flow.controls);
                    path.writes.join(&evaluated);
                    if path.writes.reads.len() + path.writes.intrinsics.len() > 200 {
                        let reason = if effect.verb == EffectVerb::Transition {
                            "transition write dependency bound"
                        } else {
                            "effect write dependency bound"
                        };
                        return Err(self.fail(effect.node, reason));
                    }
                    path.observe_value(&evaluated);
                    if let Some(delivery) = &delivery {
                        path.env.insert(
                            Local::Send(effect.node),
                            ValuePath {
                                delivery: Some(delivery.clone()),
                                ..ValuePath::default()
                            },
                        );
                        if path.env.len() > 256 {
                            return Err(self.fail(effect.node, "binding closure bound"));
                        }
                    }
                    if effect.verb == EffectVerb::Call
                        && effect.binding.is_some()
                        && (evaluated.query_child.is_some()
                            || evaluated.model_result.is_some())
                    {
                        path.env.insert(Local::Call(effect.node), evaluated.clone());
                        if path.env.len() > 256 {
                            return Err(self.fail(effect.node, "binding closure bound"));
                        }
                    }
                    next.push(path);
                    if next.len() > 1024 {
                        let reason = if effect.verb == EffectVerb::Transition {
                            "transition path bound"
                        } else {
                            "effect evaluation path bound"
                        };
                        return Err(self.fail(effect.node, reason));
                    }
                }
                Ok(())
            }

            /// Whether one guard read stays controlled: reference operands,
            /// revisions, stored inputs, unfinished runs, or active profiles.
            /// (This was the controls-join filter.)
            fn guarded_if_read(&self, module: ModuleId, dependency: &DisclosureDependency) -> bool {
                dependency.calls.is_empty() && dependency.query_id.is_none()
                                && self.count_member(dependency.node).is_some_and(|(base,name)|
                                    self.nullable_field_if_branch(base,module).is_some_and(|(_,operand,_,_,_,target)|
                                        operand==base && target==dependency.model
                                            && self.resolve.symbols.get(dependency.field.0 as usize).is_some_and(|field|field.name==name
                                                && matches!(field.kind,SymbolKind::Field{owner,..} if owner==target)
                                                && self.types.symbol_types.get(&field.id)==Some(&dependency.ty))))
            }

            fn require_controlled_read(
                &self,
                module: ModuleId,
                dependency: &DisclosureDependency,
            ) -> bool {
                self.reference_operand_type_id(&dependency.ty).is_some()
                    || self.current_revision_control(dependency, module)
                    || self.guarded_if_read(module,dependency)
                    || self
                        .contract_input_stored_read(dependency, module)
                    || self.run_unfinished_control(dependency, module)
                    || dependency.field_name == "active"
                        && self
                            .checked_profile_scalar(
                                dependency.node,
                                module,
                            )
                            .is_some_and(|(_, _, _, profile, field)| {
                                dependency.model == profile
                                    && dependency.field == field
                                    && dependency.calls.is_empty()
                            })
            }

            /// Whether one guard read joins the admitted guard: Contract authority,
            /// reference operands, revisions, stored inputs, unfinished runs, active
            /// profiles, or an influenced value.
            /// (This was the admitted-guard filter.)
            fn require_admitted_read(
                &self,
                module: ModuleId,
                influences_empty: bool,
                dependency: &DisclosureDependency,
            ) -> bool {
                matches!(&dependency.ty, ResolvedType::Record {symbol,..}
                    if self.resolve.symbols.get(symbol.0 as usize)
                        .is_some_and(|symbol| matches!(symbol.kind, SymbolKind::Contract { .. })))
                    || self.reference_operand_type_id(&dependency.ty).is_some()
                    || self.current_revision_control(dependency,module)
                    || self.guarded_if_read(module,dependency)
                    || self.contract_input_stored_read(dependency,module)
                    || self.run_unfinished_control(dependency,module)
                    || dependency.field_name == "active" && self.checked_profile_scalar(dependency.node,module).is_some_and(|(_,_,_,profile,field)| {
                        dependency.model == profile && dependency.field == field && dependency.calls.is_empty()
                    })
                    || !influences_empty
            }

            /// Consume one requirement%(TM)s stored dependencies: whole-field reads
            /// plus the consumption census.
            /// (This was the execution-reads block: observed stored reads, control
            /// dependencies, then the require-consumption inventory.)
            fn consume_require_dependencies(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                cond: NodeKey,
                value: &ValuePath,
            ) -> Result<(), DisclosureDecline> {
        // Preserve the existing canonical whole-field read even
        // when an independent return prunes the guard lane.
        // Emission observes it only at this authored Member.
        let mut execution_reads = value.reads.clone();
        for (node, calls) in &value.observed {
            if let Some(read) =
                self.require_observed_stored_read(*node, calls, module)
            {
                if !execution_reads.iter().any(|prior| {
                    prior.node == read.node
                        && prior.calls == read.calls
                        && prior.model == read.model
                        && prior.field == read.field
                }) {
                    execution_reads.push(read);
                }
            }
        }
        let dependencies = self.control(ValuePath {
            reads: execution_reads.iter().filter(|read| {
                matches!(&read.ty, ResolvedType::Record {symbol, ..}
                    if self.resolve.symbols.get(symbol.0 as usize)
                        .is_some_and(|symbol| matches!(symbol.kind, SymbolKind::Contract { .. })))
                    || self.first_query_stored_require_read(read, module)
            }).cloned().collect(),
            ..ValuePath::default()
        })?.reads;
        if !dependencies.is_empty() {
            let index =
                match self.require_consumptions.iter().position(|entry| {
                    entry.statement == effect.node && entry.condition == cond
                }) {
                    Some(index) => index,
                    None => {
                        if self.require_consumptions.len() >= 200 {
                            return Err(self.fail(
                                effect.node,
                                "require consumption bound",
                            ));
                        }
                        self.require_consumptions.push(
                            CheckedRequireConsumption {
                                statement: effect.node,
                                condition: cond,
                                dependencies: Vec::new(),
                            },
                        );
                        self.require_consumptions.len() - 1
                    }
                };
            for dependency in dependencies {
                let entry = &self.require_consumptions[index];
                if let Some(previous) = entry
                    .dependencies
                    .iter()
                    .find(|read| read.id == dependency.id)
                {
                    if previous != &dependency {
                        return Err(self.fail(
                            effect.node,
                            "conflicting require consumption",
                        ));
                    }
                } else {
                    if self
                        .require_consumptions
                        .iter()
                        .map(|entry| entry.dependencies.len())
                        .sum::<usize>()
                        >= 200
                    {
                        return Err(self.fail(
                            effect.node,
                            "require consumption dependency bound",
                        ));
                    }
                    self.require_consumptions[index]
                        .dependencies
                        .push(dependency);
                }
            }
        }
                Ok(())
            }

            /// Walk one requirement value: controlled joins, admitted guard,
            /// consumption, then the path merge.
            /// (This was the per-value loop body: compatible decisions only.)
            fn walk_require_value(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: &Flow,
                value: ValuePath,
                cond: NodeKey,
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
        if !compatible(&flow.evaluated, &value.decisions) {
            return Ok(());
        }
        let mut path = flow.clone();
        if value.transcript_count {
            // The exact eager transcript cardinality guard
            // controls this scalar sink as well as effects.
            path.controls.join(&self.control(ValuePath {
                reads: value.reads.clone(),
                influences: value.influences.clone(),
                ..ValuePath::default()
            })?);
        }
        // The new finite reference operand retains whole
        // source-field authority even on a scalar return.
        // Ordinary scalar/Contract guard pruning is unchanged.
        path.controls.join(
            &self.control(ValuePath {
                reads: value
                    .reads
                    .iter()
                    .filter(|dependency| self.require_controlled_read(module, dependency))
                    .cloned()
                    .collect(),
                ..ValuePath::default()
            })?,
        );
        let admitted_guard = self.control(ValuePath {
            intrinsics: value.intrinsics.clone(),
            influences: value.influences.clone(),
            // Whole canonical Contract/reference-field
            // authority belongs to the successful guard,
            // including void/effect returns. Keep existing
            // ordinary scalar authorization pruning.
            reads: value.reads.iter().filter(|dependency| self.require_admitted_read(module, value.influences.is_empty(), dependency)).cloned().collect(),
            ..ValuePath::default()
        })?;
        self.consume_require_dependencies(effect, module, cond, &value)?;
        path.effect_guards.join(&admitted_guard);
        if path.executed_effect {
            path.writes.join(&admitted_guard);
        }
        for read in &value.observed {
            if !path.observed.contains(read) {
                path.observed.push(read.clone());
            }
        }
        for decision in value.decisions {
            if !path.evaluated.contains(&decision) {
                path.evaluated.push(decision);
            }
        }
        next.push(path);
        if next.len() > 1024 {
            return Err(self.fail(effect.node, "statement path bound"));
        }
                Ok(())
            }

            /// One `require` statement effect: the observer-owned leading guard
            /// or the authorized requirement values.
            /// (This was the Require arm: leading-guard shortcut, then values.)
            fn walk_effect_require(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
                next: &mut Vec<Flow>,
            ) -> Result<(), DisclosureDecline> {
        let cond = effect
            .cond
            .ok_or_else(|| self.fail(effect.node, "missing checked requirement"))?;
        if calls.is_empty()
            && self.effects.scenarios.values().any(|scenario| {
                scenario.module == module
                    && self.checked_source_requires(scenario).is_some_and(|sites| {
                        sites.iter().any(|site| {
                            site.statement == effect.node && site.node == cond
                        })
                    })
            })
        {
            // Only the original full leading guard is observer-owned.
            // The body and every other requirement keep static closure.
            next.push(flow);
            return Ok(());
        }
        let alternatives =
            self.authorization_expr(cond, module, &flow.env, calls)?;
        // Preserve independent-return authorization pruning. Required
        // supported intrinsic guard values control successful effects,
        // while stored guard reads retain their existing policy.
        for value in alternatives {
            self.walk_require_value(effect, module, &flow, value, cond, next)?;
        }
                Ok(())
            }

            /// One return's values: the direct child result, checked expression,
            /// or the default void.
            /// (This was the return-operand match.)
            fn return_call_value(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: &Flow,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                Ok(match effect.value {
                    Some(key)
                        if matches!(
                            self.query_binding(key),
                            Some(Binding::CallAs { .. })
                        ) && self.result_model.is_some() =>
                    {
                        let Some(Binding::CallAs { node }) = self.query_binding(key) else {
                            unreachable!();
                        };
                        let value = flow
                            .env
                            .get(&Local::Call(*node))
                            .filter(|value| {
                                value.model_result.is_some_and(|origin| {
                                    Some(origin.model()) == self.result_model
                                })
                            })
                            .cloned()
                            .ok_or_else(|| {
                                self.fail(
                                    key,
                                    "direct child model result provenance required",
                                )
                            })?;
                        if self.types.node_types.get(&self.query_group(key).ok_or_else(
                            || self.fail(key, "missing direct result operand"),
                        )?) != Some(&ResolvedType::Record {
                            symbol: self.result_model.unwrap(),
                            stored: true,
                        }) {
                            return Err(
                                self.fail(key, "direct child model result type mismatch")
                            );
                        }
                        vec![value]
            }
            Some(key) => self.expr(key, module, &flow.env, calls)?,
            None => vec![ValuePath::default()],
        })
            }

            /// Check one model return's parameter source correspondence: readable
            /// owner, matching parameter, stored declaration, and identity rules.
            /// (This was the source-correspondence check.)
            #[allow(clippy::too_many_arguments)]
            fn check_model_return_correspondence(
                &self,
                effect: &Effect,
                module: ModuleId,
                operand: NodeKey,
                scenario: &super::effects::ScenarioData,
                param: &super::effects::ParamData,
                owner: &super::resolve::Symbol,
                model: SymbolId,
                origin: SymbolId,
            ) -> Result<(), DisclosureDecline> {
                let SymbolKind::Model { fields, .. } = &owner.kind else {
                    return Err(self.fail(
                        operand,
                        "model return parameter source correspondence",
                    ));
                };
                if scenario.read
                    || scenario.on.is_some()
                    || owner.module != module
                    || param.default.is_some()
                    || self
                        .nodes
                        .get(&operand)
                        .is_none_or(|node| node.kind != SyntaxKind::NameRef)
                    || self.checked_call_parent_path(operand, origin, 0)
                        != Some((model, 0))
                    || fields.iter().any(|field| {
                        self.resolve
                            .symbols
                            .get(field.0 as usize)
                            .is_none_or(|field| field.name == "id")
                    })
                {
                    return Err(self.fail(
                        operand,
                        "model return parameter source correspondence",
                    ));
                }
                Ok(())
            }

            /// One `first` builtin call: the original first-query record.
            /// (This was the `first` query-source block.)
            fn call_first_builtin(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && self.statement_depth == 1
                    && matches!(&selected.target, SelectedCallTarget::Builtin {id,..} if id == "first")
                {
                    let original = self.effects.scenarios.values().find_map(|scenario| {
                        if scenario.module != module {
                            return None;
                        }
                        scenario
                            .effects
                            .iter()
                            .filter(|binding| binding.verb == EffectVerb::Let)
                            .find_map(|binding| {
                                let query = self.checked_first_query_source(scenario, binding)?;
                                (query.first.as_ref()?.call == key).then_some(query)
                            })
                    });
                    if let Some(query) = original {
                        let first = query.first.as_ref().expect("checked first source");
                        return Ok(Some(vec![ValuePath {
                            record: Some(query.model),
                            first_query: Some((first.call, first.binding)),
                            influences: query.influences,
                            ..ValuePath::default()
                        }]));
                    }
                }
                Ok(None)
            }

            /// One authorization membership call: original StateRead membership evidence.
            /// (This was the single-call authorization membership block.)
            fn call_membership_authorize(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                calls: &[NodeKey],
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if self.authorization
                    && calls.len() == 1
                    && self
                        .effects
                        .scenarios
                        .values()
                        .find_map(|scenario| {
                            (scenario.node.file == calls[0].file
                                && scenario.node.start <= calls[0].start
                                && scenario.node.end >= calls[0].end)
                                .then(|| self.checked_authorization_derive(calls[0], scenario.module))
                                .flatten()
                        })
                        .is_some_and(|(_, _, _, membership)| membership == key)
                {
                    self.checked_membership_signature(key, module)
                        .ok_or_else(|| self.fail(key, "original StateRead membership evidence required"))?;
                    return Ok(Some(vec![ValuePath {
                        observed: vec![(key, calls.to_vec())],
                        ..ValuePath::default()
                    }]));
                }
                Ok(None)
            }

            /// One transcript `count` builtin call: exact transcript-origin messages, counted.
            /// (This was the transcript concat `count` block.)
            fn call_transcript_count(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && self.statement_depth == 1
                    && self.loop_node.is_none()
                    && matches!(&selected.target,SelectedCallTarget::Builtin {id,overload:0} if id=="count")
                    && selected.slots.as_slice() == [Some(0)]
                    && selected.arguments.len() == 1
                    && self.types.node_types.get(&key) == Some(&ResolvedType::Scalar(Scalar::Int))
                    && self
                        .types
                        .node_types
                        .get(&selected.arguments[0])
                        .is_some_and(transcript_message_array)
                {
                    let argument = selected.arguments[0];
                    let original = self
                        .query_group(argument)
                        .ok_or_else(|| self.fail(key, "missing transcript count operand"))?;
                    let operand = self.transcript_count_operand(key, original, module)?;
                    let count_node = self
                        .nodes
                        .get(&key)
                        .ok_or_else(|| self.fail(key, "missing transcript count"))?;
                    let head = count_node
                        .children
                        .iter()
                        .find(|child| expression(child.kind))
                        .ok_or_else(|| self.fail(key, "missing transcript count target"))?;
                    let syntax_args: Vec<_> = count_node
                        .children
                        .iter()
                        .filter(|child| child.kind == SyntaxKind::Argument)
                        .filter_map(|child| {
                            child
                                .children
                                .iter()
                                .find(|child| expression(child.kind))
                                .map(NodeKey::of)
                        })
                        .collect();
                    if count_node.kind != SyntaxKind::Call
                        || syntax_args.as_slice() != [argument]
                        || !matches!(self.query_binding(NodeKey::of(head)),Some(Binding::Builtin {id}) if id=="count")
                    {
                        return Err(self.fail(key, "transcript count source selection mismatch"));
                    }
                    let mut values = self.expr(argument, module, env, calls)?;
                    if values.is_empty()
                        || values
                            .iter()
                            .any(|value| value.transcript_messages != Some(operand))
                    {
                        return Err(self.fail(key, "count needs exact transcript-origin messages"));
                    }
                    for value in &mut values {
                        value.transcript_messages = None;
                        value.transcript_count = true;
                    }
                    return Ok(Some(values));
                }
                Ok(None)
            }

            /// One transcript DeriveFn call: the original required Branch parameter's eager selection.
            /// (This was the transcript source block.)
            fn call_transcript_derive(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && self.statement_depth == 1
                    && self.loop_node.is_none()
                    && matches!(&selected.target, SelectedCallTarget::DeriveFn(_))
                    && self
                        .types
                        .node_types
                        .get(&key)
                        .is_some_and(transcript_message_array)
                    && let Some(fact) = self.effects.scenarios.values().find_map(|scenario| {
                        (scenario.module == module).then_some(())?;
                        self.checked_transcript_sources(scenario)?
                            .into_iter()
                            .find(|fact| fact.call == key)
                    })
                {
                    if !env.get(&Local::Symbol(fact.parameter)).is_some_and(|value| {
                        value.record==Some(fact.branch)
                            && matches!(value.reference_origin,Some(ReferenceOrigin::Parameter(parameter)) if parameter==fact.parameter)
                    }) {
                        return Err(self.fail(key,"transcript needs its original required Branch parameter"));
                    }
                    let model = self
                        .resolve
                        .symbols
                        .get(fact.branch.0 as usize)
                        .ok_or_else(|| self.fail(key, "missing transcript owning Branch"))?;
                    let nested = vec![key];
                    let mut observed = vec![(fact.prefix_node, nested.clone())];
                    observed.extend(
                        fact.dependencies
                            .iter()
                            .map(|dependency| (dependency.node, dependency.calls.clone())),
                    );
                    let mut reads = vec![DisclosureDependency {
                        id: self.opaque("read-data", fact.prefix_node, &self.call_stamp(&nested)?)?,
                        source: fact.source.clone(),
                        node: fact.prefix_node,
                        calls: nested.clone(),
                        role: DependencyRole::Data,
                        model: fact.branch,
                        field: fact.prefix,
                        model_name: model.canonical.clone(),
                        field_name: self.resolve.symbols[fact.prefix.0 as usize].name.clone(),
                        ty: fact.ty.clone(),
                        type_id: "TextMessage[]".into(),
                        query_id: None,
                    }];
                    reads.extend(fact.dependencies);
                    return Ok(Some(vec![ValuePath {
                        // Retain each real eager selection in every consuming Return;
                        // its exact query association still owns candidate capture.
                        reads,
                        observed,
                        influences: fact.influences,
                        transcript_messages: Some(key),
                        ..ValuePath::default()
                    }]));
                }
                Ok(None)
            }

            /// One authorization `any` builtin call: the original required parent lineage.
            /// (This was the `any` query-source block.)
            fn call_any_builtin(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && self.authorization
                    && self.statement_depth == 1
                    && self.loop_node.is_none()
                    && matches!(&selected.target,SelectedCallTarget::Builtin {id,..} if id=="any")
                {
                    let original = self.effects.scenarios.values().find_map(|scenario| {
                        (scenario.module == module).then_some(())?;
                        let actual = self.types.checked_collection_calls.get(&key)?;
                        self.checked_any_query_sources(scenario)?
                            .into_iter()
                            .find(|query| {
                                actual.node == key
                                    && actual.builtin == "any"
                                    && actual.query == query.node
                                    && Some(actual.alias) == query.alias
                                    && actual.predicate.as_ref().map(|predicate| predicate.node)
                                        == query.predicate
                            })
                    });
                    if let Some(query) = original {
                        let [(receiver, parameter)] = query.inputs.as_slice() else {
                            return Err(self.fail(key, "any needs its original required parent"));
                        };
                        let Some(ResolvedType::Record {
                            symbol: parent,
                            stored: true,
                        }) = self.types.symbol_types.get(parameter)
                        else {
                            return Err(self.fail(key, "any needs its original parent type"));
                        };
                        if !(self.original_reference_parameter(*receiver, *parameter)
                            || self.original_navigation_parameter(*receiver, *parameter))
                            || !env.get(&Local::Symbol(*parameter)).is_some_and(|value| {
                                value.record == Some(*parent)
                                    && matches!(value.reference_origin,
                                        Some(ReferenceOrigin::Parameter(original)) if original==*parameter)
                            })
                        {
                            return Err(self.fail(key, "any needs its original required parent lineage"));
                        }
                        return Ok(Some(vec![ValuePath {
                            // The external predicate is lazy and may run zero or many
                            // times. Its real CONTROL read is retained by the query,
                            // rather than becoming a parent scalar/root decision.
                            influences: query.influences,
                            ..ValuePath::default()
                        }]));
                    }
                }
                Ok(None)
            }

            /// One derive-nested `any` builtin call: the domain formal's
            /// original required parent lineage, re-verified against the
            /// live environment. The static inventory above proves the
            /// shape; this proves the actual values flow from the original
            /// scenario parameter, so a copied lexical value still
            /// acquires nothing.
            fn call_nested_any_builtin(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    || !self.authorization
                    || self.statement_depth != 1
                    || self.loop_node.is_some()
                    || !matches!(&selected.target,SelectedCallTarget::Builtin {id,..} if id=="any")
                {
                    return Ok(None);
                }
                let found = self.effects.scenarios.values().find_map(|scenario| {
                    if scenario.module != module {
                        return None;
                    }
                    let outer = calls.first()?;
                    if outer.file != scenario.node.file
                        || outer.start < scenario.node.start
                        || outer.end > scenario.node.end
                    {
                        return None;
                    }
                    let inventory = self.checked_nested_any_query_sources(scenario)?;
                    inventory
                        .into_iter()
                        .find(|nested| nested.call == key && nested.chain.as_slice() == calls)
                });
                let Some(nested) = found else {
                    return Ok(None);
                };
                let Some(ResolvedType::Record {
                    symbol: parent,
                    stored: true,
                }) = self.types.symbol_types.get(&nested.parameter)
                else {
                    return Err(self.fail(key, "any needs its original parent type"));
                };
                if *parent != nested.parent
                    || !env.get(&Local::Symbol(nested.formal)).is_some_and(|value| {
                        value.record == Some(nested.parent)
                            && matches!(value.reference_origin,
                                Some(ReferenceOrigin::Parameter(original)) if original==nested.parameter)
                    })
                {
                    return Err(self.fail(key, "any needs its original required parent lineage"));
                }
                Ok(Some(vec![ValuePath {
                    // The external predicate is lazy and may run zero or many
                    // times. Its real CONTROL read is retained by the query,
                    // rather than becoming a parent scalar/root decision.
                    influences: nested.query.influences.clone(),
                    ..ValuePath::default()
                }]))
            }

            /// One pure-input-guarded call: the guarded argument's values, stripped to observations.
            /// (This was the pure input guard block.)
            fn call_pure_input(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && let Some(argument) = self.checked_pure_input_guard(key, module)
                {
                    return Ok(Some(self
                        .expr(argument, module, env, calls)?
                        .into_iter()
                        .map(|value| ValuePath {
                            reads: value.reads,
                            intrinsics: value.intrinsics,
                            observed: value.observed,
                            decisions: value.decisions,
                            influences: value.influences,
                            ..ValuePath::default()
                        })
                        .collect()));
                }
                Ok(None)
            }

            /// One authorization helper-query DeriveFn call: the helper's original reference.
            /// (This was the helper-query source block.)
            fn call_helper_query(
                &mut self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                selected: &super::types::SelectedCall,
            ) -> Result<Option<Vec<ValuePath>>, DisclosureDecline> {
                if calls.is_empty()
                    && self.authorization
                    && self.statement_depth >= 1
                    && self.loop_node.is_none()
                    && matches!(&selected.target, SelectedCallTarget::DeriveFn(_))
                {
                    let found = self.effects.scenarios.values().find_map(|scenario| {
                        if scenario.module != module
                            || key.file != scenario.node.file
                            || key.start < scenario.node.start
                            || key.end > scenario.node.end
                        {
                            return None;
                        }
                        self.checked_helper_any_query_sources(scenario)?
                            .into_iter()
                            .find(|query| {
                                query
                                    .dependencies
                                    .first()
                                    .is_some_and(|read| read.calls.as_slice() == [key])
                            })
                            .map(|query| (scenario, query))
                    });
                    if let Some((scenario, query)) = found {
                        let argument = selected
                            .slots
                            .get(1)
                            .copied()
                            .flatten()
                            .and_then(|slot| selected.arguments.get(slot))
                            .copied()
                            .ok_or_else(|| self.fail(key, "helper query selected reference argument"))?;
                        let input = self.checked_contract_input_reference(argument, module);
                        let required = self
                            .checked_required_model_reference(argument, module)
                            .or_else(|| self.helper_parent_chained_reference(scenario, argument));
                        let model = match (&input, &required, query.inputs.as_slice()) {
                            (Some((parameter, model, _)), _, [(original, root)])
                                if *original == argument && root == parameter =>
                            {
                                *model
                            }
                            (None, Some((_, _, model)), []) => *model,
                            _ => {
                                return Err(
                                    self.fail(key, "helper query original reference source mismatch")
                                );
                            }
                        };
                        let argument_node = self
                            .query_group(argument)
                            .ok_or_else(|| self.fail(argument, "helper query reference group"))?;
                        let mut result = ValuePath::default();
                        // Traverse explicit arguments in their authored order. The
                        // callback's candidate reads and membership stay query-owned.
                        for supplied in &selected.arguments {
                            self.call_helper_query_supplied(
                                *supplied,
                                argument,
                                argument_node,
                                model,
                                &input,
                                &required,
                                module,
                                env,
                                calls,
                                selected,
                                &mut result,
                            )?;
                        }
                        result.influences.extend(query.influences);
                        return Ok(Some(vec![result]));
                    }
                }
                Ok(None)
            }

            fn direct_builtin_parameter_type(&self, key: NodeKey, scalar: Scalar) -> bool {
                let Some(node) = self.nodes.get(&key) else {
                    return false;
                };
                if node.kind != SyntaxKind::NamedType {
                    return false;
                }
                let mut paths = node
                    .children
                    .iter()
                    .filter(|child| child.kind == SyntaxKind::Path);
                let Some(path) = paths.next() else {
                    return false;
                };
                paths.next().is_none()
                    && matches!(self.resolve.node_typeref.get(&NodeKey::of(path)),
                    Some(TypeRef::Scalar(name)) if name == scalar.as_str())
            }

            /// Every child slot is supplied explicitly. Owning literal defaults and
            /// checked scalar field reuse remain declaration facts, never reevaluated
            /// CALL arguments or an omitted-input admission.
            fn explicit_scalar_call_parameter(
                &self,
                parameter: &super::effects::ParamData,
                child: &super::effects::ScenarioData,
                scalar: Scalar,
            ) -> bool {
                if let Some(default) = parameter.default {
                    let literal = self
                        .nodes
                        .get(&default)
                        .is_some_and(|node| node.kind == SyntaxKind::Literal)
                        && self.types.node_types.get(&default)
                            == Some(&ResolvedType::Scalar(scalar));
                    if !literal && !self.explicit_param_reference_default(parameter, child, default) {
                        return false;
                    }
                }
                let module = child.module;
                if self.direct_builtin_parameter_type(parameter.type_node, scalar) {
                    return true;
                }
                let Some(node) = self.nodes.get(&parameter.type_node) else {
                    return false;
                };
                let Some(path) = node
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                if node.kind != SyntaxKind::NamedType {
                    return false;
                }
                let checked_alias = |alias: SymbolId| {
                    self.resolve
                        .judgment_value_constraints
                        .get(&alias)
                        .is_some_and(|constraints| {
                            constraints.alias == Some(alias)
                                && self.types.value_constraints.get(&parameter.param) == Some(constraints)
                                && self.types.symbol_types.get(&alias)
                                    == Some(&ResolvedType::Scalar(scalar))
                        })
                };
                match self.resolve.node_typeref.get(&NodeKey::of(path)) {
                    Some(TypeRef::FieldChain { fields, .. }) if fields.len() == 1 => {
                        (self.types.field_reuse_sources.get(&parameter.param) == fields.first()
                            && self.types.symbol_types.get(&fields[0])
                                == Some(&ResolvedType::Scalar(scalar)))
                            || checked_alias(fields[0])
                    }
                    Some(TypeRef::Symbol(alias)) => checked_alias(*alias),
                    Some(TypeRef::External) => {
                        let Some(source) = self.db.get(path.span.file) else {
                            return false;
                        };
                        let segments = super::path_segments(path, &source.text);
                        let [head, field] = segments.as_slice() else {
                            return false;
                        };
                        let Some(ScopedName::External { provider, name }) = self
                            .resolve
                            .module_scopes
                            .get(module.0 as usize)
                            .and_then(|scope| scope.prod.get(*head))
                        else {
                            return false;
                        };
                        if provider != "std"
                            || !matches!(
                                (name.as_str(), *field),
                                ("TextMessage", "content")
                                    | ("ImageRequest", "prompt" | "negative" | "width" | "height")
                            )
                        {
                            return false;
                        }
                        nominal_schema(name)
                            .and_then(|schema| schema.fields.iter().find(|(name, _)| name == field))
                            .and_then(|(_, declared)| super::types::std_schema_type(declared))
                            == Some(ResolvedType::Scalar(scalar))
                    }
                    _ => false,
                }
            }

            /// Singular model slots retain their actual named declaration. Only the
            /// original nullable slot's literal null is a default; CALL supplies it.
            fn explicit_model_call_parameter(
                &self,
                parameter: &super::effects::ParamData,
            ) -> Option<(SymbolId, bool)> {
                let ty = self.types.symbol_types.get(&parameter.param)?;
                let (base, nullable) = match ty {
                    ResolvedType::Nullable(inner) => (inner.as_ref(), true),
                    ty => (ty, false),
                };
                let ResolvedType::Record {
                    symbol,
                    stored: true,
                } = base
                else {
                    return None;
                };
                let model = self.resolve.symbols.get(symbol.0 as usize)?;
                if !matches!(model.kind, SymbolKind::Model { .. })
                    || self.types.value_constraints.contains_key(&parameter.param)
                    || self
                        .types
                        .field_reuse_sources
                        .contains_key(&parameter.param)
                {
                    return None;
                }
                let named = self.model_param_declared(parameter, nullable)?;
                let path = named
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Path)?;
                if !matches!(self.resolve.node_typeref.get(&NodeKey::of(path)),
                    Some(TypeRef::Symbol(actual)) if actual == symbol)
                    || super::path_segments(path, &self.db.get(path.span.file)?.text)
                        != [model.name.as_str()]
                {
                    return None;
                }
                if !self.model_param_default_ok(parameter, nullable) {
                    return None;
                }
                Some((*symbol, nullable))
            }

            /// Resolve an explicit model parameter's declared named type: plain
            /// `NamedType`, or the inner name of a `NullableType`.
            fn model_param_declared(
                &self,
                parameter: &super::effects::ParamData,
                nullable: bool,
            ) -> Option<&SyntaxNode> {
                let declared = self.nodes.get(&parameter.type_node)?;
                let named = if nullable {
                    if declared.kind != SyntaxKind::NullableType {
                        return None;
                    }
                    declared
                        .children
                        .iter()
                        .find(|node| node.kind == SyntaxKind::NamedType)?
                } else {
                    declared
                };
                if named.kind != SyntaxKind::NamedType {
                    return None;
                }
                Some(named)
            }

            /// Whether an explicit model parameter's default is admissible: none
            /// when nonnullable, a `null` literal when nullable.
            fn model_param_default_ok(
                &self,
                parameter: &super::effects::ParamData,
                nullable: bool,
            ) -> bool {
                match (nullable, parameter.default) {
                    (false, None) => true,
                    (true, Some(default)) => {
                        let literal = self
                            .nodes
                            .get(&default)
                            .is_some_and(|node| node.kind == SyntaxKind::Literal);
                        let null_type =
                            self.types.node_types.get(&default) == Some(&ResolvedType::Null);
                        let null_text = self
                            .db
                            .get(default.file)
                            .and_then(|file| {
                                file.text
                                    .get(default.start as usize..default.end as usize)
                            })
                            == Some("null");
                        literal && null_type && null_text
                    }
                    _ => false,
                }
            }

            /// The ordinary File[] child slot keeps its original empty literal default.
            /// That literal is declaration evidence and is not a supplied CALL operand.
            fn explicit_file_array_call_parameter(&self, parameter: &super::effects::ParamData) -> bool {
                let Some(ty) = self.types.symbol_types.get(&parameter.param) else {
                    return false;
                };
                if !ordinary_file_array(ty)
                    || self.types.value_constraints.contains_key(&parameter.param)
                    || self
                        .types
                        .field_reuse_sources
                        .contains_key(&parameter.param)
                {
                    return false;
                }
                let Some(node) = self.nodes.get(&parameter.type_node) else {
                    return false;
                };
                let Some(element) = node
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::NamedType)
                else {
                    return false;
                };
                let Some(default) = parameter.default else {
                    return false;
                };
                let Some(value) = self.nodes.get(&default) else {
                    return false;
                };
                node.kind == SyntaxKind::ArrayType
                    && self.direct_builtin_parameter_type(NodeKey::of(element), Scalar::File)
                    && value.kind == SyntaxKind::Array
                    && !value.children.iter().any(|node| expression(node.kind))
                    && self.types.node_types.get(&default) == Some(ty)
            }

            /// A genuine `=name` scalar default names an earlier required same-type
            /// parameter. Static CALL supplies every slot, so the default never
            /// evaluates there; this keeps the declaration's own genuine default
            /// rather than admitting arbitrary default expressions.
            fn explicit_param_reference_default(
                &self,
                parameter: &super::effects::ParamData,
                child: &super::effects::ScenarioData,
                default: NodeKey,
            ) -> bool {
                let Some(node) = self.nodes.get(&default) else {
                    return false;
                };
                if node.kind != SyntaxKind::NameRef {
                    return false;
                }
                let Some(Binding::Symbol(target)) = self.resolve.node_binding.get(&default) else {
                    return false;
                };
                let target = *target;
                let Some(position) = child.params.iter().position(|param| param.param == parameter.param)
                else {
                    return false;
                };
                let Some(earlier) = child.params.iter().position(|param| param.param == target) else {
                    return false;
                };
                if earlier >= position {
                    return false;
                }
                let referenced = &child.params[earlier];
                if referenced.default.is_some() {
                    return false;
                }
                let Some(expected) = self.types.symbol_types.get(&parameter.param) else {
                    return false;
                };
                if self.types.symbol_types.get(&target) != Some(expected) {
                    return false;
                }
                let Some(declaration) = self.resolve.symbols.get(target.0 as usize) else {
                    return false;
                };
                if declaration.module != child.module {
                    return false;
                }
                matches!(declaration.kind, super::resolve::SymbolKind::Param { owner, .. } if owner == child.scenario)
                    && self.types.node_types.get(&default) == Some(expected)
            }

            /// Implicit `T?` absence is null; only an explicit literal null may also
            /// appear. Server-owned or constrained slots stay ineligible.
            fn nullable_value_default_ok(&self, parameter: &super::effects::ParamData) -> bool {
                match parameter.default {
                    None => true,
                    Some(default) => self.nodes.get(&default).is_some_and(|node| {
                        node.kind == SyntaxKind::Literal
                            && self.types.node_types.get(&default) == Some(&ResolvedType::Null)
                            && self.db.get(default.file).and_then(|file| {
                                file.text.get(default.start as usize..default.end as usize)
                            }) == Some("null")
                    }),
                }
            }

            /// Nullable scalar/enum/file slots (`text?`, `file?`, …) widen from their
            /// exact supplied inner value. Stored-model nullables keep the existing
            /// model rule; only value nullables land here.
            fn explicit_nullable_value_call_parameter(
                &self,
                parameter: &super::effects::ParamData,
            ) -> bool {
                let Some(ty) = self.types.symbol_types.get(&parameter.param) else {
                    return false;
                };
                let ResolvedType::Nullable(inner) = ty else {
                    return false;
                };
                match inner.as_ref() {
                    ResolvedType::Scalar(scalar) => {
                        if !(primitive_type(inner.as_ref()) || *scalar == Scalar::File) {
                            return false;
                        }
                    }
                    ResolvedType::Enum { cases, .. } => {
                        if cases.is_empty() {
                            return false;
                        }
                    }
                    _ => return false,
                }
                if self.types.value_constraints.contains_key(&parameter.param)
                    || self
                        .types
                        .field_reuse_sources
                        .contains_key(&parameter.param)
                {
                    return false;
                }
                let Some(node) = self.nodes.get(&parameter.type_node) else {
                    return false;
                };
                if node.kind != SyntaxKind::NullableType {
                    return false;
                }
                let named = node
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::NamedType);
                let Some(named) = named else {
                    return false;
                };
                let Some(path) = named
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                let direct = match inner.as_ref() {
                    ResolvedType::Scalar(scalar) => {
                        self.direct_builtin_parameter_type(NodeKey::of(named), *scalar)
                            && matches!(
                                self.resolve.node_typeref.get(&NodeKey::of(path)),
                                Some(TypeRef::Scalar(name)) if name == scalar.as_str()
                            )
                    }
                    ResolvedType::Enum { .. } => {
                        self.resolve.node_typeref.get(&NodeKey::of(path)).is_some()
                    }
                    _ => false,
                };
                direct && self.nullable_value_default_ok(parameter)
            }

            /// Enum slots keep their exact checked domain through field reuse or a
            /// checked alias. Case spellings are never converted or widened here.
            fn explicit_enum_call_parameter(&self, parameter: &super::effects::ParamData) -> bool {
                let Some(ty) = self.types.symbol_types.get(&parameter.param) else {
                    return false;
                };
                let ResolvedType::Enum { cases, .. } = ty else {
                    return false;
                };
                if cases.is_empty() {
                    return false;
                }
                if parameter.default.is_some_and(|default| {
                    self.nodes
                        .get(&default)
                        .is_none_or(|node| node.kind != SyntaxKind::Literal)
                        || self.types.node_types.get(&default) != Some(ty)
                }) {
                    return false;
                }
                if self.types.value_constraints.contains_key(&parameter.param) {
                    return false;
                }
                let Some(node) = self.nodes.get(&parameter.type_node) else {
                    return false;
                };
                if node.kind != SyntaxKind::NamedType {
                    return false;
                }
                let Some(path) = node
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                self.reused_parameter_type_matches(parameter, path, ty)
            }

            /// Non-file array slots (`text[]`, `Slot[]`, …) keep their exact element
            /// shape. Only required slots or an empty-array literal default are
            /// eligible; stored-model element arrays stay declined.
            fn explicit_array_call_parameter(&self, parameter: &super::effects::ParamData) -> bool {
                let Some(ty) = self.types.symbol_types.get(&parameter.param) else {
                    return false;
                };
                let ResolvedType::Array { element, ordered: true, .. } = ty else {
                    return false;
                };
                if ordinary_file_array(ty) {
                    return false;
                }
                if !self.array_element_admitted(element) {
                    return false;
                }
                if self.types.value_constraints.contains_key(&parameter.param) {
                    return false;
                }
                if !self.array_param_default_ok(parameter, ty) {
                    return false;
                }
                let Some(node) = self.nodes.get(&parameter.type_node) else {
                    return false;
                };
                if node.kind == SyntaxKind::ArrayType {
                    return true;
                }
                let Some(path) = node
                    .children
                    .iter()
                    .find(|node| node.kind == SyntaxKind::Path)
                else {
                    return false;
                };
                self.reused_parameter_type_matches(parameter, path, ty)
            }

            /// Whether an array parameter's element keeps its exact shape:
            /// primitives, files, non-empty enums, detached records, value-type
            /// contracts/events and objects. Stored models stay declined.
            fn array_element_admitted(&self, element: &ResolvedType) -> bool {
                match element {
                    element if primitive_type(element) => true,
                    ResolvedType::Scalar(Scalar::File) => true,
                    ResolvedType::Enum { cases, .. } if !cases.is_empty() => true,
                    ResolvedType::Record { stored: false, .. } => true,
                    // Declared contracts/events are value types without row
                    // authority, even though they resolve stored. Stored models
                    // keep their row authority and stay declined as array slots.
                    ResolvedType::Record { symbol, .. } => !matches!(
                        self.resolve.symbols.get(symbol.0 as usize).map(|symbol| &symbol.kind),
                        Some(super::resolve::SymbolKind::Model { .. }) | None
                    ),
                    ResolvedType::Object(_) => true,
                    _ => false,
                }
            }

            /// Whether an array parameter's default is admissible: absent, or an
            /// empty-array literal of the parameter type.
            fn array_param_default_ok(
                &self,
                parameter: &super::effects::ParamData,
                ty: &ResolvedType,
            ) -> bool {
                let Some(default) = parameter.default else {
                    return true;
                };
                let Some(value) = self.nodes.get(&default) else {
                    return false;
                };
                value.kind == SyntaxKind::Array
                    && !value.children.iter().any(|node| expression(node.kind))
                    && self.types.node_types.get(&default) == Some(ty)
            }

            /// Reused enum/array CALL slots retain the same original field or
            /// checked alias declaration, constraint identity and exact type.
            fn reused_parameter_type_matches(
                &self,
                parameter: &super::effects::ParamData,
                path: &SyntaxNode,
                ty: &ResolvedType,
            ) -> bool {
                match self.resolve.node_typeref.get(&NodeKey::of(path)) {
                    Some(TypeRef::FieldChain { fields, .. }) if fields.len() == 1 => {
                        self.types.field_reuse_sources.get(&parameter.param) == fields.first()
                            && self.types.symbol_types.get(&fields[0]) == Some(ty)
                    }
                    Some(TypeRef::Symbol(alias)) => self
                        .resolve
                        .judgment_value_constraints
                        .get(alias)
                        .is_some_and(|constraints| {
                            constraints.alias == Some(*alias)
                                && self.types.value_constraints.get(&parameter.param) == Some(constraints)
                                && self.types.symbol_types.get(alias) == Some(ty)
                        }),
                    _ => false,
                }
            }

            /// Original required caller parameters remain source operands, not copied
            /// lexical values which happen to carry the same resolved model type.
            fn original_call_model_parameter(
                &self,
                key: NodeKey,
                statement: NodeKey,
                module: ModuleId,
            ) -> Option<(SymbolId, SymbolId)> {
                let node = self.nodes.get(&key)?;
                if !matches!(node.kind, SyntaxKind::Name | SyntaxKind::NameRef) {
                    return None;
                }
                let Some(Binding::Symbol(parameter)) = self.query_binding(key) else {
                    return None;
                };
                let SymbolKind::Param { owner, .. } = self.resolve.symbols.get(parameter.0 as usize)?.kind
                else {
                    return None;
                };
                let scenario = self.effects.scenarios.get(&owner)?;
                let parameter_data = scenario
                    .params
                    .iter()
                    .find(|param| param.param == *parameter)?;
                let (model, nullable) = self.explicit_model_call_parameter(parameter_data)?;
                (!nullable
                    && !scenario.read
                    && scenario.on.is_none()
                    && scenario.module == module
                    && statement.file == scenario.node.file
                    && scenario.node.start <= statement.start
                    && statement.end <= scenario.node.end
                    && key.file == statement.file
                    && statement.start <= key.start
                    && key.end <= statement.end
                    && self.types.node_types.get(&key) == self.types.symbol_types.get(parameter))
                .then_some((*parameter, model))
            }

            /// One checked `param.parent` hop into a required non-null model slot.
            /// The base remains the caller's original required model parameter and
            /// the hop is the checked containment edge, never a copied row.
            fn original_call_parent_parameter(
                &self,
                key: NodeKey,
                statement: NodeKey,
                module: ModuleId,
            ) -> Option<(SymbolId, SymbolId)> {
                let node = self.nodes.get(&key)?;
                if node.kind != SyntaxKind::Member {
                    return None;
                }
                let mut operands = node.children.iter().filter(|child| expression(child.kind));
                let base = NodeKey::of(operands.next()?);
                if operands.next().is_some() {
                    return None;
                }
                if node
                    .children
                    .iter()
                    .rev()
                    .find(|child| child.kind == SyntaxKind::Name)
                    .and_then(|child| self.word(child))
                    != Some("parent")
                {
                    return None;
                }
                let (parameter, child) = self.original_call_model_parameter(base, statement, module)?;
                let declaration = self.resolve.symbols.get(child.0 as usize)?;
                let SymbolKind::Model {
                    owner: ModelOwner::ChildOf(parent),
                    ..
                } = &declaration.kind
                else {
                    return None;
                };
                (self.checked_call_parent_path(key, parameter, 0) == Some((*parent, 1)))
                    .then_some((parameter, *parent))
            }

            /// One contained-collection domain (`param.Child`) over the caller's
            /// original required model parameter. Returns the root parameter and
            /// the contained child model proven through the checked containment
            /// edge and the domain's own array type.
            fn original_loop_member_root(
                &self,
                domain: NodeKey,
                statement: NodeKey,
                module: ModuleId,
            ) -> Result<(SymbolId, SymbolId), DisclosureDecline> {
                let fail = || self.fail(domain, "loop needs original admitted member domain");
                let node = self.nodes.get(&domain).ok_or_else(fail)?;
                if node.kind != SyntaxKind::Member {
                    return Err(fail());
                }
                let mut operands = node.children.iter().filter(|child| expression(child.kind));
                let base = NodeKey::of(operands.next().ok_or_else(fail)?);
                if operands.next().is_some() {
                    return Err(fail());
                }
                let (parameter, root) = self
                    .original_call_model_parameter(base, statement, module)
                    .or_else(||self.original_call_parent_parameter(base,statement,module))
                    .ok_or_else(fail)?;
                let expected_domain = self
                    .types
                    .node_types
                    .get(&domain)
                    .ok_or_else(fail)?;
                let ResolvedType::Array { element, ordered: true, .. } = expected_domain else {
                    return Err(fail());
                };
                let ResolvedType::Record {
                    symbol: model,
                    stored: true,
                } = element.as_ref()
                else {
                    return Err(fail());
                };
                let model = *model;
                let declaration = self.resolve.symbols.get(model.0 as usize).ok_or_else(fail)?;
                let SymbolKind::Model {
                    owner: ModelOwner::ChildOf(parent),
                    ..
                } = &declaration.kind
                else {
                    return Err(fail());
                };
                if *parent != root
                    || declaration.module != module
                    || self.effects.models.get(&model).ok_or_else(fail)?.owner != ModelOwner::ChildOf(root)
                    || self.types.node_types.get(&base)
                        != Some(&ResolvedType::Record {
                            symbol: root,
                            stored: true,
                        })
                {
                    return Err(fail());
                }
                Ok((parameter, model))
            }

            fn preceding_call_create(
                &self,
                effect: &Effect,
                module: ModuleId,
                key: NodeKey,
                model: SymbolId,
                created: NodeKey,
            ) -> bool {
                let Some(node) = self.nodes.get(&key) else {
                    return false;
                };
                if !matches!(node.kind, SyntaxKind::Name | SyntaxKind::NameRef)
                    || !matches!(self.query_binding(key), Some(Binding::CreateAs {node}) if *node == created)
                {
                    return false;
                }
                let mut owners = self.effects.scenarios.values().filter(|scenario| {
                    scenario.module == module
                        && scenario.node.file == effect.node.file
                        && scenario.node.start <= effect.node.start
                        && effect.node.end <= scenario.node.end
                });
                let Some(owner) = owners.next() else {
                    return false;
                };
                if owners.next().is_some() {
                    return false;
                }
                let Some(position) = owner
                    .effects
                    .iter()
                    .position(|statement| statement.node == effect.node)
                else {
                    return false;
                };
                let Some(previous) = position
                    .checked_sub(1)
                    .and_then(|position| owner.effects.get(position))
                else {
                    return false;
                };
                let Some(original) = self.checked_create_source(previous, module) else {
                    return false;
                };
                previous.verb == EffectVerb::Create
                    && previous.node == created
                    && original.model == model
                    && self.word(node) == Some(original.binding.as_str())
            }

            /// A model returned by the immediately preceding checked child
            /// call may fill one stored reference on this same root path.
            /// The source binding and evaluated call result must be identical;
            /// an intervening statement or copied lexical value is refused.
            fn preceding_set_call(
                &self,
                effect: &Effect,
                module: ModuleId,
                key: NodeKey,
                called: NodeKey,
            ) -> bool {
                let Some(node) = self.nodes.get(&key) else {
                    return false;
                };
                if !matches!(node.kind, SyntaxKind::Name | SyntaxKind::NameRef)
                    || !matches!(self.query_binding(key), Some(Binding::CallAs {node}) if *node == called)
                {
                    return false;
                }
                let mut owners = self.effects.scenarios.values().filter(|scenario| {
                    scenario.module == module
                        && scenario.node.file == effect.node.file
                        && scenario.node.start <= effect.node.start
                        && effect.node.end <= scenario.node.end
                });
                let Some(owner) = owners.next() else {
                    return false;
                };
                if owners.next().is_some() {
                    return false;
                }
                let Some(position) = owner.effects.iter().position(|statement| statement.node == effect.node)
                else {
                    return false;
                };
                let Some(previous) = position.checked_sub(1).and_then(|index| owner.effects.get(index))
                else {
                    return false;
                };
                previous.verb == EffectVerb::Call
                    && previous.node == called
                    && matches!((previous.binding.as_deref(), self.word(node)),
                        (Some(expected), Some(actual)) if expected == actual)
            }

            /// CALL-only stored File[] observation. No ordinary expression/result or
            /// File intrinsic gains admission from this source-backed input leaf.
            fn call_file_array_operand(
                &self,
                key: NodeKey,
                statement: NodeKey,
                module: ModuleId,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let fail = || {
                    self.fail(
                        key,
                        "File[] call input needs original stored parameter member",
                    )
                };
                let node = self.nodes.get(&key).ok_or_else(fail)?;
                if node.kind != SyntaxKind::Member || !calls.is_empty() || self.loop_node.is_some() {
                    return Err(fail());
                }
                let (base, name) = self.file_array_member_shape(key, node)?;
                let (parameter, model) = self
                    .original_call_model_parameter(base, statement, module)
                    .ok_or_else(fail)?;
                let (field_id, owner_canonical, ty) =
                    self.file_array_field_original(key, model, &name, parameter)?;
                self.file_array_declaration_ok(key, model, field_id)?;
                Ok(vec![ValuePath {
                    reads: vec![DisclosureDependency {
                        query_id: None,
                        id: self.opaque("read-data", key, &self.call_stamp(calls)?)?,
                        source: self.source(module, key)?,
                        node: key,
                        calls: calls.to_vec(),
                        role: DependencyRole::Data,
                        model,
                        field: field_id,
                        model_name: owner_canonical,
                        field_name: name,
                        ty: ty.clone(),
                        type_id: "file[]".into(),
                    }],
                    observed: vec![(key, calls.to_vec())],
                    ..ValuePath::default()
                }])
            }

            /// A `File[]` operand's member shape: its base and field name.
            fn file_array_member_shape(
                &self,
                key: NodeKey,
                node: &SyntaxNode,
            ) -> Result<(NodeKey, String), DisclosureDecline> {
                let fail = || {
                    self.fail(
                        key,
                        "File[] call input needs original stored parameter member",
                    )
                };
                let mut operands = node.children.iter().filter(|node| expression(node.kind));
                let base = NodeKey::of(operands.next().ok_or_else(fail)?);
                let name = node
                    .children
                    .iter()
                    .rev()
                    .find(|node| node.kind == SyntaxKind::Name)
                    .and_then(|node| self.word(node))
                    .ok_or_else(fail)?;
                if operands.next().is_some() {
                    return Err(fail());
                }
                Ok((base, name.to_string()))
            }

            /// A `File[]` operand's stored field: its id, owner canonical and
            /// exact `file[]` type from the stored-contracts inventory.
            fn file_array_field_original(
                &self,
                key: NodeKey,
                model: SymbolId,
                name: &str,
                parameter: SymbolId,
            ) -> Result<(SymbolId, String, ResolvedType), DisclosureDecline> {
                let fail = || {
                    self.fail(
                        key,
                        "File[] call input needs original stored parameter member",
                    )
                };
                let owner = self
                    .resolve
                    .symbols
                    .get(model.0 as usize)
                    .ok_or_else(fail)?;
                let SymbolKind::Model { fields, .. } = &owner.kind else {
                    return Err(fail());
                };
                let field = fields
                    .iter()
                    .filter_map(|id| self.resolve.symbols.get(id.0 as usize))
                    .find(|field| field.name == name)
                    .ok_or_else(fail)?;
                let SymbolKind::Param {
                    owner: scenario, ..
                } = self
                    .resolve
                    .symbols
                    .get(parameter.0 as usize)
                    .ok_or_else(fail)?
                    .kind
                else {
                    return Err(fail());
                };
                let scenario = self.effects.scenarios.get(&scenario).ok_or_else(fail)?;
                let inventory = self.checked_stored_contracts(scenario).ok_or_else(fail)?;
                let mut originals = inventory
                    .iter()
                    .filter(|schema| schema.model && schema.id == model)
                    .flat_map(|schema| schema.fields.iter())
                    .filter(|original| original.id == field.id);
                let original = originals.next().ok_or_else(fail)?;
                if originals.next().is_some()
                    || !matches!(field.kind, SymbolKind::Field {owner,..} if owner == model)
                    || field.module != owner.module
                    || original.owner != model
                    || original.name != name
                    || !ordinary_file_array(&original.ty)
                    || original.required_array
                    || original.reuse.is_some()
                    || original.min.is_some()
                    || original.max.as_ref().map(|(_, max, _)| *max) != Some(8)
                    || self.types.node_types.get(&key) != Some(&original.ty)
                    || self.types.symbol_types.get(&field.id) != Some(&original.ty)
                {
                    return Err(fail());
                }
                Ok((field.id, owner.canonical.clone(), original.ty.clone()))
            }

            /// A `File[]` operand's declaration carries no default, server
            /// initializer or required array.
            fn file_array_declaration_ok(
                &self,
                key: NodeKey,
                model: SymbolId,
                field_id: SymbolId,
            ) -> Result<(), DisclosureDecline> {
                let data = self
                    .effects
                    .models
                    .get(&model)
                    .and_then(|model| model.fields.iter().find(|data| data.field == field_id))
                    .ok_or_else(|| {
                        self.fail(
                            key,
                            "File[] call input needs original stored parameter member",
                        )
                    })?;
                if data.default.is_some() || data.server.is_some() || data.required_array {
                    return Err(self.fail(
                        key,
                        "File[] call input needs original stored parameter member",
                    ));
                }
                Ok(())
            }

            fn input_value(
                &self,
                key: NodeKey,
                module: ModuleId,
                calls: &[NodeKey],
                mut value: ValuePath,
            ) -> Result<ValuePath, DisclosureDecline> {
                if value.record.is_some()
                    && matches!(value.reference_origin, Some(ReferenceOrigin::Field { .. }))
                    && self
                        .query_group(key)
                        .and_then(|key| {
                            self.checked_scalar_reference(ScalarReferenceKind::Profile, key, module)
                                .or_else(|| {
                                    self.checked_scalar_reference(ScalarReferenceKind::Run, key, module)
                                })
                        })
                        .is_some()
                {
                    return Err(self.fail(
                        key,
                        "Profile reference needs its direct original scalar member",
                    ));
                }
                if let Some(binding) = value.current_revision
                    && (!calls.is_empty()
                        || !matches!(self.query_binding(key),Some(Binding::Let {node}) if *node==binding)
                        || !self.current_revision_at(key, module).is_some_and(|fact| {
                            fact.binding == binding && value.record == Some(fact.revision)
                        }))
                {
                    return Err(self.fail(key, "current Revision needs its original lexical binding"));
                }
                if let Some((parameter, parameter_name, scalar)) = value.input.take() {
                    let intrinsic = self.intrinsic(
                        key,
                        module,
                        calls,
                        DisclosureIntrinsicKind::AdmittedInput {
                            parameter,
                            parameter_name,
                        },
                        scalar,
                    )?;
                    value.join(&intrinsic);
                }
                Ok(value)
            }

            fn operation_context(&self, mut key: NodeKey) -> bool {
                for _ in 0..64 {
                    let Some(node) = self.nodes.get(&key) else {
                        return false;
                    };
                    if node.kind != SyntaxKind::Group {
                        return node.kind == SyntaxKind::NameRef
                            && matches!(
                                self.resolve.node_binding.get(&key),
                                Some(Binding::Context(ContextVar::Operation))
                            );
                    }
                    let mut children = node.children.iter().filter(|child| expression(child.kind));
                    let Some(child) = children.next() else {
                        return false;
                    };
                    if children.next().is_some() {
                        return false;
                    }
                    key = NodeKey::of(child);
                }
                false
            }

            fn intrinsic(
                &self,
                node: NodeKey,
                module: ModuleId,
                calls: &[NodeKey],
                kind: DisclosureIntrinsicKind,
                scalar: Scalar,
            ) -> Result<ValuePath, DisclosureDecline> {
                Ok(ValuePath {
                    intrinsics: vec![DisclosureIntrinsic {
                        id: self.opaque("intrinsic-data", node, &self.call_stamp(calls)?)?,
                        source: self.source(module, node)?,
                        node,
                        calls: calls.to_vec(),
                        role: DependencyRole::Data,
                        kind,
                        ty: ResolvedType::Scalar(scalar),
                        type_id: scalar.as_str().to_string(),
                    }],
                    observed: vec![(node, calls.to_vec())],
                    ..ValuePath::default()
                })
            }

            fn word(&self, node: &SyntaxNode) -> Option<&'a str> {
                let name = if node.kind == SyntaxKind::NameRef {
                    node.children
                        .iter()
                        .find(|child| child.kind == SyntaxKind::Name)?
                } else {
                    node
                };
                self.db
                    .get(name.span.file)?
                    .text
                    .get(name.span.start as usize..name.span.end as usize)
            }

            /// Shorthand entries have a checked lexical binding on their key token,
            /// rather than an invented expression node/type.
            fn lexical(
                &self,
                key: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                if self.types.resolved_cases.contains(&key)
                    && matches!(
                        self.types.node_types.get(&key),
                        Some(ResolvedType::Enum { .. })
                    )
                {
                    return Ok(vec![ValuePath::default()]);
                }
                let local = match self.resolve.node_binding.get(&key) {
                    Some(Binding::Symbol(id)) => Local::Symbol(*id),
                    Some(Binding::Let { node }) => Local::Let(*node),
                    Some(Binding::CreateAs { node }) => Local::Create(*node),
                    Some(Binding::ForItem { node }) => Local::For(*node),
                    Some(Binding::SendAs { node }) => Local::Send(*node),
                    Some(Binding::CallAs { .. }) => {
                        return Err(self.fail(
                            key,
                            "bound child result consumption needs its owning provenance",
                        ));
                    }
                    None if self.types.resolved_cases.contains(&key) => {
                        return Ok(vec![ValuePath::default()]);
                    }
                    _ => return Err(self.fail(key, "unsupported shorthand binding")),
                };
                let value = env
                    .get(&local)
                    .cloned()
                    .ok_or_else(|| self.fail(key, "missing shorthand provenance"))?;
                if value.record.is_some()
                    && value
                        .first_query
                        .is_some_and(|(_, binding)| local != Local::Let(binding))
                {
                    return Err(self.fail(key, "copied first query row binding"));
                }
                if value
                    .current_revision
                    .is_some_and(|binding| local != Local::Let(binding))
                {
                    return Err(self.fail(key, "copied current Revision binding"));
                }
                Ok(vec![self.input_value(key, module, calls, value)?])
            }

            fn object(
                &mut self,
                (key, node): (NodeKey, &SyntaxNode),
                ty: &ResolvedType,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                schema: Option<String>,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let fields = self.object_fields(key, ty, schema.as_deref())?;
                if fields.len() > 200 {
                    return Err(self.fail(key, "object field bound"));
                }
                let mut paths = vec![ValuePath {
                    members: Some(Vec::new()),
                    schema,
                    ..ValuePath::default()
                }];
                let mut seen = HashSet::new();
                for entry in node
                    .children
                    .iter()
                    .filter(|child| child.kind == SyntaxKind::ObjectEntry)
                {
                    self.object_entry(key, entry, module, env, calls, &fields, &mut seen, &mut paths)?;
                }
                for (name, field_ty) in &fields {
                    if seen.contains(name) {
                        continue;
                    }
                    let literal_default = if let ResolvedType::Record {symbol, ..} = ty {
                        self.effects.records.get(symbol).filter(|record| record.record == *symbol
                            && self.resolve.symbols.get(symbol.0 as usize).is_some_and(|symbol|matches!(symbol.kind,SymbolKind::Contract{..})))
                            .and_then(|record| record.fields.iter().find(|field|
                                self.resolve.symbols.get(field.field.0 as usize).is_some_and(|declaration|
                                    declaration.name == *name && matches!(declaration.kind,SymbolKind::Field{owner,..} if owner == *symbol))))
                            .filter(|field| field.server.is_none() && !field.required_array)
                            .and_then(|field| field.default)
                            .is_some_and(|default| self.declared_constructor_default(default, field_ty, 0, &mut 0).is_some())
                    } else { false };
                    if !matches!(
                        field_ty,
                        ResolvedType::Nullable(_) | ResolvedType::Array { .. }
                    ) && !literal_default {
                        return Err(self.fail(key, "missing required checked object field"));
                    }
                    for path in &mut paths {
                        path.members
                            .as_mut()
                            .unwrap()
                            .push((name.clone(), ValuePath::default()));
                    }
                }
                self.bounded(key, paths)
            }

            /// Resolve an object's declared fields: text-schema fields or the
            /// owning Contract's fields.
            fn object_fields(
                &self,
                key: NodeKey,
                ty: &ResolvedType,
                schema: Option<&str>,
            ) -> Result<Vec<(String, ResolvedType)>, DisclosureDecline> {
                if let Some(fields) = checked_text_schema_fields(ty, schema) {
                    return Ok(fields.to_vec());
                }
                if let ResolvedType::Record { symbol, .. } = ty {
                    let declaration = self
                        .resolve
                        .symbols
                        .get(symbol.0 as usize)
                        .ok_or_else(|| self.fail(key, "missing object Contract declaration"))?;
                    let SymbolKind::Contract { fields } = &declaration.kind else {
                        return Err(self.fail(key, "object needs its owning Contract"));
                    };
                    return fields
                        .iter()
                        .map(|field| {
                            let field = self.resolve.symbols.get(field.0 as usize)?;
                            (matches!(field.kind, SymbolKind::Field {owner, ..} if owner == *symbol)).then(
                                || {
                                    Some((
                                        field.name.clone(),
                                        self.types.symbol_types.get(&field.id)?.clone(),
                                    ))
                                },
                            )?
                        })
                        .collect::<Option<Vec<_>>>()
                        .ok_or_else(|| self.fail(key, "object Contract fields disagree with owner"));
                }
                Err(self.fail(key, "unsupported object type"))
            }

            /// Check one object entry against the declared fields and join its
            /// value alternatives into the evaluation paths.
            #[allow(clippy::too_many_arguments)]
            fn object_entry(
                &mut self,
                key: NodeKey,
                entry: &SyntaxNode,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                fields: &[(String, ResolvedType)],
                seen: &mut HashSet<String>,
                paths: &mut Vec<ValuePath>,
            ) -> Result<(), DisclosureDecline> {
                let key_node = entry
                    .children
                    .first()
                    .filter(|child| child.kind == SyntaxKind::Name)
                    .ok_or_else(|| self.fail(key, "missing object key anchor"))?;
                let name = self
                    .word(key_node)
                    .ok_or_else(|| self.fail(key, "missing object key"))?;
                if !fields.iter().any(|(field, _)| field == name) || !seen.insert(name.to_string()) {
                    return Err(self.fail(key, "object fields disagree with checked shape"));
                }
                let value = entry.children.iter().find(|child| expression(child.kind));
                let alternatives = match value {
                    Some(value) => self.expr(NodeKey::of(value), module, env, calls)?,
                    None => self.lexical(NodeKey::of(key_node), module, env, calls)?,
                };
                if alternatives
                    .iter()
                    .any(|value| value.record.is_some() || value.delivery.is_some())
                {
                    return Err(self.fail(key, "opaque object member"));
                }
                if paths.len().saturating_mul(alternatives.len()) > 1024 {
                    return Err(self.fail(key, "object evaluation path bound"));
                }
                let mut next = Vec::new();
                for path in &*paths {
                    for value in &alternatives {
                        if !compatible(&path.decisions, &value.decisions) {
                            continue;
                        }
                        let mut joined = path.clone();
                        joined.join(value);
                        joined
                            .members
                            .as_mut()
                            .unwrap()
                            .push((name.to_string(), value.clone()));
                        next.push(joined);
                    }
                }
                *paths = next;
                Ok(())
            }

            fn proof(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                kind: DisclosureEffectKind,
            ) -> Result<(), DisclosureDecline> {
                let proof = DisclosureEffect {
                    node: effect.node,
                    source: self.source(module, effect.node)?,
                    kind,
                };
                if let Some(prior) = self
                    .effect_proofs
                    .iter()
                    .find(|prior| prior.node == effect.node)
                {
                    if prior != &proof {
                        return Err(self.fail(effect.node, "conflicting checked effect proof"));
                    }
                } else {
                    if self.effect_proofs.len() >= 200 {
                        return Err(self.fail(effect.node, "effect proof bound"));
                    }
                    self.effect_proofs.push(proof);
                }
                Ok(())
            }

            /// The original empty constructor uses State-owned literal integer defaults.
            /// Other model/default/lifetime profiles retain their whole-decline boundary.
            fn literal_root_model(
                &self,
                model: SymbolId,
                module: ModuleId,
                anchor: NodeKey,
            ) -> Result<(SymbolId, Vec<DisclosureCreateDefault>), DisclosureDecline> {
                let (crud, fields) = self.root_model_crud(model, module, anchor)?;
                let mut defaults = Vec::new();
                for field in fields {
                    defaults.push(self.root_model_default(model, module, anchor, field)?);
                }
                Ok((crud, defaults))
            }

            /// A root literal model's CRUD gate: a Team model whose fields match
            /// the checked model exactly, with no hooks or extras.
            fn root_model_crud(
                &self,
                model: SymbolId,
                module: ModuleId,
                anchor: NodeKey,
            ) -> Result<(SymbolId, &[super::effects::FieldData]), DisclosureDecline> {
                let fail = || self.fail(anchor, "root literal integer model profile required");
                let symbol = self
                    .resolve
                    .symbols
                    .get(model.0 as usize)
                    .ok_or_else(fail)?;
                let SymbolKind::Model {
                    fields,
                    owner: ModelOwner::Team,
                    crud: Some(crud),
                } = &symbol.kind
                else {
                    return Err(fail());
                };
                let data = self.effects.models.get(&model).ok_or_else(fail)?;
                if symbol.id != model || symbol.module != module || data.model != model || data.module != module
                    || data.owner != ModelOwner::Team || fields.is_empty() || fields.len() > 200
                    || !fields.iter().copied().eq(data.fields.iter().map(|field| field.field))
                    || !data.invariants.is_empty() || !data.uniques.is_empty() || !data.locks.is_empty()
                    || !data.retains.is_empty()
                {
                    return Err(fail());
                }
                self.root_model_crud_ok(model, module, anchor, *crud)?;
                Ok((*crud, &data.fields))
            }

            /// A root literal model's CRUD gate matches the model with no
            /// pending `when` and no hook claimant.
            fn root_model_crud_ok(
                &self,
                model: SymbolId,
                module: ModuleId,
                anchor: NodeKey,
                crud: SymbolId,
            ) -> Result<(), DisclosureDecline> {
                let fail = || self.fail(anchor, "root literal integer model profile required");
                let crud_data = self.effects.cruds.get(&crud).ok_or_else(fail)?;
                if crud_data.crud != crud || crud_data.model != model
                    || crud_data.module != module || crud_data.when.is_some()
                    || !self.root_model_hook_free(model)
                {
                    return Err(fail());
                }
                Ok(())
            }

            /// A root literal model has no hook scenario claiming it.
            fn root_model_hook_free(&self, model: SymbolId) -> bool {
                !self.effects.scenarios.values().any(|scenario| {
                    matches!(&scenario.on, Some(HandlerSource::Hook {model: target, ..}) if *target == model)
                })
            }

            /// One root literal model field's default: a literal integer in
            /// field span checking as `Int`.
            fn root_model_default(
                &self,
                model: SymbolId,
                module: ModuleId,
                anchor: NodeKey,
                field: &super::effects::FieldData,
            ) -> Result<DisclosureCreateDefault, DisclosureDecline> {
                let fail = || self.fail(anchor, "root literal integer model profile required");
                let owned = self
                    .resolve
                    .symbols
                    .get(field.field.0 as usize)
                    .ok_or_else(fail)?;
                if !matches!(owned.kind, SymbolKind::Field {owner, ..} if owner == model)
                    || owned.module != module
                    || field.server.is_some()
                    || field.required_array
                    || !field.modifiers.is_empty()
                    || self.types.symbol_types.get(&field.field)
                        != Some(&ResolvedType::Scalar(Scalar::Int))
                {
                    return Err(fail());
                }
                let default = field.default.ok_or_else(fail)?;
                let node = self.nodes.get(&default).ok_or_else(fail)?;
                if node.kind != SyntaxKind::Literal
                    || self.types.node_types.get(&default) != Some(&ResolvedType::Scalar(Scalar::Int))
                    || default.file != field.node.file
                    || default.start < field.node.start
                    || default.end > field.node.end
                {
                    return Err(fail());
                }
                let integer = node
                    .children
                    .iter()
                    .find(|child| child.kind == SyntaxKind::Integer)
                    .ok_or_else(fail)?;
                let source = self.db.get(default.file).ok_or_else(fail)?;
                let value = source
                    .text
                    .get(integer.span.start as usize..integer.span.end as usize)
                    .and_then(|text| text.parse::<i128>().ok())
                    .ok_or_else(fail)?;
                self.source(module, default)?;
                Ok(DisclosureCreateDefault {
                    field: field.field,
                    default,
                    value,
                })
            }

            /// A create's legacy constructor/default proof: kept only for
            /// input-free creates over a literal root model with a CRUD gate.
            fn create_legacy_crud(
                &mut self,
                checked: &CheckedScenarioCreate,
                model: SymbolId,
                module: ModuleId,
                node: NodeKey,
            ) -> (Option<SymbolId>, Vec<DisclosureCreateDefault>) {
                if !checked.inputs.is_empty() {
                    return (None, Vec::new());
                }
                match self.literal_root_model(model, module, node) {
                    Ok((crud, defaults))
                        if self
                            .effects
                            .cruds
                            .get(&crud)
                            .is_some_and(|data| data.create) =>
                    {
                        (Some(crud), defaults)
                    }
                    _ => (None, Vec::new()),
                }
            }

            /// One create input's evaluation paths: author attribution, lexical
            /// or expression alternatives joined onto every path.
            #[allow(clippy::too_many_arguments)]
            fn create_input_paths(
                &mut self,
                node: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                model: SymbolId,
                input: &CheckedScenarioCreateInput,
                paths: Vec<ValuePath>,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                // The authored creator attribution is evaluated by the genuine
                // scenario context. It is not a stored-field observation or grant.
                let alternatives = if self.admitted_actor_default(input.value_node, &input.ty) {
                    vec![ValuePath::default()]
                } else if input.value_node == input.key_node {
                    self.lexical(input.key_node, module, env, calls)?
                } else {
                    self.expr(input.value_node, module, env, calls)?
                };
                let mut next = Vec::new();
                for path in paths {
                    for value in &alternatives {
                        if let Some(binding) = value.current_revision {
                            self.create_revision_check(input, model, module, binding)?;
                        }
                        let value = self.input_value(input.value_node, module, calls, value.clone())?;
                        let mut joined = path.clone();
                        joined.join(&value);
                        next.push(joined);
                    }
                }
                self.bounded(node, next)
            }

            /// A create input carrying a current Revision must be its exact
            /// `Run.revision` input through the original `let` binding.
            fn create_revision_check(
                &self,
                input: &CheckedScenarioCreateInput,
                model: SymbolId,
                module: ModuleId,
                binding: NodeKey,
            ) -> Result<(), DisclosureDecline> {
                let fail = || {
                    self.fail(
                        input.value_node,
                        "current Revision needs its exact Run.revision Create input",
                    )
                };
                let fact = self
                    .current_revision_at(input.value_node, module)
                    .ok_or_else(fail)?;
                let owner = self
                    .resolve
                    .symbols
                    .get(model.0 as usize)
                    .ok_or_else(fail)?;
                let field = input
                    .field
                    .and_then(|field| self.resolve.symbols.get(field.0 as usize))
                    .ok_or_else(fail)?;
                if fact.binding != binding
                    || !matches!(owner.kind, SymbolKind::Model { .. })
                    || input.name != field.name
                    || !matches!(field.kind,SymbolKind::Field {owner,..} if owner==model)
                    || !matches!(self.query_binding(input.value_node),Some(Binding::Let {node}) if *node==binding)
                    || input.ty
                        != (ResolvedType::Record {
                            symbol: fact.revision,
                            stored: true,
                        })
                {
                    return Err(fail());
                }
                Ok(())
            }

            fn create(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<(SymbolId, Vec<ValuePath>), DisclosureDecline> {
                let decline = self.fail(
                    effect.node,
                    "checked bound scenario create profile required",
                );
                let fail = || decline.clone();
                let checked = self
                    .checked_create_source(effect, module)
                    .ok_or_else(fail)?;
                let model = checked.model;
                // Branch-arm creates prove conditionally: only `statements` arm
                // recursion raises statement_depth past 1 (loops use loop_node, call
                // frames use calls), so If/Match-arm nesting is admitted here while
                // the receipt tail rule narrowly admits only captured conditional
                // shapes — every other nested tail keeps its loud refusal there.
                if self.loop_node.is_some() || !calls.is_empty() {
                    return Err(fail());
                }
                // Retain the accepted legacy constructor/default proof. Other checked
                // scenario creates use the owning declaration, not a public CRUD gate.
                let (crud, defaults) =
                    self.create_legacy_crud(&checked, model, module, effect.node);
                let mut paths = vec![ValuePath::default()];
                for input in &checked.inputs {
                    paths = self.create_input_paths(
                        effect.node,
                        module,
                        env,
                        calls,
                        model,
                        input,
                        paths,
                    )?;
                }
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Create {
                        model,
                        crud,
                        binding: checked.binding,
                        defaults,
                        inputs: checked.inputs,
                    },
                )?;
                Ok((model, paths))
            }

            fn delete(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<(), DisclosureDecline> {
                let refusal = self.fail(effect.node, "direct root archive profile required");
                let fail = || refusal.clone();
                let node = *self.nodes.get(&effect.node).ok_or_else(fail)?;
                let Some(EffectTarget::Record { model: Some(model) }) = effect.target else {
                    return Err(fail());
                };
                let receiver = node
                    .children
                    .iter()
                    .find(|child| child.kind == SyntaxKind::Path)
                    .ok_or_else(fail)?;
                let key = NodeKey::of(receiver);
                let parameter = match self.query_binding(key) {
                    Some(Binding::Symbol(parameter)) => *parameter,
                    _ => return Err(fail()),
                };
                let Some(SymbolKind::Param { owner, .. }) = self
                    .resolve
                    .symbols
                    .get(parameter.0 as usize)
                    .map(|symbol| &symbol.kind)
                else {
                    return Err(fail());
                };
                if !self.effects.scenarios.get(owner).is_some_and(|scenario| {
                    scenario
                        .params
                        .iter()
                        .any(|input| input.param == parameter && input.default.is_none())
                }) {
                    return Err(fail());
                }
                if node.kind != SyntaxKind::Delete
                    || self.statement_depth != 1
                    || self.loop_node.is_some()
                    || !calls.is_empty()
                    || effect.when.is_some()
                    || !effect.args.is_empty()
                    || !matches!(
                        self.resolve
                            .symbols
                            .get(parameter.0 as usize)
                            .map(|symbol| &symbol.kind),
                        Some(SymbolKind::Param { .. })
                    )
                    || self.types.symbol_types.get(&parameter)
                        != Some(&ResolvedType::Record {
                            symbol: model,
                            stored: true,
                        })
                    || self.expr(key, module, env, calls)?.iter().any(|value| {
                        value.record != Some(model)
                            || !matches!(value.reference_origin, Some(ReferenceOrigin::Parameter(original)) if original == parameter)
                    })
                {
                    return Err(fail());
                }
                let (crud, _) = self.literal_root_model(model, module, effect.node)?;
                if !self
                    .effects
                    .cruds
                    .get(&crud)
                    .is_some_and(|data| data.delete && data.delete_mode == DeleteMode::Archive)
                {
                    return Err(fail());
                }
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Delete {
                        model,
                        crud,
                        receiver: key,
                    },
                )
            }

            /// SET references consume an original required input/reference or the
            /// immediately preceding checked constructor. Copies remain refused.
            fn set_reference_value(
                &self,
                effect: &Effect,
                module: ModuleId,
                key: NodeKey,
                model: SymbolId,
                value: &ValuePath,
            ) -> bool {
                value.record == Some(model)
                    && value.delivery.is_none()
                    && value.members.is_none()
                    && (matches!(value.reference_origin,
                        Some(ReferenceOrigin::Parameter(parameter))
                        if self.original_call_model_parameter(key, effect.node, module) == Some((parameter, model)))
                        || matches!(value.model_result,
                            Some(DisclosureModelResult::Reference {model: actual, node, source_model, field})
                            if actual == model && node == key
                                && self.checked_required_model_reference(key,module) == Some((source_model,field,model))
                                && key.file == effect.node.file && effect.node.start <= key.start && key.end <= effect.node.end
                                && value.reads.iter().any(|read|read.node==key&&read.model==source_model&&read.field==field
                                    && read.ty==ResolvedType::Record {symbol:model,stored:true}
                                    &&read.calls.is_empty()&&read.query_id.is_none()))
                        || matches!(value.model_result,
                            Some(DisclosureModelResult::Create { model: actual, node })
                            if actual == model && (self.preceding_call_create(effect, module, key, model, node)
                                || self.preceding_set_create(effect, module, key, model, node)))
                        || matches!(value.model_result,
                            Some(DisclosureModelResult::Call { model: actual, node, .. })
                            if actual == model && self.preceding_set_call(effect, module, key, node)))
            }

            /// A conditional constructor may populate a reference only in
            /// its own original arm, immediately after that constructor.
            /// Branch dominance comes from the current flow's CreateAs value;
            /// this syntax join also excludes copies and intervening effects.
            fn preceding_set_create(&self, effect: &Effect, module: ModuleId,
                key: NodeKey, model: SymbolId, created: NodeKey) -> bool {
                let Some(node) = self.nodes.get(&key) else { return false; };
                if !matches!(node.kind, SyntaxKind::Name | SyntaxKind::NameRef)
                    || !matches!(self.query_binding(key), Some(Binding::CreateAs { node }) if *node == created)
                { return false; }
                let mut pending = self.effects.scenarios.values().filter(|scenario|
                    scenario.module == module && scenario.node.file == effect.node.file
                        && scenario.node.start <= effect.node.start && effect.node.end <= scenario.node.end)
                    .map(|scenario| scenario.effects.as_slice()).collect::<Vec<_>>();
                if pending.len() != 1 { return false; }
                let mut visited = 0;
                while let Some(statements) = pending.pop() {
                    visited += 1;
                    if visited > 200 { return false; }
                    if let Some(position) = statements.iter().position(|statement| statement.node == effect.node) {
                        let Some(previous) = position.checked_sub(1).and_then(|index| statements.get(index)) else { return false; };
                        let Some(original) = self.checked_create_source(previous, module) else { return false; };
                        return previous.verb == EffectVerb::Create && previous.node == created
                            && original.model == model && self.word(node) == Some(original.binding.as_str());
                    }
                    for statement in statements {
                        if statement.verb == EffectVerb::If {
                            pending.push(statement.then_effects.as_slice());
                            pending.push(statement.else_effects.as_slice());
                        }
                    }
                }
                false
            }

            fn set_reference_type(&self, ty: &ResolvedType, calls: &[NodeKey]) -> Option<SymbolId> {
                let ResolvedType::Record { symbol, stored: true } = ty else {
                    return None;
                };
                (calls.is_empty() && self.loop_node.is_none() && self.effects.models.contains_key(symbol))
                    .then_some(*symbol)
            }

            fn set_uses_scalar_inventory(&self, ty: &ResolvedType, calls: &[NodeKey]) -> bool {
                !matches!(ty, ResolvedType::Delivery { .. } | ResolvedType::StdDelivery { .. }
                    | ResolvedType::Scalar(Scalar::File)) && self.set_reference_type(ty, calls).is_none()
            }

            /// A SET consumes exactly one declared carrier family; scalar fields never
            /// inherit row, delivery or object authority from their expression.
            fn set_value_matches(&self, effect: &Effect, module: ModuleId, key: NodeKey,
                declared: &ResolvedType, calls: &[NodeKey], value: &ValuePath) -> bool {
                let base = if let ResolvedType::Nullable(inner) = declared { inner.as_ref() } else { declared };
                // Clearing an optional stored reference issues no row identity.
                // The exact original null literal retains the target's nullable
                // schema; ordinary SET permissions and final staging still apply.
                if matches!(declared, ResolvedType::Nullable(inner)
                    if matches!(inner.as_ref(), ResolvedType::Record { symbol, stored: true }
                        if self.effects.models.contains_key(symbol)))
                    && calls.is_empty() && self.loop_node.is_none()
                    && key.file == effect.node.file && effect.node.start <= key.start && key.end <= effect.node.end
                    && self.nodes.get(&key).is_some_and(|node| node.kind == SyntaxKind::Literal && self.word(node) == Some("null"))
                    && self.types.node_types.get(&key) == Some(&ResolvedType::Null)
                    && value == &ValuePath::default()
                { return true; }
                if matches!(declared,ResolvedType::Nullable(inner)
                    if matches!(inner.as_ref(),ResolvedType::Record {stored:true,..}))
                    && calls.is_empty() && self.loop_node.is_none()
                    && self.set_nullable_reference_input(effect,module,key,declared,value)
                { return true; }
                if let Some(model) = self.set_reference_type(base, calls) {
                    self.set_reference_value(effect, module, key, model, value)
                } else if matches!(base, ResolvedType::Delivery { .. } | ResolvedType::StdDelivery { .. }) {
                    value.delivery.as_ref() == Some(base)
                } else {
                    value.delivery.is_none() && value.record.is_none() && value.members.is_none()
                }
            }

            /// A nullable model SET transports the original admitted slot,
            /// including null. It neither issues a required row/version nor
            /// promotes a copy, field traversal or constructor to that slot.
            fn set_nullable_reference_input(&self, effect: &Effect, module: ModuleId,
                key: NodeKey, declared: &ResolvedType, value: &ValuePath) -> bool {
                let Some(node) = self.nodes.get(&key) else { return false; };
                if !matches!(node.kind,SyntaxKind::Name | SyntaxKind::NameRef)
                    || value.delivery.is_some() || value.members.is_some()
                    || !value.reads.is_empty() || !value.intrinsics.is_empty()
                    || !value.decisions.is_empty() || !value.influences.is_empty()
                    || !value.observed.is_empty() || value.first_query.is_some()
                    || value.current_revision.is_some() || value.model_result.is_some()
                    || value.reference.is_some() || value.input.is_some() || value.schema.is_some()
                    || value.query_child.is_some() || value.transcript_messages.is_some()
                    || value.transcript_count || value.contract_value.is_some()
                { return false; }
                let Some(Binding::Symbol(parameter)) = self.query_binding(key) else { return false; };
                let Some(SymbolKind::Param {owner,..}) = self.resolve.symbols.get(parameter.0 as usize).map(|symbol|&symbol.kind)
                    else { return false; };
                let Some(scenario) = self.effects.scenarios.get(owner) else { return false; };
                let Some(input) = scenario.params.iter().find(|input|input.param==*parameter) else { return false; };
                let ResolvedType::Nullable(inner) = declared else { return false; };
                let ResolvedType::Record {symbol:model,stored:true} = inner.as_ref() else { return false; };
                let Some(named) = self.model_param_declared(input,true) else { return false; };
                let Some(path) = named.children.iter().find(|node|node.kind==SyntaxKind::Path) else {return false;};
                let Some(model_decl) = self.resolve.symbols.get(model.0 as usize) else {return false;};
                let Some(source)=self.db.get(path.span.file) else {return false;};
                if !matches!(model_decl.kind,SymbolKind::Model {..})
                    || !matches!(self.resolve.node_typeref.get(&NodeKey::of(path)),Some(TypeRef::Symbol(actual)) if actual==model)
                    || super::path_segments(path,&source.text) != [model_decl.name.as_str()]
                    || self.types.value_constraints.contains_key(parameter)
                    || self.types.field_reuse_sources.contains_key(parameter)
                    || (input.default.is_some() && !self.model_param_default_ok(input,true))
                {return false;}
                scenario.module == module && !scenario.read && scenario.on.is_none()
                    && effect.node.file == scenario.node.file
                    && scenario.node.start <= effect.node.start && effect.node.end <= scenario.node.end
                    && key.file == effect.node.file && effect.node.start <= key.start && key.end <= effect.node.end
                    && self.types.symbol_types.get(parameter) == Some(declared)
                    && self.types.node_types.get(&key) == Some(declared)
                    && value.record.is_none_or(|actual|actual==*model)
                    && value.reference_origin.is_none_or(|origin|origin==ReferenceOrigin::NullableParameter(*parameter))
            }

            /// Mutation paths have no nested Member AST. Retain every edge of
            /// the original required input's one- or two-hop containment path.
            /// Copies, nullable roots and stored-field navigation stay separate.
            fn set_parent_receiver(
                &self,
                effect: &Effect,
                module: ModuleId,
                receiver: &SyntaxNode,
                model: SymbolId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Option<ValuePath> {
                if !calls.is_empty() || self.loop_node.is_some() {
                    return None;
                }
                let names = receiver.children.iter()
                    .filter(|child| child.kind == SyntaxKind::Name).collect::<Vec<_>>();
                let (root, parents) = names.split_first()?;
                if parents.is_empty() || parents.len() > 2
                    || parents.iter().any(|parent| self.word(parent) != Some("parent")) { return None; }
                let Binding::Symbol(parameter) = self.query_binding(NodeKey::of(root))? else {
                    return None;
                };
                let declaration = self.resolve.symbols.get(parameter.0 as usize)?;
                let SymbolKind::Param { owner, .. } = declaration.kind else { return None; };
                let scenario = self.effects.scenarios.get(&owner)?;
                let input = scenario.params.iter().find(|input| input.param == *parameter)?;
                let ResolvedType::Record { symbol: child, stored: true } =
                    self.types.symbol_types.get(parameter)? else { return None; };
                let value = env.get(&Local::Symbol(*parameter))?;
                if scenario.module != module || input.default.is_some()
                    || declaration.name != self.word(root)?
                    || scenario.node.file != effect.node.file
                    || scenario.node.start > effect.node.start || scenario.node.end < effect.node.end
                    || value.record != Some(*child)
                    || value.reference_origin != Some(ReferenceOrigin::Parameter(*parameter))
                { return None; }
                let key = NodeKey::of(receiver);
                if self.types.node_types.get(&key) != Some(&ResolvedType::Record { symbol: model, stored: true }) { return None; }
                let mut result = value.clone();
                let mut child = *child;
                for (index, parent) in parents.iter().enumerate() {
                    let child_decl = self.resolve.symbols.get(child.0 as usize)?;
                    let SymbolKind::Model { owner: ModelOwner::ChildOf(actual), fields, .. } =
                        &child_decl.kind else { return None; };
                    if fields.iter().any(|id| self.resolve.symbols.get(id.0 as usize)
                        .is_none_or(|field| field.name == "parent"))
                        || self.effects.models.get(&child)?.owner != ModelOwner::ChildOf(*actual)
                    { return None; }
                    // Path syntax has no nested Member nodes. The evaluated IR
                    // still has each original prefix, so retain each edge read.
                    let edge = NodeKey { file: key.file, start: key.start, end: parent.span.end,
                        kind: if index + 1 == parents.len() { key.kind } else { SyntaxKind::Member as u8 } };
                    let ty = ResolvedType::Record { symbol: *actual, stored: true };
                    result.reads.push(DisclosureDependency {
                        query_id: None,
                        id: self.opaque("read-data", edge, &self.call_stamp(calls).ok()?).ok()?,
                        source: self.source(module, edge).ok()?, node: edge, calls: Vec::new(),
                        role: DependencyRole::Data, model: child, field: child,
                        model_name: child_decl.canonical.clone(), field_name: "parent".into(),
                        type_id: self.reference_operand_type_id(&ty)?, ty,
                    });
                    result.observed.push((edge, Vec::new()));
                    child = *actual;
                }
                if child != model { return None; }
                result.record = Some(model);
                result.reference = None;
                result.reference_origin = Some(ReferenceOrigin::Parent {
                    parameter: *parameter, model, depth: parents.len() as u8,
                });
                Some(result)
            }

            /// A set's target and receiver: the checked stored model, its
            /// fields, the receiver key and the receiver's evaluated paths.
            fn set_target_receiver(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                node: &SyntaxNode,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<(SymbolId, Vec<SymbolId>, NodeKey, Vec<ValuePath>), DisclosureDecline> {
                let Some(EffectTarget::Record { model: Some(model) }) = &effect.target else {
                    return Err(self.fail(effect.node, "set needs checked stored target"));
                };
                let model = *model;
                let owner = self
                    .resolve
                    .symbols
                    .get(model.0 as usize)
                    .ok_or_else(|| self.fail(effect.node, "missing set model"))?;
                let SymbolKind::Model { fields, .. } = &owner.kind else {
                    return Err(self.fail(effect.node, "set target is not a model"));
                };
                if owner.module != module {
                    return Err(self.fail(effect.node, "foreign set model"));
                }
                let receiver = node
                    .children
                    .iter()
                    .find(|child| child.kind == SyntaxKind::Path)
                    .ok_or_else(|| self.fail(effect.node, "missing direct set receiver"))?;
                if let Some(parent) = self.set_parent_receiver(effect, module, receiver, model, env, calls) {
                    return Ok((model, fields.to_vec(), NodeKey::of(receiver), vec![parent]));
                }
                if receiver
                    .children
                    .iter()
                    .filter(|child| child.kind == SyntaxKind::Name)
                    .count()
                    != 1
                    || !matches!(self.types.node_types.get(&NodeKey::of(receiver)), Some(ResolvedType::Record {symbol,stored:true}) if *symbol == model)
                {
                    return Err(self.fail(effect.node, "set needs nonnullable direct stored receiver"));
                }
                // A set may target a bound child result row: consume its owning
                // evaluated provenance in this flow, preserving caller, transaction
                // and order. Other CallAs uses keep their existing refusal.
                let receiver_key = NodeKey::of(receiver);
                let bound_call = self
                    .resolve
                    .node_binding
                    .get(&receiver_key)
                    .or_else(|| {
                        receiver
                            .children
                            .iter()
                            .find_map(|child| self.resolve.node_binding.get(&NodeKey::of(child)))
                    })
                    .and_then(|binding| match binding {
                        Binding::CallAs { node } => Some(*node),
                        _ => None,
                    });
                let paths = match bound_call {
                    Some(node) => vec![env.get(&Local::Call(node)).cloned().ok_or_else(|| {
                        self.fail(
                            receiver_key,
                            "bound child result consumption needs its owning provenance",
                        )
                    })?],
                    None => self.expr(receiver_key, module, env, calls)?,
                };
                if paths.iter().any(|path| path.record != Some(model)) {
                    return Err(self.fail(effect.node, "set receiver lacks binding provenance"));
                }
                Ok((model, fields.to_vec(), receiver_key, paths))
            }

            /// One set argument's field: a distinct checked stored field with its
            /// declared type.
            fn set_argument_field(
                &self,
                model: SymbolId,
                fields: &[SymbolId],
                written: &[SymbolId],
                arg: &super::effects::EffectArg,
            ) -> Result<(SymbolId, ResolvedType), DisclosureDecline> {
                let field = fields
                    .iter()
                    .filter_map(|id| self.resolve.symbols.get(id.0 as usize))
                    .find(|field| field.name == arg.key)
                    .ok_or_else(|| self.fail(arg.key_node, "unowned set field"))?;
                if !matches!(field.kind, SymbolKind::Field {owner,..} if owner == model)
                    || written.contains(&field.id)
                {
                    return Err(self.fail(arg.key_node, "set needs distinct checked stored fields"));
                }
                let ty = self
                    .types
                    .symbol_types
                    .get(&field.id)
                    .ok_or_else(|| self.fail(arg.key_node, "missing set field type"))?;
                Ok((field.id, ty.clone()))
            }

            /// One set argument's scalar inventory: reference arrays pass
            /// through, other arrays refuse, scalars check their field type.
            #[allow(clippy::too_many_arguments)]
            fn set_scalar_inventory(
                &self,
                module: ModuleId,
                calls: &[NodeKey],
                model: SymbolId,
                field_id: SymbolId,
                ty: &ResolvedType,
                arg: &super::effects::EffectArg,
            ) -> Result<(), DisclosureDecline> {
                let base = match ty {
                    ResolvedType::Nullable(inner) => inner.as_ref(),
                    ty => ty,
                };
                if !self.set_uses_scalar_inventory(base, calls) {
                    return Ok(());
                }
                let source_reference_array = matches!(ty, ResolvedType::Array { .. })
                    && calls.is_empty() && self.loop_node.is_none()
                    && arg.value.is_some_and(|value| {
                        self.types.node_types.get(&value) == Some(ty)
                            && self.source_require_reference_array(value, module).is_some()
                    })
                    && self.effects.models.get(&model).is_some_and(|owner| {
                        owner.fields.iter().any(|declaration| declaration.field == field_id)
                    });
                let key = arg.value.unwrap_or(arg.key_node);
                let admitted_answers = matches!(ty, ResolvedType::Array { element, ordered: true, nonempty: false }
                    if element.as_ref() == &ResolvedType::Scalar(Scalar::Text))
                    && calls.is_empty() && self.loop_node.is_none()
                    && self.query_binding(key).is_some_and(|binding| match binding {
                        Binding::Symbol(parameter) => self.effects.scenarios.values().any(|scenario|
                            scenario.module == module && scenario.params.iter().any(|param|
                                param.param == *parameter && param.default.is_none()
                                    && self.types.symbol_types.get(parameter) == Some(ty))
                                && self.checked_source_requires(scenario).is_some_and(|sites| !sites.is_empty())),
                        _ => false,
                    });
                if source_reference_array || admitted_answers {
                    return Ok(());
                }
                if matches!(base, ResolvedType::Array { .. }) {
                    return Err(self.fail(arg.key_node, "set array outside scalar effect profile"));
                }
                self.field_type_id(arg.key_node, field_id, ty)?;
                Ok(())
            }

            /// One set argument's values: file assignments through their input,
            /// otherwise the value expression or lexical entry.
            #[allow(clippy::too_many_arguments)]
            fn set_argument_values(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                receiver_key: NodeKey,
                field_id: SymbolId,
                file: bool,
                arg: &super::effects::EffectArg,
                file_inputs: &mut Vec<DisclosureFileInput>,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                if !file {
                    let key = arg.value.unwrap_or(arg.key_node);
                    if let Some(Binding::CallAs { node }) = self.query_binding(key) {
                        let value = env.get(&Local::Call(*node)).cloned().ok_or_else(|| {
                            self.fail(key, "bound child result lacks its original evaluated call")
                        })?;
                        return Ok(vec![self.input_value(key, module, calls, value)?]);
                    }
                    return match arg.value {
                        Some(value) => self.expr(value, module, env, calls),
                        None => self.lexical(arg.key_node, module, env, calls),
                    };
                }
                let value = arg.value.ok_or_else(|| {
                    self.fail(
                        arg.key_node,
                        "File assignment needs explicit original input",
                    )
                })?;
                file_inputs.push(self.file_assignment_input(
                    effect.node,
                    module,
                    env,
                    calls,
                    (receiver_key, field_id, value),
                )?);
                Ok(vec![ValuePath::default()])
            }

            fn set(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let node = *self
                    .nodes
                    .get(&effect.node)
                    .ok_or_else(|| self.fail(effect.node, "missing set anchor"))?;
                if node.kind != SyntaxKind::Set || effect.when.is_some() {
                    return Err(self.fail(effect.node, "unsupported set shape"));
                }
                let (model, fields, receiver_key, mut paths) =
                    self.set_target_receiver(effect, module, node, env, calls)?;
                let mut written = Vec::new();
                let mut file_inputs = Vec::new();
                for arg in &effect.args {
                    let (field_id, ty) =
                        self.set_argument_field(model, &fields, &written, arg)?;
                    let base = match &ty {
                        ResolvedType::Nullable(inner) => inner.as_ref(),
                        ty => ty,
                    };
                    let file = matches!(base, ResolvedType::Scalar(Scalar::File));
                    self.set_scalar_inventory(module, calls, model, field_id, &ty, arg)?;
                    let values = self.set_argument_values(
                        effect,
                        module,
                        env,
                        calls,
                        receiver_key,
                        field_id,
                        file,
                        arg,
                        &mut file_inputs,
                    )?;
                    if values.iter().any(|value| !self.set_value_matches(effect, module,
                        arg.value.unwrap_or(arg.key_node), &ty, calls, value)) {
                        return Err(self.fail(arg.key_node, "set carrier or scalar provenance mismatch"));
                    }
                    paths = self.product(effect.node, &paths, &values)?;
                    written.push(field_id);
                }
                if written.is_empty() {
                    return Err(self.fail(effect.node, "empty set profile"));
                }
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Set {
                        model,
                        fields: written,
                        file_inputs,
                    },
                )?;
                Ok(paths)
            }

            /// Source correspondence only. The installed Files producer supplies the
            /// genuine finalized observation to the owning active root invocation.
            fn file_assignment_input(
                &self,
                statement: NodeKey,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                assignment: (NodeKey, SymbolId, NodeKey),
            ) -> Result<DisclosureFileInput, DisclosureDecline> {
                let (receiver, field, value) = assignment;
                let fail = || self.fail(value, "File assignment needs original required root input");
                if !calls.is_empty()
                    || self.loop_node.is_some()
                    || self
                        .nodes
                        .get(&value)
                        .is_none_or(|node| node.kind != SyntaxKind::NameRef)
                    || self.types.node_types.get(&value) != Some(&ResolvedType::Scalar(Scalar::File))
                {
                    return Err(fail());
                }
                let (parameter, owner, parent, param) = self.file_input_parameter(value)?;
                let (receiver_parameter, field_owner, declaration) =
                    self.file_input_receiver(receiver, field, value)?;
                if !self.file_input_parent_ok(statement, module, value, parent, param)
                    || !self.file_input_value_ok(
                        parameter,
                        field,
                        owner,
                        receiver_parameter,
                        declaration,
                        parent,
                        env,
                    )
                {
                    return Err(fail());
                }
                self.source(module, value)?;
                Ok(DisclosureFileInput {
                    field,
                    parameter,
                    value,
                })
            }

            /// A file input's source parameter: a scenario parameter of the
            /// owning scenario, with its scenario owner, scenario and data.
            fn file_input_parameter(
                &self,
                value: NodeKey,
            ) -> Result<
                (
                    SymbolId,
                    SymbolId,
                    &super::effects::ScenarioData,
                    &super::effects::ParamData,
                ),
                DisclosureDecline,
            > {
                let fail = || self.fail(value, "File assignment needs original required root input");
                let Some(Binding::Symbol(parameter)) = self.query_binding(value) else {
                    return Err(fail());
                };
                let parameter = *parameter;
                let Some(SymbolKind::Param { owner, .. }) = self
                    .resolve
                    .symbols
                    .get(parameter.0 as usize)
                    .map(|symbol| &symbol.kind)
                else {
                    return Err(fail());
                };
                let owner = *owner;
                let parent = self.effects.scenarios.get(&owner).ok_or_else(fail)?;
                let param = parent
                    .params
                    .iter()
                    .find(|param| param.param == parameter)
                    .ok_or_else(fail)?;
                Ok((parameter, owner, parent, param))
            }

            /// A file input's parent scope: the owning scenario admits the
            /// statement and value spans with a default-free `File` parameter.
            fn file_input_parent_ok(
                &self,
                statement: NodeKey,
                module: ModuleId,
                value: NodeKey,
                parent: &super::effects::ScenarioData,
                param: &super::effects::ParamData,
            ) -> bool {
                !parent.read
                    && parent.on.is_none()
                    && parent.cohort.is_none()
                    && !parent.scope_authority
                    && parent.module == module
                    && statement.file == parent.node.file
                    && statement.start >= parent.node.start
                    && statement.end <= parent.node.end
                    && value.file == statement.file
                    && value.start >= statement.start
                    && value.end <= statement.end
                    && param.default.is_none()
                    && self.direct_builtin_parameter_type(param.type_node, Scalar::File)
            }

            /// A file input's value scope: exact `File` types without reuse, a
            /// live parameter, and a default-free receiver parameter of the same
            /// scenario owning the declared field.
            #[allow(clippy::too_many_arguments)]
            fn file_input_value_ok(
                &self,
                parameter: SymbolId,
                field: SymbolId,
                owner: SymbolId,
                receiver_parameter: SymbolId,
                declaration: &super::effects::FieldData,
                parent: &super::effects::ScenarioData,
                env: &Env,
            ) -> bool {
                self.types.symbol_types.get(&parameter) == Some(&ResolvedType::Scalar(Scalar::File))
                    && !self.types.field_reuse_sources.contains_key(&parameter)
                    && !self.types.field_reuse_sources.contains_key(&field)
                    && !declaration.required_array
                    && env.contains_key(&Local::Symbol(parameter))
                    && matches!(self.resolve.symbols.get(receiver_parameter.0 as usize).map(|symbol| &symbol.kind),
                        Some(SymbolKind::Param { owner: receiver_owner, .. }) if *receiver_owner == owner)
                    && parent
                        .params
                        .iter()
                        .any(|param| param.param == receiver_parameter && param.default.is_none())
            }

            /// A file input's receiver: a scenario parameter whose field owner
            /// declares the assigned field.
            fn file_input_receiver(
                &self,
                receiver: NodeKey,
                field: SymbolId,
                value: NodeKey,
            ) -> Result<(SymbolId, SymbolId, &super::effects::FieldData), DisclosureDecline> {
                let fail = || self.fail(value, "File assignment needs original required root input");
                let Some(Binding::Symbol(receiver_parameter)) = self.query_binding(receiver) else {
                    return Err(fail());
                };
                let field_owner = match self
                    .resolve
                    .symbols
                    .get(field.0 as usize)
                    .map(|symbol| &symbol.kind)
                {
                    Some(SymbolKind::Field { owner, .. }) => *owner,
                    _ => return Err(fail()),
                };
                let declaration = self
                    .effects
                    .models
                    .get(&field_owner)
                    .and_then(|model| {
                        model
                            .fields
                            .iter()
                            .find(|candidate| candidate.field == field)
                    })
                    .ok_or_else(fail)?;
                Ok((*receiver_parameter, field_owner, declaration))
            }

            fn send(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<(Vec<ValuePath>, Option<ResolvedType>), DisclosureDecline> {
                let node = *self
                    .nodes
                    .get(&effect.node)
                    .ok_or_else(|| self.fail(effect.node, "missing send anchor"))?;
                let text = &self
                    .db
                    .get(effect.node.file)
                    .ok_or_else(|| self.fail(effect.node, "missing send source"))?
                    .text;
                // SEND stores `when = expr` as direct statement children, unlike a
                // declaration's Attribute node. Match that original parser shape.
                let parts = super::kids(node);
                let mut authored_when = parts
                    .windows(3)
                    .filter(|parts| {
                        super::is_name(parts[0], text, "when")
                            && super::is_punct(parts[1], text, "=")
                            && expression(parts[2].kind)
                    })
                    .map(|parts| NodeKey::of(parts[2]));
                let source_when = authored_when.next();
                if node.kind != SyntaxKind::Send
                    || authored_when.next().is_some()
                    || source_when != effect.when
                {
                    return Err(self.fail(effect.node, "checked send source mismatch"));
                }
                if let Some(when) = effect.when {
                    self.send_when_site(effect, module, when)?;
                }
                let target = node
                    .children
                    .iter()
                    .find(|child| expression(child.kind))
                    .ok_or_else(|| self.fail(effect.node, "missing send target"))?;
                let (head, member) = if target.kind == SyntaxKind::Member {
                    let head = target
                        .children
                        .iter()
                        .find(|child| expression(child.kind))
                        .ok_or_else(|| self.fail(effect.node, "missing send import head"))?;
                    let member = target
                        .children
                        .iter()
                        .rev()
                        .find(|child| child.kind == SyntaxKind::Name)
                        .and_then(|child| self.word(child))
                        .ok_or_else(|| self.fail(effect.node, "missing send member"))?;
                    (head, Some(member))
                } else {
                    (target, None)
                };
                if head.kind != SyntaxKind::NameRef {
                    return Err(self.fail(effect.node, "unsupported send target head"));
                }
                let alias = self
                    .word(head)
                    .ok_or_else(|| self.fail(effect.node, "missing send alias"))?;
                let host = self
                    .resolve
                    .modules
                    .get(module.0 as usize)
                    .ok_or_else(|| self.fail(effect.node, "missing importing module"))?;
                let imports: Vec<_> = host
                    .imports
                    .iter()
                    .flat_map(|import| {
                        import
                            .members
                            .iter()
                            .filter(|item| item.alias == alias)
                            .map(move |item| (import, item))
                    })
                    .collect();
                if imports.len() > 1 {
                    return Err(self.fail(effect.node, "ambiguous send import"));
                }
                let binding = self.types.target_bindings.get(&NodeKey::of(head));
                let sink = send_sink(
                    self.types
                        .runtime_bindings
                        .get(&module)
                        .map(Vec::as_slice)
                        .unwrap_or(&[]),
                    &effect.target,
                    &alias,
                    member,
                );
                let optional_sink_inputs = sink
                    .as_ref()
                    .map(|(_, _, optional)| optional.clone())
                    .unwrap_or_default();
                let (operation, deployment_binding, delivery, input_names) = self.send_operation(
                    effect,
                    binding,
                    sink,
                    &imports,
                    &host.name,
                    &alias,
                    member,
                )?;
                let paths = self.send_input_paths(
                    effect,
                    module,
                    env,
                    calls,
                    &delivery,
                    &input_names,
                    &optional_sink_inputs,
                )?;
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Send {
                        operation,
                        deployment_binding,
                        when: effect.when,
                    },
                )?;
                Ok((paths, effect.binding.as_ref().map(|_| delivery)))
            }

            /// A send's `when` dispatch site: the durable Rule lifetime keeps its
            /// exact checked source site without evaluating it as a parent selector.
            /// (This was the `if let Some(when)` block: false still yields the
            /// original skipped delivery and continues.)
            fn send_when_site(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                when: NodeKey,
            ) -> Result<(), DisclosureDecline> {
                // Dispatch happens in the durable Rule lifetime. Retain its exact
                // checked source site without evaluating it as a parent selector:
                // false still yields the original skipped delivery and continues.
                let mut owners = self.effects.scenarios.values().filter(|scenario| {
                    scenario.module == module
                        && scenario.node.file == effect.node.file
                        && scenario.node.start <= effect.node.start
                        && effect.node.end <= scenario.node.end
                });
                let owner = owners
                    .next()
                    .ok_or_else(|| self.fail(when, "missing send dispatch source owner"))?;
                if owners.next().is_some()
                    || self.types.node_types.get(&when) != Some(&ResolvedType::Scalar(Scalar::Bool))
                {
                    return Err(self.fail(when, "checked Boolean send dispatch required"));
                }
                let sites = self
                    .checked_decision_sites(owner)
                    .ok_or_else(|| self.fail(when, "missing checked send dispatch source site"))?;
                let mut matching = sites.iter().filter(|site| {
                    site.stage == CheckedDecisionStage::SendDispatch && site.statement == effect.node
                });
                let site = matching
                    .next()
                    .ok_or_else(|| self.fail(when, "missing original send dispatch source site"))?;
                if matching.next().is_some()
                    || site.owner != owner.scenario
                    || site.node != when
                    || site.source != self.source(module, effect.node)?
                    || when.file != effect.node.file
                    || when.start < effect.node.start
                    || when.end > effect.node.end
                {
                    return Err(self.fail(when, "send dispatch source correspondence"));
                }
                Ok(())
            }

            /// A send's operation, deployment binding, delivery type, and input
            /// names: sink shortcut, external std capability, or declared operation.
            /// (This was the `match binding` with its sink, external, and declared
            /// operation arms.)
            fn send_operation(
                &self,
                effect: &Effect,
                binding: Option<&Binding>,
                sink: Option<(&str, Vec<String>, Vec<String>)>,
                imports: &[(&super::resolve::Import, &super::resolve::ImportMember)],
                host_name: &str,
                alias: &str,
                member: Option<&str>,
            ) -> Result<(String, Option<String>, ResolvedType, Vec<String>), DisclosureDecline> {
                match binding {
                    None if sink.is_some() && imports.is_empty() => {
                        let (op, inputs, _) = sink.unwrap();
                        Ok((
                            format!("{host_name}.{alias}.{op}"),
                            Some(format!("{host_name}.{alias}")),
                            super::types::sink_delivery_type(),
                            inputs,
                        ))
                    }
                    Some(Binding::External { provider, name }) => {
                        let (import, item) = imports
                            .first()
                            .copied()
                            .ok_or_else(|| self.fail(effect.node, "missing external send import"))?;
                        if provider != "std"
                            || &import.provider != provider
                            || &item.name != name
                            || import.from.is_none()
                        {
                            return Err(self.fail(effect.node, "external send import provenance mismatch"));
                        }
                        let cap = std_capability(name)
                            .ok_or_else(|| self.fail(effect.node, "unowned external capability"))?;
                        let op = member
                            .and_then(|member| std_operation(cap.name, member))
                            .ok_or_else(|| self.fail(effect.node, "unowned external operation"))?;
                        Ok((
                            format!("{}.{}", cap.name, op.name),
                            Some(format!("{host_name}.{alias}")),
                            ResolvedType::StdDelivery {
                                capability: cap.name,
                                op,
                            },
                            op.inputs
                                .iter()
                                .map(|(name, _)| name.to_string())
                                .collect::<Vec<_>>(),
                        ))
                    }
                    _ => {
                        let Some(EffectTarget::Operation(id)) = &effect.target else {
                            return Err(self.fail(effect.node, "unsupported send operation"));
                        };
                        let operation = self
                            .resolve
                            .symbols
                            .get(id.0 as usize)
                            .ok_or_else(|| self.fail(effect.node, "missing send declaration"))?;
                        let SymbolKind::CapabilityOp { params, .. } = &operation.kind else {
                            return Err(self.fail(effect.node, "send target is not capability operation"));
                        };
                        let deployment = if let Some((import, item)) = imports.first().copied() {
                            let Some(Binding::Symbol(head_id)) = binding else {
                                return Err(self.fail(effect.node, "unestablished send import binding"));
                            };
                            let head_symbol = self
                                .resolve
                                .symbols
                                .get(head_id.0 as usize)
                                .ok_or_else(|| self.fail(effect.node, "missing send import declaration"))?;
                            let expected_head = format!("{}.{}", import.provider, item.name);
                            let expected = member
                                .map(|member| format!("{expected_head}.{member}"))
                                .unwrap_or_else(|| expected_head.clone());
                            if head_symbol.canonical != expected_head || operation.canonical != expected {
                                return Err(self.fail(effect.node, "send declaration import mismatch"));
                            }
                            import
                                .from
                                .as_ref()
                                .map(|_| format!("{host_name}.{alias}"))
                        } else {
                            None
                        };
                        Ok((
                            operation.canonical.clone(),
                            deployment,
                            ResolvedType::Delivery { op: *id },
                            params
                                .iter()
                                .map(|id| self.resolve.symbols[id.0 as usize].name.clone())
                                .collect::<Vec<_>>(),
                        ))
                    }
                }
            }

            /// A send's checked input paths: complete slots, no duplicates, no
            /// opaque delivery/record values.
            /// (This was the required-inputs computation plus the argument product
            /// loop.)
            fn send_input_paths(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                delivery: &ResolvedType,
                input_names: &[String],
                optional_sink_inputs: &[String],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let required_inputs = match delivery {
                    ResolvedType::StdDelivery { op, .. } => op
                        .inputs
                        .iter()
                        // Same T14/B9 source rule as types::std_send_requires_input:
                        // ordinary std arrays omit to empty in the owning supplier;
                        // their required wire key is not an authored binding slot.
                        .filter(|(_, declared)| {
                            !declared
                                .strip_suffix('?')
                                .unwrap_or(declared)
                                .ends_with("[]")
                        })
                        .map(|(name, _)| *name)
                        .collect::<Vec<_>>(),
                    _ => input_names
                        .iter()
                        .filter(|name| !optional_sink_inputs.contains(name))
                        .map(String::as_str)
                        .collect(),
                };
                if required_inputs
                    .iter()
                    .any(|name| !effect.args.iter().any(|arg| arg.key == *name))
                    || effect
                        .args
                        .iter()
                        .any(|arg| !input_names.contains(&arg.key))
                {
                    return Err(self.fail(effect.node, "send needs complete checked input slots"));
                }
                let mut seen = HashSet::new();
                let mut paths = vec![ValuePath::default()];
                for arg in &effect.args {
                    if !seen.insert(&arg.key) {
                        return Err(self.fail(arg.key_node, "duplicate send input"));
                    }
                    let values = match arg.value {
                        Some(value) => self.expr(value, module, env, calls)?,
                        None => self.lexical(arg.key_node, module, env, calls)?,
                    };
                    if values
                        .iter()
                        .any(|value| value.delivery.is_some() || value.record.is_some())
                    {
                        return Err(self.fail(arg.key_node, "opaque send input"));
                    }
                    paths = self.product(effect.node, &paths, &values)?;
                }
                Ok(paths)
            }

            /// An external effect's event target and expected node kind.
            fn external_event_target(
                &self,
                effect: &Effect,
                module: ModuleId,
                node: &SyntaxNode,
            ) -> Result<(Option<SymbolId>, SyntaxKind), DisclosureDecline> {
                let event = match effect.verb {
                    EffectVerb::Emit | EffectVerb::Schedule => match &effect.target {
                        Some(EffectTarget::Event(event)) => Some(*event),
                        _ => {
                            return Err(self.fail(effect.node, "external effect needs its event target"));
                        }
                    },
                    EffectVerb::Cancel => None,
                    _ => return Err(self.fail(effect.node, "unsupported external effect")),
                };
                if let Some(event) = event {
                    let declaration = self
                        .resolve
                        .symbols
                        .get(event.0 as usize)
                        .ok_or_else(|| self.fail(effect.node, "missing external event declaration"))?;
                    if !matches!(declaration.kind, super::resolve::SymbolKind::Event { .. })
                        || declaration.module != module
                    {
                        return Err(self.fail(effect.node, "external effect needs its event target"));
                    }
                }
                let expected_kind = match effect.verb {
                    EffectVerb::Emit => SyntaxKind::Emit,
                    EffectVerb::Schedule => SyntaxKind::Schedule,
                    EffectVerb::Cancel => SyntaxKind::Cancel,
                    _ => return Err(self.fail(effect.node, "unsupported external effect")),
                };
                if node.kind != expected_kind {
                    return Err(self.fail(effect.node, "checked external effect mismatch"));
                }
                Ok((event, expected_kind))
            }

            /// One external effect schedule key: pure values joined onto the paths.
            fn external_effect_key(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                key: NodeKey,
                paths: Vec<ValuePath>,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let values = self.expr(key, module, env, calls)?;
                if values
                    .iter()
                    .any(|value| value.record.is_some() || value.delivery.is_some())
                {
                    return Err(self.fail(key, "opaque external effect input"));
                }
                self.product(effect.node, &paths, &values)
            }

            /// An event may carry the original required child input's checked
            /// parent reference when its declared field has that stored Model
            /// type. Member removal's AccessChanged.membership is the one
            /// admitted two-hop form; neither grants a parent-row read.
            fn external_effect_parent_reference(
                &self,
                event: SymbolId,
                module: ModuleId,
                argument: &super::effects::EffectArg,
                key: NodeKey,
                value: &ValuePath,
            ) -> Option<()> {
                let Some(ReferenceOrigin::Parent { parameter, model, depth }) =
                    value.reference_origin else {
                    return None;
                };
                if value.record != Some(model)
                    || value.first_query.is_some()
                    || value.model_result.is_some()
                    || value.delivery.is_some()
                    || value.members.is_some()
                    || value.query_child.is_some()
                {
                    return None;
                }
                let key = self.query_group(key)?;
                let (base, name) = self.count_member(key)?;
                let declaration = self.resolve.symbols.get(event.0 as usize)?;
                let two_parent_membership = depth == 2
                    && declaration.canonical == "member_terms.AccessChanged"
                    && argument.key == "membership"
                    && self.resolve.symbols.get(model.0 as usize)?.canonical == "member_terms.Membership"
                    && matches!(self.resolve.symbols.get(parameter.0 as usize)?.kind,
                        SymbolKind::Param { owner, .. }
                        if self.resolve.symbols.get(owner.0 as usize)
                            .is_some_and(|symbol| symbol.canonical == "member_terms.remove"))
                    && self.checked_call_parent_path(key, parameter, 0) == Some((model, 2));
                if name != "parent"
                    || !(depth == 1
                        && matches!(self.query_binding(base), Some(Binding::Symbol(actual)) if *actual == parameter)
                        || two_parent_membership)
                    || !matches!(self.resolve.symbols.get(parameter.0 as usize)?.kind,
                        SymbolKind::Param { .. })
                    || self.nodes.get(&argument.key_node)?.kind != SyntaxKind::Name
                    || self.word(self.nodes.get(&argument.key_node)?) != Some(argument.key.as_str())
                {
                    return None;
                }
                let SymbolKind::Event { fields } = &declaration.kind else {
                    return None;
                };
                if declaration.module != module {
                    return None;
                }
                let field = fields.iter().copied().find(|field| {
                    self.resolve.symbols.get(field.0 as usize)
                        .is_some_and(|symbol| symbol.name == argument.key)
                })?;
                let ty = self.types.symbol_types.get(&field)?;
                if !matches!(ty, ResolvedType::Record { symbol, stored: true } if *symbol == model)
                    || self.types.node_types.get(&key) != Some(ty)
                {
                    return None;
                }
                Some(())
            }

            /// Retain only an original singular required scenario argument in an
            /// exactly nominal owning Event field. This carries identity only;
            /// it grants neither a row/field read nor an arbitrary Model value.
            fn external_effect_parameter_reference(&self,effect:&Effect,event:SymbolId,
                module:ModuleId,argument:&super::effects::EffectArg,key:NodeKey,value:&ValuePath)->Option<()> {
                if !matches!(effect.verb,EffectVerb::Emit|EffectVerb::Schedule){return None;}
                let Some(ReferenceOrigin::Parameter(parameter))=value.reference_origin else{return None;};
                let model=value.record?;
                if value.first_query.is_some()||value.model_result.is_some()||value.delivery.is_some()
                    ||value.members.is_some()||value.query_child.is_some()
                    ||!matches!(self.query_binding(key),Some(Binding::Symbol(actual))if *actual==parameter)
                    ||!(self.original_reference_parameter(key,parameter)
                        ||argument.value.is_none()&&key==argument.key_node
                            &&self.nodes.get(&key).is_some_and(|node|node.kind==SyntaxKind::Name
                                &&self.word(node)==Some(argument.key.as_str()))){return None;}
                let SymbolKind::Param{owner,..}=self.resolve.symbols.get(parameter.0 as usize)?.kind else{return None;};
                let scenario=self.effects.scenarios.get(&owner)?;
                let input=scenario.params.iter().find(|input|input.param==parameter)?;
                if scenario.module!=module||input.default.is_some()
                    ||self.types.symbol_types.get(&parameter)!=Some(&ResolvedType::Record{symbol:model,stored:true}){return None;}
                let declaration=self.resolve.symbols.get(event.0 as usize)?;
                let SymbolKind::Event{fields}=&declaration.kind else{return None;};
                if declaration.module!=module{return None;}
                let field=fields.iter().find(|field|self.resolve.symbols.get(field.0 as usize)
                    .is_some_and(|field|field.name==argument.key))?;
                let input_ty=self.types.symbol_types.get(&parameter)?;
                let event_ty=self.types.symbol_types.get(field)?;
                // A required original identity can fill an optional slot of the
                // same Model; it still carries no nullable input or DATA grant.
                ((event_ty==input_ty||matches!(event_ty,ResolvedType::Nullable(inner)if inner.as_ref()==input_ty))
                    &&self.types.node_types.get(&key)==Some(input_ty)).then_some(())
            }

            /// An EMIT or SCHEDULE may carry its original owning CREATE binding. The
            /// checked lexical value supplies dominance; exact CreateAs/source
            /// facts pin identity. No caller-supplied or copied row qualifies.
            fn external_effect_created_reference(&self, effect: &Effect, event: SymbolId,
                module: ModuleId, argument: &super::effects::EffectArg,
                key: NodeKey, value: &ValuePath) -> Option<()> {
                if !matches!(effect.verb, EffectVerb::Emit | EffectVerb::Schedule) || self.loop_node.is_some() { return None; }
                let Some(DisclosureModelResult::Create { model, node }) = value.model_result else { return None; };
                if value.record != Some(model) || value.delivery.is_some() || value.members.is_some()
                    || value.first_query.is_some() || value.query_child.is_some()
                    || !matches!(self.query_binding(key), Some(Binding::CreateAs { node: original }) if *original == node)
                { return None; }
                let owner = self.effects.scenarios.values().find(|owner| owner.module == module
                    && owner.node.file == key.file && owner.node.start <= node.start
                    && node.end <= key.start && key.end <= owner.node.end)?;
                let sources = self.checked_create_sources(owner)?;
                let source = sources.iter().find(|source| source.node == node && source.model == model)?;
                if self.word(self.nodes.get(&key)?) != Some(source.binding.as_str()) { return None; }
                let declaration = self.resolve.symbols.get(event.0 as usize)?;
                let SymbolKind::Event { fields } = &declaration.kind else { return None; };
                if declaration.module != module { return None; }
                let field = fields.iter().find(|field| self.resolve.symbols.get(field.0 as usize)
                    .is_some_and(|field| field.name == argument.key))?;
                (self.types.symbol_types.get(field) == Some(&ResolvedType::Record { symbol: model, stored: true })
                    && self.types.node_types.get(&key) == self.types.symbol_types.get(field)).then_some(())
            }

            /// A bounded contained loop may emit its exact item identity to an
            /// exactly typed event field; this carries no arbitrary row value.
            fn external_effect_loop_reference(&self,event:SymbolId,argument:&super::effects::EffectArg,
                key:NodeKey,value:&ValuePath)->bool {
                let Some(loop_node)=self.loop_node else {return false;};
                let Some(model)=value.record else {return false;};
                let Some(SymbolKind::Event {fields})=self.resolve.symbols.get(event.0 as usize).map(|symbol|&symbol.kind)
                    else {return false;};
                matches!(self.query_binding(key),Some(Binding::ForItem {node}) if *node==loop_node)
                    && value.reads.is_empty() && value.intrinsics.is_empty() && value.decisions.is_empty()
                    && value.first_query.is_none() && value.model_result.is_none() && value.reference_origin.is_none()
                    && fields.iter().any(|field|self.resolve.symbols.get(field.0 as usize).is_some_and(|symbol|symbol.name==argument.key)
                        && self.types.symbol_types.get(field)==Some(&ResolvedType::Record {symbol:model,stored:true}))
            }

            /// One external effect argument: pure values joined onto the paths.
            fn external_effect_argument(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                event: Option<SymbolId>,
                argument: &super::effects::EffectArg,
                paths: Vec<ValuePath>,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let key = argument.value.unwrap_or(argument.key_node);
                let values = match argument.value {
                    Some(value) => self.expr(value, module, env, calls)?,
                    None => self.lexical(argument.key_node, module, env, calls)?,
                };
                if values.iter().any(|value| {
                    value.delivery.is_some() || value.members.is_some()
                        || value.record.is_some() && event.is_none_or(|event| {
                            (effect.verb != EffectVerb::Emit
                                || self.external_effect_parent_reference(event, module, argument, key, value).is_none())
                                && self.external_effect_parameter_reference(effect,event,module,argument,key,value).is_none()
                                && self.external_effect_created_reference(effect, event, module, argument, key, value).is_none()
                                && (effect.verb != EffectVerb::Emit
                                    || !self.external_effect_loop_reference(event,argument,key,value))
                        })
                }) {
                    return Err(self.fail(key, "opaque external effect input"));
                }
                self.product(effect.node, &paths, &values)
            }

            /// Durable owner effects (`emit`, `schedule`, `cancel`) evaluate their
            /// exact authored value operands once in source order and persist them
            /// in the owner transaction. Only pure value operands are admitted:
            /// record reads keep their own observation paths and never hide inside
            /// an event payload or schedule key.
            fn external_effect(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                if !calls.is_empty() {
                    return Err(self.fail(
                        effect.node,
                        "bound or nested operand call outside source profile",
                    ));
                }
                let node = self
                    .nodes
                    .get(&effect.node)
                    .ok_or_else(|| self.fail(effect.node, "missing external effect anchor"))?;
                let (event, _) = self.external_event_target(effect, module, node)?;
                let mut keys = vec![effect.key, effect.at, effect.value];
                let mut paths = vec![ValuePath::default()];
                for key in keys.drain(..).flatten() {
                    paths = self.external_effect_key(effect, module, env, calls, key, paths)?;
                }
                let payload_event = event.filter(|_| matches!(effect.verb, EffectVerb::Emit | EffectVerb::Schedule));
                for argument in &effect.args {
                    paths = self.external_effect_argument(effect, module, env, calls, payload_event, argument, paths)?;
                }
                let kind = match effect.verb {
                    EffectVerb::Emit => DisclosureEffectKind::Emit { event: event.unwrap() },
                    EffectVerb::Schedule => DisclosureEffectKind::Schedule { event: event.unwrap() },
                    _ => DisclosureEffectKind::Cancel {},
                };
                self.proof(effect, module, kind)?;
                Ok(paths)
            }

            /// Prepare the State-owned child lifetime; only direct cardinality uses of
            /// its exact returned wire can consume the bound result.
            fn static_call(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                if !calls.is_empty() {
                    return Err(self.fail(
                        effect.node,
                        "bound or nested operand call outside source profile",
                    ));
                }
                let target_node = effect
                    .target_node
                    .ok_or_else(|| self.fail(effect.node, "missing checked call operand"))?;
                let Some(EffectTarget::Operation(operation)) = &effect.target else {
                    return Err(self.fail(effect.node, "static mutation scenario call required"));
                };
                if self.types.node_types.get(&target_node) != Some(&ResolvedType::Operation(*operation)) {
                    return Err(self.fail(effect.node, "checked static call target mismatch"));
                }
                let child = self
                    .effects
                    .scenarios
                    .get(operation)
                    .ok_or_else(|| self.fail(effect.node, "call target is not a mutation scenario"))?
                    .clone();
                if child.read && child.on.is_none() {
                    return self.query_child_call(effect, module, env, calls, &child, *operation);
                }
                let child_model = self.complete_model_children.get(operation).copied();
                if (effect.binding.is_some() && child_model.is_none()) || child.on.is_some() {
                    return Err(self.fail(
                        effect.node,
                        "read or trusted child call outside source profile",
                    ));
                }
                let signature = self
                    .types
                    .symbol_results
                    .get(operation)
                    .ok_or_else(|| self.fail(effect.node, "missing child result signature"))?;
                if (signature.as_ref().is_some_and(|ty| !primitive_type(ty)) && child_model.is_none())
                    || self.types.effect_call_results.get(&effect.node) != Some(signature)
                {
                    return Err(self.fail(effect.node, "unsupported or mismatched child result"));
                }
                if !self.complete_children.contains(operation) {
                    return Err(self.fail(effect.node, "child needs complete acyclic source closure"));
                }
                if effect.args.len() != child.params.len() || child.params.len() > 200 {
                    return Err(self.fail(effect.node, "call requires complete authored inputs"));
                }
                let mut slots = HashMap::new();
                for parameter in &child.params {
                    let ty = self
                        .types
                        .symbol_types
                        .get(&parameter.param)
                        .ok_or_else(|| self.fail(effect.node, "missing child input type"))?;
                    let eligible = match ty {
                        ResolvedType::Scalar(scalar) => {
                            primitive_type(ty)
                                && self.explicit_scalar_call_parameter(parameter, &child, *scalar)
                        }
                        ResolvedType::Record { .. } | ResolvedType::Nullable(_) => {
                            self.explicit_model_call_parameter(parameter).is_some()
                                || self.explicit_nullable_value_call_parameter(parameter)
                        }
                        ResolvedType::Enum { .. } => self.explicit_enum_call_parameter(parameter),
                        ty if ordinary_file_array(ty) => self.explicit_file_array_call_parameter(parameter),
                        ty if matches!(ty, ResolvedType::Array { .. }) => {
                            self.explicit_array_call_parameter(parameter)
                        }
                        _ => false,
                    };
                    if !eligible {
                        return Err(self.fail(
                            effect.node,
                            "child input needs explicit checked declaration",
                        ));
                    }
                    let declaration = self
                        .resolve
                        .symbols
                        .get(parameter.param.0 as usize)
                        .ok_or_else(|| self.fail(effect.node, "missing child parameter identity"))?;
                    slots.insert(declaration.name.clone(), ty.clone());
                }
                let mut keys = Vec::new();
                let mut paths = vec![ValuePath::default()];
                for argument in &effect.args {
                    let expected = slots
                        .get(&argument.key)
                        .ok_or_else(|| self.fail(argument.key_node, "unowned child input"))?;
                    if keys.contains(&argument.key) {
                        return Err(self.fail(argument.key_node, "duplicate child input"));
                    }
                    let key = argument.value.unwrap_or(argument.key_node);
                    let parameter = child
                        .params
                        .iter()
                        .find(|parameter| {
                            self.resolve
                                .symbols
                                .get(parameter.param.0 as usize)
                                .is_some_and(|declaration| declaration.name == argument.key)
                        })
                        .ok_or_else(|| self.fail(key, "missing checked child slot"))?;
                    let model_slot = self.explicit_model_call_parameter(parameter);
                    // A supplied non-null value fills a nullable value slot exactly;
                    // stored-model nullables keep their own provenance rule above.
                    // Anything else (including null or a mismatched scalar) still
                    // refuses at the exact-type gate below.
                    let supplied_type = match (model_slot, expected) {
                        (Some((_, true)), ResolvedType::Nullable(inner)) => inner.as_ref(),
                        (None, ResolvedType::Nullable(inner))
                            if !matches!(
                                inner.as_ref(),
                                ResolvedType::Record { stored: true, .. }
                            ) && self.types.node_types.get(&key) == Some(inner.as_ref()) =>
                        {
                            inner.as_ref()
                        }
                        _ => expected,
                    };
                    if self.types.node_types.get(&key) != Some(supplied_type) {
                        return Err(self.fail(key, "child input lacks exact checked supplied type"));
                    }
                    let values = if ordinary_file_array(expected) {
                        self.call_file_array_operand(key, effect.node, module, calls)?
                    } else {
                        match argument.value {
                            Some(value) => self.expr(value, module, env, calls)?,
                            None => self.lexical(argument.key_node, module, env, calls)?,
                        }
                    };
                    if let Some((model, nullable)) = model_slot {
                        // Branch-nested calls keep the caller's original parameter
                        // value: shadowing still resolves through the lexical
                        // binding check below, and derived/call/loop positions stay
                        // refused. Only the top-level statement requirement is
                        // relaxed; the provenance proof is unchanged.
                        if !calls.is_empty() || self.loop_node.is_some() || self.statement_depth < 1 {
                            return Err(self.fail(key, "model call input needs original root occurrence"));
                        }
                        for value in &values {
                            let original = if nullable {
                                matches!(value.reference_origin,
                                    Some(ReferenceOrigin::Parent { parameter, model: actual, depth: 2 })
                                    if actual == model && self.checked_call_parent_path(key, parameter, 0) == Some((model, 2)))
                            } else {
                                matches!(value.reference_origin,
                                    Some(ReferenceOrigin::Parameter(parameter))
                                    if self.original_call_model_parameter(key, effect.node, module) == Some((parameter, model)))
                                    || matches!(value.model_result,
                                        Some(DisclosureModelResult::Create { model: actual, node })
                                        if actual == model && self.preceding_call_create(effect, module, key, model, node))
                                    || matches!(value.reference_origin,
                                        Some(ReferenceOrigin::Field { parameter, model: source, field })
                                        if self.nullable_field_call_branch(key, module).is_some_and(|(_, operand, original, owner, member, target)|
                                            operand == key && original == parameter && owner == source && member == field && target == model))
                                    // One `param.parent` hop into the required slot:
                                    // the base stays the caller's original required
                                    // model parameter and the hop is the checked
                                    // containment edge, never a copied row.
                                    || matches!(value.reference_origin,
                                        Some(ReferenceOrigin::Parent { parameter, model: actual, depth: 1 })
                                        if actual == model && self.original_call_parent_parameter(key, effect.node, module) == Some((parameter, model)))
                            };
                            if !original
                                || value.record != Some(model)
                                || value.delivery.is_some()
                                || value.members.is_some()
                            {
                                return Err(self.fail(key, "model child input lacks original provenance"));
                            }
                        }
                    } else if values.iter().any(|value| {
                        value.record.is_some() || value.delivery.is_some() || value.members.is_some()
                    }) {
                        return Err(self.fail(key, "opaque child input provenance"));
                    }
                    paths = self.product(effect.node, &paths, &values)?;
                    keys.push(argument.key.clone());
                }
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Call {
                        operation: *operation,
                        input_keys: keys,
                    },
                )?;
                if let Some(model) = child_model
                    && effect.binding.is_some()
                {
                    for path in &mut paths {
                        path.record = Some(model);
                        path.model_result = Some(DisclosureModelResult::Call {
                            model,
                            node: effect.node,
                            operation: *operation,
                        });
                    }
                }
                Ok(paths)
            }

            /// Original caller parameters, or their exact one-parent reference fields,
            /// prepare this finite read child. Keep actual source reads separately from
            /// candidate dependencies in the child's query lifetime.
            /// Resolve one query-child argument to its caller input: an exact
            /// original parent field operand or an original caller parameter.
            /// Returns the key, input, source field and child parameter.
            #[allow(clippy::too_many_arguments)]
            fn query_child_operand(
                &mut self,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                child: &super::effects::ScenarioData,
                argument: &super::effects::EffectArg,
                keys: &[String],
                evaluated: &mut ValuePath,
            ) -> Result<(NodeKey, SymbolId, Option<SymbolId>, SymbolId), DisclosureDecline> {
                let parameter = child
                    .params
                    .iter()
                    .find(|parameter| {
                        self.resolve
                            .symbols
                            .get(parameter.param.0 as usize)
                            .is_some_and(|symbol| symbol.name == argument.key)
                    })
                    .ok_or_else(|| self.fail(argument.key_node, "unowned query child input"))?;
                if keys.contains(&argument.key) || parameter.default.is_some() {
                    return Err(self.fail(
                        argument.key_node,
                        "query child needs explicit unique inputs",
                    ));
                }
                let key = argument.value.unwrap_or(argument.key_node);
                let member = self
                    .nodes
                    .get(&key)
                    .is_some_and(|node| node.kind == SyntaxKind::Member);
                let (input, source_field) = if member {
                    let values = self.expr(key, module, env, calls)?;
                    if values.len() != 1 {
                        return Err(self.fail(key, "query child reference operand path mismatch"));
                    }
                    let value = &values[0];
                    let Some(ReferenceOrigin::Field {
                        parameter,
                        model,
                        field,
                    }) = value.reference_origin
                    else {
                        return Err(
                            self.fail(key, "query child needs exact original parent field operand")
                        );
                    };
                    if value.reads.len() != 2
                        || !value
                            .reads
                            .iter()
                            .any(|read| read.model == model && read.field == field)
                    {
                        return Err(self.fail(key, "query child parent field source mismatch"));
                    }
                    evaluated.join(value);
                    (parameter, Some(field))
                } else {
                    let Some(Binding::Symbol(input)) = self.query_binding(key) else {
                        return Err(
                            self.fail(key, "query child needs original caller parameter operand")
                        );
                    };
                    (*input, None)
                };
                Ok((key, input, source_field, parameter.param))
            }

            /// Check one query-child input's owning parent scenario: same
            /// original nondefault parent as the other inputs.
            fn query_child_parent(
                &self,
                effect: &Effect,
                module: ModuleId,
                key: NodeKey,
                input: SymbolId,
                parent_owner: Option<SymbolId>,
            ) -> Result<SymbolId, DisclosureDecline> {
                let Some(SymbolKind::Param { owner, .. }) = self
                    .resolve
                    .symbols
                    .get(input.0 as usize)
                    .map(|symbol| &symbol.kind)
                else {
                    return Err(self.fail(
                        key,
                        "query child rejects copied or computed reference operands",
                    ));
                };
                let owner = *owner;
                let parent =
                    self.effects.scenarios.get(&owner).ok_or_else(|| {
                        self.fail(key, "query child input lacks owning parent scenario")
                    })?;
                if parent.read
                    || parent.on.is_some()
                    || parent.cohort.is_some()
                    || parent.scope_authority
                    || parent.module != module
                    || effect.node.file != parent.node.file
                    || effect.node.start < parent.node.start
                    || effect.node.end > parent.node.end
                    || parent_owner.is_some_and(|previous| previous != owner)
                    || !parent
                        .params
                        .iter()
                        .any(|param| param.param == input && param.default.is_none())
                {
                    return Err(self.fail(
                        key,
                        "query child input needs same original nondefault parent",
                    ));
                }
                Ok(owner)
            }

            /// Check one query-child input's type: the exact owning checked type,
            /// a stored record or a protected array owner.
            fn query_child_input_type(
                &self,
                key: NodeKey,
                input: SymbolId,
                source_field: Option<SymbolId>,
                child_param: SymbolId,
            ) -> Result<(), DisclosureDecline> {
                let expected = self
                    .types
                    .symbol_types
                    .get(&child_param)
                    .ok_or_else(|| self.fail(key, "missing query child input type"))?;
                if self.types.node_types.get(&key) != Some(expected)
                    || (source_field.is_none() && self.types.symbol_types.get(&input) != Some(expected))
                {
                    return Err(self.fail(key, "query child input needs exact owning checked type"));
                }
                match expected {
                    ResolvedType::Record { stored: true, .. } => Ok(()),
                    ResolvedType::Array { .. }
                        if source_field.map_or_else(
                            || {
                                self.query_parameter_bounds(input).is_some()
                                    && self.query_parameter_bounds(input)
                                        == self.query_parameter_bounds(child_param)
                            },
                            |field| self.reference_field_bounds(field, child_param),
                        ) =>
                    {
                        Ok(())
                    }
                    _ => Err(self.fail(
                        key,
                        "query child input lacks exact protected reference or array owner",
                    )),
                }
            }

            fn query_child_call(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
                child: &super::effects::ScenarioData,
                operation: SymbolId,
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                if !self.complete_children.contains(&operation) || self.complete_query(child)?.is_none() {
                    return Err(self.fail(
                        effect.node,
                        "read child needs complete acyclic finite query closure",
                    ));
                }
                if self.types.effect_call_results.get(&effect.node)
                    != self.types.symbol_results.get(&operation)
                    || effect.args.len() != child.params.len()
                {
                    return Err(self.fail(effect.node, "read child result or input signature mismatch"));
                }
                let mut keys = Vec::new();
                let mut parent_owner = None;
                let mut evaluated = ValuePath::default();
                for argument in &effect.args {
                    let (key, input, source_field, child_param) = self.query_child_operand(
                        module,
                        env,
                        calls,
                        child,
                        argument,
                        &keys,
                        &mut evaluated,
                    )?;
                    let owner = self.query_child_parent(
                        effect,
                        module,
                        key,
                        input,
                        parent_owner,
                    )?;
                    self.query_child_input_type(key, input, source_field, child_param)?;
                    parent_owner = Some(owner);
                    keys.push(argument.key.clone());
                }
                self.proof(
                    effect,
                    module,
                    DisclosureEffectKind::Call {
                        operation,
                        input_keys: keys,
                    },
                )?;
                evaluated.query_child = Some(operation);
                Ok(vec![evaluated])
            }

            /// A transition's receiver: one direct path resolving to a stored
            /// model matching the checked target.
            fn transition_receiver(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                node: &SyntaxNode,
            ) -> Result<(NodeKey, SymbolId), DisclosureDecline> {
                let mut receivers = node
                    .children
                    .iter()
                    .filter(|child| child.kind == SyntaxKind::Path);
                let receiver = receivers
                    .next()
                    .ok_or_else(|| self.fail(effect.node, "missing transition receiver"))?;
                if receivers.next().is_some()
                    || receiver
                        .children
                        .iter()
                        .filter(|child| child.kind == SyntaxKind::Name)
                        .count()
                        != 1
                {
                    return Err(self.fail(effect.node, "transition needs immutable direct receiver"));
                }
                let receiver_key = NodeKey::of(receiver);
                let model = match self.types.node_types.get(&receiver_key) {
                    Some(ResolvedType::Record {
                        symbol,
                        stored: true,
                    }) => *symbol,
                    Some(ResolvedType::Nullable(_)) => {
                        return Err(self.influence(
                            effect.node,
                            module,
                            &[InfluenceKind::AbsentReference],
                            "nullable transition receiver",
                        ));
                    }
                    _ => return Err(self.fail(effect.node, "unestablished transition receiver type")),
                };
                if !matches!(effect.target, Some(EffectTarget::Record { model: Some(target) }) if target == model)
                {
                    return Err(self.fail(effect.node, "transition checked target mismatch"));
                }
                Ok((receiver_key, model))
            }

            /// A transition's literal endpoints: field, from-case and to-case
            /// spellings.
            fn transition_endpoints(
                &self,
                effect: &Effect,
                node: &SyntaxNode,
            ) -> Result<(String, String, String), DisclosureDecline> {
                let names: Vec<_> = node
                    .children
                    .iter()
                    .filter(|child| child.kind == SyntaxKind::Name)
                    .collect();
                if names.len() != 4 {
                    return Err(self.fail(effect.node, "missing transition literal endpoints"));
                }
                let word = |node: &SyntaxNode| {
                    self.db.get(node.span.file).and_then(|source| {
                        source
                            .text
                            .get(node.span.start as usize..node.span.end as usize)
                    })
                };
                let field_name = word(names[1])
                    .ok_or_else(|| self.fail(effect.node, "missing transition field spelling"))?;
                let from =
                    word(names[2]).ok_or_else(|| self.fail(effect.node, "missing transition from case"))?;
                let to =
                    word(names[3]).ok_or_else(|| self.fail(effect.node, "missing transition to case"))?;
                Ok((
                    field_name.to_string(),
                    from.to_string(),
                    to.to_string(),
                ))
            }

            /// A transition's machine field: a stored enum field with a default
            /// and a `machine` modifier spanning both endpoint cases.
            fn transition_machine(
                &self,
                effect: &Effect,
                model: SymbolId,
                field_name: &str,
                from: &str,
                to: &str,
            ) -> Result<(SymbolId, String, String, String, ResolvedType), DisclosureDecline> {
                let owner = self
                    .resolve
                    .symbols
                    .get(model.0 as usize)
                    .ok_or_else(|| self.fail(effect.node, "missing transition model"))?;
                let SymbolKind::Model { fields, .. } = &owner.kind else {
                    return Err(self.fail(effect.node, "non-model transition owner"));
                };
                let field = fields
                    .iter()
                    .filter_map(|id| self.resolve.symbols.get(id.0 as usize))
                    .find(|field| field.name == field_name)
                    .ok_or_else(|| self.fail(effect.node, "missing transition field"))?;
                if !matches!(field.kind, SymbolKind::Field { owner, .. } if owner == model) {
                    return Err(self.fail(effect.node, "nonstored transition field"));
                }
                let declaration = self
                    .effects
                    .models
                    .get(&model)
                    .and_then(|owner| owner.fields.iter().find(|decl| decl.field == field.id))
                    .ok_or_else(|| self.fail(effect.node, "missing checked machine declaration"))?;
                if declaration.default.is_none()
                    || !declaration
                        .modifiers
                        .iter()
                        .any(|modifier| modifier.name == "machine" && modifier.value.is_none())
                {
                    return Err(self.fail(effect.node, "unestablished checked machine"));
                }
                let ty = self
                    .types
                    .symbol_types
                    .get(&field.id)
                    .ok_or_else(|| self.fail(effect.node, "missing checked machine type"))?;
                let ResolvedType::Enum { cases, .. } = ty else {
                    return Err(self.fail(effect.node, "machine needs scalar enum"));
                };
                if !cases.iter().any(|case| case == from) || !cases.iter().any(|case| case == to) {
                    return Err(self.fail(effect.node, "unestablished machine endpoints"));
                }
                Ok((
                    field.id,
                    field.canonical.clone(),
                    owner.canonical.clone(),
                    field.name.clone(),
                    ty.clone(),
                ))
            }

            fn transition(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                env: &Env,
                calls: &[NodeKey],
            ) -> Result<Vec<ValuePath>, DisclosureDecline> {
                let node = *self
                    .nodes
                    .get(&effect.node)
                    .ok_or_else(|| self.fail(effect.node, "missing transition anchor"))?;
                if node.kind != SyntaxKind::Transition || !effect.args.is_empty() {
                    return Err(self.fail(effect.node, "unsupported transition shape"));
                }
                let (receiver_key, model) = self.transition_receiver(effect, module, node)?;
                let (field_name, from, to) = self.transition_endpoints(effect, node)?;
                let (field_id, field_canonical, model_canonical, name, ty) =
                    self.transition_machine(effect, model, &field_name, &from, &to)?;
                let read = DisclosureDependency {
                    query_id: None,
                    id: self.opaque(
                        "transition-control",
                        effect.node,
                        &format!(
                            "{}:{}:{}:{}",
                            field_canonical, from, to,
                            self.call_stamp(calls)?
                        ),
                    )?,
                    source: self.source(module, effect.node)?,
                    node: effect.node,
                    calls: calls.to_vec(),
                    role: DependencyRole::Control,
                    model,
                    field: field_id,
                    model_name: model_canonical,
                    field_name: name,
                    ty: ty.clone(),
                    type_id: self.field_type_id(effect.node, field_id, &ty)?,
                };
                let mut paths = self.expr(receiver_key, module, env, calls)?;
                for value in &mut paths {
                    if value.record != Some(model) {
                        return Err(self.fail(effect.node, "transition receiver closure mismatch"));
                    }
                    *value = self.control(value.clone())?;
                    value.reads.push(read.clone());
                    value.observed.push((effect.node, calls.to_vec()));
                    value.record = None;
                }
                Ok(paths)
            }

            fn return_path(
                &self,
                node: NodeKey,
                module: ModuleId,
                flow: Flow,
                value: ValuePath,
            ) -> Result<DisclosureReturn, DisclosureDecline> {
                let mut merged = flow.controls;
                merged.join(&flow.writes);
                merged.join(&value);
                let mut observed = flow.observed;
                for read in &value.observed {
                    if !observed.contains(read) {
                        observed.push(read.clone());
                    }
                }
                merged.reads.sort_by_key(|read| {
                    observed
                        .iter()
                        .position(|entry| entry.0 == read.node && entry.1 == read.calls)
                        .unwrap_or(usize::MAX)
                });
                merged.intrinsics.sort_by_key(|intrinsic| {
                    observed
                        .iter()
                        .position(|entry| entry.0 == intrinsic.node && entry.1 == intrinsic.calls)
                        .unwrap_or(usize::MAX)
                });
                if merged
                    .reads
                    .len()
                    .saturating_add(merged.intrinsics.len())
                    .saturating_add(flow.repeated_observations)
                    > 200
                {
                    return Err(self.fail(node, "return dependency bound"));
                }
                let mut decisions = flow.evaluated;
                for decision in merged.decisions {
                    if !decisions.contains(&decision) {
                        decisions.push(decision);
                    }
                }
                merged.decisions = decisions;
                Ok(DisclosureReturn {
                    id: String::new(),
                    source: self.source(module, node)?,
                    node,
                    decisions: merged.decisions,
                    dependencies: merged.reads,
                    intrinsics: merged.intrinsics,
                    influences: merged.influences,
                    model_result: value.model_result,
                })
            }

            /// A finite original filter reads only the actual checked query
            /// alias's scalar fields. It opens no additional row navigation.
            fn bounded_loop_filter(&self, query: &super::types::CheckedQuery) -> Option<NodeKey> {
                let [alias, filter] = query.clauses.as_slice() else { return None; };
                let [predicate] = filter.expressions.as_slice() else { return None; };
                if !matches!(alias.kind, CheckedQueryClauseKind::As { .. }) || !alias.expressions.is_empty()
                    || filter.kind != CheckedQueryClauseKind::Where || query.projection.is_some()
                    || query.result != query.domain_type || self.types.node_types.get(predicate) != Some(&ResolvedType::Scalar(Scalar::Bool)) { return None; }
                let ResolvedType::Array {element,ordered:true,nonempty:false} = &query.domain_type else { return None; };
                let ResolvedType::Record {symbol:model,stored:true} = element.as_ref() else { return None; };
                self.bounded_item_condition(*predicate,*model,alias.node,true)?;
                Some(*predicate)
            }

            fn bounded_item_condition(&self, predicate: NodeKey, model: SymbolId,
                owner: NodeKey, query_alias: bool) -> Option<()> {
                let item = |key| match self.query_binding(key) {
                    Some(Binding::QueryAlias {node}) if query_alias => *node == owner,
                    Some(Binding::ForItem {node}) if !query_alias => *node == owner,
                    _ => false,
                };
                if self.types.node_types.get(&predicate) != Some(&ResolvedType::Scalar(Scalar::Bool)) { return None; }
                let mut pending = vec![predicate]; let mut count = 0;
                while let Some(key) = pending.pop() {
                    count += 1; if count > 1024 { return None; }
                    let node = self.nodes.get(&key)?;
                    if expression(node.kind) && !matches!(node.kind,SyntaxKind::Literal|SyntaxKind::NameRef
                        |SyntaxKind::Group|SyntaxKind::Member|SyntaxKind::Unary|SyntaxKind::Binary|SyntaxKind::Array) { return None; }
                    if node.kind == SyntaxKind::NameRef && !item(key) && !self.types.resolved_cases.contains(&key)
                        && !(query_alias && self.types.node_types.get(&key)==Some(&ResolvedType::Record{symbol:model,stored:true})
                            && matches!(self.query_binding(key),Some(Binding::Symbol(parameter))
                                if self.original_reference_parameter(key,*parameter))) { return None; }
                    if node.kind == SyntaxKind::Member {
                        let (base,name) = self.count_member(key)?;
                        if !item(base) { return None; }
                        let field = self.effects.models.get(&model)?.fields.iter().find(|field|
                            self.resolve.symbols.get(field.field.0 as usize).is_some_and(|symbol|symbol.name == name))?;
                        let ty = self.types.symbol_types.get(&field.field)?;
                        if self.types.node_types.get(&key) != Some(ty)
                            || !(primitive_type(ty) || matches!(ty,ResolvedType::Enum {..})) { return None; }
                    }
                    pending.extend(node.children.iter().map(NodeKey::of));
                }
                Some(())
            }

            /// A bounded sibling constructor retains its original prefix proof.
            /// Native emission must independently seal the complete source loop;
            /// this shape alone grants no collection or selected-row authority.
            fn bounded_sibling_create_loop(&mut self,effect:&Effect,module:ModuleId,flow:Flow,calls:&[NodeKey])->Result<Vec<Flow>,DisclosureDecline>{
                let fail=||self.fail(effect.node,"checked contained sibling constructor required");
                if !calls.is_empty()||self.loop_node.is_some()||effect.cond.is_some()||!effect.else_effects.is_empty()||!effect.match_arms.is_empty(){return Err(fail());}
                let [created]=effect.then_effects.as_slice()else{return Err(fail());};
                let owner=self.effects.scenarios.values().find(|owner|owner.module==module&&owner.effects.last().is_some_and(|last|last.node==effect.node)).ok_or_else(fail)?;
                if owner.result.is_some()||owner.on.is_some()||owner.read||created.verb!=EffectVerb::Create{return Err(fail());}
                let domain=effect.domain.ok_or_else(fail)?;
                let member=if let Some(query)=self.types.checked_queries.get(&domain){
                    if query.projection.is_some()||query.clauses.iter().any(|clause|!matches!(clause.kind,CheckedQueryClauseKind::As{..}|CheckedQueryClauseKind::Where)){return Err(fail());}
                    query.domain
                }else{domain};
                let (parameter,model)=self.original_loop_member_root(member,effect.node,module)?;
                let checked=self.checked_create_source(created,module).ok_or_else(fail)?;
                let [parent,fields @ ..]=checked.inputs.as_slice()else{return Err(fail());};
                let (root,parent_model)=self.original_call_model_parameter(parent.value_node,created.node,module).ok_or_else(fail)?;
                if parent.name!="parent"||root!=parameter||fields.is_empty()||fields.len()>200
                    ||self.effects.models.get(&checked.model).is_none_or(|definition|definition.owner!=ModelOwner::ChildOf(parent_model)) {return Err(fail());}
                let mut selected=false;
                for field in fields{
                    let item=matches!(self.query_binding(field.value_node),Some(Binding::ForItem{node})if *node==effect.node)
                        &&field.ty==(ResolvedType::Record{symbol:model,stored:true});
                    if item{selected=true;continue;}
                    if !primitive_type(&field.ty)||!self.nodes.get(&field.value_node).is_some_and(|node|matches!(node.kind,SyntaxKind::Literal|SyntaxKind::NameRef|SyntaxKind::Name)){return Err(fail());}
                    if self.nodes.get(&field.value_node).is_some_and(|node|matches!(node.kind,SyntaxKind::NameRef|SyntaxKind::Name))
                        &&!matches!(self.query_binding(field.value_node),Some(Binding::Symbol(id))if owner.params.iter().any(|param|param.param==*id)){return Err(fail());}
                }
                if !selected{return Err(fail());}
                let limit=effect.limit.ok_or_else(fail)?;
                let maximum=self.db.get(limit.file).and_then(|source|source.text.get(limit.start as usize..limit.end as usize))
                    .and_then(|text|text.trim().parse::<u16>().ok()).filter(|bound|(1..=1000).contains(bound)).ok_or_else(fail)?;
                if self.nodes.get(&limit).is_none_or(|node|node.kind!=SyntaxKind::Literal)||self.types.node_types.get(&limit)!=Some(&ResolvedType::Scalar(Scalar::Int)){return Err(fail());}
                let item=effect.item.clone().ok_or_else(fail)?;let (crud,defaults)=self.create_legacy_crud(&checked,checked.model,module,created.node);
                self.proof(created,module,DisclosureEffectKind::Create{model:checked.model,crud,binding:checked.binding,defaults,inputs:checked.inputs})?;
                self.proof(effect,module,DisclosureEffectKind::ForMember{domain,limit,maximum,item,parameter,model,body:vec![created.node]})?;
                let mut empty=flow.clone();empty.writes.join(&empty.controls);empty.evaluated.push(DisclosureDecision{node:effect.node,calls:Vec::new(),choice:DisclosureChoice::Else});
                let mut populated=flow;populated.evaluated.push(DisclosureDecision{node:effect.node,calls:Vec::new(),choice:DisclosureChoice::Then});
                populated.executed_effect=true;populated.writes.join(&populated.controls);populated.writes.join(&populated.effect_guards);self.effect_visits+=1;
                Ok(vec![empty,populated])
            }

            /// A finite same-model copy constructor retains its complete original
            /// field inventory in the loop/create proofs. Its per-item reads are
            /// owned by the source loop copy producer, not a one-shot result read.
            fn bounded_copy_loop(&mut self, effect:&Effect, module:ModuleId, flow:Flow,
                calls:&[NodeKey]) -> Result<Vec<Flow>,DisclosureDecline> {
                let fail=|| self.fail(effect.node,"checked source-owned copy loop required");
                if !calls.is_empty() || self.loop_node.is_some() || effect.cond.is_some()
                    || !effect.else_effects.is_empty() || !effect.match_arms.is_empty() {return Err(fail());}
                let [created]=effect.then_effects.as_slice() else {return Err(fail());};
                if created.verb!=EffectVerb::Create || !created.then_effects.is_empty()
                    || !created.else_effects.is_empty() || !created.match_arms.is_empty() {return Err(fail());}
                let owner=self.effects.scenarios.values().find(|owner|owner.module==module
                    && owner.effects.last().is_some_and(|last|last.node==effect.node)).ok_or_else(fail)?;
                let [called,linked,looped]=owner.effects.as_slice() else{return Err(fail());};
                if owner.result.is_some() || owner.on.is_some() || owner.read || owner.expose_none
                    || called.verb!=EffectVerb::Call || called.binding.is_none()
                    || linked.verb!=EffectVerb::Set || looped.node!=effect.node {return Err(fail());}
                let Some(EffectTarget::Operation(operation))=called.target else{return Err(fail());};
                let domain=effect.domain.ok_or_else(fail)?;
                let (parameter,model)=self.original_loop_member_root(domain,effect.node,module)?;
                let parent_model=*self.complete_model_children.get(&operation).ok_or_else(fail)?;
                let checked=self.checked_create_source(created,module).ok_or_else(fail)?;
                if checked.model!=model || self.types.symbol_types.get(&parameter)
                    !=Some(&ResolvedType::Record{symbol:parent_model,stored:true}) {return Err(fail());}
                let [parent,fields @ ..]=checked.inputs.as_slice() else{return Err(fail());};
                if parent.name!="parent" || parent.field.is_some() || fields.is_empty() || fields.len()>200
                    || parent.ty!=(ResolvedType::Record{symbol:parent_model,stored:true})
                    || !matches!(self.query_binding(parent.value_node),Some(Binding::CallAs{node})if *node==called.node)
                    || !self.nodes.get(&parent.value_node).is_some_and(|node|node.kind==SyntaxKind::NameRef) {return Err(fail());}
                for field in fields {
                    let Some((base,name))=self.count_member(field.value_node)else{return Err(fail());};
                    if name!=field.name || !primitive_type(&field.ty)
                        || !matches!(self.query_binding(base),Some(Binding::ForItem{node})if *node==effect.node)
                        || !self.nodes.get(&base).is_some_and(|node|node.kind==SyntaxKind::NameRef)
                        || !self.effects.models.get(&model).is_some_and(|definition|definition.fields.iter().any(|entry|
                            Some(entry.field)==field.field && self.resolve.symbols.get(entry.field.0 as usize)
                                .is_some_and(|symbol|symbol.name==name)
                                && self.types.symbol_types.get(&entry.field)==Some(&field.ty))) {return Err(fail());}
                }
                let limit=effect.limit.ok_or_else(fail)?;
                let maximum=self.db.get(limit.file).and_then(|source|source.text.get(limit.start as usize..limit.end as usize))
                    .and_then(|text|text.trim().parse::<u16>().ok()).filter(|bound|(1..=200).contains(bound)).ok_or_else(fail)?;
                if self.nodes.get(&limit).is_none_or(|node|node.kind!=SyntaxKind::Literal)
                    || self.types.node_types.get(&limit)!=Some(&ResolvedType::Scalar(Scalar::Int)) {return Err(fail());}
                let item=effect.item.clone().ok_or_else(fail)?;
                let (crud,defaults)=self.create_legacy_crud(&checked,model,module,created.node);
                self.proof(created,module,DisclosureEffectKind::Create{model,crud,binding:checked.binding,defaults,inputs:checked.inputs})?;
                self.proof(effect,module,DisclosureEffectKind::ForMember{domain,limit,maximum,item,parameter,model,body:vec![created.node]})?;
                let mut empty=flow.clone();
                empty.writes.join(&empty.controls);
                empty.evaluated.push(DisclosureDecision{node:effect.node,calls:Vec::new(),choice:DisclosureChoice::Else});
                let mut populated=flow;
                populated.evaluated.push(DisclosureDecision{node:effect.node,calls:Vec::new(),choice:DisclosureChoice::Then});
                populated.executed_effect=true;
                populated.writes.join(&populated.controls);populated.writes.join(&populated.effect_guards);
                self.effect_visits+=1;
                Ok(vec![empty,populated])
            }

            /// One bounded, straight-line loop over the actual admitted reference
            /// array. This is source closure, not an array/query authority claim.
            fn bounded_input_loop(
                &mut self,
                effect: &Effect,
                module: ModuleId,
                flow: Flow,
                calls: &[NodeKey],
            ) -> Result<Vec<Flow>, DisclosureDecline> {
                let emits = effect.then_effects.iter().all(|child|child.verb == EffectVerb::Emit);
                let updated_owner = self.effects.scenarios.values().any(|scenario|
                    scenario.module == module && scenario.effects.first().is_some_and(|first|first.node == effect.node)
                    && scenario.effects.get(3).is_some_and(|created|
                        matches!(created.target,Some(EffectTarget::Model(model))
                            if self.check_updated_model_return(&scenario.effects,model,created))));
                // A void mutation may update its admitted parent, cancel its
                // Work key, and mutate a finite contained sibling collection.
                // Native emission independently seals this whole original owner.
                let void_owner = self.effects.scenarios.values().any(|scenario|
                    scenario.module == module && !scenario.read && scenario.on.is_none()
                    && scenario.result.is_none() && scenario.cohort.is_none()
                    && scenario.effects.iter().any(|candidate|candidate.node == effect.node)
                    && scenario.effects.iter().all(|candidate|matches!(candidate.verb,
                        EffectVerb::Set | EffectVerb::Cancel | EffectVerb::For | EffectVerb::Emit)
                        // The independently sealed native owner may end with
                        // one original conditional declared-event notification.
                        || scenario.effects.last().is_some_and(|last|last.node==candidate.node)
                            &&candidate.verb==EffectVerb::If&&candidate.else_effects.is_empty()
                            &&candidate.match_arms.is_empty()&&candidate.cond.is_some_and(|cond|
                                self.types.node_types.get(&cond)==Some(&ResolvedType::Scalar(Scalar::Bool)))
                            &&matches!(candidate.then_effects.as_slice(),[emitted]if emitted.verb==EffectVerb::Emit)));
                let sealed_loop_owner = updated_owner || void_owner;
                let mut assignments = Vec::new();
                for child in &effect.then_effects {
                    if child.verb == EffectVerb::Set || emits && child.verb == EffectVerb::Emit { assignments.push((child, None)); }
                    else if sealed_loop_owner && child.verb == EffectVerb::If && child.else_effects.is_empty() && child.match_arms.is_empty()
                        && child.then_effects.len() == 1 && child.then_effects[0].verb == EffectVerb::Set
                        && child.then_effects[0].args.iter().all(|argument| {
                            let key = argument.value.unwrap_or(argument.key_node);
                            self.nodes.get(&key).is_some_and(|node| matches!(node.kind, SyntaxKind::NameRef | SyntaxKind::Literal)
                                && !matches!(self.query_binding(key), Some(Binding::ForItem { .. } | Binding::QueryAlias { .. })))
                        })
                    { assignments.push((&child.then_effects[0], Some(child.cond.ok_or_else(|| self.fail(child.node,"missing item condition"))?))); }
                    else { return Err(self.fail(child.node,"unsupported bounded loop body")); }
                }
                if !calls.is_empty()
                    || self.loop_node.is_some_and(|node| node != effect.node)
                    || !effect.else_effects.is_empty()
                    || !effect.match_arms.is_empty()
                    || effect.then_effects.is_empty()
                    || effect.then_effects.len() > 200
                    || assignments.iter().any(|(child,_)| !child.then_effects.is_empty()
                        || !child.else_effects.is_empty() || !child.match_arms.is_empty())
                {
                    return Err(self.fail(effect.node, "unsupported bounded loop body"));
                }
                let mut domain = effect
                    .domain
                    .ok_or_else(|| self.fail(effect.node, "missing loop domain"))?;
                for _ in 0..65 {
                    let node = self
                        .nodes
                        .get(&domain)
                        .ok_or_else(|| self.fail(domain, "missing loop domain anchor"))?;
                    if node.kind != SyntaxKind::Group {
                        break;
                    }
                    let children: Vec<_> = node
                        .children
                        .iter()
                        .filter(|child| expression(child.kind))
                        .collect();
                    if children.len() != 1 {
                        return Err(self.fail(domain, "unsupported grouped loop domain"));
                    }
                    domain = NodeKey::of(children[0]);
                }
                let original_domain = domain;
                if let Some(query) = self.types.checked_queries.get(&domain) {
                    let alias_only = query.projection.is_none() && matches!(query.clauses.as_slice(),[clause]
                        if matches!(&clause.kind,CheckedQueryClauseKind::As {name} if Some(name)==effect.item.as_ref()));
                    if !alias_only {
                        if !sealed_loop_owner { return Err(self.fail(domain,"filtered domain needs its original finite mutation owner")); }
                        self.bounded_loop_filter(query).ok_or_else(|| self.fail(domain,"loop needs original item-only filter"))?;
                        domain = query.domain;
                    }
                }
                let node = self
                    .nodes
                    .get(&domain)
                    .ok_or_else(|| self.fail(domain, "missing loop domain"))?;
                // A contained-collection domain (`param.Child`) scans the caller's
                // original required model parameter through its checked containment
                // edge. Query filters stay declined: only the whole contained
                // collection in source order is disclosed here.
                let member_domain = if node.kind==SyntaxKind::Query {
                    let checked=self.types.checked_queries.get(&domain)
                        .ok_or_else(||self.fail(domain,"loop query correspondence"))?;
                    if checked.projection.is_some() || !matches!(checked.clauses.as_slice(),[clause]
                        if matches!(&clause.kind,super::types::CheckedQueryClauseKind::As {name} if Some(name)==effect.item.as_ref()))
                    {return Err(self.fail(domain,"loop requires alias-only contained query"));}
                    Some(checked.domain)
                } else if node.kind==SyntaxKind::Member {Some(domain)} else {None};
                let member_root = if let Some(member_domain)=member_domain {
                    if effect.cond.is_some() {
                        return Err(self.fail(domain, "loop needs unfiltered member domain"));
                    }
                    Some(self.original_loop_member_root(member_domain, effect.node, module)?)
                } else {
                    None
                };
                if node.kind != SyntaxKind::NameRef && member_root.is_none() {
                    return Err(self.fail(domain, "loop needs direct admitted array input"));
                }
                let (model, parameter) = match member_root {
                    Some((root, model)) => (model, root),
                    None => {
                        let binding = self.resolve.node_binding.get(&domain).or_else(|| {
                            node.children
                                .iter()
                                .find_map(|child| self.resolve.node_binding.get(&NodeKey::of(child)))
                        });
                        let Some(Binding::Symbol(parameter)) = binding else {
                            return Err(self.fail(domain, "unestablished loop input"));
                        };
                        let parameter = *parameter;
                        let declared = self
                            .resolve
                            .symbols
                            .get(parameter.0 as usize)
                            .ok_or_else(|| self.fail(domain, "missing loop parameter"))?;
                        let SymbolKind::Param { owner, .. } = declared.kind else {
                            return Err(self.fail(domain, "loop domain is not a parameter"));
                        };
                        let scenario = self
                            .effects
                            .scenarios
                            .get(&owner)
                            .ok_or_else(|| self.fail(domain, "loop domain is not a scenario input"))?;
                        if declared.module != module
                            || !flow.env.contains_key(&Local::Symbol(parameter))
                            || scenario
                                .params
                                .iter()
                                .find(|param| param.param == parameter)
                                .is_none_or(|param| param.default.is_some())
                        {
                            return Err(self.fail(domain, "loop needs original admitted array input"));
                        }
                        let Some(ResolvedType::Array { element, .. }) =
                            self.types.symbol_types.get(&parameter)
                        else {
                            return Err(self.fail(domain, "loop needs nonnullable stored-reference array"));
                        };
                        let ResolvedType::Record {
                            symbol: model,
                            stored: true,
                        } = element.as_ref()
                        else {
                            return Err(self.fail(domain, "loop needs stored-reference elements"));
                        };
                        let model = *model;
                        if self.types.node_types.get(&domain) != self.types.symbol_types.get(&parameter)
                            || !matches!(self.resolve.symbols.get(model.0 as usize), Some(symbol) if symbol.module == module && matches!(symbol.kind, SymbolKind::Model {..}))
                        {
                            return Err(self.fail(domain, "loop stored model correspondence"));
                        }
                        (model, parameter)
                    }
                };
                let limit = effect
                    .limit
                    .ok_or_else(|| self.fail(effect.node, "loop needs literal finite limit"))?;
                let limit_node = self
                    .nodes
                    .get(&limit)
                    .ok_or_else(|| self.fail(limit, "missing loop limit"))?;
                let maximum = self
                    .db
                    .get(limit.file)
                    .and_then(|file| file.text.get(limit.start as usize..limit.end as usize))
                    .and_then(|text| text.trim().parse::<u16>().ok());
                let Some(maximum) = maximum.filter(|maximum| (1..=if emits && member_root.is_some() {500} else {200}).contains(maximum)) else {
                    return Err(self.fail(limit, "loop limit exceeds observation bound"));
                };
                if limit_node.kind != SyntaxKind::Literal
                    || self.types.node_types.get(&limit) != Some(&ResolvedType::Scalar(Scalar::Int))
                {
                    return Err(self.fail(limit, "loop needs typed literal limit"));
                }
                if usize::from(maximum).saturating_mul(assignments.len()) > if emits {500} else {200} {
                    return Err(self.fail(effect.node, "loop Set execution bound"));
                }
                let item = effect
                    .item
                    .clone()
                    .ok_or_else(|| self.fail(effect.node, "missing loop item binding"))?;
                self.loop_node = Some(effect.node);
                let mut env = flow.env.clone();
                env.insert(
                    Local::For(effect.node),
                    ValuePath {
                        record: Some(model),
                        ..ValuePath::default()
                    },
                );
                let mut body = ValuePath::default();
                for (child, condition) in assignments {
                    if let Some(condition) = condition {
                        self.bounded_item_condition(condition,model,effect.node,false)
                            .ok_or_else(||self.fail(condition,"condition must test its exact loop item fields"))?;
                        let values = self.expr(condition, module, &env, calls)?;
                        let [value] = values.as_slice() else { return Err(self.fail(condition,"item condition alternatives unsupported")); };
                        if !value.decisions.is_empty() || !value.intrinsics.is_empty() || value.record.is_some() { return Err(self.fail(condition,"item condition is not a scalar field test")); }
                        body.join(value);
                    }
                    if child.verb == EffectVerb::Emit {
                        if !emits || member_root.is_none() || child.args.is_empty()
                            || child.args.iter().any(|argument| {
                                let key=argument.value.unwrap_or(argument.key_node);
                                !matches!(self.query_binding(key),Some(Binding::ForItem {node}) if *node==effect.node)
                                    || self.types.node_types.get(&key) != Some(&ResolvedType::Record {symbol:model,stored:true})
                            }) {return Err(self.fail(child.node,"loop emit requires its exact contained item"));}
                        let values=self.external_effect(child,module,&env,calls)?;
                        if values.len()!=1 {return Err(self.fail(child.node,"loop emit alternatives"));}
                        body.join(&values[0]);
                        continue;
                    }
                    let node = self
                        .nodes
                        .get(&child.node)
                        .ok_or_else(|| self.fail(child.node, "missing loop Set"))?;
                    let receiver = node
                        .children
                        .iter()
                        .find(|node| node.kind == SyntaxKind::Path)
                        .ok_or_else(|| self.fail(child.node, "missing loop Set receiver"))?;
                    let receiver_binding = self
                        .resolve
                        .node_binding
                        .get(&NodeKey::of(receiver))
                        .or_else(|| {
                            receiver
                                .children
                                .iter()
                                .find_map(|node| self.resolve.node_binding.get(&NodeKey::of(node)))
                        });
                    if !matches!(receiver_binding, Some(Binding::ForItem {node}) if *node == effect.node) {
                        return Err(self.fail(child.node, "loop Set must target its exact item"));
                    }
                    let mut pending = vec![*node];
                    let mut visits = 0usize;
                    while let Some(part) = pending.pop() {
                        visits += 1;
                        if visits > 4096 || matches!(part.kind, SyntaxKind::Call | SyntaxKind::Query) {
                            return Err(self.fail(child.node, "unsupported per-element expression"));
                        }
                        if part.kind == SyntaxKind::Member {
                            let mut base = part
                                .children
                                .iter()
                                .find(|child| expression(child.kind))
                                .ok_or_else(|| self.fail(child.node, "missing loop field receiver"))?;
                            for _ in 0..65 {
                                if base.kind != SyntaxKind::Group {
                                    break;
                                }
                                base = base
                                    .children
                                    .iter()
                                    .find(|child| expression(child.kind))
                                    .ok_or_else(|| {
                                        self.fail(child.node, "missing grouped loop receiver")
                                    })?;
                            }
                            let binding = self
                                .resolve
                                .node_binding
                                .get(&NodeKey::of(base))
                                .or_else(|| {
                                    base.children.iter().find_map(|child| {
                                        self.resolve.node_binding.get(&NodeKey::of(child))
                                    })
                                });
                            if base.kind != SyntaxKind::NameRef
                                || !matches!(binding, Some(Binding::ForItem {node}) if *node == effect.node)
                            {
                                return Err(self.fail(child.node, "loop field must read its exact item"));
                            }
                        }
                        pending.extend(part.children.iter());
                    }
                    let mut alternatives = self.set(child, module, &env, calls)?;
                    if alternatives.len() != 1 {
                        return Err(self.fail(child.node, "per-element loop alternatives unsupported"));
                    }
                    let value = alternatives
                        .pop()
                        .ok_or_else(|| self.fail(child.node, "missing loop body alternative"))?;
                    // A constant admitted scalar input is the same value on every
                    // element and is counted once in the total observation bound
                    // below. Branch decisions and model-reference intrinsics keep
                    // their per-element refusal: only the loop item is an admitted
                    // row inside the body.
                    if !value.decisions.is_empty()
                        || value.intrinsics.iter().any(|intrinsic| {
                            !matches!(
                                intrinsic.kind,
                                DisclosureIntrinsicKind::AdmittedInput { .. }
                            )
                        })
                    {
                        return Err(self.fail(
                            child.node,
                            "per-element loop decisions or intrinsics unsupported",
                        ));
                    }
                    body.join(&value);
                }
                let repeated = (usize::from(maximum) - 1).saturating_mul(body.reads.len());
                if body.reads.len().saturating_add(repeated) > 200 {
                    return Err(self.fail(effect.node, "loop observation bound"));
                }
                let body_nodes: Vec<NodeKey> = effect.then_effects.iter().map(|child| child.node).collect();
                // Member domains scan the caller's contained collection rather than
                // a supplied array parameter; the root parameter owns the domain.
                let kind = if member_root.is_some() {
                    DisclosureEffectKind::ForMember {
                        domain: original_domain,
                        limit,
                        maximum,
                        item,
                        parameter,
                        model,
                        body: body_nodes,
                    }
                } else {
                    DisclosureEffectKind::For {
                        domain,
                        limit,
                        maximum,
                        item,
                        parameter,
                        model,
                        body: body_nodes,
                    }
                };
                self.proof(effect, module, kind)?;
                let mut empty = flow.clone();
                empty.writes.join(&empty.controls);
                empty.evaluated.push(DisclosureDecision {
                    node: effect.node,
                    calls: Vec::new(),
                    choice: DisclosureChoice::Else,
                });
                let mut populated = flow;
                populated.evaluated.push(DisclosureDecision {
                    node: effect.node,
                    calls: Vec::new(),
                    choice: DisclosureChoice::Then,
                });
                populated.executed_effect = true;
                populated.writes.join(&populated.controls);
                populated.writes.join(&populated.effect_guards);
                populated.writes.join(&body);
                populated.repeated_observations = populated.repeated_observations.saturating_add(repeated);
                for read in body.observed {
                    if !populated.observed.contains(&read) {
                        populated.observed.push(read);
                    }
                }
                if populated
                    .writes
                    .reads
                    .len()
                    .saturating_add(populated.writes.intrinsics.len())
                    .saturating_add(populated.repeated_observations)
                    > 200
                {
                    return Err(self.fail(effect.node, "loop total observation bound"));
                }
                self.effect_visits += 1;
                Ok(vec![empty, populated])
            }

            fn statements(
                &mut self,
                effects: &[Effect],
                module: ModuleId,
                flows: Vec<Flow>,
                calls: &[NodeKey],
            ) -> Result<(Vec<Flow>, Vec<DisclosureReturn>), DisclosureDecline> {
                let Some(anchor) = effects.first().map(|effect| effect.node) else {
                    return Ok((flows, Vec::new()));
                };
                if self.statement_depth >= 64 {
                    return Err(self.fail(anchor, "statement closure depth bound"));
                }
                self.statement_depth += 1;
                let previous_expressions = self.statement_expressions.replace(Vec::new());
                let result = self.statements_inner(effects, module, flows, calls);
                self.statement_expressions = previous_expressions;
                self.statement_depth -= 1;
                result
            }

            /// Two adjacent original creates may retain the first row as their result.
            /// Team roots store its exact CreateAs; the established contained pair also
            /// retains its same-parent and checked-count obligations.
            fn checked_created_pair(&self, effects: &[Effect], module: ModuleId, created: &Effect) -> bool {
                let Some(model) = self.result_model else {
                    return false;
                };
                let mut creates = effects
                    .iter()
                    .enumerate()
                    .filter(|(_, effect)| effect.verb == EffectVerb::Create);
                let Some((index, first)) = creates.next() else {
                    return false;
                };
                let Some((second_index, second)) = creates.next() else {
                    return false;
                };
                if creates.next().is_some() || first.node != created.node || second_index != index + 1 {
                    return false;
                }
                let Some(first) = self.checked_create_source(first, module) else {
                    return false;
                };
                let Some(second) = self.checked_create_source(second, module) else {
                    return false;
                };
                if first.model != model || second.model == model || first.binding == second.binding {
                    return false;
                }
                let result_type = ResolvedType::Record {
                    symbol: model,
                    stored: true,
                };
                let mut result_inputs = second.inputs.iter().filter(|input| input.ty == result_type);
                let Some(result_input) = result_inputs.next() else {
                    return false;
                };
                if result_inputs.next().is_some()
                    || result_input.field.is_none()
                    || !matches!(self.query_binding(result_input.value_node),
                        Some(Binding::CreateAs {node}) if *node == first.node)
                {
                    return false;
                }
                if first.definition.declaration.owner == ModelOwner::Team
                    && second.definition.declaration.owner == ModelOwner::Team
                {
                    return effects[..index].iter().all(|effect| {
                        matches!(effect.verb, EffectVerb::Let | EffectVerb::Require)
                            || effect.verb == EffectVerb::If
                                && effect.match_arms.is_empty()
                                && effect
                                    .then_effects
                                    .iter()
                                    .chain(&effect.else_effects)
                                    .all(|nested| {
                                        matches!(nested.verb, EffectVerb::Require | EffectVerb::Return)
                                            && nested.then_effects.is_empty()
                                            && nested.else_effects.is_empty()
                                            && nested.match_arms.is_empty()
                                    })
                    });
                }
                let ModelOwner::ChildOf(parent) = first.definition.declaration.owner else {
                    return false;
                };
                if first.model != model
                    || second.model == model
                    || first.binding == second.binding
                    || second.definition.declaration.owner != ModelOwner::ChildOf(parent)
                {
                    return false;
                }
                let Some(first_parent) = first.inputs.iter().find(|input| input.name == "parent") else {
                    return false;
                };
                let Some(second_parent) = second.inputs.iter().find(|input| input.name == "parent") else {
                    return false;
                };
                let Some(Binding::Symbol(parameter)) = self.query_binding(first_parent.value_node) else {
                    return false;
                };
                if self.checked_call_parent_path(first_parent.value_node, *parameter, 0)
                    != Some((parent, 0))
                    || self.checked_call_parent_path(second_parent.value_node, *parameter, 0)
                        != Some((parent, 0))
                {
                    return false;
                }
                if effects[..index]
                    .iter()
                    .any(|effect| !matches!(effect.verb, EffectVerb::Let | EffectVerb::Require))
                {
                    return false;
                }
                self.effects.scenarios.values().any(|scenario| {
                    scenario.module == module
                        && scenario
                            .effects
                            .iter()
                            .any(|effect| effect.node == first.node)
                        && scenario
                            .effects
                            .iter()
                            .any(|effect| effect.node == second.node)
                        && self
                            .checked_count_query_sources(scenario)
                            .is_some_and(|queries| {
                                queries.iter().any(|query| {
                                    let Some(count) = &query.count else {
                                        return false;
                                    };
                                    query.model == second.model
                                        && count.statement == second.node
                                        && count
                                            .contained_parent
                                            .is_some_and(|(_, actual)| actual == *parameter)
                                        && second.inputs.iter().any(|input| {
                                            let Some((counted, increment)) =
                                                self.query_binary(input.value_node, "+")
                                            else {
                                                return false;
                                            };
                                            input.field.is_some()
                                                && input.ty == ResolvedType::Scalar(Scalar::Int)
                                                && self.query_group(counted) == Some(count.call)
                                                && self.query_group(increment).is_some_and(|increment| {
                                                    self.nodes.get(&increment).is_some_and(|node| {
                                                        node.kind == SyntaxKind::Literal
                                                            && self.types.node_types.get(&increment)
                                                                == Some(&ResolvedType::Scalar(Scalar::Int))
                                                            && self.db.get(increment.file).and_then(
                                                                |source| {
                                                                    source.text.get(
                                                                        increment.start as usize
                                                                            ..increment.end as usize,
                                                                    )
                                                                },
                                                            ) == Some("1")
                                                    })
                                                })
                                        })
                                })
                            })
                })
            }

            fn statements_inner(
                &mut self,
                effects: &[Effect],
                module: ModuleId,
                mut flows: Vec<Flow>,
                calls: &[NodeKey],
            ) -> Result<(Vec<Flow>, Vec<DisclosureReturn>), DisclosureDecline> {
                self.check_result_created_return(effects, module)?;
                let mut returns = Vec::new();
                for effect in effects {
                    if let Some(entries) = &mut self.statement_expressions {
                        entries.clear();
                    }
                    self.steps += 1;
                    if self.steps > 16384 {
                        return Err(self.fail(effect.node, "statement closure item bound"));
                    }
                    let mut next = Vec::new();
                    for flow in flows {
                        self.walk_statement_flow(effect, module, flow, calls, effects, &mut next, &mut returns)?;
                    }
                    if next.len().saturating_add(returns.len()) > 1024 {
                        return Err(self.fail(effect.node, "statement path bound"));
                    }
                    flows = next;
                }
                Ok((flows, returns))
            }

    /// Mutation-verb flows: create, delete, let, require, set/send/call and
    /// transition walks. The wildcard mirrors the control half's refusal.
    /// (This was the mutation arm group.)
    fn walk_mutation_flow(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: Flow,
        calls: &[NodeKey],
        effects: &[Effect],
        next: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
        match effect.verb {
            EffectVerb::Create  => self.walk_effect_create(effect, module, flow, calls, &mut *next)?,
            EffectVerb::Delete  => self.walk_effect_delete(effect, module, flow, calls, effects, &*returns, &mut *next)?,
            EffectVerb::Let  => self.walk_effect_let(effect, module, flow, calls, &mut *next)?,
            EffectVerb::Require => self.walk_effect_require(effect, module, flow, calls, &mut *next)?,
            EffectVerb::Set | EffectVerb::Send | EffectVerb::Call | EffectVerb::Transition => {
                self.walk_write_effect(effect, module, flow, calls, &mut *next)?;
            }
            _ => return Err(self.fail(effect.node, "mutation or external effect closure")),
        }
        Ok(())
    }

    /// Control-verb flows: return, branch, loop and external walks, with the
    /// same refusal as the mutation half. (This was the control arm group.)
    fn walk_control_flow(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: Flow,
        calls: &[NodeKey],
        next: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
        match effect.verb {
            EffectVerb::Return => {
                self.walk_return_flow(effect, module, &flow, calls, &mut *returns)?;
            }
            EffectVerb::If | EffectVerb::Match => {
                self.walk_branch_effect(effect, module, flow, calls, &mut *next, &mut *returns)?;
            }
            EffectVerb::For => { self.walk_loop_flow(effect, module, flow, calls, &mut *next)?; }
            EffectVerb::Emit | EffectVerb::Schedule | EffectVerb::Cancel  => self.walk_write_effect(effect, module, flow, calls, &mut *next)?,
            _ => return Err(self.fail(effect.node, "mutation or external effect closure")),
        }
        Ok(())
    }

    /// One returned flow: prove each return-call value against the
    /// result-model gates. (This was the Return-arm block.)
    fn walk_return_flow(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: &Flow,
        calls: &[NodeKey],
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
        let values = self.return_call_value(effect, module, flow, calls)?;
        for value in values {
            self.walk_return_value(effect, module, flow, calls, value, &mut *returns)?;
        }
        Ok(())
    }

    /// One loop flow: extend the path with the bounded input-loop outcomes.
    /// (This was the For-arm block.)
    fn walk_loop_flow(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: Flow,
        calls: &[NodeKey],
        next: &mut Vec<Flow>,
    ) -> Result<(), DisclosureDecline> {
        let previous = self.loop_node;
        let paths = if matches!(effect.then_effects.as_slice(),[created] if created.verb==EffectVerb::Create) {
            if self.effects.scenarios.values().any(|owner|owner.module==module&&matches!(owner.effects.as_slice(),[called,linked,looped]
                if called.verb==EffectVerb::Call&&linked.verb==EffectVerb::Set&&looped.node==effect.node)){
                self.bounded_copy_loop(effect,module,flow,calls)
            }else{self.bounded_sibling_create_loop(effect,module,flow,calls)}
        } else {self.bounded_input_loop(effect, module, flow, calls)};
        self.loop_node = previous;
        next.extend(paths?);
        Ok(())
    }

    /// One statement flow through the effect-verb dispatch: create, delete,
    /// let, require, mutation, transition, return, branch, loop and external
    /// walks. (This was the per-flow match.)
    fn walk_statement_flow(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: Flow,
        calls: &[NodeKey],
        effects: &[Effect],
        next: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
                        match effect.verb {
                            EffectVerb::Create | EffectVerb::Delete | EffectVerb::Let
                            | EffectVerb::Require | EffectVerb::Set | EffectVerb::Send
                            | EffectVerb::Call | EffectVerb::Transition => {
                                self.walk_mutation_flow(effect, module, flow, calls, effects, &mut *next, &mut *returns)?;
                            }
                            _ => {
                                self.walk_control_flow(effect, module, flow, calls, &mut *next, &mut *returns)?;
                            }
                        }
        Ok(())
    }

    /// Created-result gate for a result-model closure: admit direct,
    /// child and send returns, else require a straight-line created row.
    /// (This was the result-model opening block.)
    fn check_result_created_return(
        &self,
        effects: &[Effect],
        module: ModuleId,
    ) -> Result<(), DisclosureDecline> {
                // Void scenarios return no row, so no create/return profile applies;
                // their creates are still individually disclosed below, in order.
                if self.result_model.is_some()
                    && let Some(created) = effects
                        .iter()
                        .find(|effect| effect.verb == EffectVerb::Create)
                {
                    let created_pair = self.checked_created_pair(effects, module, created);
                    // Branch contents still pass the ordinary ordered Flow proof:
                    // only the actual surviving path reaches this final created row.
                    // Shape admission only: the existing Flow walk below still proves
                    // each operand, target, send, mutation and branch in authored order.
                    // A created result may pass through a finite effect tail without
                    // requiring a particular send/set arrangement. Nested creates,
                    // child calls, loops and additional returns retain their own gates.
                    let direct_model_return = self.result_model.is_some_and(|model| self.check_direct_model_return(effects, model, created, created_pair));
                    let created_child_return = self.result_model.is_some_and(|model| self.check_created_child_return(effects, model, created));
                    let created_send_return = self.result_model.is_some_and(|model| self.check_created_send_return(effects, model, created, created_pair));
                    let updated_model_return = self.result_model.is_some_and(|model|
                        self.check_updated_model_return(effects, model, created));
                    if !direct_model_return && !created_child_return && !created_send_return && !updated_model_return {
                        self.check_straight_line_created_return(effects, module, created)?;
                    }
                }
        Ok(())
    }
    /// One returned value against the result-model gates: parameter-member,
    /// parameter and reference admission, then the result-shape match.
    /// (This was the per-value Return-arm body.)
    fn walk_return_value(
        &self,
        effect: &Effect,
        module: ModuleId,
        flow: &Flow,
        calls: &[NodeKey],
        mut value: ValuePath,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
        if let Some(model) = self.result_model {
            let direct = effect.value.and_then(|key| self.query_binding(key));
            self.admit_parameter_member_result(effect, module, model, calls, &mut value)?;
            self.admit_parameter_result(effect, module, model, calls, direct, &mut value)?;
            self.admit_reference_result(effect, module, model, calls, &mut value)?;
            self.check_return_result_match(direct, &value, effect, module, model)?;
        }
        if !compatible(&flow.evaluated, &value.decisions) {
            return Ok(());
        }
        returns.push(self.return_path(
            effect.node,
            module,
            flow.clone(),
            value,
        )?);
        if returns.len() > 1024 {
            return Err(self.fail(effect.node, "return path bound"));
        }
        Ok(())
    }
    /// One parameter-member model return: readable owner, matching input
    /// reference and reserved identity rules. (This was the ParameterMember gate.)
    fn admit_parameter_member_result(
        &self,
        effect: &Effect,
        module: ModuleId,
        model: SymbolId,
        calls: &[NodeKey],
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
                                        if let Some(ReferenceOrigin::ParameterMember { parameter, node }) =
                                            value.reference_origin
                                            && value.record == Some(model)
                                            && calls.is_empty()
                                            && self.loop_node.is_none()
                                            && effect.value.and_then(|key| self.query_group(key))
                                                == Some(node)
                                            && self
                                                .checked_contract_input_reference(node, module)
                                                .is_some_and(|(root, target, _)| {
                                                    root == parameter && target == model
                                                })
                                        {
                                            let owner =
                                                self.resolve.symbols.get(model.0 as usize).ok_or_else(
                                                    || self.fail(node, "missing input result model"),
                                                )?;
                                            let SymbolKind::Model { fields, .. } = &owner.kind else {
                                                return Err(
                                                    self.fail(node, "input result needs stored Model")
                                                );
                                            };
                                            if fields.iter().any(|field| {
                                                self.resolve
                                                    .symbols
                                                    .get(field.0 as usize)
                                                    .is_none_or(|field| field.name == "id")
                                            }) {
                                                return Err(
                                                    self.fail(node, "input result identity is reserved")
                                                );
                                            }
                                            value.reads.push(DisclosureDependency {
                                                query_id: None,
                                                id: self.opaque(
                                                    "read-data",
                                                    node,
                                                    &self.call_stamp(calls)?,
                                                )?,
                                                source: self.source(module, node)?,
                                                node,
                                                calls: calls.to_vec(),
                                                role: DependencyRole::Data,
                                                model,
                                                field: model,
                                                model_name: owner.canonical.clone(),
                                                field_name: "id".into(),
                                                ty: ResolvedType::Scalar(Scalar::Text),
                                                type_id: "text".into(),
                                            });
                                            value.observed.push((node, calls.to_vec()));
                                            value.model_result = Some(DisclosureModelResult::Parameter {
                                                model,
                                                parameter,
                                                node,
                                            });
                                        }
        Ok(())
    }
    /// One parameter model return: source correspondence and the read row.
    /// (This was the Parameter gate.)
    fn admit_parameter_result(
        &self,
        effect: &Effect,
        module: ModuleId,
        model: SymbolId,
        calls: &[NodeKey],
        direct: Option<&Binding>,
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
                                        if let (
                                            Some(Binding::Symbol(parameter)),
                                            Some(ReferenceOrigin::Parameter(origin)),
                                        ) = (direct, value.reference_origin)
                                            && *parameter == origin
                                            && value.record == Some(model)
                                            && calls.is_empty()
                                            && self.loop_node.is_none()
                                        {
                                            let operand = self
                                                .query_group(effect.value.unwrap())
                                                .ok_or_else(|| {
                                                    self.fail(effect.node, "missing model return operand")
                                                })?;
                                            let scenario = self
                                                .effects
                                                .scenarios
                                                .values()
                                                .find(|scenario| {
                                                    scenario.module == module
                                                        && scenario.node.file == effect.node.file
                                                        && scenario.node.start <= effect.node.start
                                                        && effect.node.end <= scenario.node.end
                                                })
                                                .ok_or_else(|| {
                                                    self.fail(effect.node, "missing model return owner")
                                                })?;
                                            let param = scenario
                                                .params
                                                .iter()
                                                .find(|param| param.param == origin)
                                                .ok_or_else(|| {
                                                    self.fail(operand, "missing model return parameter")
                                                })?;
                                            let owner = self
                                                .resolve
                                                .symbols
                                                .get(model.0 as usize)
                                                .ok_or_else(|| {
                                                    self.fail(operand, "missing model return declaration")
                                                })?;
                                            let SymbolKind::Model { fields, .. } = &owner.kind else {
                                                return Err(self.fail(
                                                    operand,
                                                    "model return needs a stored declaration",
                                                ));
                                            };
                                            self.check_model_return_correspondence(
                                                effect,
                                                module,
                                                operand,
                                                scenario,
                                                param,
                                                owner,
                                                model,
                                                origin,
                                            )?;
                                            value.reads.push(DisclosureDependency {
                                                query_id: None,
                                                id: self.opaque(
                                                    "read-data",
                                                    operand,
                                                    &self.call_stamp(calls)?,
                                                )?,
                                                source: self.source(module, operand)?,
                                                node: operand,
                                                calls: calls.to_vec(),
                                                role: DependencyRole::Data,
                                                model,
                                                field: model,
                                                model_name: owner.canonical.clone(),
                                                field_name: "id".into(),
                                                ty: ResolvedType::Scalar(Scalar::Text),
                                                type_id: "text".into(),
                                            });
                                            value.observed.push((operand, calls.to_vec()));
                                            value.model_result = Some(DisclosureModelResult::Parameter {
                                                model,
                                                parameter: origin,
                                                node: operand,
                                            });
                                        }
        Ok(())
    }
    /// One reference model return: required-reference source correspondence
    /// and the return-model-id row. (This was the Reference gate.)
    fn admit_reference_result(
        &self,
        effect: &Effect,
        module: ModuleId,
        model: SymbolId,
        calls: &[NodeKey],
        value: &mut ValuePath,
    ) -> Result<(), DisclosureDecline> {
                                        if let Some(DisclosureModelResult::Reference {
                                            model: target,
                                            node: operand,
                                            source_model,
                                            field,
                                        }) = value.model_result
                                        {
                                            let owner = self
                                                .resolve
                                                .symbols
                                                .get(target.0 as usize)
                                                .ok_or_else(|| {
                                                    self.fail(operand, "missing reference result target")
                                                })?;
                                            if target != model
                                                || value.record != Some(target)
                                                || effect.value.and_then(|key| self.query_group(key))
                                                    != Some(operand)
                                                || self
                                                    .nodes
                                                    .get(&operand)
                                                    .is_none_or(|node| node.kind != SyntaxKind::Member)
                                                || self.types.node_types.get(&operand)
                                                    != Some(&ResolvedType::Record {
                                                        symbol: target,
                                                        stored: true,
                                                    })
                                                || !value.reads.iter().any(|read| {
                                                    read.node == operand
                                                        && read.role == DependencyRole::Data
                                                        && read.model == source_model
                                                        && read.field == field
                                                        && read.ty
                                                            == (ResolvedType::Record {
                                                                symbol: target,
                                                                stored: true,
                                                            })
                                                        && read.calls.is_empty()
                                                        && read.query_id.is_none()
                                                })
                                                || !matches!(owner.kind, SymbolKind::Model { .. })
                                            {
                                                return Err(self.fail(operand, "direct required reference result source correspondence"));
                                            }
                                            value.reads.push(DisclosureDependency {
                                                query_id: None,
                                                id: self.opaque(
                                                    "return-model-id",
                                                    operand,
                                                    &self.call_stamp(calls)?,
                                                )?,
                                                source: self.source(module, operand)?,
                                                node: operand,
                                                calls: calls.to_vec(),
                                                role: DependencyRole::Data,
                                                model: target,
                                                field: target,
                                                model_name: owner.canonical.clone(),
                                                field_name: "id".into(),
                                                ty: ResolvedType::Scalar(Scalar::Text),
                                                type_id: "text".into(),
                                            });
                                            value.observed.push((operand, calls.to_vec()));
                                        }
        Ok(())
    }
    /// A returned value matches its proven producer: parameter, created,
    /// call, reference or idempotent first-query replay shape.
    /// (This was the return-shape match.)
    fn check_return_result_match(
        &self,
        direct: Option<&Binding>,
        value: &ValuePath,
        effect: &Effect,
        module: ModuleId,
        model: SymbolId,
    ) -> Result<(), DisclosureDecline> {
                                        let matches = match (direct, value.model_result) {
                                            (
                                                _,
                                                Some(DisclosureModelResult::Parameter {
                                                    model: actual,
                                                    parameter,
                                                    node,
                                                }),
                                            ) if effect.value.and_then(|key| self.query_group(key))
                                                == Some(node)
                                                && self
                                                    .checked_contract_input_reference(node, module)
                                                    .is_some_and(|(root, target, _)| {
                                                        root == parameter && target == model
                                                    }) =>
                                            {
                                                actual == model
                                            }
                                            (
                                                Some(Binding::Symbol(parameter)),
                                                Some(DisclosureModelResult::Parameter {
                                                    model: actual,
                                                    parameter: original,
                                                    ..
                                                }),
                                            ) => *parameter == original && model == actual,
                                            (
                                                Some(Binding::CreateAs { node }),
                                                Some(DisclosureModelResult::Create {
                                                    model: actual,
                                                    node: producer,
                                                }),
                                            )
                                            | (
                                                Some(Binding::CallAs { node }),
                                                Some(DisclosureModelResult::Call {
                                                    model: actual,
                                                    node: producer,
                                                    ..
                                                }),
                                            ) => *node == producer && model == actual,
                                            (
                                                _,
                                                Some(DisclosureModelResult::Reference {
                                                    model: actual,
                                                    node,
                                                    ..
                                                }),
                                            ) => {
                                                model == actual
                                                    && effect.value.and_then(|key| self.query_group(key))
                                                        == Some(node)
                                            }
                                            // Finite first-query slice D (CAN18-v1):
                                            // whole-row idempotent replay
                                            // (`if previous!=null ... return previous`
                                            // alongside a same-model create) for one
                                            // unscoped single-Text-equality
                                            // id-ordered family. All other Let returns
                                            // (including bare absence and direct
                                            // returns) stay refused below.
                                            (
                                                Some(Binding::Let { node: let_node }),
                                                None,
                                            ) if value.record == Some(model)
                                                && value.first_query.is_some()
                                                && value.influences.len() == 4 =>
                                            {
                                                self.effects
                                                    .scenarios
                                                    .values()
                                                    .find(|scenario| {
                                                        scenario.module == module
                                                            && scenario.node.file
                                                                == effect.node.file
                                                            && scenario.node.start
                                                                <= effect.node.start
                                                            && effect.node.end
                                                                <= scenario.node.end
                                                    })
                                                    .is_some_and(|scenario| {
                                                        let Some(let_effect) =
                                                            scenario.effects.iter().find(|binding| {
                                                                binding.verb == EffectVerb::Let
                                                                    && binding.node == *let_node
                                                            })
                                                        else {
                                                            return false;
                                                        };
                                                        let Some(query) = self.checked_first_query_source(
                                                            scenario, let_effect,
                                                        ) else {
                                                            return false;
                                                        };
                                                        let Some(first) = query.first.as_ref() else {
                                                            return false;
                                                        };
                                                        query.model == model
                                                            && first.binding == *let_node
                                                            && value.first_query.is_some_and(
                                                                |(call, binding)| {
                                                                    call == first.call
                                                                        && binding == first.binding
                                                                },
                                                            )
                                                            && query.dependencies.len() == 1
                                                            && query.dependencies[0].role
                                                                == DependencyRole::Control
                                                            && query.dependencies[0].model == model
                                                            && query.dependencies[0].type_id == "text"
                                                            && query.dependencies[0].ty
                                                                == ResolvedType::Scalar(Scalar::Text)
                                                            && query.inputs.len() == 1
                                                            && !query.archived
                                                            && query.limit.is_none()
                                                            && query.projection.is_none()
                                                            && query.cardinality_guard.is_none()
                                                            && query.count.is_none()
                                                            && query.order.len() == 1
                                                            && query.order[0].field.is_none()
                                                            && query.order[0].field_name == "id"
                                                            && !query.order[0].descending
                                                    })
                                            }
                                            _ => false,
                                        };
                                        if !matches {
                                            return Err(self.fail(
                                                effect.node,
                                                "direct newly-created model result required",
                                            ));
                                        }
        Ok(())
    }
    /// Branch bodies for an If subject or the checked Match arms.
    /// (This was the alternatives branch table.)
    fn branch_bodies<'e>(
        &self,
        effect: &'e Effect,
    ) -> Result<Vec<(DisclosureChoice, &'e Vec<Effect>)>, DisclosureDecline> {
                                let branches: Vec<_> = if effect.verb == EffectVerb::If {
                                    vec![
                                        (DisclosureChoice::Then, &effect.then_effects),
                                        (DisclosureChoice::Else, &effect.else_effects),
                                    ]
                                } else {
                                    effect
                                        .match_arms
                                        .iter()
                                        .map(|arm| {
                                            arm.case
                                                .clone()
                                                .map(|case| (DisclosureChoice::Match(case), &arm.effects))
                                                .ok_or_else(|| {
                                                    self.fail(arm.node, "missing checked match case")
                                                })
                                        })
                                        .collect::<Result<_, _>>()?
                                };
        Ok(branches)
    }
    /// One If/Match effect: prove the subject, walk each alternative, and
    /// join the continuing paths. (This was the If|Match arm.)
    fn walk_branch_effect(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        flow: Flow,
        calls: &[NodeKey],
        next: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
                                let subject = if effect.verb == EffectVerb::If {
                                    effect.cond
                                } else {
                                    effect.value
                                }
                                .ok_or_else(|| self.fail(effect.node, "missing branch subject"))?;
                                if effect.verb == EffectVerb::Match
                                    && !self.types.exhaustive_matches.contains(&effect.node)
                                {
                                    return Err(self.fail(effect.node, "unproven exhaustive match"));
                                }
        // The exact source observer owns only this reached boolean and its
        // current/final reads. Keep both original branch paths and decisions;
        // its control observations confer no DATA authority on either arm.
        let observed_condition=effect.verb==EffectVerb::If && calls.is_empty()
            && self.effects.scenarios.values().any(|scenario|scenario.module==module
                &&self.checked_source_requires(scenario).is_some_and(|sites|sites.iter().any(|site|
                    site.stage==CheckedDecisionStage::BodyCondition && site.statement==effect.node && site.node==subject)));
        let alternatives=if observed_condition{vec![ValuePath::default()]}
            else{self.expr(subject,module,&flow.env,calls)?};
        let branches = self.branch_bodies(effect)?;
        for condition in alternatives {
            self.walk_branch_alternative(effect, module, calls, &flow, condition, &branches, next, returns)?;
        }
        Ok(())
    }
    /// One branch alternative: admit the control, walk each choice body,
    /// and join the continuing paths. (This was the per-condition loop.)
    fn walk_branch_alternative(
        &mut self,
        effect: &Effect,
        module: ModuleId,
        calls: &[NodeKey],
        flow: &Flow,
        condition: ValuePath,
        branches: &[(DisclosureChoice, &Vec<Effect>)],
        next: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
    ) -> Result<(), DisclosureDecline> {
        if !compatible(&flow.evaluated, &condition.decisions) {
            return Ok(());
        }
        let control = self.control(condition)?;
                                    let mut continuing = Vec::new();
                                    let mut all_continue = true;
                                    let prior_effect_visits = self.effect_visits;
        for (choice, body) in branches {
            self.walk_branch_body(effect.node, module, calls, flow, choice, body, &control, &mut continuing, returns, &mut all_continue)?;
            if continuing.len().saturating_add(returns.len()) > 1024 {
                return Err(self.fail(effect.node, "branch path bound"));
            }
        }
                                    // A branch can select whether a changed record
                                    // exists, even on its no-transition outcome. Keep
                                    // that selector for every continuing outcome when
                                    // any sibling accumulated new write dependencies.
                                    let selects_writes = self.effect_visits != prior_effect_visits
                                        || continuing.iter().any(|path| {
                                            path.writes.reads.iter().any(|read| {
                                                !flow.writes.reads.iter().any(|prior| prior.id == read.id)
                                            })
                                        });
        self.join_branch_paths(effect.node, calls, flow, continuing, all_continue, selects_writes, next)?;
        Ok(())
    }
    /// One branch choice body: extend the control evidence and walk it.
    /// (This was the per-choice loop body.)
    fn walk_branch_body(
        &mut self,
        effect_node: NodeKey,
        module: ModuleId,
        calls: &[NodeKey],
        flow: &Flow,
        choice: &DisclosureChoice,
        body: &[Effect],
        control: &ValuePath,
        continuing: &mut Vec<Flow>,
        returns: &mut Vec<DisclosureReturn>,
        all_continue: &mut bool,
    ) -> Result<(), DisclosureDecline> {
                                        let mut branch = flow.clone();
                                        for read in &control.observed {
                                            if !branch.observed.contains(read) {
                                                branch.observed.push(read.clone());
                                            }
                                        }
                                        branch.controls.join(&control);
                                        branch.controls.decisions.push(DisclosureDecision {
                                            node: effect_node,
                                            calls: calls.to_vec(),
                                            choice: choice.clone(),
                                        });
                                        for decision in &branch.controls.decisions {
                                            if !branch.evaluated.contains(decision) {
                                                branch.evaluated.push(decision.clone());
                                            }
                                        }
                                        let (live, emitted) =
                                            self.statements(body, module, vec![branch], calls)?;
                                        *all_continue &= !live.is_empty() && emitted.is_empty();
                                        continuing.extend(live);
                                        returns.extend(emitted);
                                        if continuing.len().saturating_add(returns.len()) > 1024 {
                                            return Err(self.fail(effect_node, "branch path bound"));
                                        }
        Ok(())
    }
    /// Join continuing branch paths at the common postdominator: keep
    /// selectors with new writes, else restore read-only controls.
    /// (This was the continuing-path join loop.)
    fn join_branch_paths(
        &self,
        effect_node: NodeKey,
        calls: &[NodeKey],
        flow: &Flow,
        continuing: Vec<Flow>,
        all_continue: bool,
        selects_writes: bool,
        next: &mut Vec<Flow>,
    ) -> Result<(), DisclosureDecline> {
                                    for mut path in continuing {
                                        // Only an entirely read-only branch loses its
                                        // local controls at the common postdominator.
                                        path.env = flow.env.clone();
                                        if selects_writes {
                                            path.writes.join(&path.controls);
                                            if path.writes.reads.len() + path.writes.intrinsics.len() > 200
                                            {
                                                return Err(self.fail(
                                                    effect_node,
                                                    "transition write dependency bound",
                                                ));
                                            }
                                        } else if all_continue {
                                            path.controls = flow.controls.clone();
                                        }
                                        next.push(path);
                                        if next.len() > 1024 {
                                            return Err(self.fail(effect_node, "statement path bound"));
                                        }
                                    }
        Ok(())
    }
}

fn compatible(left: &[DisclosureDecision], right: &[DisclosureDecision]) -> bool {
    let default_selection = |choice: &DisclosureChoice| {
        matches!(
            choice,
            DisclosureChoice::DefaultEvaluated | DisclosureChoice::DefaultProvided
        )
    };
    !left.iter().any(|a| {
        right.iter().any(|b| {
            a.node == b.node
                && a.calls == b.calls
                && default_selection(&a.choice) == default_selection(&b.choice)
                && a.choice != b.choice
        })
    })
}

fn ordinary_file_array(ty: &ResolvedType) -> bool {
    matches!(ty, ResolvedType::Array { element, ordered: true, nonempty: false }
        if element.as_ref() == &ResolvedType::Scalar(Scalar::File))
}

/// Email joins the disclosed primitives: stored email fields are ordinary
/// checked scalars with a String MCP mapping and a Values wire codec, and
/// native dispatch (row 10) must seal record email inputs such as a mail
/// recipient. Other unlisted scalars keep failing closed; each needs its own
/// probe before admission.
pub(crate) fn primitive_type(ty: &ResolvedType) -> bool {
    matches!(
        ty,
        ResolvedType::Scalar(
            Scalar::Int
                | Scalar::Text
                | Scalar::Email
                | Scalar::Bool
                | Scalar::Decimal
                | Scalar::Money
                | Scalar::Date
                | Scalar::Datetime
                | Scalar::Duration
                | Scalar::Currency
                | Scalar::User
        )
    )
}

fn result_type(ty: &ResolvedType) -> bool {
    let base = match ty {
        ResolvedType::Nullable(inner) => inner.as_ref(),
        ty => ty,
    };
    primitive_type(base)
        || matches!(base, ResolvedType::Enum { cases, .. } if !cases.is_empty())
        || matches!(base, ResolvedType::Array { element, .. } if primitive_type(element))
}

fn transcript_message_array(ty: &ResolvedType) -> bool {
    matches!(ty,ResolvedType::Array {element,ordered:true,..}
        if checked_standard_nominal_name(element)==Some("TextMessage"))
}

/// The owning imported constructor supplies the carried schema identity.
/// Retain anonymous objects without deriving a nominal identity from shape.
/// A child predicate scalar: primitives and non-empty enums.
fn predicate_scalar(ty: &ResolvedType) -> bool {
    primitive_type(ty) || matches!(ty, ResolvedType::Enum {cases,..} if !cases.is_empty())
}

/// A send's runtime sink binding: the queue publish or analytics write the
/// target alias resolves to, with its input and optional input names.
/// (This was the `find_map` closure over the module runtime bindings.)
fn send_sink<'a>(
    declarations: &'a [super::types::CheckedRuntimeBinding],
    target: &'a Option<EffectTarget>,
    alias: &'a str,
    member: Option<&'a str>,
) -> Option<(&'a str, Vec<String>, Vec<String>)> {
    declarations
        .iter()
        .find_map(|declaration| match (declaration, target) {
            (
                super::types::CheckedRuntimeBinding::Queue { name, .. },
                Some(EffectTarget::Queue { queue, op }),
            ) if name == alias
                && queue == name
                && op == "publish"
                && member == Some(op.as_str()) =>
            {
                Some((op.as_str(), vec!["value".to_string()], Vec::new()))
            }
            (
                super::types::CheckedRuntimeBinding::Analytics { name, fields },
                Some(EffectTarget::Analytics { sink, op }),
            ) if name == alias
                && sink == name
                && op == "write"
                && member == Some(op.as_str()) =>
            {
                Some((
                    op.as_str(),
                    fields.iter().map(|(name, _)| name.clone()).collect(),
                    fields
                        .iter()
                        .filter(|(_, ty)| matches!(ty, ResolvedType::Nullable(_)))
                        .map(|(name, _)| name.clone())
                        .collect::<Vec<_>>(),
                ))
            }
            _ => None,
        })
}

fn checked_text_schema_fields<'a>(
    ty: &'a ResolvedType,
    schema: Option<&str>,
) -> Option<&'a [(String, ResolvedType)]> {
    match ty {
        ResolvedType::Object(fields) => Some(fields),
        ResolvedType::StdNominal { fields, .. }
            if schema.is_some_and(|name| {
                matches!(
                    name,
                    "TextRequest"
                        | "TextMessage"
                        | "WorkflowInput"
                        | "WorkflowDefinition"
                        | "ImageRequest"
                ) && checked_standard_nominal_name(ty) == Some(name)
            }) =>
        {
            Some(fields)
        }
        _ => None,
    }
}

fn stored_result_model(ty: &ResolvedType, resolve: &ResolveTables) -> Option<SymbolId> {
    let ResolvedType::Record {
        symbol,
        stored: true,
    } = ty
    else {
        return None;
    };
    let declaration = resolve.symbols.get(symbol.0 as usize)?;
    (declaration.id == *symbol && matches!(declaration.kind, SymbolKind::Model { .. }))
        .then_some(*symbol)
}

fn checked_stored_contract_type_id(
    ty: &ResolvedType,
    alias: Option<SymbolId>,
    resolve: &ResolveTables,
    depth: usize,
) -> Option<String> {
    if depth > 64 {
        return None;
    }
    match ty {
        ResolvedType::Nullable(inner) => Some(format!(
            "{}?",
            checked_stored_contract_type_id(inner, alias, resolve, depth + 1)?
        )),
        ResolvedType::Array { element, .. } => Some(format!(
            "{}[]",
            checked_stored_contract_type_id(element, alias, resolve, depth + 1)?
        )),
        _ if alias.is_some() => Some(resolve.symbols.get(alias?.0 as usize)?.canonical.clone()),
        ResolvedType::Scalar(scalar) => Some(scalar.as_str().into()),
        ResolvedType::Record { symbol, .. } => {
            Some(resolve.symbols.get(symbol.0 as usize)?.canonical.clone())
        }
        ResolvedType::Enum {
            owner: Some(owner), ..
        } => Some(resolve.symbols.get(owner.0 as usize)?.canonical.clone()),
        ResolvedType::Enum { owner: None, cases } => Some(format!("enum({})", cases.join(","))),
        _ => None,
    }
}

fn exact_type_id(ty: &ResolvedType, resolve: &ResolveTables) -> Option<String> {
    if !result_type(ty) && *ty != ResolvedType::Scalar(Scalar::Timezone) {
        return None;
    }
    let mut ty = ty;
    let mut suffix = String::new();
    for _ in 0..64 {
        if let ResolvedType::Nullable(inner) = ty {
            ty = inner;
            suffix.push('?');
        } else {
            break;
        }
    }
    if let ResolvedType::Array { element, .. } = ty {
        ty = element;
        suffix.insert_str(0, "[]");
    }
    let base = match ty {
        ResolvedType::Scalar(scalar) => Some(scalar.as_str().to_string()),
        ResolvedType::Enum {
            owner: Some(owner), ..
        } => Some(resolve.symbols.get(owner.0 as usize)?.canonical.clone()),
        ResolvedType::Enum { owner: None, cases } if !cases.is_empty() => {
            Some(format!("enum({})", cases.join(",")))
        }
        _ => None,
    }?;
    Some(format!("{base}{suffix}"))
}

fn expression(kind: SyntaxKind) -> bool {
    matches!(
        kind,
        SyntaxKind::Literal
            | SyntaxKind::NameRef
            | SyntaxKind::Group
            | SyntaxKind::Array
            | SyntaxKind::Object
            | SyntaxKind::Construct
            | SyntaxKind::Member
            | SyntaxKind::Call
            | SyntaxKind::Unary
            | SyntaxKind::Binary
            | SyntaxKind::Query
            | SyntaxKind::Path
            | SyntaxKind::MessageValue
    )
}

